                </div>
            `;

            // 添加特定设备类型的详细信息
            if (device.type.includes('摄像头')) {
                detailsHtml += `
                    <div class="info-item">
                        <div class="info-label">分辨率:</div>
                        <div class="info-value">${device.resolution}</div>
                    </div>
                    <div class="info-item">
                        <div class="info-label">帧率:</div>
                        <div class="info-value">${device.framerate}</div>
                    </div>
                `;
            }

            if (device.type.includes('雷视')) {
                detailsHtml += `
                    <div class="info-item">
                        <div class="info-label">检测范围:</div>
                        <div class="info-value">${device.detectionRange}</div>
                    </div>
                    <div class="info-item">
                        <div class="info-label">目标数量:</div>
                        <div class="info-value">${device.targetCount}</div>
                    </div>
                `;
            }

            if (device.type.includes('边缘计算')) {
                detailsHtml += `
                    <div class="info-item">
                        <div class="info-label">处理器:</div>
                        <div class="info-value">${device.chip}</div>
                    </div>
                    <div class="info-item">
                        <div class="info-label">内存:</div>
                        <div class="info-value">${device.memory}</div>
                    </div>
                    <div class="info-item">
                        <div class="info-label">存储:</div>
                        <div class="info-value">${device.storage}</div>
                    </div>
                `;
            }

            if (device.type.includes('网关')) {
                detailsHtml += `
                    <div class="info-item">
                        <div class="info-label">连接设备:</div>
                        <div class="info-value">${device.connectedDevices}个</div>
                    </div>
                `;
            }

            contentElement.innerHTML = detailsHtml;
            infoPanel.style.display = 'block';
        }

        // 切换交通信号灯状态
        function toggleTrafficLights() {
            const lights = document.querySelectorAll('.traffic-light');
            lights.forEach((light, index) => {
                const redLight = light.querySelector('.red');
                const yellowLight = light.querySelector('.yellow');
                const greenLight = light.querySelector('.green');

                // 北向和南向红绿灯同步
                if (index === 0 || index === 1) {
                    // 北向和南向：红->绿->黄->红
                    if (redLight.classList.contains('active')) {
                        redLight.classList.remove('active');
                        greenLight.classList.add('active');
                    } else if (greenLight.classList.contains('active')) {
                        greenLight.classList.remove('active');
                        yellowLight.classList.add('active');
                    } else {
                        yellowLight.classList.remove('active');
                        redLight.classList.add('active');
                    }
                } else {
                    // 东向和西向：绿->黄->红->绿
                    if (greenLight.classList.contains('active')) {
                        greenLight.classList.remove('active');
                        yellowLight.classList.add('active');
                    } else if (yellowLight.classList.contains('active')) {
                        yellowLight.classList.remove('active');
                        redLight.classList.add('active');
                    } else {
                        redLight.classList.remove('active');
                        greenLight.classList.add('active');
                    }
                }
            });
        }

        // 初始化
        document.addEventListener('DOMContentLoaded', function() {
            // 初始化设备状态
            updateDeviceStatus();

            // 交通信号灯定时切换
            setInterval(toggleTrafficLights, 5000);

            // 设备标记点击事件
            document.querySelectorAll('.device-marker').forEach(marker => {
                marker.addEventListener('click', function() {
                    const deviceId = this.getAttribute('data-device');
                    const device = devices.find(d => d.id === deviceId);
                    if (device) {
                        showDeviceInfo(device);
                    }
                });
            });

            // 关闭设备信息面板
            document.getElementById('close-device-info').addEventListener('click', function() {
                document.getElementById('device-info-panel').style.display = 'none';
            });

            // 切换视图按钮
            let showSatellite = false;
            document.getElementById('toggle-satellite').addEventListener('click', function() {
                showSatellite = !showSatellite;
                if (showSatellite) {
                    map.removeLayer(map._layers[Object.keys(map._layers)[1]]);
                    satelliteLayer.addTo(map);
                    this.innerHTML = '<i class="fas fa-layer-group"></i> 地图视图';
                } else {
                    map.removeLayer(satelliteLayer);
                    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
                        attribution: '© OpenStreetMap contributors'
                    }).addTo(map);
                    this.innerHTML = '<i class="fas fa-layer-group"></i> 卫星视图';
                }
            });

            // 刷新状态按钮
            document.getElementById('refresh-status').addEventListener('click', function() {
                // 模拟随机更新设备状态
                devices.forEach(device => {
                    if (Math.random() < 0.1) { // 10%概率改变状态
                        const statuses = ['online', 'warning', 'offline'];
                        device.status = statuses[Math.floor(Math.random() * statuses.length)];

                        // 更新心跳时间
                        const now = new Date();
                        device.lastHeartbeat = now.getFullYear() + '-' + 
                                             String(now.getMonth() + 1).padStart(2, '0') + '-' + 
                                             String(now.getDate()).padStart(2, '0') + ' ' + 
                                             String(now.getHours()).padStart(2, '0') + ':' + 
                                             String(now.getMinutes()).padStart(2, '0') + ':' + 
                                             String(now.getSeconds()).padStart(2, '0');
                    }
                });

                updateDeviceStatus();

                // 添加视觉反馈
                this.innerHTML = '<i class="fas fa-check"></i> 已刷新';
                setTimeout(() => {
                    this.innerHTML = '<i class="fas fa-sync-alt"></i> 刷新状态';
                }, 1000);
            });

            // 地图工具按钮事件
            document.getElementById('zoom-in').addEventListener('click', () => map.zoomIn());
            document.getElementById('zoom-out').addEventListener('click', () => map.zoomOut());
            document.getElementById('reset-view').addEventListener('click', () => map.setView([31.2304, 121.4737], 16));
            document.getElementById('measure-tool').addEventListener('click', () => alert('测距工具已激活'));
            document.getElementById('mark-tool').addEventListener('click', () => alert('标注工具已激活'));

            // 显示所有设备按钮
            document.getElementById('show-all-devices').addEventListener('click', () => {
                alert('已显示所有设备');
            });

            // 图层控制
            document.querySelectorAll('input[type="checkbox"]').forEach(checkbox => {
                checkbox.addEventListener('change', function() {
                    const layerId = this.id;
                    const elements = document.querySelectorAll(`[data-layer="${layerId}"]`);

                    if (layerId === 'layer-devices') {
                        const deviceMarkers = document.querySelectorAll('.device-marker');
                        deviceMarkers.forEach(marker => {
                            marker.style.display = this.checked ? 'flex' : 'none';
                        });
                    } else if (layerId === 'layer-traffic') {
                        const trafficLights = document.querySelectorAll('.traffic-light');
                        trafficLights.forEach(light => {
                            light.style.display = this.checked ? 'flex' : 'none';
                        });
                    }
                });
            });

            // 设备筛选
            document.querySelectorAll('input[id^="filter-"]').forEach(checkbox => {
                checkbox.addEventListener('change', function() {
                    const filterType = this.id.replace('filter-', '');
                    const deviceMarkers = document.querySelectorAll('.device-marker');

                    deviceMarkers.forEach(marker => {
                        if (marker.classList.contains(`marker-${filterType}`)) {
                            marker.style.display = this.checked ? 'flex' : 'none';
                        }
                    });
                });
            });

            // 自动刷新设备状态
            setInterval(() => {
                // 随机更新一个设备的状态
                if (Math.random() < 0.3) { // 30%概率更新
                    const randomIndex = Math.floor(Math.random() * devices.length);
                    const device = devices[randomIndex];

                    if (Math.random() < 0.2) { // 20%概率改变状态
                        const statuses = ['online', 'warning', 'offline'];
                        const currentStatusIndex = statuses.indexOf(device.status);
                        const newStatusIndex = (currentStatusIndex + 1) % statuses.length;
                        device.status = statuses[newStatusIndex];

                        // 更新心跳时间
                        const now = new Date();
                        device.lastHeartbeat = now.getFullYear() + '-' + 
                                             String(now.getMonth() + 1).padStart(2, '0') + '-' + 
                                             String(now.getDate()).padStart(2, '0') + ' ' + 
                                             String(now.getHours()).padStart(2, '0') + ':' + 
                                             String(now.getMinutes()).padStart(2, '0') + ':' + 
                                             String(now.getSeconds()).padStart(2, '0');

                        updateDeviceStatus();
                    }
                }
            }, 10000); // 每10秒检查一次
        });
    </script>
</body>
