                confidence: 0.81,
                algorithm: "YOLOv8-ObjectDetect",
                algorithmVersion: "v2.4.0",
                detectTime: "2025-03-15 10:34:55",
                verifiedBy: "",
                verifyTime: "",
                remarks: "自动检测结果，待验证",
                geometryType: "POLYGON",
                center: "X: 128.45, Y: 40.23",
                bbox: "minX: 127.8, minY: 39.7, maxX: 129.1, maxY: 40.8"
            }
        ];

        // 初始化函数
        function initElementsTable() {
            const tableBody = document.getElementById('elements-table-body');
            tableBody.innerHTML = '';

            elements.forEach(element => {
                const row = document.createElement('tr');

                // 根据置信度确定颜色类
                let confidenceClass = 'confidence-medium';
                let confidencePercent = Math.round(element.confidence * 100);
                let confidenceWidth = element.confidence * 100;

                if (element.confidence >= 0.9) {
                    confidenceClass = 'confidence-high';
                } else if (element.confidence < 0.7) {
                    confidenceClass = 'confidence-low';
                }

                // 根据状态确定状态类
                let statusClass = 'status-auto';
                if (element.status === 'verified') {
                    statusClass = 'status-verified';
                } else if (element.status === 'corrected') {
                    statusClass = 'status-corrected';
                } else if (element.status === 'rejected') {
                    statusClass = 'status-rejected';
                }

                // 根据类型确定类型类
                let typeClass = 'type-lane';
                if (element.type === 'crosswalk') {
                    typeClass = 'type-crosswalk';
                } else if (element.type === 'traffic-light') {
                    typeClass = 'type-traffic-light';
                } else if (element.type === 'camera') {
                    typeClass = 'type-camera';
                } else if (element.type === 'stop-line') {
                    typeClass = 'type-stop-line';
                } else if (element.type === 'traffic-sign') {
                    typeClass = 'type-traffic-sign';
                } else if (element.type === 'guardrail') {
                    typeClass = 'type-guardrail';
                } else if (element.type === 'parking') {
                    typeClass = 'type-parking';
                }

                row.innerHTML = `
                    <td>${element.id}</td>
                    <td>${element.name}</td>
                    <td><span class="element-type-badge ${typeClass}">${element.typeName}</span></td>
                    <td><span class="status-badge ${statusClass}">${element.statusName}</span></td>
                    <td>
                        <div class="confidence-bar">
                            <div class="confidence-fill ${confidenceClass}" style="width: ${confidenceWidth}%"></div>
                        </div>
                        ${confidencePercent}%
                    </td>
                    <td>${element.algorithmVersion}</td>
                    <td>${element.verifiedBy || '-'}</td>
                    <td>${element.verifyTime || '-'}</td>
                    <td>
                        <div class="action-buttons">
                            <button class="action-btn view-btn" data-id="${element.id}">
                                <i class="fas fa-eye"></i>
                            </button>
                            <button class="action-btn edit-btn" data-id="${element.id}">
                                <i class="fas fa-edit"></i>
                            </button>
                            ${element.status !== 'verified' ? `
                            <button class="action-btn verify-btn" data-id="${element.id}">
                                <i class="fas fa-check"></i>
                            </button>
                            ` : ''}
                            ${element.status !== 'rejected' ? `
                            <button class="action-btn reject-btn" data-id="${element.id}">
                                <i class="fas fa-times"></i>
                            </button>
                            ` : ''}
                        </div>
                    </td>
                `;

                tableBody.appendChild(row);
            });

            // 更新统计卡片
            updateStatistics();

            // 添加事件监听器
            addEventListeners();
        }

        // 更新统计信息
        function updateStatistics() {
            const totalElements = elements.length;
            const verifiedElements = elements.filter(e => e.status === 'verified').length;
            const autoElements = elements.filter(e => e.status === 'auto').length;
            const correctedElements = elements.filter(e => e.status === 'corrected').length;

            document.getElementById('total-elements').textContent = totalElements;
            document.getElementById('verified-elements').textContent = verifiedElements;
            document.getElementById('auto-elements').textContent = autoElements;
            document.getElementById('corrected-elements').textContent = correctedElements;
        }

        // 显示要素详情
        function showElementDetail(elementId) {
            const element = elements.find(e => e.id === elementId);
            if (!element) return;

            // 填充详情信息
            document.getElementById('detail-id').textContent = element.id;
            document.getElementById('detail-name').textContent = element.name;
            document.getElementById('detail-type').textContent = element.typeName;
            document.getElementById('detail-intersection').textContent = '路口A - 长安街与建国路交叉口';

            // 更新状态徽章
            const statusBadge = document.getElementById('detail-status');
            statusBadge.textContent = element.statusName;
            statusBadge.className = 'status-badge ';

            if (element.status === 'auto') {
                statusBadge.classList.add('status-auto');
            } else if (element.status === 'verified') {
                statusBadge.classList.add('status-verified');
            } else if (element.status === 'corrected') {
                statusBadge.classList.add('status-corrected');
            } else if (element.status === 'rejected') {
                statusBadge.classList.add('status-rejected');
            }

            // 更新类型徽章
            const typeBadge = document.getElementById('detail-type');
            typeBadge.textContent = element.typeName;
            typeBadge.className = 'element-type-badge ';

            if (element.type === 'lane') {
                typeBadge.classList.add('type-lane');
            } else if (element.type === 'crosswalk') {
                typeBadge.classList.add('type-crosswalk');
            } else if (element.type === 'traffic-light') {
                typeBadge.classList.add('type-traffic-light');
            } else if (element.type === 'camera') {
                typeBadge.classList.add('type-camera');
            } else if (element.type === 'stop-line') {
                typeBadge.classList.add('type-stop-line');
            } else if (element.type === 'traffic-sign') {
                typeBadge.classList.add('type-traffic-sign');
            } else if (element.type === 'guardrail') {
                typeBadge.classList.add('type-guardrail');
            } else if (element.type === 'parking') {
                typeBadge.classList.add('type-parking');
            }

            // 更新置信度
            const confidencePercent = Math.round(element.confidence * 100);
            document.getElementById('detail-confidence').textContent = confidencePercent + '%';

            const confidenceFill = document.querySelector('#element-detail-panel .confidence-fill');
            confidenceFill.style.width = confidencePercent + '%';

            if (element.confidence >= 0.9) {
                confidenceFill.className = 'confidence-fill confidence-high';
            } else if (element.confidence < 0.7) {
                confidenceFill.className = 'confidence-fill confidence-low';
            } else {
                confidenceFill.className = 'confidence-fill confidence-medium';
            }

            // 更新其他信息
            document.getElementById('detail-algorithm').textContent = element.algorithm;
            document.getElementById('detail-algorithm-version').textContent = element.algorithmVersion;
            document.getElementById('detail-detect-time').textContent = element.detectTime;
            document.getElementById('detail-auto').textContent = element.status === 'auto' ? '是' : '否';

            // 验证信息
            document.getElementById('detail-verify-status').textContent = element.statusName;
            document.getElementById('detail-verify-by').textContent = element.verifiedBy || '-';
            document.getElementById('detail-verify-time').textContent = element.verifyTime || '-';
            document.getElementById('detail-remarks').textContent = element.remarks;

            // 几何信息
            document.getElementById('detail-geometry-type').textContent = element.geometryType;
            document.getElementById('detail-center').textContent = element.center;
            document.getElementById('detail-bbox').textContent = element.bbox;

            // 更新几何查看器
            const geometryViewer = document.getElementById('geometry-viewer');
            let geometryIcon = 'fa-project-diagram';
            let geometryText = '';

            if (element.geometryType === 'POINT') {
                geometryIcon = 'fa-map-marker-alt';
                geometryText = `点坐标: ${element.center}`;
            } else if (element.geometryType === 'LINESTRING') {
                geometryIcon = 'fa-road';
                geometryText = `线要素，长度: 约${Math.round(Math.random() * 50) + 20}米`;
            } else if (element.geometryType === 'POLYGON') {
                geometryIcon = 'fa-draw-polygon';
                geometryText = `面要素，面积: 约${Math.round(Math.random() * 100) + 50}平方米`;
            }

            geometryViewer.innerHTML = `
                <div style="text-align: center;">
                    <i class="fas ${geometryIcon}" style="font-size: 48px; margin-bottom: 15px; color: #1890ff;"></i>
                    <div>${element.typeName}几何数据</div>
                    <div style="font-size: 0.9rem; margin-top: 10px;">${geometryText}</div>
                    <div style="font-size: 0.8rem; margin-top: 5px; color: #8c8c8c;">${element.geometryType}: ${element.center}</div>
                </div>
            `;

            // 显示详情面板
            document.getElementById('element-detail-panel').style.display = 'block';

            // 滚动到详情面板
            document.getElementById('element-detail-panel').scrollIntoView({ behavior: 'smooth' });
        }

        // 验证要素
        function verifyElement(elementId) {
            const element = elements.find(e => e.id === elementId);
            if (!element) return;

            // 更新要素状态
            element.status = 'verified';
            element.statusName = '人工验证';
            element.verifiedBy = '当前用户';

            const now = new Date();
            element.verifyTime = now.getFullYear() + '-' + 
                               String(now.getMonth() + 1).padStart(2, '0') + '-' + 
                               String(now.getDate()).padStart(2, '0') + ' ' + 
                               String(now.getHours()).padStart(2, '0') + ':' + 
                               String(now.getMinutes()).padStart(2, '0') + ':' + 
                               String(now.getSeconds()).padStart(2, '0');

            element.remarks = '人工验证通过，标注准确';

            // 重新初始化表格
            initElementsTable();

            // 更新详情面板
            showElementDetail(elementId);

            // 显示成功消息
            alert(`要素 ${elementId} 已通过验证`);
        }

        // 修正要素
        function correctElement(elementId) {
            const element = elements.find(e => e.id === elementId);
            if (!element) return;

            // 更新要素状态
            element.status = 'corrected';
            element.statusName = '人工修正';
            element.verifiedBy = '当前用户';

            const now = new Date();
            element.verifyTime = now.getFullYear() + '-' + 
                               String(now.getMonth() + 1).padStart(2, '0') + '-' + 
                               String(now.getDate()).padStart(2, '0') + ' ' + 
                               String(now.getHours()).padStart(2, '0') + ':' + 
                               String(now.getMinutes()).padStart(2, '0') + ':' + 
                               String(now.getSeconds()).padStart(2, '0');

            element.remarks = '人工修正边界和位置';

            // 重新初始化表格
            initElementsTable();

            // 更新详情面板
            showElementDetail(elementId);

            // 显示成功消息
            alert(`要素 ${elementId} 已修正`);
        }

        // 拒绝要素
        function rejectElement(elementId) {
            const element = elements.find(e => e.id === elementId);
            if (!element) return;

            // 更新要素状态
            element.status = 'rejected';
            element.statusName = '已拒绝';
            element.verifiedBy = '当前用户';

            const now = new Date();
            element.verifyTime = now.getFullYear() + '-' + 
                               String(now.getMonth() + 1).padStart(2, '0') + '-' + 
                               String(now.getDate()).padStart(2, '0') + ' ' + 
                               String(now.getHours()).padStart(2, '0') + ':' + 
                               String(now.getMinutes()).padStart(2, '0') + ':' + 
                               String(now.getSeconds()).padStart(2, '0');

            element.remarks = '检测错误，拒绝该标注';

            // 重新初始化表格
            initElementsTable();

            // 更新详情面板
            showElementDetail(elementId);

            // 显示成功消息
            alert(`要素 ${elementId} 已拒绝`);
        }

        // 添加事件监听器
        function addEventListeners() {
            // 查看按钮
            document.querySelectorAll('.view-btn').forEach(btn => {
                btn.addEventListener('click', function() {
                    const elementId = this.getAttribute('data-id');
                    showElementDetail(elementId);
                });
            });

            // 编辑按钮
            document.querySelectorAll('.edit-btn').forEach(btn => {
                btn.addEventListener('click', function() {
                    const elementId = this.getAttribute('data-id');
                    alert(`编辑要素 ${elementId} (功能演示)`);
                });
            });

            // 验证按钮
            document.querySelectorAll('.verify-btn').forEach(btn => {
                btn.addEventListener('click', function() {
                    const elementId = this.getAttribute('data-id');
                    if (confirm(`确认验证要素 ${elementId} 吗？`)) {
                        verifyElement(elementId);
                    }
                });
            });

            // 拒绝按钮
            document.querySelectorAll('.reject-btn').forEach(btn => {
                btn.addEventListener('click', function() {
                    const elementId = this.getAttribute('data-id');
                    if (confirm(`确认拒绝要素 ${elementId} 吗？`)) {
                        rejectElement(elementId);
                    }
                });
            });

            // 关闭详情面板
            document.getElementById('close-detail').addEventListener('click', function() {
                document.getElementById('element-detail-panel').style.display = 'none';
            });

            // 详情面板中的验证按钮
            document.getElementById('verify-element').addEventListener('click', function() {
                const elementId = document.getElementById('detail-id').textContent;
                if (confirm(`确认验证要素 ${elementId} 吗？`)) {
                    verifyElement(elementId);
                }
            });

            // 详情面板中的修正按钮
            document.getElementById('correct-element').addEventListener('click', function() {
                const elementId = document.getElementById('detail-id').textContent;
                if (confirm(`确认修正要素 ${elementId} 吗？`)) {
                    correctElement(elementId);
                }
            });

            // 详情面板中的拒绝按钮
            document.getElementById('reject-element').addEventListener('click', function() {
                const elementId = document.getElementById('detail-id').textContent;
                if (confirm(`确认拒绝要素 ${elementId} 吗？`)) {
                    rejectElement(elementId);
                }
            });

            // 标签切换
            document.querySelectorAll('.tab').forEach(tab => {
                tab.addEventListener('click', function() {
                    // 移除所有active类
                    document.querySelectorAll('.tab').forEach(t => {
                        t.classList.remove('active');
                    });

                    // 添加当前active类
                    this.classList.add('active');

                    const tabType = this.getAttribute('data-tab');

                    // 这里可以添加根据标签筛选表格的逻辑
                    console.log(`切换到标签: ${tabType}`);
                });
            });

            // 运行自动检测
            document.getElementById('run-detection').addEventListener('click', function() {
                // 模拟运行自动检测
                this.innerHTML = '<i class="fas fa-spinner fa-spin"></i> 检测中...';
                this.disabled = true;

                setTimeout(() => {
                    // 添加新的检测结果
                    const newElement = {
                        id: `ELE-${elements.length + 1}`,
                        name: `新检测要素-${elements.length + 1}`,
                        type: ['lane', 'crosswalk', 'traffic-light', 'camera'][Math.floor(Math.random() * 4)],
                        typeName: ['车道', '人行横道', '信号灯', '摄像头'][Math.floor(Math.random() * 4)],
                        status: 'auto',
                        statusName: '自动检测',
                        confidence: Math.random() * 0.3 + 0.6, // 0.6-0.9
                        algorithm: "YOLOv8-ObjectDetect",
                        algorithmVersion: "v2.4.0",
                        detectTime: new Date().toISOString().replace('T', ' ').substring(0, 19),
                        verifiedBy: "",
                        verifyTime: "",
                        remarks: "新自动检测结果",
                        geometryType: ["POINT", "LINESTRING", "POLYGON"][Math.floor(Math.random() * 3)],
                        center: `X: ${Math.round(Math.random() * 200)}, Y: ${Math.round(Math.random() * 100)}`,
                        bbox: `minX: ${Math.round(Math.random() * 200)}, minY: ${Math.round(Math.random() * 100)}, maxX: ${Math.round(Math.random() * 200 + 10)}, maxY: ${Math.round(Math.random() * 100 + 10)}`
                    };

                    // 设置具体类型名
                    if (newElement.type === 'lane') newElement.typeName = '车道';
                    else if (newElement.type === 'crosswalk') newElement.typeName = '人行横道';
                    else if (newElement.type === 'traffic-light') newElement.typeName = '信号灯';
                    else if (newElement.type === 'camera') newElement.typeName = '摄像头';

                    elements.unshift(newElement); // 添加到开头

                    // 重新初始化表格
                    initElementsTable();

                    // 恢复按钮状态
                    this.innerHTML = '<i class="fas fa-robot"></i> 运行自动检测';
                    this.disabled = false;

                    // 显示成功消息
                    alert(`自动检测完成，发现 ${1} 个新要素`);
                }, 2000);
            });

            // 导出数据
            document.getElementById('export-data').addEventListener('click', function() {
                alert('导出功能演示，实际会下载CSV文件');
            });

            // 搜索功能
            document.querySelector('.search-btn').addEventListener('click', function() {
                const searchInput = document.querySelector('.search-input');
                const searchTerm = searchInput.value.toLowerCase();

                if (searchTerm) {
                    // 这里可以添加搜索逻辑
                    alert(`搜索: ${searchTerm}`);
                }
            });

            // 筛选功能
            document.querySelectorAll('input[type="checkbox"]').forEach(checkbox => {
                checkbox.addEventListener('change', function() {
                    // 这里可以添加筛选逻辑
                    console.log(`筛选器 ${this.id} 状态: ${this.checked}`);
                });
            });

            // 导航菜单点击事件
            document.querySelectorAll('.nav-item, .nav-subitem').forEach(item => {
                item.addEventListener('click', function() {
                    // 移除所有active类
                    document.querySelectorAll('.nav-item.active, .nav-subitem.active').forEach(el => {
                        el.classList.remove('active');
                    });

                    // 为当前项添加active类
                    this.classList.add('active');

                    // 如果点击的是主菜单项，激活其第一个子项
                    if (this.classList.contains('nav-item')) {
                        const nextSibling = this.nextElementSibling;
                        if (nextSibling && nextSibling.classList.contains('nav-subitem')) {
                            nextSibling.classList.add('active');
                        }
                    }
                });
            });
        }

        // 页面加载完成后初始化
        document.addEventListener('DOMContentLoaded', function() {
            initElementsTable();
        });
    </script>
</body>
</html>
```

## 设备要素页面功能说明

这个页面实现了设备要素管理功能，主要包括：

### 1. 数据统计卡片
- 要素总数
- 已验证要素数量
- 自动检测要素数量
- 人工修正要素数量

### 2. 要素分类标签
- 全部要素
- 车道
- 人行横道
- 信号灯
- 摄像头
- 待验证要素

### 3. 要素数据表格
- 要素ID和名称
- 要素类型（车道、人行横道、信号灯等）
- 标注状态（自动检测、人工验证、人工修正、已拒绝）
- 置信度（可视化进度条）
- 检测算法版本
- 验证人和验证时间
- 操作按钮（查看、编辑、验证、拒绝）

### 4. 要素详细信息面板
- 基本信息（ID、名称、类型、所属路口）
- 检测信息（算法、版本、检测时间）
- 验证信息（状态、验证人、验证时间、备注）
- 几何信息（类型、中心点坐标、边界框）
- 几何数据可视化预览
- 操作按钮（通过验证、修正要素、拒绝要素）

### 5. 交互功能
- 点击查看按钮显示要素详细信息
- 验证/修正/拒绝要素操作
- 运行自动检测模拟
- 要素数据导出
- 搜索和筛选功能

### 6. 视觉设计
- 不同要素类型使用不同颜色标识
- 置信度使用颜色编码进度条
- 状态使用徽章样式区分
- 响应式设计适配不同屏幕

这个页面提供了完整的设备要素管理功能，包括自动标注结果的验证、修正和管理，符合交通路口数字孪生可视化的实际需求。

