            },
            {
                id: 3,
                deviceId: "RV-001-2025",
                deviceName: "雷视一体机-01",
                deviceType: "鸿蒙雷视一体机",
                platformType: "HARMONYOS",
                manufacturer: "佳都科技",
                discoveryTime: "2025-03-15 14:40:12",
                registerStatus: "REGISTERING",
                onlineStatus: true,
                ipAddress: "192.168.1.103",
                macAddress: "00:1A:2B:3C:4D:60",
                protocolType: "星闪协议"
            },
            {
                id: 4,
                deviceId: "EC-001-2025",
                deviceName: "边缘计算盒子-01",
                deviceType: "OpenHarmony边缘计算盒子",
                platformType: "OPENHARMONY",
                manufacturer: "深开鸿",
                discoveryTime: "2025-03-15 14:45:33",
                registerStatus: "REGISTERED",
                onlineStatus: true,
                ipAddress: "192.168.1.104",
                macAddress: "00:1A:2B:3C:4D:61",
                protocolType: "鸿蒙软总线"
            },
            {
                id: 5,
                deviceId: "SLC-002-2018",
                deviceName: "信号灯控制器-02",
                deviceType: "老旧信号控制器",
                platformType: "LEGACY",
                manufacturer: "传统设备",
                discoveryTime: "2025-03-15 14:50:18",
                registerStatus: "DISCOVERED",
                onlineStatus: false,
                ipAddress: "192.168.1.105",
                macAddress: "00:1A:2B:3C:4D:62",
                protocolType: "Modbus"
            },
            {
                id: 6,
                deviceId: "SENSOR-001-2024",
                deviceName: "环境监测传感器-01",
                deviceType: "标准传感器",
                platformType: "NON_HARMONY",
                manufacturer: "标准厂商",
                discoveryTime: "2025-03-15 14:55:07",
                registerStatus: "AUTH_FAILED",
                onlineStatus: true,
                ipAddress: "192.168.1.106",
                macAddress: "00:1A:2B:3C:4D:63",
                protocolType: "MQTT"
            },
            {
                id: 7,
                deviceId: "CAM-005-2025",
                deviceName: "智能摄像机-05",
                deviceType: "鸿蒙摄像头",
                platformType: "HARMONYOS",
                manufacturer: "大华股份",
                discoveryTime: "2025-03-15 15:00:22",
                registerStatus: "DISCOVERED",
                onlineStatus: true,
                ipAddress: "192.168.1.107",
                macAddress: "00:1A:2B:3C:4D:64",
                protocolType: "RTSP"
            },
            {
                id: 8,
                deviceId: "RSU-001-2025",
                deviceName: "路侧单元-01",
                deviceType: "鸿蒙路侧单元",
                platformType: "HARMONYOS",
                manufacturer: "华为",
                discoveryTime: "2025-03-15 15:05:41",
                registerStatus: "REGISTERED",
                onlineStatus: true,
                ipAddress: "192.168.1.108",
                macAddress: "00:1A:2B:3C:4D:65",
                protocolType: "星闪协议"
            }
        ];

        // 状态映射
        const statusMap = {
            "DISCOVERED": { text: "已发现", class: "status-discovered" },
            "REGISTERING": { text: "注册中", class: "status-registering" },
            "REGISTERED": { text: "已注册", class: "status-registered" },
            "AUTH_FAILED": { text: "认证失败", class: "status-auth-failed" },
            "OFFLINE": { text: "离线", class: "status-offline" },
            "MAINTENANCE": { text: "维护中", class: "status-maintenance" }
        };

        const platformMap = {
            "HARMONYOS": { text: "鸿蒙设备", class: "platform-harmony" },
            "OPENHARMONY": { text: "开源鸿蒙设备", class: "platform-openharmony" },
            "NON_HARMONY": { text: "非鸿蒙设备", class: "platform-non-harmony" },
            "LEGACY": { text: "老旧设备", class: "platform-legacy" }
        };

        // 初始化设备表格
        function renderDeviceTable() {
            const tableBody = document.getElementById('deviceTableBody');
            tableBody.innerHTML = '';

            deviceData.forEach(device => {
                const status = statusMap[device.registerStatus];
                const platform = platformMap[device.platformType];

                const row = document.createElement('tr');
                row.dataset.id = device.id;
                row.innerHTML = `
                    <td><input type="checkbox" class="device-checkbox" data-id="${device.id}"></td>
                    <td>${device.deviceName}</td>
                    <td>${device.deviceType}</td>
                    <td><span class="device-platform ${platform.class}">${platform.text}</span></td>
                    <td>${device.discoveryTime}</td>
                    <td>
                        <div style="display: flex; align-items: center; gap: 8px;">
                            <div class="device-status ${status.class}"></div>
                            <span>${status.text}</span>
                        </div>
                    </td>
                    <td>
                        <div class="device-actions">
                            <button class="action-btn register" data-id="${device.id}" title="注册设备">
                                <i class="fas fa-plus-circle"></i>
                            </button>
                            <button class="action-btn config" data-id="${device.id}" title="配置设备">
                                <i class="fas fa-cog"></i>
                            </button>
                            <button class="action-btn delete" data-id="${device.id}" title="删除设备">
                                <i class="fas fa-trash"></i>
                            </button>
                            <button class="action-btn view" data-id="${device.id}" title="查看详情">
                                <i class="fas fa-eye"></i>
                            </button>
                        </div>
                    </td>
                `;

                tableBody.appendChild(row);
            });

            updateDeviceCounts();
            attachTableEvents();
        }

        // 更新设备统计
        function updateDeviceCounts() {
            const harmonyCount = deviceData.filter(d => 
                d.platformType === "HARMONYOS" || d.platformType === "OPENHARMONY"
            ).length;

            const legacyCount = deviceData.filter(d => 
                d.platformType === "LEGACY" || d.platformType === "NON_HARMONY"
            ).length;

            const discoveredCount = deviceData.length;

            const protocolSet = new Set();
            deviceData.forEach(d => protocolSet.add(d.protocolType));

            document.getElementById('harmonyCount').textContent = harmonyCount;
            document.getElementById('legacyCount').textContent = legacyCount;
            document.getElementById('discoveredCount').textContent = discoveredCount;
            document.getElementById('protocolCount').textContent = protocolSet.size;
        }

        // 绑定表格事件
        function attachTableEvents() {
            // 全选/取消全选
            document.getElementById('selectAll').addEventListener('change', function(e) {
                const checkboxes = document.querySelectorAll('.device-checkbox');
                checkboxes.forEach(cb => cb.checked = e.target.checked);
            });

            // 设备复选框
            document.querySelectorAll('.device-checkbox').forEach(cb => {
                cb.addEventListener('change', function() {
                    const row = this.closest('tr');
                    if (this.checked) {
                        row.classList.add('selected');
                    } else {
                        row.classList.remove('selected');
                    }
                });
            });

            // 设备操作按钮
            document.querySelectorAll('.action-btn.register').forEach(btn => {
                btn.addEventListener('click', function() {
                    const deviceId = this.dataset.id;
                    openRegisterModal(deviceId);
                });
            });

            document.querySelectorAll('.action-btn.view').forEach(btn => {
                btn.addEventListener('click', function() {
                    const deviceId = this.dataset.id;
                    showDeviceDetail(deviceId);
                });
            });

            document.querySelectorAll('.action-btn.delete').forEach(btn => {
                btn.addEventListener('click', function() {
                    const deviceId = this.dataset.id;
                    if (confirm('确定要删除此设备吗？')) {
                        deleteDevice(deviceId);
                    }
                });
            });
        }

        // 显示设备详情
        function showDeviceDetail(deviceId) {
            const device = deviceData.find(d => d.id == deviceId);
            if (!device) return;

            const status = statusMap[device.registerStatus];
            const platform = platformMap[device.platformType];

            document.getElementById('detailDeviceName').textContent = device.deviceName;
            document.getElementById('detailDeviceId').textContent = device.deviceId;
            document.getElementById('detailDeviceType').textContent = device.deviceType;
            document.getElementById('detailPlatformType').textContent = platform.text;
            document.getElementById('detailManufacturer').textContent = device.manufacturer;
            document.getElementById('detailDeviceModel').textContent = "标准型号";
            document.getElementById('detailFirmwareVersion').textContent = "V2.3.1";
            document.getElementById('detailHardwareVersion').textContent = "V1.0";
            document.getElementById('detailProtocolType').textContent = device.protocolType;
            document.getElementById('detailIpAddress').textContent = device.ipAddress;
            document.getElementById('detailMacAddress').textContent = device.macAddress;
            document.getElementById('detailRegisterStatus').textContent = status.text;
            document.getElementById('detailOnlineStatus').textContent = device.onlineStatus ? "在线" : "离线";
            document.getElementById('detailDiscoveryTime').textContent = device.discoveryTime;
            document.getElementById('detailRegisterTime').textContent = device.registerStatus === "REGISTERED" ? "2025-03-15 15:00:00" : "-";
            document.getElementById('detailLastHeartbeat').textContent = device.onlineStatus ? "2025-03-15 15:10:22" : "-";

            document.getElementById('deviceDetailView').style.display = 'block';
        }

        // 打开注册模态框
        function openRegisterModal(deviceId) {
            const device = deviceData.find(d => d.id == deviceId);
            if (!device) return;

            document.getElementById('regDeviceName').value = device.deviceName;
            document.getElementById('registerModal').style.display = 'flex';
        }

        // 删除设备
        function deleteDevice(deviceId) {
            const index = deviceData.findIndex(d => d.id == deviceId);
            if (index !== -1) {
                deviceData.splice(index, 1);
                renderDeviceTable();
                alert('设备删除成功');
            }
        }

        // 设备发现控制
        let discoveryInterval;
        let isDiscovering = false;

        function startDiscovery() {
            if (isDiscovering) return;

            isDiscovering = true;
            document.getElementById('statusDot').className = 'status-dot scanning';
            document.getElementById('statusText').textContent = '正在发现设备...';
            document.getElementById('statusDetail').textContent = '正在扫描网络中的设备，请稍候...';

            // 模拟发现新设备
            discoveryInterval = setInterval(() => {
                if (Math.random() > 0.7) {
                    // 模拟发现新设备
                    const newDevice = {
                        id: deviceData.length + 1,
                        deviceId: `NEW-${Date.now()}`,
                        deviceName: `新设备-${deviceData.length + 1}`,
                        deviceType: Math.random() > 0.5 ? "鸿蒙摄像头" : "标准传感器",
                        platformType: Math.random() > 0.6 ? "HARMONYOS" : "NON_HARMONY",
                        manufacturer: Math.random() > 0.5 ? "海康威视" : "大华股份",
                        discoveryTime: new Date().toLocaleString('zh-CN'),
                        registerStatus: "DISCOVERED",
                        onlineStatus: true,
                        ipAddress: `192.168.1.${100 + deviceData.length}`,
                        macAddress: `00:1A:2B:3C:4D:${70 + deviceData.length}`,
                        protocolType: Math.random() > 0.5 ? "星闪协议" : "MQTT"
                    };

                    deviceData.unshift(newDevice);
                    renderDeviceTable();

                    // 更新状态显示
                    document.getElementById('statusDetail').textContent = 
                        `发现新设备: ${newDevice.deviceName} (${newDevice.ipAddress})`;
                }
            }, 3000);
        }

        function stopDiscovery() {
            if (!isDiscovering) return;

            isDiscovering = false;
            clearInterval(discoveryInterval);

            document.getElementById('statusDot').className = 'status-dot idle';
            document.getElementById('statusText').textContent = '发现服务已停止';
            document.getElementById('statusDetail').textContent = '设备发现服务已停止运行';
        }

        // 初始化页面
        document.addEventListener('DOMContentLoaded', function() {
            // 渲染设备表格
            renderDeviceTable();

            // 绑定按钮事件
            document.getElementById('startDiscoveryBtn').addEventListener('click', startDiscovery);
            document.getElementById('stopDiscoveryBtn').addEventListener('click', stopDiscovery);
            document.getElementById('applyFilterBtn').addEventListener('click', function() {
                alert('筛选条件已应用');
            });

            document.getElementById('batchRegisterBtn').addEventListener('click', function() {
                const selected = document.querySelectorAll('.device-checkbox:checked');
                if (selected.length === 0) {
                    alert('请先选择要注册的设备');
                    return;
                }
                alert(`将为 ${selected.length} 个设备执行批量注册`);
            });

            document.getElementById('batchDeleteBtn').addEventListener('click', function() {
                const selected = document.querySelectorAll('.device-checkbox:checked');
                if (selected.length === 0) {
                    alert('请先选择要删除的设备');
                    return;
                }
                if (confirm(`确定要删除 ${selected.length} 个设备吗？`)) {
                    alert(`${selected.length} 个设备已标记为删除`);
                }
            });

            // 模态框控制
            document.getElementById('closeDetailBtn').addEventListener('click', function() {
                document.getElementById('deviceDetailView').style.display = 'none';
            });

            document.getElementById('closeRegisterModal').addEventListener('click', function() {
                document.getElementById('registerModal').style.display = 'none';
            });

            document.getElementById('cancelRegisterBtn').addEventListener('click', function() {
                document.getElementById('registerModal').style.display = 'none';
            });

            document.getElementById('confirmRegisterBtn').addEventListener('click', function() {
                const deviceName = document.getElementById('regDeviceName').value;
                if (!deviceName.trim()) {
                    alert('请输入设备名称');
                    return;
                }

                alert(`设备 ${deviceName} 注册成功！`);
                document.getElementById('registerModal').style.display = 'none';

                // 重置表单
                document.getElementById('regDeviceName').value = '';
                document.getElementById('regIntersection').value = '';
                document.getElementById('regDeviceGroup').value = '';
                document.getElementById('regDescription').value = '';
                document.getElementById('regAuthInfo').value = '';
            });

            // 导航菜单点击事件
            document.querySelectorAll('.nav-item, .nav-subitem').forEach(item => {
                item.addEventListener('click', function() {
                    // 移除所有active类
                    document.querySelectorAll('.nav-item.active, .nav-subitem.active').forEach(el => {
                        el.classList.remove('active');
                    });

                    // 为当前项添加active类
                    this.classList.add('active');

                    // 如果点击的是主菜单项，激活其第一个子项
                    if (this.classList.contains('nav-item')) {
                        const nextSibling = this.nextElementSibling;
                        if (nextSibling && nextSibling.classList.contains('nav-subitem')) {
                            nextSibling.classList.add('active');
                        }
                    }
                });
            });

            // 分页按钮
            document.querySelectorAll('.page-btn').forEach(btn => {
                btn.addEventListener('click', function() {
                    if (this.id === 'prevPage' || this.id === 'nextPage') {
                        // 简单分页切换
                        const currentPage = document.querySelector('.page-btn.active');
                        const pages = document.querySelectorAll('.page-btn:not(#prevPage):not(#nextPage)');
                        let currentIndex = Array.from(pages).indexOf(currentPage);

                        if (this.id === 'prevPage' && currentIndex > 0) {
                            pages[currentIndex].classList.remove('active');
                            pages[currentIndex - 1].classList.add('active');
                        } else if (this.id === 'nextPage' && currentIndex < pages.length - 1) {
                            pages[currentIndex].classList.remove('active');
                            pages[currentIndex + 1].classList.add('active');
                        }
                    } else {
                        // 点击页码
                        document.querySelectorAll('.page-btn').forEach(b => b.classList.remove('active'));
                        this.classList.add('active');
                    }
                });
            });
        });
    </script>
