        // 分组类型映射
        const groupTypeMap = {
            1: { name: "按路口分组", color: "#1890ff" },
            2: { name: "按区域分组", color: "#52c41a" },
            3: { name: "按设备类型分组", color: "#fa8c16" },
            4: { name: "自定义分组", color: "#722ed1" },
            5: { name: "按厂商分组", color: "#eb2f96" }
        };

        // 当前选中的分组ID
        let selectedGroupId = null;

        // 渲染分组树
        function renderGroupTree() {
            const treeContainer = document.getElementById('groupTree');
            treeContainer.innerHTML = '';

            // 获取顶级分组
            const topLevelGroups = groupData.filter(group => group.parentId === null);

            // 渲染每个顶级分组及其子分组
            topLevelGroups.forEach(group => {
                const groupElement = createGroupTreeItem(group);
                treeContainer.appendChild(groupElement);

                // 渲染子分组
                const childGroups = groupData.filter(g => g.parentId === group.groupId);
                if (childGroups.length > 0) {
                    const childContainer = document.createElement('ul');
                    childContainer.style.display = 'block';

                    childGroups.forEach(childGroup => {
                        const childElement = createGroupTreeItem(childGroup);
                        childContainer.appendChild(childElement);
                    });

                    treeContainer.appendChild(childContainer);
                }
            });

            // 如果没有选中分组，默认选中第一个
            if (!selectedGroupId && topLevelGroups.length > 0) {
                selectGroup(topLevelGroups[0].groupId);
            }

            updateStatistics();
        }

        // 创建分组树项
        function createGroupTreeItem(group) {
            const li = document.createElement('li');
            li.className = 'tree-item';
            li.dataset.id = group.groupId;

            // 检查是否有子分组
            const hasChildren = groupData.some(g => g.parentId === group.groupId);

            li.innerHTML = `
                <div class="tree-item-content">
                    <div class="tree-item-icon">
                        <i class="${group.groupIcon}"></i>
                    </div>
                    <div class="tree-item-name">${group.groupName}</div>
                    <div class="tree-item-count">${group.deviceCount}</div>
                </div>
            `;

            // 添加点击事件
            li.addEventListener('click', function(e) {
                e.stopPropagation();
                selectGroup(group.groupId);
            });

            return li;
        }

        // 选择分组
        function selectGroup(groupId) {
            // 移除之前选中的样式
            document.querySelectorAll('.tree-item.selected').forEach(item => {
                item.classList.remove('selected');
            });

            // 添加选中样式
            const selectedItem = document.querySelector(`.tree-item[data-id="${groupId}"]`);
            if (selectedItem) {
                selectedItem.classList.add('selected');
            }

            selectedGroupId = groupId;
            updateGroupDetails(groupId);
            updateControlButtons();
        }

        // 更新分组详情
        function updateGroupDetails(groupId) {
            const group = groupData.find(g => g.groupId == groupId);
            if (!group) return;

            // 显示详情区域
            document.getElementById('noGroupSelected').style.display = 'none';
            document.getElementById('groupDetails').style.display = 'block';

            // 更新标题
            document.getElementById('selectedGroupTitle').textContent = group.groupName;

            // 更新分组信息
            document.getElementById('groupName').textContent = group.groupName;
            document.getElementById('groupType').textContent = groupTypeMap[group.groupType].name;
            document.getElementById('groupCode').textContent = group.groupCode;
            document.getElementById('deviceCount').textContent = group.deviceCount;
            document.getElementById('onlineDeviceCount').textContent = group.onlineDeviceCount;
            document.getElementById('createTime').textContent = group.createTime;
            document.getElementById('createdBy').textContent = group.createdBy;
            document.getElementById('groupStatus').textContent = group.status === 1 ? '启用' : '禁用';
            document.getElementById('groupStatus').className = `info-badge ${group.status === 1 ? 'badge-success' : 'badge-warning'}`;
            document.getElementById('groupDescription').textContent = group.description || '暂无描述';

            // 更新设备列表
            updateGroupDeviceList(groupId);
        }

        // 更新分组设备列表
        function updateGroupDeviceList(groupId) {
            const tableBody = document.getElementById('groupDeviceTableBody');
            tableBody.innerHTML = '';

            // 获取属于该分组的设备
            const groupDevices = deviceData.filter(device => 
                device.groupIds.includes(parseInt(groupId))
            );

            if (groupDevices.length === 0) {
                document.getElementById('groupDeviceTable').style.display = 'none';
                document.getElementById('noDevicesMessage').style.display = 'block';
            } else {
                document.getElementById('groupDeviceTable').style.display = 'table';
                document.getElementById('noDevicesMessage').style.display = 'none';

                groupDevices.forEach(device => {
                    const row = document.createElement('tr');

                    // 平台类型标签
                    const platformClass = device.platformType === 'HARMONYOS' || device.platformType === 'OPENHARMONY' 
                        ? 'platform-harmony' 
                        : 'platform-non-harmony';
                    const platformText = device.platformType === 'HARMONYOS' || device.platformType === 'OPENHARMONY' 
                        ? '鸿蒙设备' 
                        : '非鸿蒙设备';

                    // 状态指示器
                    const statusClass = `status-${device.status}`;
                    const statusText = device.status === 'online' ? '在线' : device.status === 'offline' ? '离线' : '警告';

                    row.innerHTML = `
                        <td>${device.deviceName}</td>
                        <td>${device.deviceType}</td>
                        <td><span class="device-platform ${platformClass}">${platformText}</span></td>
                        <td>
                            <div style="display: flex; align-items: center; gap: 8px;">
                                <div class="device-status ${statusClass}"></div>
                                <span>${statusText}</span>
                            </div>
                        </td>
                        <td>
                            <div class="device-actions">
                                <button class="action-btn remove" data-device-id="${device.id}" title="从分组移除">
                                    <i class="fas fa-unlink"></i>
                                </button>
                            </div>
                        </td>
                    `;

                    tableBody.appendChild(row);
                });

                // 绑定移除设备事件
                document.querySelectorAll('.action-btn.remove').forEach(btn => {
                    btn.addEventListener('click', function() {
                        const deviceId = this.dataset.deviceId;
                        removeDeviceFromGroup(deviceId, groupId);
                    });
                });
            }
        }

        // 从分组中移除设备
        function removeDeviceFromGroup(deviceId, groupId) {
            const device = deviceData.find(d => d.id == deviceId);
            if (!device) return;

            // 从设备的组ID列表中移除
            const index = device.groupIds.indexOf(parseInt(groupId));
            if (index !== -1) {
                device.groupIds.splice(index, 1);

                // 更新分组中的设备计数
                const group = groupData.find(g => g.groupId == groupId);
                if (group) {
                    group.deviceCount--;
                    // 简单假设设备状态，实际应根据设备状态更新在线计数
                    if (device.status === 'online') {
                        group.onlineDeviceCount--;
                    }
                }

                // 更新UI
                updateGroupDeviceList(groupId);
                updateGroupDetails(groupId);
                renderGroupTree();
                updateStatistics();

                alert(`设备 ${device.deviceName} 已从分组中移除`);
            }
        }

        // 更新控制按钮状态
        function updateControlButtons() {
            const hasSelection = selectedGroupId !== null;

            document.getElementById('editGroupBtn').disabled = !hasSelection;
            document.getElementById('deleteGroupBtn').disabled = !hasSelection;
            document.getElementById('manageDevicesBtn').disabled = !hasSelection;
        }

        // 更新统计数据
        function updateStatistics() {
            // 计算总数
            const totalGroups = groupData.length;
            const totalDevices = deviceData.length;

            // 计算在线设备数
            const onlineDevices = deviceData.filter(d => d.status === 'online').length;

            // 计算区域覆盖数（按区域分组数）
            const coveredAreas = groupData.filter(g => g.groupType === 2).length;

            document.getElementById('totalGroups').textContent = totalGroups;
            document.getElementById('totalDevices').textContent = totalDevices;
            document.getElementById('onlineDevices').textContent = onlineDevices;
            document.getElementById('coveredAreas').textContent = coveredAreas;
        }

        // 打开新建分组模态框
        function openGroupModal(isEdit = false) {
            const modal = document.getElementById('groupModal');
            const title = document.getElementById('modalTitle');
            const parentSelect = document.getElementById('modalParentGroup');

            if (isEdit && selectedGroupId) {
                // 编辑模式
                title.textContent = '编辑分组';
                const group = groupData.find(g => g.groupId == selectedGroupId);

                if (group) {
                    document.getElementById('modalGroupName').value = group.groupName;
                    document.getElementById('modalGroupType').value = group.groupType;
                    document.getElementById('modalGroupCode').value = group.groupCode;
                    document.getElementById('modalGroupIcon').value = group.groupIcon;
                    document.getElementById('modalGroupDescription').value = group.description || '';

                    // 设置父级分组
                    const parentOptions = parentSelect.querySelectorAll('option');
                    parentOptions.forEach(option => {
                        option.selected = option.value == group.parentId;
                    });

                    // 设置状态
                    const statusRadios = document.querySelectorAll('input[name="groupStatus"]');
                    statusRadios.forEach(radio => {
                        radio.checked = radio.value == group.status;
                    });

                    // 设置图标选择
                    document.querySelectorAll('.icon-option').forEach(icon => {
                        icon.classList.remove('selected');
                        if (icon.dataset.icon === group.groupIcon) {
                            icon.classList.add('selected');
                        }
                    });
                }
            } else {
                // 新建模式
                title.textContent = '新建分组';

                // 重置表单
                document.getElementById('modalGroupName').value = '';
                document.getElementById('modalGroupType').value = '1';
                document.getElementById('modalGroupCode').value = '';
                document.getElementById('modalGroupIcon').value = 'fas fa-layer-group';
                document.getElementById('modalGroupDescription').value = '';

                // 设置默认状态
                document.querySelector('input[name="groupStatus"][value="1"]').checked = true;

                // 设置默认图标
                document.querySelectorAll('.icon-option').forEach(icon => {
                    icon.classList.remove('selected');
                    if (icon.dataset.icon === 'fas fa-layer-group') {
                        icon.classList.add('selected');
                    }
                });

                // 生成分组编码
                document.getElementById('modalGroupCode').value = `GROUP-${Date.now().toString().slice(-6)}`;
            }

            // 更新父级分组选项
            updateParentGroupOptions();

            modal.style.display = 'flex';
        }

        // 更新父级分组选项
        function updateParentGroupOptions() {
            const parentSelect = document.getElementById('modalParentGroup');
            parentSelect.innerHTML = '<option value="">无（顶级分组）</option>';

            // 添加可选的父级分组（不能选择自己作为父级）
            groupData.forEach(group => {
                // 在编辑模式下，不能选择自己或自己的子分组作为父级
                if (selectedGroupId && group.groupId == selectedGroupId) return;

                // 构建缩进前缀
                let prefix = '';
                for (let i = 1; i < group.groupLevel; i++) {
                    prefix += '├─ ';
                }

                const option = document.createElement('option');
                option.value = group.groupId;
                option.textContent = prefix + group.groupName;
                parentSelect.appendChild(option);
            });
        }

        // 保存分组
        function saveGroup() {
            const groupName = document.getElementById('modalGroupName').value.trim();
            const groupType = document.getElementById('modalGroupType').value;
            const groupCode = document.getElementById('modalGroupCode').value.trim();
            const parentId = document.getElementById('modalParentGroup').value;
            const description = document.getElementById('modalGroupDescription').value;
            const groupIcon = document.getElementById('modalGroupIcon').value;
            const status = document.querySelector('input[name="groupStatus"]:checked').value;

            if (!groupName) {
                alert('请输入分组名称');
                return;
            }

            if (!groupCode) {
                alert('请输入分组编码');
                return;
            }

            // 检查分组编码是否重复
            const isEdit = document.getElementById('modalTitle').textContent === '编辑分组';
            const duplicateCode = groupData.some(g => 
                g.groupCode === groupCode && 
                (!isEdit || g.groupId != selectedGroupId)
            );

            if (duplicateCode) {
                alert('分组编码已存在，请使用其他编码');
                return;
            }

            if (isEdit && selectedGroupId) {
                // 更新现有分组
                const groupIndex = groupData.findIndex(g => g.groupId == selectedGroupId);
                if (groupIndex !== -1) {
                    groupData[groupIndex].groupName = groupName;
                    groupData[groupIndex].groupType = parseInt(groupType);
                    groupData[groupIndex].groupCode = groupCode;
                    groupData[groupIndex].parentId = parentId ? parseInt(parentId) : null;
                    groupData[groupIndex].description = description;
                    groupData[groupIndex].groupIcon = groupIcon;
                    groupData[groupIndex].status = parseInt(status);
                    groupData[groupIndex].groupTypeName = groupTypeMap[groupType].name;

                    // 更新分组路径和层级
                    if (parentId) {
                        const parentGroup = groupData.find(g => g.groupId == parentId);
                        groupData[groupIndex].groupPath = parentGroup.groupPath + '/' + selectedGroupId;
                        groupData[groupIndex].groupLevel = parentGroup.groupLevel + 1;
                    } else {
                        groupData[groupIndex].groupPath = '/' + selectedGroupId;
                        groupData[groupIndex].groupLevel = 1;
                    }
                }

                alert('分组更新成功');
            } else {
                // 创建新分组
                const newGroupId = Math.max(...groupData.map(g => g.groupId)) + 1;
                const groupLevel = parentId ? 
                    (groupData.find(g => g.groupId == parentId).groupLevel + 1) : 1;
                const groupPath = parentId ? 
                    (groupData.find(g => g.groupId == parentId).groupPath + '/' + newGroupId) : 
                    '/' + newGroupId;

                const newGroup = {
                    groupId: newGroupId,
                    groupName: groupName,
                    groupCode: groupCode,
                    groupType: parseInt(groupType),
                    groupTypeName: groupTypeMap[groupType].name,
                    parentId: parentId ? parseInt(parentId) : null,
                    groupPath: groupPath,
                    groupLevel: groupLevel,
                    deviceCount: 0,
                    onlineDeviceCount: 0,
                    description: description,
                    groupIcon: groupIcon,
                    status: parseInt(status),
                    isSystem: false,
                    createTime: new Date().toLocaleString('zh-CN'),
                    createdBy: '管理员'
                };

                groupData.push(newGroup);
                alert('分组创建成功');
            }

            // 关闭模态框
            document.getElementById('groupModal').style.display = 'none';

            // 刷新UI
            renderGroupTree();
            if (isEdit) {
                updateGroupDetails(selectedGroupId);
            } else {
                // 选中新创建的分组
                const newGroupId = Math.max(...groupData.map(g => g.groupId));
                selectGroup(newGroupId);
            }
        }

        // 删除分组
        function deleteGroup() {
            if (!selectedGroupId) return;

            const group = groupData.find(g => g.groupId == selectedGroupId);
            if (!group) return;

            // 检查是否是系统分组
            if (group.isSystem) {
                alert('系统预置分组不能删除');
                return;
            }

            // 检查是否有子分组
            const hasChildren = groupData.some(g => g.parentId == selectedGroupId);
            if (hasChildren) {
                alert('该分组包含子分组，请先删除或移动子分组');
                return;
            }

            // 检查分组中是否有设备
            if (group.deviceCount > 0) {
                if (!confirm(`分组 "${group.groupName}" 中包含 ${group.deviceCount} 个设备，确定要删除吗？`)) {
                    return;
                }
            } else {
                if (!confirm(`确定要删除分组 "${group.groupName}" 吗？`)) {
                    return;
                }
            }

            // 删除分组
            const index = groupData.findIndex(g => g.groupId == selectedGroupId);
            groupData.splice(index, 1);

            // 从设备的组ID列表中移除该分组
            deviceData.forEach(device => {
                const groupIndex = device.groupIds.indexOf(selectedGroupId);
                if (groupIndex !== -1) {
                    device.groupIds.splice(groupIndex, 1);
                }
            });

            // 重置选中状态
            selectedGroupId = null;

            // 刷新UI
            renderGroupTree();
            document.getElementById('noGroupSelected').style.display = 'block';
            document.getElementById('groupDetails').style.display = 'none';
            updateControlButtons();

            alert('分组删除成功');
        }

        // 打开添加设备到分组模态框
        function openAddDeviceModal() {
            const modal = document.getElementById('addDeviceModal');
            const targetGroupSelect = document.getElementById('targetGroupSelect');
            const deviceChecklist = document.getElementById('deviceChecklist');

            // 更新目标分组选择
            targetGroupSelect.innerHTML = '';
            groupData.forEach(group => {
                const option = document.createElement('option');
                option.value = group.groupId;
                option.textContent = group.groupName;
                if (group.groupId == selectedGroupId) {
                    option.selected = true;
                }
                targetGroupSelect.appendChild(option);
            });

            // 更新设备复选框列表
            deviceChecklist.innerHTML = '';
            deviceData.forEach(device => {
                const checkboxId = `device-${device.id}`;
                const isInSelectedGroup = selectedGroupId ? 
                    device.groupIds.includes(parseInt(selectedGroupId)) : false;

                const deviceItem = document.createElement('div');
                deviceItem.style.display = 'flex';
                deviceItem.style.alignItems = 'center';
                deviceItem.style.padding = '8px 0';
                deviceItem.style.borderBottom = '1px solid #f0f0f0';

                deviceItem.innerHTML = `
                    <input type="checkbox" id="${checkboxId}" value="${device.id}" ${isInSelectedGroup ? 'checked' : ''} style="margin-right: 10px;">
                    <label for="${checkboxId}" style="flex: 1; cursor: pointer;">
                        <div style="font-weight: 500;">${device.deviceName}</div>
                        <div style="font-size: 0.85rem; color: #8c8c8c;">${device.deviceType} • ${device.deviceId}</div>
                    </label>
                    <div>
                        <span class="device-status status-${device.status}" style="margin-right: 10px;"></span>
                        <span style="font-size: 0.85rem;">${device.status === 'online' ? '在线' : device.status === 'offline' ? '离线' : '警告'}</span>
                    </div>
                `;

                deviceChecklist.appendChild(deviceItem);
            });

            // 设备搜索功能
            document.getElementById('deviceSearch').addEventListener('input', function(e) {
                const searchTerm = e.target.value.toLowerCase();
                const deviceItems = deviceChecklist.querySelectorAll('div');

                deviceItems.forEach(item => {
                    const deviceName = item.querySelector('label div:first-child').textContent.toLowerCase();
                    const deviceId = item.querySelector('label div:last-child').textContent.toLowerCase();

                    if (deviceName.includes(searchTerm) || deviceId.includes(searchTerm)) {
                        item.style.display = 'flex';
                    } else {
                        item.style.display = 'none';
                    }
                });
            });

            modal.style.display = 'flex';
        }

        // 添加设备到分组
        function addDevicesToGroup() {
            const targetGroupId = document.getElementById('targetGroupSelect').value;
            if (!targetGroupId) {
                alert('请选择目标分组');
                return;
            }

            const targetGroup = groupData.find(g => g.groupId == targetGroupId);
            if (!targetGroup) return;

            // 获取选中的设备
            const selectedDeviceIds = [];
            document.querySelectorAll('#deviceChecklist input[type="checkbox"]:checked').forEach(checkbox => {
                selectedDeviceIds.push(parseInt(checkbox.value));
            });

            if (selectedDeviceIds.length === 0) {
                alert('请选择至少一个设备');
                return;
            }

            // 添加设备到分组
            let addedCount = 0;
            selectedDeviceIds.forEach(deviceId => {
                const device = deviceData.find(d => d.id == deviceId);
                if (device && !device.groupIds.includes(parseInt(targetGroupId))) {
                    device.groupIds.push(parseInt(targetGroupId));
                    addedCount++;

                    // 更新分组设备计数
                    targetGroup.deviceCount++;
                    if (device.status === 'online') {
                        targetGroup.onlineDeviceCount++;
                    }
                }
            });

            // 关闭模态框
            document.getElementById('addDeviceModal').style.display = 'none';

            // 刷新UI
            if (selectedGroupId == targetGroupId) {
                updateGroupDeviceList(targetGroupId);
                updateGroupDetails(targetGroupId);
            }
            renderGroupTree();
            updateStatistics();

            alert(`成功添加 ${addedCount} 个设备到分组 "${targetGroup.groupName}"`);
        }

        // 初始化页面
        document.addEventListener('DOMContentLoaded', function() {
            // 渲染分组树
            renderGroupTree();

            // 绑定按钮事件
            document.getElementById('addGroupBtn').addEventListener('click', function() {
                openGroupModal(false);
            });

            document.getElementById('editGroupBtn').addEventListener('click', function() {
                openGroupModal(true);
            });

            document.getElementById('deleteGroupBtn').addEventListener('click', deleteGroup);

            document.getElementById('refreshBtn').addEventListener('click', function() {
                renderGroupTree();
                alert('分组数据已刷新');
            });

            document.getElementById('addDeviceToGroupBtn').addEventListener('click', openAddDeviceModal);
            document.getElementById('manageDevicesBtn').addEventListener('click', openAddDeviceModal);
            document.getElementById('addFirstDeviceBtn').addEventListener('click', openAddDeviceModal);

            // 树形结构操作
            document.getElementById('expandAllBtn').addEventListener('click', function() {
                document.querySelectorAll('.group-tree ul').forEach(ul => {
                    ul.style.display = 'block';
                });
            });

            document.getElementById('collapseAllBtn').addEventListener('click', function() {
                document.querySelectorAll('.group-tree ul').forEach(ul => {
                    ul.style.display = 'none';
                });
            });

            // 分组搜索
            document.getElementById('groupSearch').addEventListener('input', function(e) {
                const searchTerm = e.target.value.toLowerCase();
                const treeItems = document.querySelectorAll('.tree-item');

                treeItems.forEach(item => {
                    const groupName = item.querySelector('.tree-item-name').textContent.toLowerCase();
                    if (groupName.includes(searchTerm)) {
                        item.style.display = 'flex';

                        // 显示父级
                        let parent = item.parentElement;
                        while (parent && parent.classList.contains('group-tree')) {
                            if (parent.tagName === 'UL') {
                                parent.style.display = 'block';
                            }
                            parent = parent.parentElement;
                        }
                    } else {
                        item.style.display = 'none';
                    }
                });
            });

            // 图标选择
            document.querySelectorAll('.icon-option').forEach(icon => {
                icon.addEventListener('click', function() {
                    document.querySelectorAll('.icon-option').forEach(i => i.classList.remove('selected'));
                    this.classList.add('selected');
                    document.getElementById('modalGroupIcon').value = this.dataset.icon;
                });
            });

            // 模态框控制
            document.getElementById('closeGroupModal').addEventListener('click', function() {
                document.getElementById('groupModal').style.display = 'none';
            });

            document.getElementById('cancelGroupBtn').addEventListener('click', function() {
                document.getElementById('groupModal').style.display = 'none';
            });

            document.getElementById('saveGroupBtn').addEventListener('click', saveGroup);

            document.getElementById('closeAddDeviceModal').addEventListener('click', function() {
                document.getElementById('addDeviceModal').style.display = 'none';
            });

            document.getElementById('cancelAddDeviceBtn').addEventListener('click', function() {
                document.getElementById('addDeviceModal').style.display = 'none';
            });

            document.getElementById('confirmAddDeviceBtn').addEventListener('click', addDevicesToGroup);

            // 导航菜单点击事件
            document.querySelectorAll('.nav-item, .nav-subitem').forEach(item => {
                item.addEventListener('click', function() {
                    // 移除所有active类
                    document.querySelectorAll('.nav-item.active, .nav-subitem.active').forEach(el => {
                        el.classList.remove('active');
                    });

                    // 为当前项添加active类
                    this.classList.add('active');

                    // 如果点击的是主菜单项，激活其第一个子项
                    if (this.classList.contains('nav-item')) {
                        const nextSibling = this.nextElementSibling;
                        if (nextSibling && nextSibling.classList.contains('nav-subitem')) {
                            nextSibling.classList.add('active');
                        }
                    }
                });
            });
        });
    </script>
</body>
</html>
```

这个HTML页面实现了中软国际开源鸿蒙交通路口管理平台的设备分组管理功能，包含以下特性：

1. **分组树形结构**：直观展示按路口、区域、类型等维度的分组层次结构
2. **分组详情展示**：显示选中的分组详细信息，包括分组属性、设备数量、创建信息等
3. **分组设备管理**：查看和管理分组内的设备，支持从分组中移除设备
4. **分组操作**：支持创建、编辑、删除分组，支持图标选择和状态设置
5. **设备添加功能**：将设备添加到分组，支持多选和搜索过滤
6. **数据统计面板**：实时统计分组总数、设备总数、在线设备和覆盖区域
7. **响应式设计**：适配不同屏幕尺寸，支持移动端操作

页面模拟了真实的设备分组管理场景，展示了多维度、层次化的设备分组管理能力，支持路口分组、区域分组、设备类型分组和厂商分组等多种分组方式，实现了设备与分组的灵活关联管理。

