        function renderTagGrid(category = "all", searchTerm = "") {
            const tagGrid = document.getElementById('tagGrid');
            tagGrid.innerHTML = '';

            // 过滤标签
            let filteredTags = tagData;

            if (category !== "all") {
                filteredTags = filteredTags.filter(tag => tag.category === category);
            }

            if (searchTerm) {
                const term = searchTerm.toLowerCase();
                filteredTags = filteredTags.filter(tag => 
                    tag.name.toLowerCase().includes(term) || 
                    (tag.description && tag.description.toLowerCase().includes(term))
                );
            }

            if (filteredTags.length === 0) {
                document.getElementById('noTagsMessage').style.display = 'block';
                tagGrid.style.display = 'none';
            } else {
                document.getElementById('noTagsMessage').style.display = 'none';
                tagGrid.style.display = 'grid';

                filteredTags.forEach(tag => {
                    const tagElement = createTagCard(tag);
                    tagGrid.appendChild(tagElement);
                });
            }

            updateCategoryCounts();
            updateStatistics();
        }

        // 创建标签卡片
        function createTagCard(tag) {
            const div = document.createElement('div');
            div.className = 'tag-item';
            div.dataset.id = tag.id;

            // 获取分类信息
            const categoryInfo = categoryMap[tag.category];

            div.innerHTML = `
                <div class="tag-header">
                    <div class="tag-name">${tag.name}</div>
                    <div class="tag-actions">
                        <button class="tag-action-btn edit" data-id="${tag.id}" title="编辑标签">
                            <i class="fas fa-edit"></i>
                        </button>
                        <button class="tag-action-btn delete" data-id="${tag.id}" title="删除标签">
                            <i class="fas fa-trash"></i>
                        </button>
                    </div>
                </div>
                <div class="tag-description">${tag.description || '暂无描述'}</div>
                <div class="tag-meta">
                    <div>
                        <span class="tag-color" style="background-color: ${tag.color}; margin-right: 5px;"></span>
                        <span>${categoryInfo.name}</span>
                    </div>
                    <div class="tag-device-count">${tag.deviceCount} 设备</div>
                </div>
            `;

            // 绑定编辑和删除事件
            div.querySelector('.edit').addEventListener('click', function(e) {
                e.stopPropagation();
                openTagModal(tag.id);
            });

            div.querySelector('.delete').addEventListener('click', function(e) {
                e.stopPropagation();
                deleteTag(tag.id);
            });

            return div;
        }

        // 渲染设备表格
        function renderDeviceTable() {
            const tableBody = document.getElementById('deviceTableBody');
            tableBody.innerHTML = '';

            deviceData.forEach(device => {
                const row = document.createElement('tr');

                // 状态指示器
                const statusClass = `status-${device.status}`;
                const statusText = device.status === 'online' ? '在线' : device.status === 'offline' ? '离线' : '警告';

                // 设备标签
                const tagElements = device.tags.map(tagId => {
                    const tag = tagData.find(t => t.id === tagId);
                    if (!tag) return '';

                    return `
                        <div class="device-tag" style="background-color: ${tag.color}20; color: ${tag.color}; border: 1px solid ${tag.color}40;">
                            ${tag.name}
                            <span class="remove-tag" data-device-id="${device.id}" data-tag-id="${tagId}">×</span>
                        </div>
                    `;
                }).join('');

                row.innerHTML = `
                    <td>${device.deviceName}</td>
                    <td>${device.deviceType}</td>
                    <td>
                        <div style="display: flex; align-items: center; gap: 8px;">
                            <div class="device-status ${statusClass}"></div>
                            <span>${statusText}</span>
                        </div>
                    </td>
                    <td>
                        <div class="device-tags">
                            ${tagElements}
                        </div>
                    </td>
                    <td>
                        <div class="tagging-actions">
                            <button class="add-tag-btn" data-device-id="${device.id}">
                                <i class="fas fa-plus"></i>
                                添加标签
                            </button>
                        </div>
                    </td>
                `;

                tableBody.appendChild(row);
            });

            // 绑定添加标签事件
            document.querySelectorAll('.add-tag-btn').forEach(btn => {
                btn.addEventListener('click', function() {
                    const deviceId = this.dataset.deviceId;
                    openDeviceTagModal([deviceId]);
                });
            });

