                btn.addEventListener('click', function() {
                    const deviceId = parseInt(this.dataset.deviceId);
                    const tagId = parseInt(this.dataset.tagId);
                    removeTagFromDevice(deviceId, tagId);
                });
            });
        }

        // 从设备中移除标签
        function removeTagFromDevice(deviceId, tagId) {
            const device = deviceData.find(d => d.id === deviceId);
            if (!device) return;

            const tagIndex = device.tags.indexOf(tagId);
            if (tagIndex !== -1) {
                device.tags.splice(tagIndex, 1);

                // 更新标签的设备计数
                const tag = tagData.find(t => t.id === tagId);
                if (tag) {
                    tag.deviceCount--;
                }

                // 更新UI
                renderDeviceTable();
                renderTagGrid(selectedCategory);

                alert(`标签已从设备 ${device.deviceName} 中移除`);
            }
        }

        // 更新分类计数
        function updateCategoryCounts() {
            // 计算每个分类的标签数量
            const categoryCounts = {
                all: tagData.length,
                status: tagData.filter(tag => tag.category === "status").length,
                location: tagData.filter(tag => tag.category === "location").length,
                "device-type": tagData.filter(tag => tag.category === "device-type").length,
                vendor: tagData.filter(tag => tag.category === "vendor").length,
                priority: tagData.filter(tag => tag.category === "priority").length,
                custom: tagData.filter(tag => tag.category === "custom").length
            };

            // 更新分类列表中的计数
            document.querySelectorAll('.category-item').forEach(item => {
                const category = item.dataset.category;
                const countElement = item.querySelector('.category-count');
                if (countElement) {
                    countElement.textContent = categoryCounts[category] || 0;
                }
            });
        }

        // 更新统计信息
        function updateStatistics() {
            // 计算已标记设备数量
            const taggedDevices = deviceData.filter(device => device.tags.length > 0).length;

            // 计算标签分类数量
            const uniqueCategories = new Set(tagData.map(tag => tag.category));
            const tagCategories = uniqueCategories.size;

            // 计算自动化规则数量
            const autoRules = tagData.filter(tag => tag.autoRule).length;

            document.getElementById('taggedDevices').textContent = taggedDevices;
            document.getElementById('tagCategories').textContent = tagCategories;
            document.getElementById('autoRules').textContent = autoRules;
        }

        // 打开标签模态框
        function openTagModal(tagId = null) {
            const modal = document.getElementById('tagModal');
            const title = document.getElementById('modalTitle');

            if (tagId) {
                // 编辑模式
                title.textContent = '编辑标签';
                editingTagId = tagId;
                const tag = tagData.find(t => t.id === tagId);

                if (tag) {
                    document.getElementById('modalTagName').value = tag.name;
                    document.getElementById('modalTagCategory').value = tag.category;
                    document.getElementById('modalTagDescription').value = tag.description || '';
                    document.getElementById('modalAutoRule').value = tag.autoRule || '';
                    document.getElementById('modalTagColor').value = tag.color;

                    // 设置颜色选择
                    document.querySelectorAll('.color-option').forEach(option => {
                        option.classList.remove('selected');
                        if (option.dataset.color === tag.color) {
                            option.classList.add('selected');
                        }
                    });
                }
            } else {
                // 新建模式
                title.textContent = '新建标签';
                editingTagId = null;

                // 重置表单
                document.getElementById('modalTagName').value = '';
                document.getElementById('modalTagCategory').value = selectedCategory === 'all' ? 'custom' : selectedCategory;
                document.getElementById('modalTagDescription').value = '';
                document.getElementById('modalAutoRule').value = '';
                document.getElementById('modalTagColor').value = '#1890ff';

                // 设置默认颜色选择
                document.querySelectorAll('.color-option').forEach(option => {
                    option.classList.remove('selected');
                    if (option.dataset.color === '#1890ff') {
                        option.classList.add('selected');
                    }
                });
            }

            modal.style.display = 'flex';
        }

        // 保存标签
        function saveTag() {
            const tagName = document.getElementById('modalTagName').value.trim();
            const tagCategory = document.getElementById('modalTagCategory').value;
            const tagDescription = document.getElementById('modalTagDescription').value;
            const tagColor = document.getElementById('modalTagColor').value;
            const autoRule = document.getElementById('modalAutoRule').value;

            if (!tagName) {
                alert('请输入标签名称');
                return;
            }

            if (editingTagId !== null) {
                // 更新现有标签
                const tagIndex = tagData.findIndex(t => t.id === editingTagId);
                if (tagIndex !== -1) {
                    tagData[tagIndex].name = tagName;
                    tagData[tagIndex].category = tagCategory;
                    tagData[tagIndex].description = tagDescription;
                    tagData[tagIndex].color = tagColor;
                    tagData[tagIndex].autoRule = autoRule;
                }

                alert('标签更新成功');
            } else {
                // 创建新标签
                const newTagId = Math.max(...tagData.map(t => t.id)) + 1;
                const newTag = {
                    id: newTagId,
                    name: tagName,
                    category: tagCategory,
                    color: tagColor,
                    description: tagDescription,
                    deviceCount: 0,
                    autoRule: autoRule,
                    createdBy: '管理员',
                    createTime: new Date().toLocaleString('zh-CN')
                };

                tagData.push(newTag);
                alert('标签创建成功');
            }

            // 关闭模态框
            document.getElementById('tagModal').style.display = 'none';

            // 刷新UI
            renderTagGrid(selectedCategory);
        }

        // 删除标签
        function deleteTag(tagId) {
            const tag = tagData.find(t => t.id === tagId);
            if (!tag) return;

            // 检查是否有设备使用此标签
            const devicesWithTag = deviceData.filter(device => device.tags.includes(tagId));

            if (devicesWithTag.length > 0) {
                if (!confirm(`标签 "${tag.name}" 正在被 ${devicesWithTag.length} 个设备使用，确定要删除吗？删除后将从所有设备中移除该标签。`)) {
                    return;
                }

                // 从所有设备中移除该标签
                deviceData.forEach(device => {
                    const index = device.tags.indexOf(tagId);
                    if (index !== -1) {
                        device.tags.splice(index, 1);
                    }
                });
            } else {
                if (!confirm(`确定要删除标签 "${tag.name}" 吗？`)) {
                    return;
                }
            }

            // 删除标签
            const tagIndex = tagData.findIndex(t => t.id === tagId);
            tagData.splice(tagIndex, 1);

            // 刷新UI
            renderTagGrid(selectedCategory);
            renderDeviceTable();

            alert('标签删除成功');
        }

        // 打开设备打标签模态框
        function openDeviceTagModal(deviceIds = []) {
            const modal = document.getElementById('deviceTagModal');
            const deviceChecklist = document.getElementById('deviceTagChecklist');
            const tagChecklist = document.getElementById('tagSelectionChecklist');

            // 更新设备复选框列表
            deviceChecklist.innerHTML = '';
            deviceData.forEach(device => {
                const isSelected = deviceIds.length === 0 || deviceIds.includes(device.id.toString());
                const checkboxId = `modal-device-${device.id}`;

                const deviceItem = document.createElement('div');
                deviceItem.style.display = 'flex';
                deviceItem.style.alignItems = 'center';
                deviceItem.style.padding = '8px 0';
                deviceItem.style.borderBottom = '1px solid #f0f0f0';

                deviceItem.innerHTML = `
                    <input type="checkbox" id="${checkboxId}" value="${device.id}" ${isSelected ? 'checked' : ''} style="margin-right: 10px;">
                    <label for="${checkboxId}" style="flex: 1; cursor: pointer;">
                        <div style="font-weight: 500;">${device.deviceName}</div>
                        <div style="font-size: 0.85rem; color: #8c8c8c;">${device.deviceType}</div>
                    </label>
                    <div>
                        <span class="device-status status-${device.status}" style="margin-right: 10px;"></span>
                        <span style="font-size: 0.85rem;">${device.status === 'online' ? '在线' : device.status === 'offline' ? '离线' : '警告'}</span>
                    </div>
                `;

                deviceChecklist.appendChild(deviceItem);
            });

            // 更新标签复选框列表
            tagChecklist.innerHTML = '';
            tagData.forEach(tag => {
                const checkboxId = `modal-tag-${tag.id}`;

                const tagItem = document.createElement('div');
                tagItem.style.display = 'flex';
                tagItem.style.alignItems = 'center';
                tagItem.style.padding = '8px 0';
                tagItem.style.borderBottom = '1px solid #f0f0f0';

                tagItem.innerHTML = `
                    <input type="checkbox" id="${checkboxId}" value="${tag.id}" style="margin-right: 10px;">
                    <label for="${checkboxId}" style="flex: 1; cursor: pointer; display: flex; align-items: center; gap: 8px;">
                        <span class="tag-color" style="width: 16px; height: 16px; background-color: ${tag.color}; border-radius: 3px;"></span>
                        <div>
                            <div style="font-weight: 500;">${tag.name}</div>
                            <div style="font-size: 0.85rem; color: #8c8c8c;">${tag.description || '无描述'}</div>
                        </div>
                    </label>
                    <div style="font-size: 0.85rem; color: #8c8c8c;">
                        ${tag.deviceCount} 设备
                    </div>
                `;

                tagChecklist.appendChild(tagItem);
            });

            // 设备搜索功能
            document.getElementById('deviceTagSearch').addEventListener('input', function(e) {
                const searchTerm = e.target.value.toLowerCase();
                const deviceItems = deviceChecklist.querySelectorAll('div');

                deviceItems.forEach(item => {
                    const deviceName = item.querySelector('label div:first-child').textContent.toLowerCase();
                    const deviceType = item.querySelector('label div:last-child').textContent.toLowerCase();

                    if (deviceName.includes(searchTerm) || deviceType.includes(searchTerm)) {
                        item.style.display = 'flex';
                    } else {
                        item.style.display = 'none';
                    }
                });
            });

            // 标签搜索功能
            document.getElementById('tagSelectionSearch').addEventListener('input', function(e) {
                const searchTerm = e.target.value.toLowerCase();
                const tagItems = tagChecklist.querySelectorAll('div');

                tagItems.forEach(item => {
                    const tagName = item.querySelector('label div:first-child').textContent.toLowerCase();
                    const tagDescription = item.querySelector('label div:last-child').textContent.toLowerCase();

                    if (tagName.includes(searchTerm) || tagDescription.includes(searchTerm)) {
                        item.style.display = 'flex';
                    } else {
                        item.style.display = 'none';
                    }
                });
            });

            modal.style.display = 'flex';
        }

        // 应用标签到设备
        function applyTagsToDevices() {
            // 获取选中的设备
            const selectedDeviceIds = [];
            document.querySelectorAll('#deviceTagChecklist input[type="checkbox"]:checked').forEach(checkbox => {
                selectedDeviceIds.push(parseInt(checkbox.value));
            });

            if (selectedDeviceIds.length === 0) {
                alert('请选择至少一个设备');
                return;
            }

            // 获取选中的标签
            const selectedTagIds = [];
            document.querySelectorAll('#tagSelectionChecklist input[type="checkbox"]:checked').forEach(checkbox => {
                selectedTagIds.push(parseInt(checkbox.value));
            });

            if (selectedTagIds.length === 0) {
                alert('请选择至少一个标签');
                return;
            }

            // 为每个设备添加选中的标签
            let updatedDevices = 0;
            selectedDeviceIds.forEach(deviceId => {
                const device = deviceData.find(d => d.id === deviceId);
                if (!device) return;

                selectedTagIds.forEach(tagId => {
                    if (!device.tags.includes(tagId)) {
                        device.tags.push(tagId);

                        // 更新标签的设备计数
                        const tag = tagData.find(t => t.id === tagId);
                        if (tag) {
                            tag.deviceCount++;
                        }

                        updatedDevices++;
                    }
                });
            });

            // 关闭模态框
            document.getElementById('deviceTagModal').style.display = 'none';

            // 刷新UI
            renderDeviceTable();
            renderTagGrid(selectedCategory);

            alert(`成功为 ${selectedDeviceIds.length} 个设备添加了 ${selectedTagIds.length} 个标签`);
        }

        // 初始化页面
        document.addEventListener('DOMContentLoaded', function() {
            // 渲染标签网格
            renderTagGrid();

            // 渲染设备表格
            renderDeviceTable();

            // 绑定分类选择事件
            document.querySelectorAll('.category-item').forEach(item => {
                item.addEventListener('click', function() {
                    // 移除之前选中的样式
                    document.querySelectorAll('.category-item.selected').forEach(el => {
                        el.classList.remove('selected');
                    });

                    // 添加选中样式
                    this.classList.add('selected');

                    // 更新当前分类
                    selectedCategory = this.dataset.category;

                    // 更新标题
                    const categoryInfo = categoryMap[selectedCategory];
                    document.getElementById('currentCategoryTitle').textContent = categoryInfo.name;

                    // 重新渲染标签网格
                    const searchTerm = document.getElementById('tagSearch').value;
                    renderTagGrid(selectedCategory, searchTerm);
                });
            });

            // 绑定按钮事件
            document.getElementById('createTagBtn').addEventListener('click', function() {
                openTagModal();
            });

            document.getElementById('batchTagBtn').addEventListener('click', function() {
                openDeviceTagModal();
            });

            document.getElementById('refreshBtn').addEventListener('click', function() {
                renderTagGrid(selectedCategory);
                renderDeviceTable();
                alert('标签数据已刷新');
            });

            document.getElementById('exportTagsBtn').addEventListener('click', function() {
                alert('标签数据导出功能正在开发中');
            });

            document.getElementById('filterTagsBtn').addEventListener('click', function() {
                alert('高级筛选功能正在开发中');
            });

            document.getElementById('addCategoryBtn').addEventListener('click', function() {
                alert('新增分类功能正在开发中');
            });

            // 标签搜索
            document.getElementById('tagSearch').addEventListener('input', function(e) {
                const searchTerm = e.target.value;
                renderTagGrid(selectedCategory, searchTerm);
            });

            // 颜色选择
            document.querySelectorAll('.color-option').forEach(option => {
                option.addEventListener('click', function() {
                    document.querySelectorAll('.color-option').forEach(opt => opt.classList.remove('selected'));
                    this.classList.add('selected');
                    document.getElementById('modalTagColor').value = this.dataset.color;
                });
            });

            // 模态框控制
            document.getElementById('closeTagModal').addEventListener('click', function() {
                document.getElementById('tagModal').style.display = 'none';
            });

            document.getElementById('cancelTagBtn').addEventListener('click', function() {
                document.getElementById('tagModal').style.display = 'none';
            });

            document.getElementById('saveTagBtn').addEventListener('click', saveTag);

            document.getElementById('closeDeviceTagModal').addEventListener('click', function() {
                document.getElementById('deviceTagModal').style.display = 'none';
            });

            document.getElementById('cancelDeviceTagBtn').addEventListener('click', function() {
                document.getElementById('deviceTagModal').style.display = 'none';
            });

            document.getElementById('confirmDeviceTagBtn').addEventListener('click', applyTagsToDevices);

            // 导航菜单点击事件
            document.querySelectorAll('.nav-item, .nav-subitem').forEach(item => {
                item.addEventListener('click', function() {
                    // 移除所有active类
                    document.querySelectorAll('.nav-item.active, .nav-subitem.active').forEach(el => {
                        el.classList.remove('active');
                    });

                    // 为当前项添加active类
                    this.classList.add('active');

                    // 如果点击的是主菜单项，激活其第一个子项
                    if (this.classList.contains('nav-item')) {
                        const nextSibling = this.nextElementSibling;
                        if (nextSibling && nextSibling.classList.contains('nav-subitem')) {
                            nextSibling.classList.add('active');
                        }
                    }
                });
            });
        });
    </script>
</body>
