            },
            {
                id: 3,
                title: "内存使用率过高",
                device: "智能摄像机-08",
                level: "major",
                levelText: "重要",
                time: "15分钟前",
                description: "内存使用率超过65%"
            },
            {
                id: 4,
                title: "网络延迟增大",
                device: "边缘计算盒子-03",
                level: "minor",
                levelText: "一般",
                time: "25分钟前",
                description: "网络延迟超过200ms"
            },
            {
                id: 5,
                title: "存储空间不足",
                device: "边缘计算盒子-01",
                level: "minor",
                levelText: "一般",
                time: "1小时前",
                description: "存储空间剩余不足20%"
            },
            {
                id: 6,
                title: "视频流异常",
                device: "智能摄像机-03",
                level: "info",
                levelText: "提示",
                time: "10分钟前",
                description: "视频流帧率低于20fps"
            }
        ];

        // 初始化设备表格
        function renderDeviceTable(filteredDevices = deviceData) {
            const tableBody = document.getElementById('deviceTableBody');
            tableBody.innerHTML = '';

            filteredDevices.forEach(device => {
                const row = document.createElement('tr');

                // 根据状态设置行样式
                if (device.status === 'offline') {
                    row.style.opacity = '0.7';
                }

                // 设备类型图标
                let typeIconClass = '';
                let iconClass = '';

                switch(device.type) {
                    case 'signal':
                        typeIconClass = 'traffic-light-icon';
                        iconClass = 'fas fa-traffic-light';
                        break;
                    case 'camera':
                        typeIconClass = 'camera-icon';
                        iconClass = 'fas fa-video';
                        break;
                    case 'radar':
                        typeIconClass = 'radar-icon';
                        iconClass = 'fas fa-satellite-dish';
                        break;
                    case 'edge':
                        typeIconClass = 'server-icon';
                        iconClass = 'fas fa-server';
                        break;
                    case 'sensor':
                        typeIconClass = 'sensor-icon';
                        iconClass = 'fas fa-thermometer-half';
                        break;
                }

                // 状态标签
                let statusClass = '';
                let statusText = '';
                let indicatorClass = '';

                switch(device.status) {
                    case 'online':
                        statusClass = 'status-online';
                        statusText = '在线';
                        indicatorClass = 'status-indicator online';
                        break;
                    case 'offline':
                        statusClass = 'status-offline';
                        statusText = '离线';
                        indicatorClass = 'status-indicator offline';
                        break;
                    case 'warning':
                        statusClass = 'status-warning';
                        statusText = '异常';
                        indicatorClass = 'status-indicator warning';
                        break;
                }

                row.innerHTML = `
                    <td>
                        <div class="device-name">
                            <div class="device-type-icon ${typeIconClass}">
                                <i class="${iconClass}"></i>
                            </div>
                            <div>
                                <div>${device.name}</div>
                                <div style="font-size: 0.8rem; color: #8c8c8c;">${device.ip}</div>
                            </div>
                        </div>
                    </td>
                    <td>${device.typeText}</td>
                    <td>${device.intersection}</td>
                    <td>
                        <div class="device-status ${statusClass}">
                            <span class="${indicatorClass}"></span>
                            <span>${statusText}</span>
                        </div>
                    </td>
                    <td>
                        <div class="resource-meter">
                            <div class="meter-bar">
                                <div class="meter-fill cpu-fill" style="width: ${device.cpu}%"></div>
                            </div>
                            <span class="meter-value">${device.cpu}%</span>
                        </div>
                    </td>
                    <td>
                        <div class="resource-meter">
                            <div class="meter-bar">
                                <div class="meter-fill memory-fill" style="width: ${device.memory}%"></div>
                            </div>
                            <span class="meter-value">${device.memory}%</span>
                        </div>
                    </td>
                    <td>${device.lastReport}</td>
                `;

                tableBody.appendChild(row);

                // 添加点击事件
                row.addEventListener('click', function() {
                    // 移除所有选中状态
                    document.querySelectorAll('.device-table tr').forEach(r => {
                        r.classList.remove('selected');
                    });

                    // 添加选中状态
                    this.classList.add('selected');

                    // 更新图表显示选中设备
                    updateDeviceChart(device);
                });
            });
        }

        // 初始化告警列表
        function renderAlertsList() {
            const alertsList = document.getElementById('alertsList');
            alertsList.innerHTML = '';

            alertData.forEach(alert => {
                const alertItem = document.createElement('div');
                alertItem.className = 'alert-item';

                // 告警级别图标
                let alertIconClass = '';
                let levelClass = '';

                switch(alert.level) {
                    case 'critical':
                        alertIconClass = 'alert-icon alert-critical';
                        levelClass = 'alert-level level-critical';
                        break;
                    case 'major':
                        alertIconClass = 'alert-icon alert-major';
                        levelClass = 'alert-level level-major';
                        break;
                    case 'minor':
                        alertIconClass = 'alert-icon alert-minor';
                        levelClass = 'alert-level level-minor';
                        break;
                    case 'info':
                        alertIconClass = 'alert-icon alert-info';
                        levelClass = 'alert-level level-info';
                        break;
                }

                alertItem.innerHTML = `
                    <div class="${alertIconClass}">
                        <i class="fas fa-exclamation-circle"></i>
                    </div>
                    <div class="alert-content">
                        <div class="alert-title">
                            <span>${alert.title}</span>
                            <span class="${levelClass}">${alert.levelText}</span>
                        </div>
                        <div class="alert-device">设备: ${alert.device}</div>
                        <div class="alert-time">${alert.time} • ${alert.description}</div>
                    </div>
                `;

                alertsList.appendChild(alertItem);
            });
        }

        // 初始化资源使用趋势图表
        let resourceChart;

        function initResourceChart() {
            const ctx = document.getElementById('resourceChart').getContext('2d');

            // 模拟24小时内的数据
            const hours = [];
            for (let i = 0; i < 24; i++) {
                hours.push(`${i}:00`);
            }

            // 模拟CPU和内存数据
            const cpuData = [];
            const memoryData = [];

            for (let i = 0; i < 24; i++) {
                // 模拟白天高峰时段
                if (i >= 7 && i <= 19) {
                    cpuData.push(Math.floor(Math.random() * 30) + 40);
                    memoryData.push(Math.floor(Math.random() * 25) + 50);
                } else {
                    cpuData.push(Math.floor(Math.random() * 20) + 20);
                    memoryData.push(Math.floor(Math.random() * 20) + 30);
                }
            }

            resourceChart = new Chart(ctx, {
                type: 'line',
                data: {
                    labels: hours,
                    datasets: [
                        {
                            label: 'CPU使用率 (%)',
                            data: cpuData,
                            borderColor: '#722ed1',
                            backgroundColor: 'rgba(114, 46, 209, 0.1)',
                            borderWidth: 2,
                            fill: true,
                            tension: 0.3
                        },
                        {
                            label: '内存使用率 (%)',
                            data: memoryData,
                            borderColor: '#eb2f96',
                            backgroundColor: 'rgba(235, 47, 150, 0.1)',
                            borderWidth: 2,
                            fill: true,
                            tension: 0.3
                        }
                    ]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: {
                        legend: {
                            position: 'top',
                        },
                        tooltip: {
                            mode: 'index',
                            intersect: false
                        }
                    },
                    scales: {
                        y: {
                            beginAtZero: true,
                            max: 100,
                            title: {
                                display: true,
                                text: '使用率 (%)'
                            }
                        },
                        x: {
                            title: {
                                display: true,
                                text: '时间 (24小时)'
                            }
                        }
                    }
                }
            });
        }

        // 更新设备图表
        function updateDeviceChart(device) {
            // 这里可以更新图表以显示选定设备的详细数据
            // 为了简单起见，我们只是显示一个提示
            console.log(`显示设备 ${device.name} 的详细图表数据`);

            // 在实际应用中，这里会向服务器请求设备的历史数据并更新图表
            alert(`将显示设备 "${device.name}" 的详细资源使用历史图表`);
        }

        // 过滤设备数据
        function filterDevices() {
            const typeFilter = document.getElementById('deviceTypeFilter').value;
            const statusFilter = document.getElementById('deviceStatusFilter').value;
            const intersectionFilter = document.getElementById('intersectionFilter').value;
            const searchInput = document.getElementById('searchInput').value.toLowerCase();

            let filtered = deviceData;

            // 按设备类型过滤
            if (typeFilter !== 'all') {
                filtered = filtered.filter(device => device.type === typeFilter);
            }

            // 按设备状态过滤
            if (statusFilter !== 'all') {
                filtered = filtered.filter(device => device.status === statusFilter);
            }

            // 按路口过滤
            if (intersectionFilter !== 'all') {
                filtered = filtered.filter(device => device.intersection === `路口${intersectionFilter}`);
            }

            // 按搜索词过滤
            if (searchInput) {
                filtered = filtered.filter(device => 
                    device.name.toLowerCase().includes(searchInput) || 
                    device.ip.includes(searchInput)
                );
            }

            renderDeviceTable(filtered);
        }

        // 刷新数据
        function refreshData() {
            // 模拟数据更新
            const now = new Date();
            const timeString = now.toLocaleString('zh-CN');
            document.getElementById('lastUpdateTime').textContent = timeString;

            // 随机更新一些设备的状态和数据
            deviceData.forEach(device => {
                if (device.status !== 'offline') {
                    // 随机变化CPU和内存使用率
                    device.cpu = Math.max(5, Math.min(95, device.cpu + Math.floor(Math.random() * 10) - 5));
                    device.memory = Math.max(10, Math.min(90, device.memory + Math.floor(Math.random() * 8) - 4));

                    // 更新时间
                    const minutesAgo = Math.floor(Math.random() * 5) + 1;
                    device.lastReport = `${minutesAgo}分钟前`;

                    // 随机改变一些设备的状态
                    if (Math.random() < 0.05) {
                        device.status = 'warning';
                    } else if (Math.random() < 0.02) {
                        device.status = 'offline';
                    } else if (device.status === 'offline' && Math.random() < 0.1) {
                        device.status = 'online';
                    }
                }
            });

            // 重新渲染表格
            renderDeviceTable();

            // 更新卡片数据
            const onlineCount = deviceData.filter(d => d.status === 'online').length;
            const offlineCount = deviceData.filter(d => d.status === 'offline').length;
            const warningCount = deviceData.filter(d => d.status === 'warning').length;

            document.querySelector('.card:nth-child(2) .card-value').textContent = onlineCount;
            document.querySelector('.card:nth-child(3) .card-value').textContent = offlineCount;
            document.querySelector('.card:nth-child(4) .card-value').textContent = warningCount;

            // 计算平均CPU和内存使用率
            const onlineDevices = deviceData.filter(d => d.status !== 'offline');
            const avgCpu = onlineDevices.length > 0 ? 
                Math.round(onlineDevices.reduce((sum, d) => sum + d.cpu, 0) / onlineDevices.length) : 0;
            const avgMemory = onlineDevices.length > 0 ? 
                Math.round(onlineDevices.reduce((sum, d) => sum + d.memory, 0) / onlineDevices.length) : 0;

            document.querySelector('.card:nth-child(5) .card-value').textContent = `${avgCpu}%`;
            document.querySelector('.card:nth-child(6) .card-value').textContent = `${avgMemory}%`;

            // 显示刷新提示
            const refreshBtn = document.querySelector('.btn-primary');
            const originalText = refreshBtn.innerHTML;
            refreshBtn.innerHTML = '<i class="fas fa-check"></i> 数据已更新';
            refreshBtn.style.backgroundColor = '#52c41a';
            refreshBtn.style.borderColor = '#52c41a';

            setTimeout(() => {
                refreshBtn.innerHTML = originalText;
                refreshBtn.style.backgroundColor = '';
                refreshBtn.style.borderColor = '';
            }, 2000);
        }

        // 初始化页面
        document.addEventListener('DOMContentLoaded', function() {
            // 渲染初始数据
            renderDeviceTable();
            renderAlertsList();
            initResourceChart();

            // 设置过滤器事件
            document.getElementById('deviceTypeFilter').addEventListener('change', filterDevices);
            document.getElementById('deviceStatusFilter').addEventListener('change', filterDevices);
            document.getElementById('intersectionFilter').addEventListener('change', filterDevices);
            document.getElementById('searchInput').addEventListener('input', filterDevices);

            // 设置自动刷新
            setInterval(refreshData, 60000); // 每60秒刷新一次

            // 导航菜单点击事件
            document.querySelectorAll('.nav-item, .nav-subitem').forEach(item => {
                item.addEventListener('click', function() {
                    // 移除所有active类
                    document.querySelectorAll('.nav-item.active, .nav-subitem.active').forEach(el => {
                        el.classList.remove('active');
                    });

                    // 为当前项添加active类
                    this.classList.add('active');

                    // 如果点击的是主菜单项，激活其第一个子项
                    if (this.classList.contains('nav-item')) {
                        const nextSibling = this.nextElementSibling;
                        if (nextSibling && nextSibling.classList.contains('nav-subitem')) {
                            nextSibling.classList.add('active');
                        }
                    }
                });
            });
        });
    </script>
</body>
</html>
