                if (metric.name === "CPU使用率" || metric.name === "内存使用率" || metric.name === "存储空间使用") {
                    if (metric.value >= 85) {
                        progressClass = 'progress-danger';
                    } else if (metric.value >= 70) {
                        progressClass = 'progress-warning';
                    }
                } else if (metric.name === "设备温度") {
                    if (metric.value >= 75) {
                        progressClass = 'progress-danger';
                    } else if (metric.value >= 60) {
                        progressClass = 'progress-warning';
