                thresholdItem.className = 'threshold-item';

                // 确定阈值位置
                const warningPos = (threshold.warning / 100) * 100;
                const criticalPos = (threshold.critical / 100) * 100;
                const currentPos = (threshold.current / 100) * 100;

                // 确定当前状态颜色
                let currentColorClass = 'progress-safe';
                if (threshold.current >= threshold.critical) {
                    currentColorClass = 'progress-danger';
