        // 刷新资源数据
        function refreshResourceData() {
            const now = new Date();
            const timeString = now.toLocaleString('zh-CN');
            document.getElementById('lastUpdateTime').textContent = timeString;

            // 模拟数据更新
            const deviceId = document.getElementById('deviceSelector').value;

            // 随机更新资源数据
            Object.keys(resourceData).forEach(key => {
                const data = resourceData[key];

                // 随机变化资源使用率
                data.cpu = Math.max(5, Math.min(95, data.cpu + Math.floor(Math.random() * 6) - 3));
                data.memory = Math.max(10, Math.min(90, data.memory + Math.floor(Math.random() * 6) - 3));
                data.storage = Math.max(20, Math.min(95, data.storage + Math.floor(Math.random() * 4) - 2));
                data.network = Math.max(5, Math.min(80, data.network + Math.floor(Math.random() * 10) - 5));
                data.temperature = Math.max(35, Math.min(65, data.temperature + Math.floor(Math.random() * 4) - 2));
                data.power = Math.max(85, Math.min(100, data.power - Math.floor(Math.random() * 2)));

                // 更新趋势数据
                data.cpuTrend = data.cpuTrend.map(value => Math.max(5, Math.min(95, value + Math.floor(Math.random() * 4) - 2)));
                data.memoryTrend = data.memoryTrend.map(value => Math.max(10, Math.min(90, value + Math.floor(Math.random() * 4) - 2)));
            });

            // 更新阈值当前值
            thresholdConfigs.forEach(threshold => {
                const deviceData = resourceData[deviceId] || resourceData.all;
                threshold.current = deviceData[threshold.metric];
            });

            // 更新界面
            updateDashboardCards(deviceId);
            renderResourceMetrics(deviceId);
            renderThresholds();

            // 显示刷新提示
            const refreshBtn = document.querySelector('.btn-primary');
            const originalText = refreshBtn.innerHTML;
            refreshBtn.innerHTML = '<i class="fas fa-check"></i> 数据已更新';
            refreshBtn.style.backgroundColor = '#52c41a';
            refreshBtn.style.borderColor = '#52c41a';

            setTimeout(() => {
                refreshBtn.innerHTML = originalText;
                refreshBtn.style.backgroundColor = '';
                refreshBtn.style.borderColor = '';
            }, 2000);
        }

        // 初始化页面
        document.addEventListener('DOMContentLoaded', function() {
            // 初始化默认视图（所有设备概览）
            updateDashboardCards('all');
            renderResourceMetrics('all');
            renderThresholds();

            // 设备选择器事件
            document.getElementById('deviceSelector').addEventListener('change', function() {
                const deviceId = this.value;
                updateDashboardCards(deviceId);
                renderResourceMetrics(deviceId);
            });

            // 时间选择器事件
            document.querySelectorAll('.time-btn').forEach(btn => {
                btn.addEventListener('click', function() {
                    // 移除所有active类
                    this.parentNode.querySelectorAll('.time-btn').forEach(b => {
                        b.classList.remove('active');
                    });

                    // 添加active类
                    this.classList.add('active');

                    // 在实际应用中，这里会根据选择的时间范围重新获取数据
                    // 这里只是模拟
                    const period = this.getAttribute('data-period');
                    console.log(`加载 ${period} 时间段的数据`);
                });
            });

            // 设置自动刷新
            setInterval(refreshResourceData, 30000); // 每30秒刷新一次

            // 导航菜单点击事件
            document.querySelectorAll('.nav-item, .nav-subitem').forEach(item => {
                item.addEventListener('click', function() {
                    // 移除所有active类
                    document.querySelectorAll('.nav-item.active, .nav-subitem.active').forEach(el => {
                        el.classList.remove('active');
                    });

                    // 为当前项添加active类
                    this.classList.add('active');

                    // 如果点击的是主菜单项，激活其第一个子项
                    if (this.classList.contains('nav-item')) {
                        const nextSibling = this.nextElementSibling;
                        if (nextSibling && nextSibling.classList.contains('nav-subitem')) {
                            nextSibling.classList.add('active');
                        }
                    }
                });
            });
        });
    </script>
</body>
</html>
