        // 获取质量等级
        function getQualityLevel(score) {
            if (score >= 90) return { level: "excellent", label: "优秀", color: "#52c41a" };
            if (score >= 80) return { level: "good", label: "良好", color: "#73d13d" };
            if (score >= 70) return { level: "fair", label: "一般", color: "#faad14" };
            if (score >= 60) return { level: "poor", label: "较差", color: "#ff7a45" };
            return { level: "bad", label: "差", color: "#ff4d4f" };
        }

        // 获取状态图标
        function getStatusIcon(status) {
            if (status === "normal") return "fas fa-check-circle";
            if (status === "warning") return "fas fa-exclamation-triangle";
            return "fas fa-times-circle";
        }

        // 获取趋势图标
        function getTrendIcon(trend) {
            if (trend === "up") return "fas fa-arrow-up";
            if (trend === "down") return "fas fa-arrow-down";
            return "fas fa-minus";
        }

