                                <span class="metric-unit">分</span>
                                <div class="metric-trend ${stream.qualityTrend}">
                                    <i class="${getTrendIcon(stream.qualityTrend)}"></i>
                                    <span>${qualityLevel.label}</span>
                                </div>
                            </div>
