                    </td>
                    <td>
                        <div>
                            <span class="metric-value">${stream.stutter}</span>
                            <span class="metric-unit">次/分钟</span>
                            <div class="metric-trend ${stream.stutterTrend}">
                                <i class="${getTrendIcon(stream.stutterTrend)}"></i>
                            </div>
                        </div>
                    </td>
                    <td>
                        <div>
                            <span class="metric-value">${stream.packetLoss}</span>
                            <span class="metric-unit">%</span>
                            <div class="metric-trend ${stream.packetLossTrend}">
                                <i class="${getTrendIcon(stream.packetLossTrend)}"></i>
                            </div>
                        </div>
                    </td>
                    <td>
                        <div>
                            <span class="metric-value">${stream.latency}</span>
                            <span class="metric-unit">ms</span>
                            <div class="metric-trend ${stream.latencyTrend}">
                                <i class="${getTrendIcon(stream.latencyTrend)}"></i>
                            </div>
                        </div>
                    </td>
                    <td>
                        <span class="status-badge status-${stream.status}">
                            ${stream.status === 'normal' ? '正常' : stream.status === 'warning' ? '警告' : '异常'}
                        </span>
                    </td>
                    <td>
                        <div class="action-buttons">
                            <button class="action-btn" title="查看详情" onclick="viewStreamDetails(${stream.id})">
                                <i class="fas fa-eye"></i>
                            </button>
                            <button class="action-btn" title="调阅视频" onclick="viewStreamVideo(${stream.id})">
                                <i class="fas fa-play"></i>
                            </button>
                            <button class="action-btn" title="诊断修复" onclick="diagnoseStream(${stream.id})">
                                <i class="fas fa-stethoscope"></i>
                            </button>
                        </div>
                    </td>
                `;

                tableBody.appendChild(row);
            });
        }

        // 更新统计数据
        function updateStatistics() {
            const totalStreams = videoStreams.length;
            const normalStreams = videoStreams.filter(s => s.status === 'normal').length;
            const avgQualityScore = (videoStreams.reduce((sum, s) => sum + s.qualityScore, 0) / totalStreams).toFixed(1);
            const avgBitrate = (videoStreams.reduce((sum, s) => sum + s.bitrate, 0) / totalStreams).toFixed(1);
            const avgLatency = Math.round(videoStreams.reduce((sum, s) => sum + s.latency, 0) / totalStreams);

            document.getElementById('avgQualityScore').textContent = avgQualityScore;
            document.getElementById('qualityProgress').style.width = `${avgQualityScore}%`;

            document.getElementById('normalStreams').textContent = normalStreams;
            document.getElementById('streamProgress').style.width = `${(normalStreams / totalStreams * 100).toFixed(1)}%`;

            document.getElementById('avgBitrate').textContent = avgBitrate;
            document.getElementById('bitrateProgress').style.width = `${(avgBitrate / 4.0 * 100).toFixed(1)}%`;

            document.getElementById('avgLatency').textContent = avgLatency;
            document.getElementById('latencyProgress').style.width = `${(100 - (avgLatency / 500 * 100)).toFixed(1)}%`;
        }

        // 初始化图表
        let qualityChart;
        function initCharts() {
            const ctx = document.getElementById('qualityChart').getContext('2d');

            // 生成过去24小时的数据
            const labels = [];
            const qualityData = [];
            const bitrateData = [];
            const framerateData = [];
            const latencyData = [];

            // 当前时间
            const now = new Date();

            // 生成24个时间点（每小时一个）
            for (let i = 23; i >= 0; i--) {
                const time = new Date(now.getTime() - i * 60 * 60 * 1000);
                const hour = time.getHours();
                labels.push(`${hour}:00`);

                // 生成模拟数据
                const baseQuality = 85 + Math.random() * 10;
                qualityData.push(baseQuality + Math.random() * 5 - 2.5);

                const baseBitrate = 3.5 + Math.random() * 1;
                bitrateData.push(baseBitrate + Math.random() * 0.5 - 0.25);

                const baseFramerate = 23 + Math.random() * 4;
                framerateData.push(baseFramerate + Math.random() * 2 - 1);

                const baseLatency = 150 + Math.random() * 50;
                latencyData.push(baseLatency + Math.random() * 30 - 15);
            }

            qualityChart = new Chart(ctx, {
                type: 'line',
                data: {
                    labels: labels,
                    datasets: [{
                        label: '质量评分',
                        data: qualityData,
                        borderColor: '#1890ff',
                        backgroundColor: 'rgba(24, 144, 255, 0.1)',
                        borderWidth: 2,
                        fill: true,
                        tension: 0.4
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: {
                        legend: {
                            display: true,
                            position: 'top',
                        },
                        tooltip: {
                            mode: 'index',
                            intersect: false
                        }
                    },
                    scales: {
                        y: {
                            beginAtZero: false,
                            min: 60,
                            max: 100,
                            title: {
                                display: true,
                                text: '质量评分'
                            }
                        },
                        x: {
                            grid: {
                                display: false
                            }
                        }
                    },
                    interaction: {
                        intersect: false,
                        mode: 'nearest'
                    }
                }
            });

            // 存储数据用于切换
            window.chartData = {
                quality: qualityData,
                bitrate: bitrateData,
                framerate: framerateData,
                latency: latencyData
            };
        }

        // 切换图表数据
        function switchChart(type) {
            const chartTypes = {
                quality: {
                    label: '质量评分',
                    color: '#1890ff',
                    min: 60,
                    max: 100,
                    unit: '分'
                },
                bitrate: {
                    label: '码率',
                    color: '#fa8c16',
                    min: 2,
                    max: 5,
                    unit: 'Mbps'
                },
                framerate: {
                    label: '帧率',
                    color: '#52c41a',
                    min: 15,
                    max: 30,
                    unit: 'fps'
                },
                latency: {
                    label: '延迟',
                    color: '#ff4d4f',
                    min: 100,
                    max: 350,
                    unit: 'ms'
                }
            };

            const chartType = chartTypes[type];
            qualityChart.data.datasets[0].label = chartType.label;
            qualityChart.data.datasets[0].data = window.chartData[type];
            qualityChart.data.datasets[0].borderColor = chartType.color;
            qualityChart.data.datasets[0].backgroundColor = `${chartType.color}20`;

            qualityChart.options.scales.y.min = chartType.min;
            qualityChart.options.scales.y.max = chartType.max;
            qualityChart.options.scales.y.title.text = chartType.label;

            qualityChart.update();

            // 更新按钮状态
            document.querySelectorAll('.chart-control-btn').forEach(btn => {
                btn.classList.remove('active');
            });
            event.target.classList.add('active');
        }

        // 过滤视频流
        function filterStreams() {
            const qualityFilter = document.getElementById('qualityFilter').value;
            const statusFilter = document.getElementById('statusFilter').value;
            const locationFilter = document.getElementById('locationFilter').value;

            let filteredStreams = videoStreams;

            // 按质量过滤
            if (qualityFilter !== 'all') {
                filteredStreams = filteredStreams.filter(stream => {
                    const qualityLevel = getQualityLevel(stream.qualityScore).level;
                    return qualityLevel === qualityFilter;
                });
            }

            // 按状态过滤
            if (statusFilter !== 'all') {
                filteredStreams = filteredStreams.filter(stream => stream.status === statusFilter);
            }

            // 按位置过滤
            if (locationFilter !== 'all') {
                filteredStreams = filteredStreams.filter(stream => {
                    if (locationFilter === 'intersectionA') return stream.location.includes('路口A');
                    if (locationFilter === 'intersectionB') return stream.location.includes('路口B');
                    if (locationFilter === 'intersectionC') return stream.location.includes('路口C');
                    if (locationFilter === 'intersectionD') return stream.location.includes('路口D');
                    return true;
                });
            }

            renderStreamTable(filteredStreams);
        }

        // 查看视频流详情
        function viewStreamDetails(id) {
            const stream = videoStreams.find(s => s.id === id);
            if (stream) {
                alert(`视频流详情:\n\n名称: ${stream.name}\n位置: ${stream.location}\n协议: ${stream.protocol}\n分辨率: ${stream.resolution}\n质量评分: ${stream.qualityScore}\n码率: ${stream.bitrate} Mbps\n帧率: ${stream.framerate} fps\n卡顿: ${stream.stutter} 次/分钟\n丢包率: ${stream.packetLoss}%\n延迟: ${stream.latency} ms\n状态: ${stream.status === 'normal' ? '正常' : stream.status === 'warning' ? '警告' : '异常'}`);
            }
        }

        // 调阅视频
        function viewStreamVideo(id) {
            alert(`正在打开视频流 ${id} 的实时画面...\n\n注意: 此功能需要安装视频播放插件，或跳转到视频播放页面。`);
        }

        // 诊断修复
        function diagnoseStream(id) {
            const stream = videoStreams.find(s => s.id === id);
            if (stream) {
                alert(`正在对视频流 "${stream.name}" 进行诊断...\n\n诊断建议:\n${stream.status === 'error' ? '1. 检查网络连接\n2. 重启视频编码器\n3. 检查电源供应' : stream.status === 'warning' ? '1. 优化网络带宽\n2. 调整视频编码参数\n3. 检查存储空间' : '视频流状态正常，无需修复'}`);
            }
        }

        // 刷新数据
        function refreshData() {
            // 模拟数据更新
            videoStreams.forEach(stream => {
                // 随机更新一些指标
                if (Math.random() > 0.7) {
                    stream.qualityScore = Math.max(50, Math.min(100, stream.qualityScore + (Math.random() * 6 - 3)));
                }
                if (Math.random() > 0.7) {
                    stream.bitrate = Math.max(1.0, Math.min(5.0, stream.bitrate + (Math.random() * 0.6 - 0.3)));
                }
                if (Math.random() > 0.7) {
                    stream.latency = Math.max(80, Math.min(400, stream.latency + (Math.random() * 40 - 20)));
                }

                // 更新状态
                if (stream.qualityScore < 60) {
                    stream.status = 'error';
                } else if (stream.qualityScore < 75) {
                    stream.status = 'warning';
                } else {
                    stream.status = 'normal';
                }

                // 更新趋势
                const trends = ['up', 'down', 'stable'];
                stream.qualityTrend = trends[Math.floor(Math.random() * 3)];
                stream.bitrateTrend = trends[Math.floor(Math.random() * 3)];
                stream.latencyTrend = trends[Math.floor(Math.random() * 3)];
            });

            // 重新渲染
            renderStreamTable(videoStreams);
            updateStatistics();

            // 显示刷新提示
            const refreshBtn = document.getElementById('refreshBtn');
            const originalText = refreshBtn.innerHTML;
            refreshBtn.innerHTML = '<i class="fas fa-check"></i> 数据已更新';
            refreshBtn.disabled = true;

            setTimeout(() => {
                refreshBtn.innerHTML = originalText;
                refreshBtn.disabled = false;
            }, 2000);
        }

        // 阈值设置
        function showThresholdSettings() {
            alert('视频流质量阈值设置:\n\n优秀: ≥90分\n良好: 80-89分\n一般: 70-79分\n较差: 60-69分\n差: <60分\n\n码率阈值: ≥2.0 Mbps\n帧率阈值: ≥20 fps\n卡顿阈值: ≤5次/分钟\n丢包率阈值: ≤1.0%\n延迟阈值: ≤200 ms');
        }

        // 初始化页面
        document.addEventListener('DOMContentLoaded', function() {
            // 渲染初始数据
            renderStreamTable(videoStreams);
            updateStatistics();
            initCharts();

            // 绑定事件
            document.getElementById('refreshBtn').addEventListener('click', refreshData);
            document.getElementById('thresholdBtn').addEventListener('click', showThresholdSettings);

            // 绑定图表切换事件
            document.querySelectorAll('.chart-control-btn').forEach(btn => {
                btn.addEventListener('click', function() {
                    switchChart(this.dataset.chart);
                });
            });

            // 绑定筛选事件
            document.getElementById('qualityFilter').addEventListener('change', filterStreams);
            document.getElementById('statusFilter').addEventListener('change', filterStreams);
            document.getElementById('locationFilter').addEventListener('change', filterStreams);

            // 导航菜单点击事件
            document.querySelectorAll('.nav-item, .nav-subitem').forEach(item => {
                item.addEventListener('click', function() {
                    // 移除所有active类
                    document.querySelectorAll('.nav-item.active, .nav-subitem.active').forEach(el => {
                        el.classList.remove('active');
                    });

                    // 为当前项添加active类
                    this.classList.add('active');

                    // 如果点击的是主菜单项，激活其第一个子项
                    if (this.classList.contains('nav-item')) {
                        const nextSibling = this.nextElementSibling;
                        if (nextSibling && nextSibling.classList.contains('nav-subitem')) {
                            nextSibling.classList.add('active');
                        }
                    }
                });
            });

            // 模拟实时更新
            setInterval(() => {
                // 随机更新一个视频流的数据
                if (videoStreams.length > 0) {
                    const randomIndex = Math.floor(Math.random() * videoStreams.length);
                    const stream = videoStreams[randomIndex];

                    // 小幅更新质量评分
                    stream.qualityScore = Math.max(50, Math.min(100, stream.qualityScore + (Math.random() * 2 - 1)));

                    // 更新状态
                    if (stream.qualityScore < 60) {
                        stream.status = 'error';
                    } else if (stream.qualityScore < 75) {
                        stream.status = 'warning';
                    } else {
                        stream.status = 'normal';
                    }

                    // 重新渲染该行
                    renderStreamTable(videoStreams);
                    updateStatistics();
                }
            }, 10000); // 每10秒更新一次
        });
    </script>
</body>
</html>
```

这个HTML页面实现了视频流质量监测功能，包含以下特性：

1. **实时监控仪表盘**：显示平均质量评分、正常视频流数量、平均码率和平均延迟等关键指标

2. **质量趋势图表**：使用Chart.js展示过去24小时视频流质量趋势，支持切换查看码率、帧率和延迟等不同指标

3. **详细视频流列表**：展示每个视频流的详细质量指标，包括：
   - 质量评分（按颜色区分等级：优秀/良好/一般/较差/差）
   - 码率（Mbps）
   - 帧率（fps）
   - 卡顿次数（次/分钟）
   - 丢包率（%）
   - 延迟（ms）
   - 当前状态（正常/警告/异常）

4. **交互功能**：
   - 数据筛选：按质量等级、状态和路口位置筛选视频流
   - 刷新数据：模拟实时数据更新
   - 阈值设置：查看质量阈值配置
   - 操作按钮：查看详情、调阅视频、诊断修复

5. **模拟数据更新**：页面包含定时更新功能，模拟真实监控系统的数据变化

6. **响应式设计**：适配不同屏幕尺寸，在移动设备上自动调整布局

页面展示了中软国际开源鸿蒙交通路口管理平台对视频流质量的全面监控能力，帮助运维人员及时发现和解决视频质量问题。

