    <script>
        // 初始化地图
        const map = L.map('map').setView([31.2304, 121.4737], 16); // 上海坐标

        // 添加地图图层
        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
            attribution: '© OpenStreetMap contributors'
        }).addTo(map);

        // 自定义图标
        const cameraIcon = L.divIcon({
            html: '<div style="background-color: #1890ff; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; color: white; font-size: 14px; border: 2px solid white; box-shadow: 0 2px 6px rgba(0,0,0,0.3);"><i class="fas fa-video"></i></div>',
            className: 'custom-marker',
            iconSize: [32, 32],
            iconAnchor: [16, 16]
        });

        const cameraIconWarning = L.divIcon({
            html: '<div style="background-color: #faad14; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; color: white; font-size: 14px; border: 2px solid white; box-shadow: 0 2px 6px rgba(0,0,0,0.3);"><i class="fas fa-video"></i></div>',
            className: 'custom-marker',
            iconSize: [32, 32],
            iconAnchor: [16, 16]
        });

        const cameraIconOffline = L.divIcon({
            html: '<div style="background-color: #8c8c8c; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; color: white; font-size: 14px; border: 2px solid white; box-shadow: 0 2px 6px rgba(0,0,0,0.3);"><i class="fas fa-video"></i></div>',
            className: 'custom-marker',
            iconSize: [32, 32],
            iconAnchor: [16, 16]
        });

        // 摄像头数据
        const cameras = [
            {
                id: "cam-001",
                name: "智能摄像机-01",
                type: "鸿蒙摄像头",
                status: "online",
                lat: 31.2312,
                lng: 121.4745,
                icon: cameraIcon,
                details: "设备ID: CAM-001-2025<br>厂商: 海康威视<br>视频流: RTSP/H.265<br>分辨率: 4K (3840×2160)<br>帧率: 30 fps<br>视角: 东进口主视角",
                streamUrl: "https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4"
            },
            {
                id: "cam-003",
                name: "智能摄像机-03",
                type: "鸿蒙摄像头",
                status: "online",
                lat: 31.2298,
                lng: 121.4748,
                icon: cameraIcon,
                details: "设备ID: CAM-003-2025<br>厂商: 大华股份<br>视频流: RTSP/H.264<br>分辨率: 全景 360°<br>帧率: 25 fps<br>视角: 北出口全景",
                streamUrl: "https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ElephantsDream.mp4"
            },
            {
                id: "cam-005",
                name: "电子警察-02",
                type: "鸿蒙化交通卡口",
                status: "warning",
                lat: 31.2309,
                lng: 121.4732,
                icon: cameraIconWarning,
                details: "设备ID: EP-002-2025<br>厂商: 佳都科技<br>视频流: RTSP/H.264<br>分辨率: 1080P<br>帧率: 25 fps<br>状态: 码率波动异常",
                streamUrl: "https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerBlazes.mp4"
            },
            {
                id: "cam-007",
                name: "雷视一体机-01",
                type: "鸿蒙雷视一体机",
                status: "online",
                lat: 31.2305,
                lng: 121.4738,
                icon: cameraIcon,
                details: "设备ID: RV-001-2025<br>厂商: 佳都科技<br>视频流: RTSP/H.265<br>分辨率: 1080P<br>帧率: 30 fps<br>功能: 车流检测+视频",
                streamUrl: "https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerEscapes.mp4"
            },
            {
                id: "cam-009",
                name: "人行横道监控-01",
                type: "标准摄像头",
                status: "online",
                lat: 31.2295,
                lng: 121.4735,
                icon: cameraIcon,
                details: "设备ID: CAM-009-2024<br>厂商: 宇视科技<br>视频流: RTSP/H.264<br>分辨率: 1080P<br>帧率: 20 fps<br>功能: 行人检测",
                streamUrl: "https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerFun.mp4"
            },
            {
                id: "cam-011",
                name: "立交桥高空监控",
                type: "老旧监控设备",
                status: "offline",
                lat: 31.2315,
                lng: 121.473,
                icon: cameraIconOffline,
                details: "设备ID: CAM-011-2018<br>厂商: 传统设备<br>状态: 离线<br>最后在线: 2025-03-14 18:22:10<br>故障原因: 网络中断",
                streamUrl: null
            }
        ];

        // 在地图上添加摄像头标记
        cameras.forEach(camera => {
            const marker = L.marker([camera.lat, camera.lng], { 
                icon: camera.icon,
                cameraId: camera.id
            })
            .addTo(map)
            .bindPopup(`
                <div class="marker-popup">
                    <div class="popup-title">${camera.name}</div>
                    <div class="popup-info">类型: ${camera.type}</div>
                    <div class="popup-info">位置: 路口A</div>
                    <div class="popup-info">${camera.details}</div>
                    <div class="popup-status ${camera.status === 'online' ? 'status-online' : camera.status === 'offline' ? 'status-offline' : 'status-warning'}">
                        ${camera.status === 'online' ? '在线' : camera.status === 'offline' ? '离线' : '警告'}
                    </div>
                    <div class="popup-actions">
                        ${camera.status !== 'offline' ? 
                            `<button class="popup-btn primary view-video-btn" data-camera-id="${camera.id}">
