            // 为标记添加点击事件
            marker.on('click', function() {
                if (camera.status !== 'offline') {
                    // 显示视频缩略图
                    const thumbnail = document.getElementById('videoThumbnail');
                    const thumbnailVideo = document.getElementById('thumbnailVideo');

                    // 更新缩略图位置
                    const point = map.latLngToContainerPoint(marker.getLatLng());
                    thumbnail.style.left = (point.x - 200 + 10) + 'px';
                    thumbnail.style.bottom = (map.getSize().y - point.y + 10) + 'px';

                    // 更新视频源
                    thumbnailVideo.src = camera.streamUrl;
                    thumbnailVideo.load();

                    // 显示缩略图
                    thumbnail.classList.add('active');

                    // 更新标题
                    document.querySelector('.thumbnail-header span').textContent = `${camera.name} - 实时预览`;
                }
            });
        });

        // 绘制路口区域（示例）
        const intersectionBounds = [
            [31.2318, 121.4725],
            [31.2318, 121.4755],
            [31.2292, 121.4755],
            [31.2292, 121.4725]
        ];

        const intersectionArea = L.polygon(intersectionBounds, {
            color: '#1890ff',
            weight: 2,
            fillColor: '#e6f7ff',
            fillOpacity: 0.1
        }).addTo(map);

        // 绘制车道线（示例）
        const laneLines = [
            [[31.2312, 121.473], [31.2312, 121.4748]],
            [[31.2308, 121.473], [31.2308, 121.4748]],
            [[31.2304, 121.473], [31.2304, 121.4748]],
            [[31.231, 121.4735], [31.2298, 121.4735]],
            [[31.231, 121.474], [31.2298, 121.474]],
            [[31.231, 121.4743], [31.2298, 121.4743]]
        ];

        laneLines.forEach(line => {
            L.polyline(line, {
                color: '#8c8c8c',
                weight: 2,
                opacity: 0.7
            }).addTo(map);
        });

        // 视频播放器功能
        const videoModal = document.getElementById('videoModal');
        const mainVideoPlayer = document.getElementById('mainVideoPlayer');
        const closeVideoBtn = document.getElementById('closeVideoBtn');
        const playPauseBtn = document.getElementById('playPauseBtn');
        const videoTime = document.getElementById('videoTime');
        const videoProgress = document.getElementById('videoProgress');
        const videoProgressFilled = document.getElementById('videoProgressFilled');
        const videoTitle = document.getElementById('videoTitle');
        const thumbnail = document.getElementById('videoThumbnail');
        const thumbnailVideo = document.getElementById('thumbnailVideo');
        const closeThumbnailBtn = document.getElementById('closeThumbnailBtn');
        const toggleThumbnailBtn = document.getElementById('toggleThumbnailBtn');

        // 当前播放的摄像头
        let currentCamera = cameras[0];

        // 打开视频播放器
        function openVideoPlayer(cameraId) {
            const camera = cameras.find(c => c.id === cameraId);
            if (!camera || camera.status === 'offline') return;

            currentCamera = camera;

            // 更新视频标题
            videoTitle.textContent = `${camera.name} - 实时视频流`;

            // 更新视频源
            mainVideoPlayer.src = camera.streamUrl;
            mainVideoPlayer.load();
            mainVideoPlayer.play();

            // 更新侧边栏摄像头列表激活状态
            document.querySelectorAll('.camera-item').forEach(item => {
                item.classList.remove('active');
                if (item.getAttribute('data-camera-id') === cameraId) {
                    item.classList.add('active');
                }
            });

            // 显示视频播放器
            videoModal.classList.add('active');

            // 隐藏缩略图
            thumbnail.classList.remove('active');
        }

        // 关闭视频播放器
        function closeVideoPlayer() {
            videoModal.classList.remove('active');
            mainVideoPlayer.pause();
        }

        // 关闭缩略图
        function closeThumbnail() {
            thumbnail.classList.remove('active');
            thumbnailVideo.pause();
        }

        // 切换缩略图显示
        function toggleThumbnail() {
            if (thumbnail.classList.contains('active')) {
                closeThumbnail();
            } else {
                // 如果有摄像头被选中，显示缩略图
                if (currentCamera) {
                    thumbnailVideo.src = currentCamera.streamUrl;
                    thumbnailVideo.load();
                    thumbnailVideo.play();
                    thumbnail.classList.add('active');
                }
            }
        }

        // 更新视频时间显示
        function updateVideoTime() {
            const currentTime = formatTime(mainVideoPlayer.currentTime);
            const duration = formatTime(mainVideoPlayer.duration);
            videoTime.textContent = `${currentTime} / ${duration}`;

            // 更新进度条
            const progressPercent = (mainVideoPlayer.currentTime / mainVideoPlayer.duration) * 100;
            videoProgressFilled.style.width = `${progressPercent}%`;
        }

        // 格式化时间 (秒 -> mm:ss)
        function formatTime(seconds) {
            if (isNaN(seconds)) return "00:00";
            const mins = Math.floor(seconds / 60);
            const secs = Math.floor(seconds % 60);
            return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
        }

        // 切换播放/暂停
        function togglePlayPause() {
            if (mainVideoPlayer.paused) {
                mainVideoPlayer.play();
                playPauseBtn.innerHTML = '<i class="fas fa-pause"></i>';
            } else {
                mainVideoPlayer.pause();
                playPauseBtn.innerHTML = '<i class="fas fa-play"></i>';
            }
        }

        // 点击进度条跳转
        function seekVideo(e) {
            const rect = videoProgress.getBoundingClientRect();
            const percent = (e.clientX - rect.left) / rect.width;
            mainVideoPlayer.currentTime = percent * mainVideoPlayer.duration;
        }

        // 事件监听
        closeVideoBtn.addEventListener('click', closeVideoPlayer);
        closeThumbnailBtn.addEventListener('click', closeThumbnail);
        toggleThumbnailBtn.addEventListener('click', toggleThumbnail);
        playPauseBtn.addEventListener('click', togglePlayPause);

        mainVideoPlayer.addEventListener('timeupdate', updateVideoTime);
        mainVideoPlayer.addEventListener('play', () => {
            playPauseBtn.innerHTML = '<i class="fas fa-pause"></i>';
        });
        mainVideoPlayer.addEventListener('pause', () => {
            playPauseBtn.innerHTML = '<i class="fas fa-play"></i>';
        });

        videoProgress.addEventListener('click', seekVideo);

        // 点击查看视频按钮
        document.querySelectorAll('.view-video-btn').forEach(btn => {
            btn.addEventListener('click', function() {
                const cameraId = this.getAttribute('data-camera-id');
                openVideoPlayer(cameraId);
            });
        });

        // 侧边栏摄像头列表点击事件
        document.querySelectorAll('.camera-item').forEach(item => {
            item.addEventListener('click', function() {
                const cameraId = this.getAttribute('data-camera-id');
                openVideoPlayer(cameraId);
            });
        });

        // 地图控件功能
        document.querySelectorAll('.map-tool-btn').forEach((btn, index) => {
            btn.addEventListener('click', function() {
                switch(index) {
                    case 0: // 放大
                        map.zoomIn();
                        break;
                    case 1: // 缩小
                        map.zoomOut();
                        break;
                    case 2: // 重置视图
                        map.setView([31.2304, 121.4737], 16);
                        break;
                    case 3: // 筛选摄像头
                        alert('摄像头筛选功能：可按照状态、类型筛选显示');
                        break;
                }
            });
        });

        // 点击地图其他区域关闭缩略图
        map.on('click', function(e) {
            // 检查点击的是否是标记
            const markerClicked = e.originalEvent.target.closest('.leaflet-marker-icon');
            if (!markerClicked) {
                closeThumbnail();
            }
        });

        // 模拟视频数据更新
        function updateVideoStats() {
            // 随机更新一些数据
            const cards = document.querySelectorAll('.card-value');
            if (cards.length >= 4) {
                // 更新正常通道数
                const normalChannels = Math.floor(Math.random() * 3) + 40;
                cards[1].textContent = normalChannels;

                // 更新实时带宽
                const bandwidth = (Math.random() * 10 + 80).toFixed(1);
                cards[2].textContent = bandwidth + ' Mbps';

                // 更新视频异常数
                const abnormal = 48 - normalChannels;
                cards[3].textContent = abnormal;
            }

            // 更新视频质量数据
            const dataValues = document.querySelectorAll('.data-value');
            if (dataValues.length >= 6) {
                // 平均帧率
                const fps = (Math.random() * 2 + 23.5).toFixed(1);
                dataValues[0].textContent = fps;

                // 平均码率
                const bitrate = (Math.random() * 0.5 + 1.9).toFixed(1);
                dataValues[1].textContent = bitrate + ' Mbps';

                // 视频可用率
                const availability = (Math.random() * 1 + 96).toFixed(1);
                dataValues[2].textContent = availability + '%';

                // 平均延迟
                const latency = Math.floor(Math.random() * 30 + 140);
                dataValues[3].textContent = latency + ' ms';

                // 平均丢包率
                const packetLoss = (Math.random() * 0.3 + 0.7).toFixed(1);
                dataValues[4].textContent = packetLoss + '%';

                // 平均质量评分
                const quality = Math.floor(Math.random() * 5 + 86);
                dataValues[5].textContent = quality;
            }
        }

        // 每10秒更新一次数据
        setInterval(updateVideoStats, 10000);

        // 导航菜单点击事件
        document.querySelectorAll('.nav-item, .nav-subitem').forEach(item => {
            item.addEventListener('click', function() {
                // 移除所有active类
                document.querySelectorAll('.nav-item.active, .nav-subitem.active').forEach(el => {
                    el.classList.remove('active');
                });

                // 为当前项添加active类
                this.classList.add('active');

                // 如果点击的是主菜单项，激活其第一个子项
                if (this.classList.contains('nav-item')) {
                    const nextSibling = this.nextElementSibling;
                    if (nextSibling && nextSibling.classList.contains('nav-subitem')) {
                        nextSibling.classList.add('active');
                    }
                }
            });
        });

        // 初始打开第一个摄像头的视频
        setTimeout(() => {
            openVideoPlayer('cam-001');
        }, 1000);
    </script>
</body>
</html>
```

## 功能说明

这个HTML页面实现了"地图实时视频"功能，具有以下特性：

### 1. **地图交互功能**
- 地图显示路口区域和车道线
- 摄像头设备在地图上以不同颜色标记（蓝色-在线，黄色-警告，灰色-离线）
- 点击摄像头标记显示设备信息和"查看实时视频"按钮

### 2. **视频播放功能**
- 全屏视频播放器，支持播放控制（播放/暂停、音量、全屏）
- 实时显示视频流状态（码率、帧率、分辨率、延迟、丢包率、质量评分）
- 侧边栏显示其他摄像头列表，可快速切换

### 3. **实时数据展示**
- 顶部数据卡片显示视频通道总数、正常通道、实时带宽、异常数量
- 视频质量监控面板显示平均帧率、码率、可用率、延迟、丢包率、质量评分
- 数据动态更新，模拟实时变化

### 4. **摄像头设备管理**
- 摄像头设备列表显示设备名称、类型、位置和状态
- 每个设备提供"查看视频"和"详情"按钮
- 设备状态以颜色区分（绿色-在线，黄色-警告，灰色-离线）

### 5. **用户体验优化**
- 地图上的视频缩略图预览功能
- 响应式设计，适配不同屏幕尺寸
- 直观的UI界面，符合交通管理系统的专业需求

### 6. **鸿蒙特色功能**
- 支持鸿蒙设备（摄像头、雷视一体机等）的视频流接入
- 显示设备厂商信息（海康威视、大华股份、佳都科技等）
- 支持多种视频流协议（RTSP/H.264，RTSP/H.265）

这个页面模拟了一个完整的交通路口视频监控系统，用户可以通过地图直观地查看摄像头位置，并实时观看各个摄像头的视频流，同时监控视频质量状态。

