            channelsTableBody.innerHTML = '';

            // 获取筛选条件
            const statusFilterValue = statusFilter.value;
            const typeFilterValue = typeFilter.value;
            const searchValue = searchInput.value.toLowerCase();

            // 筛选通道
            let filteredChannels = videoChannels.filter(channel => {
                // 状态筛选
                if (statusFilterValue && channel.status !== statusFilterValue) {
                    return false;
                }

                // 类型筛选
                if (typeFilterValue && channel.type !== typeFilterValue) {
                    return false;
                }

                // 搜索筛选
                if (searchValue) {
                    const searchText = `${channel.name} ${channel.location} ${channel.manufacturer}`.toLowerCase();
                    if (!searchText.includes(searchValue)) {
                        return false;
                    }
                }

                return true;
            });

            // 渲染通道行
