        // 获取信号强度条
        function getSignalBars(strength) {
            let bars = '';
            const barCount = 5;

            for (let i = 1; i <= barCount; i++) {
                let barClass = 'signal-bar';
                const threshold = i * 20;

                if (strength >= threshold) {
                    if (strength >= 80) {
                        barClass += ' active';
                    } else if (strength >= 60) {
                        barClass += ' warning';
                    } else {
                        barClass += ' error';
                    }
                }

                bars += `<div class="${barClass}"></div>`;
            }

            return bars;
        }

        // 获取质量评分指示器
        function getQualityIndicator(score) {
            let qualityClass = '';

            if (score >= 90) {
                qualityClass = 'quality-excellent';
            } else if (score >= 80) {
                qualityClass = 'quality-good';
            } else if (score >= 70) {
                qualityClass = 'quality-fair';
            } else if (score >= 60) {
                qualityClass = 'quality-poor';
            } else {
                qualityClass = 'quality-bad';
            }

            return `<div class="quality-dot ${qualityClass}"></div>`;
        }

