        // 重启通道
        function restartChannel(channelId) {
            const channel = videoChannels.find(ch => ch.id === channelId);

            if (!channel) return;

            // 模拟重启过程
            if (confirm(`确定要重启设备 "${channel.name}" 吗？`)) {
                // 显示加载状态
                const restartBtn = document.querySelector(`.restart-btn[data-channel-id="${channelId}"]`);
                const originalHTML = restartBtn.innerHTML;
                restartBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> 重启中...';
                restartBtn.disabled = true;

                // 模拟重启延迟
                setTimeout(() => {
                    // 更新通道状态
                    channel.status = 'normal';
                    channel.signalStrength = 95;
                    channel.frameRate = 30;
                    channel.bitRate = 4.2;
                    channel.latency = 156;
                    channel.packetLoss = 0.2;
                    channel.qualityScore = 95;
                    channel.errorCode = null;
                    channel.errorMessage = null;
                    channel.retryCount = 0;
                    channel.lastCheckTime = new Date().toISOString().replace('T', ' ').substr(0, 19);

                    // 恢复按钮状态
                    restartBtn.innerHTML = originalHTML;
                    restartBtn.disabled = false;

                    // 更新表格
                    initChannelsTable();

                    // 显示成功消息
                    alert(`设备 "${channel.name}" 重启成功！`);
                }, 2000);
            }
        }

        // 刷新状态
        function refreshStatus() {
            // 显示加载状态
            refreshBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> 刷新中...';
            refreshBtn.disabled = true;

            // 模拟刷新延迟
            setTimeout(() => {
                // 随机更新一些通道的状态
                videoChannels.forEach(channel => {
                    if (channel.status !== 'offline' && Math.random() > 0.7) {
                        // 随机改变状态
                        if (Math.random() > 0.8) {
                            channel.status = 'warning';
                            channel.signalStrength = Math.floor(Math.random() * 30) + 50;
                            channel.frameRate = Math.floor(Math.random() * 10) + 15;
                            channel.bitRate = (Math.random() * 2 + 1).toFixed(1);
                            channel.latency = Math.floor(Math.random() * 200) + 200;
                            channel.packetLoss = (Math.random() * 3 + 1).toFixed(1);
                            channel.qualityScore = Math.floor(Math.random() * 20) + 60;
                            channel.errorCode = 'VIDEO_BITRATE_LOW';
                            channel.errorMessage = '码率低于阈值';
                        } else {
                            channel.status = 'normal';
                            channel.signalStrength = Math.floor(Math.random() * 20) + 80;
                            channel.frameRate = Math.floor(Math.random() * 5) + 25;
                            channel.bitRate = (Math.random() * 1 + 3).toFixed(1);
                            channel.latency = Math.floor(Math.random() * 50) + 150;
                            channel.packetLoss = (Math.random() * 1).toFixed(1);
                            channel.qualityScore = Math.floor(Math.random() * 10) + 85;
                            channel.errorCode = null;
                            channel.errorMessage = null;
                        }

                        channel.lastCheckTime = new Date().toISOString().replace('T', ' ').substr(0, 19);
                    }
                });

                // 更新表格
                initChannelsTable();

                // 恢复按钮状态
                refreshBtn.innerHTML = '<i class="fas fa-sync-alt"></i> 刷新状态';
                refreshBtn.disabled = false;

                // 更新卡片数据
                updateDashboardCards();

                // 显示成功消息
                alert('状态刷新完成！');
            }, 1500);
        }

        // 更新仪表板卡片数据
        function updateDashboardCards() {
            // 计算各种状态的通道数量
            let normalCount = 0;
            let warningCount = 0;
            let errorCount = 0;
            let offlineCount = 0;

            videoChannels.forEach(channel => {
                switch(channel.status) {
                    case 'normal':
                        normalCount++;
                        break;
                    case 'warning':
                        warningCount++;
                        break;
                    case 'error':
                        errorCount++;
                        break;
                    case 'offline':
                        offlineCount++;
                        break;
                }
            });

            // 更新卡片显示
            const cardValues = document.querySelectorAll('.card-value');
            if (cardValues.length >= 4) {
                cardValues[1].textContent = normalCount;
                cardValues[2].textContent = warningCount + errorCount;
                cardValues[3].textContent = offlineCount;
            }
        }

