            alert(`时间范围已更改为: ${timeRangeFilter.options[timeRangeFilter.selectedIndex].text}`);
        });

        // 导航菜单点击事件
        document.querySelectorAll('.nav-item, .nav-subitem').forEach(item => {
            item.addEventListener('click', function() {
                // 移除所有active类
                document.querySelectorAll('.nav-item.active, .nav-subitem.active').forEach(el => {
                    el.classList.remove('active');
                });

                // 为当前项添加active类
                this.classList.add('active');

                // 如果点击的是主菜单项，激活其第一个子项
                if (this.classList.contains('nav-item')) {
                    const nextSibling = this.nextElementSibling;
                    if (nextSibling && nextSibling.classList.contains('nav-subitem')) {
                        nextSibling.classList.add('active');
                    }
                }
            });
        });

        // 点击模态框外部关闭模态框
        detailModal.addEventListener('click', (e) => {
            if (e.target === detailModal) {
                detailModal.classList.remove('active');
            }
        });

        // 初始化
        document.addEventListener('DOMContentLoaded', () => {
            initChannelsTable();
            updateDashboardCards();
        });
    </script>
</body>
</html>
```

## 功能说明

这个HTML页面实现了"视频通道状态"功能，具有以下特性：

### 1. **状态概览卡片**
- 视频通道总数：显示已接入平台的视频通道总数
- 正常通道：显示码率、帧率正常的视频流数量
- 异常通道：显示卡顿、掉线或质量异常的视频通道数量
- 离线通道：显示设备离线或网络中断的通道数量

### 2. **视频通道状态列表**
- 表格形式展示所有视频通道的详细状态信息
- 设备信息：包括设备名称、位置、厂商和设备图标
- 通道状态：用不同颜色的徽章标识状态（正常/异常/错误/离线）
- 信号强度：可视化信号强度条和百分比数值
- 视频参数：显示分辨率、视频格式、帧率和码率
- 质量评分：用颜色点表示质量等级和具体分数
- 最后检测时间：显示最近一次状态检测的时间
- 操作按钮：提供"详情"和"重启/预览"按钮

### 3. **视频质量监控概览**
- 关键质量指标：平均视频可用率、平均帧率、平均码率、平均延迟、平均丢包率、平均质量评分
- 趋势对比：显示各项指标与昨日/上周的对比变化
- 质量趋势图表区域：预留图表展示空间

### 4. **通道详情模态框**
- 基本信息：设备名称、类型、位置、厂商、型号、状态等
- 视频参数：视频格式、分辨率、帧率、码率、质量评分等
- 网络状态：信号强度、网络延迟、丢包率、IP地址、MAC地址、视频流地址
- 状态历史：显示最近的状态检测记录
- 操作记录：显示对该通道的历史操作记录

### 5. **交互功能**
- 筛选功能：按状态、类型筛选通道，支持关键字搜索
- 刷新状态：实时刷新所有通道的最新状态
- 导出报告：导出当前状态的报告（模拟功能）
- 重启设备：对离线设备执行重启操作
- 查看详情：点击通道行或详情按钮查看完整信息
- 分页导航：支持表格分页浏览

### 6. **鸿蒙特色功能**
- 支持多种鸿蒙设备类型：摄像头、雷视一体机、边缘计算设备
- 显示设备厂商信息：海康威视、大华股份、佳都科技、宇视科技、华为等
- 支持多种视频流协议：RTSP、HTTP-FLV等

这个页面提供了一个完整的视频通道状态监控解决方案，帮助运维人员实时了解所有视频通道的健康状况，快速定位和解决问题，确保交通监控系统的稳定运行。

