        function updatePhaseEditor(phase) {
            if (!phase) return;

            phaseNameInput.value = phase.name;
            phaseNumberInput.value = phase.number;

            // 更新颜色选择
            colorOptions.forEach(option => {
                option.classList.remove('active');
                if (option.getAttribute('data-color') === phase.color) {
                    option.classList.add('active');
                }
            });

            // 更新方向选择
            directionOptions.forEach(option => {
                option.classList.remove('active');
                if (option.getAttribute('data-direction') === phase.direction) {
                    option.classList.add('active');
                }
            });

            // 更新时长滑块
            greenDurationSlider.value = phase.greenDuration;
            greenDurationValue.textContent = phase.greenDuration;

            yellowDurationSlider.value = phase.yellowDuration;
            yellowDurationValue.textContent = phase.yellowDuration;

            // 更新其他输入
            minGreenTimeInput.value = phase.minGreenTime;
            maxGreenTimeInput.value = phase.maxGreenTime;
            allRedTimeInput.value = phase.allRedDuration;
            phasePriorityInput.value = phase.priority;

            // 更新编辑器标题
            document.querySelector('.editor-title').textContent = `相位 ${phase.number} - ${phase.name}`;
        }

        // 更新周期时间轴
        function updateCycleTimeline() {
            cycleTimeline.innerHTML = '';

            // 计算总周期时间
            const totalDuration = parseInt(cycleDurationSlider.value);
            totalCycleTime.textContent = totalDuration;
            cycleDurationValue.textContent = totalDuration;

            // 计算相位总时间（绿灯+黄灯+全红）
            const totalPhaseTime = phases.reduce((sum, phase) => {
                return sum + phase.greenDuration + phase.yellowDuration + phase.allRedDuration;
            }, 0);

            // 计算比例因子
            const scaleFactor = totalDuration / totalPhaseTime;

            let accumulatedWidth = 0;

            // 添加相位块到时间轴
            phases.forEach((phase, index) => {
                // 计算相位块宽度
                const greenWidth = (phase.greenDuration * scaleFactor / totalDuration) * 100;
                const yellowWidth = (phase.yellowDuration * scaleFactor / totalDuration) * 100;
                const allRedWidth = (phase.allRedDuration * scaleFactor / totalDuration) * 100;

                // 添加绿灯块
                const greenBlock = document.createElement('div');
                greenBlock.className = `timeline-phase green`;
                greenBlock.style.left = `${accumulatedWidth}%`;
                greenBlock.style.width = `${greenWidth}%`;
                greenBlock.innerHTML = `
                    <div>${phase.greenDuration}s</div>
                    <div class="phase-order">相位 ${phase.number}</div>
                `;
                cycleTimeline.appendChild(greenBlock);

                accumulatedWidth += greenWidth;

                // 添加黄灯块
                const yellowBlock = document.createElement('div');
                yellowBlock.className = `timeline-phase yellow`;
                yellowBlock.style.left = `${accumulatedWidth}%`;
                yellowBlock.style.width = `${yellowWidth}%`;
                yellowBlock.innerHTML = `
                    <div>${phase.yellowDuration}s</div>
                    <div class="phase-order">黄灯</div>
                `;
                cycleTimeline.appendChild(yellowBlock);

                accumulatedWidth += yellowWidth;

                // 添加全红块
                const allRedBlock = document.createElement('div');
                allRedBlock.className = `timeline-phase red`;
                allRedBlock.style.left = `${accumulatedWidth}%`;
                allRedBlock.style.width = `${allRedWidth}%`;
                allRedBlock.innerHTML = `
                    <div>${phase.allRedDuration}s</div>
                    <div class="phase-order">全红</div>
                `;
                cycleTimeline.appendChild(allRedBlock);

                accumulatedWidth += allRedWidth;
            });
        }

        // 更新相位列表项
        function updatePhaseList() {
            phaseItems.forEach(item => {
                const phaseId = item.getAttribute('data-phase-id');
                const phase = phases.find(p => p.id === phaseId);

                if (phase) {
                    const phaseNumber = item.querySelector('.phase-number');
                    const phaseName = item.querySelector('.phase-name');
                    const phaseDuration = item.querySelector('.phase-duration');

                    if (phaseNumber) phaseNumber.textContent = `相位 ${phase.number}`;
                    if (phaseName) phaseName.textContent = phase.name;
                    if (phaseDuration) phaseDuration.textContent = `${phase.greenDuration}秒`;
                }
            });
        }

        // 保存相位配置
        function savePhaseConfig() {
            const phaseId = currentPhase.id;
            const phaseIndex = phases.findIndex(p => p.id === phaseId);

            if (phaseIndex >= 0) {
                phases[phaseIndex] = {
                    ...phases[phaseIndex],
                    name: phaseNameInput.value,
                    color: document.querySelector('.color-option.active').getAttribute('data-color'),
                    direction: document.querySelector('.direction-option.active').getAttribute('data-direction'),
                    greenDuration: parseInt(greenDurationSlider.value),
                    yellowDuration: parseInt(yellowDurationSlider.value),
                    allRedDuration: parseInt(allRedTimeInput.value),
                    minGreenTime: parseInt(minGreenTimeInput.value),
                    maxGreenTime: parseInt(maxGreenTimeInput.value),
                    priority: parseInt(phasePriorityInput.value)
                };

                // 更新当前相位
                currentPhase = phases[phaseIndex];

                // 更新UI
                updatePhaseList();
                updateCycleTimeline();

                alert(`相位 ${currentPhase.number} 配置已保存`);
            }
        }

        // 启动模拟器
        function startSimulation() {
            if (simulationActive) return;

            simulationActive = true;
            simulationPaused = false;
            currentPhaseIndex = 0;

            // 设置第一个相位
            setSimulationPhase(0);

            // 启动定时器
            simulationInterval = setInterval(() => {
                if (!simulationPaused) {
                    countdown--;

                    // 更新倒计时显示
                    countdownTimer.textContent = countdown;

                    // 更新进度条
                    const currentPhase = phases[currentPhaseIndex];
                    const totalPhaseTime = currentPhase.greenDuration + currentPhase.yellowDuration + currentPhase.allRedDuration;
                    const progressPercent = (1 - (countdown / totalPhaseTime)) * 100;
                    phaseProgressBar.style.width = `${progressPercent}%`;

                    // 如果倒计时结束，切换到下一个相位
                    if (countdown <= 0) {
                        currentPhaseIndex = (currentPhaseIndex + 1) % phases.length;
                        setSimulationPhase(currentPhaseIndex);
                    }
                }
            }, 1000);

            startSimulationBtn.disabled = true;
            pauseSimulationBtn.disabled = false;
            stopSimulationBtn.disabled = false;

            alert('信号灯模拟已启动');
        }

        // 暂停模拟器
        function pauseSimulation() {
            simulationPaused = !simulationPaused;

            if (simulationPaused) {
                pauseSimulationBtn.innerHTML = '<i class="fas fa-play"></i> 继续模拟';
                alert('模拟已暂停');
            } else {
                pauseSimulationBtn.innerHTML = '<i class="fas fa-pause"></i> 暂停模拟';
                alert('模拟已继续');
            }
        }

        // 停止模拟器
        function stopSimulation() {
            simulationActive = false;
            simulationPaused = false;

            clearInterval(simulationInterval);

            // 重置显示
            setSimulationPhase(0, true);

            startSimulationBtn.disabled = false;
            pauseSimulationBtn.disabled = true;
            stopSimulationBtn.disabled = true;
            pauseSimulationBtn.innerHTML = '<i class="fas fa-pause"></i> 暂停模拟';

            alert('模拟已停止');
        }

        // 设置模拟器相位
        function setSimulationPhase(index, reset = false) {
            if (index >= 0 && index < phases.length) {
                currentPhaseIndex = index;
                const phase = phases[index];

                // 更新显示
                currentPhaseDisplay.className = `phase-display ${phase.color}`;
                currentPhaseDisplay.innerHTML = `
                    <div>相位 ${phase.number}</div>
                    <div>${phase.name}</div>
                `;

                // 设置倒计时
                countdown = reset ? phase.greenDuration : phase.greenDuration + phase.yellowDuration + phase.allRedDuration;
                countdownTimer.textContent = countdown;

                // 重置进度条
                phaseProgressBar.className = `phase-progress-bar ${phase.color}`;
                phaseProgressBar.style.width = reset ? '0%' : '0%';
            }
        }

        // 手动控制信号灯
        function openManualControl() {
            manualControlModal.classList.add('active');
        }

        // 执行手动控制
        function executeManualControl() {
            const controlMode = controlModeSelect.value;
            const duration = parseInt(document.getElementById('controlDuration').value);

            if (controlMode === 'single-phase') {
                const phaseId = document.getElementById('manualPhaseSelect').value;
                const phase = phases.find(p => p.id === phaseId);

                if (phase) {
                    // 停止模拟器
                    stopSimulation();

                    // 设置手动控制相位
                    currentPhaseDisplay.className = `phase-display ${phase.color}`;
                    currentPhaseDisplay.innerHTML = `
                        <div>手动控制</div>
                        <div>${phase.name}</div>
                    `;

                    // 设置倒计时
                    countdown = duration || 999;
                    countdownTimer.textContent = duration || '∞';

                    // 设置进度条
                    phaseProgressBar.className = `phase-progress-bar ${phase.color}`;
                    phaseProgressBar.style.width = '100%';

                    alert(`已切换到手动控制模式: ${phase.name}`);
                }
            } else if (controlMode === 'all-red') {
                // 全红控制
                currentPhaseDisplay.className = 'phase-display red';
                currentPhaseDisplay.innerHTML = `
                    <div>手动控制</div>
                    <div>全红模式</div>
                `;

                countdownTimer.textContent = duration || '∞';
                phaseProgressBar.className = 'phase-progress-bar red';
                phaseProgressBar.style.width = '100%';

                alert('已切换到全红控制模式');
            } else if (controlMode === 'flashing-yellow') {
                // 黄闪控制
                currentPhaseDisplay.className = 'phase-display yellow';
                currentPhaseDisplay.innerHTML = `
                    <div>手动控制</div>
                    <div>黄闪模式</div>
                `;

                countdownTimer.textContent = duration || '∞';
                phaseProgressBar.className = 'phase-progress-bar yellow';
                phaseProgressBar.style.width = '100%';

                alert('已切换到黄闪控制模式');
            } else if (controlMode === 'flashing-red') {
                // 红闪控制
                currentPhaseDisplay.className = 'phase-display red';
                currentPhaseDisplay.innerHTML = `
                    <div>手动控制</div>
                    <div>红闪模式</div>
                `;

                countdownTimer.textContent = duration || '∞';
                phaseProgressBar.className = 'phase-progress-bar red';
                phaseProgressBar.style.width = '100%';

                alert('已切换到红闪控制模式');
            }

            manualControlModal.classList.remove('active');
        }

        // 取消手动控制
        function cancelManualControl() {
            manualControlModal.classList.remove('active');
            alert('手动控制已取消');
        }

        // 保存配置
        function saveConfiguration() {
            // 模拟保存配置到服务器
            const configData = {
                intersectionId: document.querySelector('.intersection-card.active').getAttribute('data-intersection-id'),
                phases: phases,
                cycleDuration: parseInt(cycleDurationSlider.value),
                configName: `CONFIG-${new Date().toISOString().split('T')[0].replace(/-/g, '')}-001`,
                timestamp: new Date().toISOString()
            };

            // 在实际应用中，这里会发送API请求保存配置
            console.log('保存配置:', configData);

            alert('配置已保存到本地\n配置编号: ' + configData.configName);
        }

        // 下发配置
        function deployConfiguration() {
            if (!confirm('确定要将配置下发到所有信号控制器吗？')) return;

            // 模拟下发配置过程
            deployConfigBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> 下发中...';
            deployConfigBtn.disabled = true;

            setTimeout(() => {
                deployConfigBtn.innerHTML = '<i class="fas fa-cloud-upload-alt"></i> 下发配置';
                deployConfigBtn.disabled = false;

                alert('配置已成功下发到8个信号控制器中的6个\n2个离线设备将在恢复连接后自动同步配置');
            }, 2000);
        }

        // 添加新相位
        function addNewPhase() {
            const newPhaseNumber = phases.length + 1;
            const newPhase = {
                id: `phase-${newPhaseNumber}`,
                number: newPhaseNumber,
                name: `新相位 ${newPhaseNumber}`,
                color: "green",
                direction: "north",
                greenDuration: 30,
                yellowDuration: 3,
                allRedDuration: 2,
                minGreenTime: 15,
                maxGreenTime: 45,
                priority: 5
            };

            // 添加到相位数组
            phases.push(newPhase);

            // 创建新的相位列表项
            const phaseList = document.querySelector('.phase-list');
            const newPhaseItem = document.createElement('div');
            newPhaseItem.className = 'phase-item';
            newPhaseItem.setAttribute('data-phase-id', newPhase.id);
            newPhaseItem.innerHTML = `
                <div class="phase-number">相位 ${newPhase.number}</div>
                <div class="phase-name">${newPhase.name}</div>
                <div class="phase-duration">${newPhase.greenDuration}秒</div>
            `;

            phaseList.appendChild(newPhaseItem);

            // 添加点击事件
            newPhaseItem.addEventListener('click', function() {
                // 移除所有active类
                phaseItems.forEach(item => item.classList.remove('active'));
                // 为当前项添加active类
                this.classList.add('active');

                const phaseId = this.getAttribute('data-phase-id');
                currentPhase = phases.find(p => p.id === phaseId);
                updatePhaseEditor(currentPhase);
            });

            // 选中新相位
            phaseItems.forEach(item => item.classList.remove('active'));
            newPhaseItem.classList.add('active');
            currentPhase = newPhase;
            updatePhaseEditor(currentPhase);

            // 更新相位列表引用
            phaseItems = document.querySelectorAll('.phase-item');

            // 更新周期时间轴
            updateCycleTimeline();

            alert(`新相位 ${newPhaseNumber} 已添加`);
        }

        // 删除当前相位
        function deleteCurrentPhase() {
            if (phases.length <= 4) {
                alert('最少需要保留4个相位');
                return;
            }

            if (!confirm(`确定要删除相位 ${currentPhase.number} - ${currentPhase.name} 吗？`)) return;

            const phaseIndex = phases.findIndex(p => p.id === currentPhase.id);
            if (phaseIndex >= 0) {
                // 从数组中删除
                phases.splice(phaseIndex, 1);

                // 重新编号相位
                phases.forEach((phase, index) => {
                    phase.number = index + 1;
                    phase.id = `phase-${phase.number}`;
                });

                // 重新构建相位列表
                const phaseList = document.querySelector('.phase-list');
                phaseList.innerHTML = '<div class="phase-list-title">相位列表</div>';

                phases.forEach(phase => {
                    const phaseItem = document.createElement('div');
                    phaseItem.className = 'phase-item';
                    if (phase.id === phases[0].id) phaseItem.classList.add('active');
                    phaseItem.setAttribute('data-phase-id', phase.id);
                    phaseItem.innerHTML = `
                        <div class="phase-number">相位 ${phase.number}</div>
                        <div class="phase-name">${phase.name}</div>
                        <div class="phase-duration">${phase.greenDuration}秒</div>
                    `;

                    phaseList.appendChild(phaseItem);
                });

                // 更新当前相位
                currentPhase = phases[0];
                updatePhaseEditor(currentPhase);

                // 更新相位列表引用
                phaseItems = document.querySelectorAll('.phase-item');

                // 添加点击事件
                phaseItems.forEach(item => {
                    item.addEventListener('click', function() {
                        // 移除所有active类
                        phaseItems.forEach(item => item.classList.remove('active'));
                        // 为当前项添加active类
                        this.classList.add('active');

                        const phaseId = this.getAttribute('data-phase-id');
                        currentPhase = phases.find(p => p.id === phaseId);
                        updatePhaseEditor(currentPhase);
                    });
                });

                // 更新周期时间轴
                updateCycleTimeline();

                alert('相位已删除，剩余相位已重新编号');
            }
        }

        // 事件监听
        document.addEventListener('DOMContentLoaded', () => {
            initPhaseEditor();
            setSimulationPhase(0, true);

            // 相位列表项点击事件
            phaseItems.forEach(item => {
                item.addEventListener('click', function() {
                    // 移除所有active类
                    phaseItems.forEach(item => item.classList.remove('active'));
                    // 为当前项添加active类
                    this.classList.add('active');

                    const phaseId = this.getAttribute('data-phase-id');
                    currentPhase = phases.find(p => p.id === phaseId);
                    updatePhaseEditor(currentPhase);
                });
            });

            // 颜色选择器点击事件
            colorOptions.forEach(option => {
                option.addEventListener('click', function() {
                    colorOptions.forEach(opt => opt.classList.remove('active'));
                    this.classList.add('active');
                });
            });

            // 方向选择器点击事件
            directionOptions.forEach(option => {
                option.addEventListener('click', function() {
                    directionOptions.forEach(opt => opt.classList.remove('active'));
                    this.classList.add('active');
                });
            });

            // 绿灯时长滑块事件
            greenDurationSlider.addEventListener('input', function() {
                greenDurationValue.textContent = this.value;
            });

            // 黄灯时长滑块事件
            yellowDurationSlider.addEventListener('input', function() {
                yellowDurationValue.textContent = this.value;
            });

            // 周期时长滑块事件
            cycleDurationSlider.addEventListener('input', function() {
                cycleDurationValue.textContent = this.value;
                totalCycleTime.textContent = this.value;
                updateCycleTimeline();
            });

            // 应用配置按钮
            applyPhaseBtn.addEventListener('click', savePhaseConfig);

            // 测试相位按钮
            testPhaseBtn.addEventListener('click', () => {
                alert(`正在测试相位 ${currentPhase.number}...\n实际部署中将控制信号控制器切换到测试模式`);
            });

            // 删除相位按钮
            deletePhaseBtn.addEventListener('click', deleteCurrentPhase);

            // 添加相位按钮
            addPhaseBtn.addEventListener('click', addNewPhase);

            // 保存配置按钮
            saveConfigBtn.addEventListener('click', saveConfiguration);

            // 下发配置按钮
            deployConfigBtn.addEventListener('click', deployConfiguration);

            // 路口选择器点击事件
            intersectionCards.forEach(card => {
                card.addEventListener('click', function() {
                    intersectionCards.forEach(c => c.classList.remove('active'));
                    this.classList.add('active');

                    const intersectionId = this.getAttribute('data-intersection-id');
                    alert(`已切换到路口: ${this.querySelector('.intersection-name').textContent}`);
                });
            });

            // 模拟控制按钮
            startSimulationBtn.addEventListener('click', startSimulation);
            pauseSimulationBtn.addEventListener('click', pauseSimulation);
            stopSimulationBtn.addEventListener('click', stopSimulation);

            // 手动控制按钮
            manualControlBtn.addEventListener('click', openManualControl);
            closeManualControlBtn.addEventListener('click', () => {
                manualControlModal.classList.remove('active');
            });

            // 控制模式选择事件
            controlModeSelect.addEventListener('change', function() {
                singlePhaseControl.style.display = this.value === 'single-phase' ? 'block' : 'none';
            });

            // 执行控制按钮
            executeControlBtn.addEventListener('click', executeManualControl);

            // 取消控制按钮
            cancelControlBtn.addEventListener('click', cancelManualControl);

            // 导航菜单点击事件
            document.querySelectorAll('.nav-item, .nav-subitem').forEach(item => {
                item.addEventListener('click', function() {
                    // 移除所有active类
                    document.querySelectorAll('.nav-item.active, .nav-subitem.active').forEach(el => {
                        el.classList.remove('active');
                    });

                    // 为当前项添加active类
                    this.classList.add('active');

                    // 如果点击的是主菜单项，激活其第一个子项
                    if (this.classList.contains('nav-item')) {
                        const nextSibling = this.nextElementSibling;
                        if (nextSibling && nextSibling.classList.contains('nav-subitem')) {
                            nextSibling.classList.add('active');
                        }
                    }
                });
            });
        });
    </script>
</body>
</html>
```

## 功能说明

这个HTML页面实现了"相位/周期远程配置"功能，具有以下特性：

### 1. **相位配置编辑器**
- **相位列表**：显示当前路口的所有相位，支持点击选择编辑
- **相位参数**：
  - 相位名称和编号
  - 信号灯颜色选择（绿灯、黄灯、红灯）
  - 方向控制（北向、南向、东向、西向及各方向左转）
  - 绿灯时间配置（10-60秒可调）
  - 黄灯时间配置（2-5秒可调）
  - 最小/最大绿灯时间限制
  - 全红时间配置（1-5秒）
  - 相位优先级设置（1-10级）

### 2. **周期配置管理**
- **周期时间轴**：可视化显示所有相位在周期中的时间分配
- **周期总时长**：60-180秒可调，实时计算和显示总时长
- **相位时间分配**：自动根据各相位时长计算在周期中的比例

### 3. **路口选择器**
- 支持切换不同路口进行配置
- 显示路口基本信息（类型、相位数量、周期时长）
- 当前路口高亮显示

### 4. **实时状态模拟器**
- **当前相位显示**：圆形指示灯显示当前相位状态
- **倒计时**：显示当前相位剩余时间
- **进度条**：可视化显示相位进度
- **模拟控制**：启动、暂停、停止模拟功能
- **手动控制**：支持单相位控制、全红控制、黄闪控制、红闪控制

### 5. **操作功能**
- **保存配置**：将当前配置保存到本地/服务器
- **下发配置**：将配置下发到所有信号控制器
- **新增相位**：添加新的相位配置
- **删除相位**：删除当前选中的相位
- **测试相位**：测试当前相位配置
- **应用配置**：将编辑器中的配置应用到当前相位

### 6. **鸿蒙特色功能**
- **鸿蒙设备支持**：专门针对鸿蒙信号控制器优化配置
- **远程下发**：通过OpenHarmony分布式能力远程配置设备
- **状态同步**：实时同步信号控制器状态

### 7. **数据展示**
- **统计卡片**：显示相位总数、信号周期、在线设备数、配置告警
- **配置信息**：显示当前配置的详细信息
- **实时状态**：显示信号灯的实时运行状态

这个页面提供了一个完整的交通信号灯相位/周期远程配置解决方案，帮助交通管理人员直观、高效地配置和管理路口信号灯，提高交通管理效率和路口通行能力。

