        // 边缘节点数据
        const edgeNodes = [
            { id: 1, name: "边缘节点-A", location: "路口A", cpu: 65, memory: 72, storage: 45, status: "online" },
            { id: 2, name: "边缘节点-B", location: "路口B", cpu: 42, memory: 58, storage: 32, status: "online" },
