                            </div>
                            <div class="detail-item">
                                <div class="detail-label">优先级</div>
                                <div class="detail-value">${strategy.priority}/10</div>
                            </div>
                            <div class="detail-item">
                                <div class="detail-label">最后部署时间</div>
                                <div class="detail-value">${strategy.lastDeployTime || '未部署'}</div>
                            </div>
                        </div>
                    </div>

                    <div class="detail-section">
                        <div class="detail-section-title">算法参数</div>
                        <div>${paramsHtml}</div>
                    </div>

                    <div class="detail-section">
                        <div class="detail-section-title">目标设备</div>
                        <div>${devicesHtml}</div>
                    </div>

                    <div class="detail-section">
                        <div class="detail-section-title">资源需求</div>
                        <div class="detail-grid">
                            <div class="detail-item">
                                <div class="detail-label">CPU需求</div>
                                <div class="detail-value">${strategy.resourceRequirements.cpu} 核心</div>
                            </div>
                            <div class="detail-item">
                                <div class="detail-label">内存需求</div>
                                <div class="detail-value">${strategy.resourceRequirements.memory} MB</div>
                            </div>
