            // 更新部署统计信息
            updateDeploymentStats(strategy);

            // 更新设备部署列表
            updateDeviceDeploymentList(strategy);
        }

        // 更新部署统计信息
        function updateDeploymentStats(strategy) {
            // 模拟部署统计数据
            let deployed = 0, deploying = 0, pending = 0, failed = 0;

            if (strategy.status === 'deployed') {
                deployed = strategy.devices.length;
            } else if (strategy.status === 'deploying') {
                deploying = Math.floor(strategy.devices.length * 0.6);
                pending = strategy.devices.length - deploying;
                failed = Math.floor(strategy.devices.length * 0.1);
            } else if (strategy.status === 'published') {
                pending = strategy.devices.length;
            }

            document.getElementById('deployedCount').textContent = deployed;
            document.getElementById('deployingCount').textContent = deploying;
            document.getElementById('pendingCount').textContent = pending;
            document.getElementById('failedCount').textContent = failed;
        }

        // 更新设备部署列表
        function updateDeviceDeploymentList(strategy) {
            const deviceList = document.getElementById('deviceDeploymentList');
            deviceList.innerHTML = '';

            strategy.devices.forEach((device, index) => {
                let status, statusClass, progress;

                if (strategy.status === 'deployed') {
                    status = '已部署';
                    statusClass = 'status-deployed';
                    progress = 100;
                } else if (strategy.status === 'deploying') {
                    if (index < 3) {
                        status = '部署中';
                        statusClass = 'status-deploying';
                        progress = 30 + (index * 20);
                    } else {
                        status = '待部署';
                        statusClass = 'status-draft';
                        progress = 0;
                    }
                } else if (strategy.status === 'published') {
                    status = '待部署';
                    statusClass = 'status-draft';
                    progress = 0;
                } else {
                    status = '未部署';
                    statusClass = 'status-stopped';
                    progress = 0;
                }

                const deviceItem = document.createElement('div');
                deviceItem.className = 'strategy-item';
                deviceItem.innerHTML = `
                    <div class="strategy-item-header">
                        <div class="strategy-name">${device}</div>
                        <div class="strategy-status ${statusClass}">${status}</div>
                    </div>
                    <div class="strategy-description">边缘节点: ${edgeNodes[index % edgeNodes.length].name}</div>
                    <div class="progress-bar">
                        <div class="progress-fill progress-${progress > 70 ? 'safe' : progress > 30 ? 'warning' : 'danger'}" style="width: ${progress}%"></div>
                    </div>
                `;

                deviceList.appendChild(deviceItem);
            });
        }

        // 初始化资源监控
        function initResourceMonitor() {
            const resourceMetrics = document.getElementById('resourceMetrics');
            resourceMetrics.innerHTML = '';

            edgeNodes.forEach(node => {
                const metric = document.createElement('div');
                metric.className = 'resource-metric';

                let statusClass = '';
                if (node.cpu > 80 || node.memory > 80) {
                    statusClass = 'progress-danger';
                } else if (node.cpu > 60 || node.memory > 60) {
                    statusClass = 'progress-warning';
                } else {
                    statusClass = 'progress-safe';
                }

                metric.innerHTML = `
                    <div class="metric-header">
                        <div class="metric-name">${node.name}</div>
                        <div class="metric-value">${node.status === 'online' ? '在线' : '警告'}</div>
                    </div>
                    <div class="metric-header">
                        <div>CPU: ${node.cpu}%</div>
                        <div>内存: ${node.memory}%</div>
                    </div>
                    <div class="progress-bar">
                        <div class="progress-fill ${statusClass}" style="width: ${Math.max(node.cpu, node.memory)}%"></div>
                    </div>
                `;

                resourceMetrics.appendChild(metric);
            });
        }

        // 策略操作函数
        function deployStrategy(strategyId) {
            const strategy = edgeStrategies.find(s => s.id === strategyId);
            if (!strategy) return;

            alert(`开始部署策略: ${strategy.name}\n目标设备: ${strategy.devices.length}个\n预计部署时间: 2-5分钟`);

            // 模拟状态更新
            strategy.status = 'deploying';
            strategy.statusText = '部署中';
            strategy.lastDeployTime = new Date().toLocaleString('zh-CN').replace(/\//g, '-');
            strategy.lastDeployBy = '当前用户';

            initStrategyList();
            selectStrategy(strategyId);

            // 模拟部署进度
            setTimeout(() => {
                strategy.status = 'deployed';
                strategy.statusText = '已部署';
                initStrategyList();
                selectStrategy(strategyId);
            }, 5000);
        }

        function stopStrategy(strategyId) {
            const strategy = edgeStrategies.find(s => s.id === strategyId);
            if (!strategy) return;

            if (confirm(`确认停止策略 "${strategy.name}" 吗？`)) {
                strategy.status = 'stopped';
                strategy.statusText = '已停止';

                initStrategyList();
                selectStrategy(strategyId);

                alert(`策略 "${strategy.name}" 已停止`);
            }
        }

        function updateStrategy(strategyId) {
            const strategy = edgeStrategies.find(s => s.id === strategyId);
            if (!strategy) return;

            alert(`开始更新策略: ${strategy.name}\n将逐步更新到所有目标设备`);

            strategy.status = 'deploying';
            strategy.statusText = '更新中';
            strategy.lastDeployTime = new Date().toLocaleString('zh-CN').replace(/\//g, '-');
            strategy.lastDeployBy = '当前用户';

            initStrategyList();
            selectStrategy(strategyId);

            // 模拟更新完成
            setTimeout(() => {
                strategy.status = 'deployed';
                strategy.statusText = '已部署';
                initStrategyList();
                selectStrategy(strategyId);
            }, 3000);
        }

        function editStrategy(strategyId) {
            const strategy = edgeStrategies.find(s => s.id === strategyId);
            if (!strategy) return;

            alert(`进入策略编辑模式: ${strategy.name}\n（在实际系统中将打开策略编辑器）`);
        }

        function deleteStrategy(strategyId) {
            const strategy = edgeStrategies.find(s => s.id === strategyId);
            if (!strategy) return;

            if (confirm(`确认删除策略 "${strategy.name}" 吗？此操作不可恢复。`)) {
                // 在实际系统中，这里会调用API删除策略
                alert(`策略 "${strategy.name}" 已标记为删除`);
            }
        }

        function stopDeployment(strategyId) {
            const strategy = edgeStrategies.find(s => s.id === strategyId);
            if (!strategy) return;

            if (confirm(`确认停止策略 "${strategy.name}" 的部署过程吗？`)) {
                strategy.status = 'published';
                strategy.statusText = '已发布';

                initStrategyList();
                selectStrategy(strategyId);

                alert(`策略 "${strategy.name}" 的部署已停止`);
            }
        }

        // 页面初始化
        document.addEventListener('DOMContentLoaded', function() {
            initStrategyList();
            initResourceMonitor();

            // 默认选择第一个策略
            if (edgeStrategies.length > 0) {
                selectStrategy(edgeStrategies[0].id);
            }

            // 搜索功能
            document.getElementById('strategySearch').addEventListener('input', function(e) {
                const searchTerm = e.target.value.toLowerCase();

                document.querySelectorAll('.strategy-item').forEach(item => {
                    const name = item.querySelector('.strategy-name').textContent.toLowerCase();
                    const desc = item.querySelector('.strategy-description').textContent.toLowerCase();

                    if (name.includes(searchTerm) || desc.includes(searchTerm)) {
                        item.style.display = 'block';
                    } else {
                        item.style.display = 'none';
                    }
                });
            });

            // 新建策略按钮
            document.getElementById('newStrategyBtn').addEventListener('click', function() {
                alert('打开策略创建向导\n（在实际系统中将打开策略创建界面）');
            });

            // 批量下发按钮
            document.getElementById('deployBtn').addEventListener('click', function() {
                const selectedStrategies = edgeStrategies.filter(s => s.status === 'published');
                if (selectedStrategies.length === 0) {
                    alert('没有找到可部署的策略（状态为"已发布"的策略）');
                    return;
                }

                if (confirm(`将部署 ${selectedStrategies.length} 个策略到目标设备，确认继续吗？`)) {
                    alert(`开始批量部署 ${selectedStrategies.length} 个策略\n部署任务已提交，可在任务中心查看进度`);
                }
            });

            // 模拟资源监控更新
            setInterval(() => {
                // 随机更新节点资源使用率
                edgeNodes.forEach(node => {
                    if (node.status === 'online') {
                        const change = Math.floor(Math.random() * 10) - 5;
                        node.cpu = Math.max(10, Math.min(95, node.cpu + change));

                        const memChange = Math.floor(Math.random() * 8) - 4;
                        node.memory = Math.max(15, Math.min(90, node.memory + memChange));

                        const storageChange = Math.floor(Math.random() * 3) - 1;
                        node.storage = Math.max(20, Math.min(80, node.storage + storageChange));
                    }
                });

                initResourceMonitor();

                // 更新仪表板卡片数据
                const onlineNodes = edgeNodes.filter(n => n.status === 'online').length;
                const totalNodes = edgeNodes.length;
                const avgResource = Math.floor(edgeNodes.reduce((sum, node) => sum + node.cpu, 0) / edgeNodes.length);

                document.querySelector('.card:nth-child(1) .card-value').textContent = onlineNodes;
                document.querySelector('.card:nth-child(1) .card-label').textContent = `在线节点 / 总数: ${totalNodes}`;

                document.querySelector('.card:nth-child(4) .card-value').textContent = `${avgResource}%`;
            }, 8000);

            // 导航菜单点击事件
            document.querySelectorAll('.nav-item, .nav-subitem').forEach(item => {
                item.addEventListener('click', function() {
                    // 移除所有active类
                    document.querySelectorAll('.nav-item.active, .nav-subitem.active').forEach(el => {
                        el.classList.remove('active');
                    });

                    // 为当前项添加active类
                    this.classList.add('active');

                    // 如果点击的是主菜单项，激活其第一个子项
                    if (this.classList.contains('nav-item')) {
                        const nextSibling = this.nextElementSibling;
                        if (nextSibling && nextSibling.classList.contains('nav-subitem')) {
                            nextSibling.classList.add('active');
                        }
                    }
                });
            });
        });
