        // 初始化审计表格
        function initAuditTable() {
            const tableBody = document.getElementById('auditTableBody');
            tableBody.innerHTML = '';

            auditLogs.forEach(log => {
                const row = document.createElement('tr');

                // 根据操作类型设置样式
                let operationClass = '';
                let operationText = '';
                switch(log.operationType) {
                    case 'CONTROL_COMMAND':
                        operationClass = 'badge-control';
                        operationText = '控制命令';
                        break;
                    case 'UPDATE_CONFIG':
                        operationClass = 'badge-config';
                        operationText = '更新配置';
                        break;
                    case 'DEPLOY_STRATEGY':
                        operationClass = 'badge-strategy';
                        operationText = '部署策略';
                        break;
                    case 'SECURITY_OPERATION':
                        operationClass = 'badge-security';
                        operationText = '安全操作';
                        break;
                    default:
                        operationClass = 'badge-control';
                        operationText = log.operationType;
                }

                // 根据结果状态设置样式
                let resultClass = '';
                let resultText = '';
                switch(log.resultStatus) {
                    case 'SUCCESS':
                        resultClass = 'result-success';
                        resultText = '成功';
                        break;
                    case 'FAILED':
                        resultClass = 'result-failed';
                        resultText = '失败';
                        break;
                    case 'PARTIAL_SUCCESS':
                        resultClass = 'result-partial';
                        resultText = '部分成功';
                        break;
                    case 'TIMEOUT':
                        resultClass = 'result-timeout';
                        resultText = '超时';
                        break;
                    default:
                        resultClass = 'result-success';
                        resultText = log.resultStatus;
                }

                // 根据风险等级设置样式
                let riskClass = '';
                let riskText = '';
                switch(log.riskLevel) {
                    case 'LOW':
                        riskClass = 'risk-low';
                        riskText = '低风险';
                        break;
                    case 'MEDIUM':
                        riskClass = 'risk-medium';
                        riskText = '中风险';
                        break;
                    case 'HIGH':
                        riskClass = 'risk-high';
                        riskText = '高风险';
                        break;
                    case 'CRITICAL':
                        riskClass = 'risk-critical';
                        riskText = '严重风险';
                        break;
                    default:
                        riskClass = 'risk-low';
                        riskText = log.riskLevel;
                }

                row.innerHTML = `
                    <td class="log-id">${log.logId}</td>
                    <td>
                        <span class="operation-badge ${operationClass}">${operationText}</span>
                    </td>
                    <td>${log.operationName}</td>
                    <td>${log.operator}</td>
                    <td>${log.operationTime}</td>
                    <td>
                        <span class="result-badge ${resultClass}">${resultText}</span>
                    </td>
                    <td>
                        <span class="risk-indicator ${riskClass}"></span>
                        <span>${riskText}</span>
                    </td>
                    <td>
                        <button class="detail-btn" onclick="showLogDetail(${log.id})">详情</button>
                    </td>
                `;

                tableBody.appendChild(row);
            });
        }

