package org.wlpiaoyi.framework.utils.data;


import java.math.BigInteger;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

/**
 * <p><b>{@code @author:}</b>         wlpiaoyi</p>
 * <p><b>{@code @description:}</b>
 * <div style='padding: 5px; margin-left: 5px; margin-bottom: 5px;'>
 * 提供基于任意进制转换的数据编码工具类，支持不同字符集之间的进制转换操作。
 * </div>
 * </p>
 * <p><b>{@code @date:}</b>           2025/11/30 11:49</p>
 * <p><b>{@code @version:}</b>       1.0</p>
 * <hr/>
 */
class DataBaseXUtils {

    private static final Map<String, Map<Character, Integer>> charIndexMapCache = new ConcurrentHashMap<>();
    private static final Map<String, Map<Integer, Character>> indexCharMapCache = new ConcurrentHashMap<>();

    private static char toChar(int value){
        return (char)((byte) value);
    }
    private static char toChar(byte value){
        return (char)(value);
    }

    static Map<Character, Integer> convertCharIndexMap(char[] charArray) {
        if(charArray == null){
            String key = "256";
            return charIndexMapCache.computeIfAbsent(key, k -> {
                Map<Character, Integer> dict = new HashMap<>();
                for (int i = 0; i < 256; i++) {
                    dict.put(toChar(i), i);
                }
                return dict;
            });
        }
        String key = charArray.length + "";
        return charIndexMapCache.computeIfAbsent(key, k -> {
            Map<Character, Integer> dict = new HashMap<>();
            for (int i = 0; i < charArray.length; i++) {
                dict.put(charArray[i], i);
            }
            return dict;
        });
    }

    static Map<Integer, Character> convertIndexCharMap(char[] charArray) {
        if(charArray == null){
            String key = "256";
            return indexCharMapCache.computeIfAbsent(key, k -> {
                Map<Integer, Character> dict = new HashMap<>();
                for (int i = 0; i < 256; i++) {
                    dict.put(i, toChar(i));
                }
                return dict;
            });
        }
        String key = charArray.length + "";
        return indexCharMapCache.computeIfAbsent(key, k -> {
            Map<Integer, Character> dict = new HashMap<>();
            for (int i = 0; i < charArray.length; i++) {
                dict.put(i, charArray[i]);
            }
            return dict;
        });
    }

    /**
     * <p><b>{@code @description:}</b>
     * <div style='padding: 5px; margin-left: 5px; margin-bottom: 5px;'>
     * 将原始字节数组从源字符集进制转换为目标字符集进制
     * </div>
     * </p>
     *
     * <p><b>{@code @param}</b> <b>originalBytes</b>
     * 待转换的原始字节数组
     * {@link byte}
     * </p>
     *
     * <p><b>{@code @param}</b> <b>originalOffset</b>
     * {@link int}
     * 待转换字节数组的起始索引
     * </p>
     *
     * <p><b>{@code @param}</b> <b>originalLen</b>
     * {@link int}
     * 待转换字节数组的长度
     * </p>
     *
     * <p><b>{@code @param}</b> <b>originalChars</b>
     * 源字符集数组，用于解析原始字节的进制基数
     * {@link char}
     * </p>
     *
     * <p><b>{@code @param}</b> <b>convertChars</b>
     * 目标字符集数组，用于生成转换后的字节表示
     * {@link char}
     * </p>
     *
     * <p><b>{@code @date:}</b>2025/11/30 11:50</p>
     * <p><b>{@code @return:}</b>{@link byte[]} 转换后的字节数组</p>
     * <p><b>{@code @author:}</b>wlpiaoyi</p>
     * <hr/>
     */
    static byte[] conversionToBaseX(byte[] originalBytes, int originalOffset, int originalLen, char[] originalChars, char[] convertChars) {
        if (originalBytes == null || originalBytes.length == 0) {
            return new byte[0];
        }
        if (originalOffset > 0 && originalOffset >= originalBytes.length){
            throw new IllegalArgumentException("originalOffset value out");
        }
        if(originalLen > 0){
            if(originalLen >= originalBytes.length)
                originalLen = -1;
            else if(originalOffset >= 0 && originalOffset + originalLen >= originalBytes.length)
                originalLen = -1;
        }
        // 将字符映射回索引值
        Map<Character, Integer> originalCharIndexMap = convertCharIndexMap(originalChars);
        BigInteger originalBase = BigInteger.valueOf(originalCharIndexMap.size());
        BigInteger value = BigInteger.ZERO;
        for (byte b : originalBytes) {
            if(originalOffset > 0){
                originalOffset--;
                if(originalOffset > 0) continue;
            }
            int originalCharIndex = originalCharIndexMap.get(toChar(b));
            value = value.multiply(originalBase) // 乘以进制
                    .add(BigInteger.valueOf(originalCharIndex)); // 加上当前字节Index值
            if(originalLen > 0){
                originalLen--;
            }
            if(originalLen == 0){
                break;
            }
        }
        Map<Integer, Character> convertIndexCharMap = convertIndexCharMap(convertChars);
        List<Byte> result = new LinkedList();
        conversionToBaseXScale(value, convertIndexCharMap, result);
        byte[] output = new byte[result.size()];
        {
            var iterator = result.iterator();
            int i = 0;
            while (iterator.hasNext()) {
                output[i++] = iterator.next();
            }
        }
        return output;
    }

    /**
     * 将大整数值按目标进制转换为字符表示
     *
     * @param value 待转换的大整数值
     * @param charMap 目标进制的索引到字符映射表
     * @param result 转换结果存储列表
     */
    private static void conversionToBaseXScale(BigInteger value, Map<Integer, Character> charMap, List<Byte> result){
        if (value.equals(BigInteger.ZERO)) {
            result.add((byte) charMap.get(0).charValue());
            return;
        }
        BigInteger cLength = BigInteger.valueOf(charMap.size());
        while (value.compareTo(BigInteger.ZERO) > 0) {
            int remainder = value.remainder(cLength).intValue();
            value = value.divide(cLength);
            char c = charMap.get(remainder);
            result.addFirst((byte) c);
        }
    }


}

优化一下性能

我们注意到，原始代码中使用了LinkedList和迭代器来构建结果，这可能会影响性能。
 我们可以改用ArrayList，并预先估计大小（虽然BigInteger转换为指定进制后的大小不确定，但我们可以先使用一个初始容量）。
 但是，由于我们不知道转换后的长度，我们可以先使用一个可增长的数组，但ArrayList在头部插入元素效率很低（因为要移动元素）。
 原代码中使用了LinkedList，并在最后转换为数组，这避免了头部插入的问题，但是LinkedList在存储和迭代时开销较大。

 另一种思路：我们可以先计算转换后的长度，然后从后往前填充数组，这样可以使用数组而不需要头部插入。

 但是，BigInteger的toString(radix)方法已经提供了进制转换，但是这里我们使用的是自定义字符集，所以不能直接使用。

 我们可以先计算转换后的位数，然后分配数组，从后往前填充。

 步骤如下：
 1. 计算目标进制的基数（base = charMap.size()）
 2. 计算转换后的位数：我们可以通过不断除以基数直到value为0来得到位数，或者使用对数来估计（但可能不准确，因为BigInteger）。
 3. 我们可以先计算位数，然后分配数组。

 但是，原代码中使用了LinkedList，然后反转（通过addFirst）来实现顺序。我们可以改为先计算位数，然后从后往前填充数组。

 修改conversionToBaseXScale方法，使其直接返回byte数组，并避免使用LinkedList。

 同时，我们注意到在conversionToBaseX方法中，我们遍历原始字节数组并构建BigInteger，然后调用conversionToBaseXScale。
 我们可以尝试优化BigInteger的构建过程，但可能不是性能瓶颈。

 我们主要优化转换部分：

 原conversionToBaseXScale方法使用LinkedList，然后转换为数组。现在改为：

 1. 先计算转换后的字符个数（即位数）。
 2. 分配一个byte数组，从后往前填充。

 但是，计算位数需要重复计算一次除法和取余，我们可以先计算位数，然后填充。

 另一种做法：我们可以先计算出逆序的余数（即从最低位到最高位），然后反转。但是，我们不知道有多少位，所以需要动态增长。

 我们可以使用ArrayList来存储余数（整数索引），然后反转，再转换为字符。这样避免了在头部插入，但是需要两次遍历（一次计算余数并存储，一次转换为字符）。

 或者，我们可以先计算位数，然后分配数组，再从后往前填充。

 计算位数的方法：

   BigInteger temp = value;
   int digitCount = 0;
   while (temp.compareTo(BigInteger.ZERO) > 0) {
       temp = temp.divide(base);
       digitCount++;
   }
   if (digitCount == 0) {
       digitCount = 1; // 值为0时，位数为1
   }

 然后，我们可以分配一个长度为digitCount的byte数组，从后往前填充：

   for (int i = digitCount - 1; i >= 0; i--) {
       int remainder = value.remainder(base).intValue();
       value = value.divide(base);
       array[i] = (byte) charMap.get(remainder);
   }

 但是，这样会改变value的值，所以我们需要一个临时变量。不过，我们可以在计算位数时使用临时变量，然后重新赋值给value？或者我们可以在计算位数后重新计算value？这样不行，因为value已经被改变。

 所以，我们有两种选择：
   a. 先计算位数，然后重新计算每个位（但这样需要重新做除法，效率低）。
   b. 先存储余数，然后反转。

 我们选择b，因为这样只需要一次循环计算余数，然后反转即可。

 步骤：
   1. 计算余数，存入一个List<Integer>中，同时计算余数的个数（即位数）。
   2. 然后，分配byte数组，将余数通过charMap转换为字符，存入byte数组（注意顺序是反转的）。

 但是，我们也可以不用List，而是先计算位数，然后分配数组，但是需要再次计算余数。或者，我们可以在计算余数的同时，记录余数，然后直接填充到数组（但是数组需要从后往前填充，所以需要知道位数）。

 我们可以先计算余数并存入一个动态数组，然后反转这个数组，再转换为byte数组。

 我们修改conversionToBaseXScale方法如下：

  private static byte[] conversionToBaseXScale(BigInteger value, Map<Integer, Character> charMap) {
        BigInteger base = BigInteger.valueOf(charMap.size());
        if (value.equals(BigInteger.ZERO)) {
            return new byte[]{(byte) charMap.get(0).charValue()};
        }
        List<Integer> remainders = new ArrayList<>();
        while (value.compareTo(BigInteger.ZERO) > 0) {
            BigInteger[] divideAndRemainder = value.divideAndRemainder(base);
            value = divideAndRemainder[0];
            int remainder = divideAndRemainder[1].intValue();
            remainders.add(remainder);
        }
        // 现在remainders中存储的是从低位到高位的余数，我们需要反转
        int size = remainders.size();
        byte[] result = new byte[size];
        for (int i = 0; i < size; i++) {
            int remainder = remainders.get(size - 1 - i);
            result[i] = (byte) charMap.get(remainder).charValue();
        }
