    public void rotateProxy() {
        if (proxyPool != null && !proxyPool.isEmpty()) {
            proxyIndex = (proxyIndex + 1) % proxyPool.size();
            this.proxyServer = proxyPool.get(proxyIndex);

            // 重启浏览器或重新配置代理
            if (this.driver != null) {
                this.quit();
                openChromeDriver();  // 根据当前浏览器类型重新打开
            }
        }
    }

