public class Browser {

    @Getter
    private int maxRetries = 3;

    public void openUrlWithRetry(String url) {
        int retryCount = 0;
        while (retryCount < maxRetries) {
            try {
                this.setUrl(url);
                break;
            } catch (Exception e) {
                retryCount++;
                if (retryCount >= maxRetries) {
                    throw new BusinessException("Failed to open URL after " + maxRetries + " attempts", e);
                }

                // 每次重试前更换代理
                rotateProxy();

                // 随机等待
                try {
                    Thread.sleep(5000 * retryCount + new Random().nextInt(3000));
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
            }
        }
    }
}
