 以下是修改后的openChromeDriver方法中的相关部分：

```java
public void openChromeDriver(){
    ChromeOptions options = new ChromeOptions();

    // ... 其他配置

    // 反检测配置
    options.setExperimentalOption("excludeSwitches", new String[]{"enable-automation"});
    options.setExperimentalOption("useAutomationExtension", false);

    // 添加一个脚本，在页面加载前隐藏WebDriver特征
    String script = "Object.defineProperty(navigator, 'webdriver', {get: () => undefined});";
    options.setExperimentalOption("excludeSwitches", new String[]{"enable-automation"});
    options.addArguments("--disable-blink-features=AutomationControlled");

    // ... 其他配置

    // 创建driver
    ChromeDriverService driverService;
    if(StringUtils.isBlank(this.driverPath)){
        driverService = ChromeDriverService.createDefaultService();
    }else {
        driverService = new ChromeDriverService.Builder()
                .usingDriverExecutable(new File(this.driverPath))
                .usingAnyFreePort().build();
    }
    this.driver = new ChromeDriver(driverService, options);

    // 如果Selenium版本支持，还可以使用DevTools执行CDP命令
    // 这里使用try-catch，如果版本不支持则忽略
    try {
        // Selenium 4的用法
        // 获取DevTools并执行CDP命令
        DevTools devTools = ((ChromeDriver) this.driver).getDevTools();
        devTools.createSession();
        devTools.send(Page.enable());
        devTools.send(Page.addScriptToEvaluateOnNewDocument(script));
    } catch (Exception e) {
        // 如果版本不支持，则只使用上面的实验性选项
        System.err.println("当前Selenium版本可能不支持DevTools，部分反检测功能可能无法使用");
    }

    // 调用openDriver方法
    openDriver();
}
```

