## 3. **完整的人类行为模拟器**

```java
public class Browser {

    // 添加人类行为模拟器
    public static class HumanBehaviorSimulator {
        private final WebDriver driver;
        private final Random random;

        public HumanBehaviorSimulator(WebDriver driver) {
            this.driver = driver;
            this.random = new Random();
        }

        // 模拟人类滚动
        public void simulateScroll() {
            JavascriptExecutor js = (JavascriptExecutor) driver;

            // 获取页面高度
            Long pageHeight = (Long) js.executeScript("return document.body.scrollHeight");
            int viewportHeight = driver.manage().window().getSize().height;

            // 分段滚动，模拟人类阅读速度
            for (int i = 0; i < pageHeight; i += viewportHeight) {
                // 随机滚动距离
                int scrollDistance = random.nextInt(viewportHeight / 2) + viewportHeight / 4;

                // 平滑滚动
                js.executeScript(String.format(
                    "window.scrollTo({top: %d, behavior: 'smooth'})", 
                    Math.min(i + scrollDistance, pageHeight)
                ));

                // 随机等待（模拟阅读时间）
                try {
                    Thread.sleep(random.nextInt(2000) + 500);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }

                // 偶尔向上滚动一点（模拟人类行为）
                if (random.nextDouble() < 0.1) {
                    js.executeScript(String.format(
                        "window.scrollBy({top: %d, behavior: 'smooth'})", 
                        -random.nextInt(100)
                    ));
                    try {
                        Thread.sleep(random.nextInt(1000) + 200);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                }
            }
        }

        // 模拟鼠标移动
        public void simulateMouseMovement() {
            JavascriptExecutor js = (JavascriptExecutor) driver;

            // 随机移动鼠标
            for (int i = 0; i < random.nextInt(10) + 5; i++) {
                int x = random.nextInt(1000);
                int y = random.nextInt(700);

                js.executeScript(String.format(
                    "var evt = new MouseEvent('mousemove', {" +
                    "    view: window," +
                    "    bubbles: true," +
                    "    cancelable: true," +
                    "    clientX: %d," +
                    "    clientY: %d" +
                    "});" +
                    "document.dispatchEvent(evt);", 
                    x, y
                ));

                try {
                    Thread.sleep(random.nextInt(300) + 100);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        }

        // 模拟点击行为
        public void simulateRandomClick() {
            JavascriptExecutor js = (JavascriptExecutor) driver;

            // 查找所有可点击元素
            String script = 
                "var elements = document.querySelectorAll('a, button, input[type=\"button\"], " +
                "input[type=\"submit\"], [role=\"button\"]');" +
                "return elements.length > 0 ? " +
                "elements[Math.floor(Math.random() * elements.length)] : null;";

            WebElement element = (WebElement) js.executeScript(script);

            if (element != null && element.isDisplayed() && element.isEnabled()) {
                try {
                    // 先移动鼠标到元素上
                    Actions actions = new Actions(driver);
                    actions.moveToElement(element).pause(100 + random.nextInt(200)).perform();

                    // 偶尔点击
                    if (random.nextDouble() < 0.3) {
                        actions.click().perform();
                        try {
                            Thread.sleep(random.nextInt(3000) + 1000); // 等待页面响应
                        } catch (InterruptedException e) {
                            Thread.currentThread().interrupt();
                        }
                    }
                } catch (Exception e) {
                    // 忽略元素交互异常
                }
            }
        }
    }
}
