package com.chinasofti.adaptationcenter.tenant.repository;

import com.baomidou.mybatisplus.core.mapper.BaseMapper;
import com.baomidou.mybatisplus.core.metadata.IPage;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import com.chinasofti.adaptationcenter.tenant.entity.Tenant;
import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Param;
import org.apache.ibatis.annotations.Select;

import java.util.List;

/**
 * 租户数据访问层
 * 
 * 功能描述：提供租户数据的CRUD操作及复杂查询
 * 
 * @author 中软国际研发团队
 * @since 2025-11-10
 */
@Mapper
public interface TenantRepository extends BaseMapper<Tenant> {

    /**
     * 根据租户编码查询租户信息
     * 
     * @param tenantCode 租户编码
     * @return 租户实体
     */
    @Select("SELECT * FROM sys_tenant WHERE tenant_code = #{tenantCode} AND is_deleted = 0")
    Tenant selectByTenantCode(@Param("tenantCode") String tenantCode);

    /**
     * 根据租户名称模糊查询
     * 
     * @param tenantName 租户名称（模糊匹配）
     * @return 租户列表
     */
    @Select("SELECT * FROM sys_tenant WHERE tenant_name LIKE CONCAT('%', #{tenantName}, '%') AND is_deleted = 0")
    List<Tenant> selectByTenantName(@Param("tenantName") String tenantName);

    /**
     * 根据状态查询租户列表（分页）
     * 
     * @param page 分页参数
     * @param status 租户状态
     * @return 分页结果
     */
    @Select("SELECT * FROM sys_tenant WHERE status = #{status} AND is_deleted = 0")
    IPage<Tenant> selectPageByStatus(Page<Tenant> page, @Param("status") Integer status);

    /**
     * 查询即将到期的租户列表
     * 
     * @param days 到期天数阈值
     * @return 租户列表
     */
    @Select("SELECT * FROM sys_tenant WHERE expire_time <= DATE_ADD(NOW(), INTERVAL #{days} DAY) " +
            "AND status = 1 AND is_deleted = 0 ORDER BY expire_time ASC")
    List<Tenant> selectExpiringTenants(@Param("days") Integer days);

    /**
     * 检查租户编码是否存在
     * 
     * @param tenantCode 租户编码
     * @return 是否存在
     */
    @Select("SELECT COUNT(1) FROM sys_tenant WHERE tenant_code = #{tenantCode} AND is_deleted = 0")
    Integer existsByTenantCode(@Param("tenantCode") String tenantCode);
}
