package com.chinasofti.adaptationcenter.tenant.service.impl;

import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.baomidou.mybatisplus.core.metadata.IPage;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import com.baomidou.mybatisplus.extension.service.impl.ServiceImpl;
import com.chinasofti.adaptationcenter.common.exception.BusinessException;
import com.chinasofti.adaptationcenter.tenant.entity.Tenant;
import com.chinasofti.adaptationcenter.tenant.dto.TenantDTO;
import com.chinasofti.adaptationcenter.tenant.query.TenantQuery;
import com.chinasofti.adaptationcenter.tenant.repository.TenantRepository;
import com.chinasofti.adaptationcenter.tenant.service.TenantService;
import lombok.extern.slf4j.Slf4j;
import org.apache.commons.lang3.StringUtils;
import org.springframework.beans.BeanUtils;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.List;
import java.util.Objects;

/**
 * 租户管理服务实现类
 * 
 * @author 中软国际研发团队
 * @since 2025-11-10
 */
@Slf4j
@Service
public class TenantServiceImpl extends ServiceImpl<TenantRepository, Tenant> implements TenantService {

    /**
     * 创建租户
     */
    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long createTenant(TenantDTO tenantDTO, Long operatorId, String operatorName) {
        log.info("开始创建租户，租户编码：{}，操作人：{}", tenantDTO.getTenantCode(), operatorName);

        // 1. 校验租户编码是否已存在
        if (!checkTenantCodeAvailable(tenantDTO.getTenantCode())) {
            log.error("租户编码已存在：{}", tenantDTO.getTenantCode());
            throw new BusinessException("租户编码已存在");
        }

        // 2. 校验数据隔离模式
        if (tenantDTO.getDataIsolationMode() == 1 && StringUtils.isBlank(tenantDTO.getSchemaName())) {
            log.error("独立schema模式必须指定schema名称");
            throw new BusinessException("独立schema模式必须指定schema名称");
        }

        // 3. 创建租户实体
        Tenant tenant = new Tenant();
        BeanUtils.copyProperties(tenantDTO, tenant);

        // 设置默认值
        tenant.setStatus(1); // 默认启用
        tenant.setIsDeleted(0);
        tenant.setCreateUserId(operatorId);
        tenant.setCreateUserName(operatorName);
        tenant.setCreateTime(LocalDateTime.now());
        tenant.setUpdateUserId(operatorId);
        tenant.setUpdateUserName(operatorName);
        tenant.setUpdateTime(LocalDateTime.now());

        // 4. 保存到数据库
        boolean saveResult = this.save(tenant);
        if (!saveResult) {
            log.error("保存租户信息失败：{}", tenantDTO.getTenantCode());
            throw new BusinessException("创建租户失败");
        }

        // 5. 初始化租户数据
        try {
            initializeTenantData(tenant.getTenantId());
        } catch (Exception e) {
            log.error("初始化租户数据失败，租户ID：{}", tenant.getTenantId(), e);
            throw new BusinessException("租户创建成功，但初始化数据失败，请手动初始化");
        }

        log.info("租户创建成功，租户ID：{}，租户编码：{}", tenant.getTenantId(), tenant.getTenantCode());
        return tenant.getTenantId();
    }

    /**
     * 更新租户信息
     */
    @Override
    @Transactional(rollbackFor = Exception.class)
    public boolean updateTenant(TenantDTO tenantDTO, Long operatorId, String operatorName) {
        log.info("开始更新租户信息，租户ID：{}，操作人：{}", tenantDTO.getTenantId(), operatorName);

        // 1. 检查租户是否存在
        Tenant existingTenant = this.getById(tenantDTO.getTenantId());
        if (existingTenant == null || existingTenant.getIsDeleted() == 1) {
            log.error("租户不存在或已删除，租户ID：{}", tenantDTO.getTenantId());
            throw new BusinessException("租户不存在或已删除");
        }

        // 2. 检查租户编码是否重复（排除自身）
        if (!existingTenant.getTenantCode().equals(tenantDTO.getTenantCode())) {
            Integer count = baseMapper.existsByTenantCode(tenantDTO.getTenantCode());
            if (count > 0) {
                log.error("租户编码已存在：{}", tenantDTO.getTenantCode());
                throw new BusinessException("租户编码已存在");
            }
        }

        // 3. 更新租户信息
        Tenant updateTenant = new Tenant();
        BeanUtils.copyProperties(tenantDTO, updateTenant);
        updateTenant.setUpdateUserId(operatorId);
        updateTenant.setUpdateUserName(operatorName);
        updateTenant.setUpdateTime(LocalDateTime.now());

        boolean updateResult = this.updateById(updateTenant);
        if (!updateResult) {
            log.error("更新租户信息失败，租户ID：{}", tenantDTO.getTenantId());
            throw new BusinessException("更新租户失败");
        }

        log.info("租户信息更新成功，租户ID：{}", tenantDTO.getTenantId());
        return true;
    }

    /**
     * 删除租户（逻辑删除）
     */
    @Override
    @Transactional(rollbackFor = Exception.class)
    public boolean deleteTenant(Long tenantId, Long operatorId, String operatorName) {
        log.info("开始删除租户，租户ID：{}，操作人：{}", tenantId, operatorName);

        // 1. 检查租户是否存在
        Tenant tenant = this.getById(tenantId);
        if (tenant == null || tenant.getIsDeleted() == 1) {
            log.error("租户不存在或已删除，租户ID：{}", tenantId);
            throw new BusinessException("租户不存在或已删除");
        }

        // 2. 执行逻辑删除
        Tenant deleteTenant = new Tenant();
        deleteTenant.setTenantId(tenantId);
        deleteTenant.setIsDeleted(1);
        deleteTenant.setUpdateUserId(operatorId);
        deleteTenant.setUpdateUserName(operatorName);
        deleteTenant.setUpdateTime(LocalDateTime.now());

        boolean deleteResult = this.updateById(deleteTenant);
        if (!deleteResult) {
            log.error("删除租户失败，租户ID：{}", tenantId);
            throw new BusinessException("删除租户失败");
        }

        log.info("租户删除成功，租户ID：{}", tenantId);
        return true;
    }

    /**
     * 启用租户
     */
    @Override
    @Transactional(rollbackFor = Exception.class)
    public boolean enableTenant(Long tenantId, Long operatorId, String operatorName) {
        log.info("开始启用租户，租户ID：{}，操作人：{}", tenantId, operatorName);
        return updateTenantStatus(tenantId, 1, operatorId, operatorName);
    }

    /**
     * 禁用租户
     */
    @Override
    @Transactional(rollbackFor = Exception.class)
    public boolean disableTenant(Long tenantId, Long operatorId, String operatorName) {
        log.info("开始禁用租户，租户ID：{}，操作人：{}", tenantId, operatorName);
        return updateTenantStatus(tenantId, 0, operatorId, operatorName);
    }

    /**
     * 更新租户状态
     */
    private boolean updateTenantStatus(Long tenantId, Integer status, Long operatorId, String operatorName) {
        // 1. 检查租户是否存在
        Tenant tenant = this.getById(tenantId);
        if (tenant == null || tenant.getIsDeleted() == 1) {
            log.error("租户不存在或已删除，租户ID：{}", tenantId);
            throw new BusinessException("租户不存在或已删除");
        }

        // 2. 检查状态是否已为目标状态
        if (Objects.equals(tenant.getStatus(), status)) {
            log.warn("租户状态已是目标状态，租户ID：{}，当前状态：{}", tenantId, status);
            return true;
        }

        // 3. 更新状态
        Tenant updateTenant = new Tenant();
        updateTenant.setTenantId(tenantId);
        updateTenant.setStatus(status);
        updateTenant.setUpdateUserId(operatorId);
        updateTenant.setUpdateUserName(operatorName);
        updateTenant.setUpdateTime(LocalDateTime.now());

        boolean updateResult = this.updateById(updateTenant);
        if (!updateResult) {
            log.error("更新租户状态失败，租户ID：{}，目标状态：{}", tenantId, status);
            throw new BusinessException("更新租户状态失败");
        }

        log.info("租户状态更新成功，租户ID：{}，新状态：{}", tenantId, status);
        return true;
    }

    /**
     * 根据租户编码查询租户
     */
    @Override
    public Tenant getByTenantCode(String tenantCode) {
        log.debug("根据租户编码查询租户：{}", tenantCode);
        return baseMapper.selectByTenantCode(tenantCode);
    }

    /**
     * 分页查询租户列表
     */
    @Override
    public IPage<Tenant> queryTenantPage(TenantQuery query, Integer pageNum, Integer pageSize) {
        log.debug("分页查询租户列表，页码：{}，页大小：{}，查询条件：{}", pageNum, pageSize, query);

        Page<Tenant> page = new Page<>(pageNum, pageSize);
        LambdaQueryWrapper<Tenant> wrapper = new LambdaQueryWrapper<>();

        // 构建查询条件
        wrapper.eq(Tenant::getIsDeleted, 0);

        if (StringUtils.isNotBlank(query.getTenantCode())) {
            wrapper.like(Tenant::getTenantCode, query.getTenantCode());
        }

        if (StringUtils.isNotBlank(query.getTenantName())) {
            wrapper.like(Tenant::getTenantName, query.getTenantName());
        }

        if (StringUtils.isNotBlank(query.getContactName())) {
            wrapper.like(Tenant::getContactName, query.getContactName());
        }

        if (StringUtils.isNotBlank(query.getContactPhone())) {
            wrapper.like(Tenant::getContactPhone, query.getContactPhone());
        }

        if (query.getStatus() != null) {
            wrapper.eq(Tenant::getStatus, query.getStatus());
        }

        if (query.getDataIsolationMode() != null) {
            wrapper.eq(Tenant::getDataIsolationMode, query.getDataIsolationMode());
        }

        if (StringUtils.isNotBlank(query.getCreateTimeStart())) {
            wrapper.ge(Tenant::getCreateTime, query.getCreateTimeStart() + " 00:00:00");
        }

        if (StringUtils.isNotBlank(query.getCreateTimeEnd())) {
            wrapper.le(Tenant::getCreateTime, query.getCreateTimeEnd() + " 23:59:59");
        }

        // 按创建时间倒序排列
        wrapper.orderByDesc(Tenant::getCreateTime);

        return this.page(page, wrapper);
    }

    /**
     * 查询所有启用的租户
     */
    @Override
    public List<Tenant> listEnabledTenants() {
        log.debug("查询所有启用的租户");
        LambdaQueryWrapper<Tenant> wrapper = new LambdaQueryWrapper<>();
        wrapper.eq(Tenant::getStatus, 1)
               .eq(Tenant::getIsDeleted, 0)
               .orderByAsc(Tenant::getTenantId);
        return this.list(wrapper);
    }

    /**
     * 检查租户编码是否可用
     */
    @Override
    public boolean checkTenantCodeAvailable(String tenantCode) {
        log.debug("检查租户编码是否可用：{}", tenantCode);
        Integer count = baseMapper.existsByTenantCode(tenantCode);
        return count == 0;
    }

