package com.cssoft.adaptation.test.management.service.impl;

import com.cssoft.adaptation.test.management.entity.Project;
import com.cssoft.adaptation.test.management.repository.ProjectRepository;
import com.cssoft.adaptation.test.management.service.ProjectService;
import com.cssoft.adaptation.test.management.dto.ProjectCreateDTO;
import com.cssoft.adaptation.test.management.dto.ProjectUpdateDTO;
import com.cssoft.adaptation.test.management.dto.ProjectQueryDTO;
import com.cssoft.adaptation.test.management.vo.ProjectVO;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import com.baomidou.mybatisplus.extension.service.impl.ServiceImpl;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.apache.commons.lang3.StringUtils;
import org.springframework.beans.BeanUtils;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.List;
import java.util.stream.Collectors;

/**
 * 测试项目管理服务实现类
 * 
 * @author System
 * @since 2025-11-10
 */
@Slf4j
@Service
@RequiredArgsConstructor
public class ProjectServiceImpl extends ServiceImpl<ProjectRepository, Project> implements ProjectService {

    private final ProjectRepository projectRepository;

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long createProject(ProjectCreateDTO createDTO, Long userId, String userName) {
        log.info("开始创建测试项目，项目名称：{}, 创建人：{}", createDTO.getProjectName(), userName);

        // 校验项目编号是否已存在
        if (projectRepository.existsByProjectCode(createDTO.getProjectCode(), createDTO.getTenantId())) {
            log.error("项目编号已存在：{}，租户ID：{}", createDTO.getProjectCode(), createDTO.getTenantId());
            throw new RuntimeException("项目编号已存在");
        }

        // 构建项目实体
        Project project = Project.builder()
                .projectCode(createDTO.getProjectCode())
                .projectName(createDTO.getProjectName())
                .projectDesc(createDTO.getProjectDesc())
                .projectLeaderId(createDTO.getProjectLeaderId())
                .projectLeaderName(createDTO.getProjectLeaderName())
                .departmentId(createDTO.getDepartmentId())
                .departmentName(createDTO.getDepartmentName())
                .tenantId(createDTO.getTenantId())
                .tenantName(createDTO.getTenantName())
                .processTemplateId(createDTO.getProcessTemplateId())
                .processTemplateName(createDTO.getProcessTemplateName())
                .projectStatus(0) // 默认未开始
                .projectType(createDTO.getProjectType())
                .priority(createDTO.getPriority())
                .planStartTime(createDTO.getPlanStartTime())
                .planEndTime(createDTO.getPlanEndTime())
                .testEnvInfo(createDTO.getTestEnvInfo())
                .projectConfig(createDTO.getProjectConfig())
                .isDeleted(0)
                .createBy(userId)
                .createByName(userName)
                .remark(createDTO.getRemark())
                .build();

        // 保存项目信息
        boolean success = this.save(project);
        if (!success) {
            log.error("创建测试项目失败，项目名称：{}", createDTO.getProjectName());
            throw new RuntimeException("创建测试项目失败");
        }

        log.info("测试项目创建成功，项目ID：{}，项目编号：{}", project.getId(), project.getProjectCode());
        return project.getId();
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public boolean updateProject(ProjectUpdateDTO updateDTO, Long userId, String userName) {
        log.info("开始更新测试项目，项目ID：{}，更新人：{}", updateDTO.getId(), userName);

        // 查询项目是否存在
        Project project = this.getById(updateDTO.getId());
        if (project == null || project.getIsDeleted() == 1) {
            log.error("测试项目不存在或已删除，项目ID：{}", updateDTO.getId());
            throw new RuntimeException("测试项目不存在或已删除");
        }

        // 更新项目信息
        project.setProjectName(updateDTO.getProjectName());
        project.setProjectDesc(updateDTO.getProjectDesc());
        project.setProjectLeaderId(updateDTO.getProjectLeaderId());
        project.setProjectLeaderName(updateDTO.getProjectLeaderName());
        project.setDepartmentId(updateDTO.getDepartmentId());
        project.setDepartmentName(updateDTO.getDepartmentName());
        project.setProcessTemplateId(updateDTO.getProcessTemplateId());
        project.setProcessTemplateName(updateDTO.getProcessTemplateName());
        project.setProjectType(updateDTO.getProjectType());
        project.setPriority(updateDTO.getPriority());
        project.setPlanStartTime(updateDTO.getPlanStartTime());
        project.setPlanEndTime(updateDTO.getPlanEndTime());
        project.setTestEnvInfo(updateDTO.getTestEnvInfo());
        project.setProjectConfig(updateDTO.getProjectConfig());
        project.setUpdateBy(userId);
        project.setUpdateByName(userName);
        project.setUpdateTime(LocalDateTime.now());
        project.setRemark(updateDTO.getRemark());

        boolean success = this.updateById(project);
        if (success) {
            log.info("测试项目更新成功，项目ID：{}", updateDTO.getId());
        } else {
            log.error("测试项目更新失败，项目ID：{}", updateDTO.getId());
        }

        return success;
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public boolean deleteProject(Long projectId, Long userId, String userName) {
        log.info("开始删除测试项目，项目ID：{}，操作人：{}", projectId, userName);

        Project project = this.getById(projectId);
        if (project == null || project.getIsDeleted() == 1) {
            log.error("测试项目不存在或已删除，项目ID：{}", projectId);
            throw new RuntimeException("测试项目不存在或已删除");
        }

        // 逻辑删除
        project.setIsDeleted(1);
        project.setUpdateBy(userId);
        project.setUpdateByName(userName);
        project.setUpdateTime(LocalDateTime.now());

        boolean success = this.updateById(project);
        if (success) {
            log.info("测试项目删除成功，项目ID：{}", projectId);
        } else {
            log.error("测试项目删除失败，项目ID：{}", projectId);
        }

        return success;
    }

    @Override
    public ProjectVO getProjectById(Long projectId) {
        log.debug("查询测试项目详情，项目ID：{}", projectId);

        Project project = this.getById(projectId);
        if (project == null || project.getIsDeleted() == 1) {
            log.warn("测试项目不存在或已删除，项目ID：{}", projectId);
            return null;
        }

        return convertToVO(project);
    }

    @Override
    public ProjectVO getProjectByCode(String projectCode, Long tenantId) {
        log.debug("根据项目编号查询测试项目，项目编号：{}，租户ID：{}", projectCode, tenantId);

        Project project = projectRepository.selectByProjectCode(projectCode);
        if (project == null || !project.getTenantId().equals(tenantId) || project.getIsDeleted() == 1) {
            log.warn("测试项目不存在或不属于该租户，项目编号：{}，租户ID：{}", projectCode, tenantId);
            return null;
        }

        return convertToVO(project);
    }

    @Override
    public List<ProjectVO> listProjects(ProjectQueryDTO queryDTO, Long tenantId, Integer pageNum, Integer pageSize) {
        log.debug("查询测试项目列表，租户ID：{}，查询条件：{}", tenantId, queryDTO);

        LambdaQueryWrapper<Project> queryWrapper = new LambdaQueryWrapper<>();
        queryWrapper.eq(Project::getTenantId, tenantId)
                    .eq(Project::getIsDeleted, 0);

        // 条件筛选
        if (StringUtils.isNotBlank(queryDTO.getProjectName())) {
            queryWrapper.like(Project::getProjectName, queryDTO.getProjectName());
        }

        if (StringUtils.isNotBlank(queryDTO.getProjectCode())) {
            queryWrapper.eq(Project::getProjectCode, queryDTO.getProjectCode());
        }

        if (queryDTO.getProjectStatus() != null) {
            queryWrapper.eq(Project::getProjectStatus, queryDTO.getProjectStatus());
        }

        if (queryDTO.getProjectType() != null) {
            queryWrapper.eq(Project::getProjectType, queryDTO.getProjectType());
        }

        if (queryDTO.getProjectLeaderId() != null) {
            queryWrapper.eq(Project::getProjectLeaderId, queryDTO.getProjectLeaderId());
        }

        if (queryDTO.getDepartmentId() != null) {
            queryWrapper.eq(Project::getDepartmentId, queryDTO.getDepartmentId());
        }

        // 分页查询
        Page<Project> page = new Page<>(pageNum, pageSize);
        Page<Project> projectPage = this.page(page, queryWrapper);

        // 转换为VO列表
        return projectPage.getRecords().stream()
                .map(this::convertToVO)
                .collect(Collectors.toList());
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public boolean updateProjectStatus(Long projectId, Integer status, Long userId, String userName) {
        log.info("更新测试项目状态，项目ID：{}，新状态：{}，操作人：{}", projectId, status, userName);

        Project project = this.getById(projectId);
        if (project == null || project.getIsDeleted() == 1) {
            log.error("测试项目不存在或已删除，项目ID：{}", projectId);
            throw new RuntimeException("测试项目不存在或已删除");
        }

        // 更新状态
        project.setProjectStatus(status);
        project.setUpdateBy(userId);
        project.setUpdateByName(userName);
        project.setUpdateTime(LocalDateTime.now());

        // 如果状态变更为进行中且实际开始时间为空，则设置实际开始时间
        if (status == 1 && project.getActualStartTime() == null) {
            project.setActualStartTime(LocalDateTime.now());
        }

        // 如果状态变更为已完成或已关闭，则设置实际结束时间
        if ((status == 3 || status == 4) && project.getActualEndTime() == null) {
            project.setActualEndTime(LocalDateTime.now());
        }

        boolean success = this.updateById(project);
        if (success) {
            log.info("测试项目状态更新成功，项目ID：{}，新状态：{}", projectId, status);
        } else {
            log.error("测试项目状态更新失败，项目ID：{}", projectId);
        }

        return success;
    }

    @Override
    public Long countProjects(Long tenantId, Integer status) {
        log.debug("统计测试项目数量，租户ID：{}，状态：{}", tenantId, status);

        LambdaQueryWrapper<Project> queryWrapper = new LambdaQueryWrapper<>();
        queryWrapper.eq(Project::getTenantId, tenantId)
                    .eq(Project::getIsDeleted, 0);

        if (status != null) {
            queryWrapper.eq(Project::getProjectStatus, status);
        }

        return this.count(queryWrapper);
    }

    @Override
    public boolean validateProjectTenant(Long projectId, Long tenantId) {
        log.debug("验证项目租户权限，项目ID：{}，租户ID：{}", projectId, tenantId);

        Project project = this.getById(projectId);
        if (project == null || project.getIsDeleted() == 1) {
            log.warn("测试项目不存在或已删除，项目ID：{}", projectId);
            return false;
        }

        return project.getTenantId().equals(tenantId);
    }

    /**
     * 将Project实体转换为ProjectVO
     * 
     * @param project 项目实体
     * @return 项目VO
     */
    private ProjectVO convertToVO(Project project) {
        ProjectVO vo = new ProjectVO();
        BeanUtils.copyProperties(project, vo);
        return vo;
    }
}
