    @Override
    @Transactional(rollbackFor = Exception.class)
    public TestCase createTestCase(TestCase testCase, Long userId) {
        log.info("开始创建测试用例，创建人ID：{}，用例名称：{}", userId, testCase.getCaseName());

        try {
            // 生成用例编号
            String caseCode = generateCaseCode(testCase.getProjectId());
            testCase.setCaseCode(caseCode);

            // 设置创建信息
            testCase.setCreatorId(userId);
            testCase.setCreatorName(getUserName(userId));
            testCase.setStatus(0); // 草稿状态
            testCase.setVersion("1.0");
            testCase.setExecutionCount(0);
            testCase.setPassCount(0);
            testCase.setDeleted(false);
            testCase.setCreateTime(LocalDateTime.now());
            testCase.setUpdateTime(LocalDateTime.now());

            // 保存用例
            int result = testCaseRepository.insert(testCase);
            if (result > 0) {
                log.info("测试用例创建成功，用例ID：{}，用例编号：{}", testCase.getId(), caseCode);

                // 保存版本历史
                saveVersionHistory(testCase, "初始版本", userId);

                return testCase;
            } else {
                log.error("测试用例创建失败，数据库插入返回结果为0");
                throw new RuntimeException("测试用例创建失败");
            }
        } catch (Exception e) {
            log.error("创建测试用例异常，用户ID：{}，错误信息：{}", userId, e.getMessage(), e);
            throw new RuntimeException("创建测试用例失败：" + e.getMessage());
        }
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public TestCase updateTestCase(TestCase testCase, Long userId) {
        log.info("开始更新测试用例，更新人ID：{}，用例ID：{}", userId, testCase.getId());

        try {
            // 查询原用例
            TestCase existingCase = testCaseRepository.selectById(testCase.getId());
            if (existingCase == null || existingCase.getDeleted()) {
                log.error("测试用例不存在或已被删除，用例ID：{}", testCase.getId());
                throw new RuntimeException("测试用例不存在");
            }

            // 保存版本历史
            saveVersionHistory(existingCase, "更新用例", userId);

            // 设置更新信息
            testCase.setUpdaterId(userId);
            testCase.setUpdateTime(LocalDateTime.now());

            // 如果版本变更，生成新版本号
            if (!existingCase.getVersion().equals(testCase.getVersion())) {
                testCase.setVersion(generateNextVersion(existingCase.getVersion()));
            }

            // 更新用例
            int result = testCaseRepository.updateById(testCase);
            if (result > 0) {
                log.info("测试用例更新成功，用例ID：{}", testCase.getId());
                return testCase;
            } else {
                log.error("测试用例更新失败，数据库更新返回结果为0");
                throw new RuntimeException("测试用例更新失败");
            }
        } catch (Exception e) {
            log.error("更新测试用例异常，用户ID：{}，用例ID：{}，错误信息：{}", 
                userId, testCase.getId(), e.getMessage(), e);
            throw new RuntimeException("更新测试用例失败：" + e.getMessage());
        }
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public boolean deleteTestCase(Long caseId, Long userId) {
        log.info("开始删除测试用例，删除人ID：{}，用例ID：{}", userId, caseId);

        try {
            TestCase testCase = testCaseRepository.selectById(caseId);
            if (testCase == null) {
                log.error("测试用例不存在，用例ID：{}", caseId);
                return false;
            }

            // 逻辑删除
            testCase.setDeleted(true);
            testCase.setUpdaterId(userId);
            testCase.setUpdateTime(LocalDateTime.now());

            int result = testCaseRepository.updateById(testCase);
            if (result > 0) {
                log.info("测试用例删除成功，用例ID：{}", caseId);
                return true;
            } else {
                log.error("测试用例删除失败，数据库更新返回结果为0");
                return false;
            }
        } catch (Exception e) {
            log.error("删除测试用例异常，用户ID：{}，用例ID：{}，错误信息：{}", 
                userId, caseId, e.getMessage(), e);
            throw new RuntimeException("删除测试用例失败：" + e.getMessage());
        }
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public boolean batchDeleteTestCase(List<Long> caseIds, Long userId) {
        log.info("开始批量删除测试用例，删除人ID：{}，用例数量：{}", userId, caseIds.size());

        try {
            List<TestCase> testCases = testCaseRepository.selectBatchIds(caseIds);
            for (TestCase testCase : testCases) {
                if (testCase != null) {
                    testCase.setDeleted(true);
                    testCase.setUpdaterId(userId);
                    testCase.setUpdateTime(LocalDateTime.now());
                    testCaseRepository.updateById(testCase);
                }
            }

            log.info("批量删除测试用例成功，删除数量：{}", testCases.size());
            return true;
        } catch (Exception e) {
            log.error("批量删除测试用例异常，用户ID：{}，错误信息：{}", userId, e.getMessage(), e);
            throw new RuntimeException("批量删除测试用例失败：" + e.getMessage());
        }
    }

