package com.chinasofti.adapter.testmanagement.service.impl;

import com.chinasofti.adapter.testmanagement.dto.TestCaseDTO;
import com.chinasofti.adapter.testmanagement.dto.TestCaseQueryDTO;
import com.chinasofti.adapter.testmanagement.dto.TestCaseRelationDTO;
import com.chinasofti.adapter.testmanagement.entity.*;
import com.chinasofti.adapter.testmanagement.repository.*;
import com.chinasofti.adapter.testmanagement.service.TestCaseService;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.BeanUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.domain.Specification;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.util.StringUtils;
import org.springframework.web.multipart.MultipartFile;

import javax.persistence.criteria.Predicate;
import java.time.LocalDateTime;
import java.util.*;
import java.util.stream.Collectors;

/**
 * 测试用例服务实现类
 */
@Slf4j
@Service
@Transactional
public class TestCaseServiceImpl implements TestCaseService {

    @Autowired
    private TestCaseRepository testCaseRepository;

    @Autowired
    private RequirementRepository requirementRepository;

    @Autowired
    private BugRepository bugRepository;

    @Autowired
    private TestCaseCategoryRepository categoryRepository;

    @Autowired
    private TestCaseTaskRelationRepository taskRelationRepository;

    @Override
    public TestCase createTestCase(TestCaseDTO testCaseDTO) {
        log.info("开始创建测试用例，标题：{}", testCaseDTO.getTitle());

        // 生成用例编号
        String caseCode = generateCaseCode(testCaseDTO.getProjectId());

        TestCase testCase = new TestCase();
        BeanUtils.copyProperties(testCaseDTO, testCase, "id", "caseCode");
        testCase.setCaseCode(caseCode);
        testCase.setStatus("DRAFT");
        testCase.setVersion(1);
        testCase.setCreateTime(LocalDateTime.now());
        testCase.setUpdateTime(LocalDateTime.now());

        TestCase savedCase = testCaseRepository.save(testCase);

        log.info("测试用例创建成功，ID：{}，编号：{}", savedCase.getId(), savedCase.getCaseCode());
        return savedCase;
    }

    @Override
    public TestCase updateTestCase(Long id, TestCaseDTO testCaseDTO) {
        log.info("开始更新测试用例，ID：{}", id);

        TestCase existingCase = testCaseRepository.findById(id)
            .orElseThrow(() -> new RuntimeException("测试用例不存在，ID：" + id));

        // 创建新版本
        TestCase newVersion = new TestCase();
        BeanUtils.copyProperties(existingCase, newVersion, "id", "version", "createTime");
        BeanUtils.copyProperties(testCaseDTO, newVersion, "id", "caseCode", "version");

        // 版本号递增
        newVersion.setVersion(existingCase.getVersion() + 1);
        newVersion.setUpdateTime(LocalDateTime.now());

        TestCase updatedCase = testCaseRepository.save(newVersion);

        log.info("测试用例更新成功，ID：{}，新版本：{}", id, updatedCase.getVersion());
        return updatedCase;
    }

    @Override
    public TestCase getTestCaseById(Long id) {
        log.debug("查询测试用例，ID：{}", id);
        return testCaseRepository.findById(id)
            .orElseThrow(() -> new RuntimeException("测试用例不存在，ID：" + id));
    }

    @Override
    public TestCase getTestCaseByCode(String caseCode) {
        log.debug("查询测试用例，编号：{}", caseCode);
        return testCaseRepository.findByCaseCode(caseCode)
            .orElseThrow(() -> new RuntimeException("测试用例不存在，编号：" + caseCode));
    }

    @Override
    public void deleteTestCase(Long id) {
        log.info("删除测试用例，ID：{}", id);

        TestCase testCase = testCaseRepository.findById(id)
            .orElseThrow(() -> new RuntimeException("测试用例不存在，ID：" + id));

        // 逻辑删除，更新状态为废弃
        testCase.setStatus("DEPRECATED");
        testCase.setUpdateTime(LocalDateTime.now());
        testCaseRepository.save(testCase);

        log.info("测试用例已标记为废弃，ID：{}", id);
    }

    @Override
    public Page<TestCase> queryTestCases(TestCaseQueryDTO queryDTO, Pageable pageable) {
        log.debug("查询测试用例列表，项目ID：{}，分类ID：{}", 
                 queryDTO.getProjectId(), queryDTO.getCategoryId());

        Specification<TestCase> spec = (root, query, cb) -> {
            List<Predicate> predicates = new ArrayList<>();

            // 项目ID筛选
            if (queryDTO.getProjectId() != null) {
                predicates.add(cb.equal(root.get("projectId"), queryDTO.getProjectId()));
            }

            // 分类ID筛选
            if (queryDTO.getCategoryId() != null) {
                predicates.add(cb.equal(root.get("categoryId"), queryDTO.getCategoryId()));
            }

            // 状态筛选
            if (StringUtils.hasText(queryDTO.getStatus())) {
                predicates.add(cb.equal(root.get("status"), queryDTO.getStatus()));
            }

            // 类型筛选
            if (StringUtils.hasText(queryDTO.getCaseType())) {
                predicates.add(cb.equal(root.get("caseType"), queryDTO.getCaseType()));
            }

            // 优先级筛选
            if (StringUtils.hasText(queryDTO.getPriority())) {
                predicates.add(cb.equal(root.get("priority"), queryDTO.getPriority()));
            }

            // 关键字搜索（标题或描述）
            if (StringUtils.hasText(queryDTO.getKeyword())) {
                String likePattern = "%" + queryDTO.getKeyword() + "%";
                Predicate titlePredicate = cb.like(root.get("title"), likePattern);
                Predicate descPredicate = cb.like(root.get("description"), likePattern);
                predicates.add(cb.or(titlePredicate, descPredicate));
            }

            // 标签筛选
            if (StringUtils.hasText(queryDTO.getTag())) {
                predicates.add(cb.like(root.get("tags"), "%" + queryDTO.getTag() + "%"));
            }

            // 租户ID筛选
            if (queryDTO.getTenantId() != null) {
                predicates.add(cb.equal(root.get("tenantId"), queryDTO.getTenantId()));
            }

            // 排除已废弃的用例
            predicates.add(cb.notEqual(root.get("status"), "DEPRECATED"));

            return cb.and(predicates.toArray(new Predicate[0]));
        };

        return testCaseRepository.findAll(spec, pageable);
    }

