                    map.put("reqCode", req.getReqCode());
                    map.put("title", req.getTitle());
                    map.put("status", req.getStatus());
                    return map;
                })
                .collect(Collectors.toList());
            relationDTO.setRequirements(reqList);
        }

        // 获取关联的缺陷
        if (testCase.getBugs() != null) {
            List<Map<String, Object>> bugList = testCase.getBugs().stream()
                .map(bug -> {
                    Map<String, Object> map = new HashMap<>();
                    map.put("id", bug.getId());
