                    map.put("title", bug.getTitle());
                    map.put("severity", bug.getSeverity());
                    map.put("status", bug.getStatus());
                    return map;
                })
                .collect(Collectors.toList());
            relationDTO.setBugs(bugList);
        }

        // 获取关联的任务
        List<TestCaseTaskRelation> taskRelations = taskRelationRepository.findByCaseId(caseId);
        if (!taskRelations.isEmpty()) {
            List<Map<String, Object>> taskList = taskRelations.stream()
                .map(rel -> {
