@Slf4j
@Service
public class IntelligentSchedulingServiceImpl extends ServiceImpl<TestTaskMapper, TestTask> 
        implements IntelligentSchedulingService {

    @Autowired
    private TestTaskMapper testTaskMapper;

    @Autowired
    private TestEngineerMapper testEngineerMapper;

    @Autowired
    private TaskAssignmentRecordMapper taskAssignmentRecordMapper;

    // 技能匹配权重
    private static final double SKILL_MATCH_WEIGHT = 0.35;
    // 负载均衡权重
    private static final double WORKLOAD_BALANCE_WEIGHT = 0.25;
    // 任务优先级权重
    private static final double PRIORITY_WEIGHT = 0.20;
    // 绩效评分权重
    private static final double PERFORMANCE_WEIGHT = 0.15;
    // 设备匹配权重
    private static final double DEVICE_MATCH_WEIGHT = 0.05;

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Map<String, Object> intelligentAssignTask(Long taskId) {
        log.info("开始智能分配任务，任务ID: {}", taskId);
        Map<String, Object> result = new HashMap<>();

        try {
            // 1. 获取任务信息
            TestTask task = testTaskMapper.selectById(taskId);
            if (task == null || task.getIsDeleted() == 1) {
                result.put("success", false);
                result.put("message", "任务不存在或已被删除");
                return result;
            }

            if (task.getStatus() != 0) {
                result.put("success", false);
                result.put("message", "任务状态不是待分配状态");
                return result;
            }

            // 2. 获取所有可用测试人员
            List<TestEngineer> availableEngineers = testEngineerMapper.selectAvailableEngineers();
            if (availableEngineers.isEmpty()) {
                result.put("success", false);
                result.put("message", "当前没有可用的测试人员");
                return result;
            }

            // 3. 计算每个测试人员的匹配得分
            List<Map<String, Object>> scoreList = calculateEngineerScores(task, availableEngineers);

            // 4. 选择得分最高的测试人员
            Map<String, Object> bestMatch = scoreList.stream()
                    .max(Comparator.comparingDouble(s -> (Double) s.get("totalScore")))
                    .orElse(null);

            if (bestMatch == null || (Double) bestMatch.get("totalScore") < 0.6) {
                result.put("success", false);
                result.put("message", "没有找到合适的测试人员（得分低于阈值）");
                result.put("recommendations", scoreList);
                return result;
            }

            Long bestEngineerId = (Long) bestMatch.get("engineerId");
            Double bestScore = (Double) bestMatch.get("totalScore");

            // 5. 执行分配
            boolean assignSuccess = assignTaskToEngineer(taskId, bestEngineerId, bestScore, 0);

            if (assignSuccess) {
                result.put("success", true);
                result.put("message", "任务分配成功");
                result.put("taskId", taskId);
                result.put("engineerId", bestEngineerId);
                result.put("score", bestScore);
                result.put("assignmentDetails", bestMatch);

                log.info("任务分配成功，任务ID: {} -> 测试人员ID: {}, 得分: {}", 
                        taskId, bestEngineerId, bestScore);
            } else {
                result.put("success", false);
                result.put("message", "任务分配失败");
            }

        } catch (Exception e) {
            log.error("智能分配任务失败，任务ID: {}", taskId, e);
            result.put("success", false);
            result.put("message", "系统错误: " + e.getMessage());
            throw new RuntimeException("智能分配任务失败", e);
        }

        return result;
    }

    /**
     * 计算测试人员匹配得分
     */
    private List<Map<String, Object>> calculateEngineerScores(TestTask task, List<TestEngineer> engineers) {
        List<Map<String, Object>> scoreList = new ArrayList<>();

        // 解析任务所需技能
        List<String> requiredSkills = parseJsonArray(task.getRequiredSkills());
        // 解析任务设备依赖
        List<String> requiredDevices = parseJsonArray(task.getDeviceDependencies());

        for (TestEngineer engineer : engineers) {
            Map<String, Object> scoreMap = new HashMap<>();
            scoreMap.put("engineerId", engineer.getId());
            scoreMap.put("engineerName", engineer.getEmployeeNo());

            // 1. 技能匹配得分
            List<String> engineerSkills = parseJsonArray(engineer.getSkillTags());
            double skillMatchScore = calculateSkillMatchScore(requiredSkills, engineerSkills);
            scoreMap.put("skillMatchScore", skillMatchScore);

            // 2. 负载均衡得分
            double workloadScore = calculateWorkloadScore(engineer, task.getEstimatedHours());
            scoreMap.put("workloadScore", workloadScore);

            // 3. 任务优先级调整得分
            double priorityScore = calculatePriorityScore(task.getPriority());
            scoreMap.put("priorityScore", priorityScore);

            // 4. 绩效得分
            double performanceScore = engineer.getPerformanceScore() != null ? 
                    engineer.getPerformanceScore() / 5.0 : 0.7;
            scoreMap.put("performanceScore", performanceScore);

            // 5. 设备匹配得分
            List<String> availableDevices = parseJsonArray(engineer.getAvailableDevices());
            double deviceMatchScore = calculateDeviceMatchScore(requiredDevices, availableDevices);
            scoreMap.put("deviceMatchScore", deviceMatchScore);

            // 6. 计算总分（加权平均）
            double totalScore = skillMatchScore * SKILL_MATCH_WEIGHT +
                              workloadScore * WORKLOAD_BALANCE_WEIGHT +
                              priorityScore * PRIORITY_WEIGHT +
                              performanceScore * PERFORMANCE_WEIGHT +
                              deviceMatchScore * DEVICE_MATCH_WEIGHT;

            scoreMap.put("totalScore", totalScore);

            // 7. 详细得分说明
            scoreMap.put("scoreBreakdown", String.format(
                    "技能匹配: %.2f*%.2f=%.3f, 负载均衡: %.2f*%.2f=%.3f, 优先级: %.2f*%.2f=%.3f, 绩效: %.2f*%.2f=%.3f, 设备匹配: %.2f*%.2f=%.3f",
                    skillMatchScore, SKILL_MATCH_WEIGHT, skillMatchScore * SKILL_MATCH_WEIGHT,
                    workloadScore, WORKLOAD_BALANCE_WEIGHT, workloadScore * WORKLOAD_BALANCE_WEIGHT,
                    priorityScore, PRIORITY_WEIGHT, priorityScore * PRIORITY_WEIGHT,
                    performanceScore, PERFORMANCE_WEIGHT, performanceScore * PERFORMANCE_WEIGHT,
                    deviceMatchScore, DEVICE_MATCH_WEIGHT, deviceMatchScore * DEVICE_MATCH_WEIGHT
            ));

            scoreList.add(scoreMap);
        }

        // 按总分降序排序
        scoreList.sort((a, b) -> Double.compare((Double) b.get("totalScore"), (Double) a.get("totalScore")));

        return scoreList;
    }

    /**
     * 计算技能匹配得分
     */
    private double calculateSkillMatchScore(List<String> requiredSkills, List<String> engineerSkills) {
        if (requiredSkills == null || requiredSkills.isEmpty()) {
            return 1.0; // 没有技能要求，默认匹配
        }

        if (engineerSkills == null || engineerSkills.isEmpty()) {
            return 0.0; // 测试人员没有技能，完全不匹配
        }

        // 计算匹配的技能数量
        long matchedSkills = requiredSkills.stream()
                .filter(engineerSkills::contains)
                .count();

        // 返回匹配比例
        return (double) matchedSkills / requiredSkills.size();
    }

    /**
     * 计算负载均衡得分
     */
    private double calculateWorkloadScore(TestEngineer engineer, Double taskEstimatedHours) {
        if (engineer.getMaxWorkload() == null || engineer.getMaxWorkload() <= 0) {
            return 0.5; // 默认得分
        }

        double currentLoad = engineer.getCurrentWorkload() != null ? engineer.getCurrentWorkload() : 0;
        double estimatedHours = taskEstimatedHours != null ? taskEstimatedHours : 4.0;
        double predictedLoad = currentLoad + estimatedHours;

        // 如果预测负载超过最大负载，得分为0
        if (predictedLoad > engineer.getMaxWorkload()) {
            return 0.0;
        }

        // 计算负载率，负载率越低得分越高
        double loadRatio = predictedLoad / engineer.getMaxWorkload();
        return 1.0 - loadRatio;
    }

    /**
     * 计算优先级得分
     */
    private double calculatePriorityScore(Integer priority) {
        if (priority == null) {
            return 0.5;
        }

        // 优先级越高，得分越高
        switch (priority) {
            case 1: return 0.3; // 低
            case 2: return 0.5; // 中
            case 3: return 0.8; // 高
            case 4: return 1.0; // 紧急
            default: return 0.5;
        }
    }

    /**
     * 计算设备匹配得分
     */
    private double calculateDeviceMatchScore(List<String> requiredDevices, List<String> availableDevices) {
        if (requiredDevices == null || requiredDevices.isEmpty()) {
            return 1.0; // 没有设备要求，默认匹配
        }

        if (availableDevices == null || availableDevices.isEmpty()) {
            return 0.0; // 没有可用设备，完全不匹配
        }

        // 计算匹配的设备数量
        long matchedDevices = requiredDevices.stream()
                .filter(availableDevices::contains)
                .count();

        // 返回匹配比例
        return (double) matchedDevices / requiredDevices.size();
    }

    /**
     * 解析JSON数组字符串
     */
    private List<String> parseJsonArray(String jsonStr) {
        if (!StringUtils.hasText(jsonStr)) {
            return new ArrayList<>();
        }

        try {
            return JSON.parseArray(jsonStr, String.class);
        } catch (Exception e) {
            log.warn("解析JSON数组失败: {}", jsonStr, e);
            return new ArrayList<>();
        }
    }

    /**
     * 执行任务分配
     */
    @Transactional(rollbackFor = Exception.class)
    private boolean assignTaskToEngineer(Long taskId, Long engineerId, Double score, Integer assignmentType) {
        try {
            // 1. 更新任务状态
            TestTask task = new TestTask();
            task.setId(taskId);
            task.setAssignedEngineerId(engineerId);
            task.setStatus(1); // 已分配
            task.setUpdateTime(LocalDateTime.now());
            testTaskMapper.updateById(task);

            // 2. 更新测试人员当前任务
            TestEngineer engineer = new TestEngineer();
            engineer.setId(engineerId);
            engineer.setCurrentTaskId(taskId);
            if (task.getEstimatedHours() != null) {
                // 更新工作负载
                testEngineerMapper.updateEngineerWorkload(engineerId, task.getEstimatedHours());
            }
            testEngineerMapper.updateById(engineer);

            // 3. 创建分配记录
            TaskAssignmentRecord record = new TaskAssignmentRecord();
            record.setTaskId(taskId);
            record.setEngineerId(engineerId);
            record.setAssignmentType(assignmentType); // 0-智能分配
            record.setAssignmentScore(score);
            record.setAssignTime(LocalDateTime.now());
            record.setAssignmentReason("智能调度算法分配");

            taskAssignmentRecordMapper.insert(record);

            log.info("任务分配完成，任务ID: {} -> 测试人员ID: {}, 分配类型: {}", 
                    taskId, engineerId, assignmentType);

            return true;

        } catch (Exception e) {
            log.error("分配任务失败，任务ID: {}, 测试人员ID: {}", taskId, engineerId, e);
            return false;
        }
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Map<String, Object> batchIntelligentAssign(List<Long> taskIds) {
        log.info("开始批量智能分配任务，任务数量: {}", taskIds.size());
        Map<String, Object> result = new HashMap<>();
        List<Map<String, Object>> assignmentResults = new ArrayList<>();
        int successCount = 0;
        int failCount = 0;

        for (Long taskId : taskIds) {
            Map<String, Object> singleResult = intelligentAssignTask(taskId);
            singleResult.put("taskId", taskId);
            assignmentResults.add(singleResult);

            if (Boolean.TRUE.equals(singleResult.get("success"))) {
                successCount++;
            } else {
                failCount++;
            }
        }

        result.put("success", successCount > 0);
        result.put("totalTasks", taskIds.size());
        result.put("successCount", successCount);
        result.put("failCount", failCount);
        result.put("assignmentResults", assignmentResults);
        result.put("message", String.format("批量分配完成，成功%d个，失败%d个", successCount, failCount));

        log.info("批量智能分配完成，成功: {}，失败: {}", successCount, failCount);

        return result;
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public boolean manualAdjustAssignment(Long taskId, Long engineerId, String reason) {
        log.info("手动调整任务分配，任务ID: {} -> 测试人员ID: {}, 原因: {}", taskId, engineerId, reason);

        try {
            // 1. 获取原分配信息
            TestTask task = testTaskMapper.selectById(taskId);
            if (task == null || task.getStatus() != 1) {
                log.warn("任务不存在或状态不是已分配状态");
                return false;
            }

            Long originalEngineerId = task.getAssignedEngineerId();

            // 2. 还原原测试人员状态
            if (originalEngineerId != null) {
                TestEngineer originalEngineer = testEngineerMapper.selectById(originalEngineerId);
                if (originalEngineer != null) {
                    originalEngineer.setCurrentTaskId(null);
                    if (task.getEstimatedHours() != null) {
                        // 减少工作负载
                        testEngineerMapper.updateEngineerWorkload(originalEngineerId, -task.getEstimatedHours());
                    }
                    testEngineerMapper.updateById(originalEngineer);
                }
            }

            // 3. 分配新测试人员
            TestEngineer newEngineer = testEngineerMapper.selectById(engineerId);
            if (newEngineer == null || newEngineer.getStatus() != 0) {
                log.warn("新测试人员不存在或状态不可用");
                return false;
            }

            // 计算匹配得分（简化的手动分配得分计算）
            double manualScore = 0.8; // 手动分配默认得分

            boolean assignSuccess = assignTaskToEngineer(taskId, engineerId, manualScore, 1);

            if (assignSuccess) {
                // 创建手动调整记录
                TaskAssignmentRecord record = new TaskAssignmentRecord();
                record.setTaskId(taskId);
                record.setEngineerId(engineerId);
                record.setAssignmentType(1); // 1-手动分配
                record.setAssignmentScore(manualScore);
                record.setAssignTime(LocalDateTime.now());
                record.setAssignmentReason("手动调整: " + reason);
                record.setAssignerId(getCurrentUserId()); // 需要实现获取当前用户ID

                taskAssignmentRecordMapper.insert(record);

                log.info("手动调整分配成功，任务ID: {} -> 新测试人员ID: {}", taskId, engineerId);
                return true;
            }

            return false;

        } catch (Exception e) {
            log.error("手动调整任务分配失败，任务ID: {}", taskId, e);
            return false;
        }
    }

    @Override
    public List<Map<String, Object>> getAssignmentRecommendations(Long taskId, Integer topN) {
        log.info("获取任务分配推荐，任务ID: {}, 返回前{}个推荐", taskId, topN);

        TestTask task = testTaskMapper.selectById(taskId);
        if (task == null || task.getIsDeleted() == 1) {
            return new ArrayList<>();
        }

        List<TestEngineer> availableEngineers = testEngineerMapper.selectAvailableEngineers();
        List<Map<String, Object>> scoreList = calculateEngineerScores(task, availableEngineers);

        // 限制返回数量
        if (topN != null && topN > 0 && scoreList.size() > topN) {
            return scoreList.subList(0, topN);
        }

        return scoreList;
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Map<String, Object> recalculateAllPendingTasks() {
        log.info("开始重新计算所有待分配任务");
        Map<String, Object> result = new HashMap<>();

        // 获取所有待分配任务
        List<TestTask> pendingTasks = testTaskMapper.selectPendingTasks();
        log.info("找到{}个待分配任务", pendingTasks.size());

        List<Map<String, Object>> recalculationResults = new ArrayList<>();
        int reassignedCount = 0;

        for (TestTask task : pendingTasks) {
            // 获取当前分配
            Long currentEngineerId = task.getAssignedEngineerId();

            // 获取推荐分配
            List<Map<String, Object>> recommendations = getAssignmentRecommendations(task.getId(), 3);

            if (!recommendations.isEmpty()) {
                Map<String, Object> bestRecommendation = recommendations.get(0);
                Long recommendedEngineerId = (Long) bestRecommendation.get("engineerId");
                Double recommendedScore = (Double) bestRecommendation.get("totalScore");

                // 如果推荐与当前不同，且得分高于阈值，则重新分配
                if (!Objects.equals(currentEngineerId, recommendedEngineerId) && recommendedScore > 0.7) {
                    // 执行重新分配
                    if (currentEngineerId != null) {
                        // 解除原分配
                        TestEngineer originalEngineer = testEngineerMapper.selectById(currentEngineerId);
                        if (originalEngineer != null) {
                            originalEngineer.setCurrentTaskId(null);
                            if (task.getEstimatedHours() != null) {
                                testEngineerMapper.updateEngineerWorkload(currentEngineerId, -task.getEstimatedHours());
                            }
                            testEngineerMapper.updateById(originalEngineer);
                        }
                    }

                    // 新分配
                    boolean assignSuccess = assignTaskToEngineer(task.getId(), recommendedEngineerId, recommendedScore, 0);

                    if (assignSuccess) {
                        reassignedCount++;

                        Map<String, Object> reassignResult = new HashMap<>();
                        reassignResult.put("taskId", task.getId());
                        reassignResult.put("taskName", task.getTaskName());
                        reassignResult.put("fromEngineerId", currentEngineerId);
                        reassignResult.put("toEngineerId", recommendedEngineerId);
                        reassignResult.put("score", recommendedScore);
                        reassignResult.put("success", true);

                        recalculationResults.add(reassignResult);
                    }
                }
            }
        }

        result.put("success", true);
        result.put("totalPendingTasks", pendingTasks.size());
        result.put("reassignedCount", reassignedCount);
        result.put("recalculationResults", recalculationResults);
        result.put("message", String.format("重新计算完成，共重新分配%d个任务", reassignedCount));

        log.info("重新计算完成，共重新分配{}个任务", reassignedCount);

        return result;
    }

