    @Column(name = "config_json", columnDefinition = "TEXT")
    @Schema(description = "报表配置信息(JSON格式)")
    private String configJson;

    @Column(name = "query_sql", columnDefinition = "TEXT")
    @Schema(description = "数据查询SQL")
    private String querySql;

    @Column(name = "chart_config", columnDefinition = "TEXT")
    @Schema(description = "图表配置信息(JSON格式)")
    private String chartConfig;

    @Column(name = "export_format")
    @Schema(description = "导出格式，多个用逗号分隔")
    private String exportFormat;

    @Column(nullable = false)
    @Schema(description = "排序号")
    private Integer sortOrder = 0;

    @Column(nullable = false)
    @Schema(description = "是否启用")
    private Boolean enabled = true;

    @Column(name = "created_by", length = 50)
    @Schema(description = "创建人")
    private String createdBy;

    @Column(name = "created_time")
    @JsonFormat(pattern = "yyyy-MM-dd HH:mm:ss")
    @Schema(description = "创建时间")
    private LocalDateTime createdTime;

    @Column(name = "updated_by", length = 50)
    @Schema(description = "更新人")
    private String updatedBy;

    @Column(name = "updated_time")
    @JsonFormat(pattern = "yyyy-MM-dd HH:mm:ss")
    @Schema(description = "更新时间")
    private LocalDateTime updatedTime;

    @Column(name = "tenant_id")
    @Schema(description = "租户ID")
    private String tenantId;

    /**
     * 报表类型枚举
     */
