```java
package com.chinasofti.adaptationcenter.service.report;

import com.chinasofti.adaptationcenter.entity.report.ReportInstance;
import com.chinasofti.adaptationcenter.entity.report.ReportTemplate;
import com.chinasofti.adaptationcenter.entity.report.ReportSubscription;
import com.chinasofti.adaptationcenter.repository.report.ReportTemplateRepository;
import com.chinasofti.adaptationcenter.repository.report.ReportInstanceRepository;
import com.chinasofti.adaptationcenter.repository.report.ReportSubscriptionRepository;
import com.chinasofti.adaptationcenter.vo.report.*;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.BeanUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.domain.Specification;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.util.StringUtils;

import javax.persistence.criteria.Predicate;
import java.time.LocalDateTime;
import java.util.*;
import java.util.stream.Collectors;

/**
 * 报表模板服务层实现
 */
@Slf4j
@Service
@Transactional
public class ReportTemplateService {

    @Autowired
    private ReportTemplateRepository reportTemplateRepository;

    @Autowired
    private ReportInstanceRepository reportInstanceRepository;

    @Autowired
    private ReportSubscriptionRepository reportSubscriptionRepository;

    @Autowired
    private ReportGeneratorService reportGeneratorService;

    /**
     * 创建报表模板
     */
    public ReportTemplateVO createTemplate(ReportTemplateCreateVO createVO) {
        log.info("创建报表模板: {}", createVO.getName());

        // 检查模板编码是否已存在
        if (reportTemplateRepository.findByCode(createVO.getCode()).isPresent()) {
            throw new RuntimeException("模板编码已存在: " + createVO.getCode());
        }

        ReportTemplate template = new ReportTemplate();
        BeanUtils.copyProperties(createVO, template);
        template.setCreatedTime(LocalDateTime.now());
        template.setUpdatedTime(LocalDateTime.now());
        template.setSystemDefault(false); // 新创建的模板不是系统预置模板

        ReportTemplate saved = reportTemplateRepository.save(template);
        log.info("报表模板创建成功，ID: {}", saved.getId());

        return convertToVO(saved);
    }

    /**
     * 更新报表模板
     */
    public ReportTemplateVO updateTemplate(Long id, ReportTemplateUpdateVO updateVO) {
        log.info("更新报表模板，ID: {}", id);

        ReportTemplate template = reportTemplateRepository.findById(id)
                .orElseThrow(() -> new RuntimeException("报表模板不存在，ID: " + id));

        // 系统预置模板不允许修改关键信息
        if (template.getSystemDefault() && updateVO.getSystemDefault() != null) {
            throw new RuntimeException("系统预置模板不允许修改");
        }

        BeanUtils.copyProperties(updateVO, template, "id", "code", "createdTime", "createdBy");
        template.setUpdatedTime(LocalDateTime.now());

        ReportTemplate updated = reportTemplateRepository.save(template);
        log.info("报表模板更新成功，ID: {}", id);

        return convertToVO(updated);
    }

    /**
     * 获取报表模板详情
     */
    public ReportTemplateVO getTemplateById(Long id) {
        log.debug("获取报表模板详情，ID: {}", id);

        ReportTemplate template = reportTemplateRepository.findById(id)
                .orElseThrow(() -> new RuntimeException("报表模板不存在，ID: " + id));

        return convertToVO(template);
    }

    /**
     * 根据编码获取报表模板
     */
    public ReportTemplateVO getTemplateByCode(String code) {
        log.debug("根据编码获取报表模板，Code: {}", code);

        ReportTemplate template = reportTemplateRepository.findByCode(code)
                .orElseThrow(() -> new RuntimeException("报表模板不存在，Code: " + code));

        return convertToVO(template);
    }

    /**
     * 查询报表模板列表
     */
    public Page<ReportTemplateVO> queryTemplates(ReportTemplateQueryVO queryVO, Pageable pageable) {
        log.debug("查询报表模板列表，查询条件: {}", queryVO);

        Specification<ReportTemplate> spec = buildQuerySpecification(queryVO);
        Page<ReportTemplate> page = reportTemplateRepository.findAll(spec, pageable);

        return page.map(this::convertToVO);
    }

    /**
     * 获取系统预置模板列表
     */
    public List<ReportTemplateVO> getSystemTemplates() {
        log.debug("获取系统预置模板列表");

        List<ReportTemplate> templates = reportTemplateRepository.findBySystemDefaultTrueAndEnabledTrueOrderBySortOrderAsc();
        return templates.stream().map(this::convertToVO).collect(Collectors.toList());
    }

    /**
     * 根据类型获取模板
     */
    public List<ReportTemplateVO> getTemplatesByType(ReportTemplate.ReportType type) {
        log.debug("根据类型获取模板，Type: {}", type);

        List<ReportTemplate> templates = reportTemplateRepository.findByTypeAndEnabledTrueOrderBySortOrderAsc(type);
        return templates.stream().map(this::convertToVO).collect(Collectors.toList());
    }

    /**
     * 删除报表模板
     */
    public void deleteTemplate(Long id) {
        log.info("删除报表模板，ID: {}", id);

        ReportTemplate template = reportTemplateRepository.findById(id)
                .orElseThrow(() -> new RuntimeException("报表模板不存在，ID: " + id));

        // 检查是否被使用
        if (hasReportInstances(id)) {
            throw new RuntimeException("该模板已被使用，无法删除");
        }

        reportTemplateRepository.delete(template);
        log.info("报表模板删除成功，ID: {}", id);
    }

    /**
     * 启用/禁用模板
     */
    public void toggleTemplateStatus(Long id, Boolean enabled) {
        log.info("{}报表模板，ID: {}", enabled ? "启用" : "禁用", id);

        ReportTemplate template = reportTemplateRepository.findById(id)
                .orElseThrow(() -> new RuntimeException("报表模板不存在，ID: " + id));

        template.setEnabled(enabled);
        template.setUpdatedTime(LocalDateTime.now());
        reportTemplateRepository.save(template);

        log.info("报表模板状态更新成功，ID: {}, 状态: {}", id, enabled);
    }

    /**
     * 执行报表生成
     */
    public ReportInstanceVO generateReport(ReportGenerateVO generateVO) {
        log.info("执行报表生成，模板ID: {}, 项目ID: {}", 
                generateVO.getTemplateId(), generateVO.getProjectId());

        ReportTemplate template = reportTemplateRepository.findById(generateVO.getTemplateId())
                .orElseThrow(() -> new RuntimeException("报表模板不存在，ID: " + generateVO.getTemplateId()));

        // 创建报表实例
        ReportInstance instance = new ReportInstance();
        instance.setName(generateVO.getReportName());
        instance.setTemplateId(template.getId());
        instance.setTemplateCode(template.getCode());
        instance.setProjectId(generateVO.getProjectId());
        instance.setStatus(ReportInstance.ReportStatus.GENERATING);
        instance.setParamJson(generateVO.getParamJson());
        instance.setGeneratedBy(generateVO.getGeneratedBy());
        instance.setGeneratedTime(LocalDateTime.now());
        instance.setTenantId(generateVO.getTenantId());

        ReportInstance savedInstance = reportInstanceRepository.save(instance);

        try {
            // 异步执行报表生成
            reportGeneratorService.generateReportAsync(savedInstance.getId(), template, generateVO);

            log.info("报表生成任务已提交，实例ID: {}", savedInstance.getId());
            return convertToInstanceVO(savedInstance);
        } catch (Exception e) {
            log.error("报表生成提交失败", e);

            // 更新状态为失败
            savedInstance.setStatus(ReportInstance.ReportStatus.FAILED);
            savedInstance.setErrorMessage(e.getMessage());
            reportInstanceRepository.save(savedInstance);

            throw new RuntimeException("报表生成提交失败: " + e.getMessage());
        }
    }

    /**
     * 获取报表实例列表
     */
    public Page<ReportInstanceVO> queryReportInstances(ReportInstanceQueryVO queryVO, Pageable pageable) {
        log.debug("查询报表实例列表");

        Specification<ReportInstance> spec = buildInstanceQuerySpecification(queryVO);
        Page<ReportInstance> page = reportInstanceRepository.findAll(spec, pageable);

        return page.map(this::convertToInstanceVO);
    }

    /**
     * 下载报表
     */
    public ReportInstanceVO downloadReport(Long instanceId) {
        log.info("下载报表，实例ID: {}", instanceId);

        ReportInstance instance = reportInstanceRepository.findById(instanceId)
                .orElseThrow(() -> new RuntimeException("报表实例不存在，ID: " + instanceId));

        if (instance.getStatus() != ReportInstance.ReportStatus.SUCCESS) {
            throw new RuntimeException("报表尚未生成成功，无法下载");
        }

        // 增加下载次数
        reportInstanceRepository.incrementDownloadCount(instanceId);

        return convertToInstanceVO(instance);
    }

    /**
     * 创建报表订阅
     */
    public ReportSubscriptionVO createSubscription(ReportSubscriptionCreateVO createVO) {
        log.info("创建报表订阅，模板ID: {}, 用户ID: {}", 
                createVO.getTemplateId(), createVO.getUserId());

        // 检查是否已存在订阅
        ReportSubscription existing = reportSubscriptionRepository
                .findByUserIdAndTemplateId(createVO.getUserId(), createVO.getTemplateId());
        if (existing != null) {
            throw new RuntimeException("该用户已订阅此报表模板");
        }

        ReportSubscription subscription = new ReportSubscription();
        BeanUtils.copyProperties(createVO, subscription);
        subscription.setStatus(ReportSubscription.SubscriptionStatus.ACTIVE);
        subscription.setCreatedTime(LocalDateTime.now());
        subscription.setUpdatedTime(LocalDateTime.now());

        // 计算下次执行时间
        calculateNextExecuteTime(subscription);

        ReportSubscription saved = reportSubscriptionRepository.save(subscription);
        log.info("报表订阅创建成功，ID: {}", saved.getId());

        return convertToSubscriptionVO(saved);
    }

    /**
     * 执行订阅的报表生成
     */
    @Scheduled(cron = "0 0/30 * * * ?") // 每30分钟执行一次
    public void executeSubscriptions() {
        log.debug("开始执行报表订阅任务");

        LocalDateTime now = LocalDateTime.now();
        List<ReportSubscription> subscriptions = reportSubscriptionRepository.findSubscriptionsToExecute(now);

        for (ReportSubscription subscription : subscriptions) {
            try {
                executeSubscription(subscription);

                // 更新执行时间
                subscription.setLastExecuteTime(now);
                calculateNextExecuteTime(subscription);
                reportSubscriptionRepository.save(subscription);

                log.info("订阅报表执行成功，订阅ID: {}", subscription.getId());
            } catch (Exception e) {
                log.error("订阅报表执行失败，订阅ID: " + subscription.getId(), e);
            }
        }

        log.debug("报表订阅任务执行完成");
    }

    /**
     * 清理过期的报表实例
     */
    @Scheduled(cron = "0 0 2 * * ?") // 每天凌晨2点执行
    public void cleanupExpiredReports() {
        log.info("开始清理过期的报表实例");

        LocalDateTime expireTime = LocalDateTime.now().minusDays(30); // 保留30天
        int deletedCount = reportInstanceRepository.deleteByGeneratedTimeBefore(expireTime);

        log.info("清理过期的报表实例完成，共删除{}条记录", deletedCount);
    }

    // 私有辅助方法
    private Specification<ReportTemplate> buildQuerySpecification(ReportTemplateQueryVO queryVO) {
        return (root, query, criteriaBuilder) -> {
            List<Predicate> predicates = new ArrayList<>();

            if (StringUtils.hasText(queryVO.getName())) {
                predicates.add(criteriaBuilder.like(root.get("name"), "%" + queryVO.getName() + "%"));
            }

            if (queryVO.getType() != null) {
                predicates.add(criteriaBuilder.equal(root.get("type"), queryVO.getType()));
            }

            if (queryVO.getEnabled() != null) {
                predicates.add(criteriaBuilder.equal(root.get("enabled"), queryVO.getEnabled()));
            }

            if (queryVO.getSystemDefault() != null) {
                predicates.add(criteriaBuilder.equal(root.get("systemDefault"), queryVO.getSystemDefault()));
            }

            if (StringUtils.hasText(queryVO.getTenantId())) {
                predicates.add(criteriaBuilder.equal(root.get("tenantId"), queryVO.getTenantId()));
            }

            return criteriaBuilder.and(predicates.toArray(new Predicate[0]));
        };
    }

    private Specification<ReportInstance> buildInstanceQuerySpecification(ReportInstanceQueryVO queryVO) {
        return (root, query, criteriaBuilder) -> {
            List<Predicate> predicates = new ArrayList<>();

            if (queryVO.getTemplateId() != null) {
                predicates.add(criteriaBuilder.equal(root.get("templateId"), queryVO.getTemplateId()));
            }

            if (queryVO.getProjectId() != null) {
                predicates.add(criteriaBuilder.equal(root.get("projectId"), queryVO.getProjectId()));
            }

            if (queryVO.getStatus() != null) {
                predicates.add(criteriaBuilder.equal(root.get("status"), queryVO.getStatus()));
            }

            if (StringUtils.hasText(queryVO.getGeneratedBy())) {
                predicates.add(criteriaBuilder.equal(root.get("generatedBy"), queryVO.getGeneratedBy()));
            }

            if (queryVO.getStartTime() != null) {
                predicates.add(criteriaBuilder.greaterThanOrEqualTo(root.get("generatedTime"), queryVO.getStartTime()));
            }

            if (queryVO.getEndTime() != null) {
                predicates.add(criteriaBuilder.lessThanOrEqualTo(root.get("generatedTime"), queryVO.getEndTime()));
            }

            if (StringUtils.hasText(queryVO.getTenantId())) {
                predicates.add(criteriaBuilder.equal(root.get("tenantId"), queryVO.getTenantId()));
            }

            return criteriaBuilder.and(predicates.toArray(new Predicate[0]));
        };
    }

    private ReportTemplateVO convertToVO(ReportTemplate template) {
        ReportTemplateVO vo = new ReportTemplateVO();
        BeanUtils.copyProperties(template, vo);
        return vo;
    }

    private ReportInstanceVO convertToInstanceVO(ReportInstance instance) {
        ReportInstanceVO vo = new ReportInstanceVO();
        BeanUtils.copyProperties(instance, vo);
        return vo;
    }

    private ReportSubscriptionVO convertToSubscriptionVO(ReportSubscription subscription) {
        ReportSubscriptionVO vo = new ReportSubscriptionVO();
        BeanUtils.copyProperties(subscription, vo);
        return vo;
    }

    private boolean hasReportInstances(Long templateId) {
        return !reportInstanceRepository.findByTemplateId(templateId).isEmpty();
    }

    private void calculateNextExecuteTime(ReportSubscription subscription) {
        // 这里应该根据cron表达式计算下次执行时间
        // 简化实现：如果是每天执行，则设置为明天同一时间
        if ("0 0 9 * * ?".equals(subscription.getCronExpression())) { // 每天9点
            subscription.setNextExecuteTime(LocalDateTime.now().plusDays(1).withHour(9).withMinute(0).withSecond(0));
        }
        // 其他cron表达式的处理...
    }

    private void executeSubscription(ReportSubscription subscription) {
        ReportGenerateVO generateVO = new ReportGenerateVO();
        generateVO.setTemplateId(subscription.getTemplateId());
        generateVO.setParamJson(subscription.getParamJson());
        generateVO.setGeneratedBy(subscription.getUserName());

        // 执行报表生成
        generateReport(generateVO);
    }
}
