package com.chinasofti.adaptationcenter.service.report;

import com.chinasofti.adaptationcenter.entity.report.ReportInstance;
import com.chinasofti.adaptationcenter.entity.report.ReportTemplate;
import com.chinasofti.adaptationcenter.repository.report.ReportInstanceRepository;
import com.chinasofti.adaptationcenter.vo.report.ReportGenerateVO;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.scheduling.annotation.Async;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.Map;

/**
 * 报表生成服务层
 */
@Slf4j
@Service
public class ReportGeneratorService {

    @Autowired
    private ReportInstanceRepository reportInstanceRepository;

    @Autowired
    private ProjectReportService projectReportService;

    @Autowired
    private DefectReportService defectReportService;

    @Autowired
    private CoverageReportService coverageReportService;

    @Autowired
    private PerformanceReportService performanceReportService;

    /**
     * 异步生成报表
     */
    @Async("reportExecutor")
    @Transactional
    public void generateReportAsync(Long instanceId, ReportTemplate template, ReportGenerateVO generateVO) {
        log.info("开始异步生成报表，实例ID: {}, 模板类型: {}", instanceId, template.getType());

        long startTime = System.currentTimeMillis();

        try {
            // 根据模板类型选择相应的生成器
            Map<String, Object> reportData = generateReportData(template, generateVO);

            // 生成文件（PDF/Excel）
            String filePath = exportReportToFile(template, reportData, generateVO.getExportFormat());

            // 更新报表实例状态
            updateReportInstance(instanceId, ReportInstance.ReportStatus.SUCCESS, reportData, 
                    filePath, generateVO.getExportFormat(), System.currentTimeMillis() - startTime);

            log.info("报表生成成功，实例ID: {}, 耗时: {}ms", instanceId, System.currentTimeMillis() - startTime);
        } catch (Exception e) {
            log.error("报表生成失败，实例ID: " + instanceId, e);

            // 更新为失败状态
            updateReportInstance(instanceId, ReportInstance.ReportStatus.FAILED, null, 
                    null, null, System.currentTimeMillis() - startTime);
        }
    }

    /**
     * 生成报表数据
     */
    private Map<String, Object> generateReportData(ReportTemplate template, ReportGenerateVO generateVO) {
        log.debug("生成报表数据，模板类型: {}", template.getType());

        switch (template.getType()) {
            case PROJECT_PROGRESS:
                return projectReportService.generateProjectProgressReport(
                        generateVO.getProjectId(), generateVO.getParamJson());

            case DEFECT_DISTRIBUTION:
                return defectReportService.generateDefectDistributionReport(
                        generateVO.getProjectId(), generateVO.getParamJson());

            case TEST_COVERAGE:
                return coverageReportService.generateTestCoverageReport(
                        generateVO.getProjectId(), generateVO.getParamJson());

            case STAFF_PERFORMANCE:
                return performanceReportService.generateStaffPerformanceReport(
                        generateVO.getProjectId(), generateVO.getParamJson());

            default:
                throw new RuntimeException("不支持的报表类型: " + template.getType());
        }
    }

    /**
     * 导出报表到文件
     */
    private String exportReportToFile(ReportTemplate template, Map<String, Object> data, String exportFormat) {
        // 根据导出格式生成文件（PDF或Excel）
        // 这里实现文件生成的逻辑，返回文件路径
        String fileName = template.getName() + "_" + System.currentTimeMillis();

        if ("PDF".equalsIgnoreCase(exportFormat)) {
            return generatePdfReport(fileName, data);
        } else if ("EXCEL".equalsIgnoreCase(exportFormat)) {
            return generateExcelReport(fileName, data);
        } else {
            // 默认生成Excel
            return generateExcelReport(fileName, data);
        }
    }

    /**
     * 更新报表实例状态
     */
    private void updateReportInstance(Long instanceId, ReportInstance.ReportStatus status, 
                                      Map<String, Object> data, String filePath, 
                                      String fileFormat, Long executionTime) {
        ReportInstance instance = reportInstanceRepository.findById(instanceId)
                .orElseThrow(() -> new RuntimeException("报表实例不存在，ID: " + instanceId));

        instance.setStatus(status);
        instance.setExecutionTime(executionTime);

        if (data != null) {
            // 将数据转换为JSON字符串存储
            instance.setDataJson(convertMapToJson(data));
        }

        if (filePath != null) {
            instance.setFilePath(filePath);
            instance.setFileFormat(fileFormat);
        }

        if (status == ReportInstance.ReportStatus.FAILED) {
            instance.setErrorMessage("报表生成失败");
        }

        reportInstanceRepository.save(instance);
    }

    /**
     * 生成PDF报表
     */
    private String generatePdfReport(String fileName, Map<String, Object> data) {
        // 实现PDF生成逻辑
        log.debug("生成PDF报表: {}", fileName);
        return "/reports/pdf/" + fileName + ".pdf";
    }

    /**
     * 生成Excel报表
     */
    private String generateExcelReport(String fileName, Map<String, Object> data) {
        // 实现Excel生成逻辑
        log.debug("生成Excel报表: {}", fileName);
        return "/reports/excel/" + fileName + ".xlsx";
    }

    /**
     * 转换Map为JSON字符串
     */
    private String convertMapToJson(Map<String, Object> data) {
        // 使用Jackson或Gson进行转换
        // 简化实现
        return "{\"data\": \"report data\"}";
    }
}
