    User selectByUsernameAndTenant(@Param("username") String username, @Param("tenantId") Long tenantId);

    /**
     * 根据邮箱查询用户（包含租户隔离）
     * @param email 邮箱
     * @param tenantId 租户ID
     * @return 用户实体
     */
    @Select("SELECT * FROM sys_user WHERE email = #{email} AND tenant_id = #{tenantId} AND deleted = 0")
    User selectByEmailAndTenant(@Param("email") String email, @Param("tenantId") Long tenantId);

    /**
     * 根据手机号查询用户（包含租户隔离）
     * @param phone 手机号
     * @param tenantId 租户ID
     * @return 用户实体
     */
    @Select("SELECT * FROM sys_user WHERE phone = #{phone} AND tenant_id = #{tenantId} AND deleted = 0")
    User selectByPhoneAndTenant(@Param("phone") String phone, @Param("tenantId") Long tenantId);

    /**
     * 分页查询用户列表（包含租户隔离）
     * @param page 分页参数
     * @param tenantId 租户ID
     * @param username 用户名（模糊查询）
     * @param realName 真实姓名（模糊查询）
     * @param status 状态
