     * 查询用户权限标识列表
     * @param userId 用户ID
     * @return 权限标识列表
     */
    @Select("SELECT DISTINCT p.perm_key FROM sys_permission p " +
            "INNER JOIN sys_role_permission rp ON p.permission_id = rp.permission_id " +
            "INNER JOIN sys_user_role ur ON rp.role_id = ur.role_id " +
            "WHERE ur.user_id = #{userId} AND p.status = 1 AND p.deleted = 0")
    List<String> selectPermKeysByUserId(@Param("userId") Long userId);

    /**
     * 批量插入用户角色关联
