@Slf4j
@Service
public class UserServiceImpl extends ServiceImpl<UserRepository, User> implements UserService {

    @Autowired
    private UserRepository userRepository;

    @Autowired
    private UserRoleRepository userRoleRepository;

    @Autowired
    private RoleService roleService;

    @Autowired
    private TenantService tenantService;

    @Autowired
    private SecurityUtils securityUtils;

    @Override
    @Transactional(rollbackFor = Exception.class)
    public UserVO register(UserDTO userDTO) {
        log.info("用户注册开始，用户名：{}，租户编码：{}", userDTO.getUsername(), userDTO.getTenantCode());

        // 验证租户
        Long tenantId = tenantService.getTenantIdByCode(userDTO.getTenantCode());
        if (tenantId == null) {
            throw new BusinessException("租户不存在或已禁用");
        }

        // 检查用户名是否已存在
        User existUser = userRepository.selectByUsernameAndTenant(userDTO.getUsername(), tenantId);
        if (existUser != null) {
            throw new BusinessException("用户名已存在");
        }

        // 检查邮箱是否已存在
        if (StringUtils.hasText(userDTO.getEmail())) {
            User emailUser = userRepository.selectByEmailAndTenant(userDTO.getEmail(), tenantId);
            if (emailUser != null) {
                throw new BusinessException("邮箱已存在");
            }
        }

        // 检查手机号是否已存在
        if (StringUtils.hasText(userDTO.getPhone())) {
            User phoneUser = userRepository.selectByPhoneAndTenant(userDTO.getPhone(), tenantId);
            if (phoneUser != null) {
                throw new BusinessException("手机号已存在");
            }
        }

        // 创建用户实体
        User user = BeanCopyUtils.copy(userDTO, User.class);
        user.setTenantId(tenantId);
        user.setPassword(PasswordUtils.encryptPassword(userDTO.getPassword()));
        user.setStatus(1); // 启用状态
        user.setPasswordErrorCount(0);
        user.setPasswordLastModified(LocalDateTime.now());

        // 保存用户
        boolean saveSuccess = save(user);
        if (!saveSuccess) {
            throw new BusinessException("用户注册失败");
        }

        log.info("用户注册成功，用户ID：{}", user.getUserId());

        // 分配默认角色
        assignDefaultRole(user.getUserId(), tenantId);

        // 返回

