package com.chinasofti.adaptation.center.controller;

import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import com.chinasofti.adaptation.center.common.model.ApiResponse;
import com.chinasofti.adaptation.center.common.model.PageResult;
import com.chinasofti.adaptation.center.common.utils.SecurityUtils;
import com.chinasofti.adaptation.center.model.dto.UserDTO;
import com.chinasofti.adaptation.center.model.query.UserQuery;
import com.chinasofti.adaptation.center.model.vo.UserVO;
import com.chinasofti.adaptation.center.service.UserService;
import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.Parameter;
import io.swagger.v3.oas.annotations.tags.Tag;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.*;

import javax.validation.Valid;
import java.util.List;

/**
 * 用户管理控制器
 * 提供用户相关的RESTful API接口
 * @author 刘贺
 * @date 2025-08-01
 */
@Slf4j
@Validated
@RestController
@RequestMapping("/api/v1/users")
@Tag(name = "用户管理", description = "用户管理相关接口")
public class UserController {

    @Autowired
    private UserService userService;

    @Autowired
    private SecurityUtils securityUtils;

    @PostMapping("/register")
    @Operation(summary = "用户注册", description = "新用户注册接口")
    public ApiResponse<UserVO> register(@Valid @RequestBody UserDTO userDTO) {
        log.info("用户注册请求：username={}, tenantCode={}", 
                userDTO.getUsername(), userDTO.getTenantCode());

        try {
            UserVO userVO = userService.register(userDTO);
            log.info("用户注册成功：userId={}", userVO.getUserId());
            return ApiResponse.success(userVO, "注册成功");
        } catch (Exception e) {
            log.error("用户注册失败：{}", e.getMessage(), e);
            return ApiResponse.error("注册失败：" + e.getMessage());
        }
    }

    @PostMapping("/login")
    @Operation(summary = "用户登录", description = "用户登录接口，返回JWT令牌")
    public ApiResponse<String> login(
            @Parameter(description = "用户名") @RequestParam String username,
            @Parameter(description = "密码") @RequestParam String password,
            @Parameter(description = "租户编码") @RequestParam String tenantCode) {
        log.info("用户登录请求：username={}, tenantCode={}", username, tenantCode);

        try {
            String token = userService.login(username, password, tenantCode);
            log.info("用户登录成功：username={}", username);
            return ApiResponse.success(token, "登录成功");
        } catch (Exception e) {
            log.error("用户登录失败：{}", e.getMessage(), e);
            return ApiResponse.error("登录失败：" + e.getMessage());
        }
    }

    @PostMapping("/logout")
    @Operation(summary = "用户登出", description = "用户登出接口，使当前令牌失效")
    public ApiResponse<Void> logout() {
        String token = securityUtils.getCurrentToken();
        log.info("用户登出请求：token={}", token);

        try {
            userService.logout(token);
            log.info("用户登出成功");
            return ApiResponse.success("登出成功");
        } catch (Exception e) {
            log.error("用户登出失败：{}", e.getMessage(), e);
            return ApiResponse.error("登出失败：" + e.getMessage());
        }
    }

    @GetMapping("/{userId}")
    @Operation(summary = "获取用户详情", description = "根据用户ID获取用户详细信息")
    public ApiResponse<UserVO> getUserDetail(
            @Parameter(description = "用户ID") @PathVariable Long userId) {
        log.info("获取用户详情请求：userId={}", userId);

        try {
            UserVO userVO = userService.getUserDetail(userId);
            log.info("获取用户详情成功：userId={}", userId);
            return ApiResponse.success(userVO, "获取成功");
        } catch (Exception e) {
            log.error("获取用户详情失败：{}", e.getMessage(), e);
            return ApiResponse.error("获取失败：" + e.getMessage());
        }
    }

    @GetMapping("/current")
    @Operation(summary = "获取当前用户信息", description = "获取当前登录用户的信息")
    public ApiResponse<UserVO> getCurrentUser() {
        Long userId = securityUtils.getCurrentUserId();
        log.info("获取当前用户信息请求：userId={}", userId);

        try {
            UserVO userVO = userService.getUserDetail(userId);
            log.info("获取当前用户信息成功：userId={}", userId);
            return ApiResponse.success(userVO, "获取成功");
        } catch (Exception e) {
            log.error("获取当前用户信息失败：{}", e.getMessage(), e);
            return ApiResponse.error("获取失败：" + e.getMessage());
        }
    }

    @GetMapping("/page")
    @Operation(summary = "分页查询用户列表", description = "根据条件分页查询用户列表")
    public ApiResponse<PageResult<UserVO>> getUserPage(@Valid UserQuery query) {
        log.info("分页查询用户列表请求：{}", query.toString());

        try {
            Page<UserVO> page = userService.getUserPage(query);
            PageResult<UserVO> pageResult = PageResult.of(page);
            log.info("分页查询用户列表成功：total={}", page.getTotal());
            return ApiResponse.success(pageResult, "查询成功");
        } catch (Exception e) {
            log.error("分页查询用户列表失败：{}", e.getMessage(), e);
            return ApiResponse.error("查询失败：" + e.getMessage());
        }
    }

    @PostMapping
    @Operation(summary = "创建用户", description = "创建新用户")
    public ApiResponse<UserVO> createUser(@Valid @RequestBody UserDTO userDTO) {
        log.info("创建用户请求：username={}", userDTO.getUsername());

        try {
            UserVO userVO = userService.createUser(userDTO);
            log.info("创建用户成功：userId={}", userVO.getUserId());
            return ApiResponse.success(userVO, "创建成功");
        } catch (Exception e) {
            log.error("创建用户失败：{}", e.getMessage(), e);
            return ApiResponse.error("创建失败：" + e.getMessage());
        }
    }

    @PutMapping("/{userId}")
    @Operation(summary = "更新用户", description = "更新用户信息")
    public ApiResponse<UserVO> updateUser(
            @Parameter(description = "用户ID") @PathVariable Long userId,
            @Valid @RequestBody UserDTO userDTO) {
        log.info("更新用户请求：userId={}", userId);

        try {
            UserVO userVO = userService.updateUser(userId, userDTO);
            log.info("更新用户成功：userId={}", userId);
