                return ApiResponse.success("重置成功");
            } else {
                log.warn("重置密码失败：userId={}", userId);
                return ApiResponse.error("重置失败");
            }
        } catch (Exception e) {
            log.error("重置密码异常：{}", e.getMessage(), e);
            return ApiResponse.error("重置异常：" + e.getMessage());
        }
    }

    @PutMapping("/{userId}/status")
    @Operation(summary = "修改用户状态", description = "启用或禁用用户")
    public ApiResponse<Void> changeUserStatus(
            @Parameter(description = "用户ID") @PathVariable Long userId,
            @Parameter(description = "状态：0-禁用，1-启用，2-锁定") @RequestParam Integer status) {
        log.info("修改用户状态请求：userId={}, status={}", userId, status);

        try {
            boolean success = userService.changeStatus(userId, status);
            if (success) {
                log.info("修改用户状态成功：userId={}, status={}", userId, status);
                return ApiResponse.success("修改成功");
            } else {
                log.warn("修改用户状态失败：userId={}, status={}", userId, status);
                return ApiResponse.error("修改失败");
            }
        } catch (Exception e) {
            log.error("修改用户状态异常：{}", e.getMessage(), e);
            return ApiResponse.error("修改异常：" + e.getMessage());
        }
    }

    @PostMapping("/{userId}/roles")
    @Operation(summary = "分配用户角色", description = "为用户分配一个或多个角色")
    public ApiResponse<Void> assignUserRoles(
            @Parameter(description = "用户ID") @PathVariable Long userId,
            @Parameter(description = "角色ID列表") @RequestBody List<Long> roleIds) {
        log.info("分配用户角色请求：userId={}, roleIds={}", userId, roleIds);

        try {
            boolean success = userService.assignRoles(userId, roleIds);
            if (success) {
                log.info("分配用户角色成功：userId={}, roleCount={}", userId, roleIds.size());
                return ApiResponse.success("分配成功");
            } else {
                log.warn("分配用户角色失败：userId={}", userId);
                return ApiResponse.error("分配失败");
            }
        } catch (Exception e) {
            log.error("分配用户角色异常：{}", e.getMessage(), e);
            return ApiResponse.error("分配异常：" + e.getMessage());
        }
    }

    @GetMapping("/{userId}/permissions")
    @Operation(summary = "获取用户权限", description = "获取指定用户的所有权限标识")
    public ApiResponse<List<String>> getUserPermissions(
            @Parameter(description = "用户ID") @PathVariable Long userId) {
        log.info("获取用户权限请求：userId={}", userId);

        try {
            List<String> permissions = userService.getUserPermissions(userId);
            log.info("获取用户权限成功：userId={}, permissionCount={}", userId, permissions.size());
            return ApiResponse.success(permissions, "获取成功");
        } catch (Exception e) {
            log.error("获取用户权限失败：{}", e.getMessage(), e);
            return ApiResponse.error("获取失败：" + e.getMessage());
        }
    }

    @PutMapping("/password/change")
    @Operation(summary = "修改当前用户密码", description = "修改当前登录用户的密码")
    public ApiResponse<Void> changePassword(
            @Parameter(description = "原密码") @RequestParam String oldPassword,
            @Parameter(description = "新密码") @RequestParam String newPassword) {
        Long userId = securityUtils.getCurrentUserId();
        log.info("修改密码请求：userId={}", userId);

        try {
            // 验证原密码
            boolean verified = userService.verifyPassword(userId, oldPassword);
            if (!verified) {
                log.warn("原密码验证失败：userId={}", userId);
                return ApiResponse.error("原密码错误");
            }

            // 重置密码
            boolean success = userService.resetPassword(userId, newPassword);
            if (success) {
                log.info("修改密码成功：userId={}", userId);
                return ApiResponse.success("修改成功");
            } else {
                log.warn("修改密码失败：userId={}", userId);
                return ApiResponse.error("修改失败");
            }
        } catch (Exception e) {
            log.error("修改密码异常：{}", e.getMessage(), e);
            return ApiResponse.error("修改异常：" + e.getMessage());
        }
    }
}
