    @Transactional
    public UserDTO registerUser(UserDTO userDTO) {
        // 验证租户
        Tenant tenant = tenantMapper.selectByTenantCode(userDTO.getTenantId());
        if (tenant == null) {
            throw new BusinessException("租户不存在或已被禁用");
        }

        // 检查用户数限制
        Integer userCount = userMapper.countByTenant(userDTO.getTenantId());
        if (userCount >= tenant.getMaxUsers()) {
            throw new BusinessException("租户用户数已达到上限");
        }

        // 检查用户名是否已存在
        User existingUser = userMapper.selectByUsernameAndTenant(userDTO.getUsername(), userDTO.getTenantId());
        if (existingUser != null) {
            throw new BusinessException("用户名已存在");
        }

        // 创建用户
        User user = new User();
        BeanUtils.copyProperties(userDTO, user);
        user.setPasswordHash(passwordEncoder.encode(userDTO.getPassword()));
        user.setIsActive(true);
        user.setIsLocked(false);
        user.setFailedLoginAttempts(0);
        user.setMfaEnabled(false);
        user.setCreateTime(LocalDateTime.now());
        user.setUpdateTime(LocalDateTime.now());

        userMapper.insert(user);

        // 分配默认角色
        assignDefaultRole(user.getId(), userDTO.getTenantId());

        UserDTO result = new UserDTO();
        BeanUtils.copyProperties(user, result);
        return result;
    }

    private void assignDefaultRole(Long userId, String tenantId) {
        // 查询默认角色（例如：测试工程师）
        LambdaQueryWrapper<Role> queryWrapper = new LambdaQueryWrapper<>();
        queryWrapper.eq(Role::getTenantId, tenantId)
                   .eq(Role::getRoleCode, "TEST_ENGINEER")
                   .eq(Role::getIsDeleted, false);
        Role defaultRole = roleMapper.selectOne(queryWrapper);

        if (defaultRole != null) {
            UserRole userRole = new UserRole();
            userRole.setUserId(userId);
            userRole.setRoleId(defaultRole.getId());
            userRole.setTenantId(tenantId);
            userRole.setCreateTime(LocalDateTime.now());
            userRole.setCreateUser("system");
            userRoleMapper.insert(userRole);
        }
    }

    @Override
    @Transactional
    public LoginResponse login(LoginRequest loginRequest) {
        String tenantId = loginRequest.getTenantId();
        String username = loginRequest.getUsername();
        String password = loginRequest.getPassword();

        // 记录登录尝试
        LoginLog loginLog = createLoginLog(username, tenantId, loginRequest.getIp(), 
                                          loginRequest.getUserAgent());

        try {
            // 验证用户
            User user = userMapper.selectByUsernameAndTenant(username, tenantId);
            if (user == null) {
                loginLog.setLoginStatus(0);
                loginLog.setFailReason("用户不存在");
                loginLogMapper.insert(loginLog);
                throw new BusinessException("用户名或密码错误");
            }

            // 检查用户状态
            if (!user.getIsActive()) {
                loginLog.setLoginStatus(0);
                loginLog.setFailReason("用户已被禁用");
                loginLogMapper.insert(loginLog);
                throw new BusinessException("用户已被禁用");
            }

            if (user.getIsLocked()) {
                loginLog.setLoginStatus(0);
                loginLog.setFailReason("用户已被锁定");
                loginLogMapper.insert(loginLog);
                throw new BusinessException("用户已被锁定，请联系管理员");
            }

            // 验证密码
            if (!passwordEncoder.matches(password, user.getPasswordHash())) {
                handleFailedLogin(user);
                loginLog.setLoginStatus(0);
                loginLog.setFailReason("密码错误");
                loginLogMapper.insert(loginLog);
                throw new BusinessException("用户名或密码错误");
            }

            // 检查密码是否过期
            if (user.getPasswordExpireTime() != null && 
                user.getPasswordExpireTime().isBefore(LocalDateTime.now())) {
                loginLog.setLoginStatus(0);
                loginLog.setFailReason("密码已过期");
                loginLogMapper.insert(loginLog);
                throw new BusinessException("密码已过期，请修改密码");
            }

            // 重置失败登录次数
            user.setFailedLoginAttempts(0);
            user.setLastLoginTime(LocalDateTime.now());
            userMapper.updateById(user);

            // 生成JWT token
            String token = jwtTokenProvider.createToken(user.getId(), username, tenantId, 
                                                       getUserRoles(user.getId(), tenantId));

            // 记录成功登录
            loginLog.setUserId(user.getId());
            loginLog.setLoginStatus(1);
            loginLog.setMfaVerified(!user.getMfaEnabled()); // 如果启用MFA，需要二次验证
            loginLog.setSessionId(token.substring(0, 32)); // 取token前32位作为session标识
            loginLogMapper.insert(loginLog);

            LoginResponse response = new LoginResponse();
            response.setToken(token);
            response.setUsername(username);
            response.setRealName(user.getRealName());
            response.setTenantId(tenantId);
            response.setMfaRequired(user.getMfaEnabled());
            response.setExpiresIn(jwtTokenProvider.getValidityInMilliseconds() / 1000);

            return response;

        } catch (Exception e) {
            loginLogMapper.insert(loginLog);
            throw e;
        }
    }

    private LoginLog createLoginLog(String username, String tenantId, String ip, String userAgent) {
        LoginLog log = new LoginLog();
        log.setUsername(username);
        log.setLoginIp(ip);
        log.setUserAgent(userAgent);
        log.setTenantId(tenantId);
        log.setCreateTime(LocalDateTime.now());
        // 解析浏览器和操作系统（简化版）
        if (userAgent != null) {
            if (userAgent.contains("Chrome")) {
                log.setBrowser("Chrome");
            } else if (userAgent.contains("Firefox")) {
                log.setBrowser("Firefox");
            } else if (userAgent.contains("Safari")) {
                log.setBrowser("Safari");
            } else if (userAgent.contains("Edge")) {
                log.setBrowser("Edge");
            }

            if (userAgent.contains("Windows")) {
                log.setOs("Windows");
            } else if (userAgent.contains("Mac")) {
                log.setOs("macOS");
            } else if (userAgent.contains("Linux")) {
                log.setOs("Linux");
            }
        }
        return log;
    }

    private void handleFailedLogin(User user) {
        int failedAttempts = user.getFailedLoginAttempts() + 1;
        user.setFailedLoginAttempts(failedAttempts);

        // 如果连续失败5次，锁定账户
        if (failedAttempts >= 5) {
            user.setIsLocked(true);
        }

        userMapper.updateById(user);
    }

    private List<String> getUserRoles(Long userId, String tenantId) {
        List<Role> roles = userRoleMapper.selectRolesByUserId(userId, tenantId);
        return roles.stream()
                   .map(Role::getRoleCode)
                   .collect(Collectors.toList());
    }

    @Override
    public void logout(String token) {
        // JWT是无状态的，通常在前端删除token即可
        // 如果需要服务端控制，可以实现token黑名单
        jwtTokenProvider.invalidateToken(token);
    }

