package com.chinasofti.adapter.testmanagement.repository;

import com.baomidou.mybatisplus.core.mapper.BaseMapper;
import com.chinasofti.adapter.testmanagement.entity.ProjectMember;
import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Param;
import org.apache.ibatis.annotations.Select;

import java.util.List;

/**
 * 项目成员Repository
 */
@Mapper
public interface ProjectMemberRepository extends BaseMapper<ProjectMember> {

    /**
     * 根据项目ID查询项目成员列表（包含用户信息和角色信息）
     */
    @Select("SELECT pm.*, u.username, u.real_name, u.email, u.phone, u.position, " +
            "r.role_code, r.role_name " +
            "FROM tm_project_member pm " +
            "LEFT JOIN tm_user u ON pm.user_id = u.id AND u.is_deleted = 0 " +
            "LEFT JOIN tm_role r ON pm.role_id = r.id AND r.is_deleted = 0 " +
            "WHERE pm.project_id = #{projectId} AND pm.is_deleted = 0 " +
            "ORDER BY pm.created_time DESC")
    List<ProjectMember> findMembersByProjectId(@Param("projectId") Long projectId);

    /**
     * 根据用户ID查询参与的项目列表
     */
    @Select("SELECT pm.*, p.project_code, p.project_name, p.project_status, " +
            "r.role_code, r.role_name " +
            "FROM tm_project_member pm " +
            "LEFT JOIN tm_project p ON pm.project_id = p.id AND p.is_deleted = 0 " +
            "LEFT JOIN tm_role r ON pm.role_id = r.id AND r.is_deleted = 0 " +
            "WHERE pm.user_id = #{userId} AND pm.is_deleted = 0 AND pm.member_status = 1 " +
            "ORDER BY pm.created_time DESC")
    List<ProjectMember> findProjectsByUserId(@Param("userId") Long userId);

    /**
     * 检查用户是否已经是项目成员
     */
    @Select("SELECT COUNT(*) FROM tm_project_member " +
            "WHERE project_id = #{projectId} AND user_id = #{userId} AND is_deleted = 0")
    int checkUserExistsInProject(@Param("projectId") Long projectId, @Param("userId") Long userId);

    /**
     * 根据项目ID和用户ID查询项目成员信息
     */
    @Select("SELECT * FROM tm_project_member " +
            "WHERE project_id = #{projectId} AND user_id = #{userId} AND is_deleted = 0 " +
            "LIMIT 1")
    ProjectMember findByProjectIdAndUserId(@Param("projectId") Long projectId, @Param("userId") Long userId);

    /**
     * 获取项目成员数量
     */
    @Select("SELECT COUNT(*) FROM tm_project_member " +
            "WHERE project_id = #{projectId} AND is_deleted = 0 AND member_status = 1")
    int countProjectMembers(@Param("projectId") Long projectId);
}
