/**
 * 项目成员管理服务实现类
 */
@Service
@Slf4j
public class ProjectMemberServiceImpl extends ServiceImpl<ProjectMemberRepository, ProjectMember> implements ProjectMemberService {

    @Autowired
    private ProjectMemberRepository projectMemberRepository;

    @Autowired
    private ProjectRepository projectRepository;

    @Autowired
    private UserRepository userRepository;

    @Autowired
    private RoleRepository roleRepository;

    @Override
    @Transactional(rollbackFor = Exception.class)
    public boolean addProjectMember(ProjectMemberDTO memberDTO, Long operatorId) {
        log.info("开始添加项目成员，项目ID: {}, 用户ID: {}, 操作人: {}", 
                memberDTO.getProjectId(), memberDTO.getUserId(), operatorId);

        // 验证项目是否存在
        Project project = projectRepository.selectById(memberDTO.getProjectId());
        if (project == null || project.getIsDeleted() == 1) {
            log.error("项目不存在，项目ID: {}", memberDTO.getProjectId());
            throw new RuntimeException("项目不存在");
        }

        // 验证用户是否存在
        User user = userRepository.selectById(memberDTO.getUserId());
        if (user == null || user.getIsDeleted() == 1 || user.getStatus() == 0) {
            log.error("用户不存在或已禁用，用户ID: {}", memberDTO.getUserId());
            throw new RuntimeException("用户不存在或已禁用");
        }

        // 验证角色是否存在
        Role role = roleRepository.selectById(memberDTO.getRoleId());
        if (role == null || role.getIsDeleted() == 1 || role.getStatus() == 0) {
            log.error("角色不存在或已禁用，角色ID: {}", memberDTO.getRoleId());
            throw new RuntimeException("角色不存在或已禁用");
        }

        // 检查用户是否已是项目成员
        int exists = projectMemberRepository.checkUserExistsInProject(memberDTO.getProjectId(), memberDTO.getUserId());
        if (exists > 0) {
            log.warn("用户已是项目成员，项目ID: {}, 用户ID: {}", 
                    memberDTO.getProjectId(), memberDTO.getUserId());
            throw new RuntimeException("用户已是项目成员");
        }

        // 创建项目成员记录
        ProjectMember projectMember = new ProjectMember();
        BeanUtils.copyProperties(memberDTO, projectMember);
        projectMember.setRoleName(role.getRoleName());
        projectMember.setMemberStatus(1); // 已加入
        projectMember.setJoinTime(LocalDateTime.now());
        projectMember.setTenantId(project.getTenantId());
        projectMember.setCreatedBy(operatorId);
        projectMember.setCreatedTime(LocalDateTime.now());
        projectMember.setUpdatedBy(operatorId);
        projectMember.setUpdatedTime(LocalDateTime.now());
        projectMember.setIsDeleted(0);

        int result = projectMemberRepository.insert(projectMember);

        log.info("添加项目成员成功，项目ID: {}, 用户ID: {}, 角色: {}", 
                memberDTO.getProjectId(), memberDTO.getUserId(), role.getRoleName());
        return result > 0;
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public int batchAddProjectMembers(Long projectId, List<ProjectMemberDTO> memberDTOs, Long operatorId) {
        log.info("开始批量添加项目成员，项目ID: {}, 成员数量: {}, 操作人: {}", 
                projectId, memberDTOs.size(), operatorId);

        if (CollectionUtils.isEmpty(memberDTOs)) {
            return 0;
        }

        int successCount = 0;
        List<String> errorMessages = new ArrayList<>();

        for (ProjectMemberDTO memberDTO : memberDTOs) {
            try {
                memberDTO.setProjectId(projectId);
                boolean result = addProjectMember(memberDTO, operatorId);
                if (result) {
                    successCount++;
                }
            } catch (Exception e) {
                log.error("批量添加成员时出错，用户ID: {}, 错误: {}", 
                        memberDTO.getUserId(), e.getMessage());
                errorMessages.add(String.format("用户ID %d: %s", 
                        memberDTO.getUserId(), e.getMessage()));
            }
        }

        log.info("批量添加项目成员完成，成功: {}个, 失败: {}个", 
                successCount, memberDTOs.size() - successCount);

        if (!errorMessages.isEmpty()) {
            throw new RuntimeException("批量添加成员部分失败: " + String.join("; ", errorMessages));
        }

        return successCount;
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public boolean removeProjectMember(Long projectId, Long userId, Long operatorId) {
        log.info("开始移除项目成员，项目ID: {}, 用户ID: {}, 操作人: {}", 
                projectId, userId, operatorId);

        ProjectMember projectMember = projectMemberRepository.findByProjectIdAndUserId(projectId, userId);
        if (projectMember == null) {
            log.error("项目成员关系不存在，项目ID: {}, 用户ID: {}", projectId, userId);
            throw new RuntimeException("项目成员关系不存在");
        }

        // 检查是否为项目经理（项目经理不能移除自己）
        Project project = projectRepository.selectById(projectId);
        if (project != null && project.getManagerId() != null && 
                project.getManagerId().equals(userId)) {
            log.error("不能移除项目经理，项目ID: {}, 用户ID: {}", projectId, userId);
            throw new RuntimeException("不能移除项目经理，请先变更项目经理");
        }

        // 逻辑删除
        projectMember.setMemberStatus(2); // 已退出
        projectMember.setExitTime(LocalDateTime.now());
        projectMember.setUpdatedBy(operatorId);
        projectMember.setUpdatedTime(LocalDateTime.now());
        projectMember.setIsDeleted(1);

        int result = projectMemberRepository.updateById(projectMember);

        log.info("移除项目成员成功，项目ID: {}, 用户ID: {}", projectId, userId);
        return result > 0;
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public boolean updateMemberRole(ProjectMemberUpdateDTO updateDTO, Long operatorId) {
        log.info("开始更新项目成员角色，项目ID: {}, 用户ID: {}, 新角色ID: {}", 
                updateDTO.getProjectId(), updateDTO.getUserId(), updateDTO.getRoleId());

        ProjectMember projectMember = projectMemberRepository.findByProjectIdAndUserId(
                updateDTO.getProjectId(), updateDTO.getUserId());
        if (projectMember == null) {
            log.error("项目成员关系不存在，项目ID: {}, 用户ID: {}", 
                    updateDTO.getProjectId(), updateDTO.getUserId());
            throw new RuntimeException("项目成员关系不存在");
        }

        // 验证新角色是否存在
        Role role = roleRepository.selectById(updateDTO.getRoleId());
        if (role == null || role.getIsDeleted() == 1 || role.getStatus() == 0) {
            log.error("角色不存在或已禁用，角色ID: {}", updateDTO.getRoleId());
            throw new RuntimeException("角色不存在或已禁用");
        }

        // 检查是否为项目经理（项目经理角色有特殊处理）
        Project project = projectRepository.selectById(updateDTO.getProjectId());
        if (project != null && project.getManagerId() != null && 
                project.getManagerId().equals(updateDTO.getUserId()) && 
                !"PROJECT_MANAGER".equals(role.getRoleCode())) {
            log.warn("项目经理角色不能修改为其他角色，项目ID: {}, 用户ID: {}", 
                    updateDTO.getProjectId(), updateDTO.getUserId());
            throw new RuntimeException("项目经理角色不能修改，请先变更项目经理");
        }

        // 更新角色信息
        projectMember.setRoleId(updateDTO.getRoleId());
        projectMember.setRoleName(role.getRoleName());
        projectMember.setUpdatedBy(operatorId);
        projectMember.setUpdatedTime(LocalDateTime.now());

        int result = projectMemberRepository.updateById(projectMember);

        // 如果是项目经理角色，同步更新项目信息
        if ("PROJECT_MANAGER".equals(role.getRoleCode())) {
            project.setManagerId(updateDTO.getUserId());
            project.setManagerName(getUserName(updateDTO.getUserId()));
            project.setUpdatedBy(operatorId);
            project.setUpdatedTime(LocalDateTime.now());
            projectRepository.updateById(project);
            log.info("已更新项目经理，项目ID: {}, 用户ID: {}", 
                    updateDTO.getProjectId(), updateDTO.getUserId());
        }

        log.info("更新项目成员角色成功，项目ID: {}, 用户ID: {}, 新角色: {}", 
                updateDTO.getProjectId(), updateDTO.getUserId(), role.getRoleName());
        return result > 0;
    }

    @Override
    public List<ProjectMemberVO> getProjectMembers(ProjectMemberQueryDTO queryDTO) {
        log.info("查询项目成员列表，项目ID: {}, 角色ID: {}, 状态: {}", 
                queryDTO.getProjectId(), queryDTO.getRoleId(), queryDTO.getMemberStatus());

        LambdaQueryWrapper<ProjectMember> queryWrapper = new LambdaQueryWrapper<>();
        queryWrapper.eq(ProjectMember::getProjectId, queryDTO.getProjectId());
        queryWrapper.eq(ProjectMember::getIsDeleted, 0);

        if (queryDTO.getRoleId() != null) {
            queryWrapper.eq(ProjectMember::getRoleId, queryDTO.getRoleId());
        }

        if (queryDTO.getMemberStatus() != null) {
            queryWrapper.eq(ProjectMember::getMemberStatus, queryDTO.getMemberStatus());
        }

        queryWrapper.orderByDesc(ProjectMember::getCreatedTime);

        List<ProjectMember> members = projectMemberRepository.selectList(queryWrapper);

        if (CollectionUtils.isEmpty(members)) {
            return new ArrayList<>();
        }

        // 获取用户信息
        List<Long> userIds = members.stream()
                .map(ProjectMember::getUserId)
                .distinct()
                .collect(Collectors.toList());

        LambdaQueryWrapper<User> userQueryWrapper = new LambdaQueryWrapper<>();
        userQueryWrapper.in(User::getId, userIds);
        List<User> users = userRepository.selectList(userQueryWrapper);
        Map<Long, User> userMap = users.stream()
                .collect(Collectors.toMap(User::getId, user -> user));

        // 转换为VO
        List<ProjectMemberVO> result = members.stream()
                .map(member -> convertToVO(member, userMap.get(member.getUserId())))
                .collect(Collectors.toList());

        log.info("查询到项目成员数量: {}", result.size());
        return result;
    }

    @Override
    public List<ProjectVO> getUserProjects(Long userId, String tenantId) {
        log.info("查询用户参与的项目列表，用户ID: {}, 租户ID: {}", userId, tenantId);

        List<ProjectMember> projectMembers = projectMemberRepository.findProjectsByUserId(userId);

        if (CollectionUtils.isEmpty(projectMembers)) {
            return new ArrayList<>();
        }

        // 获取项目信息
        List<Long> projectIds = projectMembers.stream()
                .map(ProjectMember::getProjectId)
                .distinct()
                .collect(Collectors.toList());

        LambdaQueryWrapper<Project> projectQueryWrapper = new LambdaQueryWrapper<>();
        projectQueryWrapper.in(Project::getId, projectIds);
        projectQueryWrapper.eq(Project::getTenantId, tenantId);
        projectQueryWrapper.eq(Project::getIsDeleted, 0);
        List<Project> projects = projectRepository.selectList(projectQueryWrapper);

        Map<Long, Project> projectMap = projects.stream()
                .collect(Collectors.toMap(Project::getId, project -> project));

        // 转换为VO
        return projectMembers.stream()
                .filter(member -> projectMap.containsKey(member.getProjectId()))
                .map(member -> {
                    Project project = projectMap.get(member.getProjectId());
                    ProjectVO projectVO = new ProjectVO();
                    BeanUtils.copyProperties(project, projectVO);
                    projectVO.setMemberRole(member.getRoleName());
                    projectVO.setJoinTime(member.getJoinTime());
                    return projectVO;
                })
                .collect(Collectors.toList());
    }

    @Override
    public List<User> getAvailableUsers(Long projectId, String keyword, String tenantId) {
        log.info("获取可添加到项目的用户列表，项目ID: {}, 关键词: {}, 租户ID: {}", 
                projectId, keyword, tenantId);

        // 获取当前项目已有的成员
        List<ProjectMember> existingMembers = projectMemberRepository.findMembersByProjectId(projectId);
        List<Long> existingUserIds = existingMembers.stream()
                .map(ProjectMember::getUserId)
                .collect(Collectors.toList());

        // 查询租户下所有活跃用户
        LambdaQueryWrapper<User> queryWrapper = new LambdaQueryWrapper<>();
        queryWrapper.eq(User::getTenantId, tenantId);
        queryWrapper.eq(User::getStatus, 1);
        queryWrapper.eq(User::getIsDeleted, 0);

        if (!existingUserIds.isEmpty()) {
            queryWrapper.notIn(User::getId, existingUserIds);
        }

        if (keyword != null && !keyword.trim().isEmpty()) {
            queryWrapper.and(wrapper -> wrapper
                    .like(User::getUsername, keyword)
                    .or()
                    .like(User::getRealName, keyword)
                    .or()
                    .like(User::getEmail, keyword));
        }

        queryWrapper.orderByAsc(User::getRealName);

        List<User> users = userRepository.selectList(queryWrapper);

        log.info("查询到可添加用户数量: {}", users.size());
        return users;
    }

    /**
     * 将ProjectMember转换为ProjectMemberVO
     */
    private ProjectMemberVO convertToVO(ProjectMember member, User user) {
        if (member == null) {
            return null;
        }

        ProjectMemberVO vo = new ProjectMemberVO();
        BeanUtils.copyProperties(member, vo);

        if (user != null) {
            vo.setUsername(user.getUsername());
            vo.setRealName(user.getRealName());
            vo.setEmail(user.getEmail());
            vo.setPhone(user.getPhone());
            vo.setPosition(user.getPosition());
        }

        return vo;
    }

    /**
     * 获取用户姓名
     */
    private String getUserName(Long userId) {
        User user = userRepository.selectById(userId);
        return user != null ? user.getRealName() : "";
    }
}
