import com.chinasofti.testmanagement.entity.TestCaseCategory;
import com.chinasofti.testmanagement.mapper.TestCaseCategoryMapper;
import com.chinasofti.testmanagement.service.ITestCaseCategoryService;
import lombok.extern.slf4j.Slf4j;
import org.apache.commons.lang3.StringUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.util.CollectionUtils;

import java.time.LocalDateTime;
import java.util.*;
import java.util.stream.Collectors;

/**
 * 测试用例分类服务实现
 * 
 * @author 刘贺
 * @since 2025-08-16
 */
@Slf4j
@Service
public class TestCaseCategoryServiceImpl extends ServiceImpl<TestCaseCategoryMapper, TestCaseCategory> 
        implements ITestCaseCategoryService {

    @Autowired
    private TestCaseCategoryMapper testCaseCategoryMapper;

    @Override
    @Transactional(rollbackFor = Exception.class)
    public boolean createCategory(TestCaseCategory category, Long userId, Long tenantId) {
        log.info("开始创建测试用例分类，分类名称：{}，用户ID：{}，租户ID：{}", 
                category.getCategoryName(), userId, tenantId);

        try {
            // 1. 验证分类编码唯一性
            if (StringUtils.isNotBlank(category.getCategoryCode())) {
                Integer exists = testCaseCategoryMapper.checkCategoryCodeExists(
                        category.getCategoryCode(), tenantId, null);
                if (exists > 0) {
                    log.error("分类编码已存在：{}", category.getCategoryCode());
                    throw new RuntimeException("分类编码已存在");
                }
            }

            // 2. 设置父分类信息
            Long parentId = category.getParentId() != null ? category.getParentId() : 0L;
            category.setParentId(parentId);

            // 3. 计算分类层级和路径
            if (parentId == 0) {
                // 根分类
                category.setLevel(1);
                category.setPath("0");
            } else {
                // 子分类，查询父分类信息
                TestCaseCategory parentCategory = this.getById(parentId);
                if (parentCategory == null || !parentCategory.getTenantId().equals(tenantId)) {
                    log.error("父分类不存在或无权访问，父分类ID：{}", parentId);
                    throw new RuntimeException("父分类不存在或无权访问");
                }
                category.setLevel(parentCategory.getLevel() + 1);
                category.setPath(parentCategory.getPath() + "," + parentId);
            }

            // 4. 设置默认值
            if (category.getSortOrder() == null) {
                // 查询同级分类的最大排序号
                Integer maxSortOrder = getMaxSortOrderByParentId(parentId, tenantId);
                category.setSortOrder(maxSortOrder + 1);
            }

            // 5. 设置创建信息
            category.setCreateBy(userId);
            category.setUpdateBy(userId);
            category.setTenantId(tenantId);
            category.setCreateTime(LocalDateTime.now());
            category.setUpdateTime(LocalDateTime.now());
            category.setDeleted(0);

            // 6. 保存分类
            boolean result = this.save(category);

            // 7. 更新分类路径（包含自身ID）
            if (result) {
                category.setPath(category.getPath() + "," + category.getId());
                this.updateById(category);
                log.info("测试用例分类创建成功，分类ID：{}", category.getId());
            }

            return result;
        } catch (Exception e) {
            log.error("创建测试用例分类失败，分类名称：{}，错误信息：{}", 
                    category.getCategoryName(), e.getMessage(), e);
            throw e;
        }
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public boolean updateCategory(TestCaseCategory category, Long userId, Long tenantId) {
        log.info("开始更新测试用例分类，分类ID：{}，用户ID：{}，租户ID：{}", 
                category.getId(), userId, tenantId);

        try {
            // 1. 验证分类是否存在
            TestCaseCategory existingCategory = this.getById(category.getId());
            if (existingCategory == null || !existingCategory.getTenantId().equals(tenantId)) {
                log.error("分类不存在或无权访问，分类ID：{}", category.getId());
                throw new RuntimeException("分类不存在或无权访问");
            }

            // 2. 验证分类编码唯一性（排除自身）
            if (StringUtils.isNotBlank(category.getCategoryCode())) {
                Integer exists = testCaseCategoryMapper.checkCategoryCodeExists(
                        category.getCategoryCode(), tenantId, category.getId());
                if (exists > 0) {
                    log.error("分类编码已存在：{}", category.getCategoryCode());
                    throw new RuntimeException("分类编码已存在");
                }
            }

            // 3. 如果修改了父分类，需要重新计算层级和路径
            Long newParentId = category.getParentId() != null ? category.getParentId() : existingCategory.getParentId();
            if (!newParentId.equals(existingCategory.getParentId())) {
                // 不能将分类移动到自己的子分类下
                if (isDescendant(category.getId(), newParentId, tenantId)) {
                    log.error("不能将分类移动到自己的子分类下，分类ID：{}，目标父分类ID：{}", 
                            category.getId(), newParentId);
                    throw new RuntimeException("不能将分类移动到自己的子分类下");
                }

                // 更新父分类
                updateParentCategory(category, newParentId, existingCategory, tenantId);
            }

            // 4. 更新分类信息
            category.setUpdateBy(userId);
            category.setUpdateTime(LocalDateTime.now());

            // 5. 保存更新
            boolean result = this.updateById(category);
            log.info("测试用例分类更新{}，分类ID：{}", result ? "成功" : "失败", category.getId());

            return result;
