package com.chinasofti.testmanagement.mapper;

import com.baomidou.mybatisplus.core.mapper.BaseMapper;
import com.baomidou.mybatisplus.core.metadata.IPage;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import com.chinasofti.testmanagement.entity.TestTask;
import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Param;
import org.apache.ibatis.annotations.Select;
import org.apache.ibatis.annotations.Update;
import java.util.Date;
import java.util.List;
import java.util.Map;

/**
 * 测试任务Mapper接口
 * 
 * @author 刘贺
 * @since 2025-09-01
 */
@Mapper
public interface TestTaskMapper extends BaseMapper<TestTask> {

    /**
     * 分页查询任务池中的任务（待分配的任务）
     * 
     * @param page 分页参数
     * @param taskName 任务名称（模糊查询）
     * @param taskType 任务类型
     * @param priority 优先级
     * @param projectId 项目ID
     * @param tenantId 租户ID
     * @return 分页结果
     */
    @Select("<script>" +
            "SELECT t.*, " +
            "p.project_name, " +
            "tp.plan_name as test_plan_name, " +
            "tc.case_name as test_case_name, " +
            "te.env_name as test_env_name, " +
            "td.device_name as test_device_name " +
            "FROM test_task t " +
            "LEFT JOIN project p ON t.project_id = p.id AND p.deleted = 0 " +
            "LEFT JOIN test_plan tp ON t.test_plan_id = tp.id AND tp.deleted = 0 " +
            "LEFT JOIN test_case tc ON t.test_case_id = tc.id AND tc.deleted = 0 " +
            "LEFT JOIN test_env te ON t.test_env_id = te.id AND te.deleted = 0 " +
            "LEFT JOIN test_device td ON t.test_device_id = td.id AND td.deleted = 0 " +
            "WHERE t.deleted = 0 AND t.tenant_id = #{tenantId} " +
            "AND t.task_status = 1 " +  // 任务状态：待分配
            "<if test='projectId != null'>AND t.project_id = #{projectId}</if>" +
            "<if test='taskName != null and taskName != \"\"'>" +
            "AND t.task_name LIKE CONCAT('%', #{taskName}, '%')" +
            "</if>" +
            "<if test='taskType != null'>AND t.task_type = #{taskType}</if>" +
            "<if test='priority != null'>AND t.priority = #{priority}</if>" +
            "ORDER BY t.priority ASC, t.create_time DESC" +
            "</script>")
    IPage<TestTask> selectTaskPoolPage(Page<TestTask> page,
                                        @Param("taskName") String taskName,
                                        @Param("taskType") Integer taskType,
                                        @Param("priority") Integer priority,
                                        @Param("projectId") Long projectId,
                                        @Param("tenantId") Long tenantId);

    /**
     * 根据项目ID统计任务池中的任务数量
     * 
     * @param projectId 项目ID
     * @param tenantId 租户ID
     * @return 统计结果
     */
    @Select("SELECT COUNT(*) FROM test_task " +
            "WHERE project_id = #{projectId} " +
            "AND tenant_id = #{tenantId} " +
            "AND deleted = 0 " +
            "AND task_status = 1")  // 任务状态：待分配
    Integer countTaskPoolByProjectId(@Param("projectId") Long projectId,
                                     @Param("tenantId") Long tenantId);

    /**
     * 根据优先级统计任务池中的任务分布
     * 
     * @param projectId 项目ID
     * @param tenantId 租户ID
     * @return 优先级分布统计
     */
    @Select("SELECT priority, COUNT(*) as task_count " +
            "FROM test_task " +
            "WHERE project_id = #{projectId} " +
            "AND tenant_id = #{tenantId} " +
            "AND deleted = 0 " +
            "AND task_status = 1 " +
            "GROUP BY priority " +
            "ORDER BY priority ASC")
    List<Map<String, Object>> countTaskPoolByPriority(@Param("projectId") Long projectId,
                                                      @Param("tenantId") Long tenantId);

    /**
     * 批量更新任务优先级
     * 
     * @param taskIds 任务ID列表
     * @param priority 新的优先级
     * @param updateBy 更新人ID
     * @param tenantId 租户ID
     * @return 更新条数
     */
    @Update("<script>" +
            "UPDATE test_task " +
            "SET priority = #{priority}, " +
            "update_by = #{updateBy}, " +
            "update_time = NOW() " +
            "WHERE deleted = 0 AND tenant_id = #{tenantId} " +
            "AND id IN " +
            "<foreach collection='taskIds' item='taskId' open='(' separator=',' close=')'>" +
            "#{taskId}" +
            "</foreach>" +
            "</script>")
    Integer batchUpdatePriority(@Param("taskIds") List<Long> taskIds,
                                @Param("priority") Integer priority,
                                @Param("updateBy") Long updateBy,
                                @Param("tenantId") Long tenantId);

    /**
     * 批量分配任务
     * 
     * @param taskIds 任务ID列表
     * @param assigneeId 分配人ID
     * @param assignTime 分配时间
     * @param updateBy 更新人ID
     * @param tenantId 租户ID
     * @return 更新条数
     */
    @Update("<script>" +
            "UPDATE test_task " +
            "SET task_status = 2, " +  // 任务状态：已分配
            "assignee_id = #{assigneeId}, " +
            "assign_time = #{assignTime}, " +
            "update_by = #{updateBy}, " +
            "update_time = NOW() " +
            "WHERE deleted = 0 AND tenant_id = #{tenantId} " +
            "AND task_status = 1 " +  // 只分配待分配状态的任务
            "AND id IN " +
            "<foreach collection='taskIds' item='taskId' open='(' separator=',' close=')'>" +
            "#{taskId}" +
            "</foreach>" +
            "</script>")
    Integer batchAssignTasks(@Param("taskIds") List<Long> taskIds,
                             @Param("assigneeId") Long assigneeId,
                             @Param("assignTime") Date assignTime,
                             @Param("updateBy") Long updateBy,
                             @Param("tenantId") Long tenantId);

    /**
     * 查询即将超时的任务（距离计划结束时间小于指定天数）
     * 
     * @param days 天数
     * @param tenantId 租户ID
     * @return 即将超时的任务列表
     */
    @Select("SELECT t.*, " +
            "p.project_name, " +
            "DATEDIFF(t.plan_end_time, NOW()) as remaining_days " +
            "FROM test_task t " +
            "LEFT JOIN project p ON t.project_id = p.id AND p.deleted = 0 " +
            "WHERE t.deleted = 0 AND t.tenant_id = #{tenantId} " +
            "AND t.task_status IN (1, 2, 3) " +  // 待分配、已分配、执行中
            "AND t.plan_end_time IS NOT NULL " +
            "AND DATEDIFF(t.plan_end_time, NOW()) BETWEEN 0 AND #{days} " +
            "ORDER BY t.priority ASC, t.plan_end_time ASC")
    List<TestTask> selectTasksNearingDeadline(@Param("days") Integer days,
                                              @Param("tenantId") Long tenantId);

    /**
     * 根据任务编号查询任务
     * 
     * @param taskCode 任务编号
     * @param tenantId 租户ID
     * @return 任务信息
     */
    @Select("SELECT t.*, " +
            "p.project_name, " +
            "tp.plan_name as test_plan_name, " +
            "tc.case_name as test_case_name, " +
            "u1.real_name as assignee_name, " +
            "u2.real_name as executor_name " +
            "FROM test_task t " +
            "LEFT JOIN project p ON t.project_id = p.id AND p.deleted = 0 " +
            "LEFT JOIN test_plan tp ON t.test_plan_id = tp.id AND tp.deleted = 0 " +
            "LEFT JOIN test_case tc ON t.test_case_id = tc.id AND tc.deleted = 0 " +
            "LEFT JOIN sys_user u1 ON t.assignee_id = u1.id AND u1.deleted = 0 " +
            "LEFT JOIN sys_user u2 ON t.executor_id = u2.id AND u2.deleted = 0 " +
            "WHERE t.deleted = 0 AND t.tenant_id = #{tenantId} " +
            "AND t.task_code = #{taskCode}")
    TestTask selectTaskByCode(@Param("taskCode") String taskCode,
                              @Param("tenantId") Long tenantId);

    /**
     * 查询任务统计信息
     * 
