    @Override
    @Transactional(rollbackFor = Exception.class)
    public boolean createTask(TestTask task, List<Long> caseIds, Long userId, Long tenantId) {
        log.info("开始创建测试任务，任务名称：{}，用户ID：{}，租户ID：{}", 
                task.getTaskName(), userId, tenantId);

        try {
            // 1. 生成任务编号（如果未提供）
            if (StringUtils.isBlank(task.getTaskCode())) {
                String taskCode = generateTaskCode(tenantId);
                task.setTaskCode(taskCode);
            } else {
                // 检查任务编号是否已存在
                TestTask existingTask = testTaskMapper.selectTaskByCode(task.getTaskCode(), tenantId);
                if (existingTask != null) {
                    log.error("任务编号已存在：{}", task.getTaskCode());
                    throw new RuntimeException("任务编号已存在");
                }
            }

            // 2. 设置任务状态为待分配（任务池）
            task.setTaskStatus(1);
            task.setCompletionPercentage(0);

            // 3. 设置创建信息
            task.setCreateBy(userId);
            task.setUpdateBy(userId);
            task.setTenantId(tenantId);
            task.setCreateTime(LocalDateTime.now());
            task.setUpdateTime(LocalDateTime.now());
            task.setDeleted(0);

            // 4. 保存任务
            boolean result = this.save(task);

            // 5. 保存任务与用例关联关系
            if (result && !CollectionUtils.isEmpty(caseIds)) {
                saveTaskCaseRelations(task.getId(), caseIds, userId, tenantId);
            }

            log.info("测试任务创建成功，任务ID：{}，任务编号：{}", task.getId(), task.getTaskCode());
            return result;
        } catch (Exception e) {
            log.error("创建测试任务失败，任务名称：{}，错误信息：{}", 
                    task.getTaskName(), e.getMessage(), e);
            throw e;
        }
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public boolean updateTask(TestTask task, Long userId, Long tenantId) {
        log.info("开始更新测试任务，任务ID：{}，用户ID：{}，租户ID：{}", 
                task.getId(), userId, tenantId);

        try {
            // 1. 验证任务是否存在
            TestTask existingTask = this.getById(task.getId());
            if (existingTask == null || !existingTask.getTenantId().equals(tenantId)) {
                log.error("任务不存在或无权访问，任务ID：{}", task.getId());
                throw new RuntimeException("任务不存在或无权访问");
            }

            // 2. 验证任务编号唯一性（如果修改了任务编号）
            if (StringUtils.isNotBlank(task.getTaskCode()) && 
                !task.getTaskCode().equals(existingTask.getTaskCode())) {
                TestTask codeExists = testTaskMapper.selectTaskByCode(task.getTaskCode(), tenantId);
                if (codeExists != null) {
                    log.error("任务编号已存在：{}", task.getTaskCode());
                    throw new RuntimeException("任务编号已存在");
                }
            }

            // 3. 更新任务信息
            task.setUpdateBy(userId);
            task.setUpdateTime(LocalDateTime.now());

            // 4. 保存更新
            boolean result = this.updateById(task);
            log.info("测试任务更新{}，任务ID：{}", result ? "成功" : "失败", task.getId());

            return result;
        } catch (Exception e) {
            log.error("更新测试任务失败，任务ID：{}，错误信息：{}", 
                    task.getId(), e.getMessage(), e);
            throw e;
        }
    }

