    @Override
    public Map<String, Object> getTaskStatistics(Long projectId, Long tenantId) {
        log.info("获取任务统计信息，项目ID：{}，租户ID：{}", projectId, tenantId);

        try {
            Map<String, Object> statistics = testTaskMapper.selectTaskStatistics(projectId, tenantId);

            // 补充计算字段
            if (statistics != null) {
                Double totalEstimatedHours = (Double) statistics.get("total_estimated_hours");
                Double totalActualHours = (Double) statistics.get("total_actual_hours");

                // 计算进度百分比
                Long totalTasks = (Long) statistics.get("total_tasks");
                Long completedTasks = (Long) statistics.get("completed_tasks");

                if (totalTasks != null && totalTasks > 0) {
                    Double completionRate = (completedTasks.doubleValue() / totalTasks.doubleValue()) * 100;
                    statistics.put("completion_rate", Math.round(completionRate * 100.0) / 100.0);
                } else {
                    statistics.put("completion_rate", 0);
                }

                // 计算工作量偏差
                if (totalEstimatedHours != null && totalEstimatedHours > 0) {
                    if (totalActualHours == null) totalActualHours = 0.0;
                    Double deviation = ((totalActualHours - totalEstimatedHours) / totalEstimatedHours) * 100;
                    statistics.put("workload_deviation", Math.round(deviation * 100.0) / 100.0);
                } else {
                    statistics.put("workload_deviation", 0);
                }
            }

            return statistics;
        } catch (Exception e) {
            log.error("获取任务统计信息失败，错误信息：{}", e.getMessage(), e);
            throw e;
        }
    }

    @Override
    public Map<String, Object> getTaskPoolStatistics(Long projectId, Long tenantId) {
        log.info("获取任务池统计信息，项目ID：{}，租户ID：{}", projectId, tenantId);

        try {
            Map<String, Object> result = new HashMap<>();

            // 1. 任务池任务总数
            Integer totalTasks = testTaskMapper.countTaskPoolByProjectId(projectId, tenantId);
            result.put("total_tasks", totalTasks != null ? totalTasks : 0);

            // 2. 按优先级统计
            List<Map<String, Object>> priorityStats = testTaskMapper.countTaskPoolByPriority(projectId, tenantId);
            result.put("priority_stats", priorityStats);

            // 3. 按任务类型统计
            List<Map<String, Object>> typeStats = testTaskMapper.countTaskPoolByType(projectId, tenantId);
            result.put("type_stats", typeStats);

            // 4. 计算各优先级占比
            if (totalTasks != null && totalTasks > 0) {
                Map<Integer, Double> priorityPercentages = new HashMap<>();
                for (Map<String, Object> stat : priorityStats) {
                    Integer priority = (Integer) stat.get("priority");
                    Long count = (Long) stat.get("task_count");
                    double percentage = (count.doubleValue() / totalTasks) * 100;
                    priorityPercentages.put(priority, Math.round(percentage * 100.0) / 100.0);
                }
                result.put("priority_percentages", priorityPercentages);
            }

            return result;
        } catch (Exception e) {
            log.error("获取任务池统计信息失败，错误信息：{}", e.getMessage(), e);
            throw e;
        }
    }

