        log.info("更新任务进度，任务ID：{}，完成百分比：{}，用户ID：{}", 
                taskId, completionPercentage, userId);

        try {
            // 验证完成百分比
            if (completionPercentage < 0 || completionPercentage > 100) {
                log.error("完成百分比无效：{}", completionPercentage);
                throw new RuntimeException("完成百分比无效，必须为0-100");
            }

            // 获取任务
            TestTask task = this.getById(taskId);
            if (task == null || !task.getTenantId().equals(tenantId)) {
                log.error("任务不存在或无权访问，任务ID：{}", taskId);
                throw new RuntimeException("任务不存在或无权访问");
            }

            // 更新完成百分比
            task.setCompletionPercentage(completionPercentage);
            task.setUpdateBy(userId);
            task.setUpdateTime(LocalDateTime.now());

            // 如果完成百分比为100%，自动完成任务
            if (completionPercentage == 100 && task.getTaskStatus() == 3) {
                task.setTaskStatus(4); // 已完成
                task.setActualEndTime(new Date());
            }

            boolean result = this.updateById(task);
            log.info("更新任务进度{}，任务ID：{}", result ? "成功" : "失败", taskId);
            return result;
        } catch (Exception e) {
            log.error("更新任务进度失败，任务ID：{}，错误信息：{}", 
                    taskId, e.getMessage(), e);
            throw e;
        }
    }

