    @Override
    @Transactional(rollbackFor = Exception.class)
    public boolean completeTask(Long taskId, Integer taskResult, Double actualHours, 
                                String failureReason, Long userId, Long tenantId) {
        log.info("完成任务，任务ID：{}，任务结果：{}，实际工作量：{}，用户ID：{}", 
                taskId, taskResult, actualHours, userId);

        try {
            TestTask task = this.getById(taskId);
            if (task == null || !task.getTenantId().equals(tenantId)) {
                log.error("任务不存在或无权访问，任务ID：{}", taskId);
                throw new RuntimeException("任务不存在或无权访问");
            }

            // 更新任务信息
            task.setTaskStatus(4); // 已完成
            task.setTaskResult(taskResult);
            task.setActualHours(actualHours);
            task.setActualEndTime(new Date());
            task.setCompletionPercentage(100);
            task.setUpdateBy(userId);
            task.setUpdateTime(LocalDateTime.now());

            // 如果任务结果为失败，记录失败原因
            if (taskResult == 2 && StringUtils.isNotBlank(failureReason)) {
                task.setFailureReason(failureReason);
            }

            boolean result = this.updateById(task);
            log.info("完成任务{}，任务ID：{}", result ? "成功" : "失败", taskId);
            return result;
        } catch (Exception e) {
            log.error("完成任务失败，任务ID：{}，错误信息：{}", 
                    taskId, e.getMessage(), e);
            throw e;
        }
    }

    @Override
    public List<TestTaskCaseRel> getTaskCaseRelations(Long taskId, Long tenantId) {
        log.info("获取任务关联的测试用例，任务ID：{}，租户ID：{}", taskId, tenantId);

        try {
            return testTaskCaseRelMapper.selectByTestTaskId(taskId, tenantId);
        } catch (Exception e) {
            log.error("获取任务关联的测试用例失败，任务ID：{}，错误信息：{}", 
                    taskId, e.getMessage(), e);
            throw e;
        }
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public boolean updateTaskCaseRelations(Long taskId, List<Long> caseIds, Long userId, Long tenantId) {
        log.info("更新任务关联的测试用例，任务ID：{}，用例ID数量：{}，用户ID：{}", 
                taskId, caseIds != null ? caseIds.size() : 0, userId);

        try {
            // 1. 删除现有的关联关系
            testTaskCaseRelMapper.deleteByTestTaskId(taskId, tenantId);

            // 2. 保存新的关联关系
            if (!CollectionUtils.isEmpty(caseIds)) {
                saveTaskCaseRelations(taskId, caseIds, userId, tenantId);
            }

            log.info("更新任务关联的测试用例成功，任务ID：{}", taskId);
            return true;
        } catch (Exception e) {
            log.error("更新任务关联的测试用例失败，任务ID：{}，错误信息：{}", 
                    taskId, e.getMessage(), e);
            throw e;
        }
    }

    /**
     * 保存任务与用例关联关系
     */
    private void saveTaskCaseRelations(Long taskId, List<Long> caseIds, Long userId, Long tenantId) {
        List<TestTaskCaseRel> relations = new ArrayList<>();

        for (int i = 0; i < caseIds.size(); i++) {
            TestTaskCaseRel relation = new TestTaskCaseRel();
            relation.setTestTaskId(taskId);
            relation.setTestCaseId(caseIds.get(i));
            relation.setExecuteOrder(i + 1);
            relation.setExecuteStatus(1); // 未开始
            relation.setCreateBy(userId);
            relation.setTenantId(tenantId);
            relation.setCreateTime(LocalDateTime.now());
            relations.add(relation);
        }

        testTaskCaseRelMapper.batchInsertRelations(relations);
    }

    /**
     * 生成任务编号
     */
    private String generateTaskCode(Long tenantId) {
        // 格式：TASK-租户ID-年月日-序号
        String dateStr = new java.text.SimpleDateFormat("yyyyMMdd").format(new Date());

        // 查询当天的任务数量
        LambdaQueryWrapper<TestTask> queryWrapper = Wrappers.lambdaQuery();
        queryWrapper.eq(TestTask::getTenantId, tenantId)
                   .likeRight(TestTask::getTaskCode, "TASK-" + tenantId + "-" + dateStr)
                   .orderByDesc(TestTask::getId)
                   .last("LIMIT 1");

        TestTask lastTask = this.getOne(queryWrapper);
        int sequence = 1;

        if (lastTask != null && StringUtils.isNotBlank(lastTask.getTaskCode())) {
            String lastCode = lastTask.getTaskCode();
            String[] parts = lastCode.split("-");
            if (parts.length == 4) {
                try {
                    sequence = Integer.parseInt(parts[3]) + 1;
                } catch (NumberFormatException e) {
                    sequence = 1;
                }
            }
        }

        return String.format("TASK-%d-%s-%04d", tenantId, dateStr, sequence);
    }

    /**
     * 检查是否为后代分类（用于防止循环引用）
     */
    private boolean isDescendant(Long categoryId, Long parentId, Long tenantId) {
        if (parentId == 0) return false;

        TestTaskCategory parentCategory = testTaskCategoryService.getById(parentId);
        if (parentCategory == null) return false;

        String parentPath = parentCategory.getPath();
        if (StringUtils.isBlank(parentPath)) return false;

        return parentPath.contains(categoryId.toString());
    }

    /**
     * 更新父分类信息
     */
    private void updateParentCategory(TestTaskCategory category, Long newParentId, 
                                      TestTaskCategory existingCategory, Long tenantId) {
        if (newParentId == 0) {
            // 移动到根分类
            category.setLevel(1);
            category.setPath("0");
        } else {
            // 查询新的父分类
            TestTaskCategory newParent = testTaskCategoryService.getById(newParentId);
            if (newParent == null || !newParent.getTenantId().equals(tenantId)) {
                throw new RuntimeException("新的父分类不存在或无权访问");
            }
            category.setLevel(newParent.getLevel() + 1);
            category.setPath(newParent.getPath() + "," + newParentId);
        }

        // 更新路径（包含自身ID）
        category.setPath(category.getPath() + "," + category.getId());

        // 更新所有子分类的路径和层级
        updateChildrenPath(category.getId(), category.getPath(), category.getLevel(), tenantId);
    }

    /**
     * 更新子分类路径
     */
    private void updateChildrenPath(Long parentId, String parentPath, Integer parentLevel, Long tenantId) {
        List<TestTaskCategory> children = testTaskCategoryService.getChildrenByParentId(parentId, tenantId);
        for (TestTaskCategory child : children) {
            child.setPath(parentPath + "," + child.getId());
            child.setLevel(parentLevel + 1);
            testTaskCategoryService.updateById(child);

            // 递归更新孙子分类
            updateChildrenPath(child.getId(), child.getPath(), child.getLevel(), tenantId);
        }
    }

    /**
     * 获取同级分类的最大排序号
     */
    private Integer getMaxSortOrderByParentId(Long parentId, Long tenantId) {
        LambdaQueryWrapper<TestTaskCategory> queryWrapper = Wrappers.lambdaQuery();
        queryWrapper.eq(TestTaskCategory::getParentId, parentId)
                   .eq(TestTaskCategory::getTenantId, tenantId)
                   .eq(TestTaskCategory::getDeleted, 0)
                   .orderByDesc(TestTaskCategory::getSortOrder)
                   .last("LIMIT 1");

        TestTaskCategory lastCategory = this.getOne(queryWrapper);
        return lastCategory != null ? lastCategory.getSortOrder() : 0;
    }
}
