@Service
@Slf4j
public class DashboardServiceImpl implements DashboardService {

    @Autowired
    private DashboardRepository dashboardRepository;

    @Autowired
    private DashboardChartRepository chartRepository;

    @Autowired
    private ChartDataCacheRepository cacheRepository;

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Result<Dashboard> createDashboard(Dashboard dashboard) {
        try {
            log.info("开始创建仪表盘，名称：{}，项目ID：{}", dashboard.getName(), dashboard.getProjectId());

            // 检查名称是否重复
            int count = dashboardRepository.countByNameAndProject(
                dashboard.getName(), 
                dashboard.getTenantId(), 
                dashboard.getProjectId()
            );

            if (count > 0) {
                log.warn("仪表盘名称重复：{}", dashboard.getName());
                return Result.error("仪表盘名称已存在，请使用其他名称");
            }

            // 如果是设置为默认，先取消其他默认设置
            if (Boolean.TRUE.equals(dashboard.getIsDefault())) {
                Dashboard defaultDashboard = dashboardRepository.selectOne(
                    new QueryWrapper<Dashboard>()
                        .eq("tenant_id", dashboard.getTenantId())
                        .eq("project_id", dashboard.getProjectId())
                        .eq("is_default", 1)
                        .eq("deleted", 0)
                );

                if (defaultDashboard != null) {
                    defaultDashboard.setIsDefault(false);
                    dashboardRepository.updateById(defaultDashboard);
                    log.info("取消原有的默认仪表盘：{}", defaultDashboard.getId());
                }
            }

            // 保存仪表盘
            int result = dashboardRepository.insert(dashboard);
            if (result > 0) {
                log.info("仪表盘创建成功，ID：{}", dashboard.getId());
                return Result.success(dashboard);
            } else {
                log.error("仪表盘创建失败");
                return Result.error("创建失败");
            }
        } catch (Exception e) {
            log.error("创建仪表盘异常：", e);
            throw new RuntimeException("创建仪表盘失败", e);
        }
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Result<Dashboard> updateDashboard(Dashboard dashboard) {
        try {
            log.info("开始更新仪表盘，ID：{}", dashboard.getId());

            Dashboard existing = dashboardRepository.selectById(dashboard.getId());
            if (existing == null || existing.getDeleted() == 1) {
                return Result.error("仪表盘不存在");
            }

            // 检查名称是否重复（排除自身）
            if (!existing.getName().equals(dashboard.getName())) {
                int count = dashboardRepository.countByNameAndProject(
                    dashboard.getName(), 
                    existing.getTenantId(), 
                    existing.getProjectId()
                );

                if (count > 0) {
                    return Result.error("仪表盘名称已存在，请使用其他名称");
                }
            }

            // 如果是设置为默认，先取消其他默认设置
            if (Boolean.TRUE.equals(dashboard.getIsDefault()) && 
                !Boolean.TRUE.equals(existing.getIsDefault())) {

                Dashboard defaultDashboard = dashboardRepository.selectOne(
                    new QueryWrapper<Dashboard>()
                        .eq("tenant_id", existing.getTenantId())
                        .eq("project_id", existing.getProjectId())
                        .eq("is_default", 1)
                        .eq("deleted", 0)
                );

                if (defaultDashboard != null) {
                    defaultDashboard.setIsDefault(false);
                    dashboardRepository.updateById(defaultDashboard);
                    log.info("取消原有的默认仪表盘：{}", defaultDashboard.getId());
                }
            }

            // 更新仪表盘
            dashboard.setUpdateTime(LocalDateTime.now());
            int result = dashboardRepository.updateById(dashboard);

            if (result > 0) {
                log.info("仪表盘更新成功，ID：{}", dashboard.getId());
                return Result.success(dashboard);
            } else {
                return Result.error("更新失败");
            }
        } catch (Exception e) {
            log.error("更新仪表盘异常：", e);
            throw new RuntimeException("更新仪表盘失败", e);
        }
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Result<Boolean> deleteDashboard(Long id, Long tenantId) {
        try {
            log.info("开始删除仪表盘，ID：{}，租户ID：{}", id, tenantId);

            Dashboard dashboard = dashboardRepository.selectById(id);
            if (dashboard == null || !dashboard.getTenantId().equals(tenantId)) {
                return Result.error("仪表盘不存在或无权操作");
            }

            // 逻辑删除仪表盘
            dashboard.setDeleted(1);
            dashboard.setUpdateTime(LocalDateTime.now());
            int result = dashboardRepository.updateById(dashboard);

            if (result > 0) {
                // 删除关联的图表
                List<DashboardChart> charts = chartRepository.findByDashboardId(id);
                for (DashboardChart chart : charts) {
                    chart.setDeleted(1);
                    chartRepository.updateById(chart);

                    // 删除图表缓存
                    cacheRepository.deleteByChartId(chart.getId());
                }

                log.info("仪表盘删除成功，ID：{}", id);
                return Result.success(true);
            } else {
                return Result.error("删除失败");
            }
        } catch (Exception e) {
            log.error("删除仪表盘异常：", e);
            throw new RuntimeException("删除仪表盘失败", e);
        }
    }

    @Override
    public Result<DashboardVO> getDashboardDetail(Long id, Long tenantId) {
        try {
            log.debug("获取仪表盘详情，ID：{}，租户ID：{}", id, tenantId);

            Dashboard dashboard = dashboardRepository.selectById(id);
            if (dashboard == null || dashboard.getDeleted() == 1 || 
                !dashboard.getTenantId().equals(tenantId)) {
                return Result.error("仪表盘不存在或无权访问");
            }

            // 获取仪表盘的所有图表
            List<DashboardChart> charts = chartRepository.findByDashboardId(id);

            // 构建VO对象
            DashboardVO vo = new DashboardVO();
            vo.setDashboard(dashboard);
            vo.setCharts(charts.stream()
                .map(this::convertToChartVO)
                .collect(Collectors.toList()));

            return Result.success(vo);
        } catch (Exception e) {
            log.error("获取仪表盘详情异常：", e);
            throw new RuntimeException("获取仪表盘详情失败", e);
        }
    }

    @Override
    public Result<List<DashboardVO>> getProjectDashboards(Long projectId, Long tenantId) {
        try {
            log.debug("获取项目仪表盘列表，项目ID：{}，租户ID：{}", projectId, tenantId);

            List<Dashboard> dashboards = dashboardRepository.findByTenantAndProject(tenantId, projectId);

            List<DashboardVO> vos = dashboards.stream().map(dashboard -> {
                DashboardVO vo = new DashboardVO();
                vo.setDashboard(dashboard);

                // 获取每个仪表盘的图表数量
                int chartCount = chartRepository.selectCount(
                    new QueryWrapper<DashboardChart>()
                        .eq("dashboard_id", dashboard.getId())
                        .eq("deleted", 0)
                );
                vo.setChartCount(chartCount);

                return vo;
            }).collect(Collectors.toList());

            return Result.success(vos);
        } catch (Exception e) {
            log.error("获取项目仪表盘列表异常：", e);
            throw new RuntimeException("获取项目仪表盘列表失败", e);
        }
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Result<Boolean> setDefaultDashboard(Long id, Long tenantId) {
        try {
            log.info("设置默认仪表盘，ID：{}，租户ID：{}", id, tenantId);

            Dashboard dashboard = dashboardRepository.selectById(id);
            if (dashboard == null || !dashboard.getTenantId().equals(tenantId)) {
                return Result.error("仪表盘不存在或无权操作");
            }

            if (Boolean.TRUE.equals(dashboard.getIsDefault())) {
                return Result.success(true);
            }

            // 取消当前项目的其他默认设置
            Dashboard defaultDashboard = dashboardRepository.selectOne(
                new QueryWrapper<Dashboard>()
                    .eq("tenant_id", tenantId)
                    .eq("project_id", dashboard.getProjectId())
                    .eq("is_default", 1)
                    .eq("deleted", 0)
            );

            if (defaultDashboard != null) {
                defaultDashboard.setIsDefault(false);
                dashboardRepository.updateById(defaultDashboard);
                log.info("取消原有的默认仪表盘：{}", defaultDashboard.getId());
            }

            // 设置新的默认
            dashboard.setIsDefault(true);
            dashboard.setUpdateTime(LocalDateTime.now());
            int result = dashboardRepository.updateById(dashboard);

            if (result > 0) {
                log.info("设置默认仪表盘成功，ID：{}", id);
                return Result.success(true);
            } else {
                return Result.error("设置失败");
            }
        } catch (Exception e) {
            log.error("设置默认仪表盘异常：", e);
            throw new RuntimeException("设置默认仪表盘失败", e);
        }
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Result<Dashboard> copyDashboard(Long sourceId, String newName, Long creatorId) {
        try {
            log.info("复制仪表盘，源ID：{}，新名称：{}", sourceId, newName);

            Dashboard source = dashboardRepository.selectById(sourceId);
            if (source == null || source.getDeleted() == 1) {
                return Result.error("源仪表盘不存在");
            }

            // 创建副本
            Dashboard copy = new Dashboard();
            copy.setName(newName);
            copy.setDescription("复制自：" + source.getName());
            copy.setProjectId(source.getProjectId());
            copy.setTenantId(source.getTenantId());
            copy.setCreatorId(creatorId);
            copy.setLayoutConfig(source.getLayoutConfig());
            copy.setChartsConfig(source.getChartsConfig());
            copy.setIsShared(false);
            copy.setIsDefault(false);

            // 保存副本
            int result = dashboardRepository.insert(copy);
            if (result <= 0) {
                return Result.error("复制失败");
            }

            // 复制图表
            List<DashboardChart> sourceCharts = chartRepository.findByDashboardId(sourceId);
            if (!sourceCharts.isEmpty()) {
                List<DashboardChart> copiedCharts = sourceCharts.stream().map(sourceChart -> {
                    DashboardChart copyChart = new DashboardChart();
                    copyChart.setDashboardId(copy.getId());
                    copyChart.setChartName(sourceChart.getChartName());
                    copyChart.setChartType(sourceChart.getChartType());
                    copyChart.setChartConfig(sourceChart.getChartConfig());
                    copyChart.setPositionX(sourceChart.getPositionX());
                    copyChart.setPositionY(sourceChart.getPositionY());
                    copyChart.setWidth(sourceChart.getWidth());
                    copyChart.setHeight(sourceChart.getHeight());
                    copyChart.setRefreshInterval(sourceChart.getRefreshInterval());
                    copyChart.setDataSourceType(sourceChart.getDataSourceType());
                    copyChart.setDataSourceConfig(sourceChart.getDataSourceConfig());
                    copyChart.setSortOrder(sourceChart.getSortOrder());
                    return copyChart;
                }).collect(Collectors.toList());

                chartRepository.batchInsert(copiedCharts);
            }

            log.info("仪表盘复制成功，新ID：{}", copy.getId());
            return Result.success(copy);
        } catch (Exception e) {
            log.error("复制仪表盘异常：", e);
            throw new RuntimeException("复制仪表盘失败", e);
        }
    }

    @Override
    public Result<List<DashboardVO>> getSharedDashboards(Long tenantId) {
        try {
