    @Override
    @Transactional(rollbackFor = Exception.class)
    public Result<DashboardChart> addChart(DashboardChart chart) {
        try {
            log.info("添加图表到仪表盘，仪表盘ID：{}，图表名称：{}", chart.getDashboardId(), chart.getChartName());

            // 验证仪表盘存在
            // TODO: 添加仪表盘存在性验证

            chart.setCreateTime(LocalDateTime.now());
            int result = chartRepository.insert(chart);

            if (result > 0) {
                log.info("图表添加成功，ID：{}", chart.getId());

                // 如果是定时刷新的图表，初始化缓存
                if (chart.getRefreshInterval() > 0) {
                    refreshChartData(chart);
                }

                return Result.success(chart);
            } else {
                return Result.error("添加失败");
            }
        } catch (Exception e) {
            log.error("添加图表异常：", e);
            throw new RuntimeException("添加图表失败", e);
        }
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Result<DashboardChart> updateChart(DashboardChart chart) {
        try {
            log.info("更新图表，ID：{}", chart.getId());

            DashboardChart existing = chartRepository.selectById(chart.getId());
            if (existing == null || existing.getDeleted() == 1) {
                return Result.error("图表不存在");
            }

            int result = chartRepository.updateById(chart);

            if (result > 0) {
                log.info("图表更新成功，ID：{}", chart.getId());

                // 清除旧缓存
                cacheRepository.deleteByChartId(chart.getId());

                // 如果需要，重新生成缓存
                if (chart.getRefreshInterval() > 0) {
                    refreshChartData(chart);
                }

                return Result.success(chart);
            } else {
                return Result.error("更新失败");
            }
        } catch (Exception e) {
            log.error("更新图表异常：", e);
            throw new RuntimeException("更新图表失败", e);
        }
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Result<Boolean> deleteChart(Long id) {
        try {
            log.info("删除图表，ID：{}", id);

            DashboardChart chart = chartRepository.selectById(id);
            if (chart == null) {
                return Result.success(true);
            }

            chart.setDeleted(1);
            int result = chartRepository.updateById(chart);

            if (result > 0) {
                // 删除缓存
                cacheRepository.deleteByChartId(id);
                log.info("图表删除成功，ID：{}", id);
                return Result.success(true);
            } else {
                return Result.error("删除失败");
            }
        } catch (Exception e) {
            log.error("删除图表异常：", e);
            throw new RuntimeException("删除图表失败", e);
        }
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Result<Boolean> saveChartsLayout(List<DashboardChart> charts) {
        try {
            log.info("保存图表布局，图表数量：{}", charts.size());

            for (DashboardChart chart : charts) {
                DashboardChart existing = chartRepository.selectById(chart.getId());
                if (existing != null) {
                    existing.setPositionX(chart.getPositionX());
                    existing.setPositionY(chart.getPositionY());
                    existing.setWidth(chart.getWidth());
                    existing.setHeight(chart.getHeight());
                    existing.setSortOrder(chart.getSortOrder());

                    chartRepository.updateById(existing);
                }
            }

            log.info("图表布局保存成功");
            return Result.success(true);
        } catch (Exception e) {
            log.error("保存图表布局异常：", e);
            throw new RuntimeException("保存图表布局失败", e);
        }
    }

    @Override
    public Result<Map<String, Object>> getChartData(Long chartId, Map<String, Object> params) {
        try {
            log.debug("获取图表数据，图表ID：{}", chartId);

            DashboardChart chart = chartRepository.selectById(chartId);
            if (chart == null || chart.getDeleted() == 1) {
                return Result.error("图表不存在");
            }

            // 检查缓存
            String cacheKey = generateCacheKey(chartId, params);
            LocalDateTime now = LocalDateTime.now();

            ChartDataCache cache = cacheRepository.findByCacheKey(cacheKey, now);
            if (cache != null) {
                log.debug("使用缓存数据，缓存ID：{}", cache.getId());
                // TODO: 解析缓存数据
                return Result.success(parseCacheData(cache.getCachedData()));
            }

            // 查询数据
            Map<String, Object> chartData;
            switch (chart.getDataSourceType()) {
                case "sql":
                    chartData = queryDataBySql(chart, params);
                    break;
                case "api":
                    chartData = queryDataByApi(chart, params);
                    break;
                case "static":
                    chartData = queryStaticData(chart);
                    break;
                default:
                    return Result.error("不支持的数据源类型：" + chart.getDataSourceType());
            }

            // 缓存数据（如果需要）
            if (chart.getRefreshInterval() > 0) {
                cacheChartData(chartId, cacheKey, chartData, chart.getRefreshInterval());
            }

            return Result.success(chartData);
        } catch (Exception e) {
            log.error("获取图表数据异常：", e);
            return Result.error("获取图表数据失败：" + e.getMessage());
        }
    }

    @Override
    public Result<Boolean> refreshChartCache(Long chartId) {
        try {
            log.info("刷新图表缓存，图表ID：{}", chartId);

            DashboardChart chart = chartRepository.selectById(chartId);
            if (chart == null || chart.getDeleted() == 1) {
                return Result.error("图表不存在");
            }

            // 清除旧缓存
            cacheRepository.deleteByChartId(chartId);

            // 重新查询并缓存数据
            if (chart.getRefreshInterval() > 0) {
                Map<String, Object> params = new HashMap<>();
                Map<String, Object> chartData = getChartData(chartId, params).getData();

                if (chartData != null) {
                    log.info("图表缓存刷新成功，图表ID：{}", chartId);
                    return Result.success(true);
                }
            }

            return Result.success(true);
        } catch (Exception e) {
            log.error("刷新图表缓存异常：", e);
            return Result.error("刷新缓存失败：" + e.getMessage());
        }
    }

    /**
     * 刷新图表数据
     */
    private void refreshChartData(DashboardChart chart) {
        try {
            log.debug("刷新图表数据，图表ID：{}", chart.getId());

            // 异步执行数据刷新
            CompletableFuture.runAsync(() -> {
                try {
                    Map<String, Object> params = new HashMap<>();
                    getChartData(chart.getId(), params);
                    log.debug("图表数据刷新完成，图表ID：{}", chart.getId());
                } catch (Exception e) {
                    log.error("刷新图表数据异常，图表ID：{}", chart.getId(), e);
                }
            });
        } catch (Exception e) {
            log.error("启动图表数据刷新任务异常：", e);
        }
    }

    /**
     * 生成缓存键
     */
    private String generateCacheKey(Long chartId, Map<String, Object> params) {
        try {
            String paramString = new ObjectMapper().writeValueAsString(params);
            String rawKey = chartId + ":" + paramString;
            return DigestUtils.md5DigestAsHex(rawKey.getBytes());
        } catch (Exception e) {
            log.error("生成缓存键异常：", e);
            return String.valueOf(chartId);
        }
    }

    /**
     * 缓存图表数据
     */
    private void cacheChartData(Long chartId, String cacheKey, Map<String, Object> data, int refreshInterval) {
        try {
            String cachedData = new ObjectMapper().writeValueAsString(data);
            LocalDateTime expireTime = LocalDateTime.now().plusSeconds(refreshInterval);

            ChartDataCache cache = new ChartDataCache();
            cache.setChartId(chartId);
            cache.setCacheKey(cacheKey);
            cache.setCachedData(cachedData);
            cache.setExpireTime(expireTime);
            cache.setCreateTime(LocalDateTime.now());

            cacheRepository.insert(cache);
            log.debug("图表数据缓存成功，图表ID：{}，缓存键：{}", chartId, cacheKey);
        } catch (Exception e) {
            log.error("缓存图表数据异常：", e);
        }
    }

    /**
     * 通过SQL查询数据
     */
    private Map<String, Object> queryDataBySql(DashboardChart chart, Map<String, Object> params) {
        try {
            // 解析数据源配置
            Map<String, Object> dsConfig = parseJsonConfig(chart.getDataSourceConfig());
            String sqlTemplate = (String) dsConfig.get("sql");

            // 替换参数
            String sql = replaceSqlParams(sqlTemplate, params);

            // 执行查询
            return dataQueryService.executeQuery(sql);
        } catch (Exception e) {
            log.error("SQL查询数据异常：", e);
            throw new RuntimeException("SQL查询失败", e);
        }
    }

    /**
     * 通过API查询数据
     */
    private Map<String, Object> queryDataByApi(DashboardChart chart, Map<String, Object> params) {
        try {
            // 解析API配置
            Map<String, Object> dsConfig = parseJsonConfig(chart.getDataSourceConfig());
            String apiUrl = (String) dsConfig.get("url");
            String method = (String) dsConfig.getOrDefault("method", "GET");

            // 调用API
            return callExternalApi(apiUrl, method, params);
        } catch (Exception e) {
            log.error("API查询数据异常：", e);
            throw new RuntimeException("API调用失败", e);
        }
    }

    /**
     * 查询静态数据
     */
    private Map<String, Object> queryStaticData(DashboardChart chart) {
        try {
            return parseJsonConfig(chart.getDataSourceConfig());
        } catch (Exception e) {
            log.error("解析静态数据异常：", e);
            throw new RuntimeException("静态数据解析失败", e);
        }
    }

    /**
     * 解析JSON配置
     */
    private Map<String, Object> parseJsonConfig(String jsonConfig) {
        try {
            return new ObjectMapper().readValue(jsonConfig, Map.class);
        } catch (Exception e) {
            log.error("解析JSON配置异常：", e);
            return new HashMap<>();
        }
    }

    /**
     * 解析缓存数据
     */
    private Map<String, Object> parseCacheData(String cachedData) {
        return parseJsonConfig(cachedData);
    }

    /**
     * 替换SQL参数
     */
    private String replaceSqlParams(String sqlTemplate, Map<String, Object> params) {
        String result = sqlTemplate;
        for (Map.Entry<String, Object> entry : params.entrySet()) {
            String placeholder = "${" + entry.getKey() + "}";
            String value = entry.getValue() != null ? entry.getValue().toString() : "";
            result = result.replace(placeholder, value);
        }
        return result;
    }

    /**
     * 调用外部API
     */
    private Map<String, Object> callExternalApi(String url, String method, Map<String, Object> params) {
        // TODO: 实现API调用逻辑
        return new HashMap<>();
    }
