/**
 * 数据查询服务（辅助类）
 */
@Service
@Slf4j
public class DataQueryService {

    @Autowired
    private JdbcTemplate jdbcTemplate;

    /**
     * 执行SQL查询
     */
    public Map<String, Object> executeQuery(String sql) {
        try {
            log.debug("执行SQL查询：{}", sql);

            // 限制查询时间，防止长时间运行
            List<Map<String, Object>> result = jdbcTemplate.queryForList(sql);

            Map<String, Object> response = new HashMap<>();
            response.put("success", true);
            response.put("data", result);
            response.put("count", result.size());
            response.put("timestamp", System.currentTimeMillis());

            return response;
        } catch (Exception e) {
            log.error("执行SQL查询异常：", e);

            Map<String, Object> errorResponse = new HashMap<>();
            errorResponse.put("success", false);
            errorResponse.put("error", e.getMessage());
            errorResponse.put("timestamp", System.currentTimeMillis());

            return errorResponse;
        }
    }

    /**
     * 执行安全的SQL查询（带参数）
     */
    public Map<String, Object> executeSafeQuery(String sql, Object... params) {
        try {
            log.debug("执行安全SQL查询：{}，参数：{}", sql, Arrays.toString(params));

            List<Map<String, Object>> result = jdbcTemplate.queryForList(sql, params);

            Map<String, Object> response = new HashMap<>();
            response.put("success", true);
            response.put("data", result);
            response.put("count", result.size());
            response.put("timestamp", System.currentTimeMillis());

            return response;
        } catch (Exception e) {
            log.error("执行安全SQL查询异常：", e);

            Map<String, Object> errorResponse = new HashMap<>();
            errorResponse.put("success", false);
            errorResponse.put("error", e.getMessage());
            errorResponse.put("timestamp", System.currentTimeMillis());

            return errorResponse;
        }
    }

    /**
     * 验证SQL安全性
     */
    public boolean validateSqlSecurity(String sql) {
        // 简单的SQL注入检测
        String upperSql = sql.toUpperCase();
        String[] dangerousKeywords = {"DROP", "DELETE", "TRUNCATE", "UPDATE", "INSERT", 
                                     "ALTER", "CREATE", "EXEC", "EXECUTE", "SHUTDOWN"};

        for (String keyword : dangerousKeywords) {
            if (upperSql.contains(keyword) && !upperSql.contains("WHERE " + keyword)) {
                log.warn("检测到潜在危险SQL关键字：{}", keyword);
                return false;
            }
        }

        return true;
    }
}
