        // 当前分页状态
        let currentPage = 1;
        const itemsPerPage = 5;
        let filteredMembers = [...membersData];

        // 初始化目录树
        function initDirectoryTree() {
            const treeContainer = document.getElementById('directoryTree');
            treeContainer.innerHTML = '';

            directoryData.forEach(item => {
                treeContainer.appendChild(createTreeNode(item));
            });

            // 默认展开项目成员管理节点
            const projectMemberNode = document.querySelector('[data-id="2.2"]');
            if (projectMemberNode) {
                projectMemberNode.classList.add('active');
                const parentNode = projectMemberNode.closest('.tree-node');
                if (parentNode) {
                    const parentChildren = parentNode.querySelector('.tree-node-children');
                    if (parentChildren) {
                        parentChildren.classList.add('show');
                        const parentIcon = parentNode.querySelector('.tree-node-icon');
                        if (parentIcon) {
                            parentIcon.classList.add('rotated');
                        }
                    }
                }

                // 展开父节点
                const grandParentNode = document.querySelector('[data-id="2"]');
                if (grandParentNode) {
                    const grandParentChildren = grandParentNode.querySelector('.tree-node-children');
                    if (grandParentChildren) {
                        grandParentChildren.classList.add('show');
                        const grandParentIcon = grandParentNode.querySelector('.tree-node-icon');
                        if (grandParentIcon) {
                            grandParentIcon.classList.add('rotated');
                        }
                    }
                }
            }
        }

        // 创建目录树节点
        function createTreeNode(node) {
            const treeNode = document.createElement('div');
            treeNode.className = 'tree-node';

            const nodeTitle = document.createElement('div');
            nodeTitle.className = `tree-node-title level-${node.level}`;
            nodeTitle.setAttribute('data-id', node.id);
            nodeTitle.innerHTML = `
                ${node.children.length > 0 ? `<i class="fas fa-chevron-right tree-node-icon"></i>` : '<i class="fas fa-circle" style="font-size: 6px; margin-right: 12px; margin-left: 4px;"></i>'}
                <span>${node.title}</span>
            `;

            treeNode.appendChild(nodeTitle);

            // 点击节点标题事件
            nodeTitle.addEventListener('click', function(e) {
                e.stopPropagation();

                // 移除所有active状态
                document.querySelectorAll('.tree-node-title').forEach(el => {
                    el.classList.remove('active');
                });

                // 添加当前active状态
                this.classList.add('active');

                // 更新页面标题
                const titleText = this.querySelector('span').textContent;
                document.getElementById('pageTitle').textContent = titleText.split('. ')[1] || titleText;

                // 更新面包屑导航
                const breadcrumb = this.closest('.tree-node') ? getBreadcrumb(this) : titleText;
                document.querySelector('.content-subtitle').textContent = breadcrumb;

                // 如果有子节点，切换展开/收起
                if (node.children.length > 0) {
                    const icon = this.querySelector('.tree-node-icon');
                    const childrenContainer = this.parentNode.querySelector('.tree-node-children');

                    if (childrenContainer) {
                        childrenContainer.classList.toggle('show');
                        icon.classList.toggle('rotated');
                    }
                }
            });

            // 如果有子节点
            if (node.children.length > 0) {
                const childrenContainer = document.createElement('div');
                childrenContainer.className = 'tree-node-children';

                node.children.forEach(child => {
                    childrenContainer.appendChild(createTreeNode(child));
                });

                treeNode.appendChild(childrenContainer);
            }

            return treeNode;
        }

        // 获取面包屑导航路径
        function getBreadcrumb(node) {
            let path = [];
            let currentNode = node;

            while (currentNode) {
                const text = currentNode.querySelector('span').textContent;
                path.unshift(text.split('. ')[1] || text);
                currentNode = currentNode.closest('.tree-node-children')?.previousElementSibling;
            }

            return path.join(' > ');
        }

        // 初始化成员表格
        function initMembersTable() {
            renderMembersTable();
