            pageMembers.forEach(member => {
                const row = document.createElement('tr');
                row.innerHTML = `
                    <td>${member.id}</td>
                    <td>${member.name}</td>
                    <td>${member.role}</td>
                    <td>${member.dept}</td>
                    <td>${member.joinDate}</td>
                    <td><span class="status ${member.status}">${member.status === 'active' ? '活跃' : '已退出'}</span></td>
                    <td>
                        <div class="action-buttons">
                            <button class="btn btn-secondary btn-sm edit-btn" data-id="${member.id}">
                                <i class="fas fa-edit"></i> 编辑
                            </button>
                            <button class="btn btn-danger btn-sm delete-btn" data-id="${member.id}">
                                <i class="fas fa-trash-alt"></i> 移除
                            </button>
                        </div>
                    </td>
                `;
                tableBody.appendChild(row);
            });

            // 绑定编辑和删除按钮事件
            document.querySelectorAll('.edit-btn').forEach(btn => {
                btn.addEventListener('click', function() {
                    const memberId = parseInt(this.getAttribute('data-id'));
                    openEditModal(memberId);
                });
            });

            document.querySelectorAll('.delete-btn').forEach(btn => {
                btn.addEventListener('click', function() {
                    const memberId = parseInt(this.getAttribute('data-id'));
                    deleteMember(memberId);
                });
            });
        }

        // 渲染分页
        function renderPagination() {
            const pagination = document.getElementById('pagination');
            pagination.innerHTML = '';

            const totalPages = Math.ceil(filteredMembers.length / itemsPerPage);

            if (totalPages <= 1) return;

            // 上一页按钮
            const prevButton = document.createElement('button');
            prevButton.innerHTML = '<i class="fas fa-chevron-left"></i>';
            prevButton.disabled = currentPage === 1;
            prevButton.addEventListener('click', () => {
                if (currentPage > 1) {
                    currentPage--;
                    renderMembersTable();
                    renderPagination();
                }
            });
            pagination.appendChild(prevButton);

            // 页码按钮
            const maxVisiblePages = 5;
            let startPage = Math.max(1, currentPage - Math.floor(maxVisiblePages / 2));
            let endPage = Math.min(totalPages, startPage + maxVisiblePages - 1);

            if (endPage - startPage + 1 < maxVisiblePages) {
                startPage = Math.max(1, endPage - maxVisiblePages + 1);
            }

            for (let i = startPage; i <= endPage; i++) {
                const pageButton = document.createElement('button');
                pageButton.textContent = i;
                if (i === currentPage) {
                    pageButton.classList.add('active');
                }
                pageButton.addEventListener('click', () => {
                    currentPage = i;
                    renderMembersTable();
                    renderPagination();
                });
                pagination.appendChild(pageButton);
            }

            // 下一页按钮
            const nextButton = document.createElement('button');
            nextButton.innerHTML = '<i class="fas fa-chevron-right"></i>';
            nextButton.disabled = currentPage === totalPages;
            nextButton.addEventListener('click', () => {
                if (currentPage < totalPages) {
                    currentPage++;
                    renderMembersTable();
                    renderPagination();
                }
            });
            pagination.appendChild(nextButton);

            // 添加总页数信息
            const pageInfo = document.createElement('span');
            pageInfo.style.marginLeft = '15px';
            pageInfo.style.color = '#666';
            pageInfo.textContent = `共 ${filteredMembers.length} 条记录，${totalPages} 页`;
            pagination.appendChild(pageInfo);
        }

