        // 添加新成员
        function addMember() {
            const name = document.getElementById('memberName').value.trim();
            const role = document.getElementById('memberRole').value;
            const dept = document.getElementById('memberDept').value.trim();
            const email = document.getElementById('memberEmail').value.trim();

            if (!name || !role || !dept || !email) {
                alert('请填写所有必填字段');
                return;
            }

            // 生成新ID
            const newId = Math.max(...membersData.map(m => m.id)) + 1;
            const joinDate = new Date().toISOString().split('T')[0];

            const newMember = {
                id: newId,
                name: name,
                role: role,
                dept: dept,
                joinDate: joinDate,
                status: 'active'
            };

            membersData.unshift(newMember);
            filteredMembers = [...membersData];

            // 重置分页到第一页
            currentPage = 1;

            // 更新表格和分页
            renderMembersTable();
            renderPagination();

            // 关闭弹窗
            closeAddModal();

            // 显示成功消息
            alert(`成员 "${name}" 已成功添加！`);
        }

        // 更新成员信息
        function updateMember() {
            const memberId = parseInt(document.getElementById('submitEditMemberBtn').getAttribute('data-id'));
            const memberIndex = membersData.findIndex(m => m.id === memberId);

            if (memberIndex === -1) return;

            const name = document.getElementById('editMemberName').value.trim();
            const role = document.getElementById('editMemberRole').value;
            const dept = document.getElementById('editMemberDept').value.trim();
            const status = document.getElementById('editMemberStatus').value;

            if (!name || !role || !dept) {
                alert('请填写所有必填字段');
                return;
            }

            membersData[memberIndex] = {
                ...membersData[memberIndex],
                name: name,
                role: role,
                dept: dept,
                status: status
            };

            filteredMembers = [...membersData];

            // 更新表格
            renderMembersTable();

            // 关闭弹窗
            closeEditModal();

            // 显示成功消息
            alert(`成员 "${name}" 的信息已更新！`);
        }

        // 删除成员
        function deleteMember(memberId) {
            if (!confirm('确定要移除此成员吗？此操作不可撤销。')) {
                return;
            }

            const memberIndex = membersData.findIndex(m => m.id === memberId);
            if (memberIndex === -1) return;

            const memberName = membersData[memberIndex].name;

            // 从数据中移除
            membersData.splice(memberIndex, 1);
            filteredMembers = [...membersData];

            // 调整当前页码
            const totalPages = Math.ceil(filteredMembers.length / itemsPerPage);
            if (currentPage > totalPages && totalPages > 0) {
                currentPage = totalPages;
            } else if (totalPages === 0) {
                currentPage = 1;
            }

            // 更新表格和分页
            renderMembersTable();
            renderPagination();

            // 显示成功消息
            alert(`成员 "${memberName}" 已从项目中移除！`);
        }

        // 搜索成员
        function searchMembers() {
            const searchTerm = document.getElementById('searchInput').value.trim().toLowerCase();

            if (searchTerm === '') {
                filteredMembers = [...membersData];
            } else {
                filteredMembers = membersData.filter(member => 
                    member.name.toLowerCase().includes(searchTerm) || 
                    member.role.toLowerCase().includes(searchTerm) ||
                    member.dept.toLowerCase().includes(searchTerm)
                );
            }

            currentPage = 1;
            renderMembersTable();
            renderPagination();
        }

        // 初始化
        document.addEventListener('DOMContentLoaded', function() {
            // 初始化目录树
            initDirectoryTree();

            // 初始化成员表格
            initMembersTable();

            // 绑定事件
            document.getElementById('addMemberBtn').addEventListener('click', openAddModal);
            document.getElementById('closeModalBtn').addEventListener('click', closeAddModal);
            document.getElementById('cancelModalBtn').addEventListener('click', closeAddModal);
            document.getElementById('submitMemberBtn').addEventListener('click', addMember);

            document.getElementById('closeEditModalBtn').addEventListener('click', closeEditModal);
            document.getElementById('cancelEditModalBtn').addEventListener('click', closeEditModal);
            document.getElementById('submitEditMemberBtn').addEventListener('click', updateMember);

            document.getElementById('searchInput').addEventListener('input', searchMembers);

            // 移动端菜单切换
            document.getElementById('mobileToggle').addEventListener('click', function() {
                document.getElementById('sidebar').classList.toggle('active');
            });

            // 点击弹窗外部关闭弹窗
            document.querySelectorAll('.modal-overlay').forEach(modal => {
                modal.addEventListener('click', function(e) {
                    if (e.target === this) {
                        if (this.id === 'addMemberModal') {
                            closeAddModal();
                        } else if (this.id === 'editMemberModal') {
                            closeEditModal();
                        }
                    }
                });
            });

            // 按ESC键关闭弹窗
            document.addEventListener('keydown', function(e) {
                if (e.key === 'Escape') {
                    closeAddModal();
                    closeEditModal();
                }
            });

            // 表单提交处理
            document.getElementById('addMemberForm').addEventListener('submit', function(e) {
                e.preventDefault();
                addMember();
            });

            document.getElementById('editMemberForm').addEventListener('submit', function(e) {
                e.preventDefault();
                updateMember();
            });
        });
    </script>
</body>
</html>
