        // 计算分类总数（包括所有层级）
        function calculateTotalCategories(categories) {
            let count = 0;

            function countCategories(catList) {
                catList.forEach(cat => {
                    count++;
                    if (cat.children && cat.children.length > 0) {
                        countCategories(cat.children);
                    }
                });
            }

            countCategories(categories);
            return count;
        }

        // 计算用例总数
        function calculateTotalTestCases(categories) {
            let total = 0;

            function sumTestCases(catList) {
                catList.forEach(cat => {
                    total += cat.testCaseCount || 0;
                    if (cat.children && cat.children.length > 0) {
                        sumTestCases(cat.children);
                    }
                });
            }

            sumTestCases(categories);
            return total;
        }

