                                <div class="category-action delete-action" onclick="deleteCategory(${category.id})" title="删除分类">
                                    <i class="fas fa-trash"></i>
                                </div>
                            </div>
                        </div>
                    `;

                    categoryTree.appendChild(li);

                    // 如果分类有子分类且展开，递归渲染
                    if (category.children && category.children.length > 0 && category.expanded) {
                        renderCategories(category.children, level + 1);
                    }
                });
            }

            // 只渲染根分类
            const rootCategories = categoriesData.filter(cat => cat.parentId === 0);
            renderCategories(rootCategories);

            // 添加点击事件
            document.querySelectorAll('.category-item').forEach(item => {
                item.addEventListener('click', (e) => {
                    // 如果点击的是操作按钮，不触发选择
                    if (e.target.closest('.category-action')) {
                        return;
                    }

                    // 切换选中状态
                    document.querySelectorAll('.category-item').forEach(el => {
                        el.classList.remove('active');
                    });
                    item.classList.add('active');

                    // 如果点击的分类有子分类，切换展开状态
                    const categoryId = parseInt(item.dataset.id);
                    toggleCategoryExpand(categoryId);
                });
            });
        }

