        // 搜索分类
        function searchCategories() {
            const searchTerm = document.getElementById('categorySearch').value.toLowerCase();

            if (!searchTerm) {
                renderCategoryTree();
                return;
            }

            // 递归搜索分类
            function searchInCategories(categories, term, results = []) {
                categories.forEach(category => {
                    if (category.name.toLowerCase().includes(term) || 
                        category.code.toLowerCase().includes(term) ||
                        category.description.toLowerCase().includes(term)) {
                        results.push(category);
                    }

                    if (category.children && category.children.length > 0) {
                        searchInCategories(category.children, term, results);
                    }
                });

                return results;
            }

            const searchResults = searchInCategories(categoriesData, searchTerm);

            // 临时显示搜索结果
            if (searchResults.length === 0) {
                categoryTree.innerHTML = '<div style="text-align: center; padding: 30px; color: #666;">未找到匹配的分类</div>';
                categoryEmptyState.style.display = 'none';
            } else {
                // 显示搜索结果（扁平化）
                categoryTree.innerHTML = '';
                searchResults.forEach(category => {
                    const li = document.createElement('li');
                    li.innerHTML = `
                        <div class="category-item" data-id="${category.id}">
                            <div class="category-info">
                                <i class="fas fa-folder category-icon"></i>
