        // 打开添加分类模态框
        function openAddCategoryModal() {
            isEditingCategory = false;
            editingCategoryId = null;
            categoryModalTitle.textContent = '添加分类';
            categoryForm.reset();

            // 填充父级分类选项
            parentCategorySelect.innerHTML = '<option value="0">无（根分类）</option>';

            // 递归添加所有分类选项
            function addCategoryOptions(categories, level = 1) {
                categories.forEach(category => {
                    const prefix = '─ '.repeat(level - 1);
                    const option = document.createElement('option');
                    option.value = category.id;
                    option.textContent = `${prefix}${category.name} (${category.code})`;
                    parentCategorySelect.appendChild(option);

                    if (category.children && category.children.length > 0) {
                        addCategoryOptions(category.children, level + 1);
                    }
                });
            }

            addCategoryOptions(categoriesData.filter(cat => cat.parentId === 0));

            categoryModal.classList.add('active');
        }

