        // 计算分类总数（递归计算所有分类）
        function countAllCategories(categories) {
            let count = 0;

            function countRecursive(cats) {
                cats.forEach(cat => {
                    count++;
                    if (cat.children && cat.children.length > 0) {
                        countRecursive(cat.children);
                    }
                });
            }

            countRecursive(categories);
            return count;
        }

        // 渲染分类树
        function renderCategoryTree() {
            const totalCategories = countAllCategories(categoriesData);
            totalCategoriesElement.textContent = totalCategories;

            if (categoriesData.length === 0) {
                categoryEmptyState.style.display = 'flex';
                categoryTree.innerHTML = '';
                return;
            }

            categoryEmptyState.style.display = 'none';
            categoryTree.innerHTML = '';

            // 渲染分类树
            function renderNode(category, level = 0) {
                const li = document.createElement('li');
                li.className = 'category-node';
                li.dataset.id = category.id;
                li.dataset.level = level;

                // 创建分类头部
                const header = document.createElement('div');
                header.className = 'category-header';

                // 如果有子分类，添加展开/折叠按钮
                let toggleIcon = '';
                if (category.children && category.children.length > 0) {
                    toggleIcon = `
                        <span class="category-toggle ${category.expanded ? '' : 'collapsed'}">
                            <i class="fas fa-chevron-down"></i>
                        </span>
                    `;
                } else {
                    toggleIcon = '<span style="width: 16px;"></span>';
                }

                header.innerHTML = `
                    ${toggleIcon}
                    <span class="category-icon">
                        <i class="fas fa-folder${category.expanded ? '-open' : ''}"></i>
                    </span>
                    <span class="category-name">${category.name}</span>
                    <span class="category-count">${category.caseCount}</span>
                    <div class="category-actions">
                        <button class="category-action-btn" onclick="addSubCategory(${category.id})" title="添加子分类">
                            <i class="fas fa-plus"></i>
                        </button>
                        <button class="category-action-btn" onclick="editCategory(${category.id})" title="编辑分类">
                            <i class="fas fa-edit"></i>
                        </button>
                        <button class="category-action-btn" onclick="deleteCategory(${category.id})" title="删除分类">
                            <i class="fas fa-trash"></i>
                        </button>
                    </div>
                `;

                li.appendChild(header);

                // 创建子分类容器
                if (category.children && category.children.length > 0) {
                    const childrenContainer = document.createElement('ul');
                    childrenContainer.className = `category-children ${category.expanded ? 'expanded' : ''}`;

                    // 递归渲染子分类
                    category.children.forEach(child => {
                        childrenContainer.appendChild(renderNode(child, level + 1));
                    });

                    li.appendChild(childrenContainer);

                    // 添加展开/折叠事件
                    const toggle = header.querySelector('.category-toggle');
                    if (toggle) {
                        toggle.addEventListener('click', (e) => {
                            e.stopPropagation();
                            category.expanded = !category.expanded;
                            renderCategoryTree();
                        });
                    }
                }

                // 添加点击选中事件
                header.addEventListener('click', (e) => {
                    if (!e.target.closest('.category-actions') && !e.target.closest('.category-toggle')) {
                        // 移除所有选中状态
                        document.querySelectorAll('.category-header').forEach(item => {
                            item.classList.remove('active');
                        });

                        // 添加当前选中状态
                        header.classList.add('active');

                        // 这里可以添加显示分类详情的逻辑
                        showCategoryDetails(category);
                    }
                });

                return li;
            }

            // 渲染根分类
            categoriesData.forEach(category => {
                categoryTree.appendChild(renderNode(category));
            });
        }

        // 显示分类详情
        function showCategoryDetails(category) {
            // 这里可以实现在侧边或弹窗显示分类详情的逻辑
            console.log(`选中分类: ${category.name} (ID: ${category.id})`);
