        // 打开添加分类模态框
        function openAddCategoryModal(parentId = 0) {
            isEditingCategory = false;
            editingCategoryId = null;
            categoryModalTitle.textContent = parentId === 0 ? '添加分类' : '添加子分类';
            categoryForm.reset();

            // 填充父分类选项
            parentCategorySelect.innerHTML = '<option value="0">根分类（顶级分类）</option>';
            populateCategoryOptions(parentCategorySelect, categoriesData, 0);

            // 如果指定了父分类，默认选中
            if (parentId > 0) {
                parentCategorySelect.value = parentId;
            }

            categoryModal.classList.add('active');
        }

        // 填充分类选项（递归）
        function populateCategoryOptions(selectElement, categories, level) {
            categories.forEach(category => {
                const indent = '&nbsp;&nbsp;'.repeat(level);
                const option = document.createElement('option');
                option.value = category.id;
                option.innerHTML = `${indent}${category.name}`;
                selectElement.appendChild(option);

                // 递归处理子分类
                if (category.children && category.children.length > 0) {
                    populateCategoryOptions(selectElement, category.children, level + 1);
                }
            });
        }

        // 添加子分类
        function addSubCategory(parentId) {
            openAddCategoryModal(parentId);
        }

        // 编辑分类
        function editCategory(categoryId) {
            const category = findCategoryById(categoriesData, categoryId);
            if (!category) return;

            isEditingCategory = true;
            editingCategoryId = categoryId;
            categoryModalTitle.textContent = '编辑分类';

            // 填充表单
            categoryNameInput.value = category.name;
            categoryCodeInput.value = category.code;
            parentCategorySelect.value = category.parentId;
            categoryDescriptionInput.value = category.description || '';

            // 填充父分类选项
            parentCategorySelect.innerHTML = '<option value="0">根分类（顶级分类）</option>';
            populateCategoryOptions(parentCategorySelect, categoriesData, 0);

            // 不能选择自己或自己的子分类作为父分类
            disableInvalidParentOptions(categoryId);

            categoryModal.classList.add('active');
        }

        // 查找分类（递归）
        function findCategoryById(categories, id) {
            for (const category of categories) {
                if (category.id === id) return category;
                if (category.children && category.children.length > 0) {
                    const found = findCategoryById(category.children, id);
                    if (found) return found;
                }
            }
            return null;
        }

        // 禁用无效的父分类选项（不能选择自己或自己的子分类）
        function disableInvalidParentOptions(categoryId) {
            const category = findCategoryById(categoriesData, categoryId);
            if (!category) return;

            // 收集所有无效的ID（自己和所有子分类）
            const invalidIds = new Set();
            invalidIds.add(categoryId);

            function collectChildIds(cat) {
                if (cat.children && cat.children.length > 0) {
                    cat.children.forEach(child => {
                        invalidIds.add(child.id);
                        collectChildIds(child);
                    });
                }
            }

            collectChildIds(category);

            // 禁用无效选项
            Array.from(parentCategorySelect.options).forEach(option => {
                if (invalidIds.has(parseInt(option.value))) {
                    option.disabled = true;
                    option.textContent += ' (不可选)';
                }
            });
        }

        // 删除分类
        function deleteCategory(categoryId) {
            if (confirm('确定要删除此分类吗？删除后其下的所有子分类也将被删除。')) {
                // 递归删除分类
                function deleteRecursive(categories, id) {
                    for (let i = 0; i < categories.length; i++) {
                        if (categories[i].id === id) {
                            // 检查是否有用例
                            if (categories[i].caseCount > 0) {
                                if (!confirm(`该分类下有 ${categories[i].caseCount} 个用例，确定要删除吗？`)) {
                                    return false;
                                }
                            }
                            categories.splice(i, 1);
                            return true;
                        }
                        if (categories[i].children && categories[i].children.length > 0) {
                            if (deleteRecursive(categories[i].children, id)) {
                                return true;
                            }
                        }
                    }
                    return false;
                }

                if (deleteRecursive(categoriesData, categoryId)) {
                    renderCategoryTree();
                    showNotification('分类已删除', 'success');
                }
            }
        }

        // 保存分类
        function saveCategory() {
            const categoryName = categoryNameInput.value.trim();
            const categoryCode = categoryCodeInput.value.trim();
            const parentId = parseInt(parentCategorySelect.value);
            const description = categoryDescriptionInput.value.trim();

            if (!categoryName) {
                alert('请填写分类名称');
                return;
            }

            if (isEditingCategory) {
                // 更新现有分类
                const category = findCategoryById(categoriesData, editingCategoryId);
                if (category) {
                    category.name = categoryName;
                    category.code = categoryCode;
                    category.description = description;

                    // 如果父分类改变了，需要移动分类
                    if (category.parentId !== parentId) {
                        // 从原位置删除
                        function removeFromParent(categories, id) {
                            for (let i = 0; i < categories.length; i++) {
                                if (categories[i].id === id) {
                                    return categories.splice(i, 1)[0];
                                }
                                if (categories[i].children && categories[i].children.length > 0) {
                                    const removed = removeFromParent(categories[i].children, id);
                                    if (removed) return removed;
                                }
                            }
                            return null;
                        }

                        const removedCategory = removeFromParent(categoriesData, editingCategoryId);
                        if (removedCategory) {
                            removedCategory.parentId = parentId;

                            // 添加到新位置
                            if (parentId === 0) {
                                // 添加到根
                                categoriesData.push(removedCategory);
                            } else {
                                // 添加到父分类
                                const parentCategory = findCategoryById(categoriesData, parentId);
                                if (parentCategory) {
                                    if (!parentCategory.children) parentCategory.children = [];
                                    parentCategory.children.push(removedCategory);
                                }
                            }
                        }
                    }
                }
            } else {
                // 创建新分类
                const newCategory = {
                    id: getNextCategoryId(),
                    name: categoryName,
                    code: categoryCode,
                    parentId: parentId,
                    description: description,
                    caseCount: 0,
                    expanded: false,
                    children: []
                };

                if (parentId === 0) {
                    // 添加到根
                    categoriesData.push(newCategory);
                } else {
                    // 添加到父分类
                    const parentCategory = findCategoryById(categoriesData, parentId);
                    if (parentCategory) {
                        if (!parentCategory.children) parentCategory.children = [];
                        parentCategory.children.push(newCategory);
                    }
                }
            }

            renderCategoryTree();
            closeCategoryModal();
            showNotification(isEditingCategory ? '分类已更新' : '分类已添加', 'success');
        }

        // 获取下一个分类ID
        function getNextCategoryId() {
            let maxId = 0;

            function findMaxId(categories) {
                categories.forEach(category => {
                    if (category.id > maxId) maxId = category.id;
                    if (category.children && category.children.length > 0) {
                        findMaxId(category.children);
                    }
                });
            }

            findMaxId(categoriesData);
            return maxId + 1;
        }

        // 关闭分类模态框
        function closeCategoryModal() {
            categoryModal.classList.remove('active');
            categoryForm.reset();
        }

