        // 更新统计信息
        function updateStats() {
            const totalCases = testCasesData.length;

            // 计算已关联的需求、缺陷、任务数量
            let linkedRequirements = 0;
            let linkedDefects = 0;
            let linkedTasks = 0;

            testCasesData.forEach(caseItem => {
                linkedRequirements += caseItem.associations.requirements.length;
                linkedDefects += caseItem.associations.defects.length;
                linkedTasks += caseItem.associations.tasks.length;
            });

            totalCasesElement.textContent = totalCases;
            linkedRequirementsElement.textContent = linkedRequirements;
            linkedDefectsElement.textContent = linkedDefects;
            linkedTasksElement.textContent = linkedTasks;
        }

        // 渲染用例表格
        function renderCasesTable() {
            if (testCasesData.length === 0) {
                emptyState.style.display = 'block';
                casesTableBody.innerHTML = '';
                pagination.innerHTML = '';
                return;
            }

            emptyState.style.display = 'none';

            // 应用筛选
            let filteredData = applyFiltersToData(testCasesData);

            // 计算分页
            const totalPages = Math.ceil(filteredData.length / itemsPerPage);
            const startIndex = (currentPage - 1) * itemsPerPage;
            const endIndex = Math.min(startIndex + itemsPerPage, filteredData.length);
            const pageData = filteredData.slice(startIndex, endIndex);

            // 清空表格
            casesTableBody.innerHTML = '';

            // 填充表格数据
            pageData.forEach(caseItem => {
                // 计算关联状态
                const totalAssociations = 
                    caseItem.associations.requirements.length + 
                    caseItem.associations.defects.length + 
                    caseItem.associations.tasks.length;

                let associationStatus = "未关联";
                let statusColor = "#999";

                if (totalAssociations > 0) {
                    associationStatus = "已关联";
                    statusColor = "#0c7c42";
                }

                if (caseItem.associations.requirements.length === 0) {
                    associationStatus = "部分关联";
                    statusColor = "#d97706";
                }

                const row = document.createElement('tr');
                row.innerHTML = `
                    <td>
                        <div class="case-id">${caseItem.code}</div>
