                                    需求 <span class="tag-count">${caseItem.associations.requirements.length}</span>
                                </div>
                            ` : ''}
                            ${caseItem.associations.defects.length > 0 ? `
                                <div class="association-tag tag-defect">
                                    <i class="fas fa-bug"></i>
                                    缺陷 <span class="tag-count">${caseItem.associations.defects.length}</span>
                                </div>
                            ` : ''}
                            ${caseItem.associations.tasks.length > 0 ? `
                                <div class="association-tag tag-task">
                                    <i class="fas fa-tasks"></i>
                                    任务 <span class="tag-count">${caseItem.associations.tasks.length}</span>
                                </div>
                            ` : ''}
                            ${totalAssociations === 0 ? `
                                <div style="color: #999; font-size: 13px;">暂无关联项</div>
                            ` : ''}
                        </div>
                    </td>
                    <td>
                        <span style="font-weight: 500; color: ${statusColor}">${associationStatus}</span>
