            // 渲染分页
            renderPagination(totalPages);

            // 更新统计信息
            updateStats();
        }

        // 应用筛选到数据
        function applyFiltersToData(data) {
            const caseTypeFilter = document.getElementById('caseTypeFilter').value;
            const associationFilter = document.getElementById('associationFilter').value;
            const priorityFilter = document.getElementById('priorityFilter').value;

            return data.filter(caseItem => {
                // 用例类型筛选
                if (caseTypeFilter && caseItem.type !== caseTypeFilter) {
                    return false;
                }

                // 优先级筛选
                if (priorityFilter && caseItem.priority !== priorityFilter) {
                    return false;
                }

                // 关联状态筛选
                if (associationFilter) {
                    const totalAssociations = 
                        caseItem.associations.requirements.length + 
                        caseItem.associations.defects.length + 
                        caseItem.associations.tasks.length;

                    if (associationFilter === "已关联" && totalAssociations === 0) {
                        return false;
                    }

                    if (associationFilter === "未关联" && totalAssociations > 0) {
                        return false;
                    }

                    if (associationFilter === "部分关联" && 
                        (totalAssociations === 0 || caseItem.associations.requirements.length > 0)) {
                        return false;
                    }
                }

                return true;
            });
        }

        // 应用筛选
        function applyFilters() {
            currentPage = 1;
            renderCasesTable();
        }

        // 重置筛选
        function resetFilters() {
            document.getElementById('caseTypeFilter').value = '';
            document.getElementById('associationFilter').value = '';
            document.getElementById('priorityFilter').value = '';
            currentPage = 1;
            renderCasesTable();
        }

        // 渲染分页
        function renderPagination(totalPages) {
            pagination.innerHTML = '';

            if (totalPages <= 1) return;

            // 上一页按钮
            const prevLi = document.createElement('li');
            prevLi.className = currentPage === 1 ? 'disabled' : '';
            prevLi.innerHTML = `<a href="#" onclick="changePage(${currentPage-1}); return false;"><i class="fas fa-chevron-left"></i></a>`;
            pagination.appendChild(prevLi);

            // 页码按钮
            const maxVisiblePages = 5;
            let startPage = Math.max(1, currentPage - Math.floor(maxVisiblePages / 2));
            let endPage = Math.min(totalPages, startPage + maxVisiblePages - 1);

            if (endPage - startPage + 1 < maxVisiblePages) {
                startPage = Math.max(1, endPage - maxVisiblePages + 1);
            }

            for (let i = startPage; i <= endPage; i++) {
                const pageLi = document.createElement('li');
                pageLi.className = i === currentPage ? 'active' : '';
                pageLi.innerHTML = `<a href="#" onclick="changePage(${i}); return false;">${i}</a>`;
                pagination.appendChild(pageLi);
            }

            // 下一页按钮
            const nextLi = document.createElement('li');
            nextLi.className = currentPage === totalPages ? 'disabled' : '';
            nextLi.innerHTML = `<a href="#" onclick="changePage(${currentPage+1}); return false;"><i class="fas fa-chevron-right"></i></a>`;
            pagination.appendChild(nextLi);
        }

