                    { id: 'TASK-022', name: '权限管理测试', status: '进行中' },
                    { id: 'TASK-025', name: '性能测试', status: '已完成' },
                    { id: 'TASK-028', name: '安全防护测试', status: '进行中' }
                ];
            }

            // 获取当前用例已关联的项
            let currentAssociations = [];
            if (caseItem) {
                if (type === 'requirement') {
                    currentAssociations = caseItem.associations.requirements;
                } else if (type === 'defect') {
                    currentAssociations = caseItem.associations.defects;
