        // 保存关联
        function saveAssociation() {
            const caseItem = testCasesData.find(c => c.id === currentCaseId);
            if (!caseItem) return;

            const type = associationType.value;
            const checkboxes = associationItems.querySelectorAll('input[type="checkbox"]:checked');
            const selectedIds = Array.from(checkboxes).map(cb => cb.value);

            if (type === 'requirement') {
                caseItem.associations.requirements = selectedIds;
            } else if (type === 'defect') {
                caseItem.associations.defects = selectedIds;
            } else if (type === 'task') {
                caseItem.associations.tasks = selectedIds;
            }

            closeAssociationModal();
            renderCasesTable();
            showNotification('关联信息已保存', 'success');
        }

