    <!-- 右侧主内容区 -->
    <div class="main-content">
        <div class="top-bar">
            <button class="mobile-menu-toggle" id="mobileMenuToggle">
                <i class="fas fa-bars"></i>
            </button>
            <div class="page-title" id="pageTitle">自定义仪表盘</div>
            <div class="user-info">
                <div class="user-avatar">刘</div>
                <div>
                    <div style="font-weight: 500;">刘贺</div>
                    <div style="font-size: 13px; color: #666;">项目经理</div>
                </div>
            </div>
        </div>

        <div class="content-area">
            <!-- 统计卡片 -->
            <div class="stats-cards">
                <div class="stat-card">
                    <div class="stat-icon dashboards">
                        <i class="fas fa-tachometer-alt"></i>
                    </div>
                    <div class="stat-details">
                        <h3 id="totalDashboards">8</h3>
                        <p>仪表盘总数</p>
                    </div>
                </div>
                <div class="stat-card">
                    <div class="stat-icon charts">
                        <i class="fas fa-chart-bar"></i>
                    </div>
                    <div class="stat-details">
                        <h3 id="totalCharts">42</h3>
                        <p>图表总数</p>
                    </div>
                </div>
                <div class="stat-card">
                    <div class="stat-icon shared">
                        <i class="fas fa-share-alt"></i>
                    </div>
                    <div class="stat-details">
                        <h3>5</h3>
                        <p>已共享仪表盘</p>
                    </div>
                </div>
                <div class="stat-card">
                    <div class="stat-icon usage">
                        <i class="fas fa-eye"></i>
                    </div>
                    <div class="stat-details">
                        <h3>156</h3>
                        <p>本月访问量</p>
                    </div>
                </div>
            </div>

            <!-- 功能模块卡片 -->
            <div class="module-card" id="dashboardManagementCard">
                <div class="module-header">
                    <div>
                        <div class="module-title">自定义仪表盘管理</div>
                        <div class="module-subtitle">提供拖拽式配置，集成多种图表类型，支持实时数据刷新</div>
                    </div>
                    <div class="action-buttons">
                        <button class="btn btn-primary" onclick="openCreateDashboardModal()">
                            <i class="fas fa-plus-circle"></i> 创建仪表盘
                        </button>
                        <button class="btn btn-secondary" onclick="importTemplate()">
                            <i class="fas fa-file-import"></i> 导入模板
                        </button>
                        <button class="btn btn-secondary" onclick="refreshDashboards()">
                            <i class="fas fa-sync-alt"></i> 刷新
                        </button>
                    </div>
                </div>

                <!-- 仪表盘网格 -->
                <div class="dashboard-grid" id="dashboardGrid">
