                        <label class="form-label" for="dashboardName">仪表盘名称</label>
                        <input type="text" class="form-control" id="dashboardName" placeholder="请输入仪表盘名称" required>
                    </div>

                    <div class="form-group">
                        <label class="form-label" for="dashboardDescription">仪表盘描述</label>
                        <textarea class="form-control" id="dashboardDescription" rows="3" placeholder="请输入仪表盘描述"></textarea>
                    </div>

                    <div class="form-group">
                        <label class="form-label" for="dashboardProject">所属项目</label>
                        <select class="select-control" id="dashboardProject" required>
                            <option value="">请选择项目</option>
                            <option value="1">麒麟操作系统适配测试项目</option>
                            <option value="2">统信UOS适配测试项目</option>
                            <option value="3">中标麒麟安全测试项目</option>
                            <option value="4">华为欧拉兼容性测试项目</option>
                        </select>
                    </div>

                    <div class="form-group">
                        <label class="form-label">布局配置</label>
                        <div style="display: flex; gap: 20px; margin-top: 10px;">
                            <div class="checkbox-item">
                                <input type="radio" id="layoutGrid" name="dashboardLayout" value="grid" checked>
                                <label for="layoutGrid">网格布局</label>
                            </div>
                            <div class="checkbox-item">
                                <input type="radio" id="layoutFree" name="dashboardLayout" value="free">
                                <label for="layoutFree">自由布局</label>
                            </div>
                        </div>
                    </div>

                    <div class="form-group">
                        <label class="form-label">共享设置</label>
                        <div style="display: flex; gap: 20px; margin-top: 10px;">
                            <div class="checkbox-item">
                                <input type="checkbox" id="shareDashboard" name="shareDashboard">
                                <label for="shareDashboard">共享给项目成员</label>
                            </div>
                        </div>
                    </div>

                    <div class="form-group">
                        <label class="form-label">图表类型选择</label>
                        <div class="chart-types">
                            <div class="chart-type-item" onclick="selectChartType(this, 'line')">
                                <div class="chart-type-icon"><i class="fas fa-chart-line"></i></div>
                                <div class="chart-type-name">折线图</div>
