        function updateStats() {
            const totalDashboards = dashboardsData.length;
            const totalCharts = dashboardsData.reduce((sum, dashboard) => sum + dashboard.chartsCount, 0);

            totalDashboardsElement.textContent = totalDashboards;
            totalChartsElement.textContent = totalCharts;
        }

        // 渲染仪表盘网格
        function renderDashboardsGrid() {
            if (dashboardsData.length === 0) {
                emptyState.style.display = 'block';
                dashboardGrid.innerHTML = '';
                pagination.innerHTML = '';
                return;
            }

            emptyState.style.display = 'none';

            // 计算分页
            const totalPages = Math.ceil(dashboardsData.length / itemsPerPage);
            const startIndex = (currentPage - 1) * itemsPerPage;
            const endIndex = Math.min(startIndex + itemsPerPage, dashboardsData.length);
            const pageData = dashboardsData.slice(startIndex, endIndex);

            // 清空网格
            dashboardGrid.innerHTML = '';

            // 填充仪表盘卡片
            pageData.forEach(dashboard => {
                const card = document.createElement('div');
                card.className = 'dashboard-card';
                card.innerHTML = `
