                                <span>${dashboard.project}</span>
                            </div>
                            <div class="stat-item">
                                <i class="fas fa-eye"></i>
                                <span>${dashboard.views}次</span>
                            </div>
                            <div class="stat-item">
                                <i class="fas fa-clock"></i>
                                <span>${dashboard.lastUpdated.split(' ')[0]}</span>
                            </div>
                        </div>
                        <div class="dashboard-actions">
                            <div class="action-icon view-icon" onclick="viewDashboard(${dashboard.id})" title="查看仪表盘">
                                <i class="fas fa-eye"></i>
