                            <div class="action-icon edit-icon" onclick="editDashboard(${dashboard.id})" title="编辑仪表盘">
                                <i class="fas fa-edit"></i>
                            </div>
                            ${dashboard.shared ? 
                                '<div class="action-icon share-icon" onclick="toggleShare(' + dashboard.id + ')" title="取消共享"><i class="fas fa-share-alt"></i></div>' : 
