        // 渲染目录树
        function renderDirectoryTree(data = directoryData, parentElement = document.getElementById('directoryTree')) {
            data.forEach(item => {
                const treeItem = document.createElement('div');
                treeItem.className = 'tree-item';

                const treeLink = document.createElement('a');
                treeLink.className = `tree-link tree-level-${item.level}`;
                if (item.active) treeLink.classList.add('active');

                // 添加图标
                let iconHtml = '';
                if (item.icon) {
                    iconHtml = `<i class="${item.icon}"></i>`;
                }

                // 添加切换图标（如果有子项）
                let toggleIcon = '';
                if (item.children && item.children.length > 0) {
                    toggleIcon = `<span class="toggle-icon ${item.expanded ? 'expanded' : ''}">▶</span>`;
                }

                // 添加徽章（如果有）
                let badgeHtml = '';
                if (item.badge) {
                    badgeHtml = `<span class="tree-badge ${item.badge === 'AI驱动' ? 'new' : ''}">${item.badge}</span>`;
                }

                treeLink.innerHTML = `${toggleIcon}${iconHtml}${item.title}${badgeHtml}`;

                // 绑定点击事件
                treeLink.addEventListener('click', function(e) {
                    e.preventDefault();

                    // 如果点击的是有子项的项，则切换展开/收起
                    if (item.children && item.children.length > 0) {
                        item.expanded = !item.expanded;

                        const toggleIcon = this.querySelector('.toggle-icon');
                        if (toggleIcon) {
                            toggleIcon.classList.toggle('expanded');
                        }

                        const childrenContainer = this.nextElementSibling;
                        if (childrenContainer && childrenContainer.classList.contains('children')) {
                            childrenContainer.classList.toggle('expanded');
                        }

                        // 阻止事件冒泡，避免触发内容切换
                        e.stopPropagation();
                    } else {
                        // 如果没有子项，则显示内容
                        showContent(item.content);

                        // 更新活动状态
                        document.querySelectorAll('.tree-link').forEach(link => {
                            link.classList.remove('active');
                        });
                        this.classList.add('active');
                    }
                });

                treeItem.appendChild(treeLink);

                // 如果有子项，添加子项容器
                if (item.children && item.children.length > 0) {
                    const childrenContainer = document.createElement('div');
                    childrenContainer.className = `children ${item.expanded ? 'expanded' : ''}`;

                    // 递归渲染子项
                    renderDirectoryTree(item.children, childrenContainer);

                    treeItem.appendChild(childrenContainer);
                }

                parentElement.appendChild(treeItem);
            });
        }

        // 显示内容
        function showContent(contentId) {
            const content = contentData[contentId] || contentData['role-permission'];

            // 更新页面标题
            document.getElementById('pageTitle').textContent = content.title;

            // 更新面包屑
            const breadcrumbEl = document.getElementById('breadcrumb');
            breadcrumbEl.innerHTML = '';

            content.breadcrumb.forEach((item, index) => {
                const span = document.createElement('span');
                span.className = 'breadcrumb-item';
                span.textContent = item;

                breadcrumbEl.appendChild(span);

                // 如果不是最后一项，添加分隔符
                if (index < content.breadcrumb.length - 1) {
                    const separator = document.createElement('span');
                    separator.className = 'breadcrumb-separator';
                    separator.textContent = '/';
                    breadcrumbEl.appendChild(separator);
                }
            });

            // 更新内容区域
            document.getElementById('functionContent').innerHTML = content.content;

            // 重新绑定弹窗按钮事件
            const detailBtn = document.getElementById('openDetailBtn');
            if (detailBtn) {
                detailBtn.addEventListener('click', openModal);
            }
