        function openModal() {
            document.getElementById('modalOverlay').classList.add('active');
        }

        // 关闭弹窗
        function closeModal() {
            document.getElementById('modalOverlay').classList.remove('active');
        }

        // 目录搜索过滤
        function filterDirectory(searchText) {
            const treeItems = document.querySelectorAll('.tree-item');
            const searchLower = searchText.toLowerCase();

            treeItems.forEach(item => {
                const link = item.querySelector('.tree-link');
                const text = link.textContent.toLowerCase();

                if (searchText === '' || text.includes(searchLower)) {
                    item.style.display = 'block';

                    // 显示所有父级
                    let parent = item.parentElement;
                    while (parent && parent.classList.contains('children')) {
                        parent.style.display = 'block';
                        parent.classList.add('expanded');

                        // 展开父级的切换图标
                        const parentLink = parent.previousElementSibling;
                        if (parentLink && parentLink.classList.contains('tree-link')) {
                            const toggleIcon = parentLink.querySelector('.toggle-icon');
                            if (toggleIcon) {
                                toggleIcon.classList.add('expanded');
                            }
                        }

                        parent = parent.parentElement;
                    }
                } else {
                    item.style.display = 'none';
                }
            });
        }
