            <ul class="directory-tree" id="directoryTree">
                <!-- 目录树将通过JavaScript动态生成 -->
            </ul>
        </div>
    </div>

    <!-- 右侧主内容区 -->
    <div class="main-content">
        <div class="top-bar">
            <button class="mobile-menu-toggle" id="mobileMenuToggle">
                <i class="fas fa-bars"></i>
            </button>
            <div class="page-title" id="pageTitle">租户管理</div>
            <div class="user-info">
                <div class="user-avatar">刘</div>
                <div>
                    <div style="font-weight: 500;">刘贺</div>
                    <div style="font-size: 13px; color: #666;">项目经理</div>
                </div>
            </div>
        </div>

        <div class="content-area">
            <!-- 统计卡片 -->
            <div class="stats-container">
                <div class="stat-card">
                    <div class="stat-info">
                        <h3>总租户数</h3>
                        <div class="stat-value" id="totalTenants">8</div>
                    </div>
                    <div class="stat-icon blue">
                        <i class="fas fa-building"></i>
                    </div>
                </div>

                <div class="stat-card">
                    <div class="stat-info">
                        <h3>活跃租户</h3>
                        <div class="stat-value" id="activeTenants">6</div>
                    </div>
                    <div class="stat-icon green">
                        <i class="fas fa-check-circle"></i>
                    </div>
                </div>

                <div class="stat-card">
                    <div class="stat-info">
                        <h3>即将到期</h3>
                        <div class="stat-value" id="expiringTenants">2</div>
                    </div>
                    <div class="stat-icon orange">
                        <i class="fas fa-clock"></i>
                    </div>
                </div>

                <div class="stat-card">
                    <div class="stat-info">
                        <h3>已禁用</h3>
                        <div class="stat-value" id="disabledTenants">1</div>
                    </div>
                    <div class="stat-icon red">
                        <i class="fas fa-ban"></i>
                    </div>
                </div>
            </div>

            <!-- 租户管理主卡片 -->
            <div class="module-card" id="tenantManagementCard">
                <div class="module-header">
                    <div>
                        <div class="module-title">多租户数据隔离与独立管理</div>
                        <div class="module-subtitle">支持多个适配中心或团队的数据逻辑隔离，保障信息安全</div>
                    </div>
                    <div class="action-buttons">
                        <button class="btn btn-primary" id="addTenantBtn">
                            <i class="fas fa-plus"></i> 新增租户
                        </button>
                        <button class="btn btn-secondary" id="refreshTenantBtn">
                            <i class="fas fa-sync-alt"></i> 刷新
                        </button>
                    </div>
                </div>

                <!-- 搜索和筛选栏 -->
                <div class="filter-bar">
                    <div class="search-box">
                        <i class="fas fa-search search-icon"></i>
                        <input type="text" class="search-input" id="searchInput" placeholder="搜索租户名称、编码或联系人...">
                    </div>
                    <div class="filter-options">
                        <select class="filter-select" id="statusFilter">
                            <option value="">所有状态</option>
                            <option value="active">已启用</option>
                            <option value="inactive">已禁用</option>
                            <option value="expired">已过期</option>
                        </select>
                        <select class="filter-select" id="isolationFilter">
                            <option value="">所有隔离模式</option>
                            <option value="schema">独立Schema</option>
                            <option value="shared">共享表</option>
                        </select>
                    </div>
                </div>

                <div class="table-container">
                    <table id="tenantsTable">
                        <thead>
                            <tr>
                                <th width="12%">租户编码</th>
                                <th width="15%">租户名称</th>
                                <th width="12%">联系人</th>
