                            <div class="form-hint">唯一标识符，创建后不可修改</div>
                        </div>

                        <div class="form-group">
                            <label class="form-label" for="tenantName">租户名称 *</label>
                            <input type="text" class="form-control" id="tenantName" placeholder="例如：中软国际适配中心" required>
                        </div>
                    </div>

                    <div class="form-group">
                        <label class="form-label" for="tenantDescription">租户描述</label>
                        <textarea class="form-control" id="tenantDescription" rows="3" placeholder="描述租户的主要业务和用途"></textarea>
                    </div>

                    <div class="form-row">
                        <div class="form-group">
                            <label class="form-label" for="contactName">联系人姓名 *</label>
                            <input type="text" class="form-control" id="contactName" placeholder="联系人姓名" required>
                        </div>

                        <div class="form-group">
                            <label class="form-label" for="contactPhone">联系电话 *</label>
                            <input type="text" class="form-control" id="contactPhone" placeholder="联系电话" required>
                        </div>
                    </div>

                    <div class="form-group">
                        <label class="form-label" for="contactEmail">联系邮箱</label>
                        <input type="email" class="form-control" id="contactEmail" placeholder="联系邮箱">
                    </div>

                    <div class="form-row">
                        <div class="form-group">
                            <label class="form-label">数据隔离模式 *</label>
                            <div class="radio-group">
                                <div class="radio-item">
                                    <input type="radio" id="isolationSchema" name="dataIsolation" value="schema" checked>
                                    <label for="isolationSchema">独立Schema</label>
                                </div>
                                <div class="radio-item">
                                    <input type="radio" id="isolationShared" name="dataIsolation" value="shared">
                                    <label for="isolationShared">共享表</label>
                                </div>
                            </div>
                            <div class="form-hint">独立Schema安全性更高，共享表资源利用率更高</div>
                        </div>

                        <div class="form-group">
                            <label class="form-label" for="maxUsers">最大用户数 *</label>
                            <input type="number" class="form-control" id="maxUsers" value="50" min="1" required>
