                        </div>
                    </div>

                    <div class="form-row">
                        <div class="form-group">
                            <label class="form-label" for="expireDate">到期时间</label>
                            <input type="date" class="form-control" id="expireDate">
                            <div class="form-hint">留空表示永不过期</div>
                        </div>

                        <div class="form-group">
                            <label class="form-label" for="tenantStatus">初始状态 *</label>
                            <select class="form-control" id="tenantStatus">
                                <option value="active">启用</option>
                                <option value="inactive">禁用</option>
                            </select>
                        </div>
                    </div>
                </form>
            </div>
            <div class="modal-footer">
                <button class="btn btn-secondary" id="cancelBtn">取消</button>
                <button class="btn btn-primary" id="saveTenantBtn">保存租户</button>
            </div>
        </div>
