<script>
// 会话超时管理模块的JavaScript代码

// DOM元素
const sessionTimeoutCard = document.getElementById('sessionTimeoutCard');
const sessionTimeoutModal = document.getElementById('sessionTimeoutModal');
const editSessionSettingsBtn = document.getElementById('editSessionSettingsBtn');
const testSessionBtn = document.getElementById('testSessionBtn');
const closeSessionModalBtn = document.getElementById('closeSessionModalBtn');
const cancelSessionBtn = document.getElementById('cancelSessionBtn');
const saveSessionBtn = document.getElementById('saveSessionBtn');
const sessionTimeoutForm = document.getElementById('sessionTimeoutForm');

// 会话超时设置数据
let sessionSettings = {
    enabled: true,
    timeoutDuration: 30,
    warningTime: 5,
    resetOnActivity: true,
    logoutOnClose: true,
    multipleSessions: false,
    affectedRoles: ['所有角色'],
    lastModified: '2025-11-10 14:30'
};

// 会话统计数据
let sessionStats = {
    activeSessions: 42,
    todayTimeouts: 8,
    avgSessionDuration: '2小时15分',
    todayUsers: 28
};

// 初始化会话超时管理模块
function initSessionTimeoutModule() {
    // 更新显示当前设置
    updateSessionSettingsDisplay();

    // 事件监听
    editSessionSettingsBtn.addEventListener('click', openSessionSettingsModal);
    testSessionBtn.addEventListener('click', testSessionTimeout);
    closeSessionModalBtn.addEventListener('click', closeSessionModal);
    cancelSessionBtn.addEventListener('click', closeSessionModal);
    saveSessionBtn.addEventListener('click', saveSessionSettings);

    // 点击模态框外部关闭
    sessionTimeoutModal.addEventListener('click', (e) => {
        if (e.target === sessionTimeoutModal) {
            closeSessionModal();
        }
    });

    // 全选角色复选框逻辑
    const roleAllCheckbox = document.getElementById('roleAll');
    const roleCheckboxes = document.querySelectorAll('input[id^="role"]:not(#roleAll)');

    roleAllCheckbox.addEventListener('change', function() {
        roleCheckboxes.forEach(checkbox => {
            checkbox.checked = this.checked;
        });
    });

    // 如果任何一个角色复选框被取消，取消全选
    roleCheckboxes.forEach(checkbox => {
        checkbox.addEventListener('change', function() {
            if (!this.checked) {
                roleAllCheckbox.checked = false;
            }

            // 检查是否所有角色都被选中
            const allChecked = Array.from(roleCheckboxes).every(cb => cb.checked);
            roleAllCheckbox.checked = allChecked;
        });
    });
}

// 更新会话设置显示
function updateSessionSettingsDisplay() {
    document.getElementById('currentTimeoutDisplay').textContent = 
        `${sessionSettings.timeoutDuration} 分钟`;

    document.getElementById('currentWarningDisplay').textContent = 
        `${sessionSettings.warningTime} 分钟前`;

    document.getElementById('currentStatusDisplay').textContent = 
        sessionSettings.enabled ? '已启用' : '已禁用';

    document.getElementById('currentStatusDisplay').style.color = 
        sessionSettings.enabled ? '#0c7c42' : '#dc2626';

    document.getElementById('lastModifiedDisplay').textContent = 
        sessionSettings.lastModified;

    // 更新会话统计
    document.getElementById('activeSessionsDisplay').textContent = 
        sessionStats.activeSessions;

    document.getElementById('todayTimeoutDisplay').textContent = 
        sessionStats.todayTimeouts;

    document.getElementById('avgSessionDisplay').textContent = 
        sessionStats.avgSessionDuration;

    document.getElementById('todayUsersDisplay').textContent = 
        sessionStats.todayUsers;
}

// 打开会话设置模态框
function openSessionSettingsModal() {
    // 填充表单数据
    document.getElementById('timeoutEnabled').checked = sessionSettings.enabled;
    document.getElementById('timeoutDuration').value = sessionSettings.timeoutDuration;
    document.getElementById('warningTime').value = sessionSettings.warningTime;
    document.getElementById('policyResetOnActivity').checked = sessionSettings.resetOnActivity;
    document.getElementById('policyLogoutOnClose').checked = sessionSettings.logoutOnClose;
    document.getElementById('policyMultipleSessions').checked = sessionSettings.multipleSessions;

    // 设置受影响角色
    document.getElementById('roleAll').checked = sessionSettings.affectedRoles.includes('所有角色');
    document.getElementById('roleAdmin').checked = sessionSettings.affectedRoles.includes('系统管理员');
    document.getElementById('roleManager').checked = sessionSettings.affectedRoles.includes('项目经理');
    document.getElementById('roleEngineer').checked = sessionSettings.affectedRoles.includes('测试工程师');
    document.getElementById('roleViewer').checked = sessionSettings.affectedRoles.includes('观察员');

    sessionTimeoutModal.classList.add('active');
}

// 关闭会话设置模态框
function closeSessionModal() {
    sessionTimeoutModal.classList.remove('active');
    sessionTimeoutForm.reset();
}

// 保存会话设置
function saveSessionSettings() {
    // 收集表单数据
    sessionSettings.enabled = document.getElementById('timeoutEnabled').checked;
    sessionSettings.timeoutDuration = parseInt(document.getElementById('timeoutDuration').value);
    sessionSettings.warningTime = parseInt(document.getElementById('warningTime').value);
    sessionSettings.resetOnActivity = document.getElementById('policyResetOnActivity').checked;
    sessionSettings.logoutOnClose = document.getElementById('policyLogoutOnClose').checked;
    sessionSettings.multipleSessions = document.getElementById('policyMultipleSessions').checked;

    // 收集受影响角色
    sessionSettings.affectedRoles = [];
    if (document.getElementById('roleAll').checked) {
        sessionSettings.affectedRoles.push('所有角色');
    } else {
        if (document.getElementById('roleAdmin').checked) sessionSettings.affectedRoles.push('系统管理员');
        if (document.getElementById('roleManager').checked) sessionSettings.affectedRoles.push('项目经理');
        if (document.getElementById('roleEngineer').checked) sessionSettings.affectedRoles.push('测试工程师');
        if (document.getElementById('roleViewer').checked) sessionSettings.affectedRoles.push('观察员');
    }

    // 更新最后修改时间
    const now = new Date();
    sessionSettings.lastModified = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')} ${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;

    // 更新显示
    updateSessionSettingsDisplay();

    // 关闭模态框
    closeSessionModal();

    // 显示成功通知
    showNotification('会话超时设置已保存成功', 'success');
}

// 测试会话超时功能
function testSessionTimeout() {
    // 创建测试模态框
    const testModal = document.createElement('div');
    testModal.style.cssText = `
        position: fixed;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
        background-color: rgba(0, 0, 0, 0.7);
        display: flex;
        align-items: center;
        justify-content: center;
        z-index: 1000;
    `;

    testModal.innerHTML = `
        <div style="background-color: white; border-radius: 12px; padding: 30px; width: 400px; max-width: 90%;">
            <div style="font-size: 20px; font-weight: 600; margin-bottom: 20px; color: #1a3a8f;">
                <i class="fas fa-clock" style="margin-right: 10px;"></i>会话超时测试
            </div>
            <div style="margin-bottom: 25px; line-height: 1.6; color: #555;">
                此测试将模拟会话超时过程。系统将在5秒后显示超时提醒对话框。
            </div>
            <div style="display: flex; justify-content: flex-end; gap: 15px;">
                <button id="cancelTestBtn" style="padding: 10px 20px; border-radius: 6px; border: 1px solid #ddd; background-color: #f5f5f5; cursor: pointer;">取消</button>
                <button id="startTestBtn" style="padding: 10px 20px; border-radius: 6px; border: none; background-color: #1a3a8f; color: white; cursor: pointer;">开始测试</button>
            </div>
        </div>
    `;

    document.body.appendChild(testModal);

    // 开始测试按钮
    document.getElementById('startTestBtn').addEventListener('click', function() {
        testModal.remove();

        // 显示倒计时
        const countdownModal = document.createElement('div');
        countdownModal.style.cssText = `
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background-color: rgba(0, 0, 0, 0.7);
            display: flex;
            align-items: center;
            justify-content: center;
            z-index: 1000;
        `;

        let countdown = 5;

        countdownModal.innerHTML = `
            <div style="background-color: white; border-radius: 12px; padding: 30px; width: 400px; max-width: 90%; text-align: center;">
                <div style="font-size: 20px; font-weight: 600; margin-bottom: 20px; color: #1a3a8f;">
                    会话超时测试进行中
                </div>
                <div style="font-size: 48px; font-weight: 700; color: #1a3a8f; margin: 20px 0;" id="countdownDisplay">${countdown}</div>
                <div style="margin-bottom: 25px; line-height: 1.6; color: #555;">
                    模拟会话超时，将在 <span id="countdownSeconds">${countdown}</span> 秒后显示超时提醒
                </div>
                <div style="height: 10px; background-color: #eaeff5; border-radius: 5px; overflow: hidden;">
                    <div id="countdownProgress" style="height: 100%; width: 100%; background-color: #1a3a8f; transition: width 1s linear;"></div>
                </div>
            </div>
        `;

        document.body.appendChild(countdownModal);

        const countdownDisplay = document.getElementById('countdownDisplay');
        const countdownSeconds = document.getElementById('countdownSeconds');
        const countdownProgress = document.getElementById('countdownProgress');

        const countdownInterval = setInterval(() => {
            countdown--;
            countdownDisplay.textContent = countdown;
            countdownSeconds.textContent = countdown;
            countdownProgress.style.width = `${(countdown / 5) * 100}%`;

            if (countdown <= 0) {
                clearInterval(countdownInterval);
                countdownModal.remove();
                showTimeoutWarning();
            }
        }, 1000);
    });

    // 取消测试按钮
    document.getElementById('cancelTestBtn').addEventListener('click', function() {
        testModal.remove();
    });
}

// 显示超时警告
function showTimeoutWarning() {
    const warningModal = document.createElement('div');
    warningModal.style.cssText = `
        position: fixed;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
        background-color: rgba(0, 0, 0, 0.7);
        display: flex;
        align-items: center;
        justify-content: center;
        z-index: 1000;
    `;

    let warningCountdown = 60; // 60秒后自动退出

    warningModal.innerHTML = `
        <div style="background-color: white; border-radius: 12px; padding: 30px; width: 500px; max-width: 90%;">
            <div style="display: flex; align-items: center; margin-bottom: 20px;">
                <div style="width: 50px; height: 50px; border-radius: 50%; background-color: #fef3c7; color: #d97706; display: flex; align-items: center; justify-content: center; margin-right: 15px;">
