                <button id="continueSessionBtn" style="padding: 10px 20px; border-radius: 6px; border: none; background-color: #1a3a8f; color: white; cursor: pointer;">继续会话</button>
            </div>
        </div>
    `;

    document.body.appendChild(warningModal);

    const warningCountdownDisplay = document.getElementById('warningCountdownDisplay');
    const warningCountdownSeconds = document.getElementById('warningCountdownSeconds');
    const warningCountdownProgress = document.getElementById('warningCountdownProgress');

    const warningInterval = setInterval(() => {
        warningCountdown--;
        warningCountdownDisplay.textContent = warningCountdown;
        warningCountdownSeconds.textContent = warningCountdown;
        warningCountdownProgress.style.width = `${(warningCountdown / 60) * 100}%`;

        if (warningCountdown <= 0) {
            clearInterval(warningInterval);
            warningModal.remove();
            showSessionExpired();
        }
    }, 1000);

    // 继续会话按钮
    document.getElementById('continueSessionBtn').addEventListener('click', function() {
        clearInterval(warningInterval);
        warningModal.remove();
        showNotification('会话已延长，您可以继续使用系统', 'success');
    });

    // 立即退出按钮
    document.getElementById('logoutNowBtn').addEventListener('click', function() {
        clearInterval(warningInterval);
        warningModal.remove();
        showSessionExpired();
    });
}

