        const projectTypeFilter = document.getElementById('projectTypeFilter');
        const resetFilterBtn = document.getElementById('resetFilterBtn');
        const searchProjectBtn = document.getElementById('searchProjectBtn');
        const projectDetailModal = document.getElementById('projectDetailModal');
        const projectDetailTitle = document.getElementById('projectDetailTitle');
        const projectDetailContent = document.getElementById('projectDetailContent');
        const closeProjectDetailBtn = document.getElementById('closeProjectDetailBtn');
        const closeDetailBtn = document.getElementById('closeDetailBtn');
        const editProjectBtn = document.getElementById('editProjectBtn');
        const totalProjectsEl = document.getElementById('totalProjects');
        const inProgressProjectsEl = document.getElementById('inProgressProjects');
        const completedProjectsEl = document.getElementById('completedProjects');
        const urgentProjectsEl = document.getElementById('urgentProjects');

        let isRoleEditing = false;
        let editingRoleId = null;
        let isProjectEditing = false;
        let editingProjectId = null;
        let viewingProjectId = null;

        // 初始化目录树
        function initDirectoryTree() {
            directoryTree.innerHTML = '';

            directoryData.forEach(section => {
                const li = document.createElement('li');
                li.className = 'tree-item';

                const header = document.createElement('div');
                header.className = 'tree-header';
                header.dataset.id = section.id;

                header.innerHTML = `
                    <div class="tree-title">
                        <i class="${section.icon}"></i>
                        <span>${section.title}</span>
                    </div>
                    <div class="tree-toggle ${section.expanded ? '' : 'collapsed'}">
                        <i class="fas fa-chevron-down"></i>
                    </div>
                `;

                const content = document.createElement('ul');
                content.className = `tree-content ${section.expanded ? 'expanded' : ''}`;

                section.subItems.forEach(subItem => {
                    const subLi = document.createElement('li');
                    subLi.className = 'tree-subitem';
                    subLi.dataset.id = subItem.id;
                    subLi.dataset.parentId = section.id;

                    let iconHtml = '';
                    if (subItem.icon) {
                        iconHtml = `<i class="${subItem.icon}"></i>`;
                    }

                    subLi.innerHTML = `${iconHtml}<span>${subItem.title}</span>`;

                    // 默认选中第一个子项
                    if (section.id === 'user-management' && subItem.id === 'role-access-control') {
                        subLi.classList.add('active');
                        header.classList.add('active');
                    }

                    // 添加点击事件
                    subLi.addEventListener('click', (e) => {
                        e.stopPropagation();
                        selectMenuItem(subItem.id, subItem.title);

                        // 更新活动状态
                        document.querySelectorAll('.tree-subitem').forEach(item => {
                            item.classList.remove('active');
                        });
                        document.querySelectorAll('.tree-header').forEach(item => {
                            item.classList.remove('active');
                        });

                        subLi.classList.add('active');
                        header.classList.add('active');
                    });

                    content.appendChild(subLi);
                });

                // 添加点击事件展开/折叠
                header.addEventListener('click', () => {
                    const isExpanded = content.classList.contains('expanded');
                    const toggleIcon = header.querySelector('.tree-toggle i');

                    if (isExpanded) {
                        content.classList.remove('expanded');
                        header.querySelector('.tree-toggle').classList.add('collapsed');
                    } else {
                        content.classList.add('expanded');
                        header.querySelector('.tree-toggle').classList.remove('collapsed');
                    }
                });

                li.appendChild(header);
                li.appendChild(content);
                directoryTree.appendChild(li);
            });
        }

        // 选择菜单项
        function selectMenuItem(itemId, itemTitle) {
            pageTitle.textContent = itemTitle;

            // 隐藏所有模块，显示对应的模块
            document.querySelectorAll('.module-content').forEach(module => {
                module.classList.remove('active');
            });

            if (itemId === 'role-access-control') {
                roleModule.classList.add('active');
            } else if (itemId === 'project-create') {
                projectModule.classList.add('active');
                renderProjectsTable();
                updateProjectStats();
            }

            // 如果是移动端，点击后关闭侧边栏
            if (window.innerWidth <= 992) {
                sidebar.classList.remove('active');
            }
        }

        // 渲染角色表格
        function renderRolesTable() {
            if (rolesData.length === 0) {
                roleEmptyState.style.display = 'block';
                rolesTableBody.innerHTML = '';
                return;
            }

            roleEmptyState.style.display = 'none';
            rolesTableBody.innerHTML = '';

            rolesData.forEach(role => {
                const permissionsHtml = role.permissions.map(perm => 
                    `<span class="permission-tag">${perm}</span>`
                ).join('');

                const row = document.createElement('tr');
                row.innerHTML = `
                    <td>
                        <div class="role-badge ${role.badgeClass}">${role.name}</div>
                    </td>
                    <td>${role.code}</td>
                    <td>${role.description}</td>
                    <td>
                        <div class="permission-list">
                            ${permissionsHtml}
                        </div>
                    </td>
                    <td>
                        <div class="action-cell">
                            <div class="action-icon edit-icon" data-id="${role.id}">
                                <i class="fas fa-edit"></i>
                            </div>
                            <div class="action-icon delete-icon" data-id="${role.id}">
                                <i class="fas fa-trash"></i>
                            </div>
                        </div>
                    </td>
                `;

                rolesTableBody.appendChild(row);
            });

            // 添加编辑和删除事件监听
            document.querySelectorAll('.edit-icon').forEach(icon => {
                icon.addEventListener('click', (e) => {
                    const roleId = parseInt(e.currentTarget.dataset.id);
                    editRole(roleId);
                });
            });

            document.querySelectorAll('.delete-icon').forEach(icon => {
                icon.addEventListener('click', (e) => {
                    const roleId = parseInt(e.currentTarget.dataset.id);
                    deleteRole(roleId);
                });
            });
        }

        // 渲染项目表格
        function renderProjectsTable() {
            // 更新分页信息
            const totalItems = filteredProjects.length;
            const totalPages = Math.ceil(totalItems / itemsPerPage);

            // 确保当前页在有效范围内
            if (currentPage > totalPages && totalPages > 0) {
                currentPage = totalPages;
            } else if (currentPage < 1 && totalItems > 0) {
                currentPage = 1;
            }

            // 计算当前页的项目数据
            const startIndex = (currentPage - 1) * itemsPerPage;
            const endIndex = Math.min(startIndex + itemsPerPage, totalItems);
            const currentProjects = filteredProjects.slice(startIndex, endIndex);

            // 渲染表格
            if (currentProjects.length === 0) {
                projectEmptyState.style.display = 'block';
                projectsTableBody.innerHTML = '';
            } else {
                projectEmptyState.style.display = 'none';
                projectsTableBody.innerHTML = '';

                currentProjects.forEach(project => {
                    // 根据状态获取对应的徽章类
                    let statusBadgeClass = '';
                    switch(project.status) {
                        case 0: statusBadgeClass = 'status-not-started'; break;
                        case 1: statusBadgeClass = 'status-in-progress'; break;
                        case 2: statusBadgeClass = 'status-paused'; break;
                        case 3: statusBadgeClass = 'status-completed'; break;
                        case 4: statusBadgeClass = 'status-closed'; break;
                    }

                    // 根据优先级获取对应的徽章类
                    let priorityBadgeClass = '';
                    switch(project.priority) {
                        case 1: priorityBadgeClass = 'priority-low'; break;
                        case 2: priorityBadgeClass = 'priority-medium'; break;
                        case 3: priorityBadgeClass = 'priority-high'; break;
                        case 4: priorityBadgeClass = 'priority-urgent'; break;
                    }

                    const row = document.createElement('tr');
                    row.innerHTML = `
                        <td>${project.projectCode}</td>
                        <td>
                            <div style="font-weight: 500;">${project.projectName}</div>
                            <div style="font-size: 12px; color: #666; margin-top: 4px;">${project.projectDesc.substring(0, 50)}${project.projectDesc.length > 50 ? '...' : ''}</div>
                        </td>
                        <td>${project.projectTypeText}</td>
                        <td><span class="status-badge ${statusBadgeClass}">${project.statusText}</span></td>
                        <td><span class="priority-badge ${priorityBadgeClass}">${project.priorityText}</span></td>
                        <td>${project.projectLeader}</td>
                        <td>
                            <div class="action-cell">
                                <button class="btn btn-secondary" style="padding: 5px 10px; font-size: 13px;" data-id="${project.id}" onclick="viewProject(${project.id})">
                                    <i class="fas fa-eye"></i> 查看
                                </button>
                                <button class="btn btn-secondary" style="padding: 5px 10px; font-size: 13px;" data-id="${project.id}" onclick="editProject(${project.id})">
                                    <i class="fas fa-edit"></i> 编辑
                                </button>
                                <div class="action-icon delete-icon" data-id="${project.id}">
                                    <i class="fas fa-trash"></i>
                                </div>
                            </div>
                        </td>
                    `;

                    projectsTableBody.appendChild(row);
                });
            }

            // 更新分页信息文本
            const startItem = totalItems > 0 ? startIndex + 1 : 0;
            const endItem = totalItems > 0 ? endIndex : 0;
            paginationInfo.textContent = `显示第 ${startItem}-${endItem} 条，共 ${totalItems} 条`;

            // 渲染分页按钮
            renderPagination(totalPages);

            // 添加删除事件监听
            document.querySelectorAll('.delete-icon').forEach(icon => {
                icon.addEventListener('click', (e) => {
                    const projectId = parseInt(e.currentTarget.dataset.id);
                    deleteProject(projectId);
                });
            });
        }

        // 渲染分页按钮
        function renderPagination(totalPages) {
            pagination.innerHTML = '';

            if (totalPages <= 1) {
                return;
            }

            // 上一页按钮
            const prevButton = document.createElement('button');
            prevButton.className = `pagination-btn ${currentPage === 1 ? 'disabled' : ''}`;
            prevButton.innerHTML = '<i class="fas fa-chevron-left"></i>';
            prevButton.disabled = currentPage === 1;
            prevButton.addEventListener('click', () => {
                if (currentPage > 1) {
                    currentPage--;
                    renderProjectsTable();
                }
            });
            pagination.appendChild(prevButton);

            // 页码按钮
            const maxVisiblePages = 5;
            let startPage = Math.max(1, currentPage - Math.floor(maxVisiblePages / 2));
            let endPage = Math.min(totalPages, startPage + maxVisiblePages - 1);

            if (endPage - startPage + 1 < maxVisiblePages) {
                startPage = Math.max(1, endPage - maxVisiblePages + 1);
            }

            // 第一页
            if (startPage > 1) {
                const firstButton = document.createElement('button');
                firstButton.className = 'pagination-btn';
                firstButton.textContent = '1';
                firstButton.addEventListener('click', () => {
                    currentPage = 1;
                    renderProjectsTable();
                });
                pagination.appendChild(firstButton);

                if (startPage > 2) {
                    const dots = document.createElement('div');
                    dots.className = 'pagination-dots';
                    dots.textContent = '...';
                    pagination.appendChild(dots);
                }
            }

            // 中间页码
            for (let i = startPage; i <= endPage; i++) {
                const pageButton = document.createElement('button');
                pageButton.className = `pagination-btn ${i === currentPage ? 'active' : ''}`;
                pageButton.textContent = i;
                pageButton.addEventListener('click', () => {
                    currentPage = i;
                    renderProjectsTable();
                });
                pagination.appendChild(pageButton);
            }

            // 最后一页
            if (endPage < totalPages) {
                if (endPage < totalPages - 1) {
                    const dots = document.createElement('div');
                    dots.className = 'pagination-dots';
                    dots.textContent = '...';
                    pagination.appendChild(dots);
                }

                const lastButton = document.createElement('button');
                lastButton.className = 'pagination-btn';
                lastButton.textContent = totalPages;
                lastButton.addEventListener('click', () => {
                    currentPage = totalPages;
                    renderProjectsTable();
                });
                pagination.appendChild(lastButton);
            }

            // 下一页按钮
            const nextButton = document.createElement('button');
            nextButton.className = `pagination-btn ${currentPage === totalPages ? 'disabled' : ''}`;
            nextButton.innerHTML = '<i class="fas fa-chevron-right"></i>';
            nextButton.disabled = currentPage === totalPages;
            nextButton.addEventListener('click', () => {
                if (currentPage < totalPages) {
                    currentPage++;
                    renderProjectsTable();
                }
            });
            pagination.appendChild(nextButton);
        }

        // 更新项目统计
        function updateProjectStats() {
            const totalProjects = projectsData.length;
            const inProgressProjects = projectsData.filter(p => p.status === 1).length;
            const completedProjects = projectsData.filter(p => p.status === 3).length;
            const urgentProjects = projectsData.filter(p => p.priority === 4).length;

            totalProjectsEl.textContent = totalProjects;
            inProgressProjectsEl.textContent = inProgressProjects;
            completedProjectsEl.textContent = completedProjects;
            urgentProjectsEl.textContent = urgentProjects;
        }

        // 打开创建项目模态框
        function openCreateProjectModal() {
            isProjectEditing = false;
            editingProjectId = null;
            projectModalTitle.textContent = '创建新项目';
            projectForm.reset();

            // 生成项目编号
            const today = new Date();
            const year = today.getFullYear();
            const month = String(today.getMonth() + 1).padStart(2, '0');
            const day = String(today.getDate()).padStart(2, '0');
            const nextId = projectsData.length > 0 ? Math.max(...projectsData.map(p => p.id)) + 1 : 1;
            projectCodeInput.value = `PROJ-${year}${month}${day}-${String(nextId).padStart(3, '0')}`;

            // 设置默认日期（今天和30天后）
            const todayStr = today.toISOString().split('T')[0];
            const futureDate = new Date(today);
            futureDate.setDate(futureDate.getDate() + 30);
            const futureStr = futureDate.toISOString().split('T')[0];

            planStartDateInput.value = todayStr;
            planStartDateInput.min = todayStr;
            planEndDateInput.value = futureStr;
            planEndDateInput.min = todayStr;

            // 填充负责人选项
            projectLeaderSelect.innerHTML = '<option value="">请选择项目负责人</option>';
            leadersData.forEach(leader => {
                const option = document.createElement('option');
                option.value = leader.id;
                option.textContent = `${leader.name} (${leader.role})`;
                projectLeaderSelect.appendChild(option);
            });

            projectModal.classList.add('active');
        }

