                        <div><strong>项目名称：</strong> ${project.projectName}</div>
                        <div><strong>项目类型：</strong> ${project.projectTypeText}</div>
                        <div><strong>项目状态：</strong> <span class="status-badge ${statusBadgeClass}">${project.statusText}</span></div>
                        <div><strong>优先级：</strong> <span class="priority-badge ${priorityBadgeClass}">${project.priorityText}</span></div>
                    </div>
                </div>

                <div class="project-detail-section">
                    <div class="detail-label">项目描述</div>
                    <div class="detail-value">${project.projectDesc || '暂无描述'}</div>
                </div>

                <div class="project-detail-section">
                    <div class="detail-label">时间安排</div>
                    <div class="detail-value">
                        <div><strong>计划开始时间：</strong> ${project.planStartDate}</div>
                        <div><strong>计划结束时间：</strong> ${project.planEndDate}</div>
                        <div><strong>实际开始时间：</strong> ${project.actualStartDate || '未开始'}</div>
                        <div><strong>实际结束时间：</strong> ${project.actualEndDate || '未结束'}</div>
                    </div>
                </div>

                <div class="project-detail-section">
                    <div class="detail-label">项目团队</div>
                    <div class="detail-value">
                        <div><strong>项目负责人：</strong> ${project.projectLeader}</div>
                        <div><strong>测试流程模板：</strong> ${project.processTemplate || '未指定'}</div>
                    </div>
                </div>

                <div class="project-detail-section">
                    <div class="detail-label">项目标签</div>
                    <div class="detail-value">${tagsHtml}</div>
                </div>

                <div class="project-detail-section">
                    <div class="detail-label">其他信息</div>
                    <div class="detail-value">
                        <div><strong>创建时间：</strong> ${project.createTime}</div>
