        // 编辑项目
        function editProject(projectId) {
            const project = projectsData.find(p => p.id === projectId);
            if (!project) return;

            isProjectEditing = true;
            editingProjectId = projectId;
            projectModalTitle.textContent = '编辑项目';

            // 填充表单
            projectCodeInput.value = project.projectCode;
            projectNameInput.value = project.projectName;
            projectDescInput.value = project.projectDesc || '';
            projectTypeSelect.value = project.projectType;
            projectPrioritySelect.value = project.priority;
            planStartDateInput.value = project.planStartDate;
            planEndDateInput.value = project.planEndDate;
            projectTagsInput.value = project.tags ? project.tags.join(', ') : '';

            // 填充负责人选项
            projectLeaderSelect.innerHTML = '<option value="">请选择项目负责人</option>';
            leadersData.forEach(leader => {
                const option = document.createElement('option');
                option.value = leader.id;
                option.textContent = `${leader.name} (${leader.role})`;
                option.selected = leader.id === project.projectLeaderId;
                projectLeaderSelect.appendChild(option);
            });

            // 填充流程模板
            processTemplateSelect.value = project.processTemplate ? 
                project.processTemplate === '标准适配测试流程' ? '1' :
                project.processTemplate === '紧急适配测试流程' ? '2' :
                project.processTemplate === '专项测试流程' ? '3' :
                project.processTemplate === '定制化测试流程' ? '4' : '' : '';

            projectModal.classList.add('active');
        }

        // 删除项目
        function deleteProject(projectId) {
            if (confirm('确定要删除这个项目吗？此操作不可恢复。')) {
                projectsData = projectsData.filter(project => project.id !== projectId);
                filteredProjects = [...projectsData];
                renderProjectsTable();
                updateProjectStats();
                showNotification('项目删除成功', 'success');
            }
        }

        // 保存项目
        function saveProject() {
            const projectName = projectNameInput.value.trim();
            const projectDesc = projectDescInput.value.trim();
            const projectType = projectTypeSelect.value;
            const projectPriority = projectPrioritySelect.value;
            const planStartDate = planStartDateInput.value;
            const planEndDate = planEndDateInput.value;
            const projectLeaderId = projectLeaderSelect.value;
            const processTemplate = processTemplateSelect.value;
            const projectTags = projectTagsInput.value.trim();

            // 验证必填字段
            if (!projectName || !projectType || !projectPriority || !planStartDate || !planEndDate || !projectLeaderId) {
                alert('请填写所有必填字段（带*号）');
                return;
            }

            // 验证日期
            if (new Date(planEndDate) < new Date(planStartDate)) {
                alert('计划结束日期不能早于计划开始日期');
                return;
            }

            // 获取负责人信息
            const leader = leadersData.find(l => l.id == projectLeaderId);
            if (!leader) {
                alert('请选择有效的项目负责人');
                return;
            }

            // 处理标签
            const tags = projectTags ? projectTags.split(',').map(tag => tag.trim()).filter(tag => tag) : [];

            // 项目类型文本
            const projectTypeText = projectType === '0' ? '标准适配项目' :
                                  projectType === '1' ? '紧急适配项目' :
                                  projectType === '2' ? '专项测试项目' :
                                  projectType === '3' ? '定制化项目' : '';

            // 优先级文本
            const priorityText = projectPriority === '1' ? '低' :
                               projectPriority === '2' ? '中' :
                               projectPriority === '3' ? '高' :
                               projectPriority === '4' ? '紧急' : '';

            // 流程模板文本
            const processTemplateText = processTemplate === '1' ? '标准适配测试流程' :
                                      processTemplate === '2' ? '紧急适配测试流程' :
                                      processTemplate === '3' ? '专项测试流程' :
                                      processTemplate === '4' ? '定制化测试流程' : '';

            if (isProjectEditing) {
                // 更新现有项目
                const projectIndex = projectsData.findIndex(p => p.id === editingProjectId);
                if (projectIndex !== -1) {
                    projectsData[projectIndex] = {
                        ...projectsData[projectIndex],
                        projectName: projectName,
                        projectDesc: projectDesc,
                        projectType: parseInt(projectType),
                        projectTypeText: projectTypeText,
                        priority: parseInt(projectPriority),
                        priorityText: priorityText,
                        planStartDate: planStartDate,
                        planEndDate: planEndDate,
                        projectLeader: leader.name,
                        projectLeaderId: leader.id,
                        processTemplate: processTemplateText,
                        tags: tags,
                        updateTime: new Date().toISOString().split('T')[0] + ' ' + 
                                   new Date().toTimeString().split(' ')[0].substring(0, 8)
                    };
                }
            } else {
                // 创建新项目
                const today = new Date();
                const newProject = {
                    id: projectsData.length > 0 ? Math.max(...projectsData.map(p => p.id)) + 1 : 1,
                    projectCode: projectCodeInput.value,
                    projectName: projectName,
                    projectDesc: projectDesc,
                    projectType: parseInt(projectType),
                    projectTypeText: projectTypeText,
                    priority: parseInt(projectPriority),
                    priorityText: priorityText,
                    status: 0, // 未开始
                    statusText: '未开始',
                    projectLeader: leader.name,
                    projectLeaderId: leader.id,
                    planStartDate: planStartDate,
                    planEndDate: planEndDate,
                    actualStartDate: null,
                    actualEndDate: null,
                    processTemplate: processTemplateText,
                    tags: tags,
                    createTime: today.toISOString().split('T')[0] + ' ' + 
                               today.toTimeString().split(' ')[0].substring(0, 8),
                    updateTime: today.toISOString().split('T')[0] + ' ' + 
                               today.toTimeString().split(' ')[0].substring(0, 8)
                };
                projectsData.push(newProject);
            }

            filteredProjects = [...projectsData];
            renderProjectsTable();
            updateProjectStats();
            closeProjectModal();
            showNotification(`项目${isProjectEditing ? '更新' : '创建'}成功`, 'success');
        }

        // 搜索项目
        function searchProjects() {
            const searchText = projectSearchInput.value.trim().toLowerCase();
            const statusFilter = projectStatusFilter.value;
            const typeFilter = projectTypeFilter.value;

            filteredProjects = projectsData.filter(project => {
                // 文本搜索
                const matchesSearch = !searchText || 
                    project.projectName.toLowerCase().includes(searchText) ||
                    project.projectCode.toLowerCase().includes(searchText) ||
                    (project.projectDesc && project.projectDesc.toLowerCase().includes(searchText));

                // 状态筛选
                const matchesStatus = !statusFilter || project.status == statusFilter;

                // 类型筛选
                const matchesType = !typeFilter || project.projectType == typeFilter;

                return matchesSearch && matchesStatus && matchesType;
            });

            currentPage = 1; // 重置到第一页
            renderProjectsTable();
        }

        // 重置筛选
        function resetFilters() {
            projectSearchInput.value = '';
            projectStatusFilter.value = '';
            projectTypeFilter.value = '';
            filteredProjects = [...projectsData];
            currentPage = 1;
            renderProjectsTable();
        }

        // 关闭项目模态框
        function closeProjectModal() {
            projectModal.classList.remove('active');
            projectForm.reset();
        }

        // 关闭项目详情模态框
        function closeProjectDetailModal() {
            projectDetailModal.classList.remove('active');
        }

        // 打开编辑项目模态框（从详情页）
        function openEditProjectFromDetail() {
            if (viewingProjectId) {
                closeProjectDetailModal();
                setTimeout(() => {
                    editProject(viewingProjectId);
                }, 300);
            }
        }

        // 角色模块相关函数保持不变

        // 初始化
        document.addEventListener('DOMContentLoaded', () => {
            initDirectoryTree();
            renderRolesTable();
            renderProjectsTable();
            updateProjectStats();

            // 设置默认日期为今天
            const today = new Date().toISOString().split('T')[0];
            planStartDateInput.value = today;
            planEndDateInput.min = today;
            planEndDateInput.value = today;

            // 事件监听 - 角色模块
            addRoleBtn.addEventListener('click', openAddRoleModal);
            refreshRoleBtn.addEventListener('click', () => {
                renderRolesTable();
                showNotification('角色数据已刷新', 'success');
            });
            closeRoleModalBtn.addEventListener('click', closeModal);
            cancelRoleBtn.addEventListener('click', closeModal);
            saveRoleBtn.addEventListener('click', saveRole);

            // 事件监听 - 项目模块
            createProjectBtn.addEventListener('click', openCreateProjectModal);
            searchProjectBtn.addEventListener('click', searchProjects);
            resetFilterBtn.addEventListener('click', resetFilters);
            closeProjectModalBtn.addEventListener('click', closeProjectModal);
            cancelProjectBtn.addEventListener('click', closeProjectModal);
            saveProjectBtn.addEventListener('click', saveProject);
            closeProjectDetailBtn.addEventListener('click', closeProjectDetailModal);
            closeDetailBtn.addEventListener('click', closeProjectDetailModal);
            editProjectBtn.addEventListener('click', openEditProjectFromDetail);

            // 回车键触发搜索
            projectSearchInput.addEventListener('keypress', (e) => {
                if (e.key === 'Enter') {
                    searchProjects();
                }
            });

            // 点击模态框外部关闭
            roleModal.addEventListener('click', (e) => {
                if (e.target === roleModal) {
                    closeModal();
                }
            });

            projectModal.addEventListener('click', (e) => {
                if (e.target === projectModal) {
                    closeProjectModal();
                }
            });

            projectDetailModal.addEventListener('click', (e) => {
                if (e.target === projectDetailModal) {
                    closeProjectDetailModal();
                }
            });

            // 移动端菜单切换
            mobileMenuToggle.addEventListener('click', () => {
                sidebar.classList.toggle('active');
            });

            // 窗口大小变化时调整侧边栏
            window.addEventListener('resize', () => {
                if (window.innerWidth > 992) {
                    sidebar.classList.remove('active');
                }
            });

            // 全局函数暴露给onclick事件
            window.viewProject = viewProject;
            window.editProject = editProject;
        });
    </script>
</body>
</html>
