        // 获取优先级徽章类
        function getPriorityBadgeClass(priority) {
            switch(priority) {
                case 'high': return 'badge-high';
                case 'medium': return 'badge-medium';
                case 'low': return 'badge-low';
                default: return '';
            }
        }

        // 获取优先级文本
        function getPriorityText(priority) {
            switch(priority) {
                case 'high': return '高';
                case 'medium': return '中';
                case 'low': return '低';
                default: return priority;
            }
        }

        // 获取类型徽章类
        function getTypeBadgeClass(type) {
            switch(type) {
                case 'functional': return 'badge-functional';
                case 'performance': return 'badge-performance';
                case 'security': return 'badge-security';
                case 'compatibility': return 'badge-functional';
                default: return '';
            }
        }

        // 获取类型文本
        function getTypeText(type) {
            switch(type) {
                case 'functional': return '功能测试';
                case 'performance': return '性能测试';
                case 'security': return '安全测试';
                case 'compatibility': return '兼容性测试';
                case 'regression': return '回归测试';
                default: return type;
            }
        }

        // 获取状态徽章类
        function getStatusBadgeClass(status) {
            switch(status) {
                case 'draft': return 'badge-draft';
                case 'reviewing': return 'badge-warning';
                case 'reviewed': return 'badge-reviewed';
                case 'archived': return 'badge-archived';
                default: return '';
            }
        }

        // 获取状态文本
        function getStatusText(status) {
            switch(status) {
                case 'draft': return '草稿';
                case 'reviewing': return '评审中';
                case 'reviewed': return '已评审';
                case 'archived': return '已归档';
                default: return status;
            }
        }

        // 应用筛选条件
        function applyFilters() {
            const priority = priorityFilter.value;
            const type = typeFilter.value;
            const status = statusFilter.value;
            const searchText = searchInput.value.toLowerCase();

            currentFilteredData = testCasesData.filter(testCase => {
                // 优先级筛选
                if (priority && testCase.priority !== priority) return false;

                // 类型筛选
                if (type && testCase.caseType !== type) return false;

                // 状态筛选
                if (status && testCase.status !== status) return false;

                // 搜索筛选
                if (searchText) {
                    const searchFields = [
                        testCase.caseCode,
                        testCase.caseName,
                        testCase.description,
                        testCase.module,
                        testCase.creator
                    ];

                    const hasMatch = searchFields.some(field => 
                        field && field.toLowerCase().includes(searchText)
                    );

                    if (!hasMatch) return false;
                }

                return true;
            });

            // 重新渲染表格和分页
            renderTestCasesTable();
            initPagination();
        }

        // 渲染测试用例表格
        function renderTestCasesTable(data = currentFilteredData) {
            if (data.length === 0) {
                emptyState.style.display = 'block';
                testCasesTableBody.innerHTML = '';
                paginationContainer.innerHTML = '';
                return;
            }

            emptyState.style.display = 'none';

            // 计算当前页的数据
            const startIndex = (currentPage - 1) * itemsPerPage;
            const endIndex = startIndex + itemsPerPage;
            const pageData = data.slice(startIndex, endIndex);

            testCasesTableBody.innerHTML = '';

            pageData.forEach(testCase => {
                const row = document.createElement('tr');
                row.innerHTML = `
                    <td>${testCase.caseCode}</td>
                    <td>${testCase.caseName}</td>
                    <td>
                        <div class="case-badge ${getPriorityBadgeClass(testCase.priority)}">
                            ${getPriorityText(testCase.priority)}
                        </div>
                    </td>
                    <td>
                        <div class="case-badge ${getTypeBadgeClass(testCase.caseType)}">
                            ${getTypeText(testCase.caseType)}
                        </div>
                    </td>
                    <td>
                        <div class="case-badge ${getStatusBadgeClass(testCase.status)}">
                            ${getStatusText(testCase.status)}
                        </div>
                    </td>
                    <td>${testCase.creator}</td>
                    <td>${testCase.createTime}</td>
                    <td>
                        <div class="action-cell">
                            <div class="action-icon view-icon" data-id="${testCase.id}" title="查看">
                                <i class="fas fa-eye"></i>
                            </div>
                            <div class="action-icon edit-icon" data-id="${testCase.id}" title="编辑">
                                <i class="fas fa-edit"></i>
                            </div>
                            <div class="action-icon delete-icon" data-id="${testCase.id}" title="删除">
                                <i class="fas fa-trash"></i>
                            </div>
                        </div>
                    </td>
                `;

                testCasesTableBody.appendChild(row);
            });

            // 添加事件监听
            document.querySelectorAll('.view-icon').forEach(icon => {
                icon.addEventListener('click', (e) => {
                    const testCaseId = parseInt(e.currentTarget.dataset.id);
                    viewTestCase(testCaseId);
                });
            });

            document.querySelectorAll('.edit-icon').forEach(icon => {
                icon.addEventListener('click', (e) => {
                    const testCaseId = parseInt(e.currentTarget.dataset.id);
                    editTestCase(testCaseId);
                });
            });

            document.querySelectorAll('.delete-icon').forEach(icon => {
                icon.addEventListener('click', (e) => {
                    const testCaseId = parseInt(e.currentTarget.dataset.id);
                    deleteTestCase(testCaseId);
                });
            });
        }

        // 初始化分页
        function initPagination() {
            paginationContainer.innerHTML = '';

            if (currentFilteredData.length <= itemsPerPage) {
                return;
            }

            $('#paginationContainer').pagination({
                dataSource: currentFilteredData,
                pageSize: itemsPerPage,
                pageNumber: currentPage,
                callback: function(data, pagination) {
                    currentPage = pagination.pageNumber;
                    renderTestCasesTable(currentFilteredData);
                },
                className: 'paginationjs-theme-blue'
            });
        }

        // 查看测试用例
        function viewTestCase(testCaseId) {
            const testCase = testCasesData.find(tc => tc.id === testCaseId);
            if (!testCase) return;

            // 这里可以打开一个查看详情的模态框
            alert(`查看测试用例: ${testCase.caseName}\n编号: ${testCase.caseCode}\n描述: ${testCase.description}`);
        }

        // 打开添加测试用例模态框
        function openAddTestCaseModal() {
            isEditing = false;
