        // 获取优先级徽章类
        function getPriorityBadgeClass(priority) {
            switch(priority) {
                case 'high': return 'badge-high';
                case 'medium': return 'badge-medium';
                case 'low': return 'badge-low';
                default: return '';
            }
        }

        // 获取优先级文本
        function getPriorityText(priority) {
            switch(priority) {
                case 'high': return '高';
                case 'medium': return '中';
                case 'low': return '低';
                default: return priority;
            }
        }

        // 获取类型徽章类
        function getTypeBadgeClass(type) {
            switch(type) {
                case 'functional': return 'badge-functional';
                case 'performance': return 'badge-performance';
                case 'security': return 'badge-security';
                case 'compatibility': return 'badge-functional';
                default: return '';
            }
        }

        // 获取类型文本
        function getTypeText(type) {
            switch(type) {
                case 'functional': return '功能测试';
                case 'performance': return '性能测试';
                case 'security': return '安全测试';
                case 'compatibility': return '兼容性测试';
                case 'regression': return '回归测试';
                default: return type;
            }
        }

        // 获取状态徽章类
        function getStatusBadgeClass(status) {
            switch(status) {
                case 'draft': return 'badge-draft';
                case 'reviewing': return 'badge-warning';
                case 'reviewed': return 'badge-reviewed';
                case 'archived': return 'badge-archived';
                default: return '';
            }
        }

        // 获取状态文本
        function getStatusText(status) {
            switch(status) {
                case 'draft': return '草稿';
                case 'reviewing': return '评审中';
                case 'reviewed': return '已评审';
                case 'archived': return '已归档';
                default: return status;
            }
        }

        // 应用筛选条件
        function applyFilters() {
            const priority = priorityFilter.value;
            const type = typeFilter.value;
            const status = statusFilter.value;
            const searchText = searchInput.value.toLowerCase();

            currentFilteredData = testCasesData.filter(testCase => {
                // 优先级筛选
                if (priority && testCase.priority !== priority) return false;

                // 类型筛选
                if (type && testCase.caseType !== type) return false;

                // 状态筛选
                if (status && testCase.status !== status) return false;

                // 搜索筛选
                if (searchText) {
                    const searchFields = [
                        testCase.caseCode,
                        testCase.caseName,
                        testCase.description,
                        testCase.module,
                        testCase.creator
                    ];

                    const hasMatch = searchFields.some(field => 
                        field && field.toLowerCase().includes(searchText)
                    );

                    if (!hasMatch) return false;
                }

                return true;
            });

            // 重置到第一页
            currentPage = 1;

            // 重新渲染表格和分页
            renderTestCasesTable();
            renderPagination();
        }

        // 渲染测试用例表格
        function renderTestCasesTable() {
            if (currentFilteredData.length === 0) {
                emptyState.style.display = 'block';
                testCasesTableBody.innerHTML = '';
                paginationContainer.innerHTML = '';
                return;
            }

            emptyState.style.display = 'none';

            // 计算当前页的数据
            totalPages = Math.ceil(currentFilteredData.length / itemsPerPage);
            const startIndex = (currentPage - 1) * itemsPerPage;
            const endIndex = Math.min(startIndex + itemsPerPage, currentFilteredData.length);
            const pageData = currentFilteredData.slice(startIndex, endIndex);

            testCasesTableBody.innerHTML = '';

            pageData.forEach(testCase => {
                const row = document.createElement('tr');
                row.innerHTML = `
                    <td>${testCase.caseCode}</td>
                    <td>${testCase.caseName}</td>
                    <td>
                        <div class="case-badge ${getPriorityBadgeClass(testCase.priority)}">
                            ${getPriorityText(testCase.priority)}
                        </div>
                    </td>
                    <td>
                        <div class="case-badge ${getTypeBadgeClass(testCase.caseType)}">
                            ${getTypeText(testCase.caseType)}
                        </div>
                    </td>
                    <td>
                        <div class="case-badge ${getStatusBadgeClass(testCase.status)}">
                            ${getStatusText(testCase.status)}
                        </div>
                    </td>
                    <td>${testCase.creator}</td>
                    <td>${testCase.createTime}</td>
                    <td>
                        <div class="action-cell">
                            <div class="action-icon view-icon" data-id="${testCase.id}" title="查看">
                                <i class="fas fa-eye"></i>
                            </div>
                            <div class="action-icon edit-icon" data-id="${testCase.id}" title="编辑">
                                <i class="fas fa-edit"></i>
                            </div>
                            <div class="action-icon delete-icon" data-id="${testCase.id}" title="删除">
                                <i class="fas fa-trash"></i>
                            </div>
                        </div>
                    </td>
                `;

                testCasesTableBody.appendChild(row);
            });

            // 添加事件监听
            document.querySelectorAll('.view-icon').forEach(icon => {
                icon.addEventListener('click', (e) => {
                    const testCaseId = parseInt(e.currentTarget.dataset.id);
                    viewTestCase(testCaseId);
                });
            });

            document.querySelectorAll('.edit-icon').forEach(icon => {
                icon.addEventListener('click', (e) => {
                    const testCaseId = parseInt(e.currentTarget.dataset.id);
                    editTestCase(testCaseId);
                });
            });

            document.querySelectorAll('.delete-icon').forEach(icon => {
                icon.addEventListener('click', (e) => {
                    const testCaseId = parseInt(e.currentTarget.dataset.id);
                    deleteTestCase(testCaseId);
                });
            });
        }

        // 渲染分页
        function renderPagination() {
            paginationContainer.innerHTML = '';

            if (currentFilteredData.length <= itemsPerPage) {
                // 如果数据量小于等于每页显示数量，不显示分页
                return;
            }

            const pagination = document.createElement('ul');
            pagination.className = 'pagination';

            // 添加上一页按钮
            const prevLi = document.createElement('li');
            prevLi.className = `pagination-item ${currentPage === 1 ? 'disabled' : ''}`;
            prevLi.innerHTML = `<a class="pagination-link" href="#" data-page="${currentPage - 1}"><i class="fas fa-chevron-left"></i></a>`;
            pagination.appendChild(prevLi);

            // 计算页码范围
            let startPage = Math.max(1, currentPage - 2);
            let endPage = Math.min(totalPages, startPage + 4);

            // 调整起始页，确保显示5个页码
            if (endPage - startPage < 4) {
                startPage = Math.max(1, endPage - 4);
            }

            // 添加第一页和省略号
            if (startPage > 1) {
                const firstLi = document.createElement('li');
                firstLi.className = 'pagination-item';
                firstLi.innerHTML = `<a class="pagination-link" href="#" data-page="1">1</a>`;
                pagination.appendChild(firstLi);

                if (startPage > 2) {
                    const ellipsisLi = document.createElement('li');
                    ellipsisLi.className = 'pagination-item';
                    ellipsisLi.innerHTML = `<span class="pagination-ellipsis">...</span>`;
                    pagination.appendChild(ellipsisLi);
                }
            }

            // 添加页码
            for (let i = startPage; i <= endPage; i++) {
                const pageLi = document.createElement('li');
                pageLi.className = `pagination-item ${i === currentPage ? 'active' : ''}`;
                pageLi.innerHTML = `<a class="pagination-link" href="#" data-page="${i}">${i}</a>`;
                pagination.appendChild(pageLi);
            }

            // 添加最后一页和省略号
            if (endPage < totalPages) {
                if (endPage < totalPages - 1) {
                    const ellipsisLi = document.createElement('li');
                    ellipsisLi.className = 'pagination-item';
                    ellipsisLi.innerHTML = `<span class="pagination-ellipsis">...</span>`;
                    pagination.appendChild(ellipsisLi);
                }

                const lastLi = document.createElement('li');
                lastLi.className = 'pagination-item';
                lastLi.innerHTML = `<a class="pagination-link" href="#" data-page="${totalPages}">${totalPages}</a>`;
                pagination.appendChild(lastLi);
            }

            // 添加下一页按钮
            const nextLi = document.createElement('li');
            nextLi.className = `pagination-item ${currentPage === totalPages ? 'disabled' : ''}`;
            nextLi.innerHTML = `<a class="pagination-link" href="#" data-page="${currentPage + 1}"><i class="fas fa-chevron-right"></i></a>`;
            pagination.appendChild(nextLi);

            paginationContainer.appendChild(pagination);

            // 添加分页点击事件
            pagination.addEventListener('click', (e) => {
                e.preventDefault();
                if (e.target.classList.contains('pagination-link') || e.target.parentElement.classList.contains('pagination-link')) {
                    const link = e.target.classList.contains('pagination-link') ? e.target : e.target.parentElement;
                    const page = parseInt(link.dataset.page);

                    if (page && page !== currentPage && page >= 1 && page <= totalPages) {
                        currentPage = page;
                        renderTestCasesTable();
                        renderPagination();

                        // 滚动到表格顶部
                        document.querySelector('.table-container').scrollIntoView({ behavior: 'smooth' });
                    }
                }
            });

            // 显示总条数和当前页信息
            const infoDiv = document.createElement('div');
            infoDiv.style.marginLeft = '20px';
            infoDiv.style.fontSize = '14px';
            infoDiv.style.color = '#666';
            infoDiv.innerHTML = `共 ${currentFilteredData.length} 条记录，当前显示第 ${startIndex + 1} - ${endIndex} 条`;
            paginationContainer.appendChild(infoDiv);
        }

