            // 这里可以打开一个查看详情的模态框
            alert(`查看测试用例: ${testCase.caseName}\n编号: ${testCase.caseCode}\n描述: ${testCase.description}`);
        }

        // 打开添加测试用例模态框
        function openAddTestCaseModal() {
            isEditing = false;
            editingTestCaseId = null;
            modalTitle.textContent = '创建测试用例';
