        // 编辑测试用例
        function editTestCase(testCaseId) {
            const testCase = testCasesData.find(tc => tc.id === testCaseId);
            if (!testCase) return;

            isEditing = true;
            editingTestCaseId = testCaseId;
            modalTitle.textContent = '编辑测试用例';

            // 填充表单
            caseCodeInput.value = testCase.caseCode;
            caseNameInput.value = testCase.caseName;
            prioritySelect.value = testCase.priority;
            caseTypeSelect.value = testCase.caseType;
            projectSelect.value = testCase.project;
            moduleInput.value = testCase.module || '';
            descriptionInput.value = testCase.description || '';
            preconditionInput.value = testCase.precondition || '';
            expectedResultInput.value = testCase.expectedResult || '';

            // 清空步骤表格并添加示例步骤
            stepsTableBody.innerHTML = '';
            addStepRow('1', '输入正确的用户名和密码', '成功登录系统，跳转到主页');
            addStepRow('2', '输入错误的密码', '显示密码错误提示信息');

            // 清除所有复选框的选中状态
            document.querySelectorAll('input[type="checkbox"]').forEach(checkbox => {
                checkbox.checked = false;
            });

            // 根据标签选中复选框
            if (testCase.tags && testCase.tags.length > 0) {
                testCase.tags.forEach(tag => {
                    const checkboxId = tag === '登录' ? 'tagLogin' :
                                     tag === '安全' ? 'tagSecurity' :
                                     tag === '兼容性' ? 'tagCompatibility' :
                                     tag === '性能' ? 'tagPerformance' :
                                     tag === '回归测试' ? 'tagRegression' : '';

                    if (checkboxId) {
                        document.getElementById(checkboxId).checked = true;
                    }
                });
            }

            testCaseModal.classList.add('active');
        }

        // 添加步骤行
        function addStepRow(stepNumber = '', description = '', expectedResult = '') {
            const rowCount = stepsTableBody.children.length;
            const stepNum = stepNumber || (rowCount + 1).toString();

            const row = document.createElement('tr');
            row.innerHTML = `
                <td><input type="text" class="form-control" value="${stepNum}" style="width: 60px;"></td>
                <td><textarea class="form-control" rows="2">${description}</textarea></td>
                <td><textarea class="form-control" rows="2">${expectedResult}</textarea></td>
                <td>
                    <div class="step-actions">
                        <button class="step-action-btn up-btn" title="上移">
                            <i class="fas fa-arrow-up"></i>
                        </button>
                        <button class="step-action-btn down-btn" title="下移">
                            <i class="fas fa-arrow-down"></i>
                        </button>
                        <button class="step-action-btn delete" title="删除">
                            <i class="fas fa-trash"></i>
                        </button>
                    </div>
                </td>
            `;

            stepsTableBody.appendChild(row);

            // 添加事件监听
            const upBtn = row.querySelector('.up-btn');
            const downBtn = row.querySelector('.down-btn');
            const deleteBtn = row.querySelector('.delete');

            upBtn.addEventListener('click', () => moveStep(row, -1));
            downBtn.addEventListener('click', () => moveStep(row, 1));
            deleteBtn.addEventListener('click', () => row.remove());
        }

        // 移动步骤
        function moveStep(row, direction) {
            const rows = Array.from(stepsTableBody.children);
            const currentIndex = rows.indexOf(row);
            const newIndex = currentIndex + direction;

            if (newIndex >= 0 && newIndex < rows.length) {
                if (direction === -1) {
                    stepsTableBody.insertBefore(row, rows[newIndex]);
                } else {
                    stepsTableBody.insertBefore(rows[newIndex + 1], row);
                }

                // 更新步骤序号
                updateStepNumbers();
            }
        }

        // 更新步骤序号
        function updateStepNumbers() {
            const rows = stepsTableBody.children;
            for (let i = 0; i < rows.length; i++) {
                const stepInput = rows[i].querySelector('input[type="text"]');
                stepInput.value = (i + 1).toString();
            }
        }

        // 删除测试用例
        function deleteTestCase(testCaseId) {
            if (confirm('确定要删除这个测试用例吗？此操作不可恢复。')) {
                testCasesData = testCasesData.filter(testCase => testCase.id !== testCaseId);
                applyFilters();
                showNotification('测试用例删除成功', 'success');
            }
        }

        // 保存测试用例
        function saveTestCase() {
            const caseCode = caseCodeInput.value.trim();
            const caseName = caseNameInput.value.trim();
            const priority = prioritySelect.value;
            const caseType = caseTypeSelect.value;
            const project = projectSelect.value;
            const module = moduleInput.value.trim();
            const description = descriptionInput.value.trim();
            const precondition = preconditionInput.value.trim();
            const expectedResult = expectedResultInput.value.trim();

            if (!caseCode || !caseName || !priority || !caseType || !project) {
                alert('请填写所有必填字段（标记为*）');
                return;
            }

            // 收集标签
            const selectedTags = [];
            document.querySelectorAll('input[type="checkbox"]:checked').forEach(checkbox => {
                if (checkbox.id.startsWith('tag')) {
                    selectedTags.push(checkbox.value);
                }
            });

            // 收集步骤
            const steps = [];
            const stepRows = stepsTableBody.children;
            for (let i = 0; i < stepRows.length; i++) {
                const stepInput = stepRows[i].querySelector('input[type="text"]');
                const descTextarea = stepRows[i].querySelector('textarea:nth-of-type(1)');
                const resultTextarea = stepRows[i].querySelector('textarea:nth-of-type(2)');

                const step = {
                    stepNumber: stepInput.value,
                    description: descTextarea.value,
                    expectedResult: resultTextarea.value
                };

                steps.push(step);
            }

            if (isEditing) {
                // 更新现有测试用例
                const testCaseIndex = testCasesData.findIndex(tc => tc.id === editingTestCaseId);
                if (testCaseIndex !== -1) {
                    testCasesData[testCaseIndex] = {
                        ...testCasesData[testCaseIndex],
                        caseCode,
                        caseName,
                        priority,
                        caseType,
                        project,
                        module,
                        description,
                        precondition,
                        expectedResult,
                        steps,
                        tags: selectedTags,
                        // 模拟更新时间和更新人
                        updateTime: new Date().toISOString().slice(0, 19).replace('T', ' '),
                        updater: '当前用户'
                    };
                }
                showNotification('测试用例更新成功', 'success');
            } else {
                // 添加新测试用例
                const newTestCase = {
                    id: testCasesData.length > 0 ? Math.max(...testCasesData.map(tc => tc.id)) + 1 : 1,
                    caseCode,
                    caseName,
                    priority,
                    caseType,
                    status: 'draft',
                    creator: '当前用户',
                    createTime: new Date().toISOString().slice(0, 19).replace('T', ' '),
                    project,
                    module,
                    description,
                    precondition,
                    expectedResult,
                    steps,
                    tags: selectedTags
                };
                testCasesData.push(newTestCase);
                showNotification('测试用例创建成功', 'success');
            }

            applyFilters();
            closeTestCaseModal();
        }

