                        <div class="trigger-type-desc">通过Webhook或API自定义触发规则</div>
                    </div>
                </div>
            </div>

            <!-- 自动化触发模块 -->
            <div class="module-card" id="autoTriggerCard">
                <div class="module-header">
                    <div>
                        <div class="module-title">自动化触发规则管理</div>
                        <div class="module-subtitle">配置代码提交后自动创建关联的测试任务，支持多种触发条件和规则</div>
                    </div>
                    <div class="action-buttons">
                        <button class="btn btn-primary" id="addTriggerBtn">
