                    this.classList.add('active');

                    const intersectionName = this.querySelector('.intersection-name').textContent;
                    document.querySelector('.map-title').textContent = `路口二维地图展示 - ${intersectionName}`;
                });
            });

            // 设备列表项点击
            const deviceItems = document.querySelectorAll('.device-item');
            deviceItems.forEach(item => {
                item.addEventListener('click', function() {
                    const deviceId = this.getAttribute('data-device');
                    showDeviceDetail(deviceId);

                    // 高亮对应的设备标记
                    const deviceMarker = document.querySelector(`.device-marker[data-device="${deviceId}"]`);
                    if (deviceMarker) {
                        // 临时高亮效果
                        const originalColor = deviceMarker.style.backgroundColor;
                        deviceMarker.style.boxShadow = '0 0 0 3px rgba(24, 144, 255, 0.5)';
                        setTimeout(() => {
                            deviceMarker.style.boxShadow = '0 2px 6px rgba(0, 0, 0, 0.3)';
                        }, 1000);
                    }
                });
            });

            // 设备标记点击
            const deviceMarkers = document.querySelectorAll('.device-marker');
            deviceMarkers.forEach(marker => {
                marker.addEventListener('click', function() {
                    const deviceId = this.getAttribute('data-device');
                    showDeviceDetail(deviceId);

                    // 高亮当前标记
                    deviceMarkers.forEach(m => m.style.boxShadow = '0 2px 6px rgba(0, 0, 0, 0.3)');
                    this.style.boxShadow = '0 0 0 3px rgba(24, 144, 255, 0.5)';
                });
            });

            // 地图控制按钮
            const mapControlBtns = document.querySelectorAll('.map-control-btn');
            mapControlBtns.forEach(btn => {
                btn.addEventListener('click', function() {
                    const btnText = this.textContent.trim();
                    if (btnText.includes('刷新数据')) {
                        // 模拟数据刷新
                        const statValues = document.querySelectorAll('.stat-value');
                        if (statValues[1].textContent === '22') {
                            statValues[1].textContent = '23';
                        } else {
                            statValues[1].textContent = '22';
                        }

                        // 随机更新延迟
                        const delays = ['38ms', '42ms', '35ms', '40ms'];
                        statValues[3].textContent = delays[Math.floor(Math.random() * delays.length)];

                        alert('数据已刷新');
                    } else if (btnText.includes('导出图片')) {
                        alert('路口地图已导出为PNG图片');
                    } else if (btnText.includes('设置')) {
                        alert('打开地图设置面板');
                    }
                });
            });

            // 图层控制
            const layerCheckboxes = document.querySelectorAll('.layer-checkbox');
            layerCheckboxes.forEach(checkbox => {
                checkbox.addEventListener('change', function() {
                    const layerName = this.parentElement.querySelector('.layer-name').textContent;
                    if (this.checked) {
                        console.log(`显示 ${layerName} 图层`);
                    } else {
                        console.log(`隐藏 ${layerName} 图层`);
                    }
                });
            });
        });

        // 显示设备详情
        function showDeviceDetail(deviceId) {
            const device = devices[deviceId];
            if (!device) return;

            const detailElement = document.getElementById('deviceDetail');
            detailElement.innerHTML = `
                <h4><i class="fas fa-microchip"></i> 设备详情</h4>
                <div class="detail-row">
