                    <div class="detail-value">
                        <span style="color: ${device.status === '在线' ? '#52c41a' : device.status === '警告' ? '#faad14' : '#ff4d4f'}; font-weight: bold;">
                            ${device.status}
                        </span>
                    </div>
                </div>
                <div class="detail-row">
                    <div class="detail-label">安装位置:</div>
                    <div class="detail-value">${device.location}</div>
                </div>
                <div class="detail-row">
