    <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
    <script>
        // 初始化地图
        let map;
        let markers = [];
        let isMeasuring = false;
        let isDrawing = false;

        // 初始化侧边栏状态
        let sidebarCollapsed = false;

        // 初始化页面
        document.addEventListener('DOMContentLoaded', function() {
            initMap();
            initSidebar();
            initEventListeners();
        });

        // 初始化地图
        function initMap() {
            map = L.map('map').setView([31.2304, 121.4737], 15); // 上海坐标

            // 添加地图图层
            L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
                attribution: '© OpenStreetMap contributors',
                maxZoom: 19
            }).addTo(map);

            // 添加设备标记
            addDeviceMarkers();

            // 绘制路口区域和车道线
            drawIntersectionElements();
        }

        // 初始化侧边栏
        function initSidebar() {
            const sidebarToggle = document.getElementById('sidebarToggle');
            const sidebar = document.getElementById('sidebar');

            sidebarToggle.addEventListener('click', function() {
                sidebar.classList.toggle('collapsed');
                sidebarCollapsed = !sidebarCollapsed;

                // 更新切换图标方向
                const icon = sidebarToggle.querySelector('i');
                if (sidebarCollapsed) {
                    icon.className = 'fas fa-chevron-right';
                } else {
                    icon.className = 'fas fa-chevron-left';
                }
            });

            // 默认展开第一个目录
            toggleSection('digitalTwin');
        }

        // 初始化事件监听器
        function initEventListeners() {
            // CAD上传按钮
            document.getElementById('uploadCadBtn').addEventListener('click', function() {
                document.getElementById('cadUploadPanel').style.display = 'block';
            });

            // 图层控制按钮
            document.getElementById('layerControlBtn').addEventListener('click', toggleLayerControl);

            // 设备筛选按钮
            document.getElementById('deviceFilterBtn').addEventListener('click', function() {
                alert('设备筛选功能正在开发中...');
            });

            // 拖放文件上传
            const dropArea = document.getElementById('dropArea');
            dropArea.addEventListener('dragover', function(e) {
                e.preventDefault();
                dropArea.style.borderColor = '#1890ff';
                dropArea.style.backgroundColor = '#f0f9ff';
            });

            dropArea.addEventListener('dragleave', function(e) {
                e.preventDefault();
                dropArea.style.borderColor = '#d9d9d9';
                dropArea.style.backgroundColor = '';
            });

            dropArea.addEventListener('drop', function(e) {
                e.preventDefault();
                dropArea.style.borderColor = '#d9d9d9';
                dropArea.style.backgroundColor = '';

                const files = e.dataTransfer.files;
                if (files.length > 0) {
                    handleCadFile(files[0]);
                }
            });
        }

        // 切换目录展开/收起
        function toggleSection(sectionId) {
            const submenu = document.getElementById(sectionId + 'Submenu');
            if (submenu) {
                submenu.classList.toggle('expanded');

                // 更新图标
                const icon = document.querySelector(`[onclick="toggleSection('${sectionId}')"] .collapse-icon`);
                if (submenu.classList.contains('expanded')) {
                    icon.className = 'fas fa-chevron-down collapse-icon';
                } else {
                    icon.className = 'fas fa-chevron-right collapse-icon';
                }
            }
        }

        // 选择主菜单项
        function selectMenuItem(element, pageId) {
            // 移除所有active类
            document.querySelectorAll('.nav-item.active').forEach(el => {
                el.classList.remove('active');
            });

            // 为当前项添加active类
            element.classList.add('active');

            // 切换页面内容（模拟）
            switchPage(pageId);
        }

        // 选择子菜单项
        function selectSubItem(element, pageId) {
            // 移除所有active类
            document.querySelectorAll('.nav-subitem.active').forEach(el => {
                el.classList.remove('active');
            });

            // 为当前项添加active类
            element.classList.add('active');

            // 切换页面内容（模拟）
            switchPage(pageId);
        }

        // 切换页面（模拟）
        function switchPage(pageId) {
            const pageTitle = document.querySelector('.page-title');
            const pageSubtitle = document.querySelector('.page-subtitle');

            switch(pageId) {
                case '2d-map':
                    pageTitle.textContent = '二维地图展示';
                    pageSubtitle.textContent = '路口平面图与设备定位 - 基于OpenHarmony生态的数字孪生可视化';
                    break;
                case 'device-elements':
                    pageTitle.textContent = '设备要素';
                    pageSubtitle.textContent = '车道、人行横道、信号灯、摄像头等要素标注与管理';
                    break;
                case 'device-map':
                    pageTitle.textContent = '设备地图';
                    pageSubtitle.textContent = '设备分布地图与状态监控';
                    break;
                default:
                    pageTitle.textContent = '二维地图展示';
                    pageSubtitle.textContent = '路口平面图与设备定位 - 基于OpenHarmony生态的数字孪生可视化';
            }

            // 在实际应用中，这里会加载对应的页面内容
            console.log('切换到页面:', pageId);
        }

        // 添加设备标记到地图
        function addDeviceMarkers() {
            // 自定义图标
            const trafficLightIcon = L.divIcon({
                html: '<div style="background-color: #52c41a; width: 24px; height: 24px; border-radius: 50%; display: flex; align-items: center; justify-content: center; color: white; font-size: 12px;"><i class="fas fa-traffic-light"></i></div>',
                className: 'custom-marker',
                iconSize: [24, 24],
                iconAnchor: [12, 12]
            });

            const cameraIcon = L.divIcon({
                html: '<div style="background-color: #1890ff; width: 24px; height: 24px; border-radius: 50%; display: flex; align-items: center; justify-content: center; color: white; font-size: 12px;"><i class="fas fa-video"></i></div>',
                className: 'custom-marker',
                iconSize: [24, 24],
                iconAnchor: [12, 12]
            });

            const radarIcon = L.divIcon({
                html: '<div style="background-color: #fa8c16; width: 24px; height: 24px; border-radius: 50%; display: flex; align-items: center; justify-content: center; color: white; font-size: 12px;"><i class="fas fa-satellite-dish"></i></div>',
                className: 'custom-marker',
                iconSize: [24, 24],
                iconAnchor: [12, 12]
            });

            const edgeIcon = L.divIcon({
                html: '<div style="background-color: #722ed1; width: 24px; height: 24px; border-radius: 50%; display: flex; align-items: center; justify-content: center; color: white; font-size: 12px;"><i class="fas fa-server"></i></div>',
                className: 'custom-marker',
                iconSize: [24, 24],
                iconAnchor: [12, 12]
            });

            // 设备数据
            const devices = [
                {
                    name: "交通信号灯-01",
                    type: "鸿蒙信号灯",
                    status: "online",
                    lat: 31.231,
                    lng: 121.474,
                    icon: trafficLightIcon,
                    details: "设备ID: TL-001-2025<br>厂商: 佳都科技<br>固件版本: V2.3.1<br>最后心跳: 2025-03-15 14:30:22"
                },
                {
                    name: "智能摄像机-03",
                    type: "鸿蒙摄像头",
                    status: "online",
                    lat: 31.2302,
                    lng: 121.475,
                    icon: cameraIcon,
                    details: "设备ID: CAM-003-2025<br>厂商: 海康威视<br>视频流: RTSP/H.264<br>分辨率: 1920×1080"
                },
                {
                    name: "雷视一体机-01",
                    type: "鸿蒙雷视一体机",
                    status: "warning",
                    lat: 31.2305,
                    lng: 121.4735,
                    icon: radarIcon,
                    details: "设备ID: RV-001-2025<br>厂商: 佳都科技<br>状态: 信号弱<br>检测范围: 200米"
                },
                {
                    name: "边缘计算盒子-01",
                    type: "OpenHarmony边缘计算盒子",
                    status: "online",
                    lat: 31.2298,
                    lng: 121.4745,
                    icon: edgeIcon,
                    details: "设备ID: EC-001-2025<br>芯片: 鲲鹏920<br>内存: 8GB<br>存储: 256GB SSD"
                },
                {
                    name: "信号灯控制器-02",
                    type: "老旧信号控制器",
                    status: "offline",
                    lat: 31.2308,
                    lng: 121.4728,
                    icon: trafficLightIcon,
                    details: "设备ID: SLC-002-2018<br>厂商: 传统设备<br>状态: 离线<br>最后在线: 2025-03-14 22:15:10"
                },
                {
                    name: "环境监测传感器-01",
                    type: "标准传感器",
                    status: "online",
                    lat: 31.2295,
                    lng: 121.4732,
                    icon: edgeIcon,
                    details: "设备ID: SENSOR-001-2024<br>监测: PM2.5, 温湿度<br>通信: MQTT<br>电池: 85%"
                }
            ];

            // 在地图上添加设备标记
            devices.forEach(device => {
                const marker = L.marker([device.lat, device.lng], { icon: device.icon })
                    .addTo(map)
                    .bindPopup(`
                        <div class="marker-popup">
                            <div class="popup-title">${device.name}</div>
                            <div class="popup-info">类型: ${device.type}</div>
                            <div class="popup-info">位置: 路口A</div>
                            <div class="popup-info">${device.details}</div>
                            <div class="popup-status ${device.status === 'online' ? 'status-online' : device.status === 'offline' ? 'status-offline' : 'status-warning'}">
                                ${device.status === 'online' ? '在线' : device.status === 'offline' ? '离线' : '警告'}
                            </div>
                        </div>
                    `);

                markers.push(marker);
            });
        }

        // 绘制路口区域和车道线
        function drawIntersectionElements() {
            // 绘制路口区域（示例）
            const intersectionBounds = [
                [31.2308, 121.4725],
                [31.2308, 121.4755],
                [31.2295, 121.4755],
                [31.2295, 121.4725]
            ];

            const intersectionArea = L.polygon(intersectionBounds, {
                color: '#1890ff',
                weight: 2,
                fillColor: '#e6f7ff',
                fillOpacity: 0.2
            }).addTo(map);

            // 绘制车道线（示例）
            const laneLines = [
                [[31.2306, 121.473], [31.2306, 121.4745]],
                [[31.2302, 121.473], [31.2302, 121.4745]],
                [[31.2304, 121.4735], [31.2297, 121.4735]],
                [[31.2304, 121.474], [31.2297, 121.474]]
            ];

            laneLines.forEach(line => {
                L.polyline(line, {
                    color: '#8c8c8c',
                    weight: 2,
                    dashArray: '5, 5'
                }).addTo(map);
            });

            // 绘制人行横道（示例）
            const crosswalk = L.polygon([
                [31.2305, 121.4738],
                [31.2305, 121.474],
                [31.2303, 121.474],
                [31.2303, 121.4738]
            ], {
                color: '#4ECDC4',
                weight: 1,
                fillColor: '#4ECDC4',
                fillOpacity: 0.5
            }).addTo(map);

            // 添加路口名称标注
            L.marker([31.2302, 121.4742], {
                icon: L.divIcon({
                    html: '<div style="background-color: rgba(255, 255, 255, 0.9); padding: 5px 10px; border-radius: 4px; border: 1px solid #1890ff; font-weight: bold; color: #1890ff;">路口A</div>',
                    className: 'intersection-label',
                    iconSize: [60, 30],
                    iconAnchor: [30, 15]
                })
            }).addTo(map);
        }

        // 重置地图视图
        function resetMapView() {
            map.setView([31.2304, 121.4737], 15);
        }

        // 切换测距工具
        function toggleMeasureTool() {
            isMeasuring = !isMeasuring;
            if (isMeasuring) {
                alert('测距工具已激活，点击地图两点测量距离');
                // 在实际应用中，这里会激活Leaflet的测距插件
            } else {
                alert('测距工具已关闭');
            }
        }

        // 切换绘制工具
        function toggleDrawTool() {
            isDrawing = !isDrawing;
            if (isDrawing) {
                alert('绘制工具已激活，可绘制车道、人行横道等要素');
                // 在实际应用中，这里会激活Leaflet的绘制插件
            } else {
                alert('绘制工具已关闭');
            }
        }

        // 切换图层控制面板
        function toggleLayerControl() {
            const layerPanel = document.getElementById('layerControlPanel');
            if (layerPanel.style.display === 'none') {
                layerPanel.style.display = 'block';
            } else {
                layerPanel.style.display = 'none';
            }
        }

        // 关闭CAD上传面板
        function closeUploadPanel() {
            document.getElementById('cadUploadPanel').style.display = 'none';
        }

        // 处理CAD文件选择
        function handleCadFileSelect(event) {
            const file = event.target.files[0];
            if (file) {
                handleCadFile(file);
            }
        }

        // 处理CAD文件
        function handleCadFile(file) {
            const fileName = file.name;
            const fileSize = (file.size / (1024 * 1024)).toFixed(2); // MB

            // 检查文件格式
            const validExtensions = ['.dwg', '.dxf'];
            const fileExt = fileName.substring(fileName.lastIndexOf('.')).toLowerCase();

            if (!validExtensions.includes(fileExt)) {
                alert('错误：只支持DWG和DXF格式的文件！');
                return;
            }

            // 检查文件大小
            if (fileSize > 100) {
                alert('错误：文件大小不能超过100MB！');
                return;
            }

            // 模拟上传和处理过程
            alert(`CAD文件 "${fileName}" (${fileSize}MB) 已上传，正在解析...`);

            // 模拟解析完成
            setTimeout(() => {
                alert('CAD图纸解析完成！已在地图上生成路口平面图。');
                closeUploadPanel();

                // 模拟在地图上添加CAD解析结果
                simulateCadParsingResult();
            }, 2000);
        }

        // 模拟CAD解析结果
        function simulateCadParsingResult() {
            // 添加一些额外的元素来模拟CAD导入效果
            const cadElements = [
                {
                    type: 'lane',
                    coords: [[31.2305, 121.4727], [31.2305, 121.4733]]
                },
                {
                    type: 'crosswalk',
                    coords: [[31.2301, 121.4742], [31.2301, 121.4744], [31.2299, 121.4744], [31.2299, 121.4742]]
                },
                {
                    type: 'stop_line',
                    coords: [[31.2307, 121.4737], [31.2307, 121.4739]]
                }
            ];

            cadElements.forEach(element => {
                if (element.type === 'lane') {
                    L.polyline(element.coords, {
                        color: '#FF6B6B',
                        weight: 3,
                        opacity: 0.8
                    }).addTo(map).bindPopup('CAD导入: 车道线');
                } else if (element.type === 'crosswalk') {
                    L.polygon(element.coords, {
                        color: '#4ECDC4',
                        weight: 1,
                        fillColor: '#4ECDC4',
                        fillOpacity: 0.6
                    }).addTo(map).bindPopup('CAD导入: 人行横道');
                } else if (element.type === 'stop_line') {
                    L.polyline(element.coords, {
                        color: '#FECA57',
                        weight: 2,
                        dashArray: '10, 5'
                    }).addTo(map).bindPopup('CAD导入: 停止线');
                }
            });

            // 更新统计信息
            document.querySelector('.card:nth-child(1) .card-value').textContent = '25';
            document.querySelector('.card:nth-child(1) .card-label').textContent = '已接入系统的路口数量（含CAD导入）';
        }

        // 模拟设备状态更新
        function updateDeviceStatus() {
            const statusElements = document.querySelectorAll('.device-status');
            statusElements.forEach(el => {
                // 随机切换状态（仅演示）
                if (Math.random() > 0.7) {
                    const statuses = ['online', 'offline', 'warning'];
                    const newStatus = statuses[Math.floor(Math.random() * statuses.length)];
                    el.className = 'device-status ' + newStatus;
                }
            });

            // 更新卡片数据
            const onlineCount = Math.floor(Math.random() * 10) + 180;
            document.querySelector('.card:nth-child(2) .card-value').textContent = onlineCount;

            const videoCount = Math.floor(Math.random() * 5) + 40;
            document.querySelector('.card:nth-child(3) .card-value').textContent = videoCount;

            const alertCount = Math.floor(Math.random() * 5);
            document.querySelector('.card:nth-child(4) .card-value').textContent = alertCount;
        }

        // 每30秒更新一次设备状态
        setInterval(updateDeviceStatus, 30000);
    </script>
</body>
</html>
```

## 功能说明

这个二维地图展示页面实现了以下核心功能：

### 1. 侧边栏目录管理
- 支持展开/收起目录结构
- 点击侧边栏切换按钮可收缩/展开整个侧边栏
- 目录结构与提供的文档一致，包含5个主要功能模块
- 当前选中的菜单项高亮显示

### 2. 地图功能
- 使用Leaflet地图库显示OpenStreetMap地图
- 在地图上标注各类设备（信号灯、摄像头、雷视一体机等）
- 每个设备标记显示详细信息弹窗
- 绘制路口区域、车道线、人行横道等交通要素
- 提供地图控制工具：缩放、重置、测距、绘图等

### 3. 统计卡片
- 显示路口总数、在线设备数、正常视频通道数、当前告警数
- 数据会定时更新模拟实时状态

### 4. 设备管理面板
- 显示路口所有设备列表
- 设备状态通过颜色标识（绿-在线，红-离线，黄-警告）
- 鼠标悬停设备卡片有交互效果

### 5. CAD图纸导入
- 支持上传DWG/DXF格式的CAD图纸
- 拖放文件上传功能
- 文件格式和大小验证
- 模拟CAD解析并在地图上显示结果

### 6. 图层控制
- 控制地图上不同图层的显示/隐藏
- 包括交通信号灯、摄像头、雷视一体机、边缘计算设备等图层

页面整体风格与2.html保持一致，采用蓝色主题，响应式设计，支持桌面和移动设备浏览。所有功能都基于开源鸿蒙交通路口管理平台的实际需求设计，符合项目文档中描述的功能要求。

