                properties: {
                    cpuUsage: "45%",
                    memoryUsage: "3.2GB",
                    temperature: "42°C"
                }
            },
            {
                name: "信号灯控制器-02",
                type: "LEGACY_SIGNAL_CONTROLLER",
                status: "offline",
                lat: 31.2308,
                lng: 121.4728,
                icon: trafficLightIcon,
