            iconSize: [28, 28],
            iconAnchor: [14, 14]
        });

        const edgeIcon = L.divIcon({
            html: '<div style="background-color: #722ed1; width: 28px; height: 28px; border-radius: 50%; display: flex; align-items: center; justify-content: center; color: white; font-size: 14px;"><i class="fas fa-server"></i></div>',
            className: 'custom-marker',
            iconSize: [28, 28],
            iconAnchor: [14, 14]
        });

        // 添加设备标记
        const devices = [
            {
                name: "鸿蒙信号灯-01",
