            color: #fa8c16;
            border: 1px solid #ffd591;
        }

        .intersection-details {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 10px;
            margin-top: 10px;
        }

        .detail-item {
            display: flex;
            flex-direction: column;
            gap: 3px;
        }

        .detail-label {
            font-size: 0.8rem;
            color: #8c8c8c;
        }

        .detail-value {
            font-weight: 500;
            color: #262626;
        }

        .footer {
