            className: 'custom-marker',
            iconSize: [28, 28],
            iconAnchor: [14, 14]
        });

        // 设备数据
        const devices = [
            {
                name: "鸿蒙信号灯-01",
                type: "HARMONY_TRAFFIC_LIGHT",
                status: "online",
                lat: 31.231,
                lng: 121.474,
                icon: trafficLightIcon,
                details: "设备ID: TL-HARMONY-001<br>厂商: 佳都科技<br>固件版本: V2.3.1<br>最后心跳: 2025-03-15 14:30:22<br>平台类型: 鸿蒙设备",
                properties: {
                    phase: "相位1",
                    direction: "北进口",
                    color: "绿灯"
                }
            },
            {
                name: "智能摄像机-03",
                type: "HARMONY_CAMERA",
                status: "online",
                lat: 31.2302,
                lng: 121.475,
                icon: cameraIcon,
                details: "设备ID: CAM-003-2025<br>厂商: 海康威视<br>视频流: RTSP/H.264<br>分辨率: 1920×1080<br>平台类型: 鸿蒙设备",
                properties: {
                    angle: "45°",
                    zoom: "3x",
                    resolution: "1080p"
                }
            },
            {
                name: "雷视一体机-01",
                type: "HARMONY_RADAR",
                status: "warning",
                lat: 31.2305,
                lng: 121.4735,
                icon: radarIcon,
                details: "设备ID: RV-001-2025<br>厂商: 佳都科技<br>状态: 信号弱<br>检测范围: 200米<br>平台类型: 鸿蒙设备",
                properties: {
