    <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
    <script>
        // 初始化地图
        const map = L.map('map').setView([31.2304, 121.4737], 17); // 上海坐标

        // 添加地图图层
        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
            attribution: '© OpenStreetMap contributors'
        }).addTo(map);

        // 自定义图标
        const trafficLightIcon = L.divIcon({
            html: '<div style="background-color: #52c41a; width: 28px; height: 28px; border-radius: 50%; display: flex; align-items: center; justify-content: center; color: white; font-size: 14px;"><i class="fas fa-traffic-light"></i></div>',
            className: 'custom-marker',
            iconSize: [28, 28],
            iconAnchor: [14, 14]
        });

        const cameraIcon = L.divIcon({
            html: '<div style="background-color: #1890ff; width: 28px; height: 28px; border-radius: 50%; display: flex; align-items: center; justify-content: center; color: white; font-size: 14px;"><i class="fas fa-video"></i></div>',
            className: 'custom-marker',
            iconSize: [28, 28],
            iconAnchor: [14, 14]
        });

        const radarIcon = L.divIcon({
            html: '<div style="background-color: #fa8c16; width: 28px; height: 28px; border-radius: 50%; display: flex; align-items: center; justify-content: center; color: white; font-size: 14px;"><i class="fas fa-satellite-dish"></i></div>',
            className: 'custom-marker',
            iconSize: [28, 28],
            iconAnchor: [14, 14]
        });

        const edgeIcon = L.divIcon({
            html: '<div style="background-color: #722ed1; width: 28px; height: 28px; border-radius: 50%; display: flex; align-items: center; justify-content: center; color: white; font-size: 14px;"><i class="fas fa-server"></i></div>',
            className: 'custom-marker',
            iconSize: [28, 28],
            iconAnchor: [14, 14]
        });

        // 添加设备标记
        const devices = [
            {
                name: "鸿蒙信号灯-01",
                type: "HARMONY_TRAFFIC_LIGHT",
                status: "online",
                lat: 31.231,
                lng: 121.474,
                icon: trafficLightIcon,
                details: "设备ID: TL-HARMONY-001<br>厂商: 佳都科技<br>固件版本: V2.3.1<br>最后心跳: 2025-03-15 14:30:22<br>平台类型: 鸿蒙设备",
                properties: {
                    phase: "相位1",
                    direction: "北进口",
                    color: "绿灯"
                }
            },
            {
                name: "智能摄像机-03",
                type: "HARMONY_CAMERA",
                status: "online",
                lat: 31.2302,
                lng: 121.475,
                icon: cameraIcon,
                details: "设备ID: CAM-003-2025<br>厂商: 海康威视<br>视频流: RTSP/H.264<br>分辨率: 1920×1080<br>平台类型: 鸿蒙设备",
                properties: {
                    angle: "45°",
                    zoom: "3x",
                    resolution: "1080p"
                }
            },
            {
                name: "雷视一体机-01",
                type: "HARMONY_RADAR",
                status: "warning",
                lat: 31.2305,
                lng: 121.4735,
                icon: radarIcon,
                details: "设备ID: RV-001-2025<br>厂商: 佳都科技<br>状态: 信号弱<br>检测范围: 200米<br>平台类型: 鸿蒙设备",
                properties: {
                    detectionRange: "200m",
                    accuracy: "95%",
                    frequency: "24GHz"
                }
            },
            {
                name: "边缘计算盒子-01",
                type: "OPENHARMONY_CONTROLLER",
                status: "online",
                lat: 31.2298,
                lng: 121.4745,
                icon: edgeIcon,
                details: "设备ID: EC-001-2025<br>芯片: 鲲鹏920<br>内存: 8GB<br>存储: 256GB SSD<br>平台类型: 开源鸿蒙设备",
                properties: {
                    cpuUsage: "45%",
                    memoryUsage: "3.2GB",
                    temperature: "42°C"
                }
            }
        ];

        // 存储图层引用
        const layers = {
            intersectionArea: null,
            laneLines: [],
            crosswalks: [],
            deviceMarkers: []
        };

        // 绘制路口区域
        function drawIntersectionArea() {
            const intersectionBounds = [
                [31.2308, 121.4725],
                [31.2308, 121.4755],
                [31.2295, 121.4755],
                [31.2295, 121.4725]
            ];

            layers.intersectionArea = L.polygon(intersectionBounds, {
                color: '#1890ff',
                weight: 2,
                fillColor: '#e6f7ff',
                fillOpacity: 0.2
            }).addTo(map);

            // 绑定点击事件
            layers.intersectionArea.bindPopup(`
                <div class="marker-popup">
                    <div class="popup-title">路口A</div>
                    <div class="popup-info">类型: 十字路口</div>
                    <div class="popup-info">车道数: 8</div>
                    <div class="popup-info">设备数: 12</div>
                    <div class="popup-info">在线设备: 10</div>
                    <div class="popup-actions">
                        <button class="popup-btn" onclick="viewIntersectionDetails()">查看详情</button>
                        <button class="popup-btn" onclick="editIntersection()">编辑</button>
                    </div>
                </div>
            `);
        }

        // 绘制车道线
        function drawLaneLines() {
            const laneLines = [
                [[31.2306, 121.473], [31.2306, 121.4745]],
                [[31.2302, 121.473], [31.2302, 121.4745]],
                [[31.2304, 121.4735], [31.2297, 121.4735]],
                [[31.2304, 121.474], [31.2297, 121.474]],
                [[31.2303, 121.4732], [31.2303, 121.4743]],
                [[31.2301, 121.4732], [31.2301, 121.4743]]
            ];

            laneLines.forEach(line => {
                const laneLine = L.polyline(line, {
                    color: '#8c8c8c',
                    weight: 3,
                    dashArray: '5, 5'
                }).addTo(map);
                layers.laneLines.push(laneLine);

                // 绑定点击事件
                laneLine.bindPopup(`
                    <div class="marker-popup">
                        <div class="popup-title">车道线</div>
                        <div class="popup-info">类型: 直行车道</div>
                        <div class="popup-info">宽度: 3.5米</div>
                        <div class="popup-info">方向: 东西向</div>
                    </div>
                `);
            });
        }

        // 绘制人行横道
        function drawCrosswalks() {
            const crosswalks = [
                [[31.2305, 121.4738], [31.2303, 121.4738], [31.2303, 121.4739], [31.2305, 121.4739]],
                [[31.2303, 121.4741], [31.2301, 121.4741], [31.2301, 121.4742], [31.2303, 121.4742]]
            ];

            crosswalks.forEach(polygon => {
                const crosswalk = L.polygon(polygon, {
                    color: '#4ECDC4',
                    weight: 1,
                    fillColor: '#4ECDC4',
                    fillOpacity: 0.6
                }).addTo(map);
                layers.crosswalks.push(crosswalk);

                // 绑定点击事件
                crosswalk.bindPopup(`
                    <div class="marker-popup">
                        <div class="popup-title">人行横道</div>
                        <div class="popup-info">宽度: 5米</div>
                        <div class="popup-info">长度: 8米</div>
                        <div class="popup-info">安全等级: 高</div>
                    </div>
                `);
            });
        }

        // 添加设备标记到地图
        function addDeviceMarkers() {
            devices.forEach(device => {
                const marker = L.marker([device.lat, device.lng], { icon: device.icon })
                    .addTo(map)
                    .bindPopup(`
                        <div class="marker-popup">
                            <div class="popup-title">${device.name}</div>
                            <div class="popup-info">类型: ${device.type}</div>
                            <div class="popup-info">位置: 路口A</div>
                            <div class="popup-info">${device.details}</div>
                            <div class="popup-actions">
                                <button class="popup-btn" onclick="viewDeviceDetails('${device.name}')">查看详情</button>
                                <button class="popup-btn" onclick="controlDevice('${device.name}')">控制</button>
                            </div>
                        </div>
                    `);
                layers.deviceMarkers.push(marker);
            });
        }

        // 初始化所有地图元素
        function initializeMapElements() {
            drawIntersectionArea();
            drawLaneLines();
            drawCrosswalks();
            addDeviceMarkers();
        }

        // 初始化地图元素
        initializeMapElements();

        // 地图控件功能
        document.getElementById('zoomInBtn').addEventListener('click', function() {
            map.zoomIn();
        });

        document.getElementById('zoomOutBtn').addEventListener('click', function() {
            map.zoomOut();
        });

        document.getElementById('resetViewBtn').addEventListener('click', function() {
            map.setView([31.2304, 121.4737], 17);
        });

        document.getElementById('measureBtn').addEventListener('click', function() {
            alert('测距工具已激活，点击地图两点测量距离');
        });

        document.getElementById('drawBtn').addEventListener('click', function() {
            alert('绘制工具已激活，可绘制车道、人行横道等要素');
        });

        // 图层控制
        let layersPanelVisible = false;
        document.getElementById('layersBtn').addEventListener('click', function() {
            const panel = document.getElementById('layersPanel');
            layersPanelVisible = !layersPanelVisible;
            panel.style.display = layersPanelVisible ? 'block' : 'none';
        });

        // 图层切换控制
        document.getElementById('intersectionLayerToggle').addEventListener('change', function(e) {
            if (layers.intersectionArea) {
                if (e.target.checked) {
                    map.addLayer(layers.intersectionArea);
                } else {
                    map.removeLayer(layers.intersectionArea);
                }
            }
        });

        document.getElementById('lanesLayerToggle').addEventListener('change', function(e) {
            layers.laneLines.forEach(lane => {
                if (e.target.checked) {
                    map.addLayer(lane);
                } else {
                    map.removeLayer(lane);
                }
            });
        });

        document.getElementById('crosswalkLayerToggle').addEventListener('change', function(e) {
            layers.crosswalks.forEach(crosswalk => {
                if (e.target.checked) {
                    map.addLayer(crosswalk);
                } else {
                    map.removeLayer(crosswalk);
                }
            });
        });

        document.getElementById('devicesLayerToggle').addEventListener('change', function(e) {
            layers.deviceMarkers.forEach(marker => {
                if (e.target.checked) {
                    map.addLayer(marker);
                } else {
                    map.removeLayer(marker);
                }
            });
        });

        // 设备筛选
        document.getElementById('filterBtn').addEventListener('click', function() {
            alert('设备筛选功能，可按类型、状态、厂商等条件筛选');
        });

        // 按钮功能
        document.getElementById('importCadBtn').addEventListener('click', function() {
            alert('CAD图纸导入功能：支持导入DWG/DXF格式的CAD图纸，自动解析为地图要素');
        });

        document.getElementById('exportConfigBtn').addEventListener('click', function() {
            alert('配置导出功能：将当前地图配置导出为JSON文件');
        });

        document.getElementById('refreshMapBtn').addEventListener('click', function() {
            // 移除所有图层
            if (layers.intersectionArea) map.removeLayer(layers.intersectionArea);
            layers.laneLines.forEach(lane => map.removeLayer(lane));
            layers.crosswalks.forEach(crosswalk => map.removeLayer(crosswalk));
            layers.deviceMarkers.forEach(marker => map.removeLayer(marker));

            // 清空图层数组
            layers.laneLines = [];
            layers.crosswalks = [];
            layers.deviceMarkers = [];

            // 重新初始化
            initializeMapElements();

            // 重置图层开关
            document.getElementById('intersectionLayerToggle').checked = true;
            document.getElementById('lanesLayerToggle').checked = true;
            document.getElementById('crosswalkLayerToggle').checked = true;
            document.getElementById('devicesLayerToggle').checked = true;

            alert('地图已刷新');
        });

        // 侧边栏折叠功能
        document.getElementById('sidebarToggle').addEventListener('click', function() {
            const sidebar = document.getElementById('sidebar');
            const icon = this.querySelector('i');

            if (sidebar.classList.contains('collapsed')) {
                sidebar.classList.remove('collapsed');
                icon.className = 'fas fa-chevron-left';
            } else {
                sidebar.classList.add('collapsed');
                icon.className = 'fas fa-chevron-right';
            }
        });

        // 目录结构展开/合并功能
        const sectionHeaders = document.querySelectorAll('.sidebar-header');
        sectionHeaders.forEach(header => {
            header.addEventListener('click', function() {
                const sectionId = this.id;
                const menuId = sectionId.replace('Header', 'Menu');
                const iconId = sectionId.replace('Header', 'Icon');

                const menu = document.getElementById(menuId);
                const icon = document.getElementById(iconId);

                if (menu.style.display === 'none' || menu.style.display === '') {
                    menu.style.display = 'block';
                    icon.classList.remove('collapsed');
                } else {
                    menu.style.display = 'none';
                    icon.classList.add('collapsed');
                }
            });
        });

        // 初始化菜单状态（第一个菜单展开，其他折叠）
        document.addEventListener('DOMContentLoaded', function() {
            // 默认展开第一个菜单
            const section1Menu = document.getElementById('section1Menu');
            const section1Icon = document.getElementById('section1Icon');

            // 折叠其他菜单
            for (let i = 2; i <= 5; i++) {
                const menu = document.getElementById(`section${i}Menu`);
                const icon = document.getElementById(`section${i}Icon`);

                if (menu) {
                    menu.style.display = 'none';
                    icon.classList.add('collapsed');
                }
            }
        });

        // 导航菜单点击事件
        document.querySelectorAll('.nav-item, .nav-subitem').forEach(item => {
            item.addEventListener('click', function() {
                // 移除所有active类
                document.querySelectorAll('.nav-item.active, .nav-subitem.active').forEach(el => {
                    el.classList.remove('active');
                });

                // 为当前项添加active类
                this.classList.add('active');

                // 根据点击的菜单项切换页面内容
                const pageTitle = this.querySelector('span').textContent;
                document.querySelector('.page-title').textContent = pageTitle;
            });
        });

        // 模拟函数
        function viewIntersectionDetails() {
            alert('查看路口详情功能');
        }

        function editIntersection() {
            alert('编辑路口功能');
        }

        function viewDeviceDetails(deviceName) {
            alert(`查看设备详情: ${deviceName}`);
        }

        function controlDevice(deviceName) {
            alert(`控制设备: ${deviceName}`);
        }
    </script>
</body>
