                [31.2308, 121.4725],
                [31.2308, 121.4755],
                [31.2295, 121.4755],
                [31.2295, 121.4725]
            ];

            const intersectionArea = L.polygon(intersectionBounds, {
                color: '#1890ff',
                weight: 2,
                fillColor: '#e6f7ff',
                fillOpacity: 0.2
            }).addTo(map);

            // 添加示例车道线
            const laneLines = [
                [[31.2306, 121.473], [31.2306, 121.4745]],
                [[31.2302, 121.473], [31.2302, 121.4745]],
