            grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
            gap: 20px;
        }

        .element-card {
            border: 1px solid #f0f0f0;
            border-radius: 8px;
            padding: 16px;
            display: flex;
            flex-direction: column;
            gap: 12px;
            transition: all 0.2s;
        }

        .element-card:hover {
            border-color: #1890ff;
            box-shadow: 0 2px 8px rgba(24, 144, 255, 0.2);
        }

        .element-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
        }

        .element-type {
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .element-icon {
            width: 24px;
            height: 24px;
            border-radius: 4px;
            display: flex;
            align-items: center;
            justify-content: center;
            color: white;
            font-size: 12px;
        }

        .element-name {
            font-weight: 500;
            font-size: 1rem;
        }

        .element-status {
            padding: 4px 8px;
            border-radius: 4px;
            font-size: 0.75rem;
            font-weight: 500;
        }

        .status-verified {
            background-color: #f6ffed;
            color: #52c41a;
            border: 1px solid #b7eb8f;
        }

        .status-detected {
            background-color: #e6f7ff;
            color: #1890ff;
            border: 1px solid #91d5ff;
        }

        .status-corrected {
            background-color: #fff7e6;
            color: #fa8c16;
            border: 1px solid #ffd591;
        }

        .element-details {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 10px;
            font-size: 0.85rem;
        }

        .detail-item {
            display: flex;
            flex-direction: column;
            gap: 2px;
        }

        .detail-label {
            color: #8c8c8c;
        }

        .detail-value {
            font-weight: 500;
        }

        .element-actions {
            display: flex;
            gap: 8px;
            margin-top: 10px;
        }

        .action-btn {
            padding: 4px 8px;
            border-radius: 4px;
            border: 1px solid #d9d9d9;
            background-color: white;
            cursor: pointer;
            font-size: 0.8rem;
            transition: all 0.2s;
            display: flex;
            align-items: center;
            gap: 4px;
        }

        .action-btn:hover {
            background-color: #f5f5f5;
            border-color: #1890ff;
        }

        .table-container {
            overflow-x: auto;
        }

        .data-table {
            width: 100%;
            border-collapse: collapse;
        }

        .data-table th {
            background-color: #fafafa;
            text-align: left;
            padding: 12px 16px;
            font-weight: 600;
            color: #262626;
            border-bottom: 1px solid #f0f0f0;
            white-space: nowrap;
        }

        .data-table td {
            padding: 12px 16px;
            border-bottom: 1px solid #f0f0f0;
        }

        .data-table tbody tr:hover {
            background-color: #fafafa;
        }

        .color-indicator {
            width: 16px;
            height: 16px;
            border-radius: 3px;
            display: inline-block;
            margin-right: 8px;
            vertical-align: middle;
        }

        .pagination {
            display: flex;
            justify-content: flex-end;
            align-items: center;
            gap: 10px;
            margin-top: 20px;
        }

        .pagination-info {
            font-size: 0.9rem;
            color: #8c8c8c;
        }

        .pagination-controls {
            display: flex;
            gap: 5px;
        }

        .pagination-btn {
            width: 32px;
            height: 32px;
            border-radius: 4px;
            border: 1px solid #d9d9d9;
            background-color: white;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .pagination-btn.active {
            background-color: #1890ff;
            color: white;
            border-color: #1890ff;
        }

        .pagination-btn:hover:not(.active) {
            background-color: #f5f5f5;
            border-color: #1890ff;
        }

        .empty-state {
            text-align: center;
            padding: 40px 20px;
            color: #8c8c8c;
        }

        .empty-state i {
            font-size: 3rem;
            margin-bottom: 15px;
            color: #d9d9d9;
        }

        .empty-state p {
            font-size: 1rem;
        }

        .footer {
            text-align: center;
            padding: 20px;
            color: #8c8c8c;
            font-size: 0.85rem;
            border-top: 1px solid #f0f0f0;
            margin-top: 30px;
        }

        @media (max-width: 992px) {
            .sidebar {
                width: 200px;
            }

            .main-content {
                margin-left: 200px;
            }

            .elements-grid {
                grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
            }
        }

        @media (max-width: 768px) {
            .sidebar {
                width: 0;
                overflow: hidden;
            }

            .sidebar.open {
                width: 250px;
            }

            .main-content {
                margin-left: 0;
            }

            .page-header {
                flex-direction: column;
                align-items: flex-start;
                gap: 15px;
            }

            .page-controls {
                width: 100%;
                justify-content: flex-start;
            }

            .filters-row {
                flex-direction: column;
            }

            .filter-group {
                min-width: 100%;
            }

            .elements-grid {
                grid-template-columns: 1fr;
            }

            .mobile-menu-toggle {
                display: block;
                background: none;
                border: none;
                color: white;
                font-size: 1.2rem;
                cursor: pointer;
                margin-right: 15px;
            }
        }
    </style>
</head>
<body>
    <div class="header">
        <button class="mobile-menu-toggle" id="mobileMenuToggle">
            <i class="fas fa-bars"></i>
        </button>
        <div class="logo-container">
