                        <div class="filter-label">要素类型</div>
                        <select class="filter-select" id="typeFilter">
                            <option value="">全部类型</option>
                            <option value="LANE">车道</option>
                            <option value="CROSSWALK">人行横道</option>
                            <option value="TRAFFIC_LIGHT">信号灯</option>
