                    </div>

                    <div class="filter-group">
                        <div class="filter-label">路口</div>
                        <select class="filter-select" id="intersectionFilter">
                            <option value="">全部路口</option>
                            <option value="INT-001">路口A</option>
                            <option value="INT-002">路口B</option>
                            <option value="INT-003">路口C</option>
                            <option value="INT-004">路口D</option>
                        </select>
                    </div>

                    <div class="filter-group">
                        <div class="filter-label">置信度</div>
                        <select class="filter-select" id="confidenceFilter">
                            <option value="">全部</option>
                            <option value="high">高 (≥ 0.8)</option>
                            <option value="medium">中 (0.5-0.8)</option>
                            <option value="low">低 (&lt; 0.5)</option>
                        </select>
                    </div>

                    <div class="filter-group">
                        <div class="filter-label">要素名称</div>
                        <input type="text" class="filter-input" id="nameFilter" placeholder="输入要素名称...">
                    </div>
                </div>

                <div style="display: flex; gap: 10px; margin-top: 10px;">
                    <button class="btn btn-primary" id="applyFiltersBtn">
                        <i class="fas fa-filter"></i>
                        应用筛选
                    </button>
                    <button class="btn" id="resetFiltersBtn">
                        <i class="fas fa-redo"></i>
                        重置筛选
                    </button>
                </div>
            </div>

            <div class="content-section">
                <div class="section-title">要素列表</div>

                <div class="elements-grid" id="elementsGrid">
                    <!-- 要素卡片将通过JS动态生成 -->
                </div>

                <div class="pagination">
                    <div class="pagination-info">显示 1-10 条，共 48 条</div>
                    <div class="pagination-controls">
                        <button class="pagination-btn"><i class="fas fa-chevron-left"></i></button>
                        <button class="pagination-btn active">1</button>
                        <button class="pagination-btn">2</button>
                        <button class="pagination-btn">3</button>
                        <button class="pagination-btn">4</button>
                        <button class="pagination-btn">5</button>
                        <button class="pagination-btn"><i class="fas fa-chevron-right"></i></button>
                    </div>
                </div>
            </div>

            <div class="footer">
                <p>© 2025 开源鸿蒙交通路口管理系统 | 基于OpenHarmony生态构建 | 版本号: V2.1.5</p>
                <p>技术支持: 中软国际技术团队 | 服务热线: 400-123-4567</p>
            </div>
        </div>
    </div>

    <script>
        // 模拟数据
        const elementTypes = {
            LANE: { name: "车道", color: "#FF6B6B", icon: "fas fa-road" },
            CROSSWALK: { name: "人行横道", color: "#4ECDC4", icon: "fas fa-walking" },
            TRAFFIC_LIGHT: { name: "信号灯", color: "#45B7D1", icon: "fas fa-traffic-light" },
            CAMERA: { name: "摄像头", color: "#96CEB4", icon: "fas fa-video" },
            STOP_LINE: { name: "停止线", color: "#FECA57", icon: "fas fa-stop" },
            ROAD_MARKING: { name: "道路标线", color: "#FF9FF3", icon: "fas fa-draw-polygon" },
            TRAFFIC_SIGN: { name: "交通标志", color: "#54A0FF", icon: "fas fa-sign" },
            GUARDRAIL: { name: "护栏", color: "#5F27CD", icon: "fas fa-shield-alt" },
            PARKING_LOT: { name: "停车位", color: "#00D2D3", icon: "fas fa-parking" }
        };

        const annotationStatuses = {
            AUTO_DETECTED: { name: "自动检测", class: "status-detected" },
            MANUAL_VERIFIED: { name: "人工验证", class: "status-verified" },
            MANUAL_CORRECTED: { name: "人工修正", class: "status-corrected" },
            REJECTED: { name: "已拒绝", class: "status-rejected" }
        };

        const intersections = ["路口A", "路口B", "路口C", "路口D"];

        // 生成模拟数据
        function generateMockElements(count) {
            const elements = [];
            const elementTypeKeys = Object.keys(elementTypes);
            const statusKeys = Object.keys(annotationStatuses);

            for (let i = 1; i <= count; i++) {
                const typeKey = elementTypeKeys[Math.floor(Math.random() * elementTypeKeys.length)];
                const statusKey = statusKeys[Math.floor(Math.random() * statusKeys.length)];
                const intersection = intersections[Math.floor(Math.random() * intersections.length)];
                const confidenceScore = (Math.random() * 0.5 + 0.5).toFixed(2); // 0.5-1.0

                elements.push({
                    id: i,
                    name: `${elementTypes[typeKey].name} ${i}`,
                    type: typeKey,
                    typeName: elementTypes[typeKey].name,
                    status: statusKey,
                    statusName: annotationStatuses[statusKey].name,
                    intersection: intersection,
                    intersectionId: `INT-00${intersections.indexOf(intersection) + 1}`,
                    confidenceScore: parseFloat(confidenceScore),
                    centerX: (Math.random() * 100).toFixed(2),
                    centerY: (Math.random() * 100).toFixed(2),
                    detectionVersion: "v2.1",
                    autoGenerated: Math.random() > 0.3,
                    createdTime: "2025-05-" + (Math.floor(Math.random() * 28) + 1).toString().padStart(2, '0')
                });
            }

            return elements;
        }

        // 初始化模拟数据
        let allElements = generateMockElements(48);
        let filteredElements = [...allElements];

        // DOM元素
        const elementsGrid = document.getElementById('elementsGrid');
        const mobileMenuToggle = document.getElementById('mobileMenuToggle');
        const sidebar = document.getElementById('sidebar');
        const sidebarHeaders = document.querySelectorAll('.sidebar-header');
        const navItems = document.querySelectorAll('.nav-item');
        const typeFilter = document.getElementById('typeFilter');
        const statusFilter = document.getElementById('statusFilter');
        const intersectionFilter = document.getElementById('intersectionFilter');
        const confidenceFilter = document.getElementById('confidenceFilter');
        const nameFilter = document.getElementById('nameFilter');
        const applyFiltersBtn = document.getElementById('applyFiltersBtn');
        const resetFiltersBtn = document.getElementById('resetFiltersBtn');
        const addElementBtn = document.getElementById('addElementBtn');
        const importCadBtn = document.getElementById('importCadBtn');
        const refreshBtn = document.getElementById('refreshBtn');

        // 渲染要素卡片
        function renderElements(elements) {
            elementsGrid.innerHTML = '';

            if (elements.length === 0) {
                elementsGrid.innerHTML = `
                    <div class="empty-state" style="grid-column: 1 / -1;">
                        <i class="fas fa-draw-polygon"></i>
                        <p>未找到匹配的设备要素</p>
                        <p style="font-size: 0.9rem; margin-top: 10px;">尝试调整筛选条件或添加新要素</p>
                    </div>
                `;
                return;
            }

            elements.forEach(element => {
                const typeInfo = elementTypes[element.type];
                const statusInfo = annotationStatuses[element.status];
                const confidenceColor = element.confidenceScore >= 0.8 ? '#52c41a' : 
                                      element.confidenceScore >= 0.5 ? '#faad14' : '#ff4d4f';

                const card = document.createElement('div');
                card.className = 'element-card';
                card.innerHTML = `
                    <div class="element-header">
                        <div class="element-type">
                            <div class="element-icon" style="background-color: ${typeInfo.color};">
                                <i class="${typeInfo.icon}"></i>
                            </div>
                            <div class="element-name">${element.name}</div>
                        </div>
                        <div class="element-status ${statusInfo.class}">${statusInfo.name}</div>
                    </div>

                    <div class="element-details">
                        <div class="detail-item">
                            <div class="detail-label">类型</div>
                            <div class="detail-value">${typeInfo.name}</div>
                        </div>
                        <div class="detail-item">
                            <div class="detail-label">路口</div>
                            <div class="detail-value">${element.intersection}</div>
                        </div>
                        <div class="detail-item">
                            <div class="detail-label">置信度</div>
                            <div class="detail-value">
                                <div style="display: flex; align-items: center;">
                                    <div style="width: 60px; height: 6px; background-color: #f0f0f0; border-radius: 3px; margin-right: 8px;">
                                        <div style="width: ${element.confidenceScore * 100}%; height: 100%; background-color: ${confidenceColor}; border-radius: 3px;"></div>
                                    </div>
                                    ${(element.confidenceScore * 100).toFixed(1)}%
                                </div>
                            </div>
                        </div>
                        <div class="detail-item">
                            <div class="detail-label">坐标</div>
                            <div class="detail-value">(${element.centerX}, ${element.centerY})</div>
                        </div>
                        <div class="detail-item">
                            <div class="detail-label">检测方式</div>
                            <div class="detail-value">${element.autoGenerated ? '自动生成' : '手动添加'}</div>
                        </div>
                        <div class="detail-item">
                            <div class="detail-label">检测版本</div>
                            <div class="detail-value">${element.detectionVersion}</div>
                        </div>
                    </div>

                    <div class="element-actions">
                        <button class="action-btn" onclick="viewElementDetails(${element.id})">
                            <i class="fas fa-eye"></i>
                            查看
                        </button>
                        <button class="action-btn" onclick="editElement(${element.id})">
                            <i class="fas fa-edit"></i>
                            编辑
                        </button>
                        <button class="action-btn" onclick="deleteElement(${element.id})">
                            <i class="fas fa-trash"></i>
                            删除
                        </button>
                    </div>
                `;

                elementsGrid.appendChild(card);
            });
        }

        // 应用筛选条件
        function applyFilters() {
            filteredElements = [...allElements];

            // 类型筛选
            if (typeFilter.value) {
                filteredElements = filteredElements.filter(element => element.type === typeFilter.value);
            }

            // 状态筛选
            if (statusFilter.value) {
                filteredElements = filteredElements.filter(element => element.status === statusFilter.value);
            }

            // 路口筛选
            if (intersectionFilter.value) {
                filteredElements = filteredElements.filter(element => element.intersectionId === intersectionFilter.value);
            }

            // 置信度筛选
            if (confidenceFilter.value) {
                if (confidenceFilter.value === 'high') {
                    filteredElements = filteredElements.filter(element => element.confidenceScore >= 0.8);
                } else if (confidenceFilter.value === 'medium') {
                    filteredElements = filteredElements.filter(element => element.confidenceScore >= 0.5 && element.confidenceScore < 0.8);
                } else if (confidenceFilter.value === 'low') {
                    filteredElements = filteredElements.filter(element => element.confidenceScore < 0.5);
                }
            }

            // 名称筛选
            if (nameFilter.value.trim()) {
                const searchTerm = nameFilter.value.trim().toLowerCase();
                filteredElements = filteredElements.filter(element => 
                    element.name.toLowerCase().includes(searchTerm) || 
                    element.typeName.toLowerCase().includes(searchTerm)
                );
            }

            renderElements(filteredElements);
        }

        // 重置筛选条件
        function resetFilters() {
            typeFilter.value = '';
            statusFilter.value = '';
            intersectionFilter.value = '';
            confidenceFilter.value = '';
            nameFilter.value = '';
            applyFilters();
        }

        // 侧边栏折叠功能
        sidebarHeaders.forEach(header => {
            header.addEventListener('click', function() {
                const section = this.getAttribute('data-section');
                const menu = document.getElementById(`${section}-menu`);
                const icon = this.querySelector('.toggle-icon');

                menu.classList.toggle('collapsed');
                icon.classList.toggle('collapsed');
            });
        });

        // 导航菜单点击事件
        navItems.forEach(item => {
            item.addEventListener('click', function() {
                // 移除所有active类
                navItems.forEach(el => el.classList.remove('active'));

                // 为当前项添加active类
                this.classList.add('active');

                // 更新页面标题
                const pageTitle = this.querySelector('span').textContent;
                document.querySelector('.page-title').textContent = pageTitle;

                // 如果是移动端，点击后关闭侧边栏
                if (window.innerWidth <= 768) {
                    sidebar.classList.remove('open');
                }
            });
        });

        // 移动端菜单切换
        mobileMenuToggle.addEventListener('click', function() {
            sidebar.classList.toggle('open');
        });

        // 按钮点击事件
        applyFiltersBtn.addEventListener('click', applyFilters);
        resetFiltersBtn.addEventListener('click', resetFilters);

        addElementBtn.addEventListener('click', function() {
            alert('添加新要素功能：支持手动添加车道、人行横道、信号灯等要素');
        });

        importCadBtn.addEventListener('click', function() {
            alert('CAD图纸导入功能：支持导入DWG/DXF格式的CAD图纸，自动解析为地图要素');
        });

        refreshBtn.addEventListener('click', function() {
            allElements = generateMockElements(48);
            applyFilters();
            alert('要素数据已刷新');
        });

        // 模拟函数
        function viewElementDetails(id) {
            const element = allElements.find(e => e.id === id);
            if (element) {
                alert(`查看要素详情:\n名称: ${element.name}\n类型: ${element.typeName}\n路口: ${element.intersection}\n置信度: ${(element.confidenceScore * 100).toFixed(1)}%\n状态: ${annotationStatuses[element.status].name}`);
            }
        }

        function editElement(id) {
            const element = allElements.find(e => e.id === id);
            if (element) {
                alert(`编辑要素: ${element.name}\n要素ID: ${element.id}\n类型: ${element.typeName}`);
            }
        }

        function deleteElement(id) {
            if (confirm('确定要删除这个要素吗？此操作不可撤销。')) {
                allElements = allElements.filter(e => e.id !== id);
                applyFilters();
                alert('要素已删除');
            }
        }

        // 初始化页面
        document.addEventListener('DOMContentLoaded', function() {
            renderElements(allElements);

            // 默认展开第一个菜单
            document.querySelector('.sidebar-header').click();
        });
    </script>
</body>
</html>
