            // 模拟设备要素数据
            const elementData = [
                {id: 'EL-2025-001-001', name: '北进口直行车道', type: 'LANE', intersection: '路口A', status: 'MANUAL_VERIFIED', confidence: 0.98, detection: '自动检测', time: '2025-03-15'},
                {id: 'EL-2025-001-002', name: '东进口人行横道', type: 'CROSSWALK', intersection: '路口A', status: 'MANUAL_VERIFIED', confidence: 0.95, detection: '自动检测', time: '2025-03-15'},
                {id: 'EL-2025-001-003', name: '南进口信号灯', type: 'TRAFFIC_LIGHT', intersection: '路口A', status: 'MANUAL_CORRECTED', confidence: 0.92, detection: '自动检测', time: '2025-03-15'},
                {id: 'EL-2025-001-004', name: '西进口摄像头', type: 'CAMERA', intersection: '路口A', status: 'MANUAL_VERIFIED', confidence: 0.96, detection: '自动检测', time: '2025-03-15'},
                {id: 'EL-2025-001-005', name: '南进口停止线', type: 'STOP_LINE', intersection: '路口A', status: 'AUTO_DETECTED', confidence: 0.88, detection: '自动检测', time: '2025-03-15'},
                {id: 'EL-2025-001-006', name: '北出口道路标线', type: 'ROAD_MARKING', intersection: '路口A', status: 'MANUAL_VERIFIED', confidence: 0.91, detection: '自动检测', time: '2025-03-15'},
                {id: 'EL-2025-002-001', name: '东进口左转车道', type: 'LANE', intersection: '路口B', status: 'MANUAL_VERIFIED', confidence: 0.97, detection: '自动检测', time: '2025-03-14'},
                {id: 'EL-2025-002-002', name: '西进口人行横道', type: 'CROSSWALK', intersection: '路口B', status: 'MANUAL_CORRECTED', confidence: 0.89, detection: '自动检测', time: '2025-03-14'},
                {id: 'EL-2025-002-003', name: '北进口信号灯', type: 'TRAFFIC_LIGHT', intersection: '路口B', status: 'MANUAL_VERIFIED', confidence: 0.94, detection: '自动检测', time: '2025-03-14'},
                {id: 'EL-2025-002-004', name: '南进口摄像头', type: 'CAMERA', intersection: '路口B', status: 'AUTO_DETECTED', confidence: 0.85, detection: '自动检测', time: '2025-03-14'},
            ];

            // 渲染表格数据
            function renderElementTable(data) {
                const tableBody = document.getElementById('elementTableBody');
                tableBody.innerHTML = '';

                data.forEach(item => {
                    const row = document.createElement('tr');

                    // 获取类型颜色
                    let typeColor = '#8c8c8c';
                    let typeText = item.type;
                    switch(item.type) {
                        case 'LANE': typeColor = '#FF6B6B'; typeText = '车道'; break;
                        case 'CROSSWALK': typeColor = '#4ECDC4'; typeText = '人行横道'; break;
                        case 'TRAFFIC_LIGHT': typeColor = '#45B7D1'; typeText = '信号灯'; break;
                        case 'CAMERA': typeColor = '#96CEB4'; typeText = '摄像头'; break;
                        case 'STOP_LINE': typeColor = '#FECA57'; typeText = '停止线'; break;
                        case 'ROAD_MARKING': typeColor = '#FF9FF3'; typeText = '道路标线'; break;
                        case 'TRAFFIC_SIGN': typeColor = '#54A0FF'; typeText = '交通标志'; break;
                    }

                    // 获取状态文本
                    let statusText = item.status;
                    let statusClass = 'online';
                    switch(item.status) {
                        case 'AUTO_DETECTED': statusText = '自动检测'; statusClass = 'offline'; break;
                        case 'MANUAL_VERIFIED': statusText = '人工验证'; statusClass = 'online'; break;
                        case 'MANUAL_CORRECTED': statusText = '人工修正'; statusClass = 'online'; break;
                        case 'REJECTED': statusText = '已拒绝'; statusClass = 'offline'; break;
