                        <td><span class="element-type-badge" style="background-color: ${typeColor}20; color: ${typeColor}; border: 1px solid ${typeColor};">${typeText}</span></td>
                        <td>${item.intersection}</td>
                        <td><span class="status-badge ${statusClass}">${statusText}</span></td>
                        <td><span class="confidence-score ${confidenceClass}">${item.confidence.toFixed(2)}</span></td>
                        <td>${item.detection}</td>
                        <td>${item.time}</td>
