                checkboxes.forEach(checkbox => {
                    checkbox.checked = this.checked;
                });
            });

            // 筛选功能
            document.getElementById('elementTypeFilter').addEventListener('change', applyFilters);
            document.getElementById('annotationStatusFilter').addEventListener('change', applyFilters);
            document.getElementById('intersectionFilter').addEventListener('change', applyFilters);
            document.getElementById('confidenceFilter').addEventListener('change', applyFilters);
            document.getElementById('searchBtn').addEventListener('click', applyFilters);
            document.getElementById('searchInput').addEventListener('keyup', function(event) {
                if (event.key === 'Enter') {
                    applyFilters();
                }
            });

            function applyFilters() {
                const typeFilter = document.getElementById('elementTypeFilter').value;
                const statusFilter = document.getElementById('annotationStatusFilter').value;
                const intersectionFilter = document.getElementById('intersectionFilter').value;
                const confidenceFilter = document.getElementById('confidenceFilter').value;
                const searchText = document.getElementById('searchInput').value.toLowerCase();

                let filteredData = elementData.filter(item => {
                    // 类型筛选
                    if (typeFilter && item.type !== typeFilter) return false;

                    // 状态筛选
                    if (statusFilter) {
                        let statusValue = '';
                        switch(item.status) {
                            case 'AUTO_DETECTED': statusValue = 'AUTO_DETECTED'; break;
                            case 'MANUAL_VERIFIED': statusValue = 'MANUAL_VERIFIED'; break;
                            case 'MANUAL_CORRECTED': statusValue = 'MANUAL_CORRECTED'; break;
                            case 'REJECTED': statusValue = 'REJECTED'; break;
                        }
                        if (statusValue !== statusFilter) return false;
                    }

                    // 路口筛选
                    if (intersectionFilter && !item.intersection.includes(intersectionFilter === '1' ? '路口A' : 
                                                                       intersectionFilter === '2' ? '路口B' : 
                                                                       intersectionFilter === '3' ? '路口C' : '路口D')) return false;

                    // 置信度筛选
                    if (confidenceFilter === 'high' && item.confidence < 0.9) return false;
                    if (confidenceFilter === 'medium' && (item.confidence < 0.7 || item.confidence >= 0.9)) return false;
                    if (confidenceFilter === 'low' && item.confidence >= 0.7) return false;

                    // 搜索文本筛选
                    if (searchText && !item.name.toLowerCase().includes(searchText) && 
                        !item.id.toLowerCase().includes(searchText) && 
                        !item.type.toLowerCase().includes(searchText)) return false;

                    return true;
                });

                renderElementTable(filteredData);

                // 更新分页信息
                const paginationInfo = document.querySelector('.pagination-info');
                paginationInfo.textContent = `显示第 1 到 ${Math.min(filteredData.length, 10)} 条，共 ${filteredData.length} 条记录`;
            }

            // 分页功能
            document.getElementById('prevPageBtn').addEventListener('click', function() {
                const activePage = document.querySelector('.page-number.active');
                const prevPage = activePage.previousElementSibling;

                if (prevPage && prevPage.classList.contains('page-number')) {
                    activePage.classList.remove('active');
                    prevPage.classList.add('active');

                    // 更新按钮状态
                    document.getElementById('prevPageBtn').disabled = !prevPage.previousElementSibling || 
                                                                    !prevPage.previousElementSibling.classList.contains('page-number');
                    document.getElementById('nextPageBtn').disabled = false;
                }
            });

            document.getElementById('nextPageBtn').addEventListener('click', function() {
                const activePage = document.querySelector('.page-number.active');
                const nextPage = activePage.nextElementSibling;

                if (nextPage && nextPage.classList.contains('page-number')) {
                    activePage.classList.remove('active');
                    nextPage.classList.add('active');

                    // 更新按钮状态
                    document.getElementById('prevPageBtn').disabled = false;
                    document.getElementById('nextPageBtn').disabled = !nextPage.nextElementSibling || 
                                                                    !nextPage.nextElementSibling.classList.contains('page-number');
                }
            });

            // 页面数字点击
            document.querySelectorAll('.page-number').forEach(page => {
                page.addEventListener('click', function() {
                    if (this.classList.contains('active')) return;

                    document.querySelector('.page-number.active').classList.remove('active');
                    this.classList.add('active');

                    // 更新按钮状态
                    const pageNumbers = document.querySelectorAll('.page-number');
                    const currentIndex = Array.from(pageNumbers).indexOf(this);

                    document.getElementById('prevPageBtn').disabled = currentIndex === 0;
                    document.getElementById('nextPageBtn').disabled = currentIndex === pageNumbers.length - 1;
                });
            });

            // 添加要素按钮
            document.getElementById('addElementBtn').addEventListener('click', function() {
