                    }, 1500);
                }
            });

            // 导出数据按钮
            document.getElementById('exportDataBtn').addEventListener('click', function() {
                showToast('正在导出设备要素数据...', 'info');

                // 模拟导出操作
                setTimeout(() => {
                    showToast('设备要素数据导出成功', 'success');
                }, 1000);
            });

            // 模态框功能
            const elementModal = document.getElementById('elementModal');
            const detailModal = document.getElementById('detailModal');

            // 打开添加要素模态框
            function openAddModal() {
                document.getElementById('modalTitle').textContent = '新增设备要素';
                document.getElementById('elementForm').reset();
                elementModal.classList.add('active');
            }

            // 打开编辑要素模态框
            function openEditModal(elementId, elementName) {
                document.getElementById('modalTitle').textContent = '编辑设备要素';
                document.getElementById('elementName').value = elementName;
                document.getElementById('elementType').value = 'LANE';
