        // Ping设备检测
        function pingDevice(deviceId) {
            const device = devicesData.find(d => d.id === deviceId);
            if (device) {
                alert(`正在检测设备 ${device.name} (${deviceId}) 的网络连接...`);
                // 模拟检测过程
                setTimeout(() => {
                    const isOnline = Math.random() > 0.3;
                    alert(`设备 ${device.name} 检测${isOnline ? '成功' : '失败'}，${isOnline ? '网络连接正常' : '无法连接到设备'}`);

                    // 更新设备状态
                    if (!isOnline && device.status === 'online') {
                        device.status = 'offline';
                        device.lastHeartbeat = new Date().toISOString().replace('T', ' ').substr(0, 19);
                        renderDevicesTable();
                        renderDeviceMarkers();
                        updateStats();
                    }
                }, 1000);
            }
        }
    </script>
