                {
                    id: 5,
                    name: "人民路与中山路交叉口",
                    code: "GROUP_INTERSECTION_001",
                    type: 1,
                    typeName: "按路口分组",
                    parentId: 1,
                    path: "/1/5",
                    level: 2,
                    description: "人民路与中山路交叉口的所有设备",
                    intersectionId: 1,
                    intersectionName: "人民路与中山路交叉口",
                    deviceCount: 12,
                    onlineDeviceCount: 11,
                    status: 1,
                    isSystem: false,
                    iconColor: "#ff4d4f"
                },
                {
                    id: 6,
                    name: "解放路与延安路交叉口",
                    code: "GROUP_INTERSECTION_002",
                    type: 1,
                    typeName: "按路口分组",
                    parentId: 1,
                    path: "/1/6",
                    level: 2,
                    description: "解放路与延安路交叉口的所有设备",
                    intersectionId: 2,
                    intersectionName: "解放路与延安路交叉口",
                    deviceCount: 10,
                    onlineDeviceCount: 10,
                    status: 1,
                    isSystem: false,
                    iconColor: "#ff4d4f"
                },
                {
                    id: 7,
                    name: "华为设备分组",
                    code: "GROUP_HUAWEI",
                    type: 5,
                    typeName: "按厂商分组",
                    parentId: null,
                    path: "/7",
                    level: 1,
                    description: "华为厂商的所有设备",
                    manufacturer: "华为技术有限公司",
                    deviceCount: 28,
                    onlineDeviceCount: 27,
                    status: 1,
                    isSystem: false,
                    iconColor: "#13c2c2"
                }
            ];

            // 模拟设备数据
            const devices = [
                { id: 1, name: "鸿蒙信号灯-001", type: "信号灯", status: "online", groupId: 5, icon: "traffic-light", iconColor: "#52c41a" },
                { id: 2, name: "智能摄像机-003", type: "摄像头", status: "online", groupId: 5, icon: "video", iconColor: "#1890ff" },
                { id: 3, name: "雷达探测器-012", type: "雷达", status: "offline", groupId: 5, icon: "satellite-dish", iconColor: "#722ed1" },
                { id: 4, name: "边缘计算盒-005", type: "边缘计算", status: "online", groupId: 5, icon: "microchip", iconColor: "#faad14" },
                { id: 5, name: "鸿蒙信号灯-002", type: "信号灯", status: "online", groupId: 6, icon: "traffic-light", iconColor: "#52c41a" },
                { id: 6, name: "智能摄像机-007", type: "摄像头", status: "online", groupId: 6, icon: "video", iconColor: "#1890ff" },
                { id: 7, name: "路侧单元-003", type: "RSU", status: "online", groupId: 6, icon: "broadcast-tower", iconColor: "#13c2c2" }
            ];

            // 当前选中的分组ID
            let selectedGroupId = null;

            // 渲染分组树
            function renderGroupTree(filteredGroups = deviceGroups) {
                const groupTree = document.getElementById('groupTree');
                groupTree.innerHTML = '';

                // 按层级和路径排序
                const sortedGroups = [...filteredGroups].sort((a, b) => {
                    if (a.path < b.path) return -1;
                    if (a.path > b.path) return 1;
                    return 0;
                });

                sortedGroups.forEach(group => {
                    const groupItem = document.createElement('li');
                    groupItem.className = 'group-tree-item';
                    if (selectedGroupId === group.id) {
                        groupItem.classList.add('active');
                    }
                    groupItem.dataset.groupId = group.id;

                    // 设置缩进
                    const indent = (group.level - 1) * 20;

                    // 分组图标颜色映射
                    const iconColors = {
                        1: "#ff4d4f", // 路口分组
                        2: "#1890ff", // 区域分组
                        3: "#faad14", // 设备类型分组
                        4: "#722ed1", // 自定义分组
                        5: "#13c2c2"  // 厂商分组
                    };

                    const iconColor = iconColors[group.type] || "#8c8c8c";

                    groupItem.innerHTML = `
                        <div style="margin-left: ${indent}px; display: flex; align-items: center; gap: 10px; width: 100%;">
                            <div class="group-icon" style="background-color: ${iconColor};">
                                <i class="fas fa-${group.type === 1 ? 'map-marker-alt' : group.type === 2 ? 'map' : group.type === 3 ? 'server' : group.type === 4 ? 'folder' : 'industry'}"></i>
                            </div>
                            <div class="group-info">
                                <div class="group-name">${group.name}</div>
                                <div class="group-details">
                                    <span>${group.typeName}</span>
                                    <span class="group-count">${group.deviceCount} 设备</span>
                                    <span>${group.onlineDeviceCount} 在线</span>
                                    ${group.isSystem ? '<span style="color: #722ed1;">系统分组</span>' : ''}
                                </div>
                            </div>
                            <div class="group-actions">
                                <button class="group-action-btn edit-group-btn" title="编辑分组">
                                    <i class="fas fa-edit"></i>
                                </button>
                                <button class="group-action-btn delete-group-btn" title="删除分组">
                                    <i class="fas fa-trash"></i>
                                </button>
                            </div>
                        </div>
                    `;

                    groupTree.appendChild(groupItem);

                    // 添加点击事件
                    groupItem.addEventListener('click', function(e) {
                        if (!e.target.closest('.group-actions')) {
                            selectGroup(group.id);
                        }
                    });

                    // 编辑按钮事件
                    const editBtn = groupItem.querySelector('.edit-group-btn');
                    editBtn.addEventListener('click', function(e) {
                        e.stopPropagation();
                        editGroup(group.id);
                    });

                    // 删除按钮事件
                    const deleteBtn = groupItem.querySelector('.delete-group-btn');
                    deleteBtn.addEventListener('click', function(e) {
                        e.stopPropagation();
                        showDeleteConfirm(group.id, group.name);
                    });
                });

                // 如果没有分组数据
                if (sortedGroups.length === 0) {
                    groupTree.innerHTML = '<li style="text-align: center; padding: 30px; color: #8c8c8c;">未找到匹配的分组</li>';
                }
            }

            // 选择分组
            function selectGroup(groupId) {
                selectedGroupId = groupId;

                // 更新分组树选中状态
                document.querySelectorAll('.group-tree-item').forEach(item => {
                    item.classList.remove('active');
                    if (parseInt(item.dataset.groupId) === groupId) {
                        item.classList.add('active');
                    }
                });

                // 显示分组详情面板
                document.getElementById('groupDetailPanel').style.display = 'block';
                document.getElementById('groupFormPanel').style.display = 'none';

                // 渲染分组详情
                renderGroupDetail(groupId);

                // 渲染分组设备列表
                renderGroupDevices(groupId);
            }

            // 渲染分组详情
            function renderGroupDetail(groupId) {
                const group = deviceGroups.find(g => g.id === groupId);
                if (!group) return;

                const detailContent = document.getElementById('groupDetailContent');

                // 根据分组类型显示不同的信息
                let specificInfo = '';
                if (group.type === 1 && group.intersectionName) {
                    specificInfo = `<div class="detail-item">
                        <div class="detail-label">关联路口</div>
                        <div class="detail-value">${group.intersectionName}</div>
                    </div>`;
                } else if (group.type === 5 && group.manufacturer) {
                    specificInfo = `<div class="detail-item">
                        <div class="detail-label">设备厂商</div>
                        <div class="detail-value">${group.manufacturer}</div>
                    </div>`;
                }

                detailContent.innerHTML = `
                    <div style="display: grid; grid-template-columns: repeat(auto-fill, minmax(250px, 1fr)); gap: 20px;">
                        <div class="detail-item">
                            <div class="detail-label">分组名称</div>
                            <div class="detail-value">${group.name}</div>
                        </div>
                        <div class="detail-item">
                            <div class="detail-label">分组编码</div>
                            <div class="detail-value">${group.code}</div>
                        </div>
                        <div class="detail-item">
                            <div class="detail-label">分组类型</div>
                            <div class="detail-value">${group.typeName}</div>
                        </div>
                        <div class="detail-item">
                            <div class="detail-label">设备数量</div>
                            <div class="detail-value">${group.deviceCount} (${group.onlineDeviceCount} 在线)</div>
                        </div>
                        ${specificInfo}
                        <div class="detail-item">
                            <div class="detail-label">创建时间</div>
                            <div class="detail-value">2025-03-15 14:30:22</div>
                        </div>
                        <div class="detail-item">
                            <div class="detail-label">更新时间</div>
                            <div class="detail-value">2025-05-20 09:15:47</div>
                        </div>
                        <div class="detail-item" style="grid-column: 1 / -1;">
                            <div class="detail-label">分组描述</div>
                            <div class="detail-value">${group.description}</div>
                        </div>
                    </div>
                `;
            }

            // 渲染分组设备列表
            function renderGroupDevices(groupId) {
                const deviceList = document.getElementById('deviceList');
                const groupDevices = devices.filter(d => d.groupId === groupId);

                if (groupDevices.length === 0) {
                    deviceList.innerHTML = '<div class="no-devices">该分组下暂无设备</div>';
                    return;
                }

                deviceList.innerHTML = '';

                groupDevices.forEach(device => {
                    const deviceCard = document.createElement('div');
                    deviceCard.className = 'device-card';

                    // 设备图标映射
                    const iconClasses = {
                        'traffic-light': 'traffic-light',
                        'video': 'video',
                        'satellite-dish': 'satellite-dish',
                        'microchip': 'microchip',
                        'broadcast-tower': 'broadcast-tower'
                    };

                    deviceCard.innerHTML = `
                        <div class="device-icon" style="background-color: ${device.iconColor};">
                            <i class="fas fa-${iconClasses[device.icon] || 'server'}"></i>
                        </div>
                        <div class="device-info">
                            <div class="device-name">${device.name}</div>
                            <div class="device-status">
                                <div class="status-indicator ${device.status === 'online' ? 'status-online' : 'status-offline'}"></div>
                                <span>${device.status === 'online' ? '在线' : '离线'}</span>
                            </div>
                            <div class="device-type">${device.type}</div>
                        </div>
                        <button class="group-action-btn" title="从分组中移除">
                            <i class="fas fa-times"></i>
                        </button>
                    `;

                    deviceList.appendChild(deviceCard);
                });
            }

            // 显示新建分组表单
            function showCreateGroupForm() {
                document.getElementById('groupFormPanel').style.display = 'block';
                document.getElementById('groupDetailPanel').style.display = 'none';
                document.getElementById('formTitle').textContent = '新增设备分组';

                // 重置表单
                document.getElementById('groupName').value = '';
                document.getElementById('groupCode').value = '';
                document.getElementById('groupType').value = '1';
                document.getElementById('parentGroup').value = '';
                document.getElementById('intersectionId').value = '';
                document.getElementById('deviceType').value = '';
                document.getElementById('groupDescription').value = '';
                document.getElementById('sortOrder').value = '0';
                document.getElementById('groupStatus').value = '1';
                document.getElementById('isSystemGroup').checked = false;

                // 滚动到表单
                document.getElementById('groupFormPanel').scrollIntoView({ behavior: 'smooth' });
            }

            // 编辑分组
            function editGroup(groupId) {
                const group = deviceGroups.find(g => g.id === groupId);
                if (!group) return;

                document.getElementById('groupFormPanel').style.display = 'block';
                document.getElementById('groupDetailPanel').style.display = 'none';
                document.getElementById('formTitle').textContent = '编辑设备分组';

                // 填充表单数据
                document.getElementById('groupName').value = group.name;
                document.getElementById('groupCode').value = group.code;
                document.getElementById('groupType').value = group.type;
                document.getElementById('parentGroup').value = group.parentId || '';
                document.getElementById('intersectionId').value = group.intersectionId || '';
                document.getElementById('deviceType').value = '';
                document.getElementById('groupDescription').value = group.description;
                document.getElementById('sortOrder').value = '0';
                document.getElementById('groupStatus').value = group.status;
                document.getElementById('isSystemGroup').checked = group.isSystem;

                // 滚动到表单
                document.getElementById('groupFormPanel').scrollIntoView({ behavior: 'smooth' });
            }

            // 显示删除确认模态框
            function showDeleteConfirm(groupId, groupName) {
                document.getElementById('deleteGroupName').textContent = groupName;
                document.getElementById('deleteConfirmModal').style.display = 'flex';

                // 设置删除确认按钮的事件
                const confirmBtn = document.getElementById('confirmDeleteBtn');
                confirmBtn.onclick = function() {
                    deleteGroup(groupId);
                    document.getElementById('deleteConfirmModal').style.display = 'none';
                };
            }

            // 删除分组
            function deleteGroup(groupId) {
                // 在实际应用中，这里应该发送API请求删除分组
                console.log(`删除分组: ${groupId}`);

                // 从数据中移除
                const index = deviceGroups.findIndex(g => g.id === groupId);
                if (index !== -1) {
                    deviceGroups.splice(index, 1);

                    // 更新统计
                    updateStats();

                    // 重新渲染分组树
                    renderGroupTree();

                    // 隐藏详情面板
                    document.getElementById('groupDetailPanel').style.display = 'none';

                    // 显示成功消息
                    alert('分组删除成功！');
                }
            }

            // 更新统计信息
            function updateStats() {
                document.getElementById('totalGroups').textContent = deviceGroups.length;

                const totalDevices = deviceGroups.reduce((sum, group) => sum + group.deviceCount, 0);
                document.getElementById('totalDevices').textContent = totalDevices;

                // 统计覆盖的路口数（假设有intersectionId的分组）
                const coveredIntersections = new Set(deviceGroups.filter(g => g.intersectionId).map(g => g.intersectionId)).size;
                document.getElementById('coveredIntersections').textContent = coveredIntersections;

                // 统计分组类型数
                const groupTypes = new Set(deviceGroups.map(g => g.type)).size;
                document.getElementById('groupTypes').textContent = groupTypes;
            }

            // 搜索分组
            function searchGroups() {
                const searchText = document.getElementById('groupSearch').value.toLowerCase();
                const filterType = document.getElementById('groupTypeFilter').value;

                let filteredGroups = deviceGroups;

                // 按搜索文本过滤
                if (searchText) {
                    filteredGroups = filteredGroups.filter(group => 
                        group.name.toLowerCase().includes(searchText) || 
                        group.code.toLowerCase().includes(searchText) ||
                        (group.description && group.description.toLowerCase().includes(searchText))
                    );
                }

                // 按分组类型过滤
                if (filterType) {
                    filteredGroups = filteredGroups.filter(group => group.type.toString() === filterType);
                }

                // 渲染过滤后的分组树
                renderGroupTree(filteredGroups);
            }

            // 初始化页面
            function initPage() {
                // 渲染分组树
                renderGroupTree();

                // 更新统计信息
                updateStats();

                // 默认选中第一个分组
                if (deviceGroups.length > 0) {
                    selectGroup(deviceGroups[0].id);
                }

                // 绑定事件
                document.getElementById('createGroupBtn').addEventListener('click', showCreateGroupForm);
                document.getElementById('importGroupsBtn').addEventListener('click', function() {
                    alert('批量导入功能：支持从Excel/CSV文件导入设备分组信息');
                });
                document.getElementById('refreshGroupsBtn').addEventListener('click', function() {
                    // 在实际应用中，这里应该重新加载数据
                    renderGroupTree();
                    updateStats();
                    alert('分组数据已刷新');
                });

                document.getElementById('searchGroupsBtn').addEventListener('click', searchGroups);
                document.getElementById('groupSearch').addEventListener('keyup', function(e) {
                    if (e.key === 'Enter') {
                        searchGroups();
                    }
                });

                document.getElementById('editGroupBtn').addEventListener('click', function() {
                    if (selectedGroupId) {
                        editGroup(selectedGroupId);
                    }
                });

                document.getElementById('deleteGroupBtn').addEventListener('click', function() {
                    if (selectedGroupId) {
                        const group = deviceGroups.find(g => g.id === selectedGroupId);
                        if (group) {
                            showDeleteConfirm(selectedGroupId, group.name);
                        }
                    }
                });

                document.getElementById('saveGroupBtn').addEventListener('click', function() {
                    // 获取表单数据
                    const groupName = document.getElementById('groupName').value;
                    const groupCode = document.getElementById('groupCode').value;

                    // 简单验证
                    if (!groupName || !groupCode) {
                        alert('分组名称和分组编码不能为空！');
                        return;
                    }

                    // 在实际应用中，这里应该发送API请求保存分组
                    alert(`保存分组：${groupName} (${groupCode})`);

                    // 隐藏表单，显示分组树
                    document.getElementById('groupFormPanel').style.display = 'none';
                    document.getElementById('groupDetailPanel').style.display = 'block';
                });

                document.getElementById('cancelGroupBtn').addEventListener('click', function() {
                    document.getElementById('groupFormPanel').style.display = 'none';
                    if (selectedGroupId) {
                        document.getElementById('groupDetailPanel').style.display = 'block';
                    }
                });

                // 删除确认模态框事件
                document.getElementById('closeDeleteModal').addEventListener('click', function() {
                    document.getElementById('deleteConfirmModal').style.display = 'none';
                });

                document.getElementById('cancelDeleteBtn').addEventListener('click', function() {
                    document.getElementById('deleteConfirmModal').style.display = 'none';
                });
            }

            // 初始化页面
            initPage();
        });
    </script>
</body>
</html>
```

## 设备分组管理页面功能说明

这个设备分组管理页面实现了以下核心功能：

### 1. 页面结构
- 保持了与2.html完全一致的脚手架架构和样式
- 侧边栏中"设备分组管理"菜单项处于激活状态
- 统一的头部、侧边栏和页脚设计

### 2. 主要功能模块

#### 统计概览
- 显示设备分组总数、设备总数、覆盖路口数和分组类型数
- 使用可视化卡片展示统计数据

#### 分组树形结构
- 展示分层的设备分组结构
- 支持按分组类型、路口、区域等维度组织
- 每个分组显示名称、类型、设备数量等信息
- 支持搜索和筛选功能

#### 分组详情
- 显示选中分组的详细信息
- 包含分组名称、编码、类型、设备数量、状态等
- 提供编辑和删除操作按钮

#### 分组设备列表
- 展示选中分组下的所有设备
- 显示设备名称、类型、状态等信息
- 支持从分组中移除设备

#### 新增/编辑分组表单
- 支持创建新的设备分组
- 支持编辑现有分组信息
- 包含分组名称、编码、类型、父分组等字段

### 3. 交互功能
- 分组选择与高亮显示
- 搜索和筛选分组
- 新建、编辑和删除分组
- 模态框确认删除操作
- 响应式设计，适配不同屏幕尺寸

### 4. 数据模拟
页面中模拟了设备分组和设备数据，包括：
- 7个不同类型的设备分组（按区域、按路口、按设备类型、按厂商等）
- 7个设备实例，分配到不同的分组
- 动态统计数据

这个页面可以直接运行，所有功能在前端实现，没有后端依赖。在实际应用中，需要与后端API对接来获取和保存真实数据。

