        // 渲染设备表格
        function renderDevicesTable(devices) {
            const tableBody = document.getElementById('devicesTableBody');
            tableBody.innerHTML = '';

            devices.forEach(device => {
                const row = document.createElement('tr');

                // 根据状态设置样式
                let statusBadge = '';
                let statusText = '';
                switch(device.status) {
                    case 'online':
                        statusBadge = 'status-online';
                        statusText = '在线';
                        break;
                    case 'offline':
                        statusBadge = 'status-offline';
                        statusText = '离线';
                        break;
                    case 'fault':
                        statusBadge = 'status-fault';
                        statusText = '故障';
                        break;
                    case 'maintenance':
                        statusBadge = 'status-maintenance';
                        statusText = '维护中';
                        break;
                }

                // 根据设备类型设置图标
                let typeIcon = '';
                let typeColor = '';
                switch(device.type) {
                    case 'traffic_light':
                        typeIcon = 'fa-traffic-light';
                        typeColor = '#52c41a';
                        break;
                    case 'camera':
                        typeIcon = 'fa-video';
                        typeColor = '#1890ff';
                        break;
                    case 'radar':
                        typeIcon = 'fa-satellite-dish';
                        typeColor = '#722ed1';
                        break;
                    case 'rsu':
                        typeIcon = 'fa-microchip';
                        typeColor = '#fa8c16';
                        break;
                    case 'controller':
                        typeIcon = 'fa-cogs';
                        typeColor = '#13c2c2';
                        break;
                }

                row.innerHTML = `
                    <td><input type="checkbox" class="device-checkbox" data-id="${device.id}"></td>
                    <td>
                        <div style="display: flex; align-items: center; gap: 10px;">
                            <div class="device-type-icon" style="background-color: ${typeColor};">
                                <i class="fas ${typeIcon}"></i>
                            </div>
                            <div>
                                <div style="font-weight: 500;">${device.name}</div>
                                <div style="font-size: 0.8rem; color: #8c8c8c;">${device.typeName}</div>
                            </div>
                        </div>
                    </td>
                    <td>${device.deviceId}</td>
                    <td>${device.typeName}</td>
                    <td>${device.intersection}</td>
                    <td>${device.ipAddress}</td>
                    <td><span class="status-badge ${statusBadge}">${statusText}</span></td>
                    <td>
                        <div style="display: flex; align-items: center; gap: 5px;">
                            <div>${device.cpuUsage}%</div>
                            <div style="width: 60px; height: 6px; background-color: #f0f0f0; border-radius: 3px; overflow: hidden;">
                                <div style="width: ${device.cpuUsage}%; height: 100%; background-color: ${device.cpuUsage > 80 ? '#ff4d4f' : (device.cpuUsage > 60 ? '#fa8c16' : '#52c41a')};"></div>
                            </div>
                        </div>
                    </td>
                    <td>
                        <div style="display: flex; align-items: center; gap: 5px;">
                            <div>${device.memoryUsage}%</div>
                            <div style="width: 60px; height: 6px; background-color: #f0f0f0; border-radius: 3px; overflow: hidden;">
                                <div style="width: ${device.memoryUsage}%; height: 100%; background-color: ${device.memoryUsage > 80 ? '#ff4d4f' : (device.memoryUsage > 60 ? '#fa8c16' : '#1890ff')};"></div>
                            </div>
                        </div>
                    </td>
                    <td>${device.lastReport}</td>
                    <td>
                        <div class="action-buttons">
                            <button class="action-btn view" data-id="${device.id}" title="查看详情">
                                <i class="fas fa-eye"></i>
                            </button>
                            <button class="action-btn edit" data-id="${device.id}" title="编辑设备">
                                <i class="fas fa-edit"></i>
                            </button>
                            <button class="action-btn delete" data-id="${device.id}" title="删除设备">
                                <i class="fas fa-trash"></i>
                            </button>
                        </div>
                    </td>
                `;

                tableBody.appendChild(row);
            });

            // 绑定查看详情按钮事件
            document.querySelectorAll('.action-btn.view').forEach(btn => {
                btn.addEventListener('click', function() {
                    const deviceId = this.getAttribute('data-id');
                    showDeviceDetail(deviceId);
                });
            });

            // 绑定编辑按钮事件
            document.querySelectorAll('.action-btn.edit').forEach(btn => {
                btn.addEventListener('click', function() {
                    const deviceId = this.getAttribute('data-id');
                    editDevice(deviceId);
                });
            });

            // 绑定删除按钮事件
            document.querySelectorAll('.action-btn.delete').forEach(btn => {
                btn.addEventListener('click', function() {
                    const deviceId = this.getAttribute('data-id');
