        // 初始化筛选功能
        function initFilters() {
            // 应用筛选按钮
            document.getElementById('applyFilterBtn').addEventListener('click', function() {
                applyFilters();
            });

            // 重置筛选按钮
            document.getElementById('resetFilterBtn').addEventListener('click', function() {
                document.getElementById('deviceTypeFilter').value = '';
                document.getElementById('deviceStatusFilter').value = '';
                document.getElementById('intersectionFilter').value = '';
                document.getElementById('deviceNameFilter').value = '';
                renderDevicesTable(devicesData);
            });

            // 筛选输入框回车事件
            document.getElementById('deviceNameFilter').addEventListener('keyup', function(event) {
                if (event.key === 'Enter') {
                    applyFilters();
                }
            });
        }

        // 应用筛选
        function applyFilters() {
            const typeFilter = document.getElementById('deviceTypeFilter').value;
            const statusFilter = document.getElementById('deviceStatusFilter').value;
            const intersectionFilter = document.getElementById('intersectionFilter').value;
            const nameFilter = document.getElementById('deviceNameFilter').value.toLowerCase();

            const filteredDevices = devicesData.filter(device => {
                // 设备类型筛选
                if (typeFilter && device.type !== typeFilter) {
                    return false;
                }

                // 设备状态筛选
                if (statusFilter && device.status !== statusFilter) {
                    return false;
                }

                // 所属路口筛选
                if (intersectionFilter) {
                    const intersectionValue = device.intersection.includes('路口A') ? 'int001' : 
                                            device.intersection.includes('路口B') ? 'int002' : 
                                            device.intersection.includes('路口C') ? 'int003' : 
                                            device.intersection.includes('路口D') ? 'int004' : '';
                    if (intersectionValue !== intersectionFilter) {
                        return false;
                    }
                }

                // 设备名称筛选
                if (nameFilter && !device.name.toLowerCase().includes(nameFilter) && 
                    !device.deviceId.toLowerCase().includes(nameFilter)) {
                    return false;
                }

                return true;
            });

            renderDevicesTable(filteredDevices);

            // 更新分页信息
            document.querySelector('.pagination-info').textContent = `显示 1 到 ${Math.min(filteredDevices.length, 10)} 条，共 ${filteredDevices.length} 条记录`;
        }

        // 初始化按钮事件
        function initButtonEvents() {
            // 刷新按钮
            document.getElementById('refreshBtn').addEventListener('click', function() {
                this.querySelector('i').className = 'fas fa-spinner fa-spin';
                setTimeout(() => {
                    this.querySelector('i').className = 'fas fa-sync-alt';
