            });

            // 批量操作按钮
            document.getElementById('batchOperationBtn').addEventListener('click', function() {
                const selectedCount = document.querySelectorAll('.device-checkbox:checked').length;
                if (selectedCount === 0) {
                    alert('请先选择要操作的设备');
                } else {
                    alert(`已选择 ${selectedCount} 台设备，可进行批量操作`);
                }
            });

            // 全选复选框
            document.getElementById('selectAll').addEventListener('change', function() {
                const checkboxes = document.querySelectorAll('.device-checkbox');
                checkboxes.forEach(checkbox => {
                    checkbox.checked = this.checked;
                });
            });

            // 分页按钮
            document.getElementById('prevPageBtn').addEventListener('click', function() {
                alert('切换到上一页');
            });

            document.getElementById('nextPageBtn').addEventListener('click', function() {
                alert('切换到下一页');
            });

            // 分页数字
            document.querySelectorAll('.page-number').forEach(number => {
                number.addEventListener('click', function() {
                    document.querySelectorAll('.page-number').forEach(n => n.classList.remove('active'));
                    this.classList.add('active');
                    alert(`切换到第 ${this.textContent} 页`);
                });
            });
        }

        // 初始化模态框事件
        function initModalEvents() {
            // 设备详情模态框
            const detailModal = document.getElementById('deviceDetailModal');
            const closeDetailModal = document.getElementById('closeDetailModal');
            const closeDetailBtn = document.getElementById('closeDetailBtn');

            closeDetailModal.addEventListener('click', function() {
                detailModal.classList.remove('active');
            });

            closeDetailBtn.addEventListener('click', function() {
                detailModal.classList.remove('active');
            });

            // 点击模态框外部关闭
            detailModal.addEventListener('click', function(event) {
                if (event.target === this) {
                    this.classList.remove('active');
                }
            });

            // 编辑设备按钮
            document.getElementById('editDeviceBtn').addEventListener('click', function() {
                detailModal.classList.remove('active');
                setTimeout(() => {
                    editDevice(currentDevice.id);
                }, 300);
            });

            // 重启设备按钮
            document.getElementById('restartDeviceBtn').addEventListener('click', function() {
                if (confirm(`确定要重启设备 "${currentDevice.name}" 吗？`)) {
                    alert(`设备 "${currentDevice.name}" 重启命令已下发`);
                    detailModal.classList.remove('active');
                }
            });

            // 设备编辑模态框
            const editModal = document.getElementById('deviceEditModal');
            const closeEditModal = document.getElementById('closeEditModal');
            const cancelEditBtn = document.getElementById('cancelEditBtn');

            closeEditModal.addEventListener('click', function() {
                editModal.classList.remove('active');
            });

            cancelEditBtn.addEventListener('click', function() {
                editModal.classList.remove('active');
            });

            // 点击模态框外部关闭
            editModal.addEventListener('click', function(event) {
                if (event.target === this) {
                    this.classList.remove('active');
                }
            });

            // 保存设备按钮
            document.getElementById('saveDeviceBtn').addEventListener('click', function() {
                saveDevice();
            });
        }

        // 显示设备详情
        function showDeviceDetail(deviceId) {
            currentDevice = devicesData.find(device => device.id === parseInt(deviceId));
            if (!currentDevice) return;

            // 填充详情数据
            document.getElementById('detail-deviceName').textContent = currentDevice.name;
            document.getElementById('detail-deviceId').textContent = currentDevice.deviceId;
            document.getElementById('detail-deviceType').textContent = currentDevice.typeName;
            document.getElementById('detail-intersection').textContent = currentDevice.intersection;
            document.getElementById('detail-ipAddress').textContent = currentDevice.ipAddress;
            document.getElementById('detail-macAddress').textContent = currentDevice.macAddress;
            document.getElementById('detail-manufacturer').textContent = currentDevice.manufacturer;
            document.getElementById('detail-deviceModel').textContent = currentDevice.deviceModel;
            document.getElementById('detail-firmwareVersion').textContent = currentDevice.firmwareVersion;
            document.getElementById('detail-onlineTime').textContent = currentDevice.onlineTime;
            document.getElementById('detail-cpuUsage').textContent = currentDevice.cpuUsage + '%';
            document.getElementById('detail-memoryUsage').textContent = currentDevice.memoryUsage + '%';
            document.getElementById('detail-networkLatency').textContent = currentDevice.networkLatency;
            document.getElementById('detail-temperature').textContent = currentDevice.temperature;
            document.getElementById('detail-lastHeartbeat').textContent = currentDevice.lastReport;

            // 设置状态
            let statusText = '';
            let statusClass = '';
            switch(currentDevice.status) {
                case 'online':
                    statusText = '在线';
                    statusClass = 'status-online';
                    break;
                case 'offline':
                    statusText = '离线';
                    statusClass = 'status-offline';
                    break;
                case 'fault':
                    statusText = '故障';
                    statusClass = 'status-fault';
                    break;
                case 'maintenance':
                    statusText = '维护中';
                    statusClass = 'status-maintenance';
                    break;
            }
            document.getElementById('detail-status').textContent = statusText;
            document.getElementById('detail-status').className = `status-badge ${statusClass}`;

            // 生成资源使用趋势图
            generateMetricsChart();

            // 显示模态框
            document.getElementById('deviceDetailModal').classList.add('active');
        }

        // 生成资源使用趋势图
        function generateMetricsChart() {
            const metricsChart = document.getElementById('metricsChart');
            metricsChart.innerHTML = '';

            // 模拟过去6小时的数据
            const hours = ['10:00', '11:00', '12:00', '13:00', '14:00', '15:00'];
            const cpuData = [18, 22, 25, 30, 15, 20];
            const memoryData = [35, 38, 40, 42, 32, 35];

            // 找出最大值用于归一化
            const maxCpu = Math.max(...cpuData);
            const maxMemory = Math.max(...memoryData);
            const maxValue = Math.max(maxCpu, maxMemory);

            // 创建CPU使用率柱状图
            hours.forEach((hour, index) => {
                const barHeight = (cpuData[index] / maxValue) * 100;
                const bar = document.createElement('div');
                bar.className = 'metric-bar';
                bar.style.height = `${barHeight}%`;
                bar.style.backgroundColor = cpuData[index] > 80 ? '#ff4d4f' : (cpuData[index] > 60 ? '#fa8c16' : '#52c41a');

                const valueLabel = document.createElement('div');
                valueLabel.className = 'metric-value';
                valueLabel.textContent = `${cpuData[index]}%`;

                const hourLabel = document.createElement('div');
                hourLabel.className = 'metric-label';
                hourLabel.textContent = hour;

                bar.appendChild(valueLabel);
                bar.appendChild(hourLabel);
                metricsChart.appendChild(bar);
            });
        }

        // 显示新增设备模态框
        function showAddDeviceModal() {
            isEditMode = false;
            document.getElementById('editModalTitle').textContent = '新增设备';

            // 重置表单
            document.getElementById('deviceForm').reset();

            // 显示模态框
            document.getElementById('deviceEditModal').classList.add('active');
        }

        // 编辑设备
        function editDevice(deviceId) {
            isEditMode = true;
            currentDevice = devicesData.find(device => device.id === parseInt(deviceId));
            if (!currentDevice) return;

            document.getElementById('editModalTitle').textContent = '编辑设备';

            // 填充表单数据
            document.getElementById('edit-deviceName').value = currentDevice.name;
            document.getElementById('edit-deviceType').value = currentDevice.type;

            // 设置所属路口
            let intersectionValue = '';
            if (currentDevice.intersection.includes('路口A')) intersectionValue = 'int001';
            else if (currentDevice.intersection.includes('路口B')) intersectionValue = 'int002';
            else if (currentDevice.intersection.includes('路口C')) intersectionValue = 'int003';
            else if (currentDevice.intersection.includes('路口D')) intersectionValue = 'int004';

            document.getElementById('edit-intersection').value = intersectionValue;
            document.getElementById('edit-ipAddress').value = currentDevice.ipAddress;
            document.getElementById('edit-port').value = '8080';
            document.getElementById('edit-protocol').value = 'harmony_bus';
            document.getElementById('edit-manufacturer').value = currentDevice.manufacturer;
            document.getElementById('edit-deviceModel').value = currentDevice.deviceModel;
            document.getElementById('edit-description').value = `这是${currentDevice.name}的描述信息`;

            // 显示模态框
            document.getElementById('deviceEditModal').classList.add('active');
        }

        // 保存设备
        function saveDevice() {
            // 验证表单
            const deviceName = document.getElementById('edit-deviceName').value;
            const deviceType = document.getElementById('edit-deviceType').value;
            const intersection = document.getElementById('edit-intersection').value;
            const ipAddress = document.getElementById('edit-ipAddress').value;

            if (!deviceName || !deviceType || !intersection || !ipAddress) {
                alert('请填写所有必填字段（标*的字段）');
                return;
            }

            // 在实际应用中，这里应该发送数据到服务器
            if (isEditMode) {
                alert(`设备 "${deviceName}" 信息已更新`);
            } else {
                alert(`设备 "${deviceName}" 已成功添加`);
            }

            // 关闭模态框
            document.getElementById('deviceEditModal').classList.remove('active');

            // 刷新设备列表
            setTimeout(() => {
                alert('设备列表已刷新');
            }, 500);
        }

        // 删除设备
        function deleteDevice(deviceId) {
            const device = devicesData.find(device => device.id === parseInt(deviceId));
            if (!device) return;

            if (confirm(`确定要删除设备 "${device.name}" 吗？此操作不可恢复。`)) {
                // 在实际应用中，这里应该发送删除请求到服务器
                alert(`设备 "${device.name}" 已删除`);

                // 从设备列表中移除
                const index = devicesData.findIndex(d => d.id === parseInt(deviceId));
                if (index !== -1) {
                    devicesData.splice(index, 1);
                    renderDevicesTable(devicesData);
                }
            }
        }

        // 更新全选复选框状态
        function updateSelectAllCheckbox() {
            const checkboxes = document.querySelectorAll('.device-checkbox');
            const selectAllCheckbox = document.getElementById('selectAll');

            const allChecked = Array.from(checkboxes).every(checkbox => checkbox.checked);
            const anyChecked = Array.from(checkboxes).some(checkbox => checkbox.checked);

            selectAllCheckbox.checked = allChecked;
            selectAllCheckbox.indeterminate = anyChecked && !allChecked;
        }
    </script>
</body>
</html>
