                const refreshedData = [...videoStreamData];
                refreshedData.forEach(item => {
                    // 模拟数据变化
                    item.bitrate = Math.max(500, item.bitrate + Math.floor(Math.random() * 200 - 100));
                    item.framerate = Math.max(5, item.framerate + Math.floor(Math.random() * 5 - 2));
                    item.stutter = Math.max(0, item.stutter + Math.floor(Math.random() * 3 - 1));
                    item.packetLoss = Math.max(0, item.packetLoss + (Math.random() * 0.5 - 0.25));
                    item.latency = Math.max(50, item.latency + Math.floor(Math.random() * 100 - 50));

                    // 重新计算质量评分
                    item.qualityScore = calculateQualityScore(item);

                    // 更新状态
                    item.status = determineStatus(item);
