                },
                {
                    id: 'CAM-002',
                    name: '南进口摄像头',
                    position: [31.2298, 121.474],
                    status: 'online',
                    resolution: '1280×720',
                    fps: 30,
                    protocol: 'RTSP',
                    intersection: '路口A',
                    location: '南进口'
                },
                {
                    id: 'CAM-003',
                    name: '东进口摄像头',
                    position: [31.2304, 121.4752],
                    status: 'online',
                    resolution: '1920×1080',
                    fps: 25,
                    protocol: 'RTSP',
                    intersection: '路口A',
                    location: '东进口'
                },
                {
                    id: 'CAM-004',
                    name: '西进口摄像头',
                    position: [31.2304, 121.4723],
