            const saveConfigBtn = document.getElementById('saveConfigBtn');

            closeConfigModalBtn.addEventListener('click', function() {
                configModal.style.display = 'none';
            });

            cancelConfigBtn.addEventListener('click', function() {
                configModal.style.display = 'none';
            });

