                            ${camera.status === 'online' ? '点击播放实时视频' : '设备离线'}
                        </div>
                        <div class="video-controls">
                            <button class="video-control-btn" onclick="openVideoModal('${camera.id}')">
                                <i class="fas fa-play"></i>
                            </button>
                            <button class="video-control-btn" onclick="openConfigModal('${camera.id}')">
                                <i class="fas fa-cog"></i>
                            </button>
                        </div>
                    </div>
                    <div class="video-info">
                        <div class="video-info-row">
                            <span class="video-info-label">设备ID:</span>
                            <span class="video-info-value">${camera.id}</span>
                        </div>
                        <div class="video-info-row">
                            <span class="video-info-label">分辨率:</span>
                            <span class="video-info-value">${camera.resolution}</span>
                        </div>
                        <div class="video-info-row">
                            <span class="video-info-label">位置:</span>
                            <span class="video-info-value">${camera.location}</span>
                        </div>
                    </div>
                `;

                // 添加点击事件
                videoCard.addEventListener('click', function(e) {
                    if (!e.target.closest('.video-control-btn')) {
                        openVideoModal(camera.id);
                    }
                });

                videoGrid.appendChild(videoCard);
            });
        }

        // 打开视频播放弹窗
        function openVideoModal(cameraId) {
            const camera = cameras.find(c => c.id === cameraId);
            if (!camera) return;

            const videoModal = document.getElementById('videoModal');
            const videoPlayer = document.getElementById('videoPlayer');
            const streamStatus = document.getElementById('streamStatus');
            const playPauseBtn = document.getElementById('playPauseBtn');

            // 更新弹窗标题
            document.querySelector('#videoModal .modal-title').textContent = `实时视频 - ${camera.name}`;

            // 设置视频源（模拟）
            videoPlayer.src = camera.status === 'online' ? 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4' : '';

            // 更新视频详情
            const videoDetails = document.getElementById('videoDetails');
            videoDetails.innerHTML = `
                <div class="detail-item">
                    <div class="detail-label">设备名称</div>
                    <div class="detail-value">${camera.name}</div>
                </div>
                <div class="detail-item">
                    <div class="detail-label">设备ID</div>
                    <div class="detail-value">${camera.id}</div>
                </div>
                <div class="detail-item">
                    <div class="detail-label">路口</div>
                    <div class="detail-value">${camera.intersection}</div>
                </div>
                <div class="detail-item">
                    <div class="detail-label">安装位置</div>
                    <div class="detail-value">${camera.location}</div>
                </div>
                <div class="detail-item">
                    <div class="detail-label">视频分辨率</div>
                    <div class="detail-value">${camera.resolution}</div>
                </div>
                <div class="detail-item">
                    <div class="detail-label">帧率</div>
                    <div class="detail-value">${camera.fps} FPS</div>
                </div>
                <div class="detail-item">
                    <div class="detail-label">传输协议</div>
                    <div class="detail-value">${camera.protocol}</div>
                </div>
                <div class="detail-item">
                    <div class="detail-label">设备状态</div>
                    <div class="detail-value">${camera.status === 'online' ? '<span style="color:#52c41a;">在线</span>' : '<span style="color:#fa541c;">离线</span>'}</div>
                </div>
            `;

            // 显示弹窗
            videoModal.style.display = 'flex';

            // 如果设备在线，自动播放视频
            if (camera.status === 'online') {
                videoPlayer.play();
                playPauseBtn.innerHTML = '<i class="fas fa-pause"></i>';
                streamStatus.textContent = '播放中';
            } else {
                streamStatus.textContent = '设备离线';
            }
        }

        // 打开视频配置弹窗
        function openConfigModal(cameraId) {
            const camera = cameras.find(c => c.id === cameraId);
            if (!camera) return;

            const configModal = document.getElementById('configModal');
            document.getElementById('configDeviceName').textContent = camera.name;

            // 显示弹窗
            configModal.style.display = 'flex';
        }
    </script>
</body>
</html>
```

## 功能说明

这个"地图实时视频"页面包含以下功能：

### 1. 地图视图
- 使用Leaflet地图库展示交通路口区域
- 在地图上标记摄像头位置（蓝色表示在线，灰色表示离线）
- 点击摄像头图标可以查看设备信息并播放实时视频

### 2. 视频列表
- 右侧显示所有摄像头的视频预览卡片
- 卡片显示摄像头状态（在线/离线）、设备ID、分辨率、位置等信息
- 点击卡片可以打开视频播放弹窗

### 3. 视频播放弹窗
- 点击摄像头标记或视频卡片打开弹窗
- 显示实时视频播放器（使用示例视频）
- 提供播放/暂停、音量控制、全屏等控制按钮
- 显示摄像头详细信息（设备ID、位置、分辨率、帧率等）
- 底部提供截图、录像、视频配置等功能按钮

### 4. 视频配置弹窗
- 二级弹窗，用于配置摄像头参数
- 可设置视频分辨率、帧率、码率、编码方式、日夜模式等参数

### 5. 操作按钮
- 顶部提供多画面模式、批量录像、刷新视频等操作按钮
- 地图工具栏提供放大、缩小、重置视图、显示所有摄像头等功能

### 6. 响应式设计
- 适配不同屏幕尺寸，在移动设备上也能良好显示

页面保持了与2.html一致的脚手架架构和样式，并按照要求使用弹窗展示二级页面（视频播放和配置界面）。

