            // 渲染相位配置表格
            function renderPhaseTable(phaseData) {
                const tableBody = document.getElementById('phaseTableBody');
                tableBody.innerHTML = '';

                phaseData.forEach((phase, index) => {
                    const row = document.createElement('tr');

                    // 根据状态设置样式
                    let statusBadge = '';
                    if (phase.isEnabled) {
                        statusBadge = '<span class="status-badge status-active">已启用</span>';
                    } else if (phase.deviceId.includes('LEGACY')) {
                        statusBadge = '<span class="status-badge status-error">配置异常</span>';
                    } else {
                        statusBadge = '<span class="status-badge status-inactive">未启用</span>';
                    }

                    // 设置灯色样式
                    let lightColorBadge = '';
                    if (phase.lightColor === 'RED') {
                        lightColorBadge = `<span style="color: #ff4d4f;">${phase.lightColorText}</span>`;
                    } else if (phase.lightColor === 'YELLOW') {
                        lightColorBadge = `<span style="color: #faad14;">${phase.lightColorText}</span>`;
                    } else {
                        lightColorBadge = `<span style="color: #52c41a;">${phase.lightColorText}</span>`;
                    }

                    row.innerHTML = `
                        <td>${index + 1}</td>
                        <td>${phase.phaseNumber}</td>
                        <td>${phase.deviceId}<br><small>${phase.deviceName}</small></td>
                        <td>${phase.intersectionName}</td>
                        <td>${phase.directionText}</td>
                        <td>${lightColorBadge}</td>
                        <td>${phase.duration}</td>
                        <td>${phase.yellowDuration}</td>
                        <td>${statusBadge}</td>
                        <td>
