                                </button>
                                <button class="action-btn edit" onclick="editPhaseConfig(${phase.id})" title="编辑配置">
                                    <i class="fas fa-edit"></i>
                                </button>
                                <button class="action-btn delete" onclick="deletePhaseConfig(${phase.id})" title="删除配置">
                                    <i class="fas fa-trash"></i>
                                </button>
                            </div>
                        </td>
                    `;

                    tableBody.appendChild(row);
                });
            }

            // 渲染操作记录表格
            function renderOperationTable(operationData) {
                const tableBody = document.getElementById('operationTableBody');
                tableBody.innerHTML = '';

                operationData.forEach((log, index) => {
                    const row = document.createElement('tr');

                    // 根据结果设置样式
                    let resultBadge = '';
                    if (log.result === '成功') {
                        resultBadge = '<span class="status-badge status-active">成功</span>';
                    } else if (log.result === '部分成功') {
                        resultBadge = '<span class="status-badge status-inactive">部分成功</span>';
                    } else {
                        resultBadge = '<span class="status-badge status-error">失败</span>';
                    }

                    row.innerHTML = `
                        <td>${log.time}</td>
                        <td>${log.operationType}</td>
                        <td>${log.phaseNumber}</td>
                        <td>${log.deviceId}</td>
                        <td>${log.operator}</td>
                        <td>${resultBadge}</td>
                    `;

                    tableBody.appendChild(row);
                });
