            renderPhaseTable(phaseConfigs);
            renderOperationTable(operationLogs);

            // 筛选功能
            document.getElementById('filterBtn').addEventListener('click', function() {
                const intersectionFilter = document.getElementById('intersectionFilter').value;
                const deviceTypeFilter = document.getElementById('deviceTypeFilter').value;
                const statusFilter = document.getElementById('statusFilter').value;

                let filteredData = phaseConfigs;

                if (intersectionFilter) {
                    filteredData = filteredData.filter(phase => phase.intersectionId === intersectionFilter);
                }

                if (deviceTypeFilter) {
                    if (deviceTypeFilter === 'HARMONY_TRAFFIC_LIGHT') {
                        filteredData = filteredData.filter(phase => phase.deviceId.includes('HARMONY'));
                    } else if (deviceTypeFilter === 'STANDARD_SIGNAL_LIGHT') {
                        filteredData = filteredData.filter(phase => phase.deviceId.includes('STANDARD'));
                    } else if (deviceTypeFilter === 'LEGACY_SIGNAL_CONTROLLER') {
                        filteredData = filteredData.filter(phase => phase.deviceId.includes('LEGACY'));
                    }
                }

                if (statusFilter) {
                    if (statusFilter === 'active') {
                        filteredData = filteredData.filter(phase => phase.isEnabled === true);
                    } else if (statusFilter === 'inactive') {
                        filteredData = filteredData.filter(phase => phase.isEnabled === false);
                    } else if (statusFilter === 'error') {
                        filteredData = filteredData.filter(phase => phase.deviceId.includes('LEGACY'));
                    }
                }

                renderPhaseTable(filteredData);
            });

