                const deviceId = document.getElementById('deviceId').value;
                const intersectionId = document.getElementById('intersectionId').value;
                const direction = document.getElementById('direction').value;
                const lightColor = document.getElementById('lightColor').value;
                const duration = document.getElementById('duration').value;

                if (!phaseNumber || !deviceId || !intersectionId || !direction || !lightColor || !duration) {
                    alert('请填写所有必填字段');
                    return;
                }

                // 获取表单数据
                const phaseData = {
                    phaseNumber: phaseNumber,
                    deviceId: deviceId,
                    intersectionId: intersectionId,
                    direction: direction,
                    lightColor: lightColor,
                    duration: parseInt(duration),
                    yellowDuration: parseInt(document.getElementById('yellowDuration').value),
                    allRedDuration: parseInt(document.getElementById('allRedDuration').value),
                    priority: parseInt(document.getElementById('priority').value),
                    isEnabled: document.getElementById('isEnabled').value === 'true',
                    configJson: document.getElementById('configJson').value
                };

                // 模拟保存操作
                if (currentPhaseId) {
                    // 编辑现有配置
                    alert(`相位配置 ${phaseNumber} 已更新`);
                } else {
                    // 新增配置
                    alert(`新增相位配置 ${phaseNumber} 成功`);
                }

                // 关闭弹框
                phaseModal.classList.remove('active');

                // 刷新表格（在实际应用中，这里应该重新加载数据）
                setTimeout(() => {
                    alert('相位配置列表已更新');
                }, 500);
            });

            // 批量下发按钮
            document.getElementById('batchApplyBtn').addEventListener('click', function() {
                // 生成批量选择列表
                const batchSelection = document.getElementById('batchSelection');
                batchSelection.innerHTML = '';

                phaseConfigs.forEach(phase => {
                    const div = document.createElement('div');
                    div.style.marginBottom = '5px';
                    div.innerHTML = `
                        <input type="checkbox" id="phase_${phase.id}" value="${phase.id}" checked>
                        <label for="phase_${phase.id}">相位${phase.phaseNumber} - ${phase.deviceId} (${phase.directionText})</label>
                    `;
                    batchSelection.appendChild(div);
                });

                batchModal.classList.add('active');
            });

            // 确认批量下发
            document.getElementById('confirmBatchBtn').addEventListener('click', function() {
                const selectedPhases = Array.from(document.querySelectorAll('#batchSelection input:checked'))
                    .map(input => input.value);

                if (selectedPhases.length === 0) {
                    alert('请至少选择一项相位配置进行下发');
                    return;
                }

                const targetDevices = document.getElementById('targetDevices').value;
                const deployTime = document.querySelector('input[name="deployTime"]:checked').value;
                const scheduledTime = document.getElementById('scheduledTime').value;

                // 模拟批量下发操作
                let message = `正在下发 ${selectedPhases.length} 个相位配置`;
                if (targetDevices) {
                    message += `到指定设备`;
                }

                if (deployTime === 'scheduled' && scheduledTime) {
                    message += `，计划于 ${scheduledTime} 执行`;
                } else {
                    message += '，立即执行';
                }

                alert(message);

                // 关闭弹框
                batchModal.classList.remove('active');

                // 模拟下发完成
                setTimeout(() => {
                    alert('相位配置批量下发完成！');
                }, 1000);
            });

            // 初始设置定时下发时间
            const now = new Date();
            const futureTime = new Date(now.getTime() + 60 * 60 * 1000); // 1小时后
            const formattedTime = futureTime.toISOString().slice(0, 16);
            document.getElementById('scheduledTime').value = formattedTime;
        });

