            border: 1px solid #f0f0f0;
            border-radius: 4px;
            padding: 15px;
            font-family: monospace;
            font-size: 0.9rem;
            max-height: 200px;
            overflow-y: auto;
            white-space: pre-wrap;
        }

        .state-comparison {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 20px;
        }

        .state-panel {
            border: 1px solid #f0f0f0;
            border-radius: 6px;
            overflow: hidden;
        }

        .state-panel-title {
            background-color: #fafafa;
            padding: 10px 15px;
            font-weight: 600;
            color: #262626;
            border-bottom: 1px solid #f0f0f0;
        }

        .state-panel-content {
            padding: 15px;
            max-height: 200px;
            overflow-y: auto;
        }

        /* 折叠状态下的样式 */
        .sidebar.collapsed .section-header {
            padding: 12px 15px;
            justify-content: center;
        }

        .sidebar.collapsed .section-title span,
        .sidebar.collapsed .section-arrow {
            display: none;
        }

        .sidebar.collapsed .section-title {
