                display: none;
            }

            .main-content {
                margin-left: 0;
                margin-top: 0;
            }

            .main-content.expanded {
                margin-left: 0;
            }

            .dashboard {
                grid-template-columns: repeat(2, 1fr);
            }

            .filter-panel {
