        // 初始化模拟数据
        function initMockData() {
            // 生成模拟日志数据
            const mockLogs = [];
            const logIds = ['LOG_001', 'LOG_002', 'LOG_003', 'LOG_004', 'LOG_005', 'LOG_006', 'LOG_007', 'LOG_008', 'LOG_009', 'LOG_010'];
            const deviceNames = ['鸿蒙信号灯-01', '智能摄像机-03', '边缘计算盒子-02', '雷视一体机-05', '协议适配器-01', '鸿蒙化交通信号控制机', 'RSU-03', '智能摄像机-07', '信号灯控制器-02', '边缘服务器-01'];
            const operators = ['admin', 'user01', 'user02', 'user03', 'sysadmin', 'auditor', 'operator01', 'operator02', 'maintenance', 'security'];
            const operationTypes = ['DEPLOY_STRATEGY', 'UPDATE_CONFIG', 'CONTROL_COMMAND', 'DATA_QUERY', 'SYSTEM_MAINTENANCE', 'SECURITY_OPERATION'];
            const resultStatuses = ['SUCCESS', 'FAILED', 'PARTIAL_SUCCESS', 'TIMEOUT', 'UNAUTHORIZED'];
            const riskLevels = ['LOW', 'MEDIUM', 'HIGH', 'CRITICAL'];

            const descriptions = [
                '部署AI交通流量预测策略到边缘设备',
                '更新信号灯相位配置参数',
                '发送紧急红灯控制命令',
                '查询路口历史车流量数据',
                '重启边缘计算设备服务',
                '更新安全证书和访问权限',
                '下发车辆识别算法模型',
                '配置视频流质量监测阈值',
                '调整信号灯配时方案',
                '执行系统备份和恢复操作'
            ];

            // 生成10条模拟日志
            for (let i = 0; i < 10; i++) {
                const operationType = operationTypes[Math.floor(Math.random() * operationTypes.length)];
                const resultStatus = resultStatuses[Math.floor(Math.random() * resultStatuses.length)];
                const riskLevel = riskLevels[Math.floor(Math.random() * riskLevels.length)];

                // 根据结果状态和操作类型调整风险等级
                let adjustedRiskLevel = riskLevel;
                if (resultStatus === 'FAILED' && operationType === 'CONTROL_COMMAND') {
                    adjustedRiskLevel = 'HIGH';
                } else if (resultStatus === 'UNAUTHORIZED') {
                    adjustedRiskLevel = 'CRITICAL';
                } else if (resultStatus === 'SUCCESS') {
                    adjustedRiskLevel = 'LOW';
                }

                mockLogs.push({
                    id: logIds[i],
                    logId: `LOG_${Date.now()}_${i}`,
                    deviceId: `DEVICE_${i + 100}`,
                    deviceName: deviceNames[i],
                    intersectionId: i % 3 + 1,
                    intersectionName: `路口${String.fromCharCode(65 + i % 3)}`,
                    operationType: operationType,
                    operationName: `${operationTypeMap[operationType]}操作`,
                    operationParams: JSON.stringify({
                        strategyId: i % 2 === 0 ? 'STRATEGY_001' : null,
                        configVersion: `v${i % 3 + 1}.${i % 5}`,
                        command: i % 2 === 0 ? 'SET_RED_LIGHT' : 'SET_GREEN_LIGHT',
                        duration: 30 + i * 5,
                        priority: i % 3 + 1
                    }, null, 2),
                    operator: operators[i],
                    operatorIp: `192.168.1.${i + 10}`,
                    operationTime: new Date(Date.now() - i * 3600000).toISOString(),
                    operationDuration: 500 + i * 100,
                    resultStatus: resultStatus,
                    resultMessage: resultStatus === 'SUCCESS' ? '操作执行成功' : '操作执行失败',
                    errorCode: resultStatus !== 'SUCCESS' ? `ERR_${i}${i}${i}` : null,
                    errorMessage: resultStatus !== 'SUCCESS' ? '设备响应超时，请检查网络连接' : null,
                    riskLevel: adjustedRiskLevel,
                    riskReason: getRiskReason(adjustedRiskLevel, operationType),
                    sessionId: `SESSION_${i}${i}${i}`,
                    requestId: `REQ_${Date.now()}_${i}`,
                    resourceChanges: JSON.stringify({
                        configUpdated: i % 2 === 0,
                        strategyDeployed: i % 3 === 0,
                        deviceRestarted: i % 4 === 0,
                        permissionsChanged: i % 5 === 0
                    }, null, 2),
                    beforeState: JSON.stringify({
                        deviceStatus: 'online',
                        configVersion: 'v1.0',
                        trafficLightState: 'GREEN',
                        cpuUsage: 45 + i,
                        memoryUsage: 60 + i
                    }, null, 2),
                    afterState: JSON.stringify({
                        deviceStatus: resultStatus === 'SUCCESS' ? 'online' : 'error',
                        configVersion: resultStatus === 'SUCCESS' ? 'v1.1' : 'v1.0',
                        trafficLightState: i % 2 === 0 ? 'RED' : 'GREEN',
                        cpuUsage: 40 + i,
                        memoryUsage: 55 + i
                    }, null, 2),
                    auditMarks: i % 3 === 0 ? 'HIGH_PRIORITY' : 'NORMAL',
                    description: descriptions[i]
                });
            }

            logsData = mockLogs;
            filteredLogsData = [...logsData];
        }

        // 获取风险原因
        function getRiskReason(riskLevel, operationType) {
            switch(riskLevel) {
                case 'CRITICAL':
                    return '未授权操作，可能存在安全风险';
                case 'HIGH':
                    return operationType === 'CONTROL_COMMAND' ? '控制命令执行失败，可能影响交通' : '高风险操作，需要关注';
                case 'MEDIUM':
                    return '操作耗时较长，需要优化';
                default:
                    return '正常操作';
            }
        }

