        // 应用筛选条件
        function applyFilters() {
            const operationType = document.getElementById('operationTypeFilter').value;
            const riskLevel = document.getElementById('riskLevelFilter').value;
            const resultStatus = document.getElementById('resultStatusFilter').value;
            const operator = document.getElementById('operatorFilter').value.toLowerCase();
            const startDate = document.getElementById('startDateFilter').value;
            const endDate = document.getElementById('endDateFilter').value;
            const globalSearch = document.getElementById('globalSearch').value.toLowerCase();

            filteredLogsData = logsData.filter(log => {
                // 操作类型筛选
                if (operationType && log.operationType !== operationType) {
                    return false;
                }

                // 风险等级筛选
                if (riskLevel && log.riskLevel !== riskLevel) {
                    return false;
                }

                // 结果状态筛选
                if (resultStatus && log.resultStatus !== resultStatus) {
                    return false;
                }

                // 操作员筛选
                if (operator && !log.operator.toLowerCase().includes(operator)) {
                    return false;
                }

                // 时间范围筛选
                const logDate = new Date(log.operationTime).toISOString().split('T')[0];
                if (startDate && logDate < startDate) {
                    return false;
                }
                if (endDate && logDate > endDate) {
                    return false;
                }

                // 全局搜索
                if (globalSearch) {
                    const searchFields = [
                        log.id,
                        log.deviceName,
                        log.description,
                        log.operator,
                        operationTypeMap[log.operationType]
                    ].join(' ').toLowerCase();

                    if (!searchFields.includes(globalSearch)) {
                        return false;
                    }
                }

                return true;
            });

            // 更新表格
            updateLogsTable();
        }

