        function updateSelectedCount() {
            const selectAllBtn = document.getElementById('selectAllBtn');
            selectAllBtn.innerHTML = `<i class="fas fa-check-square"></i> 已选 ${selectedLogIds.size} 条`;
        }

        // 绑定事件监听器
        function bindEventListeners() {
            // 应用筛选按钮
            document.getElementById('applyFilterBtn').addEventListener('click', applyFilters);

            // 重置筛选按钮
            document.getElementById('resetFilterBtn').addEventListener('click', resetFilters);

            // 全局搜索输入框（回车触发筛选）
            document.getElementById('globalSearch').addEventListener('keyup', function(event) {
                if (event.key === 'Enter') {
                    applyFilters();
                }
            });

            // 全选复选框
            document.getElementById('selectAllCheckbox').addEventListener('change', toggleSelectAll);

            // 全选按钮
            document.getElementById('selectAllBtn').addEventListener('click', function() {
                const selectAllCheckbox = document.getElementById('selectAllCheckbox');
                selectAllCheckbox.checked = !selectAllCheckbox.checked;
                toggleSelectAll();
            });

            // 导出选中日志按钮
            document.getElementById('exportSelectedBtn').addEventListener('click', exportSelectedLogs);

            // 导出全部日志按钮
            document.getElementById('exportAllBtn').addEventListener('click', exportAllLogs);

            // 生成审计报告按钮
            document.getElementById('generateReportBtn').addEventListener('click', generateAuditReport);

            // 合规检查按钮
            document.getElementById('complianceCheckBtn').addEventListener('click', runComplianceCheck);

            // 关闭日志详情弹框
            document.getElementById('closeLogDetailModal').addEventListener('click', function() {
                document.getElementById('logDetailModal').classList.remove('active');
            });

            document.getElementById('closeDetailModalBtn').addEventListener('click', function() {
                document.getElementById('logDetailModal').classList.remove('active');
            });

            // 导出单条日志按钮（在详情弹框中）
            document.getElementById('exportSingleLogBtn').addEventListener('click', function() {
                // 这里需要获取当前查看的日志ID
                // 在实际应用中，我们可以从全局变量或数据属性中获取
                // 这里简化处理，提示用户
                alert('导出当前日志功能已触发');
            });

            // 关闭报告弹框
            document.getElementById('closeReportModal').addEventListener('click', function() {
                document.getElementById('reportModal').classList.remove('active');
            });

            document.getElementById('closeReportModalBtn').addEventListener('click', function() {
                document.getElementById('reportModal').classList.remove('active');
            });

            // 执行合规检查按钮（在报告弹框中）
            document.getElementById('runComplianceCheckBtn').addEventListener('click', function() {
                runComplianceCheck();
                // 关闭报告弹框
                document.getElementById('reportModal').classList.remove('active');
            });

            // 生成报告确认按钮
            document.getElementById('generateReportConfirmBtn').addEventListener('click', function() {
                const reportType = document.getElementById('reportType').value;
                const reportFormat = document.getElementById('reportFormat').value;
                const includeCharts = document.getElementById('includeCharts').checked;
                const includeDetails = document.getElementById('includeDetails').checked;

                alert(`正在生成${reportType}报告，格式：${reportFormat}...\n包含图表：${includeCharts ? '是' : '否'}\n包含详情：${includeDetails ? '是' : '否'}`);

                // 模拟生成报告过程
                setTimeout(() => {
                    alert(`报告生成成功！\n文件：audit_report_${new Date().toISOString().split('T')[0]}.${reportFormat}`);
                    // 关闭报告弹框
                    document.getElementById('reportModal').classList.remove('active');
                }, 2000);
            });

            // 点击弹框外部关闭弹框
            document.querySelectorAll('.modal-overlay').forEach(overlay => {
                overlay.addEventListener('click', function(event) {
                    if (event.target === this) {
                        this.classList.remove('active');
                    }
                });
            });
        }
    </script>
