        const protocolTypeMap = {
            "MQTT": { name: "MQTT协议", color: "#1890ff" },
            "HTTP": { name: "HTTP协议", color: "#52c41a" },
            "HTTPS": { name: "HTTPS协议", color: "#13c2c2" },
