        document.addEventListener('DOMContentLoaded', function() {
            // 侧边栏折叠切换
            const sidebar = document.getElementById('sidebar');
            const sidebarToggle = document.getElementById('sidebarToggle');
            const mainContent = document.getElementById('mainContent');

            sidebarToggle.addEventListener('click', function() {
                sidebar.classList.toggle('collapsed');
                mainContent.classList.toggle('expanded');

                const icon = sidebarToggle.querySelector('i');
                if (sidebar.classList.contains('collapsed')) {
                    icon.className = 'fas fa-chevron-right';
                } else {
                    icon.className = 'fas fa-chevron-left';
                }
            });

            // 侧边栏章节展开/折叠
            const sectionHeaders = document.querySelectorAll('.section-header');
            sectionHeaders.forEach(header => {
                header.addEventListener('click', function() {
                    const arrow = this.querySelector('.section-arrow');
                    const menu = this.nextElementSibling;

                    if (sidebar.classList.contains('collapsed')) {
                        sidebar.classList.remove('collapsed');
                        mainContent.classList.remove('expanded');
                        sidebarToggle.querySelector('i').className = 'fas fa-chevron-left';
                    }

                    arrow.classList.toggle('rotated');
                    menu.classList.toggle('collapsed');
                });
            });

            // 默认展开设备管理章节
            const deviceManagementSection = document.querySelector('[data-section="device-management"]');
            if (deviceManagementSection) {
                const arrow = deviceManagementSection.querySelector('.section-arrow');
                const menu = deviceManagementSection.nextElementSibling;
                arrow.classList.add('rotated');
                menu.classList.remove('collapsed');
            }

            // 导航菜单点击事件
            document.querySelectorAll('.nav-item').forEach(item => {
                item.addEventListener('click', function() {
                    document.querySelectorAll('.nav-item.active').forEach(el => {
                        el.classList.remove('active');
                    });

                    this.classList.add('active');

                    const pageTitle = this.querySelector('span').textContent;
                    document.querySelector('.page-title').textContent = pageTitle;

                    // 在实际应用中，这里应该加载对应页面的内容
                    // 这里只是简单演示
                    console.log(`切换到页面: ${pageTitle}`);
                });
            });

            // 初始化设备表格
            renderDeviceTable();
            updateStats();

            // 设备搜索
            document.getElementById('deviceSearch').addEventListener('input', function() {
                filterDevices();
            });

            // 筛选按钮
            document.getElementById('filterBtn').addEventListener('click', function() {
                alert('设备筛选功能：可按设备类型、平台类型、注册状态等条件筛选');
            });

            // 开始发现设备按钮
            document.getElementById('startDiscoveryBtn').addEventListener('click', function() {
                openDiscoveryModal();
            });

            // 批量注册按钮
            document.getElementById('batchRegisterBtn').addEventListener('click', function() {
                const discoveredDevices = deviceData.filter(device => device.registerStatus === 'DISCOVERED');
                if (discoveredDevices.length === 0) {
                    alert('当前没有未注册的设备');
                    return;
                }

                if (confirm(`发现 ${discoveredDevices.length} 个未注册设备，是否批量注册？`)) {
                    // 模拟批量注册
                    discoveredDevices.forEach(device => {
                        device.registerStatus = 'REGISTERED';
                        device.registerTime = new Date().toLocaleString();
                        device.intersectionId = 1;
                        device.intersectionName = '路口A';
                        device.deviceName = device.deviceName === '未命名设备' ? 
                            `设备-${device.deviceId}` : device.deviceName;
                    });

                    renderDeviceTable();
                    updateStats();
                    alert('批量注册完成');
                }
            });

            // 刷新列表按钮
            document.getElementById('refreshDevicesBtn').addEventListener('click', function() {
                renderDeviceTable();
                updateStats();
                alert('设备列表已刷新');
