                            closeDiscoveryModal();
                        } else if (this.id === 'registerModal') {
                            closeRegisterModal();
                        }
                    }
                });
            });
        });

        // 渲染设备表格
        function renderDeviceTable() {
            const tbody = document.getElementById('deviceTableBody');
            tbody.innerHTML = '';

            deviceData.forEach(device => {
                const deviceType = deviceTypeMap[device.deviceType] || { name: device.deviceType, icon: "server", color: "#8c8c8c" };
                const platformType = platformTypeMap[device.platformType] || { name: device.platformType, color: "#8c8c8c" };
                const registerStatus = registerStatusMap[device.registerStatus] || { name: device.registerStatus, color: "#8c8c8c", class: "status-discovered" };
                const protocolType = protocolTypeMap[device.protocolType] || { name: device.protocolType, color: "#8c8c8c" };

                const row = document.createElement('tr');
                row.setAttribute('data-device-id', device.deviceId);

                // 设备类型图标
                const iconColor = device.onlineStatus ? deviceType.color : '#8c8c8c';

                row.innerHTML = `
                    <td>
                        <div class="device-type-icon" style="background-color: ${iconColor}20; color: ${iconColor};">
                            <i class="fas fa-${deviceType.icon}"></i>
                        </div>
                    </td>
                    <td>
                        <div style="font-weight: 500;">${device.deviceId}</div>
                        <div style="font-size: 0.8rem; color: #8c8c8c;">${protocolType.name}</div>
                    </td>
                    <td>${device.deviceName}</td>
                    <td>${deviceType.name}</td>
                    <td>
                        <span class="device-platform ${device.platformType === 'HARMONYOS' || device.platformType === 'OPENHARMONY' ? 'platform-harmony' : device.platformType === 'NON_HARMONY' ? 'platform-non-harmony' : 'platform-legacy'}">
                            ${platformType.name}
                        </span>
                    </td>
                    <td>${device.ipAddress}</td>
                    <td>
                        <span class="device-status ${registerStatus.class}">
                            <span class="status-dot"></span>
                            ${registerStatus.name}
                        </span>
                    </td>
                    <td>
                        <div style="display: flex; align-items: center; gap: 6px;">
                            <div style="width: 8px; height: 8px; border-radius: 50%; background-color: ${device.onlineStatus ? '#52c41a' : '#ff4d4f'};"></div>
                            <span>${device.onlineStatus ? '在线' : '离线'}</span>
                        </div>
                    </td>
                    <td>
                        <div class="device-actions">
                            <button class="action-btn action-btn-primary view-detail-btn" title="查看详情">
                                <i class="fas fa-eye"></i>
                            </button>
                            ${device.registerStatus === 'DISCOVERED' ? 
                                `<button class="action-btn action-btn-success register-btn" title="注册设备">
                                    <i class="fas fa-user-plus"></i>
                                </button>` : 
                                `<button class="action-btn action-btn-warning edit-btn" title="编辑设备">
                                    <i class="fas fa-edit"></i>
                                </button>`
                            }
                            <button class="action-btn delete-btn" title="删除设备">
                                <i class="fas fa-trash"></i>
                            </button>
                        </div>
                    </td>
                `;

                tbody.appendChild(row);
            });

            // 绑定操作按钮事件
            bindActionButtons();
        }

        // 绑定操作按钮事件
        function bindActionButtons() {
            // 查看详情按钮
