                btn.addEventListener('click', function() {
                    const deviceId = this.closest('tr').getAttribute('data-device-id');
                    showDeviceDetails(deviceId);
                });
            });

            // 注册按钮
            document.querySelectorAll('.register-btn').forEach(btn => {
                btn.addEventListener('click', function() {
                    const deviceId = this.closest('tr').getAttribute('data-device-id');
                    openRegisterModal(deviceId);
                });
            });

            // 编辑按钮
            document.querySelectorAll('.edit-btn').forEach(btn => {
                btn.addEventListener('click', function() {
                    const deviceId = this.closest('tr').getAttribute('data-device-id');
                    alert(`编辑设备: ${deviceId}`);
                });
            });

            // 删除按钮
            document.querySelectorAll('.delete-btn').forEach(btn => {
                btn.addEventListener('click', function() {
                    const deviceId = this.closest('tr').getAttribute('data-device-id');
                    const deviceName = this.closest('tr').querySelector('td:nth-child(3)').textContent;

                    if (confirm(`确认删除设备 "${deviceName}" (${deviceId}) 吗？`)) {
                        // 从数据中删除设备
                        const index = deviceData.findIndex(d => d.deviceId === deviceId);
                        if (index !== -1) {
                            deviceData.splice(index, 1);
                            renderDeviceTable();
                            updateStats();
                            alert('设备已删除');
                        }
                    }
                });
            });
        }

        // 显示设备详情
