                    <div class="detail-value">${device.ipAddress}</div>
                </div>
                <div class="detail-item">
                    <div class="detail-label">通信协议</div>
                    <div class="detail-value">
                        <span class="protocol-tag">${protocolType.name}</span>
                    </div>
                </div>
                <div class="detail-item">
                    <div class="detail-label">注册状态</div>
                    <div class="detail-value">
                        <span class="device-status ${registerStatus.class}">
                            <span class="status-dot"></span>
                            ${registerStatus.name}
