                            <span>${device.onlineStatus ? '在线' : '离线'}</span>
                        </div>
                    </div>
                </div>
                <div class="detail-item">
                    <div class="detail-label">关联路口</div>
                    <div class="detail-value">${device.intersectionName || '未关联'}</div>
                </div>
                <div class="detail-item">
                    <div class="detail-label">发现时间</div>
                    <div class="detail-value">${device.discoveryTime || '未知'}</div>
                </div>
                <div class="detail-item">
                    <div class="detail-label">注册时间</div>
                    <div class="detail-value">${device.registerTime || '未注册'}</div>
                </div>
                <div class="detail-item">
                    <div class="detail-label">最后上线时间</div>
                    <div class="detail-value">${device.lastOnlineTime || '未知'}</div>
