            document.getElementById('deviceDetailsPanel').style.display = 'block';

            // 滚动到详情面板
            document.getElementById('deviceDetailsPanel').scrollIntoView({ behavior: 'smooth' });
        }

        // 更新统计信息
        function updateStats() {
            const totalDevices = deviceData.length;
            const registeredDevices = deviceData.filter(d => d.registerStatus === 'REGISTERED').length;
            const discoveredDevices = deviceData.filter(d => d.registerStatus === 'DISCOVERED').length;
            const offlineDevices = deviceData.filter(d => !d.onlineStatus).length;

            document.getElementById('totalDevicesCount').textContent = totalDevices;
            document.getElementById('registeredDevicesCount').textContent = registeredDevices;
            document.getElementById('discoveredDevicesCount').textContent = discoveredDevices;
            document.getElementById('offlineDevicesCount').textContent = offlineDevices;
        }

        // 筛选设备
        function filterDevices() {
            const searchText = document.getElementById('deviceSearch').value.toLowerCase();

            document.querySelectorAll('#deviceTableBody tr').forEach(row => {
                const deviceId = row.getAttribute('data-device-id').toLowerCase();
                const deviceName = row.querySelector('td:nth-child(3)').textContent.toLowerCase();
                const ipAddress = row.querySelector('td:nth-child(6)').textContent.toLowerCase();

                if (deviceId.includes(searchText) || deviceName.includes(searchText) || ipAddress.includes(searchText)) {
                    row.style.display = '';
                } else {
                    row.style.display = 'none';
                }
            });
        }

        // 打开设备发现模态框
        function openDiscoveryModal() {
            document.getElementById('discoveryModal').style.display = 'flex';
            document.getElementById('discoveryResults').style.display = 'none';
            document.getElementById('discoveryProgress').style.display = 'block';
            document.getElementById('progressBar').style.width = '0%';
            document.getElementById('progressPercent').textContent = '0%';

            // 重置进度
            discoveryProgress = 0;

            // 清空之前的结果
            document.getElementById('discoveredDevicesList').innerHTML = '';
        }

        // 关闭设备发现模态框
        function closeDiscoveryModal() {
            document.getElementById('discoveryModal').style.display = 'none';

            // 停止发现进程
            if (discoveryInterval) {
                clearInterval(discoveryInterval);
                discoveryInterval = null;
            }
        }

        // 开始设备发现
        function startDiscovery() {
            const startBtn = document.getElementById('startDiscoveryModalBtn');
            const cancelBtn = document.getElementById('cancelDiscoveryBtn');

            startBtn.disabled = true;
            startBtn.textContent = '扫描中...';
            cancelBtn.textContent = '停止';

            // 模拟发现进度
            discoveryInterval = setInterval(() => {
                discoveryProgress += 10;
                document.getElementById('progressBar').style.width = discoveryProgress + '%';
                document.getElementById('progressPercent').textContent = discoveryProgress + '%';

                if (discoveryProgress >= 100) {
                    clearInterval(discoveryInterval);
                    discoveryInterval = null;

                    // 显示发现结果
                    showDiscoveryResults();

                    startBtn.disabled = false;
                    startBtn.textContent = '重新扫描';
                    cancelBtn.textContent = '关闭';
                }
            }, 300);
        }

        // 显示发现结果
        function showDiscoveryResults() {
            document.getElementById('discoveryProgress').style.display = 'none';
            document.getElementById('discoveryResults').style.display = 'block';

            // 模拟发现新设备
            const newDevices = [
                {
                    deviceId: 'NEW-DEVICE-009',
                    deviceType: 'HARMONY_RSU',
                    platformType: 'HARMONYOS',
                    ipAddress: '192.168.1.109',
                    protocolType: 'NEARLINK',
                    manufacturer: '华为'
                },
                {
                    deviceId: 'NEW-DEVICE-010',
                    deviceType: 'STANDARD_SIGNAL_LIGHT',
                    platformType: 'NON_HARMONY',
                    ipAddress: '192.168.1.110',
                    protocolType: 'MODBUS',
                    manufacturer: '中软国际'
                }
            ];

            const devicesList = document.getElementById('discoveredDevicesList');
            devicesList.innerHTML = '';

            if (newDevices.length === 0) {
                devicesList.innerHTML = '<p style="color: #8c8c8c; text-align: center;">未发现新设备</p>';
                return;
            }

            newDevices.forEach(device => {
                const deviceType = deviceTypeMap[device.deviceType] || { name: device.deviceType, icon: "server", color: "#8c8c8c" };
                const platformType = platformTypeMap[device.platformType] || { name: device.platformType, color: "#8c8c8c" };
                const protocolType = protocolTypeMap[device.protocolType] || { name: device.protocolType, color: "#8c8c8c" };

                const deviceElement = document.createElement('div');
                deviceElement.className = 'element-item';
                deviceElement.style.marginBottom = '10px';
                deviceElement.innerHTML = `
                    <div class="element-color" style="background-color: ${deviceType.color};"></div>
                    <div class="element-info">
                        <div class="element-name">${device.deviceId}</div>
                        <div class="element-type">${deviceType.name} • ${platformType.name}</div>
                        <div style="font-size: 0.8rem; color: #8c8c8c; margin-top: 2px;">
                            ${device.ipAddress} • ${protocolType.name}
                        </div>
                    </div>
                    <button class="btn btn-primary" style="padding: 4px 12px; font-size: 0.9rem;" onclick="registerDiscoveredDevice('${device.deviceId}')">
                        注册
                    </button>
                `;

                devicesList.appendChild(deviceElement);
            });

            // 添加提示
            const tip = document.createElement('p');
            tip.style.fontSize = '0.9rem';
            tip.style.color = '#8c8c8c';
            tip.style.marginTop = '15px';
            tip.textContent = `发现 ${newDevices.length} 个新设备，点击"注册"按钮进行设备注册。`;
            devicesList.appendChild(tip);
        }

        // 注册发现的设备
        function registerDiscoveredDevice(deviceId) {
            // 模拟添加到设备列表
            const newDevice = {
                id: deviceData.length + 1,
                deviceId: deviceId,
                deviceName: '未命名设备',
                deviceType: deviceId.includes('RSU') ? 'HARMONY_RSU' : 'STANDARD_SIGNAL_LIGHT',
                platformType: deviceId.includes('HARMONY') ? 'HARMONYOS' : 'NON_HARMONY',
                intersectionId: null,
                intersectionName: null,
                ipAddress: deviceId === 'NEW-DEVICE-009' ? '192.168.1.109' : '192.168.1.110',
                protocolType: deviceId === 'NEW-DEVICE-009' ? 'NEARLINK' : 'MODBUS',
                registerStatus: 'DISCOVERED',
                onlineStatus: true,
                manufacturer: deviceId === 'NEW-DEVICE-009' ? '华为' : '中软国际',
                firmwareVersion: '1.0.0',
                lastOnlineTime: new Date().toLocaleString(),
                discoveryTime: new Date().toLocaleString(),
                registerTime: null
            };

            deviceData.push(newDevice);

            // 更新UI
            renderDeviceTable();
            updateStats();

            // 关闭发现模态框
            closeDiscoveryModal();

            // 打开注册模态框
            openRegisterModal(deviceId);
        }

        // 打开设备注册模态框
        function openRegisterModal(deviceId) {
            const device = deviceData.find(d => d.deviceId === deviceId);
            if (!device) return;

            currentDeviceDetails = device;

            document.getElementById('registerDeviceId').value = device.deviceId;
            document.getElementById('registerDeviceName').value = device.deviceName === '未命名设备' ? '' : device.deviceName;
            document.getElementById('registerIntersectionId').value = device.intersectionId || '';
            document.getElementById('registerDescription').value = '';
            document.getElementById('registerAuthInfo').value = '';

            document.getElementById('registerModal').style.display = 'flex';
        }

        // 关闭设备注册模态框
        function closeRegisterModal() {
            document.getElementById('registerModal').style.display = 'none';
            currentDeviceDetails = null;
        }

        // 确认注册设备
        function confirmRegister() {
            const deviceId = document.getElementById('registerDeviceId').value;
            const deviceName = document.getElementById('registerDeviceName').value;
            const intersectionId = document.getElementById('registerIntersectionId').value;
            const description = document.getElementById('registerDescription').value;
            const authInfo = document.getElementById('registerAuthInfo').value;

            if (!deviceName.trim()) {
                alert('请输入设备名称');
                return;
            }

            if (!intersectionId) {
                alert('请选择关联路口');
                return;
            }

            // 更新设备信息
            const device = deviceData.find(d => d.deviceId === deviceId);
            if (device) {
                device.deviceName = deviceName;
                device.intersectionId = parseInt(intersectionId);
                device.intersectionName = intersectionId === '1' ? '路口A' : 
                                          intersectionId === '2' ? '路口B' : 
                                          intersectionId === '3' ? '路口C' : '路口D';
                device.registerStatus = 'REGISTERED';
                device.registerTime = new Date().toLocaleString();

                if (authInfo) {
                    // 在实际应用中，这里会设置设备的认证信息
                    console.log('设置设备认证信息:', authInfo);
                }

                // 更新UI
                renderDeviceTable();
                updateStats();

                // 关闭模态框
                closeRegisterModal();

                alert(`设备 ${deviceName} 注册成功！`);
            }
        }
    </script>
</body>
</html>
```

## 功能说明

这个"设备发现与注册"页面实现了以下核心功能：

### 1. **页面结构**
- 保持了与2.html完全一致的脚手架架构，包括头部、侧边栏和主内容区
- 侧边栏中"设备发现与注册"菜单项被设置为激活状态

### 2. **统计卡片**
- 显示总设备数、已注册设备数、已发现设备数和离线设备数
- 统计数据根据设备列表动态更新

### 3. **设备列表表格**
- 展示设备ID、名称、类型、平台类型、IP地址、注册状态和在线状态
- 支持设备搜索功能
- 提供查看详情、注册、编辑和删除操作按钮

### 4. **设备详情面板**
- 点击"查看详情"按钮显示设备的详细信息
- 包括设备基本属性、状态信息和时间戳

### 5. **设备发现功能**
- 点击"开始发现设备"按钮打开发现模态框
- 模拟网络扫描过程，显示进度条
- 扫描完成后显示发现的设备列表
- 可以直接从发现结果中注册设备

### 6. **设备注册功能**
- 针对未注册设备，点击"注册"按钮打开注册表单
- 需要填写设备名称、关联路口等信息
- 支持批量注册功能

### 7. **设备类型分类**
- 鸿蒙设备（HarmonyOS） - 蓝色标识
- 开源鸿蒙设备（OpenHarmony） - 绿色标识
- 非鸿蒙设备 - 黄色标识
- 老旧设备 - 红色标识

### 8. **状态标识**
- 已注册（绿色）
- 已发现（灰色）
- 注册中（蓝色）
- 认证失败（黄色）
- 离线（红色）

### 9. **响应式设计**
- 适配不同屏幕尺寸
- 在移动设备上优化显示效果

页面使用了与2.html完全一致的图标、主题颜色和样式规范，确保整体UI风格的一致性。所有功能都通过JavaScript模拟实现，展示了完整的设备发现与注册流程。

