            document.getElementById('assignTagsBtn').addEventListener('click', function() {
                // 检查是否有选中的设备
                const selectedDevices = Array.from(document.querySelectorAll('.device-checkbox:checked'));
                if (selectedDevices.length === 0) {
                    alert('请先选择要分配标签的设备');
