                // 渲染标签选择器
                const tagSelectionContainer = document.getElementById('tagSelectionContainer');
                tagSelectionContainer.innerHTML = '';

                tags.forEach(tag => {
                    const tagElement = document.createElement('div');
                    tagElement.className = 'device-tag';
                    tagElement.style.cssText = `background-color: ${tag.color}20; color: ${tag.color}; cursor: pointer;`;
                    tagElement.innerHTML = `
                        <i class="fas fa-tag" style="font-size: 0.7rem;"></i>
