            });

            // 为标签操作按钮添加事件（编辑和删除）
            document.addEventListener('click', function(e) {
                if (e.target.closest('.tag-action-btn.edit')) {
                    const tagItem = e.target.closest('.tag-item');
                    const tagName = tagItem.querySelector('.tag-name').textContent;
                    const tagColor = tagItem.querySelector('.tag-color').style.backgroundColor;

                    // 打开编辑模态框
                    document.getElementById('editTagName').value = tagName;
                    document.getElementById('editTagColor').value = rgbToHex(tagColor);
                    document.getElementById('editColorPreview').style.backgroundColor = rgbToHex(tagColor);

                    // 设置标签描述（这里简单模拟）
                    document.getElementById('editTagDescription').value = `${tagName}的描述信息`;

                    document.getElementById('tagEditModal').style.display = 'flex';
                }

                if (e.target.closest('.tag-action-btn.delete')) {
                    const tagItem = e.target.closest('.tag-item');
                    const tagName = tagItem.querySelector('.tag-name').textContent;

                    if (confirm(`确定要删除标签"${tagName}"吗？`)) {
                        // 模拟删除标签
                        console.log('删除标签:', tagName);
                        tagItem.style.opacity = '0.5';
                        setTimeout(() => {
                            tagItem.remove();
                        }, 300);
                    }
                }
            });

            // 关闭编辑模态框
            document.getElementById('closeEditModal').addEventListener('click', function() {
                document.getElementById('tagEditModal').style.display = 'none';
            });

            document.getElementById('cancelEditBtn').addEventListener('click', function() {
                document.getElementById('tagEditModal').style.display = 'none';
            });

            // 保存编辑
            document.getElementById('saveEditBtn').addEventListener('click', function() {
                const tagName = document.getElementById('editTagName').value;
                const tagColor = document.getElementById('editTagColor').value;
                const tagDescription = document.getElementById('editTagDescription').value;

                console.log('保存标签编辑:', { tagName, tagColor, tagDescription });
                alert(`标签"${tagName}"已更新成功`);
                document.getElementById('tagEditModal').style.display = 'none';
            });
        });

        // 辅助函数：RGB转十六进制
        function rgbToHex(rgb) {
            // 如果已经是十六进制格式，直接返回
            if (rgb.startsWith('#')) return rgb;

            // 解析rgb(r, g, b)格式
            const result = rgb.match(/\d+/g);
            if (result) {
                const r = parseInt(result[0]).toString(16).padStart(2, '0');
                const g = parseInt(result[1]).toString(16).padStart(2, '0');
                const b = parseInt(result[2]).toString(16).padStart(2, '0');
                return `#${r}${g}${b}`;
            }
            return '#1890ff';
        }

        // 编辑设备标签
        function editDeviceTags(deviceId) {
            const device = devices.find(d => d.id === deviceId);
            if (device) {
                alert(`编辑设备 ${device.name} 的标签\n当前标签: ${device.tags.join(', ')}`);
                // 在实际应用中，这里应该打开一个模态框来编辑设备标签
            }
        }

        // 从设备移除标签
        function removeTagFromDevice(deviceId, tagName) {
            const device = devices.find(d => d.id === deviceId);
            if (device) {
                const index = device.tags.indexOf(tagName);
                if (index > -1) {
                    device.tags.splice(index, 1);
                    alert(`已从设备 ${device.name} 移除标签 "${tagName}"`);
                    // 重新渲染表格
                    document.querySelectorAll('.device-checkbox').forEach(cb => cb.checked = false);
                    document.getElementById('selectAllCheckbox').checked = false;

                    // 在实际应用中，这里应该发送请求到服务器更新数据
                    // 这里简单重新渲染
                    setTimeout(() => {
                        const event = new Event('DOMContentLoaded', { bubbles: true });
                        document.dispatchEvent(event);
                    }, 100);
                }
            }
        }
    </script>
</body>
</html>
