        .page-title {
            font-size: 1.6rem;
            font-weight: 600;
            color: #262626;
        }

        .page-controls {
            display: flex;
            gap: 15px;
        }

        .btn {
            padding: 8px 16px;
            border-radius: 4px;
            border: 1px solid #d9d9d9;
            background-color: white;
            cursor: pointer;
            display: flex;
            align-items: center;
            gap: 8px;
            transition: all 0.2s;
        }

        .btn-primary {
            background-color: #1890ff;
            color: white;
            border-color: #1890ff;
        }

        .btn-primary:hover {
            background-color: #0050b3;
        }

        .btn-success {
            background-color: #52c41a;
            color: white;
            border-color: #52c41a;
        }

        .btn-success:hover {
            background-color: #389e0d;
        }

        .btn-danger {
            background-color: #ff4d4f;
            color: white;
            border-color: #ff4d4f;
        }

        .btn-danger:hover {
            background-color: #d9363e;
        }

        /* 标签管理容器 */
        .tag-management-container {
            background-color: white;
            border-radius: 8px;
            box-shadow: 0 1px 4px rgba(0, 0, 0, 0.1);
            padding: 25px;
            margin-bottom: 25px;
        }

        .tag-management-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 20px;
        }

        .tag-management-title {
            font-size: 1.2rem;
            font-weight: 600;
            color: #262626;
        }

        .tag-search {
            display: flex;
            gap: 10px;
            margin-bottom: 20px;
        }

        .search-input {
            flex: 1;
            padding: 10px 15px;
            border: 1px solid #d9d9d9;
            border-radius: 4px;
            font-size: 0.9rem;
        }

        .search-input:focus {
            outline: none;
            border-color: #1890ff;
            box-shadow: 0 0 0 2px rgba(24, 144, 255, 0.2);
        }

        .tags-table {
            width: 100%;
            border-collapse: collapse;
            margin-bottom: 20px;
        }

        .tags-table th {
            background-color: #fafafa;
            padding: 12px 16px;
            text-align: left;
            font-weight: 600;
            color: #262626;
            border-bottom: 1px solid #f0f0f0;
        }

        .tags-table td {
            padding: 12px 16px;
            border-bottom: 1px solid #f0f0f0;
        }

        .tag-color {
            display: inline-block;
            width: 16px;
            height: 16px;
            border-radius: 3px;
            margin-right: 8px;
            vertical-align: middle;
        }

        .tag-badge {
