            padding: 4px 8px;
            border-radius: 4px;
            font-size: 0.8rem;
            font-weight: 500;
        }

        .tag-badge.system {
            background-color: #e6f7ff;
            color: #1890ff;
        }

        .tag-badge.custom {
            background-color: #f6ffed;
            color: #52c41a;
        }

        .action-buttons {
            display: flex;
            gap: 8px;
