        .action-btn.edit {
            color: #1890ff;
            border-color: #91d5ff;
            background-color: #e6f7ff;
        }

        .action-btn.delete {
            color: #ff4d4f;
            border-color: #ffccc7;
            background-color: #fff2f0;
        }

        .action-btn.edit:hover {
            background-color: #91d5ff;
            color: white;
        }

        .action-btn.delete:hover {
            background-color: #ffccc7;
            color: white;
        }

        .pagination {
            display: flex;
            justify-content: flex-end;
            align-items: center;
            gap: 10px;
            margin-top: 20px;
        }

        .pagination-btn {
            padding: 6px 12px;
            border: 1px solid #d9d9d9;
            border-radius: 4px;
            background-color: white;
            cursor: pointer;
