            <div class="footer">
                <p>© 2025 开源鸿蒙交通路口管理系统 | 版本号: V2.1.5</p>
                <p>技术支持: 中软国际技术团队 | 服务热线: 400-123-4567</p>
            </div>
        </div>
    </div>

    <!-- 创建/编辑标签模态框 -->
    <div class="modal-overlay" id="tagModalOverlay">
        <div class="modal">
            <div class="modal-header">
                <div class="modal-title" id="tagModalTitle">创建标签</div>
                <button class="modal-close" id="tagModalClose">
                    <i class="fas fa-times"></i>
                </button>
            </div>
            <div class="modal-body">
                <form id="tagForm">
                    <div class="form-group">
                        <label class="form-label" for="tagName">标签名称 *</label>
                        <input type="text" class="form-input" id="tagName" placeholder="请输入标签名称" required>
                    </div>

                    <div class="form-group">
                        <label class="form-label" for="tagCategory">标签分类</label>
                        <select class="form-select" id="tagCategory">
                            <option value="device_type">设备类型</option>
                            <option value="location">位置</option>
                            <option value="status">状态</option>
                            <option value="manufacturer">厂商</option>
                            <option value="priority">优先级</option>
                            <option value="custom">自定义</option>
                        </select>
                    </div>

                    <div class="form-group">
                        <label class="form-label" for="tagType">标签类型</label>
                        <select class="form-select" id="tagType">
                            <option value="system">系统标签</option>
                            <option value="custom" selected>自定义标签</option>
                        </select>
                    </div>

                    <div class="form-group">
                        <label class="form-label">标签颜色</label>
                        <div class="color-picker">
                            <div class="color-preview" id="colorPreview" style="background-color: #1890ff;"></div>
                            <input type="color" class="color-input" id="tagColor" value="#1890ff">
                            <input type="text" class="form-input" id="tagColorText" value="#1890ff" style="flex: 1;">
                        </div>
                    </div>

                    <div class="form-group">
                        <label class="form-label" for="tagDescription">标签描述</label>
                        <textarea class="form-textarea" id="tagDescription" placeholder="请输入标签描述信息"></textarea>
                    </div>
                </form>
            </div>
            <div class="modal-footer">
                <button class="btn" id="tagModalCancel">取消</button>
                <button class="btn btn-primary" id="tagModalSubmit">保存</button>
            </div>
        </div>
    </div>

    <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
    <script>
        // 初始化侧边栏展开/折叠功能
        document.addEventListener('DOMContentLoaded', function() {
            // 侧边栏折叠切换
            const sidebar = document.getElementById('sidebar');
            const sidebarToggle = document.getElementById('sidebarToggle');
            const mainContent = document.getElementById('mainContent');

            sidebarToggle.addEventListener('click', function() {
                sidebar.classList.toggle('collapsed');
                mainContent.classList.toggle('expanded');

                // 切换箭头方向
                const icon = sidebarToggle.querySelector('i');
                if (sidebar.classList.contains('collapsed')) {
                    icon.className = 'fas fa-chevron-right';
                } else {
                    icon.className = 'fas fa-chevron-left';
                }
            });

            // 侧边栏章节展开/折叠
            const sectionHeaders = document.querySelectorAll('.section-header');
            sectionHeaders.forEach(header => {
                header.addEventListener('click', function() {
                    const arrow = this.querySelector('.section-arrow');
                    const menu = this.nextElementSibling;

                    // 如果侧边栏是折叠状态，先展开侧边栏
                    if (sidebar.classList.contains('collapsed')) {
                        sidebar.classList.remove('collapsed');
                        mainContent.classList.remove('expanded');
                        sidebarToggle.querySelector('i').className = 'fas fa-chevron-left';
                    }

                    arrow.classList.toggle('rotated');
                    menu.classList.toggle('collapsed');
                });
            });

            // 默认展开第一个章节
            const firstSection = document.querySelector('.section-header');
            if (firstSection) {
                const firstArrow = firstSection.querySelector('.section-arrow');
                const firstMenu = firstSection.nextElementSibling;
                firstArrow.classList.add('rotated');
                firstMenu.classList.remove('collapsed');
            }

            // 导航菜单点击事件
            document.querySelectorAll('.nav-item').forEach(item => {
                item.addEventListener('click', function() {
                    // 移除所有active类
                    document.querySelectorAll('.nav-item.active').forEach(el => {
                        el.classList.remove('active');
                    });

                    // 为当前项添加active类
                    this.classList.add('active');

                    // 根据点击的菜单项切换页面内容
                    const pageTitle = this.querySelector('span').textContent;
                    document.querySelector('.page-title').textContent = pageTitle;

                    // 在实际应用中，这里应该加载对应页面的内容
                    // 这里只是简单演示
                    console.log(`切换到页面: ${pageTitle}`);
                });
            });

            // 模拟标签数据
            const tagsData = [
                { id: 1, name: "鸿蒙设备", category: "设备类型", type: "system", color: "#1890ff", deviceCount: 8, createdAt: "2025-10-15", description: "运行鸿蒙操作系统的设备" },
                { id: 2, name: "信号灯", category: "设备类型", type: "system", color: "#52c41a", deviceCount: 4, createdAt: "2025-10-15", description: "交通信号灯设备" },
                { id: 3, name: "摄像头", category: "设备类型", type: "system", color: "#ff4d4f", deviceCount: 6, createdAt: "2025-10-15", description: "视频监控摄像头设备" },
                { id: 4, name: "雷达", category: "设备类型", type: "system", color: "#faad14", deviceCount: 2, createdAt: "2025-10-16", description: "雷达检测设备" },
                { id: 5, name: "路口A", category: "位置", type: "custom", color: "#722ed1", deviceCount: 12, createdAt: "2025-10-17", description: "位于路口A的设备" },
                { id: 6, name: "路口B", category: "位置", type: "custom", color: "#eb2f96", deviceCount: 9, createdAt: "2025-10-17", description: "位于路口B的设备" },
                { id: 7, name: "在线", category: "状态", type: "system", color: "#13c2c2", deviceCount: 25, createdAt: "2025-10-18", description: "当前在线设备" },
                { id: 8, name: "离线", category: "状态", type: "system", color: "#bfbfbf", deviceCount: 3, createdAt: "2025-10-18", description: "当前离线设备" },
                { id: 9, name: "海康威视", category: "厂商", type: "custom", color: "#ff7a45", deviceCount: 7, createdAt: "2025-10-19", description: "海康威视生产的设备" },
                { id: 10, name: "大华股份", category: "厂商", type: "custom", color: "#a0d911", deviceCount: 5, createdAt: "2025-10-19", description: "大华股份生产的设备" },
                { id: 11, name: "高优先级", category: "优先级", type: "custom", color: "#f5222d", deviceCount: 4, createdAt: "2025-10-20", description: "需要优先处理的高优先级设备" },
                { id: 12, name: "维护中", category: "状态", type: "system", color: "#fa8c16", deviceCount: 2, createdAt: "2025-10-21", description: "当前处于维护状态的设备" }
            ];

            // 模拟设备标签关联数据
            const deviceTagsData = [
                { id: 1, name: "鸿蒙信号灯-01", type: "HARMONY_TRAFFIC_LIGHT", tags: ["鸿蒙设备", "信号灯", "路口A", "在线", "高优先级"] },
                { id: 2, name: "鸿蒙摄像头-03", type: "HARMONY_CAMERA", tags: ["鸿蒙设备", "摄像头", "路口A", "在线", "海康威视"] },
                { id: 3, name: "标准信号灯-02", type: "STANDARD_SIGNAL_LIGHT", tags: ["信号灯", "路口B", "在线", "大华股份"] },
                { id: 4, name: "雷视一体机-01", type: "HARMONY_RADAR", tags: ["鸿蒙设备", "雷达", "路口A", "在线", "高优先级"] },
                { id: 5, name: "老旧信号控制器", type: "LEGACY_SIGNAL_CONTROLLER", tags: ["信号灯", "路口B", "离线", "维护中"] },
                { id: 6, name: "智能摄像机-08", type: "STANDARD_CAMERA", tags: ["摄像头", "路口A", "在线", "海康威视"] }
            ];

            // 渲染标签表格
            function renderTagsTable(tags) {
                const tagsTableBody = document.getElementById('tagsTableBody');
                tagsTableBody.innerHTML = '';

                tags.forEach(tag => {
                    const row = document.createElement('tr');
                    row.setAttribute('data-id', tag.id);

                    row.innerHTML = `
                        <td>
                            <input type="checkbox" class="tag-checkbox" data-id="${tag.id}">
                        </td>
                        <td>
                            <div style="font-weight: 500;">${tag.name}</div>
                            <div style="font-size: 0.8rem; color: #8c8c8c; margin-top: 2px;">${tag.description || '无描述'}</div>
                        </td>
                        <td>${tag.category}</td>
                        <td>
                            <span class="tag-badge ${tag.type}">
                                ${tag.type === 'system' ? '系统标签' : '自定义标签'}
                            </span>
                        </td>
                        <td>
                            <div class="tag-color" style="background-color: ${tag.color};"></div>
                            <span style="font-family: monospace; font-size: 0.85rem;">${tag.color}</span>
                        </td>
                        <td>
                            <span style="font-weight: 500;">${tag.deviceCount}</span>
                        </td>
                        <td>${tag.createdAt}</td>
                        <td>
                            <div class="action-buttons">
                                <button class="action-btn edit" data-id="${tag.id}">
                                    <i class="fas fa-edit"></i>
                                </button>
                                <button class="action-btn delete" data-id="${tag.id}">
                                    <i class="fas fa-trash"></i>
                                </button>
                            </div>
                        </td>
                    `;

                    tagsTableBody.appendChild(row);
                });

                // 更新标签数量
                document.getElementById('tagCount').textContent = tags.length;

                // 绑定编辑和删除按钮事件
                bindTagActions();
            }

            // 渲染设备标签关联
            function renderDeviceTags(devices) {
                const deviceTagsGrid = document.getElementById('deviceTagsGrid');
                deviceTagsGrid.innerHTML = '';

                devices.forEach(device => {
                    const card = document.createElement('div');
                    card.className = 'device-card';

                    // 为设备类型设置图标
                    let typeIcon = 'fa-microchip';
                    if (device.type.includes('TRAFFIC_LIGHT')) typeIcon = 'fa-traffic-light';
                    if (device.type.includes('CAMERA')) typeIcon = 'fa-video';
                    if (device.type.includes('RADAR')) typeIcon = 'fa-satellite-dish';
                    if (device.type.includes('CONTROLLER')) typeIcon = 'fa-cogs';

                    // 根据标签名称获取颜色
                    const tagElements = device.tags.map(tagName => {
                        // 查找标签颜色
                        const tag = tagsData.find(t => t.name === tagName);
                        const color = tag ? tag.color : '#8c8c8c';

                        return `
                            <div class="device-tag" style="background-color: ${color}20; color: ${color}; border: 1px solid ${color}40;">
                                ${tagName}
                                <i class="fas fa-times" data-device-id="${device.id}" data-tag-name="${tagName}"></i>
                            </div>
                        `;
                    }).join('');

                    card.innerHTML = `
                        <div class="device-header">
                            <div class="device-name">
                                <i class="fas ${typeIcon}" style="margin-right: 8px; color: #1890ff;"></i>
                                ${device.name}
                            </div>
                            <div class="device-type">${device.type}</div>
                        </div>
                        <div style="font-size: 0.85rem; color: #8c8c8c; margin: 5px 0;">
                            设备ID: DEV-${String(device.id).padStart(3, '0')}-2025
                        </div>
                        <div style="font-size: 0.85rem; color: #8c8c8c; margin-bottom: 10px;">
                            关联标签: ${device.tags.length} 个
                        </div>
                        <div class="device-tags">
                            ${tagElements}
                        </div>
                        <div style="margin-top: 15px; display: flex; gap: 10px;">
                            <button class="btn" style="padding: 5px 10px; font-size: 0.8rem;" data-device-id="${device.id}">
                                <i class="fas fa-tag"></i> 添加标签
                            </button>
                            <button class="btn" style="padding: 5px 10px; font-size: 0.8rem;" data-device-id="${device.id}">
                                <i class="fas fa-list"></i> 管理关联
                            </button>
                        </div>
                    `;

                    deviceTagsGrid.appendChild(card);
                });

                // 绑定移除标签按钮事件
                bindRemoveTagEvents();
            }

            // 绑定标签操作事件（编辑、删除）
            function bindTagActions() {
                // 编辑按钮
                document.querySelectorAll('.action-btn.edit').forEach(btn => {
                    btn.addEventListener('click', function() {
                        const tagId = parseInt(this.getAttribute('data-id'));
                        const tag = tagsData.find(t => t.id === tagId);

                        if (tag) {
                            openTagModal(tag);
                        }
                    });
                });

                // 删除按钮
                document.querySelectorAll('.action-btn.delete').forEach(btn => {
                    btn.addEventListener('click', function() {
                        const tagId = parseInt(this.getAttribute('data-id'));
                        const tag = tagsData.find(t => t.id === tagId);

                        if (tag && confirm(`确定要删除标签"${tag.name}"吗？`)) {
                            // 模拟删除标签
                            const index = tagsData.findIndex(t => t.id === tagId);
                            if (index !== -1) {
                                tagsData.splice(index, 1);
                                renderTagsTable(tagsData);
                                updateBatchDeleteButton();
                            }
                        }
                    });
                });

                // 标签复选框
                document.querySelectorAll('.tag-checkbox').forEach(checkbox => {
                    checkbox.addEventListener('change', updateBatchDeleteButton);
                });
            }

            // 绑定移除标签事件
            function bindRemoveTagEvents() {
                document.querySelectorAll('.device-tag i').forEach(icon => {
                    icon.addEventListener('click', function() {
                        const deviceId = parseInt(this.getAttribute('data-device-id'));
                        const tagName = this.getAttribute('data-tag-name');

                        if (confirm(`确定要从设备移除标签"${tagName}"吗？`)) {
                            // 模拟移除标签
                            const device = deviceTagsData.find(d => d.id === deviceId);
                            if (device) {
                                const tagIndex = device.tags.indexOf(tagName);
                                if (tagIndex !== -1) {
                                    device.tags.splice(tagIndex, 1);
                                    renderDeviceTags(deviceTagsData);
                                }
                            }
                        }
                    });
                });

                // 绑定设备添加标签按钮
                document.querySelectorAll('.device-card .btn').forEach(btn => {
                    btn.addEventListener('click', function() {
                        const deviceId = parseInt(this.getAttribute('data-device-id'));
                        const device = deviceTagsData.find(d => d.id === deviceId);

                        if (device) {
                            alert(`将为设备"${device.name}"添加标签\n在实际应用中，这里会弹出标签选择对话框`);
                        }
                    });
                });
            }

            // 更新批量删除按钮显示状态
            function updateBatchDeleteButton() {
                const checkedBoxes = document.querySelectorAll('.tag-checkbox:checked');
                const batchDeleteBtn = document.getElementById('batchDeleteBtn');

                if (checkedBoxes.length > 0) {
                    batchDeleteBtn.style.display = 'flex';
                    batchDeleteBtn.innerHTML = `<i class="fas fa-trash"></i> 批量删除 (${checkedBoxes.length})`;
                } else {
                    batchDeleteBtn.style.display = 'none';
                }
            }

            // 全选/取消全选标签
            document.getElementById('selectAllTags').addEventListener('change', function() {
                const checkboxes = document.querySelectorAll('.tag-checkbox');
                checkboxes.forEach(checkbox => {
                    checkbox.checked = this.checked;
                });
                updateBatchDeleteButton();
            });

            // 批量删除标签
            document.getElementById('batchDeleteBtn').addEventListener('click', function() {
                const checkedBoxes = document.querySelectorAll('.tag-checkbox:checked');

                if (checkedBoxes.length === 0) return;

                if (confirm(`确定要删除选中的 ${checkedBoxes.length} 个标签吗？`)) {
                    // 获取选中的标签ID
                    const tagIdsToDelete = Array.from(checkedBoxes).map(cb => parseInt(cb.getAttribute('data-id')));

                    // 模拟删除选中的标签
                    tagIdsToDelete.forEach(tagId => {
                        const index = tagsData.findIndex(t => t.id === tagId);
                        if (index !== -1) {
                            tagsData.splice(index, 1);
                        }
                    });

                    // 重新渲染表格
                    renderTagsTable(tagsData);
                    updateBatchDeleteButton();

                    // 取消全选
                    document.getElementById('selectAllTags').checked = false;
                }
            });

            // 标签搜索功能
            document.getElementById('searchBtn').addEventListener('click', performTagSearch);
            document.getElementById('tagSearchInput').addEventListener('keyup', function(event) {
                if (event.key === 'Enter') {
                    performTagSearch();
                }
            });

            function performTagSearch() {
                const searchTerm = document.getElementById('tagSearchInput').value.toLowerCase().trim();

                if (searchTerm === '') {
                    renderTagsTable(tagsData);
                    return;
                }

                const filteredTags = tagsData.filter(tag => 
                    tag.name.toLowerCase().includes(searchTerm) ||
                    tag.category.toLowerCase().includes(searchTerm) ||
                    (tag.description && tag.description.toLowerCase().includes(searchTerm))
                );

                renderTagsTable(filteredTags);
            }

            // 重置搜索
            document.getElementById('resetSearchBtn').addEventListener('click', function() {
                document.getElementById('tagSearchInput').value = '';
                renderTagsTable(tagsData);
            });

            // 标签模态框相关功能
            const tagModalOverlay = document.getElementById('tagModalOverlay');
            const tagModalTitle = document.getElementById('tagModalTitle');
            const tagForm = document.getElementById('tagForm');
            const tagModalSubmit = document.getElementById('tagModalSubmit');
            let isEditing = false;
            let editingTagId = null;

            // 打开标签模态框
            function openTagModal(tag = null) {
                if (tag) {
                    // 编辑模式
                    isEditing = true;
                    editingTagId = tag.id;
                    tagModalTitle.textContent = '编辑标签';

                    // 填充表单数据
                    document.getElementById('tagName').value = tag.name;
                    document.getElementById('tagCategory').value = tag.category.toLowerCase();
                    document.getElementById('tagType').value = tag.type;
                    document.getElementById('tagColor').value = tag.color;
                    document.getElementById('tagColorText').value = tag.color;
                    document.getElementById('colorPreview').style.backgroundColor = tag.color;
                    document.getElementById('tagDescription').value = tag.description || '';
                } else {
                    // 创建模式
                    isEditing = false;
                    editingTagId = null;
                    tagModalTitle.textContent = '创建标签';

                    // 重置表单
                    tagForm.reset();
                    document.getElementById('tagColor').value = '#1890ff';
                    document.getElementById('tagColorText').value = '#1890ff';
                    document.getElementById('colorPreview').style.backgroundColor = '#1890ff';
                }

                tagModalOverlay.classList.add('active');
            }

            // 关闭标签模态框
            function closeTagModal() {
                tagModalOverlay.classList.remove('active');
                tagForm.reset();
            }

            // 颜色选择器同步
            document.getElementById('tagColor').addEventListener('input', function() {
                const color = this.value;
                document.getElementById('tagColorText').value = color;
                document.getElementById('colorPreview').style.backgroundColor = color;
            });

            document.getElementById('tagColorText').addEventListener('input', function() {
                const color = this.value;
                if (/^#[0-9A-F]{6}$/i.test(color)) {
                    document.getElementById('tagColor').value = color;
                    document.getElementById('colorPreview').style.backgroundColor = color;
                }
            });

            // 创建标签按钮
            document.getElementById('createTagBtn').addEventListener('click', function() {
                openTagModal();
            });

            // 关闭模态框按钮
            document.getElementById('tagModalClose').addEventListener('click', closeTagModal);
            document.getElementById('tagModalCancel').addEventListener('click', closeTagModal);

            // 模态框外部点击关闭
            tagModalOverlay.addEventListener('click', function(event) {
                if (event.target === tagModalOverlay) {
                    closeTagModal();
                }
            });

            // 提交标签表单
            tagModalSubmit.addEventListener('click', function() {
                const tagName = document.getElementById('tagName').value.trim();
                const tagCategory = document.getElementById('tagCategory').value;
                const tagType = document.getElementById('tagType').value;
                const tagColor = document.getElementById('tagColor').value;
                const tagDescription = document.getElementById('tagDescription').value.trim();

                if (!tagName) {
                    alert('标签名称不能为空');
                    return;
                }

                if (isEditing) {
                    // 更新标签
                    const tagIndex = tagsData.findIndex(t => t.id === editingTagId);
                    if (tagIndex !== -1) {
                        tagsData[tagIndex].name = tagName;
                        tagsData[tagIndex].category = tagCategory.charAt(0).toUpperCase() + tagCategory.slice(1);
                        tagsData[tagIndex].type = tagType;
                        tagsData[tagIndex].color = tagColor;
                        tagsData[tagIndex].description = tagDescription;
                    }
                } else {
                    // 创建新标签
                    const newTag = {
                        id: tagsData.length > 0 ? Math.max(...tagsData.map(t => t.id)) + 1 : 1,
                        name: tagName,
                        category: tagCategory.charAt(0).toUpperCase() + tagCategory.slice(1),
                        type: tagType,
                        color: tagColor,
                        deviceCount: 0,
                        createdAt: new Date().toISOString().split('T')[0],
                        description: tagDescription
                    };

                    tagsData.push(newTag);
                }

                // 重新渲染表格并关闭模态框
                renderTagsTable(tagsData);
                closeTagModal();
            });

            // 导入标签按钮
            document.getElementById('importTagsBtn').addEventListener('click', function() {
                alert('标签导入功能：支持从Excel/JSON文件导入标签数据');
            });

            // 导出标签按钮
            document.getElementById('exportTagsBtn').addEventListener('click', function() {
                alert('标签导出功能：将当前标签数据导出为Excel/JSON文件');
            });

            // 分页按钮事件
            document.querySelectorAll('.pagination-btn').forEach((btn, index) => {
                if (index > 0 && index < 4) { // 数字按钮
                    btn.addEventListener('click', function() {
                        // 移除所有active类
                        document.querySelectorAll('.pagination-btn').forEach(b => {
                            b.classList.remove('active');
                        });

                        // 为当前按钮添加active类
                        this.classList.add('active');

                        // 在实际应用中，这里会加载对应页面的数据
                        console.log(`切换到第 ${this.textContent} 页`);
                    });
                }
            });

            // 上一页按钮
            document.getElementById('prevPageBtn').addEventListener('click', function() {
                const activeBtn = document.querySelector('.pagination-btn.active');
                const currentPage = parseInt(activeBtn.textContent);

                if (currentPage > 1) {
                    // 移除所有active类
                    document.querySelectorAll('.pagination-btn').forEach(b => {
                        b.classList.remove('active');
                    });

                    // 为前一个按钮添加active类
                    const prevBtn = Array.from(document.querySelectorAll('.pagination-btn'))[currentPage - 1];
                    if (prevBtn) prevBtn.classList.add('active');

                    console.log(`切换到第 ${currentPage - 1} 页`);
                }
            });

            // 下一页按钮
            document.getElementById('nextPageBtn').addEventListener('click', function() {
                const activeBtn = document.querySelector('.pagination-btn.active');
                const currentPage = parseInt(activeBtn.textContent);

                if (currentPage < 3) {
                    // 移除所有active类
                    document.querySelectorAll('.pagination-btn').forEach(b => {
                        b.classList.remove('active');
                    });

                    // 为后一个按钮添加active类
                    const nextBtn = Array.from(document.querySelectorAll('.pagination-btn'))[currentPage + 1];
                    if (nextBtn) nextBtn.classList.add('active');

                    console.log(`切换到第 ${currentPage + 1} 页`);
                }
            });

            // 初始化页面
            renderTagsTable(tagsData);
            renderDeviceTags(deviceTagsData);
        });
    </script>
</body>
</html>
```

## 功能说明

这个设备标签管理页面具有以下功能：

1. **标签列表管理**：
   - 显示所有设备标签的列表，包括标签名称、分类、类型、颜色、关联设备数量等信息
   - 支持标签的创建、编辑和删除操作
   - 支持批量删除标签
   - 支持标签搜索和筛选

2. **标签创建/编辑模态框**：
   - 支持创建新标签或编辑现有标签
   - 可设置标签名称、分类、类型、颜色和描述
   - 标签类型分为系统标签和自定义标签

3. **设备标签关联展示**：
   - 显示设备与标签的关联关系
   - 每个设备卡片展示其关联的标签
   - 支持从设备上移除标签

4. **响应式设计**：
   - 页面适配不同屏幕尺寸
   - 侧边栏可折叠/展开
   - 移动端优化布局

5. **数据模拟**：
   - 页面加载时模拟了12个标签数据和6个设备标签关联数据
   - 所有操作都在前端模拟，实际项目中需要对接后端API

这个页面完全保持了与2.html一致的脚手架架构、图标和主题风格，同时实现了设备标签管理的核心功能。

