                    triggerTime: '2025-10-23 08:45:22',
                    status: 'new',
                    statusText: '新建',
                    duration: '8小时02分钟',
                    occurrenceCount: 5
                }
            ];

            // 渲染告警表格
            function renderAlertTable(data) {
                const tableBody = document.getElementById('alertTableBody');
                tableBody.innerHTML = '';

                data.forEach(alert => {
                    const row = document.createElement('tr');

                    // 确定级别和状态的CSS类
                    let levelClass = '';
                    switch(alert.level) {
                        case 'emergency': levelClass = 'alert-level-emergency'; break;
                        case 'critical': levelClass = 'alert-level-critical'; break;
                        case 'major': levelClass = 'alert-level-major'; break;
                        case 'minor': levelClass = 'alert-level-minor'; break;
                        case 'warning': levelClass = 'alert-level-warning'; break;
                    }

                    let statusClass = '';
                    switch(alert.status) {
                        case 'new': statusClass = 'alert-status-new'; break;
                        case 'confirmed': statusClass = 'alert-status-confirmed'; break;
                        case 'processing': statusClass = 'alert-status-processing'; break;
                        case 'resolved': statusClass = 'alert-status-resolved'; break;
                        case 'closed': statusClass = 'alert-status-closed'; break;
                        case 'ignored': statusClass = 'alert-status-ignored'; break;
                    }

                    row.innerHTML = `
                        <td><input type="checkbox" class="alert-checkbox" data-id="${alert.id}"></td>
                        <td>${alert.id}</td>
                        <td><span class="alert-level-badge ${levelClass}">${alert.levelText}</span></td>
                        <td>${alert.title}</td>
                        <td>${alert.deviceName}</td>
                        <td>${alert.deviceType}</td>
                        <td>${alert.intersection}</td>
                        <td>${alert.triggerTime}</td>
                        <td><span class="alert-status-badge ${statusClass}">${alert.statusText}</span></td>
                        <td>
                            <div class="alert-actions">
                                <button class="action-btn view" data-id="${alert.id}" title="查看详情">
                                    <i class="fas fa-eye"></i>
                                </button>
                                <button class="action-btn confirm" data-id="${alert.id}" title="确认告警">
                                    <i class="fas fa-check"></i>
                                </button>
                                <button class="action-btn resolve" data-id="${alert.id}" title="解决告警">
                                    <i class="fas fa-check-circle"></i>
                                </button>
                                <button class="action-btn ignore" data-id="${alert.id}" title="忽略告警">
                                    <i class="fas fa-times"></i>
                                </button>
                            </div>
                        </td>
                    `;

                    tableBody.appendChild(row);
                });

                // 绑定查看详情按钮事件
                document.querySelectorAll('.action-btn.view').forEach(btn => {
                    btn.addEventListener('click', function() {
                        const alertId = this.getAttribute('data-id');
                        showAlertDetail(alertId);
                    });
                });

                // 绑定处理告警按钮事件
                document.querySelectorAll('.action-btn.confirm, .action-btn.resolve, .action-btn.ignore').forEach(btn => {
                    btn.addEventListener('click', function() {
                        const alertId = this.getAttribute('data-id');
                        const action = this.classList.contains('confirm') ? 'confirm' : 
                                      this.classList.contains('resolve') ? 'resolve' : 'ignore';
                        showProcessAlertModal(alertId, action);
                    });
                });

                // 绑定复选框事件
                document.querySelectorAll('.alert-checkbox').forEach(checkbox => {
                    checkbox.addEventListener('change', updateSelectAllCheckbox);
                });
            }

            // 初始化渲染表格
            renderAlertTable(alertData);

            // 全选/全不选功能
            const selectAllCheckbox = document.getElementById('selectAllCheckbox');
            selectAllCheckbox.addEventListener('change', function() {
                const checkboxes = document.querySelectorAll('.alert-checkbox');
                checkboxes.forEach(checkbox => {
                    checkbox.checked = this.checked;
                });
            });

            // 更新全选复选框状态
            function updateSelectAllCheckbox() {
                const checkboxes = document.querySelectorAll('.alert-checkbox');
                const checkedCount = Array.from(checkboxes).filter(cb => cb.checked).length;
                selectAllCheckbox.checked = checkedCount === checkboxes.length && checkboxes.length > 0;
                selectAllCheckbox.indeterminate = checkedCount > 0 && checkedCount < checkboxes.length;
            }

            // 显示告警详情弹框
            function showAlertDetail(alertId) {
                // 查找告警数据
                const alert = alertData.find(a => a.id === alertId);
                if (!alert) return;

                // 填充详情数据
                document.getElementById('detailAlertId').textContent = alert.id;
                document.getElementById('detailAlertTitle').textContent = alert.title;
                document.getElementById('detailDeviceId').textContent = alert.deviceId;
                document.getElementById('detailDeviceName').textContent = alert.deviceName;
                document.getElementById('detailDeviceType').textContent = alert.deviceType;
                document.getElementById('detailIntersection').textContent = alert.intersection;
                document.getElementById('detailTriggerTime').textContent = alert.triggerTime;
                document.getElementById('detailDuration').textContent = alert.duration;
                document.getElementById('detailOccurrenceCount').textContent = `${alert.occurrenceCount}次`;

                // 设置级别和状态
                const levelBadge = document.getElementById('detailAlertLevel');
                levelBadge.className = 'alert-level-badge';
                levelBadge.classList.add(`alert-level-${alert.level}`);
                levelBadge.textContent = alert.levelText;

                const statusBadge = document.getElementById('detailAlertStatus');
                statusBadge.className = 'alert-status-badge';
                statusBadge.classList.add(`alert-status-${alert.status}`);
                statusBadge.textContent = alert.statusText;

                // 显示弹框
                document.getElementById('alertDetailModal').classList.add('active');
            }

            // 显示处理告警弹框
            function showProcessAlertModal(alertId, action) {
                // 查找告警数据
                const alert = alertData.find(a => a.id === alertId);
                if (!alert) return;

                // 填充数据
                document.getElementById('processAlertId').value = alert.id;
                document.getElementById('processAlertTitle').value = alert.title;

                // 根据操作类型设置默认选项
                const processTypeSelect = document.getElementById('processType');
                processTypeSelect.value = action;

                // 显示/隐藏升级处理人字段
                const escalateToGroup = document.getElementById('escalateToGroup');
                if (action === 'escalate') {
                    escalateToGroup.style.display = 'block';
                } else {
                    escalateToGroup.style.display = 'none';
                }

                // 显示弹框
                document.getElementById('processAlertModal').classList.add('active');
            }

            // 关闭详情弹框
            document.getElementById('closeDetailModal').addEventListener('click', function() {
                document.getElementById('alertDetailModal').classList.remove('active');
            });

            document.getElementById('closeDetailBtn').addEventListener('click', function() {
                document.getElementById('alertDetailModal').classList.remove('active');
            });

            // 关闭处理弹框
            document.getElementById('closeProcessModal').addEventListener('click', function() {
                document.getElementById('processAlertModal').classList.remove('active');
            });

            document.getElementById('cancelProcessBtn').addEventListener('click', function() {
                document.getElementById('processAlertModal').classList.remove('active');
            });

            // 提交处理
            document.getElementById('submitProcessBtn').addEventListener('click', function() {
                const alertId = document.getElementById('processAlertId').value;
                const processType = document.getElementById('processType').value;
                const description = document.getElementById('processDescription').value;

                if (!description.trim()) {
                    alert('请输入处理说明');
                    return;
                }

                // 在实际应用中，这里应该发送请求到服务器处理告警
                alert(`已提交处理：${alertId}，处理类型：${processType}，说明：${description}`);

                // 关闭弹框
                document.getElementById('processAlertModal').classList.remove('active');

                // 清空表单
                document.getElementById('processDescription').value = '';

                // 刷新表格数据
                alert('告警处理成功，表格已刷新');
            });

            // 处理类型变化时显示/隐藏升级处理人字段
            document.getElementById('processType').addEventListener('change', function() {
                const escalateToGroup = document.getElementById('escalateToGroup');
                if (this.value === 'escalate') {
                    escalateToGroup.style.display = 'block';
                } else {
                    escalateToGroup.style.display = 'none';
                }
            });

            // 批量处理按钮
            document.getElementById('batchProcessBtn').addEventListener('click', function() {
                const selectedAlerts = Array.from(document.querySelectorAll('.alert-checkbox:checked'))
                    .map(cb => cb.getAttribute('data-id'));

                if (selectedAlerts.length === 0) {
                    alert('请至少选择一个告警进行处理');
                    return;
                }

                alert(`批量处理 ${selectedAlerts.length} 个告警\n选中告警ID: ${selectedAlerts.join(', ')}`);
            });

            // 导出告警按钮
            document.getElementById('exportAlertsBtn').addEventListener('click', function() {
                alert('告警数据已导出为CSV文件');
            });

            // 全部确认按钮
            document.getElementById('ackAllBtn').addEventListener('click', function() {
                if (confirm('确定要确认所有未确认的告警吗？')) {
                    alert('所有未确认告警已标记为已确认');
                }
            });

            // 刷新按钮
            document.getElementById('refreshBtn').addEventListener('click', function() {
                alert('告警数据已刷新');
            });

            // 搜索按钮
            document.getElementById('searchBtn').addEventListener('click', function() {
                alert('已应用筛选条件');
            });

            // 重置筛选按钮
            document.getElementById('resetFilterBtn').addEventListener('click', function() {
                document.getElementById('alertLevelFilter').value = '';
                document.getElementById('alertStatusFilter').value = '';
                document.getElementById('deviceTypeFilter').value = '';
                document.getElementById('alertTypeFilter').value = '';
                document.getElementById('timeRangeFilter').value = 'today';
                document.getElementById('intersectionFilter').value = '';
                document.getElementById('keywordFilter').value = '';
                alert('筛选条件已重置');
            });

            // 保存筛选按钮
            document.getElementById('saveFilterBtn').addEventListener('click', function() {
                alert('当前筛选条件已保存');
            });

            // 分页按钮
            document.getElementById('prevPageBtn').addEventListener('click', function() {
                alert('切换到上一页');
            });

            document.getElementById('nextPageBtn').addEventListener('click', function() {
                alert('切换到下一页');
            });

            // 点击弹框外部关闭弹框
            document.querySelectorAll('.modal-overlay').forEach(modal => {
                modal.addEventListener('click', function(e) {
                    if (e.target === this) {
                        this.classList.remove('active');
                    }
                });
            });

            // 阻止弹框内部点击事件冒泡
            document.querySelectorAll('.modal').forEach(modal => {
                modal.addEventListener('click', function(e) {
                    e.stopPropagation();
                });
            });
        });
    </script>
</body>
</html>
```

## 功能说明

这个"事件和告警"页面实现了以下核心功能：

### 1. 页面布局与导航
- 保持与2.html一致的脚手架结构，包括头部、侧边栏和主内容区域
- 侧边栏可折叠/展开，当前"事件和告警"菜单项高亮显示
- 响应式设计，适配不同屏幕尺寸

### 2. 告警统计面板
- 显示紧急、严重、重要、一般、警告五个级别的告警统计
- 每个统计卡片显示当前数量及与昨日的对比趋势
- 不同级别的告警使用不同颜色标识

### 3. 告警筛选功能
- 提供多维度筛选条件：告警级别、状态、设备类型、告警类型、时间范围、路口、关键词
- 搜索、重置、保存筛选功能

### 4. 告警列表表格
- 展示告警ID、级别、标题、设备信息、触发时间、状态等关键信息
- 支持全选/单选操作
- 提供查看详情、确认、解决、忽略等操作按钮
- 分页功能

### 5. 弹框功能（二级页面）
- **告警详情弹框**：显示告警详细信息、处理时间线、处理建议和结果
- **处理告警弹框**：提供确认、解决、忽略、升级处理等操作

### 6. 交互功能
- 所有按钮都有相应的点击事件处理
- 表格数据动态渲染
- 弹框可点击外部或关闭按钮关闭
- 响应式设计，适配移动设备

页面完全基于HTML、CSS和原生JavaScript实现，没有依赖外部UI库，保持了与2.html一致的视觉风格和交互体验。

