                    <li class="nav-item" data-page="device-elements">
                        <i class="fas fa-draw-polygon"></i>
                        <span>设备要素</span>
                    </li>
                    <li class="nav-item" data-page="device-map">
                        <i class="fas fa-layer-group"></i>
                        <span>设备地图</span>
                    </li>
                </ul>
            </div>

            <!-- 设备统一纳管中心 -->
            <div class="sidebar-section">
                <div class="section-header" data-section="device-management">
                    <div class="section-title">
                        <i class="fas fa-server"></i>
                        <span>设备统一纳管中心</span>
                    </div>
                    <div class="section-arrow">
                        <i class="fas fa-chevron-right"></i>
                    </div>
                </div>
                <ul class="nav-menu">
                    <li class="nav-item" data-page="device-discovery">
                        <i class="fas fa-search"></i>
                        <span>设备发现与注册</span>
                    </li>
                    <li class="nav-item" data-page="device-grouping">
                        <i class="fas fa-object-group"></i>
                        <span>设备分组管理</span>
                    </li>
                    <li class="nav-item" data-page="device-tagging">
                        <i class="fas fa-tags"></i>
                        <span>设备标签管理</span>
                    </li>
                </ul>
            </div>

            <!-- 设备监控中心 -->
            <div class="sidebar-section">
                <div class="section-header" data-section="device-monitoring">
                    <div class="section-title">
                        <i class="fas fa-desktop"></i>
                        <span>设备监控中心</span>
                    </div>
                    <div class="section-arrow">
                        <i class="fas fa-chevron-right"></i>
                    </div>
                </div>
                <ul class="nav-menu">
                    <li class="nav-item" data-page="device-monitor">
                        <i class="fas fa-desktop"></i>
                        <span>设备监控</span>
                    </li>
                    <li class="nav-item" data-page="resource-monitor">
                        <i class="fas fa-chart-line"></i>
                        <span>资源监控</span>
                    </li>
                    <li class="nav-item" data-page="video-quality">
                        <i class="fas fa-video"></i>
                        <span>视频流质量监测</span>
                    </li>
                    <li class="nav-item active" data-page="video-status">
                        <i class="fas fa-signal"></i>
                        <span>视频通道状态</span>
                    </li>
                </ul>
            </div>

            <!-- 视频流集成 -->
            <div class="sidebar-section">
                <div class="section-header" data-section="video-integration">
                    <div class="section-title">
                        <i class="fas fa-video"></i>
                        <span>视频流集成</span>
                    </div>
                    <div class="section-arrow">
                        <i class="fas fa-chevron-right"></i>
                    </div>
                </div>
                <ul class="nav-menu collapsed">
