                        <i class="fas fa-traffic-light"></i>
                        <span>相位/周期配置</span>
                    </li>
                    <li class="nav-item" data-page="edge-strategy">
                        <i class="fas fa-cogs"></i>
                        <span>边缘计算策略</span>
                    </li>
                    <li class="nav-item" data-page="operation-log">
                        <i class="fas fa-clipboard-list"></i>
                        <span>操作日志审计</span>
                    </li>
                </ul>
            </div>
        </div>

        <div class="main-content" id="mainContent">
            <div class="page-header">
                <div>
                    <div class="page-title">视频通道状态</div>
                    <div style="font-size: 0.9rem; color: #8c8c8c; margin-top: 5px;">监控和管理所有视频通道的运行状态与质量指标</div>
                </div>
                <div class="page-controls">
                    <button class="btn btn-primary" id="addChannelBtn">
                        <i class="fas fa-plus"></i>
                        新增通道
                    </button>
                    <button class="btn btn-info" id="refreshBtn">
                        <i class="fas fa-sync-alt"></i>
                        刷新状态
                    </button>
                    <button class="btn" id="exportBtn">
                        <i class="fas fa-download"></i>
                        导出数据
                    </button>
                </div>
            </div>

            <!-- 统计卡片 -->
            <div class="stats-cards">
                <div class="stat-card">
                    <div class="stat-icon normal">
                        <i class="fas fa-check-circle"></i>
                    </div>
                    <div class="stat-info">
                        <h3>128</h3>
                        <p>正常通道</p>
                    </div>
                </div>
                <div class="stat-card">
                    <div class="stat-icon warning">
                        <i class="fas fa-exclamation-triangle"></i>
                    </div>
                    <div class="stat-info">
                        <h3>12</h3>
                        <p>异常通道</p>
                    </div>
                </div>
                <div class="stat-card">
                    <div class="stat-icon error">
                        <i class="fas fa-times-circle"></i>
                    </div>
                    <div class="stat-info">
                        <h3>5</h3>
                        <p>故障通道</p>
                    </div>
                </div>
                <div class="stat-card">
                    <div class="stat-icon offline">
                        <i class="fas fa-power-off"></i>
                    </div>
                    <div class="stat-info">
                        <h3>8</h3>
                        <p>离线通道</p>
                    </div>
                </div>
            </div>

            <!-- 筛选栏 -->
            <div class="filter-bar">
                <div class="filter-group">
                    <label>路口:</label>
                    <select class="filter-select" id="intersectionFilter">
                        <option value="">全部路口</option>
                        <option value="INT-001">路口A (INT-001)</option>
                        <option value="INT-002">路口B (INT-002)</option>
                        <option value="INT-003">路口C (INT-003)</option>
                        <option value="INT-004">路口D (INT-004)</option>
                    </select>
                </div>

                <div class="filter-group">
                    <label>状态:</label>
                    <select class="filter-select" id="statusFilter">
                        <option value="">全部状态</option>
                        <option value="normal">正常</option>
                        <option value="warning">异常</option>
                        <option value="error">故障</option>
                        <option value="offline">离线</option>
                    </select>
                </div>

                <div class="filter-group">
                    <label>设备类型:</label>
                    <select class="filter-select" id="deviceTypeFilter">
                        <option value="">全部类型</option>
                        <option value="camera">摄像机</option>
                        <option value="nvr">NVR</option>
                        <option value="dvr">DVR</option>
                        <option value="encoder">编码器</option>
                    </select>
                </div>

                <div class="filter-group">
                    <label>通道ID:</label>
                    <input type="text" class="filter-input" id="channelIdFilter" placeholder="输入通道ID">
                </div>

                <button class="btn" id="filterBtn">
                    <i class="fas fa-filter"></i>
                    筛选
                </button>
                <button class="btn" id="resetFilterBtn">
                    <i class="fas fa-redo"></i>
                    重置
                </button>
            </div>

            <!-- 表格区域 -->
            <div class="table-container">
                <div class="table-header">
                    <h3>视频通道列表</h3>
                    <div class="table-actions">
                        <button class="btn" id="bulkEnableBtn">
                            <i class="fas fa-play"></i>
                            批量启用
                        </button>
                        <button class="btn btn-warning" id="bulkDisableBtn">
                            <i class="fas fa-pause"></i>
                            批量禁用
                        </button>
                        <button class="btn btn-danger" id="bulkDeleteBtn">
                            <i class="fas fa-trash"></i>
                            批量删除
                        </button>
                    </div>
                </div>

                <div class="table-wrapper">
                    <table class="video-channel-table">
