    <!-- 新增/编辑通道弹框 -->
    <div class="modal-overlay" id="channelModal">
        <div class="modal">
            <div class="modal-header">
                <div class="modal-title" id="modalTitle">新增视频通道</div>
                <button class="modal-close" id="closeModalBtn">&times;</button>
            </div>
            <div class="modal-body">
                <form id="channelForm">
                    <div class="form-row">
                        <div class="form-group">
                            <label for="channelId">通道ID *</label>
                            <input type="text" id="channelId" class="form-control" required>
                        </div>
                        <div class="form-group">
                            <label for="channelName">通道名称 *</label>
                            <input type="text" id="channelName" class="form-control" required>
                        </div>
                    </div>

                    <div class="form-row">
                        <div class="form-group">
                            <label for="deviceId">设备ID *</label>
                            <input type="text" id="deviceId" class="form-control" required>
                        </div>
                        <div class="form-group">
                            <label for="deviceType">设备类型 *</label>
                            <select id="deviceType" class="form-control" required>
                                <option value="">请选择</option>
                                <option value="camera">摄像机</option>
                                <option value="nvr">NVR</option>
                                <option value="dvr">DVR</option>
                                <option value="encoder">编码器</option>
                            </select>
                        </div>
                    </div>

                    <div class="form-row">
                        <div class="form-group">
                            <label for="intersectionId">路口 *</label>
                            <select id="intersectionId" class="form-control" required>
                                <option value="">请选择</option>
                                <option value="INT-001">路口A (INT-001)</option>
                                <option value="INT-002">路口B (INT-002)</option>
                                <option value="INT-003">路口C (INT-003)</option>
                                <option value="INT-004">路口D (INT-004)</option>
                            </select>
                        </div>
                        <div class="form-group">
                            <label for="protocolType">协议类型 *</label>
                            <select id="protocolType" class="form-control" required>
                                <option value="">请选择</option>
                                <option value="rtsp">RTSP</option>
