        // 渲染表格
        function renderChannelTable(data) {
            const tbody = document.getElementById('channelTableBody');
            tbody.innerHTML = '';

            data.forEach(channel => {
                const row = document.createElement('tr');

                // 状态类名和显示文本
                let statusClass = '';
                let statusText = '';
                switch(channel.status) {
                    case 'normal':
                        statusClass = 'status-normal';
                        statusText = '正常';
                        break;
                    case 'warning':
                        statusClass = 'status-warning';
                        statusText = '异常';
                        break;
                    case 'error':
                        statusClass = 'status-error';
                        statusText = '故障';
                        break;
                    case 'offline':
                        statusClass = 'status-offline';
                        statusText = '离线';
                        break;
                }

                // 信号强度条
                let signalBars = '';
                let signalValue = channel.signalStrength;
                let barClass = '';

                if (signalValue >= 80) barClass = 'active';
                else if (signalValue >= 60) barClass = 'warning';
                else if (signalValue > 0) barClass = 'error';

                for (let i = 1; i <= 5; i++) {
                    const active = signalValue >= (i * 20);
                    signalBars += `<div class="signal-bar ${active ? barClass : ''}"></div>`;
                }

                row.innerHTML = `
                    <td><input type="checkbox" class="channel-checkbox" data-id="${channel.id}"></td>
                    <td>${channel.channelId}</td>
                    <td>${channel.channelName}</td>
                    <td>${getDeviceTypeText(channel.deviceType)}</td>
                    <td>${channel.intersection}</td>
                    <td><span class="channel-status ${statusClass}">${statusText}</span></td>
                    <td>
                        <div class="signal-strength">
                            <div class="signal-bars">
                                ${signalBars}
                            </div>
                            <span>${channel.signalStrength}%</span>
                        </div>
                    </td>
                    <td>${channel.frameRate}</td>
                    <td>${channel.bitRate}</td>
                    <td>${channel.lastCheck}</td>
                    <td>
