                                <i class="fas fa-eye"></i> 查看
                            </button>
                            <button class="action-btn edit" data-id="${channel.id}" onclick="editChannel(${channel.id})">
                                <i class="fas fa-edit"></i> 编辑
                            </button>
                            <button class="action-btn delete" data-id="${channel.id}" onclick="deleteChannel(${channel.id})">
