        // 应用筛选
        function applyFilters() {
            const intersection = document.getElementById('intersectionFilter').value;
            const status = document.getElementById('statusFilter').value;
            const deviceType = document.getElementById('deviceTypeFilter').value;
            const channelId = document.getElementById('channelIdFilter').value.toLowerCase();

            let filteredData = channelData;

            if (intersection) {
                filteredData = filteredData.filter(channel => {
                    const channelIntersection = channel.intersection === '路口A' ? 'INT-001' : 
                                               channel.intersection === '路口B' ? 'INT-002' :
                                               channel.intersection === '路口C' ? 'INT-003' :
                                               channel.intersection === '路口D' ? 'INT-004' : '';
                    return channelIntersection === intersection;
                });
            }

            if (status) {
                filteredData = filteredData.filter(channel => channel.status === status);
            }

            if (deviceType) {
                filteredData = filteredData.filter(channel => channel.deviceType === deviceType);
            }

            if (channelId) {
                filteredData = filteredData.filter(channel => channel.channelId.toLowerCase().includes(channelId));
