    <script>
        // 初始化侧边栏展开/折叠功能
        document.addEventListener('DOMContentLoaded', function() {
            // 侧边栏折叠切换
            const sidebar = document.getElementById('sidebar');
            const sidebarToggle = document.getElementById('sidebarToggle');
            const mainContent = document.getElementById('mainContent');

            sidebarToggle.addEventListener('click', function() {
                sidebar.classList.toggle('collapsed');
                mainContent.classList.toggle('expanded');

                // 切换箭头方向
                const icon = sidebarToggle.querySelector('i');
                if (sidebar.classList.contains('collapsed')) {
                    icon.className = 'fas fa-chevron-right';
                } else {
                    icon.className = 'fas fa-chevron-left';
                }
            });

            // 侧边栏章节展开/折叠
            const sectionHeaders = document.querySelectorAll('.section-header');
            sectionHeaders.forEach(header => {
                header.addEventListener('click', function() {
                    const arrow = this.querySelector('.section-arrow');
                    const menu = this.nextElementSibling;

                    // 如果侧边栏是折叠状态，先展开侧边栏
                    if (sidebar.classList.contains('collapsed')) {
                        sidebar.classList.remove('collapsed');
                        mainContent.classList.remove('expanded');
                        sidebarToggle.querySelector('i').className = 'fas fa-chevron-left';
                    }

                    arrow.classList.toggle('rotated');
                    menu.classList.toggle('collapsed');
                });
            });

            // 默认展开视频集成章节
            const videoSection = document.querySelector('[data-section="video-integration"]');
            if (videoSection) {
                const videoArrow = videoSection.querySelector('.section-arrow');
                const videoMenu = videoSection.nextElementSibling;
                videoArrow.classList.add('rotated');
                videoMenu.classList.remove('collapsed');
            }

            // 导航菜单点击事件
            document.querySelectorAll('.nav-item').forEach(item => {
                item.addEventListener('click', function() {
                    // 移除所有active类
                    document.querySelectorAll('.nav-item.active').forEach(el => {
                        el.classList.remove('active');
                    });

                    // 为当前项添加active类
                    this.classList.add('active');

                    // 根据点击的菜单项切换页面内容
                    const pageTitle = this.querySelector('span').textContent;
                    document.querySelector('.page-title').textContent = pageTitle;
                });
            });

            // 初始化ECharts图表
            initCharts();

            // 初始化表格数据
            initTableData();

            // 按钮事件绑定
            document.getElementById('addChannelBtn').addEventListener('click', function() {
                openChannelModal('add');
            });

            document.getElementById('refreshBtn').addEventListener('click', function() {
                refreshData();
            });

            document.getElementById('exportBtn').addEventListener('click', function() {
                exportReport();
            });

            // 搜索和筛选事件
            document.getElementById('searchInput').addEventListener('input', function() {
                filterTable();
            });

            document.getElementById('statusFilter').addEventListener('change', function() {
                filterTable();
            });

            // 弹窗事件绑定
            const channelModal = document.getElementById('channelModal');
            const detailModal = document.getElementById('detailModal');

            document.getElementById('closeModalBtn').addEventListener('click', function() {
                channelModal.classList.remove('active');
            });

            document.getElementById('closeDetailModalBtn').addEventListener('click', function() {
                detailModal.classList.remove('active');
            });

            document.getElementById('cancelBtn').addEventListener('click', function() {
                channelModal.classList.remove('active');
            });

            document.getElementById('closeDetailBtn').addEventListener('click', function() {
                detailModal.classList.remove('active');
            });

            document.getElementById('saveBtn').addEventListener('click', function() {
                saveChannel();
            });

            document.getElementById('editDetailBtn').addEventListener('click', function() {
                detailModal.classList.remove('active');
                setTimeout(() => {
                    openChannelModal('edit');
                }, 300);
            });

            // 点击弹窗外部关闭弹窗
            channelModal.addEventListener('click', function(e) {
                if (e.target === channelModal) {
                    channelModal.classList.remove('active');
                }
            });

            detailModal.addEventListener('click', function(e) {
                if (e.target === detailModal) {
                    detailModal.classList.remove('active');
                }
            });
        });

