                                <i class="fas fa-edit"></i>
                            </div>
                            <div class="action-btn action-btn-danger" title="删除" onclick="deleteChannel(${channel.id})">
                                <i class="fas fa-trash"></i>
                            </div>
                        </div>
                    </td>
