        // 过滤表格
        function filterTable() {
            const searchText = document.getElementById('searchInput').value.toLowerCase();
            const statusFilter = document.getElementById('statusFilter').value;

            // 在实际应用中，这里应该向服务器发送过滤请求
            // 这里只是演示，所以使用模拟数据
            const allRows = document.querySelectorAll('#channelTableBody tr');

            allRows.forEach(row => {
                const name = row.cells[0].textContent.toLowerCase();
                const deviceId = row.cells[1].textContent.toLowerCase();
                const statusElement = row.cells[3].querySelector('.status-indicator');

                let statusMatch = true;
                if (statusFilter) {
                    let statusClass = '';
                    switch(statusFilter) {
                        case 'normal': statusClass = 'status-normal'; break;
                        case 'abnormal': statusClass = 'status-abnormal'; break;
                        case 'no-signal': statusClass = 'status-no-signal'; break;
                        case 'offline': statusClass = 'status-offline'; break;
                        case 'maintenance': statusClass = 'status-maintenance'; break;
                    }

                    statusMatch = statusElement.classList.contains(statusClass);
                }

                const textMatch = name.includes(searchText) || deviceId.includes(searchText);

                if (textMatch && statusMatch) {
                    row.style.display = '';
                } else {
                    row.style.display = 'none';
                }
            });
