            data.forEach(channel => {
                const row = document.createElement('tr');

                // 状态文本和颜色
                let statusText = '';
                let statusClass = '';
                let statusColor = '';
                switch(channel.status) {
                    case 'normal':
                        statusText = '正常';
                        statusClass = 'status-normal';
                        statusColor = '#52c41a';
                        break;
                    case 'abnormal':
                        statusText = '异常';
                        statusClass = 'status-abnormal';
                        statusColor = '#faad14';
                        break;
                    case 'no-signal':
                        statusText = '无信号';
                        statusClass = 'status-no-signal';
                        statusColor = '#ff4d4f';
                        break;
                    case 'offline':
                        statusText = '离线';
                        statusClass = 'status-offline';
                        statusColor = '#8c8c8c';
                        break;
                    case 'maintenance':
                        statusText = '维护中';
                        statusClass = 'status-maintenance';
                        statusColor = '#1890ff';
                        break;
                }

                // 信号强度颜色
                let signalColor = '#52c41a';
                if (channel.signalStrength <= 30) signalColor = '#ff4d4f';
                else if (channel.signalStrength <= 70) signalColor = '#faad14';

                row.innerHTML = `
                    <td style="font-weight: 500;">${channel.name}</td>
                    <td><span style="background-color: #f0f7ff; padding: 4px 8px; border-radius: 4px; color: #1890ff;">${channel.deviceId}</span></td>
                    <td>${channel.intersection}</td>
                    <td>
                        <span class="status-indicator ${statusClass}"></span>
                        <span style="color: ${statusColor}; font-weight: 500;">${statusText}</span>
                    </td>
                    <td>
                        ${channel.signalStrength}%
                        <div class="signal-progress">
                            <div class="signal-bar" style="width: ${channel.signalStrength}%; background: linear-gradient(90deg, ${signalColor}, ${signalColor}99);"></div>
                        </div>
                    </td>
                    <td>${channel.resolution}</td>
                    <td><span style="background-color: #f6ffed; padding: 4px 8px; border-radius: 4px; color: #389e0d; font-weight: 500;">${channel.frameRate} fps</span></td>
                    <td>${channel.bitRate} kbps</td>
                    <td>${channel.lastCheck}</td>
                    <td>
                        <div class="table-actions">
                            <div class="action-btn action-btn-primary" title="查看详情" onclick="showDetail(${channel.id})">
                                <i class="fas fa-eye"></i>
                            </div>
                            <div class="action-btn action-btn-warning" title="编辑" onclick="editChannel(${channel.id})">
                                <i class="fas fa-edit"></i>
                            </div>
                            <div class="action-btn action-btn-danger" title="删除" onclick="deleteChannel(${channel.id})">
                                <i class="fas fa-trash"></i>
                            </div>
                        </div>
                    </td>
                `;

                tableBody.appendChild(row);
            });
        }

        // 过滤表格
        function filterTable() {
            const searchText = document.getElementById('searchInput').value.toLowerCase();
            const statusFilter = document.getElementById('statusFilter').value;

            // 在实际应用中，这里应该向服务器发送过滤请求
            // 这里只是演示，所以使用模拟数据
            const allRows = document.querySelectorAll('#channelTableBody tr');

            allRows.forEach(row => {
                const name = row.cells[0].textContent.toLowerCase();
                const deviceId = row.cells[1].textContent.toLowerCase();
                const statusElement = row.cells[3].querySelector('.status-indicator');

                let statusMatch = true;
                if (statusFilter) {
                    let statusClass = '';
                    switch(statusFilter) {
                        case 'normal': statusClass = 'status-normal'; break;
                        case 'abnormal': statusClass = 'status-abnormal'; break;
                        case 'no-signal': statusClass = 'status-no-signal'; break;
                        case 'offline': statusClass = 'status-offline'; break;
                        case 'maintenance': statusClass = 'status-maintenance'; break;
                    }

                    statusMatch = statusElement.classList.contains(statusClass);
                }

                const textMatch = name.includes(searchText) || deviceId.includes(searchText);

                if (textMatch && statusMatch) {
                    row.style.display = '';
                } else {
                    row.style.display = 'none';
                }
            });
        }

