                document.getElementById('intersectionId').value = '1';
                document.getElementById('channelId').value = 'CH-001';
                document.getElementById('streamUrl').value = 'rtsp://192.168.1.100:554/stream1';
                document.getElementById('protocolType').value = 'RTSP';
