    <script>
        // 初始化侧边栏展开/折叠功能
        document.addEventListener('DOMContentLoaded', function() {
            // 侧边栏折叠切换
            const sidebar = document.getElementById('sidebar');
            const sidebarToggle = document.getElementById('sidebarToggle');
            const mainContent = document.getElementById('mainContent');

            sidebarToggle.addEventListener('click', function() {
                sidebar.classList.toggle('collapsed');
                mainContent.classList.toggle('expanded');

                // 切换箭头方向
                const icon = sidebarToggle.querySelector('i');
                if (sidebar.classList.contains('collapsed')) {
                    icon.className = 'fas fa-chevron-right';
                } else {
                    icon.className = 'fas fa-chevron-left';
                }
            });

            // 侧边栏章节展开/折叠
            const sectionHeaders = document.querySelectorAll('.section-header');
            sectionHeaders.forEach(header => {
                header.addEventListener('click', function() {
                    const arrow = this.querySelector('.section-arrow');
                    const menu = this.nextElementSibling;

                    // 如果侧边栏是折叠状态，先展开侧边栏
                    if (sidebar.classList.contains('collapsed')) {
                        sidebar.classList.remove('collapsed');
                        mainContent.classList.remove('expanded');
                        sidebarToggle.querySelector('i').className = 'fas fa-chevron-left';
                    }

                    arrow.classList.toggle('rotated');
                    menu.classList.toggle('collapsed');
                });
            });

            // 默认展开远程配置与控制章节
            const remoteSection = document.querySelector('[data-section="remote-config"]');
            if (remoteSection) {
                const remoteArrow = remoteSection.querySelector('.section-arrow');
                const remoteMenu = remoteSection.nextElementSibling;
                remoteArrow.classList.add('rotated');
                remoteMenu.classList.remove('collapsed');
            }

            // 导航菜单点击事件
            document.querySelectorAll('.nav-item').forEach(item => {
                item.addEventListener('click', function() {
                    // 移除所有active类
                    document.querySelectorAll('.nav-item.active').forEach(el => {
                        el.classList.remove('active');
                    });

                    // 为当前项添加active类
                    this.classList.add('active');

                    // 根据点击的菜单项切换页面内容
                    const pageTitle = this.querySelector('span').textContent;
                    document.querySelector('.page-title').textContent = pageTitle;
                });
            });

            // 初始化ECharts图表
            initCharts();

            // 初始化表格数据
            initTableData();

            // 按钮事件绑定
            document.getElementById('exportReportBtn').addEventListener('click', function() {
                exportAuditReport();
            });

            document.getElementById('complianceCheckBtn').addEventListener('click', function() {
                runComplianceCheck();
            });

            document.getElementById('exportAllBtn').addEventListener('click', function() {
                exportAllLogs();
            });

            document.getElementById('exportSelectedBtn').addEventListener('click', function() {
                exportSelectedLogs();
            });

            document.getElementById('filterToggle').addEventListener('click', function() {
                const filterContent = document.getElementById('filterContent');
                if (filterContent.style.display === 'none') {
                    filterContent.style.display = 'grid';
                    this.querySelector('span').textContent = '隐藏筛选条件';
                } else {
                    filterContent.style.display = 'none';
                    this.querySelector('span').textContent = '显示筛选条件';
                }
            });

            document.getElementById('clearFiltersBtn').addEventListener('click', function() {
                clearFilters();
            });

            document.getElementById('applyFiltersBtn').addEventListener('click', function() {
                applyFilters();
            });

            // 全选/全不选功能
            document.getElementById('selectAllCheckbox').addEventListener('change', function() {
                const checkboxes = document.querySelectorAll('.log-checkbox');
                checkboxes.forEach(checkbox => {
                    checkbox.checked = this.checked;
                });
            });

            // 搜索功能
            document.getElementById('searchInput').addEventListener('input', function() {
                filterTable();
            });

            // 弹窗事件绑定
            const detailModal = document.getElementById('detailModal');

            document.getElementById('closeDetailModalBtn').addEventListener('click', function() {
                detailModal.classList.remove('active');
            });

            document.getElementById('closeDetailBtn').addEventListener('click', function() {
                detailModal.classList.remove('active');
            });

            document.getElementById('exportDetailBtn').addEventListener('click', function() {
                exportSingleLog();
            });

            document.getElementById('detailComplianceBtn').addEventListener('click', function() {
                runSingleComplianceCheck();
            });

            // 点击弹窗外部关闭弹窗
            detailModal.addEventListener('click', function(e) {
                if (e.target === detailModal) {
                    detailModal.classList.remove('active');
                }
            });

            // 分页事件
            document.getElementById('prevPage').addEventListener('click', function() {
                changePage('prev');
            });

            document.getElementById('nextPage').addEventListener('click', function() {
                changePage('next');
            });
        });

