        // 渲染表格
        function renderTable(data) {
            const tableBody = document.getElementById('logTableBody');
            tableBody.innerHTML = '';

            data.forEach(log => {
                const row = document.createElement('tr');

                // 结果状态文本和样式
                let resultText = '';
                let resultClass = '';
                switch(log.resultStatus) {
                    case 'success':
                        resultText = '成功';
                        resultClass = 'status-success';
                        break;
                    case 'failed':
                        resultText = '失败';
                        resultClass = 'status-failed';
                        break;
                    case 'partial':
                        resultText = '部分成功';
                        resultClass = 'status-partial';
                        break;
                    case 'timeout':
                        resultText = '超时';
                        resultClass = 'status-timeout';
                        break;
                    case 'unauthorized':
                        resultText = '未授权';
                        resultClass = 'status-unauthorized';
                        break;
                }

                // 风险等级文本和样式
                let riskText = '';
                let riskClass = '';
                switch(log.riskLevel) {
                    case 'low':
                        riskText = '低风险';
                        riskClass = 'risk-low';
                        break;
                    case 'medium':
                        riskText = '中风险';
                        riskClass = 'risk-medium';
                        break;
                    case 'high':
                        riskText = '高风险';
                        riskClass = 'risk-high';
                        break;
                    case 'critical':
                        riskText = '严重风险';
                        riskClass = 'risk-critical';
                        break;
                }

                row.innerHTML = `
                    <td>
                        <input type="checkbox" class="log-checkbox" data-id="${log.id}">
                    </td>
                    <td><span style="background-color: #f0f7ff; padding: 4px 8px; border-radius: 4px; color: #1890ff; font-weight: 500;">${log.logId}</span></td>
                    <td>${log.operationType}</td>
                    <td style="font-weight: 500;">${log.operationName}</td>
                    <td>${log.operator}</td>
                    <td>
                        <div>${log.deviceName}</div>
                        <div style="font-size: 0.85rem; color: #8c8c8c;">${log.deviceId}</div>
                    </td>
                    <td>${log.operationTime}</td>
                    <td>
                        <span class="status-badge ${resultClass}">${resultText}</span>
                        <div style="font-size: 0.85rem; color: #8c8c8c; margin-top: 5px;">${log.duration}</div>
                    </td>
                    <td>
                        <span class="risk-badge ${riskClass}">${riskText}</span>
                    </td>
