        // 切换分页
        function changePage(direction) {
            const activeBtn = document.querySelector('.pagination-btn.active');
            let currentPage = parseInt(activeBtn.textContent);

            if (direction === 'prev' && currentPage > 1) {
                currentPage--;
            } else if (direction === 'next' && currentPage < 5) {
                currentPage++;
            }

            // 更新分页按钮状态
            document.querySelectorAll('.pagination-btn').forEach(btn => {
                if (!btn.querySelector('i')) {
                    if (parseInt(btn.textContent) === currentPage) {
                        btn.classList.add('active');
                    } else {
                        btn.classList.remove('active');
                    }
                }
            });

            // 在实际应用中，这里应该加载对应页面的数据
            showNotification(`已切换到第 ${currentPage} 页`, 'info');
        }

