            }

            .content-area {
                padding: 15px;
            }

            .module-card {
                padding: 20px;
            }

            .filter-container {
                flex-direction: column;
            }

            .filter-group {
                min-width: 100%;
            }
        }

        /* IP地址样式 */
        .ip-address {
            font-family: monospace;
            background-color: #f5f5f5;
            padding: 2px 6px;
            border-radius: 4px;
            font-size: 13px;
        }
