            exportLogBtn.addEventListener('click', exportAuditLog);

            // 刷新按钮
            refreshLogBtn.addEventListener('click', refreshAuditLog);

            // 筛选按钮
            applyFiltersBtn.addEventListener('click', applyFilters);

            // 重置按钮
            resetFiltersBtn.addEventListener('click', resetFilters);

            // 搜索按钮
            searchBtn.addEventListener('click', searchAuditLog);

            // 搜索框回车事件
            searchInput.addEventListener('keyup', (e) => {
                if (e.key === 'Enter') {
                    searchAuditLog();
                }
            });

            // 模态框关闭按钮
            closeDetailModalBtn.addEventListener('click', closeLogDetailModal);
            closeModalBtn.addEventListener('click', closeLogDetailModal);

