        // 应用筛选
        function applyFilters() {
            const operationTypeFilter = document.getElementById('operationTypeFilter').value;
            const resultFilter = document.getElementById('resultFilter').value;
            const startDate = document.getElementById('startDate').value;
            const endDate = document.getElementById('endDate').value;

            filteredLogs = auditLogData.filter(log => {
                const logDate = log.time.split(' ')[0];
                const typeMatch = !operationTypeFilter || log.type === operationTypeFilter;
                const resultMatch = !resultFilter || log.result === resultFilter;
                const dateMatch = (!startDate || logDate >= startDate) && (!endDate || logDate <= endDate);

                return typeMatch && resultMatch && dateMatch;
            });

            currentPage = 1;
            renderAuditLogTable();
            renderPagination();
            updateStats();
        }

        // 重置筛选
        function resetFilters() {
            document.getElementById('operationTypeFilter').value = '';
            document.getElementById('resultFilter').value = '';

            // 设置默认日期为最近10天
            const today = new Date();
            const tenDaysAgo = new Date();
            tenDaysAgo.setDate(today.getDate() - 9);

            document.getElementById('startDate').value = formatDate(tenDaysAgo);
            document.getElementById('endDate').value = formatDate(today);

            searchInput.value = '';

            filteredLogs = [...auditLogData];
            currentPage = 1;
            renderAuditLogTable();
            renderPagination();
            updateStats();
        }

