        .status-disabled {
            background-color: #fee;
            color: #dc2626;
        }

        .action-cell {
            display: flex;
            gap: 10px;
        }

        .action-icon {
            width: 32px;
            height: 32px;
            border-radius: 6px;
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            transition: all 0.2s ease;
        }

        .view-icon {
            background-color: #e8f4ff;
            color: #1a3a8f;
        }

        .view-icon:hover {
            background-color: #d0e3ff;
        }

        .edit-icon {
            background-color: #f0f5ff;
            color: #4f46e5;
        }

        .edit-icon:hover {
            background-color: #e1e9ff;
        }

        .delete-icon {
            background-color: #fee;
            color: #dc2626;
        }

        .delete-icon:hover {
            background-color: #fdd;
        }

        /* 分页样式 */
        .pagination-container {
            display: flex;
            justify-content: center;
            align-items: center;
            margin-top: 30px;
            padding-top: 20px;
            border-top: 1px solid #eee;
        }

        .pagination {
            display: flex;
            list-style: none;
            gap: 5px;
        }

        .page-item {
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .page-link {
            width: 40px;
            height: 40px;
            display: flex;
            align-items: center;
            justify-content: center;
            border-radius: 6px;
            background-color: white;
            border: 1px solid #ddd;
            color: #555;
