            background-color: #1a3a8f;
            border-color: #1a3a8f;
            color: white;
        }

        .page-link.disabled {
            background-color: #f5f5f5;
            color: #999;
            cursor: not-allowed;
        }

        .pagination-info {
            margin-left: 20px;
            color: #666;
            font-size: 14px;
        }

        /* 统计卡片 */
        .stats-container {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
            gap: 20px;
            margin-bottom: 30px;
        }

        .stat-card {
            background-color: white;
            border-radius: 10px;
            padding: 20px;
            box-shadow: 0 3px 10px rgba(0, 0, 0, 0.05);
            border-left: 4px solid #1a3a8f;
        }

        .stat-title {
            font-size: 14px;
            color: #666;
            margin-bottom: 10px;
        }

        .stat-value {
            font-size: 28px;
            font-weight: 600;
            color: #1a3a8f;
        }

        /* 模态框样式 */
        .modal-overlay {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background-color: rgba(0, 0, 0, 0.5);
            display: flex;
            align-items: center;
            justify-content: center;
            z-index: 100;
            opacity: 0;
            visibility: hidden;
            transition: all 0.3s ease;
        }

        .modal-overlay.active {
            opacity: 1;
            visibility: visible;
        }

        .modal {
            background-color: white;
            border-radius: 12px;
            width: 800px;
            max-width: 90%;
            max-height: 90vh;
            overflow-y: auto;
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
            transform: translateY(20px);
            transition: transform 0.3s ease;
        }

        .modal-overlay.active .modal {
            transform: translateY(0);
        }

        .modal-header {
            padding: 25px 30px;
            border-bottom: 1px solid #eee;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .modal-title {
            font-size: 20px;
            font-weight: 600;
            color: #1a3a8f;
        }

        .modal-close {
            background: none;
            border: none;
            font-size: 20px;
            cursor: pointer;
            color: #999;
            transition: color 0.2s;
        }

        .modal-close:hover {
            color: #333;
        }

        .modal-body {
            padding: 30px;
        }

        .form-group {
            margin-bottom: 20px;
        }

        .form-label {
            display: block;
            margin-bottom: 8px;
            font-weight: 500;
            color: #555;
        }

        .form-control {
            width: 100%;
            padding: 12px 15px;
            border: 1px solid #ddd;
            border-radius: 6px;
            font-size: 15px;
            transition: border 0.2s;
        }

        .form-control:focus {
            outline: none;
            border-color: #1a3a8f;
            box-shadow: 0 0 0 3px rgba(26, 58, 143, 0.1);
        }

        .select-control {
            width: 100%;
            padding: 12px 15px;
            border: 1px solid #ddd;
            border-radius: 6px;
            font-size: 15px;
            background-color: white;
            transition: border 0.2s;
        }

        .modal-footer {
            padding: 20px 30px;
            border-top: 1px solid #eee;
            display: flex;
            justify-content: flex-end;
            gap: 15px;
        }

        /* 流程节点管理 */
        .process-nodes-container {
            margin-top: 20px;
            border: 1px solid #eee;
            border-radius: 8px;
            padding: 20px;
            background-color: #f9fafc;
        }

        .nodes-section-title {
            font-size: 16px;
            font-weight: 600;
            color: #1a3a8f;
            margin-bottom: 15px;
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .available-nodes {
            display: flex;
            flex-wrap: wrap;
            gap: 10px;
            margin-bottom: 25px;
        }

        .node-item {
            background-color: white;
            border: 1px solid #ddd;
            border-radius: 6px;
            padding: 12px 15px;
            cursor: grab;
            user-select: none;
            transition: all 0.2s;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .node-item:hover {
            border-color: #1a3a8f;
            box-shadow: 0 2px 8px rgba(26, 58, 143, 0.1);
        }

        .node-item i {
            color: #1a3a8f;
        }

        .selected-nodes-container {
            min-height: 150px;
            border: 2px dashed #ddd;
            border-radius: 8px;
            padding: 20px;
            margin-bottom: 20px;
            background-color: white;
        }

        .selected-nodes {
            display: flex;
            flex-direction: column;
            gap: 12px;
            min-height: 100px;
        }

        .selected-node {
            background-color: #f0f5ff;
            border: 1px solid #d0e3ff;
            border-radius: 6px;
            padding: 15px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            cursor: move;
            transition: all 0.2s;
        }

        .selected-node:hover {
            background-color: #e1e9ff;
        }

        .selected-node.dragging {
            opacity: 0.5;
        }

        .node-info {
            display: flex;
            align-items: center;
            gap: 12px;
        }

        .node-order {
            width: 30px;
            height: 30px;
            background-color: #1a3a8f;
            color: white;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: 600;
        }

        .remove-node {
            background: none;
            border: none;
            color: #dc2626;
            cursor: pointer;
            font-size: 16px;
            transition: color 0.2s;
        }

        .remove-node:hover {
            color: #b91c1c;
        }

        /* 空状态 */
        .empty-state {
            text-align: center;
            padding: 40px 20px;
            color: #999;
        }

        .empty-state i {
            font-size: 50px;
            margin-bottom: 20px;
            opacity: 0.5;
        }

        .empty-state h3 {
            font-size: 18px;
            margin-bottom: 10px;
            color: #666;
        }

        /* 响应式设计 */
        @media (max-width: 1200px) {
            .sidebar {
                width: 250px;
            }

            .main-content {
                margin-left: 250px;
            }
        }

        @media (max-width: 992px) {
            .sidebar {
                position: fixed;
                left: -280px;
                transition: left 0.3s ease;
            }

            .sidebar.active {
                left: 0;
            }

            .main-content {
                margin-left: 0;
            }

            .mobile-menu-toggle {
                display: flex;
            }

            .stats-container {
                grid-template-columns: repeat(2, 1fr);
            }
        }

        .mobile-menu-toggle {
            display: none;
            background: none;
            border: none;
            font-size: 20px;
            color: #1a3a8f;
            cursor: pointer;
        }

        @media (max-width: 768px) {
            .stats-container {
                grid-template-columns: 1fr;
            }

            .content-area {
                padding: 15px;
            }

            .module-card {
                padding: 20px;
            }
        }
    </style>
</head>
<body>
    <!-- 左侧导航栏 -->
    <div class="sidebar" id="sidebar">
        <div class="logo-container">
            <div class="logo">
                <i class="fas fa-cogs"></i>
            </div>
            <div class="logo-text">
                <h1>适配中心测试管理软件</h1>
                <p>V1.0</p>
            </div>
        </div>

        <div class="directory-container">
            <div class="directory-title">功能目录</div>
            <ul class="directory-tree" id="directoryTree">
                <!-- 目录树将通过JavaScript动态生成 -->
            </ul>
        </div>
    </div>

    <!-- 右侧主内容区 -->
    <div class="main-content">
        <div class="top-bar">
            <button class="mobile-menu-toggle" id="mobileMenuToggle">
                <i class="fas fa-bars"></i>
            </button>
            <div class="page-title" id="pageTitle">测试流程管理</div>
            <div class="user-info">
                <div class="user-avatar">刘</div>
                <div>
                    <div style="font-weight: 500;">刘贺</div>
                    <div style="font-size: 13px; color: #666;">项目经理</div>
                </div>
            </div>
        </div>

        <div class="content-area" id="contentArea">
            <!-- 统计卡片 -->
            <div class="stats-container">
                <div class="stat-card">
                    <div class="stat-title">流程模板总数</div>
                    <div class="stat-value" id="totalTemplates">8</div>
                </div>
                <div class="stat-card">
                    <div class="stat-title">已启用模板</div>
                    <div class="stat-value" id="enabledTemplates">3</div>
                </div>
                <div class="stat-card">
                    <div class="stat-title">草稿状态</div>
                    <div class="stat-value" id="draftTemplates">2</div>
                </div>
                <div class="stat-card">
                    <div class="stat-title">引用项目数</div>
                    <div class="stat-value" id="referencedTemplates">5</div>
                </div>
            </div>

            <!-- 测试流程管理模块 -->
            <div class="module-card" id="processManagementCard">
                <div class="module-header">
                    <div>
                        <div class="module-title">测试流程模板管理</div>
                        <div class="module-subtitle">创建和管理测试流程模板，支持拖拽式节点调整和状态管理</div>
                    </div>
                    <div class="action-buttons">
                        <button class="btn btn-primary" id="createProcessBtn">
                            <i class="fas fa-plus-circle"></i> 创建流程模板
                        </button>
                        <button class="btn btn-secondary" id="refreshProcessBtn">
                            <i class="fas fa-sync-alt"></i> 刷新
                        </button>
                    </div>
                </div>

                <!-- 流程模板列表表格 -->
                <div class="table-container">
                    <table id="processTable">
                        <thead>
                            <tr>
                                <th width="10%">模板ID</th>
                                <th width="20%">模板名称</th>
                                <th width="15%">流程类型</th>
                                <th width="20%">描述</th>
                                <th width="15%">状态</th>
                                <th width="10%">节点数</th>
                                <th width="10%">操作</th>
                            </tr>
                        </thead>
                        <tbody id="processTableBody">
                            <!-- 表格数据将通过JavaScript动态生成 -->
                        </tbody>
                    </table>
                </div>

                <!-- 分页组件 -->
                <div class="pagination-container">
                    <ul class="pagination" id="pagination">
                        <!-- 分页按钮将通过JavaScript动态生成 -->
                    </ul>
                    <div class="pagination-info" id="paginationInfo">
                        显示 1-5 条，共 8 条
                    </div>
                </div>

                <!-- 空状态 -->
                <div class="empty-state" id="emptyState" style="display: none;">
                    <i class="fas fa-sitemap"></i>
                    <h3>暂无流程模板</h3>
                    <p>点击"创建流程模板"按钮开始创建您的第一个测试流程模板</p>
                </div>
            </div>

            <!-- 注意事项卡片 -->
            <div class="module-card">
                <div class="module-header">
                    <div class="module-title">注意事项</div>
                </div>
                <div style="line-height: 1.6;">
                    <ul style="margin-top: 15px; padding-left: 20px;">
                        <li style="margin-bottom: 10px;"><strong>已启用的流程模板</strong>：可被项目直接引用，用于新项目的测试流程定义。</li>
                        <li style="margin-bottom: 10px;"><strong>删除流程前</strong>：请确认无项目正在使用该模板，否则可能导致项目流程异常。</li>
                        <li style="margin-bottom: 10px;"><strong>状态管理</strong>：支持草稿、评审中、已批准、已启用、已禁用五种流程状态。</li>
                        <li style="margin-bottom: 10px;"><strong>节点预览</strong>：实时显示选中的流程节点顺序，支持拖拽式调整（预览功能）。</li>
                        <li style="margin-bottom: 10px;"><strong>流程配置</strong>：在编辑界面设置流程名称、类型、描述、状态，勾选所需流程节点。</li>
                    </ul>
                </div>
            </div>
        </div>
    </div>

    <!-- 创建/编辑流程模板模态框 -->
    <div class="modal-overlay" id="processModal">
        <div class="modal">
            <div class="modal-header">
                <div class="modal-title" id="modalTitle">创建流程模板</div>
                <button class="modal-close" id="closeProcessModalBtn">
                    <i class="fas fa-times"></i>
                </button>
            </div>
            <div class="modal-body">
                <form id="processForm">
                    <div class="form-group">
                        <label class="form-label" for="processName">流程名称 *</label>
                        <input type="text" class="form-control" id="processName" placeholder="请输入流程名称" required>
                    </div>

                    <div class="form-group">
                        <label class="form-label" for="processType">流程类型 *</label>
                        <select class="select-control" id="processType" required>
                            <option value="">请选择流程类型</option>
                            <option value="standard">标准测试流程</option>
                            <option value="agile">敏捷测试流程</option>
                            <option value="regression">回归测试流程</option>
                            <option value="compatibility">兼容性测试流程</option>
                            <option value="performance">性能测试流程</option>
                        </select>
                    </div>

                    <div class="form-group">
                        <label class="form-label" for="processDescription">流程描述</label>
                        <textarea class="form-control" id="processDescription" rows="3" placeholder="请输入流程描述"></textarea>
                    </div>

                    <div class="form-group">
                        <label class="form-label" for="processStatus">流程状态 *</label>
                        <select class="select-control" id="processStatus" required>
                            <option value="">请选择状态</option>
                            <option value="draft">草稿</option>
                            <option value="review">评审中</option>
                            <option value="approved">已批准</option>
                            <option value="enabled">已启用</option>
                            <option value="disabled">已禁用</option>
                        </select>
                    </div>

                    <!-- 流程节点管理 -->
                    <div class="process-nodes-container">
                        <div class="nodes-section-title">
                            <i class="fas fa-sitemap"></i>
                            <span>流程节点配置</span>
                        </div>

                        <div class="available-nodes">
                            <div class="node-item" data-node="test-planning" draggable="true">
                                <i class="fas fa-clipboard-list"></i>
                                <span>测试计划制定</span>
                            </div>
                            <div class="node-item" data-node="case-design" draggable="true">
                                <i class="fas fa-edit"></i>
                                <span>测试用例设计</span>
                            </div>
                            <div class="node-item" data-node="case-review" draggable="true">
                                <i class="fas fa-clipboard-check"></i>
                                <span>用例评审</span>
                            </div>
                            <div class="node-item" data-node="test-execution" draggable="true">
                                <i class="fas fa-play-circle"></i>
                                <span>测试执行</span>
                            </div>
                            <div class="node-item" data-node="defect-management" draggable="true">
                                <i class="fas fa-bug"></i>
                                <span>缺陷管理</span>
                            </div>
                            <div class="node-item" data-node="regression-test" draggable="true">
                                <i class="fas fa-retweet"></i>
                                <span>回归测试</span>
                            </div>
                            <div class="node-item" data-node="test-report" draggable="true">
                                <i class="fas fa-file-alt"></i>
                                <span>测试报告</span>
                            </div>
                            <div class="node-item" data-node="acceptance" draggable="true">
                                <i class="fas fa-check-double"></i>
                                <span>验收测试</span>
                            </div>
                        </div>

                        <div class="nodes-section-title">
                            <i class="fas fa-list-ol"></i>
                            <span>已选节点（可拖拽调整顺序）</span>
                        </div>

                        <div class="selected-nodes-container">
                            <div class="selected-nodes" id="selectedNodes">
                                <div class="empty-state" id="emptyNodesState" style="padding: 20px;">
                                    <i class="fas fa-mouse-pointer"></i>
                                    <p>请从上方选择节点拖拽到此处</p>
                                </div>
                            </div>
                        </div>

                        <div style="font-size: 13px; color: #666; margin-top: 10px;">
                            <i class="fas fa-info-circle"></i> 提示：拖拽节点到右侧区域，在右侧区域内可以拖拽调整节点顺序
                        </div>
                    </div>
                </form>
            </div>
            <div class="modal-footer">
                <button class="btn btn-secondary" id="cancelProcessBtn">取消</button>
                <button class="btn btn-primary" id="saveProcessBtn">保存流程模板</button>
            </div>
        </div>
    </div>

    <script>
        // 目录结构数据
        const directoryData = [
            {
