        const mobileMenuToggle = document.getElementById('mobileMenuToggle');
        const sidebar = document.getElementById('sidebar');

        // 初始化目录树
        function initDirectoryTree() {
            directoryTree.innerHTML = '';

            directoryData.forEach(section => {
                const li = document.createElement('li');
                li.className = 'tree-item';

                const header = document.createElement('div');
                header.className = 'tree-header';
                header.dataset.id = section.id;

                header.innerHTML = `
                    <div class="tree-title">
                        <i class="${section.icon}"></i>
                        <span>${section.title}</span>
                    </div>
                    <div class="tree-toggle ${section.expanded ? '' : 'collapsed'}">
                        <i class="fas fa-chevron-down"></i>
                    </div>
                `;

                const content = document.createElement('ul');
                content.className = `tree-content ${section.expanded ? 'expanded' : ''}`;

                section.subItems.forEach(subItem => {
                    const subLi = document.createElement('li');
                    subLi.className = 'tree-subitem';
                    subLi.dataset.id = subItem.id;
                    subLi.dataset.parentId = section.id;

                    let iconHtml = '';
                    if (subItem.icon) {
                        iconHtml = `<i class="${subItem.icon}"></i>`;
                    }

                    subLi.innerHTML = `${iconHtml}<span>${subItem.title}</span>`;

                    // 默认选中自定义仪表盘
                    if (section.id === 'report-visualization' && subItem.id === 'custom-dashboard') {
                        subLi.classList.add('active');
                        header.classList.add('active');
                    }

                    // 添加点击事件
                    subLi.addEventListener('click', (e) => {
                        e.stopPropagation();
                        selectMenuItem(subItem.id, subItem.title);

                        // 更新活动状态
                        document.querySelectorAll('.tree-subitem').forEach(item => {
                            item.classList.remove('active');
                        });
                        document.querySelectorAll('.tree-header').forEach(item => {
                            item.classList.remove('active');
                        });

                        subLi.classList.add('active');
                        header.classList.add('active');
                    });

                    content.appendChild(subLi);
                });

                // 添加点击事件展开/折叠
                header.addEventListener('click', () => {
                    const isExpanded = content.classList.contains('expanded');
                    const toggleIcon = header.querySelector('.tree-toggle i');

                    if (isExpanded) {
                        content.classList.remove('expanded');
                        header.querySelector('.tree-toggle').classList.add('collapsed');
                    } else {
                        content.classList.add('expanded');
                        header.querySelector('.tree-toggle').classList.remove('collapsed');
                    }
                });

                li.appendChild(header);
                li.appendChild(content);
                directoryTree.appendChild(li);
            });
        }

        // 选择菜单项
        function selectMenuItem(itemId, itemTitle) {
            document.getElementById('pageTitle').textContent = itemTitle;

            // 如果是移动端，点击后关闭侧边栏
            if (window.innerWidth <= 992) {
                sidebar.classList.remove('active');
            }
        }

        // 初始化图表选择器
        function initChartSelector() {
            chartSelector.innerHTML = '';

            chartTypes.forEach(chartType => {
                const card = document.createElement('div');
                card.className = 'chart-type-card';
                card.dataset.type = chartType.id;
                card.draggable = true;
                card.innerHTML = `
                    <div class="chart-type-icon">
                        <i class="${chartType.icon}"></i>
                    </div>
                    <div class="chart-type-name">${chartType.name}</div>
                `;

                // 添加拖拽事件
                card.addEventListener('dragstart', handleDragStart);

                // 添加点击事件
                card.addEventListener('click', () => {
                    addChartToDashboard(chartType.id, chartType.name);
                });

                chartSelector.appendChild(card);
            });
        }

        // 渲染仪表盘列表
        function renderDashboardList() {
            dashboardList.innerHTML = '';

            if (dashboards.length === 0) {
                emptyDashboardState.style.display = 'block';
                return;
            }

            emptyDashboardState.style.display = 'none';

            dashboards.forEach(dashboard => {
                const card = document.createElement('div');
                card.className = 'dashboard-card';
                card.dataset.id = dashboard.id;

                card.innerHTML = `
                    <div class="dashboard-card-header">
                        <div>
                            <div class="dashboard-name">${dashboard.name}</div>
                            ${dashboard.isDefault ? '<div style="font-size: 12px; color: #666; margin-top: 3px;">默认仪表盘</div>' : ''}
                        </div>
                        <div class="dashboard-status ${dashboard.visibility === 'private' ? 'status-private' : 'status-public'}">
                            ${dashboard.visibility === 'private' ? '私有' : '公开'}
                        </div>
                    </div>
                    <div class="dashboard-description">${dashboard.description}</div>
                    <div class="dashboard-meta">
                        <div>${dashboard.charts}个图表</div>
                        <div>更新于：${dashboard.lastUpdated}</div>
                    </div>
                    <div class="dashboard-actions">
                        <button class="dashboard-action-btn edit-btn" data-action="edit">
                            <i class="fas fa-edit"></i> 编辑
                        </button>
                        <button class="dashboard-action-btn share-btn" data-action="share">
                            <i class="fas fa-share-alt"></i> 分享
                        </button>
                        ${dashboard.id !== 1 ? '<button class="dashboard-action-btn delete-btn" data-action="delete"><i class="fas fa-trash"></i> 删除</button>' : ''}
                    </div>
                `;

                // 添加点击事件
                card.querySelector('.edit-btn').addEventListener('click', () => {
                    editDashboard(dashboard.id);
                });

                if (dashboard.id !== 1) {
                    card.querySelector('.delete-btn').addEventListener('click', () => {
                        deleteDashboard(dashboard.id);
                    });
                }

                card.querySelector('.share-btn').addEventListener('click', () => {
                    shareDashboard(dashboard.id);
                });

                dashboardList.appendChild(card);
            });
        }

        // 编辑仪表盘
        function editDashboard(dashboardId) {
            const dashboard = dashboards.find(d => d.id === dashboardId);
            if (!dashboard) return;

            currentDashboard = dashboard;
            currentCharts = generateChartsForDashboard(dashboardId);

            // 显示编辑界面
            dashboardEditorCard.style.display = 'block';
            document.getElementById('currentDashboardTitle').textContent = `编辑仪表盘: ${dashboard.name}`;
            document.getElementById('currentDashboardDesc').textContent = dashboard.description;

            // 渲染图表
            renderCharts();

            // 滚动到编辑区域
            dashboardEditorCard.scrollIntoView({ behavior: 'smooth' });
        }

        // 生成图表数据
        function generateChartsForDashboard(dashboardId) {
            if (dashboardId === 1) {
                return [
                    { id: 1, type: 'burndown', name: '项目燃尽图', dataSource: 'api', refreshInterval: 60 },
                    { id: 2, type: 'bar', name: '缺陷分布柱状图', dataSource: 'sql', refreshInterval: 300 },
                    { id: 3, type: 'pie', name: '测试用例状态分布', dataSource: 'static', refreshInterval: 600 },
                    { id: 4, type: 'line', name: '缺陷趋势图', dataSource: 'api', refreshInterval: 60 },
                    { id: 5, type: 'radar', name: '团队成员技能雷达图', dataSource: 'static', refreshInterval: 0 }
                ];
            } else if (dashboardId === 2) {
                return [
                    { id: 6, type: 'bar', name: '缺陷严重程度分布', dataSource: 'sql', refreshInterval: 300 },
                    { id: 7, type: 'line', name: '缺陷修复趋势', dataSource: 'api', refreshInterval: 60 },
                    { id: 8, type: 'pie', name: '缺陷模块分布', dataSource: 'static', refreshInterval: 600 },
                    { id: 9, type: 'gauge', name: '缺陷解决率', dataSource: 'api', refreshInterval: 30 }
                ];
            } else {
                return [
                    { id: 10, type: 'line', name: '测试覆盖率趋势', dataSource: 'api', refreshInterval: 300 },
                    { id: 11, type: 'bar', name: '各模块测试覆盖率', dataSource: 'sql', refreshInterval: 600 },
                    { id: 12, type: 'gauge', name: '总体测试覆盖率', dataSource: 'api', refreshInterval: 60 }
                ];
            }
