        // 渲染图表
        function renderCharts() {
            chartsContainer.innerHTML = '';

            if (currentCharts.length === 0) {
                dropzone.style.display = 'block';
                return;
            }

            dropzone.style.display = 'none';

            currentCharts.forEach(chart => {
                const chartCard = document.createElement('div');
                chartCard.className = 'chart-card';
                chartCard.dataset.id = chart.id;
                chartCard.draggable = true;

                chartCard.innerHTML = `
                    <div class="chart-header">
                        <div class="chart-title">${chart.name}</div>
                        <div class="chart-actions">
                            <button class="chart-action-btn config-btn" title="配置">
                                <i class="fas fa-cog"></i>
                            </button>
                            <button class="chart-action-btn remove-btn" title="删除">
                                <i class="fas fa-times"></i>
                            </button>
                        </div>
                    </div>
                    <div class="chart-canvas-container">
                        <canvas id="chart-${chart.id}"></canvas>
                    </div>
                `;

                // 添加拖拽事件
                chartCard.addEventListener('dragstart', handleDragStart);
                chartCard.addEventListener('dragover', handleDragOver);
                chartCard.addEventListener('drop', handleDrop);
                chartCard.addEventListener('dragend', handleDragEnd);

                // 添加配置按钮事件
                chartCard.querySelector('.config-btn').addEventListener('click', () => {
                    configureChart(chart.id);
                });

                // 添加删除按钮事件
                chartCard.querySelector('.remove-btn').addEventListener('click', () => {
                    removeChart(chart.id);
                });

                chartsContainer.appendChild(chartCard);

                // 渲染图表
                renderChartCanvas(chart.id, chart.type);
            });
        }

