            e.dataTransfer.setData('text/html', this.innerHTML);
        }

        function handleDragOver(e) {
            e.preventDefault();
            e.dataTransfer.dropEffect = 'move';
        }

        function handleDrop(e) {
            e.preventDefault();
            if (draggedChart !== this) {
                // 获取拖拽元素和目标元素
                const charts = Array.from(chartsContainer.children);
                const draggedIndex = charts.indexOf(draggedChart);
                const targetIndex = charts.indexOf(this);

                if (draggedIndex < targetIndex) {
                    chartsContainer.insertBefore(draggedChart, this.nextSibling);
                } else {
                    chartsContainer.insertBefore(draggedChart, this);
                }
            }
