                    visibility,
                    charts: 0,
                    lastUpdated: new Date().toISOString().split('T')[0],
                    owner: '刘贺',
                    isDefault: false
                };

                dashboards.push(newDashboard);
                renderDashboardList();
                createDashboardModal.classList.remove('active');

                // 清空表单
                document.getElementById('dashboardName').value = '';
