                chartConfigModal.classList.remove('active');
            });

            document.getElementById('cancelChartConfigBtn').addEventListener('click', () => {
                chartConfigModal.classList.remove('active');
            });

            document.getElementById('saveChartConfigBtn').addEventListener('click', () => {
                if (!chartBeingConfigured) return;

                const name = document.getElementById('chartConfigName').value;
                const dataSource = document.getElementById('chartDataSource').value;
                const refreshInterval = document.getElementById('chartRefreshInterval').value;

                if (!name) {
                    showNotification('请输入图表名称', 'error');
                    return;
                }

                // 更新图表配置
                chartBeingConfigured.name = name;
                chartBeingConfigured.dataSource = dataSource;
                chartBeingConfigured.refreshInterval = parseInt(refreshInterval);

                // 重新渲染图表
                renderCharts();
                chartConfigModal.classList.remove('active');
                showNotification('图表配置已保存', 'success');
            });

            // 数据源类型变化事件
            document.getElementById('chartDataSource').addEventListener('change', (e) => {
                toggleDataSourceFields(e.target.value);
            });

            // 移动端菜单切换
