            color: #1a3a8f;
        }

        .edit-icon:hover {
            background-color: #d0e3ff;
        }

        .delete-icon {
            background-color: #fee;
            color: #dc2626;
        }

        .delete-icon:hover {
            background-color: #fdd;
        }

        .view-icon {
            background-color: #f0f5ff;
            color: #4f46e5;
        }

        .view-icon:hover {
            background-color: #e1e9ff;
        }

        /* 分页样式 */
        .pagination-container {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-top: 30px;
            padding-top: 20px;
            border-top: 1px solid #eee;
        }

        .pagination {
            display: flex;
            list-style: none;
            gap: 5px;
        }

        .page-item {
            display: flex;
            align-items: center;
            justify-content: center;
