            color: #555;
            text-decoration: none;
            cursor: pointer;
            transition: all 0.2s ease;
        }

        .page-link:hover {
            background-color: #f0f5ff;
            border-color: #1a3a8f;
            color: #1a3a8f;
        }

        .page-link.active {
            background-color: #1a3a8f;
            border-color: #1a3a8f;
            color: white;
        }

        .page-link.disabled {
            background-color: #f5f5f5;
            color: #999;
            cursor: not-allowed;
        }

        .pagination-info {
            color: #666;
            font-size: 14px;
        }

        /* 筛选器样式 */
        .filter-container {
            background-color: #f8fafd;
            border-radius: 8px;
            padding: 20px;
            margin-bottom: 20px;
            display: flex;
            flex-wrap: wrap;
            gap: 15px;
            align-items: flex-end;
        }

        .filter-group {
            flex: 1;
            min-width: 180px;
        }

        .filter-label {
            display: block;
            margin-bottom: 8px;
            font-size: 14px;
            font-weight: 500;
            color: #555;
        }

        .select-control {
            width: 100%;
            padding: 12px 15px;
            border: 1px solid #ddd;
            border-radius: 6px;
            font-size: 15px;
            background-color: white;
            transition: border 0.2s;
        }

        .select-control:focus {
            outline: none;
            border-color: #1a3a8f;
            box-shadow: 0 0 0 3px rgba(26, 58, 143, 0.1);
        }

        .search-input {
            width: 100%;
            padding: 12px 15px;
            border: 1px solid #ddd;
            border-radius: 6px;
            font-size: 15px;
            transition: border 0.2s;
        }

        .search-input:focus {
            outline: none;
            border-color: #1a3a8f;
            box-shadow: 0 0 0 3px rgba(26, 58, 143, 0.1);
        }

        .filter-actions {
            display: flex;
            gap: 10px;
        }

        /* 统计卡片 */
        .stats-container {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
            gap: 20px;
            margin-bottom: 30px;
        }

        .stat-card {
            background-color: white;
            border-radius: 10px;
            padding: 20px;
            box-shadow: 0 3px 10px rgba(0, 0, 0, 0.05);
            border-left: 4px solid #1a3a8f;
        }

        .stat-title {
            font-size: 14px;
            color: #666;
            margin-bottom: 10px;
        }

        .stat-value {
            font-size: 28px;
            font-weight: 600;
            color: #1a3a8f;
        }

        .stat-trend {
            font-size: 12px;
            margin-top: 5px;
        }

        .trend-up {
            color: #059669;
        }

        .trend-down {
            color: #dc2626;
        }

        /* 空状态 */
        .empty-state {
            text-align: center;
            padding: 60px 20px;
            color: #999;
        }

        .empty-state i {
            font-size: 50px;
            margin-bottom: 20px;
            opacity: 0.5;
        }

        .empty-state h3 {
            font-size: 18px;
            margin-bottom: 10px;
            color: #666;
        }

        /* 模态框样式 */
        .modal-overlay {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background-color: rgba(0, 0, 0, 0.5);
            display: flex;
            align-items: center;
            justify-content: center;
            z-index: 100;
            opacity: 0;
            visibility: hidden;
            transition: all 0.3s ease;
        }

        .modal-overlay.active {
            opacity: 1;
            visibility: visible;
        }

        .modal {
            background-color: white;
            border-radius: 12px;
            width: 800px;
            max-width: 90%;
            max-height: 90vh;
            overflow-y: auto;
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
            transform: translateY(20px);
            transition: transform 0.3s ease;
        }

        .modal-overlay.active .modal {
            transform: translateY(0);
        }

        .modal-header {
            padding: 25px 30px;
            border-bottom: 1px solid #eee;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .modal-title {
            font-size: 20px;
            font-weight: 600;
            color: #1a3a8f;
        }

        .modal-close {
            background: none;
            border: none;
            font-size: 20px;
            cursor: pointer;
            color: #999;
            transition: color 0.2s;
        }

        .modal-close:hover {
            color: #333;
        }

        .modal-body {
            padding: 30px;
        }

        .form-group {
            margin-bottom: 20px;
        }

        .form-label {
            display: block;
            margin-bottom: 8px;
            font-weight: 500;
            color: #555;
        }

        .form-control {
            width: 100%;
            padding: 12px 15px;
            border: 1px solid #ddd;
            border-radius: 6px;
            font-size: 15px;
            transition: border 0.2s;
        }

        .form-control:focus {
            outline: none;
            border-color: #1a3a8f;
            box-shadow: 0 0 0 3px rgba(26, 58, 143, 0.1);
        }

        .modal-footer {
            padding: 20px 30px;
            border-top: 1px solid #eee;
            display: flex;
            justify-content: flex-end;
            gap: 15px;
        }

        /* 响应式设计 */
        @media (max-width: 1200px) {
            .sidebar {
                width: 250px;
            }
        }

        @media (max-width: 992px) {
            .sidebar {
                position: fixed;
                left: -280px;
                transition: left 0.3s ease;
            }

            .sidebar.active {
                left: 0;
            }

            .mobile-menu-toggle {
                display: flex;
            }

            .stats-container {
                grid-template-columns: repeat(2, 1fr);
            }
        }

        .mobile-menu-toggle {
            display: none;
            background: none;
            border: none;
            font-size: 20px;
            color: #1a3a8f;
            cursor: pointer;
        }

        @media (max-width: 768px) {
            .stats-container {
                grid-template-columns: 1fr;
            }

            .content-area {
                padding: 15px;
            }

            .module-card {
                padding: 20px;
            }

            .filter-group {
                min-width: 100%;
            }
        }

        /* 数据导出样式 */
        .export-buttons {
            display: flex;
            gap: 10px;
            flex-wrap: wrap;
        }

        /* 表格行详情 */
        .row-details {
            display: none;
            background-color: #f8fafd;
            padding: 20px;
            border-top: 1px solid #eaeff5;
        }

        .row-details.active {
            display: block;
        }

        .details-title {
            font-weight: 600;
            color: #1a3a8f;
            margin-bottom: 15px;
            font-size: 16px;
        }

        .details-grid {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
            gap: 15px;
        }

        .details-item {
            margin-bottom: 10px;
        }

        .details-label {
            font-weight: 500;
            color: #666;
            margin-bottom: 5px;
            font-size: 14px;
        }

        .details-value {
            color: #333;
            font-size: 15px;
        }
    </style>
</head>
<body>
    <!-- 左侧导航栏 -->
    <div class="sidebar" id="sidebar">
        <div class="logo-container">
            <div class="logo">
                <i class="fas fa-cogs"></i>
            </div>
            <div class="logo-text">
                <h1>适配中心测试管理软件</h1>
                <p>V1.0</p>
            </div>
        </div>

        <div class="directory-container">
            <div class="directory-title">功能目录</div>
            <ul class="directory-tree" id="directoryTree">
                <!-- 目录树将通过JavaScript动态生成 -->
            </ul>
        </div>
    </div>

    <!-- 右侧主内容区 -->
    <div class="main-content">
        <div class="top-bar">
            <button class="mobile-menu-toggle" id="mobileMenuToggle">
                <i class="fas fa-bars"></i>
            </button>
            <div class="page-title" id="pageTitle">测试项目管理</div>
            <div class="user-info">
                <div class="user-avatar">刘</div>
                <div>
                    <div style="font-weight: 500;">刘贺</div>
                    <div style="font-size: 13px; color: #666;">项目经理</div>
                </div>
            </div>
        </div>

        <div class="content-area" id="contentArea">
            <!-- 统计卡片 -->
            <div class="stats-container">
                <div class="stat-card">
                    <div class="stat-title">总项目数</div>
                    <div class="stat-value" id="totalProjects">28</div>
                    <div class="stat-trend trend-up">较上月 ↑ 15%</div>
                </div>
                <div class="stat-card">
                    <div class="stat-title">进行中项目</div>
                    <div class="stat-value" id="activeProjects">12</div>
                    <div class="stat-trend trend-down">较上月 ↓ 3%</div>
                </div>
                <div class="stat-card">
                    <div class="stat-title">已延期项目</div>
                    <div class="stat-value" id="delayedProjects">3</div>
                    <div class="stat-trend trend-up">较上月 ↑ 1</div>
                </div>
                <div class="stat-card">
                    <div class="stat-title">平均完成率</div>
                    <div class="stat-value" id="avgCompletion">78%</div>
                    <div class="stat-trend trend-up">较上月 ↑ 5%</div>
                </div>
            </div>

            <!-- 项目管理模块 -->
            <div class="module-card">
                <div class="module-header">
                    <div>
                        <div class="module-title">测试项目管理</div>
                        <div class="module-subtitle">管理所有测试项目，包括项目创建、状态跟踪、资源配置和进度监控</div>
                    </div>
                    <div class="action-buttons">
                        <button class="btn btn-primary" id="addProjectBtn">
                            <i class="fas fa-plus"></i> 添加项目
                        </button>
                        <button class="btn btn-secondary" id="exportDataBtn">
                            <i class="fas fa-file-export"></i> 导出数据
                        </button>
                    </div>
                </div>

                <!-- 筛选器 -->
                <div class="filter-container">
                    <div class="filter-group">
                        <label class="filter-label">项目状态</label>
                        <select class="select-control" id="statusFilter">
                            <option value="">全部状态</option>
                            <option value="planning">规划中</option>
                            <option value="active">进行中</option>
                            <option value="testing">测试中</option>
                            <option value="completed">已完成</option>
                            <option value="delayed">已延期</option>
                        </select>
                    </div>
                    <div class="filter-group">
                        <label class="filter-label">优先级</label>
                        <select class="select-control" id="priorityFilter">
                            <option value="">全部优先级</option>
                            <option value="high">高</option>
                            <option value="medium">中</option>
                            <option value="low">低</option>
                        </select>
                    </div>
                    <div class="filter-group">
                        <label class="filter-label">负责人</label>
                        <select class="select-control" id="ownerFilter">
                            <option value="">全部负责人</option>
                            <option value="liuhe">刘贺</option>
                            <option value="zhangming">张明</option>
                            <option value="lihua">李华</option>
                            <option value="wangwei">王伟</option>
                        </select>
                    </div>
                    <div class="filter-group">
                        <label class="filter-label">搜索</label>
                        <input type="text" class="search-input" id="searchInput" placeholder="输入项目名称或编号...">
                    </div>
                    <div class="filter-actions">
                        <button class="btn btn-secondary" id="applyFiltersBtn">
                            <i class="fas fa-filter"></i> 筛选
                        </button>
                        <button class="btn btn-secondary" id="resetFiltersBtn">
                            <i class="fas fa-redo"></i> 重置
                        </button>
                    </div>
                </div>

                <!-- 项目数据表格 -->
                <div class="table-container">
                    <table id="projectsTable">
                        <thead>
                            <tr>
                                <th width="8%">项目ID</th>
                                <th width="22%">项目名称</th>
                                <th width="12%">状态</th>
                                <th width="10%">优先级</th>
                                <th width="12%">负责人</th>
                                <th width="12%">开始日期</th>
                                <th width="12%">截止日期</th>
                                <th width="12%">完成率</th>
                                <th width="12%">操作</th>
                            </tr>
                        </thead>
                        <tbody id="projectsTableBody">
                            <!-- 表格数据将通过JavaScript动态生成 -->
                        </tbody>
                    </table>
                </div>

                <!-- 分页组件 -->
                <div class="pagination-container">
                    <div class="pagination-info" id="paginationInfo">
                        显示 1-10 条，共 28 条
                    </div>
                    <ul class="pagination" id="pagination">
                        <!-- 分页按钮将通过JavaScript动态生成 -->
                    </ul>
                </div>

                <!-- 空状态 -->
                <div class="empty-state" id="emptyState" style="display: none;">
