            { id: 8, code: "PROJ-2025-008", name: "智慧城市应用适配测试", status: "testing", priority: "high", owner: "李华", startDate: "2025-09-25", endDate: "2025-11-30", completion: 91, testCases: 289, passed: 256, failed: 22, defects: 15, quality: 88 },
