        // 初始化目录树交互
        function initDirectoryTree() {
            // 展开/折叠功能
            document.querySelectorAll('.tree-header').forEach(header => {
                header.addEventListener('click', () => {
                    const content = header.nextElementSibling;
                    const isExpanded = content.classList.contains('expanded');
                    const toggleIcon = header.querySelector('.tree-toggle i');

                    if (isExpanded) {
                        content.classList.remove('expanded');
                        header.querySelector('.tree-toggle').classList.add('collapsed');
                    } else {
                        content.classList.add('expanded');
                        header.querySelector('.tree-toggle').classList.remove('collapsed');
                    }
                });
            });

            // 子项点击功能
            document.querySelectorAll('.tree-subitem').forEach(item => {
                item.addEventListener('click', (e) => {
                    e.stopPropagation();

                    // 移除所有激活状态
                    document.querySelectorAll('.tree-subitem').forEach(i => {
                        i.classList.remove('active');
                    });
                    document.querySelectorAll('.tree-header').forEach(i => {
                        i.classList.remove('active');
                    });

                    // 设置当前激活状态
                    item.classList.add('active');
                    item.closest('.tree-item').querySelector('.tree-header').classList.add('active');

                    // 更新页面标题
                    const title = item.dataset.title;
                    pageTitle.textContent = title;

                    // 如果是移动端，点击后关闭侧边栏
                    if (window.innerWidth <= 992) {
                        sidebar.classList.remove('active');
                    }
                });
            });
        }

        // 生成项目编号
        function generateProjectCode() {
            const now = new Date();
            const year = now.getFullYear();
            const month = String(now.getMonth() + 1).padStart(2, '0');
            const day = String(now.getDate()).padStart(2, '0');
            const random = Math.floor(Math.random() * 1000).toString().padStart(3, '0');
            return `PROJ-${year}${month}${day}-${random}`;
        }

        // 应用筛选
        function applyFilters() {
            const statusFilter = document.getElementById('statusFilter').value;
            const priorityFilter = document.getElementById('priorityFilter').value;
            const typeFilter = document.getElementById('typeFilter').value;
            const leaderFilter = document.getElementById('leaderFilter').value;

            filteredProjects = projectsData.filter(project => {
                return (!statusFilter || project.projectStatus.toString() === statusFilter) &&
                       (!priorityFilter || project.priority.toString() === priorityFilter) &&
                       (!typeFilter || project.projectType.toString() === typeFilter) &&
                       (!leaderFilter || project.projectLeader === leaderFilter);
            });

            currentPage = 1;
            renderProjectsTable();
            renderPagination();
            updateStats();
        }

        // 重置筛选
        function resetFilters() {
            document.getElementById('statusFilter').value = '';
            document.getElementById('priorityFilter').value = '';
            document.getElementById('typeFilter').value = '';
            document.getElementById('leaderFilter').value = '';

            filteredProjects = [...projectsData];
            currentPage = 1;
            renderProjectsTable();
            renderPagination();
            updateStats();
        }

        // 渲染项目表格
        function renderProjectsTable() {
            const tableBody = document.getElementById('projectsTableBody');

            if (filteredProjects.length === 0) {
                tableBody.innerHTML = '';
                emptyState.style.display = 'block';
                return;
            }

            emptyState.style.display = 'none';

            // 计算当前页的数据
            const startIndex = (currentPage - 1) * itemsPerPage;
            const endIndex = Math.min(startIndex + itemsPerPage, filteredProjects.length);
            const currentProjects = filteredProjects.slice(startIndex, endIndex);

            tableBody.innerHTML = '';

            currentProjects.forEach(project => {
                // 确定状态徽章
                let statusBadgeClass = '';
                let statusText = '';
                switch(project.projectStatus) {
                    case 0:
                        statusBadgeClass = 'status-not-started';
                        statusText = '未开始';
                        break;
                    case 1:
                        statusBadgeClass = 'status-in-progress';
                        statusText = '进行中';
                        break;
                    case 2:
                        statusBadgeClass = 'status-paused';
                        statusText = '已暂停';
                        break;
                    case 3:
                        statusBadgeClass = 'status-completed';
                        statusText = '已完成';
                        break;
                    case 4:
                        statusBadgeClass = 'status-closed';
                        statusText = '已关闭';
                        break;
                }

                // 确定优先级徽章
                let priorityBadgeClass = '';
                let priorityText = '';
                switch(project.priority) {
                    case 1:
                        priorityBadgeClass = 'priority-low';
                        priorityText = '低';
                        break;
                    case 2:
                        priorityBadgeClass = 'priority-medium';
                        priorityText = '中';
                        break;
                    case 3:
                        priorityBadgeClass = 'priority-high';
                        priorityText = '高';
                        break;
                    case 4:
                        priorityBadgeClass = 'priority-urgent';
                        priorityText = '紧急';
                        break;
                }

                // 确定类型徽章
                let typeBadgeClass = '';
                let typeText = '';
                switch(project.projectType) {
                    case 0:
                        typeBadgeClass = 'type-standard';
                        typeText = '标准适配';
                        break;
                    case 1:
                        typeBadgeClass = 'type-emergency';
                        typeText = '紧急适配';
                        break;
                    case 2:
                        typeBadgeClass = 'type-special';
                        typeText = '专项测试';
                        break;
                    case 3:
                        typeBadgeClass = 'type-custom';
                        typeText = '定制化';
                        break;
                }

                const row = document.createElement('tr');
                row.innerHTML = `
                    <td>${project.projectCode}</td>
                    <td>${project.projectName}</td>
                    <td><span class="status-badge ${statusBadgeClass}">${statusText}</span></td>
                    <td><span class="type-badge ${typeBadgeClass}">${typeText}</span></td>
                    <td><span class="priority-badge ${priorityBadgeClass}">${priorityText}</span></td>
                    <td>${project.projectLeader}</td>
                    <td>${project.planStartTime}</td>
                    <td>${project.planEndTime}</td>
                    <td class="action-cell">
                        <div class="action-icon view-icon" data-id="${project.id}" title="查看详情">
                            <i class="fas fa-eye"></i>
                        </div>
                        <div class="action-icon edit-icon" data-id="${project.id}" title="编辑项目">
                            <i class="fas fa-edit"></i>
                        </div>
                        <div class="action-icon delete-icon" data-id="${project.id}" title="删除项目">
                            <i class="fas fa-trash"></i>
                        </div>
                    </td>
                `;

                tableBody.appendChild(row);
            });

            // 绑定操作按钮事件
            bindTableActions();
        }

        // 绑定表格操作按钮事件
        function bindTableActions() {
            // 查看详情
            document.querySelectorAll('.view-icon').forEach(icon => {
                icon.addEventListener('click', (e) => {
                    const projectId = parseInt(icon.dataset.id);
                    showProjectDetail(projectId);
                });
            });

            // 编辑项目
            document.querySelectorAll('.edit-icon').forEach(icon => {
                icon.addEventListener('click', (e) => {
                    const projectId = parseInt(icon.dataset.id);
                    editProject(projectId);
                });
            });

            // 删除项目
            document.querySelectorAll('.delete-icon').forEach(icon => {
                icon.addEventListener('click', (e) => {
                    const projectId = parseInt(icon.dataset.id);
                    confirmDeleteProject(projectId);
                });
            });
        }

        // 渲染分页
        function renderPagination() {
            const totalPages = Math.ceil(filteredProjects.length / itemsPerPage);
            const pagination = document.getElementById('pagination');
            const paginationInfo = document.getElementById('paginationInfo');

            // 更新分页信息
            const startItem = (currentPage - 1) * itemsPerPage + 1;
            const endItem = Math.min(currentPage * itemsPerPage, filteredProjects.length);
            paginationInfo.textContent = `显示 ${startItem}-${endItem} 条，共 ${filteredProjects.length} 条`;

            // 生成分页按钮
            pagination.innerHTML = '';

            // 上一页按钮
            const prevLi = document.createElement('li');
            prevLi.className = 'page-item';
            prevLi.innerHTML = `<a class="page-link ${currentPage === 1 ? 'disabled' : ''}" href="#" data-page="${currentPage - 1}"><i class="fas fa-chevron-left"></i></a>`;
            pagination.appendChild(prevLi);

            // 页码按钮
            const maxVisiblePages = 5;
            let startPage = Math.max(1, currentPage - Math.floor(maxVisiblePages / 2));
            let endPage = Math.min(totalPages, startPage + maxVisiblePages - 1);

            // 调整起始页，确保显示maxVisiblePages个页码
            if (endPage - startPage + 1 < maxVisiblePages) {
                startPage = Math.max(1, endPage - maxVisiblePages + 1);
            }

            for (let i = startPage; i <= endPage; i++) {
                const pageLi = document.createElement('li');
                pageLi.className = 'page-item';
                pageLi.innerHTML = `<a class="page-link ${i === currentPage ? 'active' : ''}" href="#" data-page="${i}">${i}</a>`;
                pagination.appendChild(pageLi);
            }

            // 下一页按钮
            const nextLi = document.createElement('li');
            nextLi.className = 'page-item';
            nextLi.innerHTML = `<a class="page-link ${currentPage === totalPages ? 'disabled' : ''}" href="#" data-page="${currentPage + 1}"><i class="fas fa-chevron-right"></i></a>`;
            pagination.appendChild(nextLi);

            // 绑定分页点击事件
            document.querySelectorAll('.page-link').forEach(link => {
                link.addEventListener('click', (e) => {
                    e.preventDefault();

                    if (link.classList.contains('disabled')) return;

                    const page = parseInt(link.dataset.page);
                    if (!isNaN(page)) {
                        currentPage = page;
                        renderProjectsTable();
                        renderPagination();
                    }
                });
            });
        }

        // 更新统计数据
        function updateStats() {
            const totalProjects = filteredProjects.length;
            const activeProjects = filteredProjects.filter(p => p.projectStatus === 1).length;
            const highPriorityProjects = filteredProjects.filter(p => p.priority >= 3).length;
            const delayedProjects = filteredProjects.filter(p => {
                if (p.projectStatus !== 3 && p.projectStatus !== 4 && p.planEndTime) {
                    const endDate = new Date(p.planEndTime);
                    const today = new Date();
                    return endDate < today;
                }
                return false;
            }).length;

            document.getElementById('totalProjects').textContent = totalProjects;
            document.getElementById('activeProjects').textContent = activeProjects;
            document.getElementById('highPriorityProjects').textContent = highPriorityProjects;
            document.getElementById('delayedProjects').textContent = delayedProjects;
        }

