        // 打开创建项目模态框
        function openCreateProjectModal() {
            modalTitle.textContent = '创建项目';
            projectForm.reset();

            // 生成项目编号
            document.getElementById('projectCode').value = generateProjectCode();
            document.getElementById('projectCode').readOnly = false;

            // 设置默认值
            document.getElementById('projectStatus').value = '0';
            document.getElementById('priority').value = '2';
            document.getElementById('projectType').value = '0';

            // 设置当前日期为默认开始时间
            const today = new Date();
            const todayStr = today.toISOString().split('T')[0];
            document.getElementById('planStartTime').value = todayStr;

            // 设置默认结束时间（30天后）
            const endDate = new Date(today);
            endDate.setDate(endDate.getDate() + 30);
            const endDateStr = endDate.toISOString().split('T')[0];
            document.getElementById('planEndTime').value = endDateStr;

            // 清空隐藏的projectId
            document.getElementById('projectId').value = '';
            currentEditingProjectId = null;

            projectModal.classList.add('active');
        }

        // 编辑项目
        function editProject(projectId) {
            const project = projectsData.find(p => p.id === projectId);
            if (!project) return;

            modalTitle.textContent = '编辑项目';

            // 填充表单数据
            document.getElementById('projectId').value = project.id;
            document.getElementById('projectCode').value = project.projectCode;
            document.getElementById('projectCode').readOnly = true; // 项目编号不可编辑
            document.getElementById('projectName').value = project.projectName;
            document.getElementById('projectDesc').value = project.projectDesc || '';
            document.getElementById('projectLeader').value = project.projectLeader;
            document.getElementById('projectType').value = project.projectType.toString();
            document.getElementById('priority').value = project.priority.toString();
            document.getElementById('projectStatus').value = project.projectStatus.toString();
            document.getElementById('planStartTime').value = project.planStartTime;
            document.getElementById('planEndTime').value = project.planEndTime;
            document.getElementById('testEnvInfo').value = project.testEnvInfo || '';
            document.getElementById('remark').value = project.remark || '';

            currentEditingProjectId = projectId;

            projectModal.classList.add('active');
        }

        // 保存项目
        function saveProject() {
            // 表单验证
            if (!validateProjectForm()) {
                showNotification('请填写所有必填字段', 'error');
                return;
            }

            // 验证结束日期是否早于开始日期
            const startTime = new Date(document.getElementById('planStartTime').value);
            const endTime = new Date(document.getElementById('planEndTime').value);

            if (endTime < startTime) {
                showNotification('计划结束日期不能早于开始日期', 'error');
                return;
            }

            const projectId = document.getElementById('projectId').value;

            if (projectId) {
                // 更新现有项目
                updateExistingProject(projectId);
            } else {
                // 创建新项目
                createNewProject();
            }
        }

        // 验证项目表单
        function validateProjectForm() {
            const requiredFields = ['projectCode', 'projectName', 'projectLeader', 'projectType', 'priority', 'projectStatus', 'planStartTime', 'planEndTime'];

            for (const fieldId of requiredFields) {
                const field = document.getElementById(fieldId);
                if (!field.value.trim()) {
                    return false;
                }
            }

            return true;
        }

        // 创建新项目
        function createNewProject() {
            const now = new Date();
            const nowStr = now.toISOString().split('T')[0];

            const newProject = {
                id: projectsData.length > 0 ? Math.max(...projectsData.map(p => p.id)) + 1 : 1,
                projectCode: document.getElementById('projectCode').value,
                projectName: document.getElementById('projectName').value,
                projectDesc: document.getElementById('projectDesc').value,
                projectLeader: document.getElementById('projectLeader').value,
                projectLeaderId: getLeaderId(document.getElementById('projectLeader').value),
                projectType: parseInt(document.getElementById('projectType').value),
                priority: parseInt(document.getElementById('priority').value),
                projectStatus: parseInt(document.getElementById('projectStatus').value),
                planStartTime: document.getElementById('planStartTime').value,
                planEndTime: document.getElementById('planEndTime').value,
                actualStartTime: parseInt(document.getElementById('projectStatus').value) > 0 ? document.getElementById('planStartTime').value : '',
                actualEndTime: '',
                testEnvInfo: document.getElementById('testEnvInfo').value,
                remark: document.getElementById('remark').value,
                progress: 0,
                testCaseCount: 0,
                taskCount: 0,
                memberCount: 0,
                defectCount: 0,
                createTime: nowStr,
                updateTime: nowStr
            };

            projectsData.unshift(newProject);

            // 重置筛选，显示所有项目
            resetFilters();

            // 关闭模态框
            projectModal.classList.remove('active');

            showNotification('项目创建成功', 'success');
        }

        // 更新现有项目
        function updateExistingProject(projectId) {
            const projectIndex = projectsData.findIndex(p => p.id.toString() === projectId);
            if (projectIndex === -1) return;

            const now = new Date();
            const nowStr = now.toISOString().split('T')[0];

            // 更新项目数据
            projectsData[projectIndex] = {
                ...projectsData[projectIndex],
                projectName: document.getElementById('projectName').value,
                projectDesc: document.getElementById('projectDesc').value,
                projectLeader: document.getElementById('projectLeader').value,
                projectLeaderId: getLeaderId(document.getElementById('projectLeader').value),
                projectType: parseInt(document.getElementById('projectType').value),
                priority: parseInt(document.getElementById('priority').value),
                projectStatus: parseInt(document.getElementById('projectStatus').value),
                planStartTime: document.getElementById('planStartTime').value,
                planEndTime: document.getElementById('planEndTime').value,
                testEnvInfo: document.getElementById('testEnvInfo').value,
                remark: document.getElementById('remark').value,
                updateTime: nowStr
            };

            // 更新项目列表
            applyFilters();

            // 关闭模态框
            projectModal.classList.remove('active');

            showNotification('项目更新成功', 'success');
        }

        // 根据负责人姓名获取ID
        function getLeaderId(leaderName) {
            const leaders = {
                '刘贺': 1,
                '张明': 2,
                '李华': 3,
                '王伟': 4,
                '赵静': 5
            };
            return leaders[leaderName] || 1;
        }

        // 确认删除项目
        function confirmDeleteProject(projectId) {
            const project = projectsData.find(p => p.id === projectId);
            if (!project) return;

            // 检查项目是否有关联数据
            let warningMessage = '';
            if (project.testCaseCount > 0 || project.taskCount > 0 || project.defectCount > 0) {
                warningMessage = `项目 "${project.projectName}" 有关联数据（测试用例: ${project.testCaseCount}, 任务: ${project.taskCount}, 缺陷: ${project.defectCount}），删除前请确认。`;
            } else {
                warningMessage = `确认要删除项目 "${project.projectName}" 吗？此操作不可撤销。`;
            }

            document.getElementById('deleteConfirmMessage').textContent = warningMessage;
            projectToDelete = projectId;
            deleteConfirmModal.classList.add('active');
        }

        // 删除项目
        function deleteProject() {
            if (!projectToDelete) return;

            const projectIndex = projectsData.findIndex(p => p.id === projectToDelete);
            if (projectIndex === -1) return;

            // 从数据中移除项目
            projectsData.splice(projectIndex, 1);

            // 更新项目列表
            applyFilters();

            // 关闭确认对话框
            deleteConfirmModal.classList.remove('active');
            projectToDelete = null;

            showNotification('项目删除成功', 'success');
        }

        // 显示通知
        function showNotification(message, type) {
            // 创建通知元素
            const notification = document.createElement('div');
            notification.className = `notification notification-${type}`;

            notification.innerHTML = `
                <i class="fas fa-${type === 'success' ? 'check-circle' : 'exclamation-circle'}"></i>
                <span>${message}</span>
            `;

            document.body.appendChild(notification);

            // 3秒后移除通知
            setTimeout(() => {
                notification.style.animation = 'slideOut 0.3s ease';
                setTimeout(() => {
                    if (notification.parentNode) {
                        notification.parentNode.removeChild(notification);
                    }
                }, 300);
            }, 3000);
        }

        // 辅助函数：获取状态文本
        function getStatusText(status) {
            switch(status) {
                case 0: return '未开始';
                case 1: return '进行中';
                case 2: return '已暂停';
                case 3: return '已完成';
                case 4: return '已关闭';
                default: return '未知';
            }
        }

        // 辅助函数：获取类型文本
        function getTypeText(type) {
            switch(type) {
                case 0: return '标准适配项目';
                case 1: return '紧急适配项目';
                case 2: return '专项测试项目';
                case 3: return '定制化项目';
                default: return '未知';
            }
        }

        // 辅助函数：获取优先级文本
        function getPriorityText(priority) {
            switch(priority) {
                case 1: return '低';
                case 2: return '中';
                case 3: return '高';
                case 4: return '紧急';
                default: return '未知';
            }
        }

        // 刷新项目列表
        function refreshProjects() {
            // 模拟从服务器重新加载数据
            showNotification('项目数据已刷新', 'success');
            applyFilters();
        }

        // 初始化
        document.addEventListener('DOMContentLoaded', () => {
            // 初始化目录树
            initDirectoryTree();

            // 初始化项目表格
            renderProjectsTable();
            renderPagination();
            updateStats();

            // 绑定按钮事件
            createProjectBtn.addEventListener('click', openCreateProjectModal);
            refreshProjectsBtn.addEventListener('click', refreshProjects);
            applyFiltersBtn.addEventListener('click', applyFilters);
            resetFiltersBtn.addEventListener('click', resetFilters);

            // 绑定模态框事件
            saveProjectBtn.addEventListener('click', saveProject);
            cancelBtn.addEventListener('click', () => projectModal.classList.remove('active'));
            closeModalBtn.addEventListener('click', () => projectModal.classList.remove('active'));

            // 详情模态框事件
            closeDetailBtn.addEventListener('click', () => detailModal.classList.remove('active'));
            closeDetailModalBtn.addEventListener('click', () => detailModal.classList.remove('active'));
            editFromDetailBtn.addEventListener('click', () => {
                const projectId = parseInt(editFromDetailBtn.dataset.projectId);
                detailModal.classList.remove('active');
                setTimeout(() => editProject(projectId), 300);
            });

            // 删除确认对话框事件
            cancelDeleteBtn.addEventListener('click', () => {
                deleteConfirmModal.classList.remove('active');
                projectToDelete = null;
            });
            confirmDeleteBtn.addEventListener('click', deleteProject);

            // 移动端菜单切换
            mobileMenuToggle.addEventListener('click', () => {
                sidebar.classList.toggle('active');
            });

            // 窗口大小变化时调整侧边栏
            window.addEventListener('resize', () => {
                if (window.innerWidth > 992) {
                    sidebar.classList.remove('active');
                }
            });

            // 点击模态框外部关闭模态框
            document.querySelectorAll('.modal-overlay').forEach(overlay => {
                overlay.addEventListener('click', (e) => {
                    if (e.target === overlay) {
                        overlay.classList.remove('active');
                    }
                });
            });
        });
    </script>
</body>
</html>
```

## 功能说明

这个页面实现了"项目创建与基础信息配置"的所有功能要求：

### 1. 创建项目
- 点击"创建项目"按钮打开模态框
- 填写项目编号、名称、负责人、类型、优先级等基础信息
- 系统自动生成唯一的项目编号
- 表单验证确保必填字段完整
- 验证结束日期不能早于开始日期

### 2. 项目列表
- 显示所有项目信息表格
- 每页显示5个项目（符合要求）
- 支持按状态、优先级、类型、负责人进行筛选
- 表格包含分页功能

### 3. 项目详情
- 点击"查看"图标查看项目完整信息
- 显示项目进度、时间计划等详细信息
- 显示关联的测试用例数、任务数、缺陷数等

### 4. 编辑/删除
- 点击"编辑"图标修改项目信息
- 点击"删除"图标移除项目
- 删除前检查是否有关联数据并提示确认

### 5. 界面特性
- 整体脚手架架构样式与2.html一致
- 使用相同的图标、主题和配色方案
- 页面上下滑动时顶部导航栏和左侧目录结构保持固定
- 软件名称已改为"适配中心测试管理软件 V1.0"
- 响应式设计，支持移动端显示

### 6. 数据统计
- 顶部统计卡片显示总项目数、进行中项目数、高优先级项目数、延期项目数
- 统计数据实时更新

### 7. 交互体验
- 完整的表单验证
- 操作成功/失败通知
- 删除确认对话框
- 平滑的动画效果

这个页面完全满足需求文档中的所有要求，并提供了良好的用户体验。

