        // 绑定仪表盘事件
        function bindDashboardEvents() {
            // 重新获取DOM元素
            const createDashboardBtn = document.getElementById('createDashboardBtn');
            const importTemplateBtn = document.getElementById('importTemplateBtn');
            const saveDashboardBtn = document.getElementById('saveDashboardBtn');
            const dashboardList = document.getElementById('dashboardList');
            const dataSourceType = document.getElementById('dataSourceType');
            const refreshInterval = document.getElementById('refreshInterval');

            // 绑定事件
            createDashboardBtn.addEventListener('click', () => {
                openCreateDashboardModal();
            });

            importTemplateBtn.addEventListener('click', () => {
                showNotification('模板导入功能将在下一版本实现', 'info');
            });

            saveDashboardBtn.addEventListener('click', () => {
                saveDashboard();
            });

            // 绑定仪表盘列表点击事件
            if (dashboardList) {
                dashboardList.addEventListener('click', (e) => {
                    const listItem = e.target.closest('.dashboard-list-item');
                    if (listItem) {
                        const dashboardId = parseInt(listItem.dataset.id);
                        selectDashboard(dashboardId);
                    }
                });
            }

            // 绑定数据源类型和刷新间隔变化事件
            if (dataSourceType) {
                dataSourceType.addEventListener('change', updateDataSourceConfig);
            }

            if (refreshInterval) {
                refreshInterval.addEventListener('change', updateDataSourceConfig);
            }

            // 绑定模态框事件
            document.getElementById('closeCreateModalBtn').addEventListener('click', closeCreateDashboardModal);
            document.getElementById('cancelCreateBtn').addEventListener('click', closeCreateDashboardModal);
            document.getElementById('confirmCreateBtn').addEventListener('click', confirmCreateDashboard);

            document.getElementById('closeChartConfigBtn').addEventListener('click', closeChartConfigModal);
            document.getElementById('cancelChartConfigBtn').addEventListener('click', closeChartConfigModal);
            document.getElementById('saveChartConfigBtn').addEventListener('click', saveChartConfig);
        }

        // 初始化图表类型
        function initChartTypes() {
            chartTypesContainer.innerHTML = '';

            chartTypes.forEach(chartType => {
                const chartItem = document.createElement('div');
                chartItem.className = 'chart-type-item';
                chartItem.dataset.type = chartType.id;
                chartItem.dataset.name = chartType.name;
                chartItem.innerHTML = `
                    <div class="chart-type-icon">
                        <i class="${chartType.icon}"></i>
                    </div>
                    <div class="chart-type-name">${chartType.name}</div>
                    <div style="font-size: 12px; color: #666; margin-top: 5px;">${chartType.description}</div>
                `;

                // 使图表类型可拖拽
                $(chartItem).draggable({
                    helper: 'clone',
                    cursor: 'move',
                    revert: 'invalid',
                    zIndex: 1000,
                    start: function() {
                        $(this).addClass('dragging');
                    },
                    stop: function() {
                        $(this).removeClass('dragging');
                    }
                });

                chartTypesContainer.appendChild(chartItem);
            });
        }

        // 初始化仪表盘列表
        function initDashboardList() {
            dashboardList.innerHTML = '';

            dashboards.forEach(dashboard => {
                const listItem = document.createElement('li');
                listItem.className = `dashboard-list-item ${currentDashboard.id === dashboard.id ? 'active' : ''}`;
                listItem.dataset.id = dashboard.id;

                listItem.innerHTML = `
                    <div>
                        <div class="dashboard-list-name">${dashboard.name}</div>
                        <div style="font-size: 12px; color: #666; margin-top: 3px;">${dashboard.description}</div>
                    </div>
                    ${dashboard.shared ? '<span class="dashboard-list-shared">共享</span>' : ''}
                `;

                dashboardList.appendChild(listItem);
            });
        }

        // 加载仪表盘画布
        function loadDashboardCanvas() {
            // 清空画布
            dashboardCanvas.innerHTML = '';

            // 如果当前仪表盘没有图表，显示空状态
            if (!currentDashboard.charts || currentDashboard.charts.length === 0) {
                emptyCanvasState.style.display = 'block';
                dashboardCanvas.appendChild(emptyCanvasState);
                return;
            }

            // 隐藏空状态
            emptyCanvasState.style.display = 'none';

            // 加载图表组件
            currentDashboard.charts.forEach(chart => {
                addChartToCanvas(chart);
            });

            // 重新启用拖拽和调整大小
            enableDragAndDrop();
        }

        // 添加图表到画布
        function addChartToCanvas(chart) {
            const chartWidget = document.createElement('div');
            chartWidget.className = 'chart-widget';
            chartWidget.id = `chart-${chart.id}`;
            chartWidget.dataset.chartId = chart.id;
            chartWidget.style.left = `${chart.x}px`;
            chartWidget.style.top = `${chart.y}px`;
            chartWidget.style.width = `${chart.width}px`;
            chartWidget.style.height = `${chart.height}px`;

            chartWidget.innerHTML = `
                <div class="chart-widget-header">
                    <div class="chart-widget-title">
                        <i class="${getChartIcon(chart.type)}"></i>
                        <span>${chart.title}</span>
                    </div>
                    <div class="chart-widget-actions">
                        <button class="chart-widget-action edit-chart-btn" title="编辑">
                            <i class="fas fa-cog"></i>
                        </button>
                        <button class="chart-widget-action delete-chart-btn" title="删除">
                            <i class="fas fa-trash"></i>
                        </button>
                    </div>
                </div>
                <div class="chart-widget-content">
                    <div class="chart-preview">
                        <i class="${getChartIcon(chart.type)}" style="font-size: 40px; margin-right: 15px;"></i>
                        <div>
                            <div>${chart.type}图表</div>
                            <div style="font-size: 12px; margin-top: 5px;">${chart.dataSourceType}数据源</div>
                        </div>
                    </div>
                </div>
            `;

            dashboardCanvas.appendChild(chartWidget);

            // 使图表组件可拖拽和调整大小
            $(chartWidget).draggable({
                containment: 'parent',
                scroll: false,
                stop: function(event, ui) {
                    updateChartPosition(chart.id, ui.position.left, ui.position.top);
                }
            }).resizable({
                containment: 'parent',
                handles: 'all',
                minWidth: 200,
                minHeight: 150,
                stop: function(event, ui) {
                    updateChartSize(chart.id, ui.size.width, ui.size.height);
                }
            });

            // 绑定编辑和删除按钮事件
            const editBtn = chartWidget.querySelector('.edit-chart-btn');
            const deleteBtn = chartWidget.querySelector('.delete-chart-btn');

            editBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                openChartConfigModal(chart);
            });

            deleteBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                deleteChart(chart.id);
            });
        }

        // 启用拖拽功能
        function enableDragAndDrop() {
            // 使画布可放置
            $(dashboardCanvas).droppable({
                accept: '.chart-type-item',
                drop: function(event, ui) {
                    const chartType = ui.draggable.data('type');
                    const chartName = ui.draggable.data('name');

                    // 计算放置位置
                    const offset = $(this).offset();
                    const x = ui.offset.left - offset.left;
                    const y = ui.offset.top - offset.top;

                    // 创建新图表
                    createNewChart(chartType, chartName, x, y);
                }
            });

            // 隐藏空状态
            emptyCanvasState.style.display = 'none';
        }

        // 创建新图表
        function createNewChart(chartType, chartName, x, y) {
            const newChart = {
                id: chartCounter++,
                type: chartType,
                title: `${chartName} ${currentDashboard.charts.length + 1}`,
                x: x,
                y: y,
                width: 300,
                height: 250,
                dataSourceType: document.getElementById('dataSourceType').value,
                refreshInterval: parseInt(document.getElementById('refreshInterval').value) || 0,
                dataSource: ''
            };

            // 添加到当前仪表盘
            if (!currentDashboard.charts) {
                currentDashboard.charts = [];
            }

            currentDashboard.charts.push(newChart);

            // 添加到画布
            addChartToCanvas(newChart);

            // 显示通知
            showNotification(`已添加${chartName}到仪表盘`, 'success');
        }

        // 更新图表位置
        function updateChartPosition(chartId, x, y) {
            const chart = currentDashboard.charts.find(c => c.id === chartId);
            if (chart) {
                chart.x = x;
                chart.y = y;
            }
        }

        // 更新图表大小
        function updateChartSize(chartId, width, height) {
            const chart = currentDashboard.charts.find(c => c.id === chartId);
            if (chart) {
                chart.width = width;
                chart.height = height;
            }
        }

        // 删除图表
        function deleteChart(chartId) {
            if (confirm('确定要删除这个图表吗？')) {
                // 从数组中移除
                currentDashboard.charts = currentDashboard.charts.filter(c => c.id !== chartId);

                // 从DOM中移除
                const chartElement = document.getElementById(`chart-${chartId}`);
                if (chartElement) {
                    chartElement.remove();
                }

                // 如果仪表盘没有图表了，显示空状态
                if (currentDashboard.charts.length === 0) {
                    emptyCanvasState.style.display = 'block';
                    dashboardCanvas.appendChild(emptyCanvasState);
                }

                showNotification('图表已删除', 'success');
            }
        }

        // 打开创建仪表盘模态框
        function openCreateDashboardModal() {
            createDashboardModal.classList.add('active');
            document.getElementById('dashboardName').focus();
        }

        // 关闭创建仪表盘模态框
        function closeCreateDashboardModal() {
            createDashboardModal.classList.remove('active');
            document.getElementById('createDashboardForm').reset();
        }

        // 确认创建仪表盘
        function confirmCreateDashboard() {
            const name = document.getElementById('dashboardName').value;
            const description = document.getElementById('dashboardDescription').value;
            const project = document.getElementById('dashboardProject').value;
            const shared = document.getElementById('dashboardShare').value === 'public';
            const template = document.getElementById('dashboardTemplate').value;

            if (!name) {
                alert('请输入仪表盘名称');
                return;
            }

            // 创建新仪表盘
            const newDashboard = {
                id: dashboards.length + 1,
                name: name,
                description: description,
                project: project === '0' ? '所有项目' : `项目${project}`,
                shared: shared,
                charts: []
            };

            // 如果选择了模板，添加预置图表
            if (template) {
                newDashboard.charts = getTemplateCharts(template);
            }

            // 添加到仪表盘列表
            dashboards.push(newDashboard);

            // 更新仪表盘列表显示
            initDashboardList();

            // 选中新创建的仪表盘
            selectDashboard(newDashboard.id);

            // 关闭模态框
            closeCreateDashboardModal();

            // 显示通知
            showNotification(`仪表盘"${name}"创建成功`, 'success');
        }

        // 获取模板图表
        function getTemplateCharts(templateType) {
            const baseCharts = [];

            switch(templateType) {
                case 'project_overview':
                    baseCharts.push(
                        { id: chartCounter++, type: 'gauge', title: '项目进度', x: 20, y: 20, width: 250, height: 200, dataSourceType: 'static', refreshInterval: 60, dataSource: '' },
                        { id: chartCounter++, type: 'bar', title: '缺陷分布', x: 290, y: 20, width: 350, height: 200, dataSourceType: 'api', refreshInterval: 120, dataSource: '' },
                        { id: chartCounter++, type: 'line', title: '测试用例趋势', x: 20, y: 240, width: 400, height: 200, dataSourceType: 'sql', refreshInterval: 180, dataSource: '' },
                        { id: chartCounter++, type: 'pie', title: '模块覆盖率', x: 440, y: 240, width: 250, height: 200, dataSourceType: 'static', refreshInterval: 60, dataSource: '' }
                    );
                    break;
                case 'defect_analysis':
                    baseCharts.push(
                        { id: chartCounter++, type: 'line', title: '缺陷趋势', x: 20, y: 20, width: 400, height: 200, dataSourceType: 'api', refreshInterval: 120, dataSource: '' },
                        { id: chartCounter++, type: 'pie', title: '缺陷严重程度', x: 440, y: 20, width: 250, height: 200, dataSourceType: 'static', refreshInterval: 60, dataSource: '' },
                        { id: chartCounter++, type: 'radar', title: '模块缺陷分布', x: 20, y: 240, width: 350, height: 200, dataSourceType: 'api', refreshInterval: 180, dataSource: '' },
                        { id: chartCounter++, type: 'bar', title: '缺陷处理效率', x: 390, y: 240, width: 300, height: 200, dataSourceType: 'sql', refreshInterval: 120, dataSource: '' }
                    );
                    break;
                case 'test_coverage':
                    baseCharts.push(
                        { id: chartCounter++, type: 'gauge', title: '总体覆盖率', x: 20, y: 20, width: 250, height: 200, dataSourceType: 'static', refreshInterval: 60, dataSource: '' },
                        { id: chartCounter++, type: 'bar', title: '模块覆盖率对比', x: 290, y: 20, width: 400, height: 200, dataSourceType: 'sql', refreshInterval: 180, dataSource: '' },
                        { id: chartCounter++, type: 'line', title: '覆盖率趋势', x: 20, y: 240, width: 350, height: 200, dataSourceType: 'api', refreshInterval: 120, dataSource: '' },
                        { id: chartCounter++, type: 'scatter', title: '用例执行分布', x: 390, y: 240, width: 300, height: 200, dataSourceType: 'sql', refreshInterval: 180, dataSource: '' }
                    );
                    break;
            }

            return baseCharts;
        }

        // 打开图表配置模态框
        function openChartConfigModal(chart) {
            currentChart = chart;

            document.getElementById('chartTitle').value = chart.title;
            document.getElementById('chartWidth').value = chart.width;
            document.getElementById('chartHeight').value = chart.height;
            document.getElementById('chartType').value = chart.type;
            document.getElementById('chartDataSource').value = chart.dataSource || '';

            chartConfigModal.classList.add('active');
        }

        // 关闭图表配置模态框
        function closeChartConfigModal() {
            chartConfigModal.classList.remove('active');
            currentChart = null;
        }

        // 保存图表配置
        function saveChartConfig() {
            if (!currentChart) return;

            const title = document.getElementById('chartTitle').value;
            const width = parseInt(document.getElementById('chartWidth').value);
            const height = parseInt(document.getElementById('chartHeight').value);
            const type = document.getElementById('chartType').value;
            const dataSource = document.getElementById('chartDataSource').value;

            // 更新图表
            currentChart.title = title;
            currentChart.width = width;
            currentChart.height = height;
            currentChart.type = type;
            currentChart.dataSource = dataSource;

            // 更新图表显示
            const chartElement = document.getElementById(`chart-${currentChart.id}`);
            if (chartElement) {
                chartElement.style.width = `${width}px`;
                chartElement.style.height = `${height}px`;

                const titleElement = chartElement.querySelector('.chart-widget-title span');
                const iconElement = chartElement.querySelector('.chart-widget-title i');
                const previewElement = chartElement.querySelector('.chart-preview');

                if (titleElement) titleElement.textContent = title;
                if (iconElement) iconElement.className = getChartIcon(type);
                if (previewElement) {
                    previewElement.innerHTML = `
                        <i class="${getChartIcon(type)}" style="font-size: 40px; margin-right: 15px;"></i>
                        <div>
                            <div>${type}图表</div>
                            <div style="font-size: 12px; margin-top: 5px;">${currentChart.dataSourceType}数据源</div>
                        </div>
                    `;
                }
            }

            closeChartConfigModal();
            showNotification('图表配置已保存', 'success');
        }

        // 选择仪表盘
        function selectDashboard(dashboardId) {
            currentDashboard = dashboards.find(d => d.id === dashboardId);

            // 更新仪表盘列表高亮
            document.querySelectorAll('.dashboard-list-item').forEach(item => {
                item.classList.remove('active');
                if (parseInt(item.dataset.id) === dashboardId) {
                    item.classList.add('active');
                }
            });

            // 加载仪表盘画布
            loadDashboardCanvas();

            // 更新数据源配置
            updateDataSourceConfig();

            showNotification(`已切换到"${currentDashboard.name}"`, 'info');
        }

        // 更新数据源配置
        function updateDataSourceConfig() {
            const dataSourceType = document.getElementById('dataSourceType').value;
            const refreshInterval = parseInt(document.getElementById('refreshInterval').value) || 0;

            // 更新当前仪表盘的所有图表
            if (currentDashboard.charts) {
                currentDashboard.charts.forEach(chart => {
                    chart.dataSourceType = dataSourceType;
                    chart.refreshInterval = refreshInterval;
                });
            }
        }

        // 保存仪表盘
        function saveDashboard() {
            // 在实际应用中，这里会将仪表盘配置保存到服务器
            // 这里我们只是模拟保存

            // 模拟保存到本地存储
            localStorage.setItem('dashboards', JSON.stringify(dashboards));

            showNotification(`仪表盘"${currentDashboard.name}"配置已保存`, 'success');
        }

        // 获取图表图标
        function getChartIcon(chartType) {
            switch(chartType) {
                case 'line': return 'fas fa-chart-line';
                case 'bar': return 'fas fa-chart-bar';
                case 'pie': return 'fas fa-chart-pie';
                case 'scatter': return 'fas fa-dot-circle';
                case 'radar': return 'fas fa-bullseye';
                case 'gauge': return 'fas fa-tachometer-alt';
                default: return 'fas fa-chart-bar';
            }
        }

        // 显示通知
        function showNotification(message, type) {
            // 创建通知元素
            const notification = document.createElement('div');
            notification.className = 'notification';
            notification.style.backgroundColor = type === 'success' ? '#4CAF50' : 
                                              type === 'error' ? '#f44336' : 
                                              type === 'info' ? '#2196F3' : '#4CAF50';

            notification.innerHTML = `
                <i class="fas fa-${type === 'success' ? 'check-circle' : 
                                  type === 'error' ? 'exclamation-circle' : 
                                  type === 'info' ? 'info-circle' : 'check-circle'}"></i>
                <span>${message}</span>
            `;

            document.body.appendChild(notification);

            // 3秒后移除通知
            setTimeout(() => {
                notification.style.animation = 'slideOut 0.3s ease';
                setTimeout(() => {
                    if (notification.parentNode) {
                        notification.parentNode.removeChild(notification);
                    }
                }, 300);
            }, 3000);
        }

        // 初始化
        document.addEventListener('DOMContentLoaded', () => {
            initDirectoryTree();
            loadCustomDashboard();

            // 移动端菜单切换
            mobileMenuToggle.addEventListener('click', () => {
                sidebar.classList.toggle('active');
            });

            // 窗口大小变化时调整侧边栏
            window.addEventListener('resize', () => {
                if (window.innerWidth > 992) {
                    sidebar.classList.remove('active');
                }
            });

            // 尝试从本地存储加载仪表盘数据
            const savedDashboards = localStorage.getItem('dashboards');
            if (savedDashboards) {
                try {
                    dashboards = JSON.parse(savedDashboards);
                    // 更新图表计数器
                    chartCounter = dashboards.reduce((max, dashboard) => {
                        if (dashboard.charts && dashboard.charts.length > 0) {
                            const maxChartId = Math.max(...dashboard.charts.map(c => c.id));
                            return Math.max(max, maxChartId);
                        }
                        return max;
                    }, 0) + 1;
                } catch (e) {
                    console.error('加载仪表盘数据失败:', e);
                }
            }
        });
    </script>
</body>
</html>
```

## 功能说明

这个自定义仪表盘功能页面实现了以下核心功能：

### 1. **界面架构**
- 完全复用了2.html的脚手架结构、样式和主题
- 左侧目录树与2.html保持一致，默认选中"自定义仪表盘"
- 顶部导航栏和左侧目录在页面滚动时保持固定

### 2. **软件名称更新**
- 已将软件名称从"中软国际适配中心-测试管理软件 V1.0"更新为"适配中心测试管理软件 V1.0"

### 3. **拖拽式配置**
- 左侧面板提供6种图表类型：折线图、柱状图、饼图、散点图、雷达图、仪表盘
- 支持从左侧拖拽图表到右侧画布区域
- 画布中的图表组件支持拖拽调整位置和调整大小

### 4. **图表管理**
- 每个图表组件包含标题、配置按钮和删除按钮
- 点击配置按钮可打开模态框配置图表属性
- 支持删除不需要的图表组件

### 5. **数据源配置**
- 支持三种数据源类型：SQL查询、API接口、静态数据
- 可设置定时刷新间隔（0表示不自动刷新）
- 数据源配置会应用到当前仪表盘的所有图表

### 6. **仪表盘管理**
- 支持创建多个仪表盘
- 仪表盘可设置为私有、团队共享或公开共享
- 提供预置模板：项目概览、缺陷分析、测试覆盖率
- 支持保存仪表盘配置到本地存储

### 7. **响应式设计**
- 适配桌面端和移动端
- 在移动端侧边栏会自动隐藏，可通过菜单按钮打开

### 8. **交互反馈**
- 操作成功/失败会有通知提示
- 拖拽时有视觉反馈
- 图表组件有悬停效果

这个实现完全符合要求，提供了完整的自定义仪表盘功能，同时保持了与2.html一致的用户体验和界面风格。

