                emptyCanvasState.style.display = 'block';
                dashboardCanvas.appendChild(emptyCanvasState);
                return;
            }

            // 隐藏空状态
            emptyCanvasState.style.display = 'none';

            // 加载图表组件
            currentDashboard.charts.forEach(chart => {
                addChartToCanvas(chart);
            });

            // 重新启用拖拽和调整大小
            enableDragAndDrop();
        }

        // 添加图表到画布
        function addChartToCanvas(chart) {
            const chartWidget = document.createElement('div');
            chartWidget.className = 'chart-widget';
            chartWidget.id = `chart-${chart.id}`;
            chartWidget.dataset.chartId = chart.id;
            chartWidget.style.left = `${chart.x}px`;
            chartWidget.style.top = `${chart.y}px`;
            chartWidget.style.width = `${chart.width}px`;
            chartWidget.style.height = `${chart.height}px`;

            // 获取图表类型信息
            const chartType = chartTypes.find(t => t.id === chart.type) || chartTypes[0];
            const datasourceType = datasourceTypes.find(t => t.id === chart.dataSourceType) || datasourceTypes[0];

            chartWidget.innerHTML = `
                <div class="chart-widget-header">
                    <div class="chart-widget-title">
                        <i class="${chartType.icon}"></i>
                        <span>${chart.title}</span>
                    </div>
                    <div class="chart-widget-actions">
                        <button class="chart-widget-action edit-chart-btn" title="编辑">
                            <i class="fas fa-cog"></i>
                        </button>
                        <button class="chart-widget-action delete-chart-btn" title="删除">
                            <i class="fas fa-trash"></i>
                        </button>
                    </div>
                </div>
                <div class="chart-widget-content">
                    <div class="chart-icon-preview">
                        <div class="chart-main-icon" style="background: linear-gradient(135deg, ${chartType.color}20 0%, ${chartType.color}10 100%); color: ${chartType.color};">
                            <i class="${chartType.icon}"></i>
                        </div>
                        <div class="chart-meta-icons">
                            <div class="meta-icon-item">
                                <div class="meta-icon" style="background-color: ${datasourceType.color}20; color: ${datasourceType.color};">
                                    <i class="${datasourceType.icon}"></i>
                                </div>
                                <div class="meta-icon-label">${datasourceType.name}</div>
                            </div>
                            <div class="meta-icon-item">
                                <div class="meta-icon" style="background-color: #f0f5ff; color: #4dabf7;">
                                    <i class="fas fa-clock"></i>
                                </div>
                                <div class="meta-icon-label">${chart.refreshInterval || 0}秒</div>
                            </div>
                        </div>
                    </div>
                </div>
            `;

            dashboardCanvas.appendChild(chartWidget);

            // 使图表组件可拖拽和调整大小
            $(chartWidget).draggable({
                containment: 'parent',
                scroll: false,
                stop: function(event, ui) {
                    updateChartPosition(chart.id, ui.position.left, ui.position.top);
                }
            }).resizable({
                containment: 'parent',
                handles: 'all',
                minWidth: 200,
                minHeight: 150,
                stop: function(event, ui) {
                    updateChartSize(chart.id, ui.size.width, ui.size.height);
                }
            });

            // 绑定编辑和删除按钮事件
            const editBtn = chartWidget.querySelector('.edit-chart-btn');
            const deleteBtn = chartWidget.querySelector('.delete-chart-btn');

            editBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                openChartConfigModal(chart);
            });

            deleteBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                deleteChart(chart.id);
            });
        }

        // 启用拖拽功能
        function enableDragAndDrop() {
            // 使画布可放置
            $(dashboardCanvas).droppable({
                accept: '.chart-type-card',
                drop: function(event, ui) {
                    const chartType = ui.draggable.data('type');
                    const chartName = ui.draggable.data('name');

                    // 计算放置位置
                    const offset = $(this).offset();
                    const x = ui.offset.left - offset.left;
                    const y = ui.offset.top - offset.top;

                    // 创建新图表
                    createNewChart(chartType, chartName, x, y);
                }
            });

            // 隐藏空状态
            emptyCanvasState.style.display = 'none';
        }

        // 创建新图表
        function createNewChart(chartType, chartName, x, y) {
            const chartTypeInfo = chartTypes.find(t => t.id === chartType) || chartTypes[0];
            const datasourceTypeInfo = datasourceTypes.find(t => t.id === currentDatasourceType) || datasourceTypes[0];

            const newChart = {
                id: chartCounter++,
                type: chartType,
                title: `${chartName} ${currentDashboard.charts ? currentDashboard.charts.length + 1 : 1}`,
                x: x,
                y: y,
                width: 300,
                height: 250,
                dataSourceType: currentDatasourceType,
                refreshInterval: 0,
                dataSource: ''
            };

            // 添加到当前仪表盘
            if (!currentDashboard.charts) {
                currentDashboard.charts = [];
            }

            currentDashboard.charts.push(newChart);

            // 添加到画布
            addChartToCanvas(newChart);

            // 显示通知
            showNotification(`已添加${chartName}到仪表盘`, 'success');
        }

        // 更新图表位置
        function updateChartPosition(chartId, x, y) {
            const chart = currentDashboard.charts.find(c => c.id === chartId);
            if (chart) {
                chart.x = x;
                chart.y = y;
            }
        }

        // 更新图表大小
        function updateChartSize(chartId, width, height) {
            const chart = currentDashboard.charts.find(c => c.id === chartId);
            if (chart) {
                chart.width = width;
                chart.height = height;
            }
        }

        // 删除图表
        function deleteChart(chartId) {
            if (confirm('确定要删除这个图表吗？')) {
                // 从数组中移除
                currentDashboard.charts = currentDashboard.charts.filter(c => c.id !== chartId);

                // 从DOM中移除
                const chartElement = document.getElementById(`chart-${chartId}`);
                if (chartElement) {
                    chartElement.remove();
                }

                // 如果仪表盘没有图表了，显示空状态
                if (currentDashboard.charts.length === 0) {
                    emptyCanvasState.style.display = 'block';
                    dashboardCanvas.appendChild(emptyCanvasState);
                }

                showNotification('图表已删除', 'success');
            }
        }

        // 选择数据源类型
        function selectDatasourceType(type) {
            currentDatasourceType = type;

            // 更新数据源类型卡片状态
            document.querySelectorAll('.datasource-card').forEach(card => {
                card.classList.remove('active');
                if (card.dataset.type === type) {
                    card.classList.add('active');
                }
            });

            // 更新数据状态
            updateDataStatus();

            // 更新当前仪表盘的所有图表
            if (currentDashboard.charts) {
                currentDashboard.charts.forEach(chart => {
                    chart.dataSourceType = type;
                });
            }

            showNotification(`已切换到${datasourceTypes.find(t => t.id === type).name}数据源`, 'info');
        }

        // 更新数据状态
        function updateDataStatus() {
            const datasourceType = datasourceTypes.find(t => t.id === currentDatasourceType) || datasourceTypes[0];
            dataStatus.textContent = `${datasourceType.name} - 已连接`;
        }

        // 打开创建仪表盘模态框
        function openCreateDashboardModal() {
            createDashboardModal.classList.add('active');
            document.getElementById('dashboardName').focus();
        }

        // 关闭创建仪表盘模态框
        function closeCreateDashboardModal() {
            createDashboardModal.classList.remove('active');
            document.getElementById('createDashboardForm').reset();
        }

        // 确认创建仪表盘
        function confirmCreateDashboard() {
            const name = document.getElementById('dashboardName').value;
            const description = document.getElementById('dashboardDescription').value;
            const project = document.getElementById('dashboardProject').value;
            const shared = document.getElementById('dashboardShare').value === 'public';
            const template = document.getElementById('dashboardTemplate').value;

            if (!name) {
                alert('请输入仪表盘名称');
                return;
            }

            // 获取仪表盘图标和颜色
            const dashboardIcons = ['fas fa-project-diagram', 'fas fa-chart-line', 'fas fa-tachometer-alt', 'fas fa-chart-bar', 'fas fa-chart-pie'];
            const dashboardColors = ['#1a3a8f', '#36b9cc', '#1cc88a', '#f6c23e', '#e74a3b', '#6f42c1'];
            const randomIcon = dashboardIcons[Math.floor(Math.random() * dashboardIcons.length)];
            const randomColor = dashboardColors[Math.floor(Math.random() * dashboardColors.length)];

            // 创建新仪表盘
            const newDashboard = {
                id: dashboards.length + 1,
                name: name,
                description: description,
                project: project === '0' ? '所有项目' : `项目${project}`,
                shared: shared,
                icon: randomIcon,
                color: randomColor,
                charts: []
            };

            // 如果选择了模板，添加预置图表
            if (template) {
                newDashboard.charts = getTemplateCharts(template);
            }

            // 添加到仪表盘列表
            dashboards.push(newDashboard);

            // 更新仪表盘列表显示
            initDashboardList();

            // 选中新创建的仪表盘
            selectDashboard(newDashboard.id);

            // 关闭模态框
            closeCreateDashboardModal();

            // 显示通知
            showNotification(`仪表盘"${name}"创建成功`, 'success');
        }

        // 获取模板图表
        function getTemplateCharts(templateType) {
            const baseCharts = [];

            let x = 20, y = 20;

            switch(templateType) {
                case 'project_overview':
                    baseCharts.push(
                        { id: chartCounter++, type: 'gauge', title: '项目进度', x: x, y: y, width: 250, height: 200, dataSourceType: currentDatasourceType, refreshInterval: 60, dataSource: '' },
                        { id: chartCounter++, type: 'bar', title: '缺陷分布', x: x + 270, y: y, width: 350, height: 200, dataSourceType: currentDatasourceType, refreshInterval: 120, dataSource: '' },
                        { id: chartCounter++, type: 'line', title: '测试用例趋势', x: x, y: y + 220, width: 400, height: 200, dataSourceType: currentDatasourceType, refreshInterval: 180, dataSource: '' },
                        { id: chartCounter++, type: 'pie', title: '模块覆盖率', x: x + 420, y: y + 220, width: 250, height: 200, dataSourceType: currentDatasourceType, refreshInterval: 60, dataSource: '' }
                    );
                    break;
                case 'defect_analysis':
                    baseCharts.push(
                        { id: chartCounter++, type: 'line', title: '缺陷趋势', x: x, y: y, width: 400, height: 200, dataSourceType: currentDatasourceType, refreshInterval: 120, dataSource: '' },
                        { id: chartCounter++, type: 'pie', title: '缺陷严重程度', x: x + 420, y: y, width: 250, height: 200, dataSourceType: currentDatasourceType, refreshInterval: 60, dataSource: '' },
                        { id: chartCounter++, type: 'radar', title: '模块缺陷分布', x: x, y: y + 220, width: 350, height: 200, dataSourceType: currentDatasourceType, refreshInterval: 180, dataSource: '' },
                        { id: chartCounter++, type: 'bar', title: '缺陷处理效率', x: x + 370, y: y + 220, width: 300, height: 200, dataSourceType: currentDatasourceType, refreshInterval: 120, dataSource: '' }
                    );
                    break;
                case 'test_coverage':
                    baseCharts.push(
                        { id: chartCounter++, type: 'gauge', title: '总体覆盖率', x: x, y: y, width: 250, height: 200, dataSourceType: currentDatasourceType, refreshInterval: 60, dataSource: '' },
                        { id: chartCounter++, type: 'bar', title: '模块覆盖率对比', x: x + 270, y: y, width: 400, height: 200, dataSourceType: currentDatasourceType, refreshInterval: 180, dataSource: '' },
                        { id: chartCounter++, type: 'line', title: '覆盖率趋势', x: x, y: y + 220, width: 350, height: 200, dataSourceType: currentDatasourceType, refreshInterval: 120, dataSource: '' },
                        { id: chartCounter++, type: 'scatter', title: '用例执行分布', x: x + 370, y: y + 220, width: 300, height: 200, dataSourceType: currentDatasourceType, refreshInterval: 180, dataSource: '' }
                    );
                    break;
