        const dashboardEmpty = document.getElementById('dashboardEmpty');
        const chartPalette = document.getElementById('chartPalette');
        const newDashboardModal = document.getElementById('newDashboardModal');
        const newDashboardBtn = document.getElementById('newDashboardBtn');
        const saveDashboardBtn = document.getElementById('saveDashboardBtn');
        const shareDashboardBtn = document.getElementById('shareDashboardBtn');
        const importTemplateBtn = document.getElementById('importTemplateBtn');
        const addChartBtn = document.getElementById('addChartBtn');
