        // 加载自定义仪表盘内容
        function loadCustomDashboard() {
            // 页面已经加载了自定义仪表盘，只需绑定事件
            bindDashboardEvents();
            initDragAndDrop();
        }

        // 绑定仪表盘事件
        function bindDashboardEvents() {
            // 新建仪表盘按钮
            newDashboardBtn.addEventListener('click', () => {
                newDashboardModal.classList.add('active');
            });

            // 保存仪表盘按钮
