            // 导入模板按钮
            importTemplateBtn.addEventListener('click', importTemplate);

            // 添加图表按钮
            addChartBtn.addEventListener('click', addRandomChart);

            // 添加第一个图表按钮
            addFirstChartBtn.addEventListener('click', addRandomChart);

            // 关闭新建仪表盘模态框
            closeNewDashboardModalBtn.addEventListener('click', () => {
                newDashboardModal.classList.remove('active');
            });

            // 取消新建仪表盘
            cancelNewDashboardBtn.addEventListener('click', () => {
                newDashboardModal.classList.remove('active');
            });

            // 确认新建仪表盘
            confirmNewDashboardBtn.addEventListener('click', createNewDashboard);

            // 仪表盘选择器
            dashboardSelector.addEventListener('change', switchDashboard);

            // 数据源选项
            dataSourceOptions.forEach(option => {
                option.addEventListener('click', () => {
                    dataSourceOptions.forEach(opt => opt.classList.remove('selected'));
                    option.classList.add('selected');
                });
            });
        }

        // 初始化拖拽功能
        function initDragAndDrop() {
            // 设置图表组件为可拖拽
            const chartTypesElements = document.querySelectorAll('.chart-type');
            chartTypesElements.forEach(chartType => {
                chartType.addEventListener('dragstart', (e) => {
                    e.dataTransfer.setData('text/plain', chartType.dataset.chartType);
                    e.dataTransfer.effectAllowed = 'copy';
                });
            });

            // 仪表盘画布拖放区域
            dashboardCanvas.addEventListener('dragover', (e) => {
                e.preventDefault();
                dashboardCanvas.classList.add('drag-over');
                e.dataTransfer.dropEffect = 'copy';
            });

            dashboardCanvas.addEventListener('dragleave', () => {
                dashboardCanvas.classList.remove('drag-over');
            });

            dashboardCanvas.addEventListener('drop', (e) => {
                e.preventDefault();
                dashboardCanvas.classList.remove('drag-over');

                const chartType = e.dataTransfer.getData('text/plain');
                if (chartType) {
                    const rect = dashboardCanvas.getBoundingClientRect();
                    const x = e.clientX - rect.left - 50;
                    const y = e.clientY - rect.top - 30;

                    addChartToDashboard(chartType, x, y);
                }
            });
        }

        // 添加图表到仪表盘
        function addChartToDashboard(chartType, x = 50, y = 50) {
            const chartConfig = chartTypes[chartType];
            if (!chartConfig) return;

            chartCounter++;
            const chartId = `chart-${chartCounter}`;

            const chartWidget = document.createElement('div');
            chartWidget.className = 'chart-widget';
            chartWidget.id = chartId;
            chartWidget.style.left = `${x}px`;
            chartWidget.style.top = `${y}px`;
            chartWidget.style.width = `${chartConfig.defaultWidth}px`;
            chartWidget.style.height = `${chartConfig.defaultHeight}px`;

            chartWidget.innerHTML = `
                <div class="chart-widget-header">
                    <div class="chart-widget-title">
                        <i class="${chartConfig.icon}"></i> ${chartConfig.name}
                    </div>
                    <div class="chart-widget-controls">
                        <button class="widget-control-btn" data-action="configure">
                            <i class="fas fa-cog"></i>
                        </button>
                        <button class="widget-control-btn" data-action="refresh">
                            <i class="fas fa-sync-alt"></i>
                        </button>
                        <button class="widget-control-btn" data-action="remove">
                            <i class="fas fa-times"></i>
                        </button>
                    </div>
                </div>
                <div class="chart-widget-content">
                    <div class="chart-placeholder">
                        <i class="${chartConfig.icon}"></i>
                        <span>${chartConfig.description}</span>
                    </div>
                </div>
            `;

            dashboardCanvas.appendChild(chartWidget);
            dashboardEmpty.style.display = 'none';

            // 添加图表到状态
            currentDashboard.charts.push({
                id: chartId,
                type: chartType,
                x: x,
                y: y,
                width: chartConfig.defaultWidth,
                height: chartConfig.defaultHeight
            });

            // 初始化图表拖拽和调整大小
            initChartWidget(chartWidget, chartId);

            showNotification(`已添加${chartConfig.name}`, 'success');
        }

        // 初始化图表组件交互
        function initChartWidget(chartWidget, chartId) {
            const header = chartWidget.querySelector('.chart-widget-header');
            let isDragging = false;
            let startX, startY, startLeft, startTop;

            // 拖拽功能
            header.addEventListener('mousedown', (e) => {
                if (e.target.closest('.widget-control-btn')) return;

                isDragging = true;
                startX = e.clientX;
                startY = e.clientY;
                startLeft = chartWidget.offsetLeft;
                startTop = chartWidget.offsetTop;

                chartWidget.style.zIndex = '1000';

                document.addEventListener('mousemove', onMouseMove);
                document.addEventListener('mouseup', onMouseUp);
            });

            function onMouseMove(e) {
                if (!isDragging) return;

                const dx = e.clientX - startX;
                const dy = e.clientY - startY;

                chartWidget.style.left = `${startLeft + dx}px`;
                chartWidget.style.top = `${startTop + dy}px`;
            }

            function onMouseUp() {
                isDragging = false;
                chartWidget.style.zIndex = '';

                // 更新图表位置状态
                const chartIndex = currentDashboard.charts.findIndex(chart => chart.id === chartId);
                if (chartIndex !== -1) {
                    currentDashboard.charts[chartIndex].x = chartWidget.offsetLeft;
                    currentDashboard.charts[chartIndex].y = chartWidget.offsetTop;
                }

                document.removeEventListener('mousemove', onMouseMove);
                document.removeEventListener('mouseup', onMouseUp);
            }

            // 控制按钮事件
            const controlButtons = chartWidget.querySelectorAll('.widget-control-btn');
            controlButtons.forEach(button => {
                button.addEventListener('click', (e) => {
                    e.stopPropagation();
                    const action = button.dataset.action;

                    switch (action) {
                        case 'configure':
                            configureChart(chartId);
                            break;
                        case 'refresh':
                            refreshChart(chartId);
                            break;
                        case 'remove':
                            removeChart(chartId);
                            break;
                    }
                });
            });

            // 调整大小
            chartWidget.addEventListener('mousedown', (e) => {
                if (e.offsetX > chartWidget.offsetWidth - 10 && e.offsetY > chartWidget.offsetHeight - 10) {
                    e.preventDefault();
                    startResizing(chartWidget, chartId);
                }
            });
        }

        // 开始调整大小
        function startResizing(chartWidget, chartId) {
            let isResizing = true;
            const startWidth = chartWidget.offsetWidth;
            const startHeight = chartWidget.offsetHeight;
            const startX = event.clientX;
            const startY = event.clientY;

            function onMouseMove(e) {
                if (!isResizing) return;

                const width = startWidth + (e.clientX - startX);
                const height = startHeight + (e.clientY - startY);

                if (width >= 200 && height >= 150) {
                    chartWidget.style.width = `${width}px`;
                    chartWidget.style.height = `${height}px`;
                }
            }

            function onMouseUp() {
                isResizing = false;

                // 更新图表尺寸状态
                const chartIndex = currentDashboard.charts.findIndex(chart => chart.id === chartId);
                if (chartIndex !== -1) {
                    currentDashboard.charts[chartIndex].width = chartWidget.offsetWidth;
                    currentDashboard.charts[chartIndex].height = chartWidget.offsetHeight;
                }

                document.removeEventListener('mousemove', onMouseMove);
                document.removeEventListener('mouseup', onMouseUp);
            }

            document.addEventListener('mousemove', onMouseMove);
            document.addEventListener('mouseup', onMouseUp);
        }

        // 配置图表
        function configureChart(chartId) {
            showNotification('图表配置功能开发中', 'info');
        }

        // 刷新图表
        function refreshChart(chartId) {
            showNotification('图表数据已刷新', 'success');
        }

        // 移除图表
        function removeChart(chartId) {
            const chartWidget = document.getElementById(chartId);
            if (chartWidget) {
                chartWidget.remove();

                // 从状态中移除
                currentDashboard.charts = currentDashboard.charts.filter(chart => chart.id !== chartId);

                // 如果没有图表了，显示空状态
                if (currentDashboard.charts.length === 0) {
                    dashboardEmpty.style.display = 'block';
                }

                showNotification('图表已移除', 'info');
            }
        }

        // 添加随机图表
        function addRandomChart() {
            const chartTypesArray = Object.keys(chartTypes);
            const randomType = chartTypesArray[Math.floor(Math.random() * chartTypesArray.length)];

            // 计算位置以避免重叠
            const x = 50 + (currentDashboard.charts.length % 3) * 300;
            const y = 50 + Math.floor(currentDashboard.charts.length / 3) * 250;

            addChartToDashboard(randomType, x, y);
        }

        // 保存仪表盘
        function saveDashboard() {
            // 更新所有图表的位置和尺寸
            currentDashboard.charts.forEach(chart => {
                const chartWidget = document.getElementById(chart.id);
                if (chartWidget) {
                    chart.x = chartWidget.offsetLeft;
                    chart.y = chartWidget.offsetTop;
                    chart.width = chartWidget.offsetWidth;
                    chart.height = chartWidget.offsetHeight;
                }
            });

            // 在实际应用中，这里会发送API请求保存到服务器
            showNotification(`仪表盘"${currentDashboard.name}"已保存`, 'success');
        }

        // 分享仪表盘
        function shareDashboard() {
            showNotification(`仪表盘"${currentDashboard.name}"已分享给团队成员`, 'success');
        }

        // 导入模板
        function importTemplate() {
            showNotification('正在导入预置模板...', 'info');

            // 模拟导入模板
            setTimeout(() => {
                // 清空现有图表
                currentDashboard.charts.forEach(chart => {
                    const chartWidget = document.getElementById(chart.id);
                    if (chartWidget) chartWidget.remove();
                });

                currentDashboard.charts = [];

                // 添加模板图表
                setTimeout(() => {
                    addChartToDashboard('burndown', 50, 50);
                    addChartToDashboard('bar', 500, 50);
                    addChartToDashboard('pie', 50, 350);
                    addChartToDashboard('line', 500, 350);

                    showNotification('预置模板已成功导入', 'success');
                }, 300);
            }, 1000);
        }

        // 创建新仪表盘
        function createNewDashboard() {
            const dashboardName = document.getElementById('dashboardName').value;
            const dashboardDescription = document.getElementById('dashboardDescription').value;
            const dashboardTemplate = document.getElementById('dashboardTemplate').value;

            if (!dashboardName.trim()) {
                showNotification('请输入仪表盘名称', 'error');
                return;
            }

            // 在实际应用中，这里会发送API请求创建新仪表盘
            currentDashboard = {
                id: Date.now(),
                name: dashboardName,
                charts: []
            };

            // 更新仪表盘选择器
            const option = document.createElement('option');
            option.value = currentDashboard.id;
            option.textContent = dashboardName;
            dashboardSelector.appendChild(option);
            dashboardSelector.value = currentDashboard.id;

            // 清空现有图表
            const chartWidgets = document.querySelectorAll('.chart-widget');
            chartWidgets.forEach(widget => widget.remove());

            // 显示空状态
            dashboardEmpty.style.display = 'block';

            // 更新仪表盘名称显示
            document.querySelector('.dashboard-name').textContent = dashboardName;

            // 关闭模态框
            newDashboardModal.classList.remove('active');

            // 重置表单
            document.getElementById('newDashboardForm').reset();

            showNotification(`仪表盘"${dashboardName}"已创建`, 'success');
        }

        // 切换仪表盘
        function switchDashboard() {
            const dashboardId = dashboardSelector.value;
            const dashboardName = dashboardSelector.options[dashboardSelector.selectedIndex].text;

            // 在实际应用中，这里会从服务器加载仪表盘数据
            // 这里我们只是模拟切换
            currentDashboard = {
                id: dashboardId,
                name: dashboardName,
                charts: []
            };

            // 清空现有图表
            const chartWidgets = document.querySelectorAll('.chart-widget');
            chartWidgets.forEach(widget => widget.remove());

            // 显示空状态
            dashboardEmpty.style.display = 'block';

            // 更新仪表盘名称显示
            document.querySelector('.dashboard-name').textContent = dashboardName;

            showNotification(`已切换到"${dashboardName}"`, 'success');
        }

        // 显示通知
        function showNotification(message, type) {
            // 创建通知元素
            const notification = document.createElement('div');
            notification.className = 'notification';
            notification.style.backgroundColor = type === 'success' ? '#4CAF50' : 
                                              type === 'error' ? '#f44336' : 
                                              type === 'info' ? '#2196F3' : '#4CAF50';

            notification.innerHTML = `
                <i class="fas fa-${type === 'success' ? 'check-circle' : 
                                  type === 'error' ? 'exclamation-circle' : 
                                  'info-circle'}"></i>
                <span>${message}</span>
            `;

            document.body.appendChild(notification);

            // 3秒后移除通知
            setTimeout(() => {
                notification.style.animation = 'slideOut 0.3s ease';
                setTimeout(() => {
                    if (notification.parentNode) {
                        notification.parentNode.removeChild(notification);
                    }
                }, 300);
            }, 3000);
        }

        // 初始化
        document.addEventListener('DOMContentLoaded', () => {
            initDirectoryTree();
            loadCustomDashboard();

            // 移动端菜单切换
            mobileMenuToggle.addEventListener('click', () => {
                sidebar.classList.toggle('active');
            });

            // 窗口大小变化时调整侧边栏
            window.addEventListener('resize', () => {
                if (window.innerWidth > 992) {
                    sidebar.classList.remove('active');
                }
            });

            // 初始化时添加一些示例图表
            setTimeout(() => {
                if (currentDashboard.charts.length === 0) {
                    addChartToDashboard('burndown', 50, 50);
                    addChartToDashboard('bar', 470, 50);
                    addChartToDashboard('pie', 50, 330);
                }
            }, 500);
        });
    </script>
</body>
