        function initExistingChartWidgets() {
            const chartWidgets = document.querySelectorAll('.chart-widget');
            chartWidgets.forEach(widget => {
                initChartWidget(widget, widget.id);

                // 添加到状态中
                if (!currentDashboard.charts.some(chart => chart.id === widget.id)) {
                    currentDashboard.charts.push({
                        id: widget.id,
                        type: widget.id.includes('table') ? 'table' : 'chart',
                        x: widget.offsetLeft,
                        y: widget.offsetTop,
                        width: widget.offsetWidth,
                        height: widget.offsetHeight
                    });
                }
            });
