        // 初始化拖拽功能
        function initDragAndDrop() {
            // 设置图表组件为可拖拽
            const chartTypesElements = document.querySelectorAll('.chart-type');
            chartTypesElements.forEach(chartType => {
                chartType.addEventListener('dragstart', (e) => {
                    e.dataTransfer.setData('text/plain', chartType.dataset.chartType);
                    e.dataTransfer.effectAllowed = 'copy';
                });
            });

            // 仪表盘画布拖放区域
            dashboardCanvas.addEventListener('dragover', (e) => {
                e.preventDefault();
                dashboardCanvas.classList.add('drag-over');
                e.dataTransfer.dropEffect = 'copy';
            });

            dashboardCanvas.addEventListener('dragleave', () => {
                dashboardCanvas.classList.remove('drag-over');
            });

            dashboardCanvas.addEventListener('drop', (e) => {
                e.preventDefault();
                dashboardCanvas.classList.remove('drag-over');

                const chartType = e.dataTransfer.getData('text/plain');
                if (chartType) {
                    const rect = dashboardCanvas.getBoundingClientRect();
                    const x = e.clientX - rect.left - 50;
                    const y = e.clientY - rect.top - 30;

                    addChartToDashboard(chartType, x, y);
                }
            });
        }

