        // 移除图表
        function removeChart(chartId) {
            const chartWidget = document.getElementById(chartId);
            if (chartWidget) {
                chartWidget.remove();

                // 从状态中移除
                currentDashboard.charts = currentDashboard.charts.filter(chart => chart.id !== chartId);

                // 如果没有图表了，显示空状态
                if (currentDashboard.charts.length === 0) {
                    dashboardEmpty.style.display = 'block';
                }

                showNotification('图表已移除', 'info');
            }
        }

