        function addRandomChart() {
            const chartTypesArray = Object.keys(chartTypes);
            const randomType = chartTypesArray[Math.floor(Math.random() * chartTypesArray.length)];

            // 计算位置以避免重叠
            const x = 50 + (currentDashboard.charts.length % 2) * 400;
            const y = 50 + Math.floor(currentDashboard.charts.length / 2) * 300;

            addChartToDashboard(randomType, x, y);
