        // 渲染测试用例表格
        function renderTestCaseTable() {
            // 计算当前页的数据
            const startIndex = (currentTestCasePage - 1) * itemsPerPage;
            const endIndex = Math.min(startIndex + itemsPerPage, testCaseData.length);
            const currentData = testCaseData.slice(startIndex, endIndex);

            testCaseTableBody.innerHTML = '';

            currentData.forEach(item => {
                // 确定状态徽章
                let statusBadgeClass = '';
                let statusText = '';
                switch(item.status) {
                    case '已完成':
                        statusBadgeClass = 'status-badge status-completed';
                        statusText = '已完成';
                        break;
                    case '进行中':
                        statusBadgeClass = 'status-badge status-active';
                        statusText = '进行中';
                        break;
                    case '未开始':
                        statusBadgeClass = 'status-badge status-inactive';
                        statusText = '未开始';
                        break;
                }

                // 确定优先级徽章
                let priorityBadgeClass = '';
                switch(item.priority) {
                    case '高':
                        priorityBadgeClass = 'priority-badge priority-high';
                        break;
                    case '中':
                        priorityBadgeClass = 'priority-badge priority-medium';
                        break;
                    case '低':
                        priorityBadgeClass = 'priority-badge priority-low';
                        break;
                }

                const row = document.createElement('tr');
                row.innerHTML = `
                    <td>TC-${item.id.toString().padStart(4, '0')}</td>
                    <td>${item.name}</td>
                    <td>${item.module}</td>
                    <td><span class="${priorityBadgeClass}">${item.priority}</span></td>
                    <td><span class="${statusBadgeClass}">${statusText}</span></td>
                    <td>${item.executor}</td>
                    <td>${item.execTime}</td>
                    <td>${item.passRate}</td>
                `;

                testCaseTableBody.appendChild(row);
            });

            // 渲染分页
            renderTestCasePagination();
        }

        // 渲染测试用例分页
        function renderTestCasePagination() {
            const totalPages = Math.ceil(testCaseData.length / itemsPerPage);

            // 更新分页信息
            const startItem = (currentTestCasePage - 1) * itemsPerPage + 1;
            const endItem = Math.min(currentTestCasePage * itemsPerPage, testCaseData.length);
            testCasePaginationInfo.textContent = `显示 ${startItem}-${endItem} 条，共 ${testCaseData.length} 条`;

            // 生成分页按钮
            testCasePagination.innerHTML = '';

            // 上一页按钮
            const prevLi = document.createElement('li');
            prevLi.className = 'page-item';
            prevLi.innerHTML = `<a class="page-link ${currentTestCasePage === 1 ? 'disabled' : ''}" href="#" data-page="${currentTestCasePage - 1}"><i class="fas fa-chevron-left"></i></a>`;
            testCasePagination.appendChild(prevLi);

            // 页码按钮
            const maxVisiblePages = 5;
            let startPage = Math.max(1, currentTestCasePage - Math.floor(maxVisiblePages / 2));
            let endPage = Math.min(totalPages, startPage + maxVisiblePages - 1);

            // 调整起始页，确保显示maxVisiblePages个页码
            if (endPage - startPage + 1 < maxVisiblePages) {
                startPage = Math.max(1, endPage - maxVisiblePages + 1);
            }

            for (let i = startPage; i <= endPage; i++) {
                const pageLi = document.createElement('li');
                pageLi.className = 'page-item';
                pageLi.innerHTML = `<a class="page-link ${i === currentTestCasePage ? 'active' : ''}" href="#" data-page="${i}">${i}</a>`;
                testCasePagination.appendChild(pageLi);
            }

            // 下一页按钮
            const nextLi = document.createElement('li');
            nextLi.className = 'page-item';
            nextLi.innerHTML = `<a class="page-link ${currentTestCasePage === totalPages ? 'disabled' : ''}" href="#" data-page="${currentTestCasePage + 1}"><i class="fas fa-chevron-right"></i></a>`;
            testCasePagination.appendChild(nextLi);

            // 绑定分页点击事件
            document.querySelectorAll('#testCasePagination .page-link').forEach(link => {
                link.addEventListener('click', (e) => {
                    e.preventDefault();

                    if (link.classList.contains('disabled')) return;

                    const page = parseInt(link.dataset.page);
                    if (!isNaN(page)) {
                        currentTestCasePage = page;
                        renderTestCaseTable();
                    }
                });
            });
        }

