        // 绑定角色模块事件
        function bindRoleEvents() {
            // 重新获取DOM元素
            const addRoleBtn = document.getElementById('addRoleBtn');
            const refreshRolesBtn = document.getElementById('refreshRolesBtn');
            const applyFiltersBtn = document.getElementById('applyFiltersBtn');
            const resetFiltersBtn = document.getElementById('resetFiltersBtn');

            // 绑定事件
            addRoleBtn.addEventListener('click', () => {
                openRoleModal();
            });

            refreshRolesBtn.addEventListener('click', refreshRoles);

            applyFiltersBtn.addEventListener('click', applyFilters);

            resetFiltersBtn.addEventListener('click', resetFilters);
        }

        // 应用筛选
        function applyFilters() {
            const roleTypeFilter = document.getElementById('roleTypeFilter').value;
            const statusFilter = document.getElementById('statusFilter').value;
            const searchInput = document.getElementById('searchRoleInput').value.toLowerCase();

            filteredRoles = rolesData.filter(role => {
                const matchesType = !roleTypeFilter || role.type === roleTypeFilter;
                const matchesStatus = !statusFilter || role.status === statusFilter;
                const matchesSearch = !searchInput || 
                    role.name.toLowerCase().includes(searchInput) || 
                    role.description.toLowerCase().includes(searchInput);

                return matchesType && matchesStatus && matchesSearch;
            });

            currentPage = 1;
            renderRolesTable();
            renderPagination();
            updateStats();
        }

        // 重置筛选
        function resetFilters() {
            document.getElementById('roleTypeFilter').value = '';
            document.getElementById('statusFilter').value = '';
            document.getElementById('searchRoleInput').value = '';

            filteredRoles = [...rolesData];
            currentPage = 1;
            renderRolesTable();
            renderPagination();
            updateStats();
        }

