            width: 40px;
            height: 40px;
            display: flex;
            align-items: center;
            justify-content: center;
            border-radius: 6px;
            background-color: white;
            border: 1px solid #ddd;
            color: #555;
            text-decoration: none;
            cursor: pointer;
            transition: all 0.2s ease;
        }

        .page-link:hover {
            background-color: #f0f5ff;
            border-color: #1a3a8f;
            color: #1a3a8f;
        }

        .page-link.active {
            background-color: #1a3a8f;
            border-color: #1a3a8f;
            color: white;
        }

        .page-link.disabled {
            background-color: #f5f5f5;
            color: #999;
            cursor: not-allowed;
        }

        .pagination-info {
            margin-left: 20px;
            color: #666;
            font-size: 14px;
        }

        /* 统计卡片 */
        .stats-container {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
            gap: 20px;
            margin-bottom: 30px;
        }

        .stat-card {
            background-color: white;
            border-radius: 10px;
            padding: 20px;
            box-shadow: 0 3px 10px rgba(0, 0, 0, 0.05);
            border-left: 4px solid #1a3a8f;
        }

        .stat-title {
            font-size: 14px;
            color: #666;
            margin-bottom: 10px;
        }

        .stat-value {
            font-size: 28px;
            font-weight: 600;
            color: #1a3a8f;
        }

        .stat-trend {
            font-size: 12px;
            margin-top: 5px;
        }

        .trend-up {
            color: #059669;
        }

        .trend-down {
            color: #dc2626;
        }

        /* 模态框样式 */
        .modal-overlay {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background-color: rgba(0, 0, 0, 0.5);
            display: flex;
            align-items: center;
            justify-content: center;
            z-index: 100;
            opacity: 0;
            visibility: hidden;
            transition: all 0.3s ease;
        }

        .modal-overlay.active {
            opacity: 1;
            visibility: visible;
        }

        .modal {
            background-color: white;
            border-radius: 12px;
            width: 700px;
            max-width: 90%;
            max-height: 90vh;
            overflow-y: auto;
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
            transform: translateY(20px);
            transition: transform 0.3s ease;
        }

        .modal-overlay.active .modal {
            transform: translateY(0);
        }

        .modal-header {
            padding: 25px 30px;
            border-bottom: 1px solid #eee;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .modal-title {
            font-size: 20px;
            font-weight: 600;
            color: #1a3a8f;
        }

        .modal-close {
            background: none;
            border: none;
            font-size: 20px;
            cursor: pointer;
            color: #999;
            transition: color 0.2s;
        }

        .modal-close:hover {
            color: #333;
        }

        .modal-body {
            padding: 30px;
        }

        .form-group {
            margin-bottom: 20px;
        }

        .form-label {
            display: block;
            margin-bottom: 8px;
            font-weight: 500;
            color: #555;
        }

        .form-control {
            width: 100%;
            padding: 12px 15px;
            border: 1px solid #ddd;
            border-radius: 6px;
            font-size: 15px;
            transition: border 0.2s;
        }

        .form-control:focus {
            outline: none;
            border-color: #1a3a8f;
            box-shadow: 0 0 0 3px rgba(26, 58, 143, 0.1);
        }

        .select-control {
            width: 100%;
            padding: 12px 15px;
            border: 1px solid #ddd;
            border-radius: 6px;
            font-size: 15px;
            background-color: white;
            transition: border 0.2s;
        }

        .modal-footer {
            padding: 20px 30px;
            border-top: 1px solid #eee;
            display: flex;
            justify-content: flex-end;
            gap: 15px;
        }

        /* 权限配置样式 */
        .permission-container {
            margin-top: 20px;
            border: 1px solid #eaeff5;
            border-radius: 8px;
            overflow: hidden;
        }

        .permission-section {
            border-bottom: 1px solid #eaeff5;
        }

        .permission-section:last-child {
            border-bottom: none;
        }

        .permission-header {
            background-color: #f8fafd;
            padding: 15px 20px;
            font-weight: 600;
            color: #1a3a8f;
            display: flex;
            align-items: center;
            justify-content: space-between;
            cursor: pointer;
        }

        .permission-header i {
            transition: transform 0.3s;
        }

        .permission-header.collapsed i {
            transform: rotate(-90deg);
        }

        .permission-content {
            padding: 20px;
            background-color: white;
        }

        .permission-row {
            display: flex;
            align-items: center;
            margin-bottom: 15px;
            padding-bottom: 15px;
            border-bottom: 1px solid #f0f5ff;
        }

        .permission-row:last-child {
            margin-bottom: 0;
            padding-bottom: 0;
            border-bottom: none;
        }

        .permission-name {
            flex: 1;
            font-weight: 500;
        }

        .permission-desc {
            flex: 2;
            color: #666;
            font-size: 14px;
        }

        .permission-actions {
            flex: 1;
            display: flex;
            justify-content: flex-end;
            gap: 15px;
        }

        .checkbox-group {
            display: flex;
            align-items: center;
        }

        .checkbox-group input[type="checkbox"] {
            margin-right: 8px;
            width: 18px;
            height: 18px;
        }

        /* 空状态 */
        .empty-state {
            text-align: center;
            padding: 60px 20px;
            color: #999;
        }

        .empty-state i {
            font-size: 50px;
            margin-bottom: 20px;
            opacity: 0.5;
        }

        .empty-state h3 {
            font-size: 18px;
            margin-bottom: 10px;
            color: #666;
        }

        /* 过滤器 */
        .filter-container {
            background-color: #f8fafd;
            border-radius: 8px;
            padding: 20px;
            margin-bottom: 20px;
            display: flex;
            flex-wrap: wrap;
            gap: 15px;
            align-items: flex-end;
        }

        .filter-group {
            flex: 1;
            min-width: 150px;
        }

        .filter-label {
            display: block;
            margin-bottom: 8px;
            font-size: 14px;
            font-weight: 500;
            color: #555;
        }

        .export-buttons {
            display: flex;
            gap: 10px;
        }

        /* 响应式设计 */
        @media (max-width: 1200px) {
            .sidebar {
                width: 250px;
            }

            .main-content {
                margin-left: 250px;
                width: calc(100% - 250px);
            }
        }

        @media (max-width: 992px) {
            .sidebar {
                position: fixed;
                left: -280px;
                transition: left 0.3s ease;
            }

            .sidebar.active {
                left: 0;
            }

            .main-content {
                margin-left: 0;
                width: 100%;
            }

            .mobile-menu-toggle {
                display: flex;
            }

            .stats-container {
                grid-template-columns: repeat(2, 1fr);
            }
        }

        .mobile-menu-toggle {
            display: none;
            background: none;
            border: none;
            font-size: 20px;
            color: #1a3a8f;
            cursor: pointer;
        }

        @media (max-width: 768px) {
            .stats-container {
                grid-template-columns: 1fr;
            }

            .content-area {
                padding: 15px;
            }

            .module-card {
                padding: 20px;
            }

            .filter-container {
                flex-direction: column;
                align-items: stretch;
            }

            .filter-group {
                min-width: 100%;
            }
        }
    </style>
</head>
<body>
    <!-- 左侧导航栏 -->
    <div class="sidebar" id="sidebar">
        <div class="logo-container">
            <div class="logo">
                <i class="fas fa-cogs"></i>
            </div>
            <div class="logo-text">
                <h1>适配中心测试管理软件</h1>
                <p>版本 V1.0</p>
            </div>
        </div>

        <div class="directory-container">
            <div class="directory-title">功能目录</div>
            <ul class="directory-tree" id="directoryTree">
                <!-- 目录树将通过JavaScript动态生成 -->
            </ul>
        </div>
    </div>

    <!-- 右侧主内容区 -->
    <div class="main-content">
        <div class="top-bar">
            <button class="mobile-menu-toggle" id="mobileMenuToggle">
                <i class="fas fa-bars"></i>
            </button>
            <div class="page-title" id="pageTitle">角色-权限-访问控制</div>
            <div class="user-info">
                <div class="user-avatar">刘</div>
                <div>
                    <div style="font-weight: 500;">刘贺</div>
                    <div style="font-size: 13px; color: #666;">管理员</div>
                </div>
            </div>
        </div>

        <div class="content-area" id="contentArea">
            <!-- 统计卡片 -->
            <div class="stats-container">
                <div class="stat-card">
                    <div class="stat-title">总角色数</div>
                    <div class="stat-value" id="totalRoles">6</div>
                    <div class="stat-trend trend-up">较上月 ↑ 1个</div>
                </div>
                <div class="stat-card">
                    <div class="stat-title">系统角色</div>
                    <div class="stat-value" id="systemRoles">4</div>
                    <div class="stat-trend">预置角色</div>
                </div>
                <div class="stat-card">
                    <div class="stat-title">自定义角色</div>
                    <div class="stat-value" id="customRoles">2</div>
                    <div class="stat-trend trend-up">较上月 ↑ 1个</div>
                </div>
                <div class="stat-card">
                    <div class="stat-title">活跃用户</div>
                    <div class="stat-value" id="activeUsers">142</div>
                    <div class="stat-trend trend-up">较上月 ↑ 12人</div>
                </div>
            </div>

            <!-- 角色-权限-访问控制模块 -->
            <div class="module-card" id="roleAccessControlCard">
                <div class="module-header">
                    <div>
                        <div class="module-title">角色-权限-访问控制</div>
                        <div class="module-subtitle">基于RBAC模型的权限体系，支持自定义角色、功能权限与数据访问权限的精细化控制</div>
                    </div>
                    <div class="action-buttons">
                        <button class="btn btn-primary" id="addRoleBtn">
                            <i class="fas fa-plus-circle"></i> 添加角色
                        </button>
                        <button class="btn btn-secondary" id="refreshRolesBtn">
                            <i class="fas fa-sync-alt"></i> 刷新
                        </button>
                    </div>
                </div>

                <!-- 过滤器 -->
                <div class="filter-container">
                    <div class="filter-group">
                        <label class="filter-label">角色类型</label>
                        <select class="select-control" id="roleTypeFilter">
                            <option value="">全部</option>
                            <option value="system">系统角色</option>
                            <option value="custom">自定义角色</option>
                        </select>
                    </div>
                    <div class="filter-group">
                        <label class="filter-label">状态</label>
                        <select class="select-control" id="statusFilter">
                            <option value="">全部</option>
                            <option value="active">启用</option>
                            <option value="inactive">禁用</option>
                        </select>
                    </div>
                    <div class="filter-group">
                        <label class="filter-label">关键词搜索</label>
                        <input type="text" class="form-control" id="keywordFilter" placeholder="角色名称/编码">
                    </div>
                    <div class="export-buttons">
                        <button class="btn btn-secondary" id="applyFiltersBtn">
                            <i class="fas fa-filter"></i> 筛选
                        </button>
                        <button class="btn btn-secondary" id="resetFiltersBtn">
                            <i class="fas fa-redo"></i> 重置
                        </button>
                    </div>
                </div>

                <!-- 角色列表表格 -->
                <div class="table-container">
                    <table id="rolesTable">
                        <thead>
                            <tr>
                                <th width="10%">角色ID</th>
                                <th width="20%">角色名称</th>
                                <th width="15%">角色编码</th>
                                <th width="15%">角色类型</th>
                                <th width="10%">状态</th>
                                <th width="15%">创建时间</th>
                                <th width="15%">操作</th>
                            </tr>
                        </thead>
                        <tbody id="rolesTableBody">
                            <!-- 表格数据将通过JavaScript动态生成 -->
                        </tbody>
                    </table>
                </div>

                <!-- 分页组件 -->
                <div class="pagination-container">
                    <ul class="pagination" id="pagination">
                        <!-- 分页按钮将通过JavaScript动态生成 -->
                    </ul>
                    <div class="pagination-info" id="paginationInfo">
                        显示 1-6 条，共 6 条
                    </div>
                </div>

                <!-- 空状态 -->
                <div class="empty-state" id="emptyState" style="display: none;">
                    <i class="fas fa-user-shield"></i>
                    <h3>暂无角色数据</h3>
                    <p>当前筛选条件下未找到角色记录</p>
                </div>
            </div>

            <!-- 权限说明卡片 -->
            <div class="module-card">
                <div class="module-header">
                    <div class="module-title">RBAC权限模型说明</div>
                </div>
                <div style="line-height: 1.6;">
                    <p>本系统采用基于角色的访问控制(RBAC)模型，实现权限的精细化管理：</p>
                    <ul style="margin-top: 15px; padding-left: 20px;">
                        <li style="margin-bottom: 10px;"><strong>系统预置角色</strong>：管理员、项目经理、测试工程师、观察员，满足大部分场景需求</li>
                        <li style="margin-bottom: 10px;"><strong>自定义角色</strong>：支持根据实际业务需求创建新的角色，配置相应权限</li>
                        <li style="margin-bottom: 10px;"><strong>功能权限</strong>：控制用户能否访问特定功能模块（项目管理、用例管理、任务管理等）</li>
                        <li style="margin-bottom: 10px;"><strong>数据权限</strong>：控制用户能够访问哪些数据（全部数据、本部门数据、本人数据、自定义数据）</li>
                        <li style="margin-bottom: 10px;"><strong>权限验证</strong>：用户登录后自动应用角色权限，界面与功能根据权限动态显示</li>
                    </ul>
                </div>
            </div>
        </div>
    </div>

    <!-- 添加/编辑角色模态框 -->
    <div class="modal-overlay" id="roleModal">
        <div class="modal">
            <div class="modal-header">
                <div class="modal-title" id="roleModalTitle">添加新角色</div>
                <button class="modal-close" id="closeRoleModalBtn">
                    <i class="fas fa-times"></i>
                </button>
            </div>
            <div class="modal-body">
                <form id="roleForm">
                    <div class="form-group">
                        <label class="form-label" for="roleName">角色名称 *</label>
                        <input type="text" class="form-control" id="roleName" placeholder="请输入角色名称" required>
                    </div>

                    <div class="form-group">
                        <label class="form-label" for="roleCode">角色编码 *</label>
                        <input type="text" class="form-control" id="roleCode" placeholder="请输入角色编码（英文）" required>
                        <div style="font-size: 12px; color: #666; margin-top: 5px;">角色编码需唯一，用于系统识别</div>
                    </div>

                    <div class="form-group">
                        <label class="form-label" for="roleType">角色类型 *</label>
                        <select class="select-control" id="roleType" required>
                            <option value="">请选择角色类型</option>
                            <option value="system">系统角色</option>
                            <option value="custom" selected>自定义角色</option>
                        </select>
                    </div>

                    <div class="form-group">
                        <label class="form-label" for="roleStatus">状态 *</label>
                        <select class="select-control" id="roleStatus" required>
                            <option value="active" selected>启用</option>
                            <option value="inactive">禁用</option>
                        </select>
                    </div>

                    <div class="form-group">
                        <label class="form-label" for="roleDesc">角色描述</label>
                        <textarea class="form-control" id="roleDesc" rows="3" placeholder="请输入角色描述"></textarea>
                    </div>

                    <div class="form-group">
                        <label class="form-label">数据权限范围 *</label>
                        <select class="select-control" id="dataScope" required>
                            <option value="1">全部数据</option>
                            <option value="2">本部门数据</option>
                            <option value="3">本人数据</option>
                            <option value="4">自定义数据</option>
                        </select>
                    </div>

                    <!-- 权限配置区域 -->
                    <div class="permission-container" id="permissionContainer">
                        <div class="permission-section">
                            <div class="permission-header">
                                <span><i class="fas fa-project-diagram"></i> 项目管理权限</span>
                                <i class="fas fa-chevron-down"></i>
                            </div>
                            <div class="permission-content">
                                <div class="permission-row">
                                    <div class="permission-name">项目创建</div>
                                    <div class="permission-desc">允许创建新的测试项目</div>
                                    <div class="permission-actions">
                                        <div class="checkbox-group">
                                            <input type="checkbox" id="perm-project-create" name="permissions" value="project:create">
                                            <label for="perm-project-create">启用</label>
                                        </div>
                                    </div>
                                </div>
                                <div class="permission-row">
                                    <div class="permission-name">项目编辑</div>
                                    <div class="permission-desc">允许编辑已有项目信息</div>
                                    <div class="permission-actions">
                                        <div class="checkbox-group">
                                            <input type="checkbox" id="perm-project-edit" name="permissions" value="project:edit">
                                            <label for="perm-project-edit">启用</label>
                                        </div>
                                    </div>
                                </div>
                                <div class="permission-row">
                                    <div class="permission-name">项目删除</div>
                                    <div class="permission-desc">允许删除测试项目</div>
                                    <div class="permission-actions">
                                        <div class="checkbox-group">
                                            <input type="checkbox" id="perm-project-delete" name="permissions" value="project:delete">
                                            <label for="perm-project-delete">启用</label>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div class="permission-section">
                            <div class="permission-header">
                                <span><i class="fas fa-book"></i> 用例管理权限</span>
                                <i class="fas fa-chevron-down"></i>
                            </div>
                            <div class="permission-content">
                                <div class="permission-row">
                                    <div class="permission-name">用例创建</div>
                                    <div class="permission-desc">允许创建测试用例</div>
                                    <div class="permission-actions">
                                        <div class="checkbox-group">
                                            <input type="checkbox" id="perm-case-create" name="permissions" value="case:create">
                                            <label for="perm-case-create">启用</label>
                                        </div>
                                    </div>
                                </div>
                                <div class="permission-row">
                                    <div class="permission-name">用例编辑</div>
                                    <div class="permission-desc">允许编辑测试用例</div>
                                    <div class="permission-actions">
                                        <div class="checkbox-group">
                                            <input type="checkbox" id="perm-case-edit" name="permissions" value="case:edit">
                                            <label for="perm-case-edit">启用</label>
                                        </div>
                                    </div>
                                </div>
                                <div class="permission-row">
                                    <div class="permission-name">用例执行</div>
                                    <div class="permission-desc">允许执行测试用例</div>
                                    <div class="permission-actions">
                                        <div class="checkbox-group">
                                            <input type="checkbox" id="perm-case-execute" name="permissions" value="case:execute">
                                            <label for="perm-case-execute">启用</label>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div class="permission-section">
                            <div class="permission-header">
                                <span><i class="fas fa-tasks"></i> 任务管理权限</span>
                                <i class="fas fa-chevron-down"></i>
                            </div>
                            <div class="permission-content">
                                <div class="permission-row">
                                    <div class="permission-name">任务创建</div>
                                    <div class="permission-desc">允许创建测试任务</div>
                                    <div class="permission-actions">
                                        <div class="checkbox-group">
                                            <input type="checkbox" id="perm-task-create" name="permissions" value="task:create">
                                            <label for="perm-task-create">启用</label>
                                        </div>
                                    </div>
                                </div>
                                <div class="permission-row">
                                    <div class="permission-name">任务分配</div>
                                    <div class="permission-desc">允许分配测试任务</div>
                                    <div class="permission-actions">
                                        <div class="checkbox-group">
                                            <input type="checkbox" id="perm-task-assign" name="permissions" value="task:assign">
                                            <label for="perm-task-assign">启用</label>
                                        </div>
                                    </div>
                                </div>
                                <div class="permission-row">
                                    <div class="permission-name">任务执行</div>
                                    <div class="permission-desc">允许执行测试任务</div>
                                    <div class="permission-actions">
                                        <div class="checkbox-group">
                                            <input type="checkbox" id="perm-task-execute" name="permissions" value="task:execute">
                                            <label for="perm-task-execute">启用</label>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div class="permission-section">
                            <div class="permission-header">
                                <span><i class="fas fa-chart-bar"></i> 报表管理权限</span>
                                <i class="fas fa-chevron-down"></i>
                            </div>
                            <div class="permission-content">
                                <div class="permission-row">
                                    <div class="permission-name">报表查看</div>
                                    <div class="permission-desc">允许查看各类报表</div>
                                    <div class="permission-actions">
                                        <div class="checkbox-group">
                                            <input type="checkbox" id="perm-report-view" name="permissions" value="report:view">
                                            <label for="perm-report-view">启用</label>
                                        </div>
                                    </div>
                                </div>
