        // 应用筛选
        function applyFilters() {
            const roleTypeFilter = document.getElementById('roleTypeFilter').value;
            const statusFilter = document.getElementById('statusFilter').value;
            const keywordFilter = document.getElementById('keywordFilter').value.toLowerCase();

            filteredRoles = rolesData.filter(role => {
                const matchesType = !roleTypeFilter || role.type === roleTypeFilter;
                const matchesStatus = !statusFilter || role.status === statusFilter;
                const matchesKeyword = !keywordFilter || 
                    role.name.toLowerCase().includes(keywordFilter) || 
                    role.code.toLowerCase().includes(keywordFilter) ||
                    (role.desc && role.desc.toLowerCase().includes(keywordFilter));

                return matchesType && matchesStatus && matchesKeyword;
            });

            currentPage = 1;
            renderRolesTable();
            renderPagination();
            updateStats();
        }

