            </ul>
        </div>
    </div>

    <!-- 右侧主内容区 -->
    <div class="main-content">
        <div class="top-bar">
            <button class="mobile-menu-toggle" id="mobileMenuToggle">
                <i class="fas fa-bars"></i>
            </button>
            <div class="page-title" id="pageTitle">用户安全</div>
            <div class="user-info">
                <div class="user-avatar">刘</div>
                <div>
                    <div style="font-weight: 500;">刘贺</div>
                    <div style="font-size: 13px; color: #666;">系统管理员</div>
                </div>
            </div>
        </div>

        <div class="content-area" id="contentArea">
            <!-- 密码策略设置 -->
            <div class="module-card">
                <div class="module-header">
                    <div>
                        <div class="module-title">密码策略设置</div>
                        <div class="module-subtitle">配置密码复杂度、过期时间、重复使用限制等安全规则</div>
                    </div>
                </div>

                <div class="form-container">
                    <div class="form-section">
                        <div class="section-header">
                            <div class="section-icon">
                                <i class="fas fa-key"></i>
                            </div>
                            <div>
                                <div class="section-title">密码复杂度要求</div>
                                <div class="section-subtitle">设置密码必须满足的复杂性规则</div>
                            </div>
                        </div>

                        <div class="form-group">
                            <div class="checkbox-group">
                                <input type="checkbox" id="minLength" class="checkbox" checked>
                                <label for="minLength" class="checkbox-label">最小密码长度: 8个字符</label>
                            </div>
                            <div class="checkbox-group">
                                <input type="checkbox" id="requireUppercase" class="checkbox" checked>
                                <label for="requireUppercase" class="checkbox-label">必须包含大写字母</label>
                            </div>
                            <div class="checkbox-group">
                                <input type="checkbox" id="requireLowercase" class="checkbox" checked>
                                <label for="requireLowercase" class="checkbox-label">必须包含小写字母</label>
                            </div>
                            <div class="checkbox-group">
                                <input type="checkbox" id="requireNumbers" class="checkbox" checked>
                                <label for="requireNumbers" class="checkbox-label">必须包含数字</label>
                            </div>
                            <div class="checkbox-group">
                                <input type="checkbox" id="requireSpecial" class="checkbox" checked>
                                <label for="requireSpecial" class="checkbox-label">必须包含特殊字符 (!@#$%^&*)</label>
                            </div>
                        </div>
                    </div>

                    <div class="form-section">
                        <div class="section-header">
                            <div class="section-icon">
                                <i class="fas fa-clock"></i>
                            </div>
                            <div>
                                <div class="section-title">密码生命周期</div>
                                <div class="section-subtitle">设置密码过期时间和重复使用限制</div>
                            </div>
                        </div>

                        <div class="form-group">
                            <label class="form-label" for="expiryDays">密码过期时间</label>
                            <select class="select-control" id="expiryDays">
                                <option value="30">30天</option>
                                <option value="60" selected>60天</option>
                                <option value="90">90天</option>
                                <option value="180">180天</option>
                                <option value="365">365天</option>
                                <option value="0">永不过期</option>
                            </select>
                        </div>

                        <div class="form-group">
                            <label class="form-label" for="historyCount">密码重复使用限制</label>
                            <select class="select-control" id="historyCount">
                                <option value="3">不能与最近3次密码相同</option>
                                <option value="5" selected>不能与最近5次密码相同</option>
                                <option value="10">不能与最近10次密码相同</option>
                                <option value="0">无限制</option>
                            </select>
                        </div>

                        <div class="form-group">
                            <label class="form-label" for="warningDays">密码过期提醒</label>
                            <select class="select-control" id="warningDays">
                                <option value="7">提前7天提醒</option>
                                <option value="14" selected>提前14天提醒</option>
                                <option value="30">提前30天提醒</option>
                            </select>
                        </div>
                    </div>
                </div>

                <div class="action-buttons" style="margin-top: 30px; justify-content: flex-end;">
                    <button class="btn btn-secondary" id="resetPasswordPolicyBtn">
                        <i class="fas fa-redo"></i> 恢复默认
                    </button>
                    <button class="btn btn-primary" id="savePasswordPolicyBtn">
                        <i class="fas fa-save"></i> 保存策略
                    </button>
                </div>
            </div>

            <!-- MFA管理 -->
            <div class="module-card">
                <div class="module-header">
                    <div>
                        <div class="module-title">MFA管理</div>
                        <div class="module-subtitle">查看用户MFA状态，批量启用多因素认证，提升账户安全性</div>
                    </div>
                </div>

                <div class="form-section">
                    <div class="section-header">
                        <div class="section-icon">
                            <i class="fas fa-user-shield"></i>
                        </div>
                        <div>
                            <div class="section-title">多因素认证设置</div>
                            <div class="section-subtitle">启用或禁用用户的MFA功能</div>
                        </div>
                    </div>

                    <div class="form-group">
                        <div class="checkbox-group">
                            <input type="checkbox" id="forceAdminMFA" class="checkbox" checked>
                            <label for="forceAdminMFA" class="checkbox-label">强制管理员账户启用MFA</label>
                        </div>
                        <div class="checkbox-group">
                            <input type="checkbox" id="enableMFAOption" class="checkbox" checked>
                            <label for="enableMFAOption" class="checkbox-label">允许普通用户自主启用MFA</label>
                        </div>
                    </div>

                    <div class="form-group">
                        <label class="form-label" for="mfaMethod">默认MFA方法</label>
                        <select class="select-control" id="mfaMethod">
                            <option value="app">认证应用程序 (如Google Authenticator)</option>
                            <option value="sms">短信验证码</option>
                            <option value="email">电子邮件验证码</option>
                            <option value="both">应用程序 + 备用方法</option>
                        </select>
                    </div>
                </div>

                <div class="mfa-status-list">
                    <div class="section-header" style="margin-top: 30px;">
                        <div class="section-icon">
                            <i class="fas fa-users"></i>
                        </div>
                        <div>
                            <div class="section-title">用户MFA状态</div>
                            <div class="section-subtitle">查看和管理所有用户的MFA状态</div>
                        </div>
                    </div>

                    <div id="mfaUserList">
                        <!-- MFA用户列表将通过JavaScript动态生成 -->
                    </div>
                </div>

                <div class="action-buttons" style="margin-top: 30px;">
                    <button class="btn btn-secondary" id="refreshMfaStatusBtn">
                        <i class="fas fa-sync-alt"></i> 刷新状态
                    </button>
                    <button class="btn btn-warning" id="enableAllMfaBtn">
                        <i class="fas fa-shield-alt"></i> 批量启用MFA
                    </button>
                    <button class="btn btn-primary" id="saveMfaSettingsBtn">
                        <i class="fas fa-save"></i> 保存设置
                    </button>
                </div>
            </div>

            <!-- 会话安全 -->
            <div class="module-card">
                <div class="module-header">
                    <div>
                        <div class="module-title">会话安全</div>
                        <div class="module-subtitle">设置登录失败锁定策略、会话超时时间，防止暴力破解</div>
                    </div>
                </div>

                <div class="form-container">
                    <div class="form-section">
                        <div class="section-header">
                            <div class="section-icon">
                                <i class="fas fa-user-lock"></i>
                            </div>
                            <div>
                                <div class="section-title">登录失败锁定</div>
                                <div class="section-subtitle">防止暴力破解攻击</div>
                            </div>
                        </div>

                        <div class="form-group">
                            <div class="checkbox-group">
                                <input type="checkbox" id="enableLockout" class="checkbox" checked>
                                <label for="enableLockout" class="checkbox-label">启用登录失败锁定功能</label>
                            </div>
                        </div>

                        <div class="form-group">
                            <label class="form-label" for="maxFailedAttempts">最大失败尝试次数</label>
                            <select class="select-control" id="maxFailedAttempts">
                                <option value="3">3次</option>
                                <option value="5" selected>5次</option>
                                <option value="10">10次</option>
                            </select>
                        </div>

                        <div class="form-group">
                            <label class="form-label" for="lockoutDuration">锁定持续时间</label>
                            <select class="select-control" id="lockoutDuration">
                                <option value="5">5分钟</option>
                                <option value="15" selected>15分钟</option>
                                <option value="30">30分钟</option>
                                <option value="60">60分钟</option>
                                <option value="1440">24小时</option>
                            </select>
                        </div>
                    </div>

                    <div class="form-section">
                        <div class="section-header">
                            <div class="section-icon">
                                <i class="fas fa-hourglass-half"></i>
                            </div>
                            <div>
                                <div class="section-title">会话超时设置</div>
                                <div class="section-subtitle">设置用户会话的超时时间</div>
                            </div>
                        </div>

                        <div class="form-group">
                            <label class="form-label" for="sessionTimeout">会话超时时间</label>
                            <select class="select-control" id="sessionTimeout">
                                <option value="15">15分钟</option>
                                <option value="30" selected>30分钟</option>
                                <option value="60">60分钟</option>
                                <option value="120">2小时</option>
                                <option value="480">8小时</option>
                            </select>
                        </div>

                        <div class="form-group">
                            <label class="form-label" for="sessionWarning">会话超时警告</label>
                            <select class="select-control" id="sessionWarning">
                                <option value="1">提前1分钟提醒</option>
                                <option value="5" selected>提前5分钟提醒</option>
                                <option value="10">提前10分钟提醒</option>
                            </select>
                        </div>

                        <div class="form-group">
                            <div class="checkbox-group">
                                <input type="checkbox" id="rememberMe" class="checkbox" checked>
                                <label for="rememberMe" class="checkbox-label">允许"记住我"功能延长会话</label>
                            </div>
                        </div>
                    </div>
                </div>

                <div class="action-buttons" style="margin-top: 30px; justify-content: flex-end;">
                    <button class="btn btn-secondary" id="resetSessionSettingsBtn">
                        <i class="fas fa-redo"></i> 恢复默认
                    </button>
                    <button class="btn btn-primary" id="saveSessionSettingsBtn">
                        <i class="fas fa-save"></i> 保存设置
                    </button>
                </div>
            </div>

            <!-- 密码修改 -->
            <div class="module-card">
                <div class="module-header">
                    <div>
                        <div class="module-title">密码修改</div>
                        <div class="module-subtitle">用户可随时修改密码，系统实时显示密码强度</div>
                    </div>
                </div>

                <div class="form-container">
                    <div class="form-section" style="grid-column: span 2;">
                        <div class="section-header">
                            <div class="section-icon">
                                <i class="fas fa-edit"></i>
                            </div>
                            <div>
                                <div class="section-title">修改当前用户密码</div>
                                <div class="section-subtitle">系统管理员 (刘贺)</div>
                            </div>
                        </div>

                        <div class="form-group">
                            <label class="form-label" for="currentPassword">当前密码</label>
                            <input type="password" class="form-control" id="currentPassword" placeholder="请输入当前密码">
                        </div>

                        <div class="form-group">
                            <label class="form-label" for="newPassword">新密码</label>
                            <input type="password" class="form-control" id="newPassword" placeholder="请输入新密码">
                            <div class="password-strength">
                                <div class="strength-bar">
                                    <div class="strength-fill" id="passwordStrengthBar"></div>
                                </div>
                                <div class="strength-text" id="passwordStrengthText">密码强度: 弱</div>
                            </div>
                        </div>

                        <div class="form-group">
                            <label class="form-label" for="confirmPassword">确认新密码</label>
                            <input type="password" class="form-control" id="confirmPassword" placeholder="请再次输入新密码">
                        </div>

                        <div class="action-buttons" style="margin-top: 20px;">
                            <button class="btn btn-primary" id="changePasswordBtn">
                                <i class="fas fa-key"></i> 修改密码
                            </button>
                        </div>
                    </div>
                </div>
            </div>

            <!-- 安全建议 -->
            <div class="info-box">
                <div class="info-title">
                    <i class="fas fa-lightbulb"></i>
                    安全建议
                </div>
                <div class="info-text">
                    <p>为确保系统安全性，建议遵循以下最佳实践：</p>
                    <ul class="info-list">
                        <li><strong>为管理员账户强制启用MFA</strong>：管理员账户权限较高，强制启用多因素认证可有效防止未授权访问。</li>
                        <li><strong>设置合理的密码过期策略</strong>：建议密码过期时间设置为60-90天，强制用户定期更换密码。</li>
                        <li><strong>启用登录失败锁定功能</strong>：防止暴力破解攻击，建议设置5次失败尝试后锁定账户15-30分钟。</li>
                        <li><strong>使用强密码策略</strong>：要求密码至少8位，包含大小写字母、数字和特殊字符。</li>
                        <li><strong>定期审计用户权限</strong>：定期检查用户权限分配，确保权限最小化原则。</li>
                        <li><strong>启用会话超时</strong>：设置适当的会话超时时间，建议30-60分钟，减少会话劫持风险。</li>
                    </ul>
                </div>
            </div>
        </div>
    </div>

    <script>
        // 目录结构数据
        const directoryData = [
            {
                id: "user-management",
