                icon: "fas fa-user-shield",
                expanded: true,
                subItems: [
                    { id: "role-access-control", title: "角色-权限-访问控制", icon: "fas fa-key" },
                    { id: "tenant-management", title: "租户管理", icon: "fas fa-building" },
                    { 
                        id: "login-security", 
