                            ${user.mfaEnabled ? '已启用' : '未启用'}
                        </span>
                        <button class="btn btn-secondary" style="margin-left: 10px; padding: 5px 10px;" data-user-id="${user.id}" data-action="toggle-mfa">
                            <i class="fas fa-${user.mfaEnabled ? 'ban' : 'check'}"></i>
                            ${user.mfaEnabled ? '禁用' : '启用'}
                        </button>
                    </div>
