            document.querySelectorAll('[data-action="toggle-mfa"]').forEach(button => {
                button.addEventListener('click', function() {
                    const userId = parseInt(this.getAttribute('data-user-id'));
                    const user = mfaUsers.find(u => u.id === userId);

                    if (user) {
                        user.mfaEnabled = !user.mfaEnabled;
                        initMfaUserList();

                        const action = user.mfaEnabled ? '启用' : '禁用';
                        showNotification(`已${action}用户 ${user.name} 的MFA功能`, 'success');
                    }
                });
            });
        }

        // 密码强度检测
        function checkPasswordStrength(password) {
            if (!password) {
                return { score: 0, text: '密码强度: 无', className: '' };
            }

            let score = 0;

            // 长度评分
            if (password.length >= 8) score += 1;
            if (password.length >= 12) score += 1;

            // 字符类型评分
            if (/[a-z]/.test(password)) score += 1;
            if (/[A-Z]/.test(password)) score += 1;
            if (/[0-9]/.test(password)) score += 1;
            if (/[^a-zA-Z0-9]/.test(password)) score += 1;

            let strengthText = '密码强度: ';
            let strengthClass = '';
            let percentage = 0;

            if (score <= 2) {
                strengthText += '弱';
                strengthClass = 'strength-weak';
                percentage = 33;
            } else if (score <= 4) {
                strengthText += '中';
                strengthClass = 'strength-medium';
                percentage = 66;
            } else {
                strengthText += '强';
                strengthClass = 'strength-strong';
                percentage = 100;
            }

            return {
                score: score,
                text: strengthText,
                className: strengthClass,
                percentage: percentage
            };
        }

        // 显示通知
        function showNotification(message, type = 'success') {
            // 创建通知元素
            const notification = document.createElement('div');
            notification.className = 'notification';

            // 设置背景颜色
            let bgColor = '#4CAF50'; // 默认成功色
            let icon = 'fas fa-check-circle';

            if (type === 'error') {
                bgColor = '#f44336';
                icon = 'fas fa-exclamation-circle';
            } else if (type === 'warning') {
                bgColor = '#ff9800';
                icon = 'fas fa-exclamation-triangle';
            } else if (type === 'info') {
                bgColor = '#2196F3';
                icon = 'fas fa-info-circle';
            }

            notification.style.backgroundColor = bgColor;

            notification.innerHTML = `
                <i class="${icon}"></i>
                <span>${message}</span>
            `;

            document.body.appendChild(notification);

            // 3秒后移除通知
            setTimeout(() => {
                notification.style.animation = 'slideOut 0.3s ease';
                setTimeout(() => {
                    if (notification.parentNode) {
                        notification.parentNode.removeChild(notification);
                    }
                }, 300);
            }, 3000);
        }

        // 绑定事件
        function bindEvents() {
            // 密码策略保存按钮
            document.getElementById('savePasswordPolicyBtn').addEventListener('click', function() {
                showNotification('密码策略设置已保存', 'success');
            });

            // 密码策略重置按钮
            document.getElementById('resetPasswordPolicyBtn').addEventListener('click', function() {
                // 重置所有复选框为选中状态
                document.querySelectorAll('#passwordPolicyForm input[type="checkbox"]').forEach(checkbox => {
                    checkbox.checked = true;
                });

                // 重置下拉框
                document.getElementById('expiryDays').value = '60';
                document.getElementById('historyCount').value = '5';
                document.getElementById('warningDays').value = '14';

                showNotification('已恢复默认密码策略', 'info');
            });

            // MFA设置保存按钮
            document.getElementById('saveMfaSettingsBtn').addEventListener('click', function() {
                showNotification('MFA设置已保存', 'success');
            });

            // 刷新MFA状态按钮
            document.getElementById('refreshMfaStatusBtn').addEventListener('click', function() {
                initMfaUserList();
                showNotification('MFA用户状态已刷新', 'success');
            });

            // 批量启用MFA按钮
            document.getElementById('enableAllMfaBtn').addEventListener('click', function() {
                mfaUsers.forEach(user => {
                    user.mfaEnabled = true;
                });
                initMfaUserList();
                showNotification('已为所有用户启用MFA', 'success');
            });

            // 会话设置保存按钮
            document.getElementById('saveSessionSettingsBtn').addEventListener('click', function() {
                showNotification('会话安全设置已保存', 'success');
            });

            // 会话设置重置按钮
            document.getElementById('resetSessionSettingsBtn').addEventListener('click', function() {
                document.getElementById('enableLockout').checked = true;
                document.getElementById('maxFailedAttempts').value = '5';
                document.getElementById('lockoutDuration').value = '15';
                document.getElementById('sessionTimeout').value = '30';
                document.getElementById('sessionWarning').value = '5';
                document.getElementById('rememberMe').checked = true;

                showNotification('已恢复默认会话设置', 'info');
            });

            // 修改密码按钮
            document.getElementById('changePasswordBtn').addEventListener('click', function() {
                const currentPassword = document.getElementById('currentPassword').value;
                const newPassword = document.getElementById('newPassword').value;
                const confirmPassword = document.getElementById('confirmPassword').value;

                if (!currentPassword) {
                    showNotification('请输入当前密码', 'error');
                    return;
                }

                if (!newPassword) {
                    showNotification('请输入新密码', 'error');
                    return;
                }

                if (newPassword !== confirmPassword) {
                    showNotification('两次输入的新密码不一致', 'error');
                    return;
                }

                const strength = checkPasswordStrength(newPassword);
                if (strength.score <= 2) {
                    showNotification('密码强度太弱，请使用更复杂的密码', 'warning');
                    return;
                }

                // 模拟密码修改成功
                document.getElementById('currentPassword').value = '';
                document.getElementById('newPassword').value = '';
                document.getElementById('confirmPassword').value = '';
                passwordStrengthBar.style.width = '0%';
                passwordStrengthBar.className = 'strength-fill';
                passwordStrengthText.textContent = '密码强度: 弱';

                showNotification('密码修改成功，新密码已生效', 'success');
            });

            // 密码强度实时检测
            newPasswordInput.addEventListener('input', function() {
                const password = this.value;
                const strength = checkPasswordStrength(password);

                passwordStrengthBar.style.width = `${strength.percentage}%`;
                passwordStrengthBar.className = `strength-fill ${strength.className}`;
                passwordStrengthText.textContent = strength.text;
            });

            // 移动端菜单切换
            mobileMenuToggle.addEventListener('click', () => {
                sidebar.classList.toggle('active');
            });

            // 窗口大小变化时调整侧边栏
            window.addEventListener('resize', () => {
                if (window.innerWidth > 992) {
                    sidebar.classList.remove('active');
                }
            });
        }

        // 初始化
        document.addEventListener('DOMContentLoaded', () => {
            initDirectoryTree();
            initMfaUserList();
            bindEvents();

            // 设置当前页面为"用户安全"
            pageTitle.textContent = '用户安全';
        });
    </script>
</body>
</html>
```

## 功能说明

这个用户安全页面实现了以下功能：

1. **整体架构**：与2.html保持一致的脚手架样式、图标和主题
2. **布局固定**：页面上下滑动时，顶部栏和左侧目录结构保持固定不动
3. **软件名称**：已按要求更改为"适配中心测试管理软件 V1.0"

4. **用户安全功能模块**：
   - **密码策略设置**：配置密码复杂度要求（最小长度、大小写字母、数字、特殊字符）、密码过期时间、重复使用限制等
   - **MFA管理**：查看用户MFA状态，支持批量启用/禁用多因素认证
   - **会话安全**：设置登录失败锁定策略（最大尝试次数、锁定时间）、会话超时时间
   - **密码修改**：用户可随时修改密码，系统实时显示密码强度

5. **交互功能**：
   - 实时密码强度检测
   - MFA状态切换
   - 配置保存与恢复默认
   - 操作成功/失败通知
   - 响应式设计，支持移动端

6. **安全建议**：页面底部提供了详细的安全建议，包括强制管理员启用MFA、设置合理密码过期策略等最佳实践。

页面默认选中"用户与权限管理" -> "登录与安全" -> "用户安全"目录项，左侧目录结构与2.html保持一致。

