        // 更新统计数据
        function updateStats() {
            const totalMembers = membersData.length;
            const managerCount = membersData.filter(m => m.role === 'manager').length;
            const engineerCount = membersData.filter(m => m.role === 'engineer').length;
            const activeMembers = membersData.filter(m => m.status === 'active').length;

