            document.getElementById('managerCount').textContent = managerCount;
            document.getElementById('engineerCount').textContent = engineerCount;
            document.getElementById('activeMembers').textContent = activeMembers;
        }

        // 应用筛选
        function applyFilters() {
            const projectFilter = document.getElementById('projectFilter').value;
            const roleFilter = document.getElementById('roleFilter').value;
            const statusFilter = document.getElementById('statusFilter').value;
            const searchInput = document.getElementById('searchInput').value.toLowerCase();

            filteredMembers = membersData.filter(member => {
                return (!projectFilter || member.project === projectFilter) &&
                       (!roleFilter || member.role === roleFilter) &&
                       (!statusFilter || member.status === statusFilter) &&
                       (!searchInput || 
                        member.name.toLowerCase().includes(searchInput) || 
                        member.employeeNo.toLowerCase().includes(searchInput) ||
                        member.email.toLowerCase().includes(searchInput));
            });

            currentPage = 1;
            renderMembersTable();
            renderPagination();
        }

        // 重置筛选
        function resetFilters() {
            document.getElementById('projectFilter').value = '';
            document.getElementById('roleFilter').value = '';
            document.getElementById('statusFilter').value = '';
            document.getElementById('searchInput').value = '';

            filteredMembers = [...membersData];
            currentPage = 1;
            renderMembersTable();
            renderPagination();
        }

        // 渲染成员表格
        function renderMembersTable() {
            const tableBody = document.getElementById('membersTableBody');
            const emptyState = document.getElementById('emptyState');

            if (filteredMembers.length === 0) {
                tableBody.innerHTML = '';
                emptyState.style.display = 'block';
                return;
            }

            emptyState.style.display = 'none';

            // 计算当前页的数据
            const startIndex = (currentPage - 1) * itemsPerPage;
            const endIndex = Math.min(startIndex + itemsPerPage, filteredMembers.length);
            const currentMembers = filteredMembers.slice(startIndex, endIndex);

            tableBody.innerHTML = '';

            currentMembers.forEach((member, index) => {
                // 确定角色徽章
                let roleBadgeClass = '';
                let roleText = '';
                switch(member.role) {
                    case 'manager':
                        roleBadgeClass = 'role-manager';
                        roleText = '项目经理';
                        break;
                    case 'engineer':
                        roleBadgeClass = 'role-engineer';
                        roleText = '测试工程师';
                        break;
                    case 'qa':
                        roleBadgeClass = 'role-qa';
                        roleText = '质量保障工程师';
                        break;
                    case 'observer':
                        roleBadgeClass = 'role-observer';
                        roleText = '观察员';
                        break;
                }

                // 确定状态徽章
                let statusBadgeClass = '';
                let statusText = '';
                switch(member.status) {
                    case 'active':
                        statusBadgeClass = 'status-active';
                        statusText = '活跃';
                        break;
                    case 'paused':
                        statusBadgeClass = 'status-paused';
                        statusText = '暂停';
                        break;
                    case 'inactive':
                        statusBadgeClass = 'status-inactive';
                        statusText = '未激活';
                        break;
                }

                // 项目名称映射
                let projectName = '';
                switch(member.project) {
                    case 'project1':
                        projectName = '智能调度系统V2.0';
                        break;
                    case 'project2':
                        projectName = '多平台适配引擎';
                        break;
                    case 'project3':
                        projectName = '数据可视化平台';
                        break;
                    case 'project4':
                        projectName = '安全测试框架';
                        break;
                    default:
                        projectName = member.project;
                }

                const row = document.createElement('tr');
                row.innerHTML = `
                    <td>${startIndex + index + 1}</td>
                    <td>
                        <div style="font-weight: 500;">${member.name}</div>
                        <div style="font-size: 12px; color: #666;">${projectName}</div>
                    </td>
                    <td>${member.employeeNo}</td>
                    <td>${member.email}</td>
                    <td><span class="role-badge ${roleBadgeClass}">${roleText}</span></td>
                    <td><span class="status-badge ${statusBadgeClass}">${statusText}</span></td>
                    <td>
                        <div class="action-cell">
                            <div class="action-icon edit-icon" data-id="${member.id}" title="编辑">
                                <i class="fas fa-edit"></i>
                            </div>
                            <div class="action-icon role-icon" data-id="${member.id}" title="调整角色">
                                <i class="fas fa-user-tag"></i>
                            </div>
                            <div class="action-icon status-icon" data-id="${member.id}" title="状态管理">
                                <i class="fas fa-user-slash"></i>
                            </div>
                            <div class="action-icon delete-icon" data-id="${member.id}" title="移除">
                                <i class="fas fa-trash"></i>
                            </div>
                        </div>
                    </td>
                `;

                tableBody.appendChild(row);
            });

            // 绑定表格操作按钮事件
