        // 保存成员
        function saveMember() {
            // 获取表单数据
            const name = document.getElementById('memberName').value.trim();
            const employeeNo = document.getElementById('employeeNo').value.trim();
            const email = document.getElementById('memberEmail').value.trim();
            const project = document.getElementById('memberProject').value;
            const role = document.getElementById('memberRole').value;
            const status = document.getElementById('memberStatus').value;
            const phone = document.getElementById('memberPhone').value.trim();
            const notes = document.getElementById('memberNotes').value.trim();

            // 简单验证
            if (!name || !employeeNo || !email || !project || !role || !status) {
                showNotification('请填写所有必填字段', 'warning');
                return;
            }

            // 邮箱格式验证
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (!emailRegex.test(email)) {
                showNotification('邮箱格式不正确', 'warning');
                return;
            }

            if (currentEditId) {
                // 编辑现有成员
                const index = membersData.findIndex(m => m.id === currentEditId);
                if (index !== -1) {
                    // 检查工号是否重复（排除当前编辑的成员）
                    const duplicate = membersData.find(m => m.employeeNo === employeeNo && m.id !== currentEditId);
                    if (duplicate) {
                        showNotification('工号已存在，请使用其他工号', 'warning');
                        return;
                    }

                    membersData[index] = {
                        ...membersData[index],
                        name,
                        employeeNo,
                        email,
                        project,
                        role,
                        status,
                        phone,
                        notes
                    };

                    showNotification('成员信息已更新', 'success');
                }
            } else {
                // 添加新成员
                // 检查工号是否重复
                const duplicate = membersData.find(m => m.employeeNo === employeeNo);
                if (duplicate) {
                    showNotification('工号已存在，请使用其他工号', 'warning');
                    return;
                }

                // 生成新ID
                const newId = membersData.length > 0 ? Math.max(...membersData.map(m => m.id)) + 1 : 1;

                membersData.push({
                    id: newId,
                    name,
                    employeeNo,
                    email,
                    project,
                    role,
                    status,
                    phone,
                    notes
                });

                showNotification('成员添加成功', 'success');
            }

            // 关闭模态框
            memberModal.classList.remove('active');

            // 更新页面
            applyFilters();
            updateStats();
        }

        // 调整角色
        function adjustRole(memberId) {
            const member = membersData.find(m => m.id === memberId);
            if (!member) return;

            const newRole = prompt(`请为 ${member.name} 选择新角色:\n1. 项目经理\n2. 测试工程师\n3. 质量保障工程师\n4. 观察员`, 
                member.role === 'manager' ? '1' : 
                member.role === 'engineer' ? '2' : 
                member.role === 'qa' ? '3' : '4');

            let roleValue = '';
            switch(newRole) {
                case '1': roleValue = 'manager'; break;
                case '2': roleValue = 'engineer'; break;
                case '3': roleValue = 'qa'; break;
                case '4': roleValue = 'observer'; break;
                default: return;
            }

            // 更新角色
            member.role = roleValue;

            // 如果是项目经理，需要确认
            if (roleValue === 'manager') {
                if (!confirm(`确定将 ${member.name} 设置为项目经理吗？项目经理拥有最高管理权限。`)) {
                    return;
                }
            }

            showNotification(`已更新 ${member.name} 的角色`, 'success');
            applyFilters();
            updateStats();
        }

        // 管理状态
        function manageStatus(memberId) {
            const member = membersData.find(m => m.id === memberId);
            if (!member) return;

            const newStatus = prompt(`请为 ${member.name} 选择新状态:\n1. 活跃\n2. 暂停\n3. 未激活`, 
                member.status === 'active' ? '1' : 
                member.status === 'paused' ? '2' : '3');

            let statusValue = '';
            switch(newStatus) {
                case '1': statusValue = 'active'; break;
                case '2': statusValue = 'paused'; break;
                case '3': statusValue = 'inactive'; break;
                default: return;
            }

            // 更新状态
            member.status = statusValue;

            showNotification(`已更新 ${member.name} 的状态`, 'success');
            applyFilters();
            updateStats();
        }

        // 移除成员
        function removeMember(memberId) {
            const member = membersData.find(m => m.id === memberId);
            if (!member) return;

            // 检查是否有未完成任务（模拟）
            const hasPendingTasks = Math.random() > 0.5;

            if (hasPendingTasks) {
                alert(`无法移除 ${member.name}，该成员仍有未完成任务。请先处理完所有待办事项后再尝试移除。`);
                return;
            }

            if (confirm(`确定要移除成员 ${member.name} 吗？此操作不可恢复。`)) {
                // 从数据中移除
                membersData = membersData.filter(m => m.id !== memberId);

                showNotification(`已移除成员 ${member.name}`, 'success');
                applyFilters();
                updateStats();
            }
        }

        // 打开批量添加模态框
        function openBatchModal() {
            batchModal.classList.add('active');
        }

        // 批量导入处理
        function handleBatchImport() {
            const project = document.getElementById('batchProject').value;

            if (!project) {
                showNotification('请选择目标项目', 'warning');
                return;
            }

            // 模拟批量导入过程
            showNotification('正在导入成员数据...', 'success');

            setTimeout(() => {
                // 模拟添加一些新成员
                const newMembers = [
                    { id: membersData.length + 1, name: "周杰", employeeNo: "CS013", email: "zhoujie@chinasofti.com", project, role: "engineer", status: "active", phone: "13800138013", notes: "新入职测试工程师" },
                    { id: membersData.length + 2, name: "林涛", employeeNo: "CS014", email: "lintao@chinasofti.com", project, role: "engineer", status: "active", phone: "13800138014", notes: "新入职测试工程师" },
                    { id: membersData.length + 3, name: "徐静", employeeNo: "CS015", email: "xujing@chinasofti.com", project, role: "qa", status: "active", phone: "13800138015", notes: "新入职质量工程师" }
                ];

                membersData.push(...newMembers);

                showNotification(`成功导入 ${newMembers.length} 名成员`, 'success');

                // 关闭模态框
                batchModal.classList.remove('active');

                // 重置批量导入表单
                document.getElementById('batchProject').value = '';
                document.getElementById('selectedFileName').textContent = '';
                document.getElementById('batchPreview').style.display = 'none';
                document.getElementById('confirmBatchBtn').disabled = true;

                // 更新页面
                applyFilters();
                updateStats();
            }, 1500);
        }

        // 导出成员数据
        function exportMembers() {
            // 模拟导出过程
            showNotification('正在导出成员数据...', 'success');

            setTimeout(() => {
                showNotification('成员数据已导出为Excel文件', 'success');
            }, 1000);
        }

        // 显示通知
        function showNotification(message, type = 'success') {
            // 移除现有的通知
            const existingNotification = document.querySelector('.notification');
            if (existingNotification) {
                existingNotification.remove();
            }

            // 创建通知元素
            const notification = document.createElement('div');
            notification.className = `notification ${type}`;
            notification.innerHTML = `
                <i class="fas fa-${type === 'success' ? 'check-circle' : type === 'warning' ? 'exclamation-triangle' : 'exclamation-circle'}"></i>
                <span>${message}</span>
            `;

            document.body.appendChild(notification);

            // 3秒后移除通知
            setTimeout(() => {
                notification.style.animation = 'slideOut 0.3s ease';
                setTimeout(() => {
                    if (notification.parentNode) {
                        notification.parentNode.removeChild(notification);
                    }
                }, 300);
            }, 3000);
        }

        // 绑定事件
        function bindEvents() {
            // 添加成员按钮
            addMemberBtn.addEventListener('click', openAddMemberModal);

            // 批量添加按钮
            batchAddBtn.addEventListener('click', openBatchModal);

            // 导出按钮
            exportMembersBtn.addEventListener('click', exportMembers);

            // 筛选按钮
            applyFiltersBtn.addEventListener('click', applyFilters);

            // 重置按钮
            resetFiltersBtn.addEventListener('click', resetFilters);

            // 搜索输入框（实时筛选）
            document.getElementById('searchInput').addEventListener('input', debounce(applyFilters, 300));

            // 成员模态框
            closeMemberModalBtn.addEventListener('click', () => memberModal.classList.remove('active'));
            cancelMemberBtn.addEventListener('click', () => memberModal.classList.remove('active'));
            saveMemberBtn.addEventListener('click', saveMember);

            // 批量导入模态框
            closeBatchModalBtn.addEventListener('click', () => batchModal.classList.remove('active'));
            cancelBatchBtn.addEventListener('click', () => batchModal.classList.remove('active'));
            confirmBatchBtn.addEventListener('click', handleBatchImport);

            // 文件选择
            selectFileBtn.addEventListener('click', () => batchFileInput.click());
            batchFileInput.addEventListener('change', function(e) {
                const file = e.target.files[0];
                if (file) {
                    document.getElementById('selectedFileName').textContent = `已选择: ${file.name}`;
                    document.getElementById('confirmBatchBtn').disabled = false;

                    // 显示预览（模拟）
                    document.getElementById('batchPreview').style.display = 'block';
                    document.getElementById('batchPreviewBody').innerHTML = `
                        <tr><td>周杰</td><td>CS013</td><td>zhoujie@chinasofti.com</td><td>测试工程师</td></tr>
                        <tr><td>林涛</td><td>CS014</td><td>lintao@chinasofti.com</td><td>测试工程师</td></tr>
                        <tr><td>徐静</td><td>CS015</td><td>xujing@chinasofti.com</td><td>质量保障工程师</td></tr>
                        <tr><td>黄伟</td><td>CS016</td><td>huangwei@chinasofti.com</td><td>测试工程师</td></tr>
                        <tr><td>杨帆</td><td>CS017</td><td>yangfan@chinasofti.com</td><td>观察员</td></tr>
                    `;
                    document.getElementById('totalRows').textContent = '8';
                }
            });

            // 下载模板
            downloadTemplateBtn.addEventListener('click', (e) => {
                e.preventDefault();
                showNotification('模板文件下载开始', 'success');
            });

            // 移动端菜单切换
            mobileMenuToggle.addEventListener('click', () => {
                sidebar.classList.toggle('active');
            });

            // 窗口大小变化时调整侧边栏
            window.addEventListener('resize', () => {
                if (window.innerWidth > 992) {
                    sidebar.classList.remove('active');
                }
            });

            // 点击模态框外部关闭
            memberModal.addEventListener('click', (e) => {
                if (e.target === memberModal) {
                    memberModal.classList.remove('active');
                }
            });

            batchModal.addEventListener('click', (e) => {
                if (e.target === batchModal) {
                    batchModal.classList.remove('active');
                }
            });

            // 按ESC键关闭模态框
            document.addEventListener('keydown', (e) => {
                if (e.key === 'Escape') {
                    memberModal.classList.remove('active');
                    batchModal.classList.remove('active');
                }
            });
        }

        // 防抖函数
        function debounce(func, wait) {
            let timeout;
            return function executedFunction(...args) {
                const later = () => {
                    clearTimeout(timeout);
                    func(...args);
                };
                clearTimeout(timeout);
                timeout = setTimeout(later, wait);
            };
        }

        // 初始化
        document.addEventListener('DOMContentLoaded', () => {
            initDirectoryTree();
            initProjectMemberPage();
        });
    </script>
</body>
</html>
