            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            transition: all 0.2s ease;
        }

        .edit-icon {
            background-color: #e8f4ff;
            color: #1a3a8f;
        }

        .edit-icon:hover {
            background-color: #d0e3ff;
        }

        .delete-icon {
            background-color: #fee;
            color: #dc2626;
        }

        .delete-icon:hover {
            background-color: #fdd;
        }

        .view-icon {
            background-color: #e6f7ed;
            color: #0c7c42;
        }

        .view-icon:hover {
            background-color: #d4f1e2;
        }

        /* 分页样式 */
        .pagination-container {
            display: flex;
            justify-content: center;
            align-items: center;
            margin-top: 30px;
            padding-top: 20px;
            border-top: 1px solid #eee;
        }

        .pagination {
            display: flex;
            list-style: none;
            gap: 5px;
        }

        .page-item {
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .page-link {
            width: 40px;
            height: 40px;
            display: flex;
            align-items: center;
            justify-content: center;
            border-radius: 6px;
            background-color: white;
            border: 1px solid #ddd;
            color: #555;
            text-decoration: none;
            cursor: pointer;
            transition: all 0.2s ease;
        }

        .page-link:hover {
            background-color: #f0f5ff;
            border-color: #1a3a8f;
            color: #1a3a8f;
        }

        .page-link.active {
            background-color: #1a3a8f;
            border-color: #1a3a8f;
            color: white;
        }

        .page-link.disabled {
            background-color: #f5f5f5;
            color: #999;
            cursor: not-allowed;
        }

        .pagination-info {
            margin-left: 20px;
            color: #666;
            font-size: 14px;
        }

        /* 统计卡片 */
        .stats-container {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
            gap: 20px;
            margin-bottom: 30px;
        }

        .stat-card {
            background-color: white;
            border-radius: 10px;
            padding: 20px;
            box-shadow: 0 3px 10px rgba(0, 0, 0, 0.05);
            border-left: 4px solid #1a3a8f;
        }

        .stat-title {
            font-size: 14px;
            color: #666;
            margin-bottom: 10px;
        }

        .stat-value {
            font-size: 28px;
            font-weight: 600;
            color: #1a3a8f;
        }

        .stat-trend {
            font-size: 12px;
            margin-top: 5px;
        }

        .trend-up {
            color: #059669;
        }

        .trend-down {
            color: #dc2626;
        }

        /* 模态框样式 */
        .modal-overlay {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background-color: rgba(0, 0, 0, 0.5);
            display: flex;
            align-items: center;
            justify-content: center;
            z-index: 100;
            opacity: 0;
            visibility: hidden;
            transition: all 0.3s ease;
        }

        .modal-overlay.active {
            opacity: 1;
            visibility: visible;
        }

        .modal {
            background-color: white;
            border-radius: 12px;
            width: 800px;
            max-width: 90%;
            max-height: 90vh;
            overflow-y: auto;
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
            transform: translateY(20px);
            transition: transform 0.3s ease;
        }

        .modal-overlay.active .modal {
            transform: translateY(0);
        }

        .modal-header {
            padding: 25px 30px;
            border-bottom: 1px solid #eee;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .modal-title {
            font-size: 20px;
            font-weight: 600;
            color: #1a3a8f;
        }

        .modal-close {
            background: none;
            border: none;
            font-size: 20px;
            cursor: pointer;
            color: #999;
            transition: color 0.2s;
        }

        .modal-close:hover {
            color: #333;
        }

        .modal-body {
            padding: 30px;
        }

        .form-group {
            margin-bottom: 20px;
        }

        .form-label {
            display: block;
            margin-bottom: 8px;
            font-weight: 500;
            color: #555;
        }

        .form-control {
            width: 100%;
            padding: 12px 15px;
            border: 1px solid #ddd;
            border-radius: 6px;
            font-size: 15px;
            transition: border 0.2s;
        }

        .form-control:focus {
            outline: none;
            border-color: #1a3a8f;
            box-shadow: 0 0 0 3px rgba(26, 58, 143, 0.1);
        }

        .select-control {
            width: 100%;
            padding: 12px 15px;
            border: 1px solid #ddd;
            border-radius: 6px;
            font-size: 15px;
            background-color: white;
            transition: border 0.2s;
        }

        .modal-footer {
            padding: 20px 30px;
            border-top: 1px solid #eee;
            display: flex;
            justify-content: flex-end;
            gap: 15px;
        }

        /* 测试步骤样式 */
        .test-steps-container {
            margin-top: 15px;
            border: 1px solid #eee;
            border-radius: 8px;
            padding: 20px;
            background-color: #f9fafc;
        }

        .step-item {
            display: flex;
            gap: 15px;
            margin-bottom: 20px;
            padding-bottom: 20px;
            border-bottom: 1px solid #eee;
        }

        .step-item:last-child {
            margin-bottom: 0;
            padding-bottom: 0;
            border-bottom: none;
        }

        .step-number {
            width: 40px;
            height: 40px;
            border-radius: 50%;
            background-color: #1a3a8f;
            color: white;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: 600;
            flex-shrink: 0;
        }

        .step-content {
            flex-grow: 1;
        }

        .step-actions {
            display: flex;
            gap: 10px;
            flex-shrink: 0;
        }

        .step-action-btn {
            width: 32px;
            height: 32px;
            border-radius: 6px;
            display: flex;
            align-items: center;
            justify-content: center;
            background-color: #e8f4ff;
            color: #1a3a8f;
            border: none;
            cursor: pointer;
            transition: all 0.2s ease;
        }

        .step-action-btn:hover {
            background-color: #d0e3ff;
        }

        .step-action-btn.delete {
            background-color: #fee;
            color: #dc2626;
        }

        .step-action-btn.delete:hover {
            background-color: #fdd;
        }

        /* 过滤器 */
        .filter-container {
            background-color: #f8fafd;
            border-radius: 8px;
            padding: 20px;
            margin-bottom: 20px;
            display: flex;
            flex-wrap: wrap;
            gap: 15px;
            align-items: flex-end;
        }

        .filter-group {
            flex: 1;
            min-width: 150px;
        }

        .filter-label {
            display: block;
            margin-bottom: 8px;
            font-size: 14px;
            font-weight: 500;
            color: #555;
        }

        .export-buttons {
            display: flex;
            gap: 10px;
        }

        /* 标签样式 */
        .tags-container {
            display: flex;
            flex-wrap: wrap;
            gap: 8px;
            margin-top: 10px;
        }

        .tag {
            padding: 5px 10px;
            background-color: #e8f4ff;
            color: #1a3a8f;
            border-radius: 15px;
            font-size: 13px;
            display: flex;
            align-items: center;
            gap: 5px;
        }

        .tag-remove {
            cursor: pointer;
            font-size: 12px;
        }

        /* 响应式设计 */
        @media (max-width: 1200px) {
            .sidebar {
                width: 250px;
            }

            .main-content {
                margin-left: 250px;
                width: calc(100% - 250px);
            }
        }

        @media (max-width: 992px) {
            .sidebar {
                position: fixed;
                left: -280px;
                transition: left 0.3s ease;
            }

            .sidebar.active {
                left: 0;
            }

            .main-content {
                margin-left: 0;
                width: 100%;
            }

            .mobile-menu-toggle {
                display: flex;
            }

            .stats-container {
                grid-template-columns: repeat(2, 1fr);
            }
        }

        .mobile-menu-toggle {
            display: none;
            background: none;
            border: none;
            font-size: 20px;
            color: #1a3a8f;
            cursor: pointer;
        }

        @media (max-width: 768px) {
            .stats-container {
                grid-template-columns: 1fr;
            }

            .content-area {
                padding: 15px;
            }

            .module-card {
                padding: 20px;
            }

            .action-buttons {
                flex-wrap: wrap;
            }
        }

        /* 空状态 */
        .empty-state {
            text-align: center;
            padding: 60px 20px;
            color: #999;
        }

        .empty-state i {
            font-size: 50px;
            margin-bottom: 20px;
            opacity: 0.5;
        }

        .empty-state h3 {
            font-size: 18px;
            margin-bottom: 10px;
            color: #666;
        }

        /* 文件上传样式 */
        .file-upload-container {
            border: 2px dashed #ddd;
            border-radius: 8px;
            padding: 40px 20px;
            text-align: center;
            background-color: #f9fafc;
            cursor: pointer;
            transition: all 0.3s ease;
        }

        .file-upload-container:hover {
            border-color: #1a3a8f;
            background-color: #f0f5ff;
        }

        .file-upload-container i {
            font-size: 40px;
            color: #1a3a8f;
            margin-bottom: 15px;
        }

        /* 表单行布局 */
        .form-row {
            display: flex;
            gap: 20px;
            margin-bottom: 20px;
        }

        .form-row .form-group {
            flex: 1;
            margin-bottom: 0;
        }
    </style>
</head>
<body>
    <!-- 左侧导航栏 -->
    <div class="sidebar" id="sidebar">
        <div class="logo-container">
            <div class="logo">
                <i class="fas fa-cogs"></i>
            </div>
            <div class="logo-text">
                <h1>适配中心测试管理软件</h1>
                <p>V1.0</p>
            </div>
        </div>

        <div class="directory-container">
            <div class="directory-title">功能目录</div>
            <ul class="directory-tree" id="directoryTree">
                <!-- 目录树将通过JavaScript动态生成 -->
            </ul>
        </div>
    </div>

    <!-- 右侧主内容区 -->
    <div class="main-content">
        <div class="top-bar">
            <button class="mobile-menu-toggle" id="mobileMenuToggle">
                <i class="fas fa-bars"></i>
            </button>
            <div class="page-title" id="pageTitle">测试用例创建与维护</div>
            <div class="user-info">
                <div class="user-avatar">刘</div>
                <div>
                    <div style="font-weight: 500;">刘贺</div>
                    <div style="font-size: 13px; color: #666;">项目经理</div>
                </div>
            </div>
        </div>

        <div class="content-area" id="contentArea">
            <!-- 统计卡片 -->
            <div class="stats-container">
                <div class="stat-card">
                    <div class="stat-title">总用例数</div>
                    <div class="stat-value" id="totalTestCases">856</div>
                    <div class="stat-trend trend-up">较上周 ↑ 8%</div>
                </div>
                <div class="stat-card">
                    <div class="stat-title">待评审用例</div>
                    <div class="stat-value" id="pendingReviewCases">42</div>
                    <div class="stat-trend trend-down">较上周 ↓ 5%</div>
                </div>
                <div class="stat-card">
                    <div class="stat-title">高优先级用例</div>
                    <div class="stat-value" id="highPriorityCases">156</div>
                    <div class="stat-trend trend-up">较上周 ↑ 12%</div>
                </div>
                <div class="stat-card">
                    <div class="stat-title">本月新增用例</div>
                    <div class="stat-value" id="newCasesThisMonth">89</div>
                    <div class="stat-trend trend-up">较上月 ↑ 15%</div>
                </div>
            </div>

            <!-- 测试用例创建与维护模块 -->
            <div class="module-card" id="testCaseCard">
                <div class="module-header">
                    <div>
                        <div class="module-title">测试用例创建与维护</div>
                        <div class="module-subtitle">支持用例创建、编辑、批量导入导出、筛选搜索和分页管理</div>
                    </div>
                    <div class="action-buttons">
                        <button class="btn btn-primary" id="createTestCaseBtn">
                            <i class="fas fa-plus-circle"></i> 创建用例
                        </button>
                        <button class="btn btn-secondary" id="importTestCasesBtn">
                            <i class="fas fa-file-import"></i> 批量导入
                        </button>
                        <button class="btn btn-success" id="exportTestCasesBtn">
                            <i class="fas fa-file-export"></i> 导出用例
                        </button>
                    </div>
                </div>

                <!-- 过滤器 -->
                <div class="filter-container">
                    <div class="filter-group">
                        <label class="filter-label">优先级</label>
                        <select class="select-control" id="priorityFilter">
                            <option value="">全部</option>
                            <option value="1">低</option>
                            <option value="2">中</option>
                            <option value="3">高</option>
                            <option value="4">紧急</option>
                        </select>
                    </div>
                    <div class="filter-group">
                        <label class="filter-label">用例类型</label>
                        <select class="select-control" id="typeFilter">
                            <option value="">全部</option>
                            <option value="1">功能测试</option>
                            <option value="2">性能测试</option>
                            <option value="3">安全测试</option>
                            <option value="4">兼容性测试</option>
                            <option value="5">回归测试</option>
                        </select>
                    </div>
                    <div class="filter-group">
                        <label class="filter-label">状态</label>
                        <select class="select-control" id="statusFilter">
                            <option value="">全部</option>
                            <option value="0">草稿</option>
                            <option value="1">评审中</option>
                            <option value="2">已评审</option>
                            <option value="3">已归档</option>
                            <option value="4">已废弃</option>
                        </select>
                    </div>
                    <div class="filter-group">
                        <label class="filter-label">关键词搜索</label>
                        <input type="text" class="form-control" id="keywordSearch" placeholder="用例名称/编号/描述">
                    </div>
                    <div class="export-buttons">
                        <button class="btn btn-secondary" id="applyFiltersBtn">
                            <i class="fas fa-filter"></i> 筛选
                        </button>
                        <button class="btn btn-secondary" id="resetFiltersBtn">
                            <i class="fas fa-redo"></i> 重置
                        </button>
                    </div>
                </div>

                <!-- 测试用例列表表格 -->
                <div class="table-container">
                    <table id="testCasesTable">
                        <thead>
                            <tr>
                                <th width="8%">用例编号</th>
                                <th width="25%">用例名称</th>
                                <th width="10%">优先级</th>
                                <th width="12%">用例类型</th>
                                <th width="10%">状态</th>
                                <th width="15%">所属模块</th>
                                <th width="10%">创建人</th>
                                <th width="10%">操作</th>
                            </tr>
                        </thead>
                        <tbody id="testCasesTableBody">
                            <!-- 表格数据将通过JavaScript动态生成 -->
                        </tbody>
                    </table>
                </div>

                <!-- 分页组件 -->
                <div class="pagination-container">
                    <ul class="pagination" id="pagination">
                        <!-- 分页按钮将通过JavaScript动态生成 -->
                    </ul>
                    <div class="pagination-info" id="paginationInfo">
                        显示 1-10 条，共 856 条
                    </div>
                </div>

                <!-- 空状态 -->
                <div class="empty-state" id="emptyState" style="display: none;">
                    <i class="fas fa-book"></i>
                    <h3>暂无测试用例数据</h3>
                    <p>当前筛选条件下未找到测试用例记录</p>
                </div>
            </div>

            <!-- 注意事项卡片 -->
            <div class="module-card">
                <div class="module-header">
                    <div class="module-title">注意事项</div>
                </div>
                <div style="line-height: 1.6;">
                    <ul style="margin-top: 15px; padding-left: 20px;">
                        <li style="margin-bottom: 10px;"><strong>用例编号需唯一</strong>：系统自动生成唯一用例编号，确保每个用例有唯一标识</li>
                        <li style="margin-bottom: 10px;"><strong>测试步骤管理</strong>：测试步骤支持添加、排序和删除，可设置预期结果</li>
                        <li style="margin-bottom: 10px;"><strong>标签分类</strong>：可为用例添加多个标签，便于后续分类检索和筛选</li>
                        <li style="margin-bottom: 10px;"><strong>分页控件</strong>：分页控件显示当前数据范围和总记录数，支持跳转至任意页</li>
                        <li style="margin-bottom: 10px;"><strong>批量操作</strong>：支持Excel/CSV文件批量导入和JSON格式批量导出</li>
                    </ul>
                </div>
            </div>
        </div>
    </div>

    <!-- 创建/编辑测试用例模态框 -->
    <div class="modal-overlay" id="testCaseModal">
        <div class="modal">
            <div class="modal-header">
                <div class="modal-title" id="modalTitle">创建测试用例</div>
                <button class="modal-close" id="closeTestCaseModalBtn">
                    <i class="fas fa-times"></i>
                </button>
            </div>
            <div class="modal-body">
                <form id="testCaseForm">
                    <div class="form-row">
                        <div class="form-group">
                            <label class="form-label" for="caseCode">用例编号</label>
                            <input type="text" class="form-control" id="caseCode" placeholder="系统自动生成" readonly>
                        </div>
                        <div class="form-group">
                            <label class="form-label" for="caseName">用例名称 <span style="color: red;">*</span></label>
                            <input type="text" class="form-control" id="caseName" placeholder="请输入用例名称" required>
                        </div>
                    </div>

                    <div class="form-group">
                        <label class="form-label" for="caseDescription">用例描述</label>
                        <textarea class="form-control" id="caseDescription" rows="3" placeholder="请输入用例描述"></textarea>
                    </div>

                    <div class="form-row">
                        <div class="form-group">
                            <label class="form-label" for="casePriority">优先级 <span style="color: red;">*</span></label>
                            <select class="select-control" id="casePriority" required>
                                <option value="">请选择优先级</option>
                                <option value="1">低</option>
                                <option value="2">中</option>
                                <option value="3">高</option>
                                <option value="4">紧急</option>
                            </select>
                        </div>
                        <div class="form-group">
                            <label class="form-label" for="caseType">用例类型 <span style="color: red;">*</span></label>
                            <select class="select-control" id="caseType" required>
                                <option value="">请选择用例类型</option>
                                <option value="1">功能测试</option>
                                <option value="2">性能测试</option>
                                <option value="3">安全测试</option>
                                <option value="4">兼容性测试</option>
                                <option value="5">回归测试</option>
                            </select>
                        </div>
                    </div>

                    <div class="form-group">
                        <label class="form-label" for="caseModule">所属模块 <span style="color: red;">*</span></label>
                        <select class="select-control" id="caseModule" required>
                            <option value="">请选择所属模块</option>
                            <option value="user-management">用户管理</option>
                            <option value="project-management">项目管理</option>
                            <option value="test-case">测试用例管理</option>
                            <option value="task-management">任务管理</option>
                            <option value="report-visualization">报表可视化</option>
                        </select>
                    </div>

                    <div class="form-group">
                        <label class="form-label">测试步骤 <span style="color: red;">*</span></label>
                        <div class="test-steps-container" id="testStepsContainer">
                            <!-- 测试步骤将通过JavaScript动态添加 -->
                        </div>
                        <button type="button" class="btn btn-secondary" id="addStepBtn" style="margin-top: 15px;">
                            <i class="fas fa-plus"></i> 添加测试步骤
                        </button>
                    </div>

                    <div class="form-group">
                        <label class="form-label" for="precondition">前置条件</label>
                        <textarea class="form-control" id="precondition" rows="2" placeholder="请输入测试前置条件"></textarea>
                    </div>

                    <div class="form-group">
                        <label class="form-label" for="expectedResult">预期结果 <span style="color: red;">*</span></label>
                        <textarea class="form-control" id="expectedResult" rows="3" placeholder="请输入预期结果" required></textarea>
                    </div>

                    <div class="form-group">
                        <label class="form-label" for="caseTags">标签</label>
                        <input type="text" class="form-control" id="caseTags" placeholder="输入标签后按回车添加（如：登录,安全,兼容性）">
                        <div class="tags-container" id="tagsContainer">
                            <!-- 标签将通过JavaScript动态添加 -->
                        </div>
                    </div>
                </form>
            </div>
            <div class="modal-footer">
                <button class="btn btn-secondary" id="cancelTestCaseBtn">取消</button>
                <button class="btn btn-primary" id="saveTestCaseBtn">保存用例</button>
            </div>
        </div>
    </div>

    <!-- 批量导入模态框 -->
    <div class="modal-overlay" id="importModal">
        <div class="modal">
            <div class="modal-header">
                <div class="modal-title">批量导入测试用例</div>
                <button class="modal-close" id="closeImportModalBtn">
                    <i class="fas fa-times"></i>
                </button>
            </div>
            <div class="modal-body">
                <div class="file-upload-container" id="fileUploadContainer">
