        // 应用筛选
        function applyFilters() {
            const priorityFilter = document.getElementById('priorityFilter').value;
            const typeFilter = document.getElementById('typeFilter').value;
            const statusFilter = document.getElementById('statusFilter').value;
            const keywordSearch = document.getElementById('keywordSearch').value.toLowerCase();

            filteredTestCases = testCasesData.filter(testCase => {
                const matchesPriority = !priorityFilter || testCase.priority == priorityFilter;
                const matchesType = !typeFilter || testCase.type == typeFilter;
                const matchesStatus = !statusFilter || testCase.status == statusFilter;
                const matchesKeyword = !keywordSearch || 
                    testCase.caseCode.toLowerCase().includes(keywordSearch) ||
                    testCase.caseName.toLowerCase().includes(keywordSearch) ||
                    testCase.description.toLowerCase().includes(keywordSearch);

                return matchesPriority && matchesType && matchesStatus && matchesKeyword;
            });

            currentPage = 1;
            renderTestCasesTable();
            renderPagination();
        }

        // 重置筛选
        function resetFilters() {
            document.getElementById('priorityFilter').value = '';
            document.getElementById('typeFilter').value = '';
            document.getElementById('statusFilter').value = '';
            document.getElementById('keywordSearch').value = '';

            filteredTestCases = [...testCasesData];
            currentPage = 1;
            renderTestCasesTable();
            renderPagination();
        }

        // 渲染测试用例表格
        function renderTestCasesTable() {
            const tableBody = document.getElementById('testCasesTableBody');
            const emptyState = document.getElementById('emptyState');

            if (filteredTestCases.length === 0) {
                tableBody.innerHTML = '';
                emptyState.style.display = 'block';
                return;
            }

            emptyState.style.display = 'none';

            // 计算当前页的数据
            const startIndex = (currentPage - 1) * itemsPerPage;
            const endIndex = Math.min(startIndex + itemsPerPage, filteredTestCases.length);
            const currentTestCases = filteredTestCases.slice(startIndex, endIndex);

            tableBody.innerHTML = '';

            currentTestCases.forEach(testCase => {
                // 确定优先级徽章
                let priorityBadgeClass = '';
                let priorityText = '';
                switch(testCase.priority) {
                    case 1:
                        priorityBadgeClass = 'priority-p4';
                        priorityText = '低';
                        break;
                    case 2:
                        priorityBadgeClass = 'priority-p3';
                        priorityText = '中';
                        break;
                    case 3:
                        priorityBadgeClass = 'priority-p2';
                        priorityText = '高';
                        break;
                    case 4:
                        priorityBadgeClass = 'priority-p1';
                        priorityText = '紧急';
                        break;
                }

                // 确定类型徽章
