                        typeText = '功能测试';
                        break;
                    case 2:
                        typeBadgeClass = 'type-performance';
                        typeText = '性能测试';
                        break;
                    case 3:
                        typeBadgeClass = 'type-security';
                        typeText = '安全测试';
                        break;
                    case 4:
                        typeBadgeClass = 'type-compatibility';
                        typeText = '兼容性测试';
                        break;
                    case 5:
                        typeBadgeClass = 'type-regression';
                        typeText = '回归测试';
                        break;
                }

                // 确定状态徽章
