                let statusText = '';
                switch(testCase.status) {
                    case 0:
                        statusBadgeClass = 'status-draft';
                        statusText = '草稿';
                        break;
                    case 1:
                        statusBadgeClass = 'status-review';
                        statusText = '评审中';
                        break;
                    case 2:
                        statusBadgeClass = 'status-reviewed';
                        statusText = '已评审';
                        break;
                    case 3:
                        statusBadgeClass = 'status-archived';
                        statusText = '已归档';
                        break;
