                        break;
                    case 'system-integration':
                        moduleName = '系统集成';
                        break;
                    case 'system-management':
                        moduleName = '系统管理';
                        break;
                    default:
                        moduleName = testCase.module;
                }

                // 标签显示
                let tagsHtml = '';
