                    <td>${testCase.caseCode}</td>
                    <td>
                        <div style="font-weight: 500;">${testCase.caseName}</div>
                        <div style="font-size: 13px; color: #666; margin-top: 5px;">${testCase.description.substring(0, 50)}${testCase.description.length > 50 ? '...' : ''}</div>
                        <div class="tags-container" style="margin-top: 5px;">${tagsHtml}</div>
                    </td>
                    <td><span class="priority-badge ${priorityBadgeClass}">${priorityText}</span></td>
                    <td><span class="type-badge ${typeBadgeClass}">${typeText}</span></td>
                    <td><span class="status-badge ${statusBadgeClass}">${statusText}</span></td>
                    <td>${moduleName}</td>
                    <td>${testCase.creator}</td>
                    <td>
                        <div class="action-cell">
                            <div class="action-icon edit-icon" data-id="${testCase.id}">
