                id: "system-integration",
                title: "系统集成能力",
                icon: "fas fa-plug",
                expanded: false,
                subItems: [
                    { id: "api-interface", title: "标准化API接口", icon: "fas fa-code" },
                    { id: "auto-trigger", title: "自动化触发", icon: "fas fa-bolt" },
                    { id: "notification-center", title: "消息通知中心", icon: "fas fa-bell" }
                ]
            },
            {
                id: "system-management",
                title: "系统管理",
                icon: "fas fa-cog",
                expanded: false,
                subItems: [
                    { id: "audit-log-system", title: "系统操作日志审计", icon: "fas fa-clipboard-list" },
                    { id: "system-params", title: "系统参数动态配置", icon: "fas fa-sliders-h" },
                    { id: "data-backup", title: "数据备份与恢复", icon: "fas fa-database" }
                ]
            }
        ];

        // 仪表盘数据
        let dashboards = [
            { id: 1, name: "项目监控仪表盘", description: "金融支付系统适配项目监控", projectId: 1, widgets: 4, lastUpdated: "2025-11-10", isDefault: true },
            { id: 2, name: "缺陷分析仪表盘", description: "缺陷趋势与分布分析", projectId: 2, widgets: 3, lastUpdated: "2025-11-09", isDefault: false },
            { id: 3, name: "测试覆盖率仪表盘", description: "各模块测试覆盖率统计", projectId: 3, widgets: 2, lastUpdated: "2025-11-08", isDefault: false }
        ];

        // 当前选中的仪表盘
        let currentDashboardId = 1;

        // 当前编辑的图表
        let currentEditingChart = null;

        // 图表类型映射
        const chartTypeMap = {
            'burn-down': { name: '燃尽图', icon: 'fas fa-chart-line', color: '#4CAF50' },
            'bar': { name: '柱状图', icon: 'fas fa-chart-bar', color: '#2196F3' },
            'pie': { name: '饼图', icon: 'fas fa-chart-pie', color: '#FF9800' },
            'trend': { name: '趋势图', icon: 'fas fa-chart-area', color: '#9C27B0' },
            'radar': { name: '雷达图', icon: 'fas fa-bullseye', color: '#00BCD4' },
            'gauge': { name: '仪表图', icon: 'fas fa-tachometer-alt', color: '#F44336' }
        };

        // DOM元素
        const directoryTree = document.getElementById('directoryTree');
        const contentArea = document.getElementById('contentArea');
        const pageTitle = document.getElementById('pageTitle');
        const dashboardList = document.getElementById('dashboardList');
        const dashboardGrid = document.getElementById('dashboardGrid');
        const emptyDashboard = document.getElementById('emptyDashboard');
        const createDashboardModal = document.getElementById('createDashboardModal');
        const chartConfigModal = document.getElementById('chartConfigModal');
        const mobileMenuToggle = document.getElementById('mobileMenuToggle');
        const sidebar = document.getElementById('sidebar');

        // 初始化目录树
        function initDirectoryTree() {
            directoryTree.innerHTML = '';

            directoryData.forEach(section => {
                const li = document.createElement('li');
                li.className = 'tree-item';

                const header = document.createElement('div');
                header.className = 'tree-header';
                header.dataset.id = section.id;

                header.innerHTML = `
                    <div class="tree-title">
                        <i class="${section.icon}"></i>
                        <span>${section.title}</span>
                    </div>
                    <div class="tree-toggle ${section.expanded ? '' : 'collapsed'}">
                        <i class="fas fa-chevron-down"></i>
                    </div>
                `;

                const content = document.createElement('ul');
                content.className = `tree-content ${section.expanded ? 'expanded' : ''}`;

                section.subItems.forEach(subItem => {
                    const subLi = document.createElement('li');
                    subLi.className = 'tree-subitem';
                    subLi.dataset.id = subItem.id;
                    subLi.dataset.parentId = section.id;

                    let iconHtml = '';
                    if (subItem.icon) {
                        iconHtml = `<i class="${subItem.icon}"></i>`;
                    }

                    subLi.innerHTML = `${iconHtml}<span>${subItem.title}</span>`;

                    // 默认选中自定义仪表盘
                    if (section.id === 'report-visualization' && subItem.id === 'custom-dashboard') {
                        subLi.classList.add('active');
                        header.classList.add('active');
                    }

                    // 添加点击事件
                    subLi.addEventListener('click', (e) => {
                        e.stopPropagation();
                        selectMenuItem(subItem.id, subItem.title);

                        // 更新活动状态
                        document.querySelectorAll('.tree-subitem').forEach(item => {
                            item.classList.remove('active');
                        });
                        document.querySelectorAll('.tree-header').forEach(item => {
                            item.classList.remove('active');
                        });

                        subLi.classList.add('active');
                        header.classList.add('active');
                    });

                    content.appendChild(subLi);
                });

                // 添加点击事件展开/折叠
                header.addEventListener('click', () => {
                    const isExpanded = content.classList.contains('expanded');
                    const toggleIcon = header.querySelector('.tree-toggle i');

                    if (isExpanded) {
                        content.classList.remove('expanded');
                        header.querySelector('.tree-toggle').classList.add('collapsed');
                    } else {
                        content.classList.add('expanded');
                        header.querySelector('.tree-toggle').classList.remove('collapsed');
                    }
                });

                li.appendChild(header);
                li.appendChild(content);
                directoryTree.appendChild(li);
            });
        }

        // 选择菜单项
        function selectMenuItem(itemId, itemTitle) {
            pageTitle.textContent = itemTitle;

            // 根据选择的菜单项加载不同的内容
            if (itemId === 'custom-dashboard') {
                loadCustomDashboard();
            }

            // 如果是移动端，点击后关闭侧边栏
            if (window.innerWidth <= 992) {
                sidebar.classList.remove('active');
            }
        }

        // 加载自定义仪表盘内容
        function loadCustomDashboard() {
            // 更新页面标题
            pageTitle.textContent = '自定义仪表盘';

            // 重新渲染仪表盘列表和画布
            renderDashboardList();
            renderDashboardCanvas();

            // 绑定事件
            bindDashboardEvents();
        }

        // 渲染仪表盘列表
        function renderDashboardList() {
            dashboardList.innerHTML = '';

            if (dashboards.length === 0) {
                dashboardList.innerHTML = '<div class="empty-state" style="padding: 20px 0;"><p>暂无仪表盘</p></div>';
                return;
            }

            dashboards.forEach(dashboard => {
                const dashboardItem = document.createElement('div');
                dashboardItem.className = `dashboard-item ${dashboard.id === currentDashboardId ? 'active' : ''}`;
                dashboardItem.dataset.id = dashboard.id;

                dashboardItem.innerHTML = `
                    <div style="display: flex; align-items: center;">
                        <div class="dashboard-icon">
                            <i class="fas fa-tachometer-alt"></i>
                        </div>
                        <div>
                            <div style="font-weight: 500; font-size: 14px;">${dashboard.name}</div>
                            <div style="font-size: 12px; color: #999;">${dashboard.description}</div>
                        </div>
                    </div>
                    <div class="dashboard-actions">
                        <div class="widget-action edit-dashboard" title="编辑">
                            <i class="fas fa-edit"></i>
                        </div>
                        <div class="widget-action delete-dashboard" title="删除">
                            <i class="fas fa-trash"></i>
                        </div>
                    </div>
                `;

                // 添加点击事件
                dashboardItem.addEventListener('click', (e) => {
                    if (!e.target.closest('.dashboard-actions')) {
                        selectDashboard(dashboard.id);
                    }
                });

                // 添加编辑事件
                const editBtn = dashboardItem.querySelector('.edit-dashboard');
                editBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    editDashboard(dashboard.id);
                });

                // 添加删除事件
                const deleteBtn = dashboardItem.querySelector('.delete-dashboard');
                deleteBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    deleteDashboard(dashboard.id);
                });

                dashboardList.appendChild(dashboardItem);
            });
        }

        // 渲染仪表盘画布
        function renderDashboardCanvas() {
            dashboardGrid.innerHTML = '';

            const currentDashboard = dashboards.find(d => d.id === currentDashboardId);

            if (!currentDashboard || !currentDashboard.widgets || currentDashboard.widgets === 0) {
                emptyDashboard.style.display = 'flex';
                dashboardGrid.appendChild(emptyDashboard);
                return;
            }

            emptyDashboard.style.display = 'none';

            // 生成示例图表组件
            const widgets = [
                { id: 1, type: 'burn-down', title: '项目燃尽图', width: 6, height: 3, x: 1, y: 1 },
                { id: 2, type: 'bar', title: '缺陷严重程度分布', width: 6, height: 3, x: 7, y: 1 },
                { id: 3, type: 'pie', title: '测试用例状态分布', width: 4, height: 3, x: 1, y: 4 },
                { id: 4, type: 'trend', title: '缺陷趋势分析', width: 8, height: 3, x: 5, y: 4 }
            ];

            widgets.forEach(widget => {
                const chartType = chartTypeMap[widget.type];

                const widgetElement = document.createElement('div');
                widgetElement.className = 'dashboard-widget';
                widgetElement.dataset.id = widget.id;
                widgetElement.dataset.type = widget.type;
                widgetElement.style.gridColumn = `${widget.x} / span ${widget.width}`;
                widgetElement.style.gridRow = `${widget.y} / span ${widget.height}`;

                widgetElement.innerHTML = `
                    <div class="widget-header">
                        <div class="widget-title">
                            <i class="${chartType.icon}" style="margin-right: 8px; color: ${chartType.color};"></i>
                            ${widget.title}
                        </div>
                        <div class="widget-actions">
                            <div class="widget-action edit-chart" title="编辑">
                                <i class="fas fa-cog"></i>
                            </div>
                            <div class="widget-action delete-chart" title="删除">
                                <i class="fas fa-times"></i>
                            </div>
                        </div>
                    </div>
                    <div class="widget-body">
                        <div class="chart-placeholder">
                            <i class="${chartType.icon}" style="color: ${chartType.color};"></i>
                            <span>${chartType.name}</span>
                            <small style="margin-top: 10px; font-size: 12px;">实时数据更新中...</small>
                        </div>
                    </div>
                `;

                // 添加编辑事件
                const editBtn = widgetElement.querySelector('.edit-chart');
                editBtn.addEventListener('click', () => {
                    editChart(widget.id);
                });

                // 添加删除事件
                const deleteBtn = widgetElement.querySelector('.delete-chart');
                deleteBtn.addEventListener('click', () => {
                    deleteChart(widget.id);
                });

                // 添加拖拽功能
                makeWidgetDraggable(widgetElement);

                dashboardGrid.appendChild(widgetElement);
            });

            // 初始化拖拽功能
            initDragAndDrop();
        }

        // 使组件可拖拽
        function makeWidgetDraggable(element) {
            const header = element.querySelector('.widget-header');
            header.setAttribute('draggable', 'true');

            header.addEventListener('dragstart', (e) => {
                e.dataTransfer.setData('text/plain', element.dataset.id);
                e.dataTransfer.effectAllowed = 'move';
                element.style.opacity = '0.5';
            });

            header.addEventListener('dragend', () => {
                element.style.opacity = '1';
            });
        }

        // 初始化拖拽功能
        function initDragAndDrop() {
            // 图表组件拖拽
            const chartTypes = document.querySelectorAll('.chart-type');
            chartTypes.forEach(chartType => {
                chartType.addEventListener('dragstart', (e) => {
                    e.dataTransfer.setData('text/plain', chartType.dataset.type);
                    e.dataTransfer.effectAllowed = 'copy';
                });
            });

            // 仪表盘画布拖拽目标
            dashboardGrid.addEventListener('dragover', (e) => {
                e.preventDefault();
                e.dataTransfer.dropEffect = 'copy';
            });

            dashboardGrid.addEventListener('drop', (e) => {
                e.preventDefault();
                const chartType = e.dataTransfer.getData('text/plain');

                if (chartType && chartTypeMap[chartType]) {
                    addChartToDashboard(chartType);
                }
            });

            // 组件在画布内拖拽重新排序
            dashboardGrid.addEventListener('dragover', (e) => {
                e.preventDefault();
                const draggable = document.querySelector('.dashboard-widget[draggable="true"]');
                if (!draggable) return;

                const afterElement = getDragAfterElement(dashboardGrid, e.clientY);
                if (afterElement) {
                    dashboardGrid.insertBefore(draggable, afterElement);
                } else {
                    dashboardGrid.appendChild(draggable);
                }
            });
        }

        // 获取拖拽后的元素位置
        function getDragAfterElement(container, y) {
            const draggableElements = [...container.querySelectorAll('.dashboard-widget:not(.dragging)')];

            return draggableElements.reduce((closest, child) => {
                const box = child.getBoundingClientRect();
                const offset = y - box.top - box.height / 2;

                if (offset < 0 && offset > closest.offset) {
                    return { offset: offset, element: child };
                } else {
                    return closest;
                }
            }, { offset: Number.NEGATIVE_INFINITY }).element;
        }

        // 添加图表到仪表盘
        function addChartToDashboard(chartType) {
            const chartInfo = chartTypeMap[chartType];

            // 打开配置模态框
            currentEditingChart = {
                type: chartType,
                title: `新建${chartInfo.name}`,
                isNew: true
            };

            document.getElementById('chartConfigTitle').textContent = `配置${chartInfo.name}`;
            document.getElementById('chartTitle').value = `新建${chartInfo.name}`;
            document.getElementById('chartType').value = chartType;

            openChartConfigModal();
        }

        // 选择仪表盘
        function selectDashboard(dashboardId) {
            currentDashboardId = dashboardId;

            // 更新列表选中状态
            document.querySelectorAll('.dashboard-item').forEach(item => {
                if (parseInt(item.dataset.id) === dashboardId) {
                    item.classList.add('active');
                } else {
                    item.classList.remove('active');
                }
            });

            // 重新渲染画布
            renderDashboardCanvas();
        }

        // 编辑仪表盘
        function editDashboard(dashboardId) {
            const dashboard = dashboards.find(d => d.id === dashboardId);

            if (dashboard) {
                document.getElementById('dashboardName').value = dashboard.name;
                document.getElementById('dashboardDescription').value = dashboard.description;
                document.getElementById('dashboardProject').value = dashboard.projectId || '';
                document.getElementById('dashboardTemplate').value = 'blank';

                openCreateDashboardModal();
            }
        }

        // 删除仪表盘
        function deleteDashboard(dashboardId) {
            if (confirm('确定要删除这个仪表盘吗？删除后无法恢复。')) {
                dashboards = dashboards.filter(d => d.id !== dashboardId);

                if (dashboards.length > 0 && currentDashboardId === dashboardId) {
                    currentDashboardId = dashboards[0].id;
                }

                renderDashboardList();
                renderDashboardCanvas();

                showNotification('仪表盘已删除', 'success');
            }
        }

        // 编辑图表
        function editChart(chartId) {
            // 这里可以获取实际图表数据，这里使用示例数据
            currentEditingChart = {
                id: chartId,
                type: 'burn-down',
                title: '项目燃尽图',
                dataSource: 'SELECT date, completed, total FROM sprint_burndown WHERE project_id = 1',
                width: 6,
                height: 3,
                refresh: 30,
                isNew: false
            };

            document.getElementById('chartConfigTitle').textContent = '编辑图表配置';
            document.getElementById('chartTitle').value = currentEditingChart.title;
            document.getElementById('chartType').value = currentEditingChart.type;
            document.getElementById('chartDataSource').value = currentEditingChart.dataSource;
            document.getElementById('chartWidth').value = currentEditingChart.width;
            document.getElementById('chartHeight').value = currentEditingChart.height;
            document.getElementById('chartRefresh').value = currentEditingChart.refresh;

            openChartConfigModal();
        }

        // 删除图表
        function deleteChart(chartId) {
            if (confirm('确定要删除这个图表吗？')) {
                // 这里应该更新仪表盘数据
                showNotification('图表已删除', 'success');

                // 重新渲染画布
                renderDashboardCanvas();
            }
        }

        // 绑定仪表盘事件
        function bindDashboardEvents() {
            // 新建仪表盘按钮
            document.getElementById('createDashboardBtn').addEventListener('click', () => {
                openCreateDashboardModal();
            });

            // 添加仪表盘按钮
            document.getElementById('addDashboardBtn').addEventListener('click', () => {
                openCreateDashboardModal();
            });

            // 导入模板按钮
            document.getElementById('importTemplateBtn').addEventListener('click', () => {
                showNotification('模板导入功能开发中', 'success');
            });

            // 保存布局按钮
            document.getElementById('saveDashboardBtn').addEventListener('click', () => {
                showNotification('仪表盘布局已保存', 'success');
            });

            // 应用数据源配置按钮
            document.getElementById('applyDataSourceBtn').addEventListener('click', () => {
                const dataSourceType = document.getElementById('dataSourceType').value;
                const refreshInterval = document.getElementById('refreshInterval').value;

                showNotification(`数据源配置已应用：${dataSourceType}，刷新间隔：${refreshInterval}秒`, 'success');
            });

            // 复制链接按钮
            document.getElementById('copyLinkBtn').addEventListener('click', () => {
                const shareLink = document.getElementById('shareLink');
                shareLink.select();
                document.execCommand('copy');
                showNotification('链接已复制到剪贴板', 'success');
            });

            // 新建仪表盘模态框
            document.getElementById('closeCreateDashboardModalBtn').addEventListener('click', closeCreateDashboardModal);
            document.getElementById('cancelCreateDashboardBtn').addEventListener('click', closeCreateDashboardModal);
            document.getElementById('confirmCreateDashboardBtn').addEventListener('click', confirmCreateDashboard);

            // 图表配置模态框
            document.getElementById('closeChartConfigModalBtn').addEventListener('click', closeChartConfigModal);
            document.getElementById('cancelChartConfigBtn').addEventListener('click', closeChartConfigModal);
            document.getElementById('confirmChartConfigBtn').addEventListener('click', confirmChartConfig);
        }

        // 打开新建仪表盘模态框
        function openCreateDashboardModal() {
            createDashboardModal.classList.add('active');
        }

        // 关闭新建仪表盘模态框
        function closeCreateDashboardModal() {
            createDashboardModal.classList.remove('active');
            document.getElementById('createDashboardForm').reset();
        }

        // 确认创建仪表盘
        function confirmCreateDashboard() {
            const name = document.getElementById('dashboardName').value;
            const description = document.getElementById('dashboardDescription').value;
            const projectId = document.getElementById('dashboardProject').value;
            const template = document.getElementById('dashboardTemplate').value;

            if (!name) {
                showNotification('请输入仪表盘名称', 'error');
                return;
            }

            // 创建新仪表盘
            const newDashboard = {
                id: dashboards.length > 0 ? Math.max(...dashboards.map(d => d.id)) + 1 : 1,
                name: name,
                description: description,
                projectId: parseInt(projectId) || 0,
                widgets: template === 'blank' ? 0 : 4,
                lastUpdated: new Date().toISOString().split('T')[0],
                isDefault: false
            };

            dashboards.push(newDashboard);
            currentDashboardId = newDashboard.id;

            closeCreateDashboardModal();
            renderDashboardList();
            renderDashboardCanvas();

            showNotification(`仪表盘"${name}"创建成功`, 'success');
        }

        // 打开图表配置模态框
        function openChartConfigModal() {
            chartConfigModal.classList.add('active');
        }

        // 关闭图表配置模态框
        function closeChartConfigModal() {
            chartConfigModal.classList.remove('active');
            document.getElementById('chartConfigForm').reset();
            currentEditingChart = null;
        }

        // 确认图表配置
        function confirmChartConfig() {
            const title = document.getElementById('chartTitle').value;
            const dataSource = document.getElementById('chartDataSource').value;
            const width = parseInt(document.getElementById('chartWidth').value);
            const height = parseInt(document.getElementById('chartHeight').value);
            const refresh = parseInt(document.getElementById('chartRefresh').value);

            if (!title) {
                showNotification('请输入图表标题', 'error');
                return;
            }

            if (!dataSource) {
                showNotification('请输入数据源配置', 'error');
                return;
            }

            // 这里应该保存图表配置到仪表盘数据
            showNotification(`图表"${title}"配置已保存`, 'success');

            closeChartConfigModal();

            // 如果是新图表，添加到画布
            if (currentEditingChart && currentEditingChart.isNew) {
                // 重新渲染画布以显示新图表
                renderDashboardCanvas();
            }
        }

        // 显示通知
        function showNotification(message, type) {
            // 创建通知元素
            const notification = document.createElement('div');
            notification.className = `notification ${type === 'error' ? 'error' : ''}`;

            notification.innerHTML = `
                <i class="fas fa-${type === 'success' ? 'check-circle' : 'exclamation-circle'}"></i>
                <span>${message}</span>
            `;

            document.body.appendChild(notification);

            // 3秒后移除通知
            setTimeout(() => {
                notification.style.animation = 'slideOut 0.3s ease';
                setTimeout(() => {
                    if (notification.parentNode) {
                        notification.parentNode.removeChild(notification);
                    }
                }, 300);
            }, 3000);
        }

        // 初始化
        document.addEventListener('DOMContentLoaded', () => {
            initDirectoryTree();
            loadCustomDashboard();

            // 移动端菜单切换
            mobileMenuToggle.addEventListener('click', () => {
                sidebar.classList.toggle('active');
            });

            // 窗口大小变化时调整侧边栏
            window.addEventListener('resize', () => {
                if (window.innerWidth > 992) {
                    sidebar.classList.remove('active');
                }
            });

            // 点击外部关闭移动端侧边栏
            document.addEventListener('click', (e) => {
                if (window.innerWidth <= 992 && 
                    !sidebar.contains(e.target) && 
                    !mobileMenuToggle.contains(e.target) && 
                    sidebar.classList.contains('active')) {
                    sidebar.classList.remove('active');
                }
            });
        });
    </script>
</body>
</html>
```

## 功能说明

这个自定义仪表盘页面实现了以下功能：

1. **整体架构与样式**：完全保持与2.html一致的脚手架架构、图标和主题风格。

2. **固定头部和侧边栏**：页面上下滑动时，顶部标题栏和左侧目录结构保持固定不动。

3. **软件名称更新**：已将"中软国际适配中心-测试管理软件 V1.0"改为"适配中心测试管理软件 V1.0"。

4. **左侧目录结构**：与2.html保持一致的目录结构，其中"报表与可视化看板"展开，并且"自定义仪表盘"处于选中状态。

5. **自定义仪表盘功能**：
   - 仪表盘列表管理：显示已有仪表盘，支持创建、编辑、删除
   - 拖拽式图表配置：支持从左侧拖拽图表组件到画布
   - 多种图表类型：燃尽图、柱状图、饼图、趋势图、雷达图、仪表图
   - 数据源配置：支持SQL查询、API接口或静态数据
   - 实时数据更新：基于WebSocket技术（模拟实现）
   - 共享设置：支持私有、共享和公开三种可见性设置
