            { id: 14, title: "测试任务执行进度更新不及时", description: "测试人员更新任务进度后，页面显示延迟超过1分钟", severity: "medium", priority: "p3", status: "closed", module: "task-management", assignee: "林涛", createdDate: "2025-10-28", project: "政务云平台测试项目", steps: "1. 更新测试任务进度\n2. 计时观察页面刷新时间\n3. 记录延迟时间" },
            { id: 15, title: "用户权限变更后需要重新登录才能生效", description: "管理员修改用户权限后，用户需要重新登录系统权限才能生效", severity: "low", priority: "p4", status: "new", module: "user-management", assignee: "徐静", createdDate: "2025-10-27", project: "医疗影像系统适配项目", steps: "1. 管理员修改用户权限\n2. 用户继续使用系统\n3. 检查权限是否生效" }
        ];

        // 分页配置
        let currentPage = 1;
        const itemsPerPage = 10;
        let filteredDefects = [...defectsData];
        let currentEditingDefectId = null;

        // DOM元素
        const directoryTree = document.getElementById('directoryTree');
        const contentArea = document.getElementById('contentArea');
        const pageTitle = document.getElementById('pageTitle');
        const defectsTableBody = document.getElementById('defectsTableBody');
        const pagination = document.getElementById('pagination');
        const paginationInfo = document.getElementById('paginationInfo');
        const emptyState = document.getElementById('emptyState');
        const exportModal = document.getElementById('exportModal');
        const defectDetailModal = document.getElementById('defectDetailModal');
        const editDefectModal = document.getElementById('editDefectModal');
        const mobileMenuToggle = document.getElementById('mobileMenuToggle');
        const sidebar = document.getElementById('sidebar');

        // 初始化目录树
        function initDirectoryTree() {
            directoryTree.innerHTML = '';

            directoryData.forEach(section => {
                const li = document.createElement('li');
                li.className = 'tree-item';

                const header = document.createElement('div');
                header.className = 'tree-header';
                header.dataset.id = section.id;

                header.innerHTML = `
                    <div class="tree-title">
                        <i class="${section.icon}"></i>
                        <span>${section.title}</span>
                    </div>
                    <div class="tree-toggle ${section.expanded ? '' : 'collapsed'}">
                        <i class="fas fa-chevron-down"></i>
                    </div>
                `;

                const content = document.createElement('ul');
                content.className = `tree-content ${section.expanded ? 'expanded' : ''}`;

                section.subItems.forEach(subItem => {
                    const subLi = document.createElement('li');
                    subLi.className = 'tree-subitem';
                    subLi.dataset.id = subItem.id;
                    subLi.dataset.parentId = section.id;

                    let iconHtml = '';
                    if (subItem.icon) {
                        iconHtml = `<i class="${subItem.icon}"></i>`;
                    }

                    subLi.innerHTML = `${iconHtml}<span>${subItem.title}</span>`;

                    // 默认选中缺陷统计与分析
                    if (section.id === 'test-task-management' && subItem.id === 'defect-statistics') {
                        subLi.classList.add('active');
                        header.classList.add('active');
                    }

                    // 添加点击事件
                    subLi.addEventListener('click', (e) => {
                        e.stopPropagation();
                        selectMenuItem(subItem.id, subItem.title);

                        // 更新活动状态
                        document.querySelectorAll('.tree-subitem').forEach(item => {
                            item.classList.remove('active');
                        });
                        document.querySelectorAll('.tree-header').forEach(item => {
                            item.classList.remove('active');
                        });

                        subLi.classList.add('active');
                        header.classList.add('active');
                    });

                    content.appendChild(subLi);
                });

                // 添加点击事件展开/折叠
                header.addEventListener('click', () => {
                    const isExpanded = content.classList.contains('expanded');
                    const toggleIcon = header.querySelector('.tree-toggle i');

                    if (isExpanded) {
                        content.classList.remove('expanded');
                        header.querySelector('.tree-toggle').classList.add('collapsed');
                    } else {
                        content.classList.add('expanded');
                        header.querySelector('.tree-toggle').classList.remove('collapsed');
                    }
                });

                li.appendChild(header);
                li.appendChild(content);
                directoryTree.appendChild(li);
            });
        }

        // 选择菜单项
        function selectMenuItem(itemId, itemTitle) {
            pageTitle.textContent = itemTitle;

            // 根据选择的菜单项加载不同的内容
            if (itemId === 'defect-statistics') {
                loadDefectStatistics();
            }

            // 如果是移动端，点击后关闭侧边栏
            if (window.innerWidth <= 992) {
                sidebar.classList.remove('active');
            }
        }

        // 加载缺陷统计与分析内容
        function loadDefectStatistics() {
            // 页面标题已经设置，无需更改

            // 渲染表格和分页
            applyFilters();

            // 绑定事件
            bindDefectEvents();
        }

        // 绑定缺陷模块事件
        function bindDefectEvents() {
            // 导出报告按钮
            document.getElementById('exportReportBtn').addEventListener('click', () => {
                exportModal.classList.add('active');
            });

            // 刷新按钮
            document.getElementById('refreshDefectsBtn').addEventListener('click', refreshDefects);

            // 新建缺陷按钮
            document.getElementById('addDefectBtn').addEventListener('click', addDefect);

            // 筛选按钮
            document.getElementById('applyFiltersBtn').addEventListener('click', applyFilters);

            // 重置筛选按钮
            document.getElementById('resetFiltersBtn').addEventListener('click', resetFilters);

            // 导出模态框事件
            document.getElementById('closeExportModalBtn').addEventListener('click', closeExportModal);
            document.getElementById('cancelExportBtn').addEventListener('click', closeExportModal);
            document.getElementById('confirmExportBtn').addEventListener('click', confirmExport);

            // 缺陷详情模态框事件
            document.getElementById('closeDefectDetailModalBtn').addEventListener('click', closeDefectDetailModal);
            document.getElementById('closeDefectDetailBtn').addEventListener('click', closeDefectDetailModal);
            document.getElementById('editDefectBtn').addEventListener('click', editDefectFromDetail);

            // 编辑缺陷模态框事件
            document.getElementById('closeEditDefectModalBtn').addEventListener('click', closeEditDefectModal);
            document.getElementById('cancelEditDefectBtn').addEventListener('click', closeEditDefectModal);
            document.getElementById('saveDefectBtn').addEventListener('click', saveDefect);

            // 移动端菜单切换
            mobileMenuToggle.addEventListener('click', () => {
                sidebar.classList.toggle('active');
            });
        }

        // 应用筛选
        function applyFilters() {
            const severityFilter = document.getElementById('severityFilter').value;
            const statusFilter = document.getElementById('statusFilter').value;
            const priorityFilter = document.getElementById('priorityFilter').value;
            const moduleFilter = document.getElementById('moduleFilter').value;

            filteredDefects = defectsData.filter(defect => {
                return (!severityFilter || defect.severity === severityFilter) &&
                       (!statusFilter || defect.status === statusFilter) &&
                       (!priorityFilter || defect.priority === priorityFilter) &&
                       (!moduleFilter || defect.module === moduleFilter);
            });

            currentPage = 1;
            renderDefectsTable();
            renderPagination();
        }

        // 重置筛选
        function resetFilters() {
            document.getElementById('severityFilter').value = '';
            document.getElementById('statusFilter').value = '';
            document.getElementById('priorityFilter').value = '';
            document.getElementById('moduleFilter').value = '';

            filteredDefects = [...defectsData];
            currentPage = 1;
            renderDefectsTable();
            renderPagination();
        }

        // 刷新缺陷数据
        function refreshDefects() {
            // 模拟从服务器重新加载数据
            showNotification('缺陷数据已刷新', 'success');
            applyFilters();
        }

        // 渲染缺陷表格
        function renderDefectsTable() {
            const tableBody = document.getElementById('defectsTableBody');
            const emptyState = document.getElementById('emptyState');

            if (filteredDefects.length === 0) {
                tableBody.innerHTML = '';
                emptyState.style.display = 'block';
                return;
            }

            emptyState.style.display = 'none';

            // 计算当前页的数据
            const startIndex = (currentPage - 1) * itemsPerPage;
            const endIndex = Math.min(startIndex + itemsPerPage, filteredDefects.length);
            const currentDefects = filteredDefects.slice(startIndex, endIndex);

            tableBody.innerHTML = '';

            currentDefects.forEach(defect => {
                // 确定严重程度徽章
                let severityBadgeClass = '';
                let severityText = '';
                switch(defect.severity) {
                    case 'critical':
                        severityBadgeClass = 'badge-critical';
                        severityText = '严重';
                        break;
                    case 'high':
                        severityBadgeClass = 'badge-high';
                        severityText = '高';
                        break;
                    case 'medium':
                        severityBadgeClass = 'badge-medium';
                        severityText = '中';
                        break;
                    case 'low':
                        severityBadgeClass = 'badge-low';
                        severityText = '低';
                        break;
                    case 'info':
                        severityBadgeClass = 'badge-info';
                        severityText = '提示';
                        break;
                }

                // 确定状态徽章
                let statusBadgeClass = '';
                let statusText = '';
                switch(defect.status) {
                    case 'new':
                        statusBadgeClass = 'status-new';
                        statusText = '新建';
                        break;
                    case 'in-progress':
                        statusBadgeClass = 'status-in-progress';
                        statusText = '处理中';
                        break;
                    case 'resolved':
                        statusBadgeClass = 'status-resolved';
                        statusText = '已解决';
                        break;
                    case 'closed':
                        statusBadgeClass = 'status-closed';
                        statusText = '已关闭';
                        break;
                    case 'reopened':
                        statusBadgeClass = 'status-reopened';
                        statusText = '重新打开';
                        break;
                }

                // 确定优先级徽章
                let priorityBadgeClass = '';
                let priorityText = '';
                switch(defect.priority) {
                    case 'p1':
                        priorityBadgeClass = 'priority-p1';
                        priorityText = 'P1';
                        break;
                    case 'p2':
                        priorityBadgeClass = 'priority-p2';
                        priorityText = 'P2';
                        break;
                    case 'p3':
                        priorityBadgeClass = 'priority-p3';
                        priorityText = 'P3';
                        break;
                    case 'p4':
                        priorityBadgeClass = 'priority-p4';
                        priorityText = 'P4';
                        break;
                }

                // 模块名称映射
                let moduleName = '';
                switch(defect.module) {
                    case 'user-management':
                        moduleName = '用户管理';
                        break;
                    case 'project-management':
                        moduleName = '项目管理';
                        break;
                    case 'test-case':
                        moduleName = '测试用例';
                        break;
                    case 'task-management':
                        moduleName = '任务管理';
                        break;
                    case 'report-visualization':
                        moduleName = '报表可视化';
                        break;
                    case 'system-integration':
                        moduleName = '系统集成';
                        break;
                    case 'system-management':
                        moduleName = '系统管理';
                        break;
                    default:
                        moduleName = defect.module;
                }

                const row = document.createElement('tr');
                row.innerHTML = `
                    <td>DEFECT-${defect.id.toString().padStart(4, '0')}</td>
                    <td>
                        <div style="font-weight: 500; margin-bottom: 5px;">${defect.title}</div>
                        <div style="font-size: 12px; color: #999;">${defect.description.substring(0, 60)}${defect.description.length > 60 ? '...' : ''}</div>
                    </td>
                    <td><span class="severity-badge ${severityBadgeClass}">${severityText}</span></td>
                    <td><span class="priority-badge ${priorityBadgeClass}">${priorityText}</span></td>
                    <td><span class="status-badge ${statusBadgeClass}">${statusText}</span></td>
                    <td>${moduleName}</td>
                    <td>${defect.assignee}</td>
                    <td>${defect.createdDate}</td>
                    <td>
                        <div class="action-cell">
                            <div class="action-icon view-icon" title="查看详情" data-id="${defect.id}">
                                <i class="fas fa-eye"></i>
                            </div>
                            <div class="action-icon edit-icon" title="编辑" data-id="${defect.id}">
                                <i class="fas fa-edit"></i>
                            </div>
                            <div class="action-icon assign-icon" title="分配" data-id="${defect.id}">
                                <i class="fas fa-user-check"></i>
                            </div>
                            <div class="action-icon delete-icon" title="删除" data-id="${defect.id}">
                                <i class="fas fa-trash"></i>
                            </div>
                        </div>
                    </td>
                `;

                // 绑定操作按钮事件
                const viewBtn = row.querySelector('.view-icon');
                viewBtn.addEventListener('click', () => {
                    viewDefectDetail(defect.id);
                });

                const editBtn = row.querySelector('.edit-icon');
                editBtn.addEventListener('click', () => {
                    editDefect(defect.id);
                });

                const assignBtn = row.querySelector('.assign-icon');
                assignBtn.addEventListener('click', () => {
                    assignDefect(defect.id);
                });

                const deleteBtn = row.querySelector('.delete-icon');
                deleteBtn.addEventListener('click', () => {
                    deleteDefect(defect.id);
                });

                tableBody.appendChild(row);
            });
        }

        // 渲染分页
        function renderPagination() {
            const totalPages = Math.ceil(filteredDefects.length / itemsPerPage);
            const pagination = document.getElementById('pagination');
            const paginationInfo = document.getElementById('paginationInfo');

            // 更新分页信息
            const startItem = (currentPage - 1) * itemsPerPage + 1;
            const endItem = Math.min(currentPage * itemsPerPage, filteredDefects.length);
            paginationInfo.textContent = `显示 ${startItem}-${endItem} 条，共 ${filteredDefects.length} 条`;

            // 生成分页按钮
            pagination.innerHTML = '';

            // 上一页按钮
            const prevLi = document.createElement('li');
            prevLi.className = 'page-item';
            prevLi.innerHTML = `<a class="page-link ${currentPage === 1 ? 'disabled' : ''}" href="#" data-page="${currentPage - 1}"><i class="fas fa-chevron-left"></i></a>`;
            pagination.appendChild(prevLi);

            // 页码按钮
            const maxVisiblePages = 5;
            let startPage = Math.max(1, currentPage - Math.floor(maxVisiblePages / 2));
            let endPage = Math.min(totalPages, startPage + maxVisiblePages - 1);

            // 调整起始页，确保显示maxVisiblePages个页码
            if (endPage - startPage + 1 < maxVisiblePages) {
                startPage = Math.max(1, endPage - maxVisiblePages + 1);
            }

            for (let i = startPage; i <= endPage; i++) {
                const pageLi = document.createElement('li');
                pageLi.className = 'page-item';
                pageLi.innerHTML = `<a class="page-link ${i === currentPage ? 'active' : ''}" href="#" data-page="${i}">${i}</a>`;
                pagination.appendChild(pageLi);
            }

            // 下一页按钮
            const nextLi = document.createElement('li');
            nextLi.className = 'page-item';
            nextLi.innerHTML = `<a class="page-link ${currentPage === totalPages ? 'disabled' : ''}" href="#" data-page="${currentPage + 1}"><i class="fas fa-chevron-right"></i></a>`;
            pagination.appendChild(nextLi);

            // 绑定分页点击事件
            document.querySelectorAll('.page-link').forEach(link => {
                link.addEventListener('click', (e) => {
                    e.preventDefault();

                    if (link.classList.contains('disabled')) return;

                    const page = parseInt(link.dataset.page);
                    if (!isNaN(page)) {
                        currentPage = page;
                        renderDefectsTable();
                        renderPagination();

                        // 滚动到表格顶部
                        document.querySelector('.table-container').scrollTop = 0;
                    }
                });
            });
        }

        // 查看缺陷详情
        function viewDefectDetail(defectId) {
            const defect = defectsData.find(d => d.id === defectId);
            if (!defect) return;

            // 确定严重程度文本
            let severityText = '';
            switch(defect.severity) {
                case 'critical': severityText = '严重'; break;
                case 'high': severityText = '高'; break;
                case 'medium': severityText = '中'; break;
                case 'low': severityText = '低'; break;
                case 'info': severityText = '提示'; break;
            }

            // 确定状态文本
            let statusText = '';
            switch(defect.status) {
                case 'new': statusText = '新建'; break;
                case 'in-progress': statusText = '处理中'; break;
                case 'resolved': statusText = '已解决'; break;
                case 'closed': statusText = '已关闭'; break;
                case 'reopened': statusText = '重新打开'; break;
            }

            // 确定优先级文本
            let priorityText = '';
            switch(defect.priority) {
                case 'p1': priorityText = 'P1 - 紧急'; break;
