                case 'project-management': moduleName = '项目管理'; break;
                case 'test-case': moduleName = '测试用例'; break;
                case 'task-management': moduleName = '任务管理'; break;
                case 'report-visualization': moduleName = '报表可视化'; break;
                case 'system-integration': moduleName = '系统集成'; break;
                case 'system-management': moduleName = '系统管理'; break;
