                    <div class="defect-detail-label">缺陷ID：</div>
                    <div class="defect-detail-value">DEFECT-${defect.id.toString().padStart(4, '0')}</div>
                </div>
                <div class="defect-detail-row">
                    <div class="defect-detail-label">缺陷标题：</div>
