                });
            });

            // 绑定模板选择事件
            document.querySelectorAll('.template-card').forEach(card => {
                card.addEventListener('click', function() {
                    document.querySelectorAll('.template-card').forEach(c => {
                        c.style.border = 'none';
                    });
                    this.style.border = '2px solid #1a3a8f';
                });
            });
        }

        // 初始化仪表盘
        function initDashboard() {
            // 生成网格
            dashboardGrid.innerHTML = '';
            for (let i = 0; i < 48; i++) {
                const cell = document.createElement('div');
                cell.className = 'grid-cell';
                cell.dataset.index = i;
                dashboardGrid.appendChild(cell);
            }

            // 绑定拖拽事件
            initDragAndDrop();

            // 如果已有组件，渲染它们
            if (dashboardWidgets.length > 0) {
                renderDashboardWidgets();
            } else {
                emptyDashboard.style.display = 'block';
            }
        }

        // 初始化拖拽功能
        function initDragAndDrop() {
            // 图表类型拖拽
            const chartItems = document.querySelectorAll('.chart-type-item');
            chartItems.forEach(item => {
                item.addEventListener('dragstart', function(e) {
                    e.dataTransfer.setData('text/plain', this.dataset.type);
                });
            });

            // 网格单元格拖拽放置
            const gridCells = document.querySelectorAll('.grid-cell');
            gridCells.forEach(cell => {
                cell.addEventListener('dragover', function(e) {
                    e.preventDefault();
                    this.classList.add('highlight');
                });

                cell.addEventListener('dragleave', function() {
                    this.classList.remove('highlight');
                });

                cell.addEventListener('drop', function(e) {
                    e.preventDefault();
                    this.classList.remove('highlight');

                    const chartType = e.dataTransfer.getData('text/plain');
                    if (chartType) {
                        addWidgetToGrid(chartType, parseInt(this.dataset.index));
                    }
                });
            });
        }

        // 添加组件到网格
        function addWidgetToGrid(type, cellIndex) {
            // 生成唯一ID
            const widgetId = 'widget_' + Date.now() + '_' + Math.floor(Math.random() * 1000);

            // 创建组件对象
            const widget = {
                id: widgetId,
                type: type,
                title: getChartTypeName(type) + ' ' + (dashboardWidgets.filter(w => w.type === type).length + 1),
                x: cellIndex % 12,
                y: Math.floor(cellIndex / 12),
                width: 2,
                height: 2,
                color: '#1a3a8f',
                showBorder: true,
                dataSourceType: 'static',
                dataSourceConfig: '{}'
            };

            // 添加到组件列表
            dashboardWidgets.push(widget);

            // 重新渲染
            renderDashboardWidgets();

            // 选中新添加的组件
            selectWidget(widgetId);

            // 隐藏空状态提示
            emptyDashboard.style.display = 'none';

            showNotification('图表组件添加成功', 'success');
        }

        // 获取图表类型名称
        function getChartTypeName(type) {
            const typeNames = {
                line: '折线图',
                bar: '柱状图',
                pie: '饼图',
                scatter: '散点图',
                radar: '雷达图',
                gauge: '仪表盘',
                table: '数据表格',
                text: '文本组件'
            };
            return typeNames[type] || type;
        }

        // 渲染仪表盘组件
        function renderDashboardWidgets() {
            // 先清空网格
            const gridCells = document.querySelectorAll('.grid-cell');
            gridCells.forEach(cell => {
                cell.innerHTML = '';
            });

            // 渲染每个组件
            dashboardWidgets.forEach(widget => {
                // 计算组件位置
                const cellIndex = widget.y * 12 + widget.x;
                const cell = document.querySelector(`.grid-cell[data-index="${cellIndex}"]`);

                if (cell) {
                    // 创建组件元素
                    const widgetElement = document.createElement('div');
                    widgetElement.className = 'chart-widget';
                    widgetElement.id = widget.id;
                    widgetElement.style.gridColumn = `${widget.x + 1} / span ${widget.width}`;
                    widgetElement.style.gridRow = `${widget.y + 1} / span ${widget.height}`;

                    if (widget.showBorder === false) {
                        widgetElement.style.border = 'none';
                    }

                    // 组件标题栏
                    const header = document.createElement('div');
                    header.className = 'chart-widget-header';
                    header.innerHTML = `
                        <div class="chart-widget-title">${widget.title}</div>
                        <div class="chart-widget-controls">
                            <div class="widget-control edit-widget" title="编辑">
                                <i class="fas fa-edit"></i>
                            </div>
                            <div class="widget-control delete-widget" title="删除">
                                <i class="fas fa-trash"></i>
                            </div>
                        </div>
                    `;

                    // 组件内容
                    const content = document.createElement('div');
                    content.className = 'chart-widget-content';
                    content.innerHTML = getChartContent(widget.type, widget.color);

                    widgetElement.appendChild(header);
                    widgetElement.appendChild(content);

                    // 添加到单元格
                    cell.appendChild(widgetElement);

                    // 绑定组件事件
                    bindWidgetEvents(widgetElement, widget.id);
                }
            });
        }

        // 获取图表内容
        function getChartContent(type, color) {
            const icons = {
                line: 'fas fa-chart-line',
                bar: 'fas fa-chart-bar',
                pie: 'fas fa-chart-pie',
                scatter: 'fas fa-chart-scatter',
                radar: 'fas fa-chart-radar',
                gauge: 'fas fa-tachometer-alt',
                table: 'fas fa-table',
                text: 'fas fa-font'
            };

            const names = {
                line: '折线图',
                bar: '柱状图',
                pie: '饼图',
                scatter: '散点图',
                radar: '雷达图',
                gauge: '仪表盘',
                table: '数据表格',
                text: '文本组件'
            };

            return `
                <div class="chart-placeholder">
                    <i class="${icons[type]}" style="color: ${color};"></i>
                    <div>${names[type]}</div>
                    <div style="font-size: 12px; margin-top: 10px;">点击上方编辑按钮配置数据</div>
                </div>
            `;
        }

        // 绑定组件事件
        function bindWidgetEvents(widgetElement, widgetId) {
            // 点击组件选中
            widgetElement.addEventListener('click', function(e) {
                if (!e.target.closest('.widget-control')) {
                    selectWidget(widgetId);
                }
            });

            // 编辑按钮
            const editBtn = widgetElement.querySelector('.edit-widget');
            editBtn.addEventListener('click', function(e) {
                e.stopPropagation();
                selectWidget(widgetId);
            });

            // 删除按钮
            const deleteBtn = widgetElement.querySelector('.delete-widget');
            deleteBtn.addEventListener('click', function(e) {
                e.stopPropagation();
                deleteWidget(widgetId);
            });
        }

        // 选择组件
        function selectWidget(widgetId) {
            // 移除所有组件的选中状态
            document.querySelectorAll('.chart-widget').forEach(widget => {
                widget.style.boxShadow = 'none';
            });

            // 添加选中状态
            const widgetElement = document.getElementById(widgetId);
            if (widgetElement) {
                widgetElement.style.boxShadow = '0 0 0 2px #4dabf7';
            }

            // 更新当前选中的组件
            selectedWidget = dashboardWidgets.find(w => w.id === widgetId);

            // 更新属性面板
            updatePropertiesPanel();
        }

        // 更新属性面板
        function updatePropertiesPanel() {
            if (!selectedWidget) {
                // 如果没有选中组件，清空属性面板
                document.getElementById('chartTitle').value = '';
                document.getElementById('chartWidth').value = '2';
                document.getElementById('chartHeight').value = '2';
                document.getElementById('dataSourceConfig').value = '';
                return;
            }

            // 更新属性值
            document.getElementById('chartTitle').value = selectedWidget.title;
            document.getElementById('chartWidth').value = selectedWidget.width;
            document.getElementById('chartHeight').value = selectedWidget.height;
            document.getElementById('showBorder').value = selectedWidget.showBorder.toString();
            document.getElementById('dataSourceType').value = selectedWidget.dataSourceType;
            document.getElementById('dataSourceConfig').value = selectedWidget.dataSourceConfig;

            // 更新颜色选择器
            document.querySelectorAll('.color-option').forEach(option => {
                option.classList.remove('selected');
                if (option.dataset.color === selectedWidget.color) {
                    option.classList.add('selected');
                }
            });
        }

        // 应用组件属性
        function applyWidgetProperties() {
            if (!selectedWidget) {
                showNotification('请先选择一个图表组件', 'error');
                return;
            }

            // 获取属性值
            const title = document.getElementById('chartTitle').value;
            const width = parseInt(document.getElementById('chartWidth').value);
            const height = parseInt(document.getElementById('chartHeight').value);
            const showBorder = document.getElementById('showBorder').value === 'true';
            const dataSourceType = document.getElementById('dataSourceType').value;
            const dataSourceConfig = document.getElementById('dataSourceConfig').value;
            const color = document.querySelector('.color-option.selected').dataset.color;

            // 验证属性
            if (!title.trim()) {
                showNotification('图表标题不能为空', 'error');
                return;
            }

            if (width < 1 || width > 12) {
                showNotification('宽度必须在1-12之间', 'error');
                return;
            }

            if (height < 1 || height > 6) {
                showNotification('高度必须在1-6之间', 'error');
                return;
            }

            // 更新组件属性
            selectedWidget.title = title;
            selectedWidget.width = width;
            selectedWidget.height = height;
            selectedWidget.showBorder = showBorder;
            selectedWidget.dataSourceType = dataSourceType;
            selectedWidget.dataSourceConfig = dataSourceConfig;
            selectedWidget.color = color;

            // 重新渲染
            renderDashboardWidgets();

            // 重新选中组件
            selectWidget(selectedWidget.id);

            showNotification('属性已应用', 'success');
        }

        // 删除组件
        function deleteWidget(widgetId) {
            if (confirm('确定要删除这个图表组件吗？')) {
                // 从组件列表中移除
                dashboardWidgets = dashboardWidgets.filter(w => w.id !== widgetId);

                // 重新渲染
                renderDashboardWidgets();

                // 清空属性面板
                selectedWidget = null;
                updatePropertiesPanel();

                // 如果没有组件了，显示空状态
                if (dashboardWidgets.length === 0) {
                    emptyDashboard.style.display = 'block';
                }

                showNotification('图表组件已删除', 'success');
            }
        }

        // 保存仪表盘
        function saveDashboard() {
            if (dashboardWidgets.length === 0) {
                showNotification('仪表盘为空，无法保存', 'error');
                return;
            }

            // 模拟保存到服务器
            showNotification('正在保存仪表盘配置...', 'success');

            setTimeout(() => {
                showNotification('仪表盘配置已保存', 'success');
            }, 1000);
        }

        // 创建新仪表盘
        function createNewDashboard() {
            const name = document.getElementById('newDashboardName').value;
            const description = document.getElementById('newDashboardDescription').value;
            const template = document.getElementById('newDashboardTemplate').value;
            const shared = document.getElementById('newDashboardShared').value;

            if (!name.trim()) {
                showNotification('请输入仪表盘名称', 'error');
                return;
            }

            // 模拟创建新仪表盘
            showNotification('正在创建新仪表盘...', 'success');

            setTimeout(() => {
                // 清空当前仪表盘
                dashboardWidgets = [];
                renderDashboardWidgets();
                selectedWidget = null;
                updatePropertiesPanel();
                emptyDashboard.style.display = 'block';

                // 添加到仪表盘列表
                const newDashboard = {
                    id: dashboardList.length + 1,
                    name: name,
                    description: description,
                    createTime: new Date().toISOString().split('T')[0],
                    chartCount: 0,
                    status: '草稿'
                };

                dashboardList.unshift(newDashboard);
                renderDashboardList();

                // 关闭模态框
                newDashboardModal.classList.remove('active');
                showNotification('新仪表盘创建成功', 'success');
            }, 1500);
        }

        // 导入模板
        function importTemplate() {
            const templateCards = document.querySelectorAll('.template-card');
            let selectedTemplate = null;

            templateCards.forEach(card => {
                if (card.style.border === '2px solid rgb(26, 58, 143)') {
                    selectedTemplate = card.dataset.template;
                }
            });

            if (!selectedTemplate) {
                showNotification('请选择一个模板', 'error');
                return;
            }

            // 模拟导入模板
            showNotification('正在导入模板...', 'success');

            setTimeout(() => {
                // 根据模板类型添加示例组件
                dashboardWidgets = [];

                if (selectedTemplate === 'project-progress') {
                    // 项目进度监控模板
                    dashboardWidgets = [
                        {
