                            x: 9, y: 0, width: 3, height: 3,
                            color: '#FF9800',
                            showBorder: true,
                            dataSourceType: 'static',
                            dataSourceConfig: '{"data": [{"module": "用户管理", "progress": 85}, {"module": "项目管理", "progress": 70}, {"module": "测试用例", "progress": 90}]}'
                        },
                        {
                            id: 'widget_4',
                            type: 'table',
                            title: '任务清单',
                            x: 0, y: 3, width: 12, height: 3,
                            color: '#9C27B0',
                            showBorder: true,
                            dataSourceType: 'sql',
                            dataSourceConfig: '{"query": "SELECT task_name, assignee, status, due_date FROM project_tasks WHERE project_id = 1"}'
                        }
                    ];
                } else if (selectedTemplate === 'defect-analysis') {
                    // 缺陷分析模板
                    dashboardWidgets = [
                        {
                            id: 'widget_1',
                            type: 'pie',
                            title: '缺陷严重程度分布',
                            x: 0, y: 0, width: 4, height: 3,
                            color: '#1a3a8f',
                            showBorder: true,
                            dataSourceType: 'api',
                            dataSourceConfig: '{"endpoint": "/api/defects/severity-distribution"}'
                        },
                        {
                            id: 'widget_2',
                            type: 'bar',
                            title: '缺陷状态统计',
                            x: 4, y: 0, width: 4, height: 3,
                            color: '#4CAF50',
                            showBorder: true,
                            dataSourceType: 'sql',
                            dataSourceConfig: '{"query": "SELECT status, COUNT(*) as count FROM defects GROUP BY status"}'
                        },
                        {
                            id: 'widget_3',
                            type: 'line',
                            title: '缺陷趋势',
                            x: 8, y: 0, width: 4, height: 3,
                            color: '#FF9800',
                            showBorder: true,
                            dataSourceType: 'static',
                            dataSourceConfig: '{"data": [{"date": "2025-11-01", "new": 12, "fixed": 8}, {"date": "2025-11-02", "new": 8, "fixed": 10}]}'
                        },
                        {
                            id: 'widget_4',
                            type: 'table',
                            title: '缺陷列表',
                            x: 0, y: 3, width: 12, height: 3,
                            color: '#9C27B0',
