            list-style: none;
            gap: 5px;
        }

        .page-item {
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .page-link {
            width: 40px;
            height: 40px;
            display: flex;
            align-items: center;
            justify-content: center;
            border-radius: 6px;
            background-color: white;
            border: 1px solid #ddd;
            color: #555;
            text-decoration: none;
            cursor: pointer;
            transition: all 0.2s ease;
        }

        .page-link:hover {
            background-color: #f0f5ff;
            border-color: #1a3a8f;
            color: #1a3a8f;
        }

        .page-link.active {
            background-color: #1a3a8f;
            border-color: #1a3a8f;
            color: white;
        }

        .page-link.disabled {
            background-color: #f5f5f5;
            color: #999;
            cursor: not-allowed;
        }

        .pagination-info {
            margin-left: 20px;
            color: #666;
            font-size: 14px;
        }

        /* 统计卡片 */
        .stats-container {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
            gap: 20px;
            margin-bottom: 30px;
        }

        .stat-card {
            background-color: white;
            border-radius: 10px;
            padding: 20px;
            box-shadow: 0 3px 10px rgba(0, 0, 0, 0.05);
            border-left: 4px solid #1a3a8f;
        }

        .stat-title {
            font-size: 14px;
            color: #666;
            margin-bottom: 10px;
        }

        .stat-value {
            font-size: 28px;
            font-weight: 600;
            color: #1a3a8f;
        }

        .stat-trend {
            font-size: 12px;
            margin-top: 5px;
        }

        .trend-up {
            color: #059669;
        }

        .trend-down {
            color: #dc2626;
        }

        /* 图表容器 */
        .charts-container {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
            gap: 20px;
            margin-bottom: 30px;
        }

        .chart-card {
            background-color: white;
            border-radius: 10px;
            padding: 20px;
            box-shadow: 0 3px 10px rgba(0, 0, 0, 0.05);
        }

        .chart-title {
            font-size: 16px;
            font-weight: 600;
            color: #1a3a8f;
            margin-bottom: 15px;
        }

        .chart-placeholder {
            height: 200px;
            background-color: #f8fafd;
            border-radius: 6px;
            display: flex;
            align-items: center;
            justify-content: center;
            color: #999;
        }

        /* 模态框样式 */
        .modal-overlay {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background-color: rgba(0, 0, 0, 0.5);
            display: flex;
            align-items: center;
            justify-content: center;
            z-index: 100;
            opacity: 0;
            visibility: hidden;
            transition: all 0.3s ease;
        }

        .modal-overlay.active {
            opacity: 1;
            visibility: visible;
        }

        .modal {
            background-color: white;
            border-radius: 12px;
            width: 700px;
            max-width: 90%;
            max-height: 90vh;
            overflow-y: auto;
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
            transform: translateY(20px);
            transition: transform 0.3s ease;
        }

        .modal-overlay.active .modal {
            transform: translateY(0);
        }

        .modal-header {
            padding: 25px 30px;
            border-bottom: 1px solid #eee;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .modal-title {
            font-size: 20px;
            font-weight: 600;
            color: #1a3a8f;
        }

        .modal-close {
            background: none;
            border: none;
            font-size: 20px;
            cursor: pointer;
            color: #999;
            transition: color 0.2s;
        }

        .modal-close:hover {
            color: #333;
        }

        .modal-body {
            padding: 30px;
        }

        .form-group {
            margin-bottom: 20px;
        }

        .form-row {
            display: flex;
            gap: 20px;
            margin-bottom: 20px;
        }

        .form-col {
            flex: 1;
        }

        .form-label {
            display: block;
            margin-bottom: 8px;
            font-weight: 500;
            color: #555;
        }

        .form-control {
            width: 100%;
            padding: 12px 15px;
            border: 1px solid #ddd;
            border-radius: 6px;
            font-size: 15px;
            transition: border 0.2s;
        }

        .form-control:focus {
            outline: none;
            border-color: #1a3a8f;
            box-shadow: 0 0 0 3px rgba(26, 58, 143, 0.1);
        }

        .select-control {
            width: 100%;
            padding: 12px 15px;
            border: 1px solid #ddd;
            border-radius: 6px;
            font-size: 15px;
            background-color: white;
            transition: border 0.2s;
        }

        .textarea-control {
            width: 100%;
            padding: 12px 15px;
            border: 1px solid #ddd;
            border-radius: 6px;
            font-size: 15px;
            min-height: 100px;
            resize: vertical;
            transition: border 0.2s;
        }

        .textarea-control:focus {
            outline: none;
            border-color: #1a3a8f;
            box-shadow: 0 0 0 3px rgba(26, 58, 143, 0.1);
        }

        .modal-footer {
            padding: 20px 30px;
            border-top: 1px solid #eee;
            display: flex;
            justify-content: flex-end;
            gap: 15px;
        }

        /* 过滤器 */
        .filter-container {
            background-color: #f8fafd;
            border-radius: 8px;
            padding: 20px;
            margin-bottom: 20px;
            display: flex;
            flex-wrap: wrap;
            gap: 15px;
            align-items: flex-end;
        }

        .filter-group {
            flex: 1;
            min-width: 150px;
        }

        .filter-label {
            display: block;
            margin-bottom: 8px;
            font-size: 14px;
            font-weight: 500;
            color: #555;
        }

        .export-buttons {
            display: flex;
            gap: 10px;
        }

        /* 响应式设计 */
        @media (max-width: 1200px) {
            .sidebar {
                width: 250px;
            }

            .charts-container {
                grid-template-columns: 1fr;
            }
        }

        @media (max-width: 992px) {
            .sidebar {
                position: fixed;
                left: -280px;
                transition: left 0.3s ease;
            }

            .sidebar.active {
                left: 0;
            }

            .mobile-menu-toggle {
                display: flex;
            }

            .stats-container {
                grid-template-columns: repeat(2, 1fr);
            }

            .form-row {
                flex-direction: column;
                gap: 0;
            }
        }

        .mobile-menu-toggle {
            display: none;
            background: none;
            border: none;
            font-size: 20px;
            color: #1a3a8f;
            cursor: pointer;
        }

        @media (max-width: 768px) {
            .stats-container {
                grid-template-columns: 1fr;
            }

            .content-area {
                padding: 15px;
            }

            .module-card {
                padding: 20px;
            }

            .action-buttons {
                flex-wrap: wrap;
            }
        }

        /* 空状态 */
        .empty-state {
            text-align: center;
            padding: 60px 20px;
            color: #999;
        }

        .empty-state i {
            font-size: 50px;
            margin-bottom: 20px;
            opacity: 0.5;
        }

        .empty-state h3 {
            font-size: 18px;
            margin-bottom: 10px;
            color: #666;
        }

        /* 租户到期提醒 */
        .expiry-warning {
            display: inline-flex;
            align-items: center;
            gap: 5px;
            color: #d97706;
            font-size: 13px;
            margin-top: 5px;
        }

        /* 租户logo预览 */
        .tenant-logo-preview {
            width: 60px;
            height: 60px;
            border-radius: 8px;
            background-color: #f0f5ff;
            display: flex;
            align-items: center;
            justify-content: center;
            overflow: hidden;
            border: 1px solid #ddd;
        }

        .tenant-logo-preview img {
            max-width: 100%;
            max-height: 100%;
        }

        /* 操作提示 */
        .operation-hint {
            background-color: #f0f5ff;
            border-left: 4px solid #1a3a8f;
            padding: 15px;
            margin-bottom: 20px;
            border-radius: 4px;
        }

        .operation-hint h4 {
            margin-bottom: 8px;
            color: #1a3a8f;
        }

        .operation-hint ul {
            padding-left: 20px;
        }

        .operation-hint li {
            margin-bottom: 5px;
        }
    </style>
</head>
<body>
    <!-- 左侧导航栏 -->
    <div class="sidebar" id="sidebar">
        <div class="logo-container">
            <div class="logo">
                <i class="fas fa-cogs"></i>
            </div>
            <div class="logo-text">
                <h1>适配中心测试管理软件</h1>
                <p>V1.0</p>
            </div>
        </div>

        <div class="directory-container">
            <div class="directory-title">功能目录</div>
            <ul class="directory-tree" id="directoryTree">
                <!-- 目录树将通过JavaScript动态生成 -->
            </ul>
        </div>
    </div>

    <!-- 右侧主内容区 -->
    <div class="main-content">
        <div class="top-bar">
            <button class="mobile-menu-toggle" id="mobileMenuToggle">
                <i class="fas fa-bars"></i>
            </button>
            <div class="page-title" id="pageTitle">租户管理</div>
            <div class="user-info">
                <div class="user-avatar">刘</div>
                <div>
                    <div style="font-weight: 500;">刘贺</div>
                    <div style="font-size: 13px; color: #666;">系统管理员</div>
                </div>
            </div>
        </div>

        <div class="content-area" id="contentArea">
            <!-- 统计卡片 -->
            <div class="stats-container">
                <div class="stat-card">
                    <div class="stat-title">总租户数</div>
                    <div class="stat-value" id="totalTenants">28</div>
                    <div class="stat-trend trend-up">较上月 ↑ 15%</div>
                </div>
                <div class="stat-card">
                    <div class="stat-title">活跃租户</div>
                    <div class="stat-value" id="activeTenants">22</div>
                    <div class="stat-trend trend-up">较上月 ↑ 10%</div>
                </div>
                <div class="stat-card">
                    <div class="stat-title">即将到期租户</div>
                    <div class="stat-value" id="expiringTenants">5</div>
                    <div class="stat-trend trend-up">需关注</div>
                </div>
                <div class="stat-card">
                    <div class="stat-title">已禁用租户</div>
                    <div class="stat-value" id="disabledTenants">3</div>
                    <div class="stat-trend trend-down">较上月 ↓ 2%</div>
                </div>
            </div>

            <!-- 操作提示 -->
            <div class="operation-hint">
                <h4>租户管理功能说明</h4>
                <ul>
                    <li><strong>租户创建</strong>：点击"新增租户"按钮，填写租户编码、名称、联系人等信息，选择数据隔离模式（独立Schema/共享表）</li>
                    <li><strong>租户管理</strong>：在租户列表中可进行编辑、启用/禁用、删除操作，支持按状态和隔离模式筛选</li>
                    <li><strong>状态监控</strong>：顶部统计卡片实时显示总租户数、活跃租户、即将到期租户和已禁用租户</li>
                    <li><strong>数据隔离</strong>：系统自动为不同租户实施数据隔离，防止数据越权访问</li>
                </ul>
            </div>

            <!-- 租户管理模块 -->
            <div class="module-card" id="tenantManagementCard">
                <div class="module-header">
                    <div>
                        <div class="module-title">租户管理</div>
                        <div class="module-subtitle">支持多租户数据隔离与独立管理，提供租户创建、编辑、启用/禁用、删除等完整生命周期管理功能</div>
                    </div>
                    <div class="action-buttons">
                        <button class="btn btn-primary" id="addTenantBtn">
                            <i class="fas fa-plus-circle"></i> 新增租户
                        </button>
                        <button class="btn btn-secondary" id="refreshTenantsBtn">
                            <i class="fas fa-sync-alt"></i> 刷新
                        </button>
                        <button class="btn btn-secondary" id="exportTenantsBtn">
                            <i class="fas fa-file-export"></i> 导出
                        </button>
                    </div>
                </div>

                <!-- 过滤器 -->
                <div class="filter-container">
                    <div class="filter-group">
                        <label class="filter-label">租户状态</label>
                        <select class="select-control" id="statusFilter">
                            <option value="">全部状态</option>
                            <option value="active">启用</option>
                            <option value="inactive">禁用</option>
                            <option value="expiring">即将到期</option>
                        </select>
                    </div>
                    <div class="filter-group">
                        <label class="filter-label">数据隔离模式</label>
                        <select class="select-control" id="isolationFilter">
                            <option value="">全部模式</option>
                            <option value="independent">独立Schema</option>
                            <option value="shared">共享表</option>
                        </select>
                    </div>
                    <div class="filter-group">
                        <label class="filter-label">搜索</label>
                        <input type="text" class="form-control" id="searchFilter" placeholder="租户编码/名称/联系人">
                    </div>
                    <div class="export-buttons">
                        <button class="btn btn-secondary" id="applyFiltersBtn">
                            <i class="fas fa-filter"></i> 筛选
                        </button>
                        <button class="btn btn-secondary" id="resetFiltersBtn">
                            <i class="fas fa-redo"></i> 重置
                        </button>
                    </div>
                </div>

                <!-- 租户列表表格 -->
                <div class="table-container">
                    <table id="tenantsTable">
                        <thead>
                            <tr>
                                <th width="10%">租户编码</th>
                                <th width="18%">租户名称</th>
                                <th width="12%">联系人</th>
                                <th width="15%">联系电话</th>
                                <th width="10%">状态</th>
                                <th width="15%">数据隔离模式</th>
                                <th width="12%">到期时间</th>
                                <th width="8%">操作</th>
                            </tr>
                        </thead>
                        <tbody id="tenantsTableBody">
                            <!-- 表格数据将通过JavaScript动态生成 -->
                        </tbody>
                    </table>
                </div>

                <!-- 分页组件 -->
                <div class="pagination-container">
                    <ul class="pagination" id="pagination">
                        <!-- 分页按钮将通过JavaScript动态生成 -->
                    </ul>
                    <div class="pagination-info" id="paginationInfo">
                        显示 1-10 条，共 28 条
                    </div>
                </div>

                <!-- 空状态 -->
                <div class="empty-state" id="emptyState" style="display: none;">
                    <i class="fas fa-building"></i>
                    <h3>暂无租户数据</h3>
                    <p>当前筛选条件下未找到租户记录</p>
                </div>
            </div>

            <!-- 租户数据隔离说明 -->
            <div class="module-card">
                <div class="module-header">
                    <div class="module-title">数据隔离机制说明</div>
                </div>
                <div style="line-height: 1.6;">
                    <p>本系统支持两种数据隔离模式，确保不同租户数据的独立性与安全性：</p>
                    <ul style="margin-top: 15px; padding-left: 20px;">
                        <li style="margin-bottom: 10px;"><strong>独立Schema模式</strong>：每个租户拥有独立的数据库Schema，数据物理隔离，安全性最高，适用于对数据安全要求严格的场景。</li>
                        <li style="margin-bottom: 10px;"><strong>共享表模式</strong>：所有租户共享同一套数据库表，通过tenant_id字段实现逻辑隔离，资源利用率高，适用于中小型租户场景。</li>
                        <li style="margin-bottom: 10px;"><strong>自动数据隔离</strong>：系统自动为不同租户实施数据隔离，防止数据越权访问，所有数据操作自动附加租户过滤条件。</li>
                        <li style="margin-bottom: 10px;"><strong>跨租户管理</strong>：管理员可在系统层面查看所有租户，普通用户只能访问所属租户的数据。</li>
                    </ul>
                </div>
            </div>
        </div>
    </div>

    <!-- 新增/编辑租户模态框 -->
    <div class="modal-overlay" id="tenantModal">
        <div class="modal">
            <div class="modal-header">
                <div class="modal-title" id="modalTitle">新增租户</div>
                <button class="modal-close" id="closeTenantModalBtn">
                    <i class="fas fa-times"></i>
                </button>
            </div>
            <div class="modal-body">
                <form id="tenantForm">
                    <div class="form-row">
                        <div class="form-col">
                            <div class="form-group">
                                <label class="form-label" for="tenantCode">租户编码 <span style="color: #dc2626;">*</span></label>
                                <input type="text" class="form-control" id="tenantCode" required placeholder="唯一标识，如：TENANT001">
                                <div class="expiry-warning" id="codeWarning" style="display: none;">
                                    <i class="fas fa-exclamation-triangle"></i>
                                    <span>该租户编码已存在</span>
                                </div>
                            </div>
                        </div>
                        <div class="form-col">
                            <div class="form-group">
                                <label class="form-label" for="tenantName">租户名称 <span style="color: #dc2626;">*</span></label>
                                <input type="text" class="form-control" id="tenantName" required placeholder="如：华东适配中心">
                            </div>
                        </div>
                    </div>

                    <div class="form-group">
                        <label class="form-label" for="description">租户描述</label>
                        <textarea class="textarea-control" id="description" placeholder="租户业务描述或备注信息"></textarea>
                    </div>

                    <div class="form-row">
                        <div class="form-col">
                            <div class="form-group">
                                <label class="form-label" for="contactName">联系人姓名 <span style="color: #dc2626;">*</span></label>
                                <input type="text" class="form-control" id="contactName" required placeholder="如：张三">
                            </div>
                        </div>
                        <div class="form-col">
                            <div class="form-group">
                                <label class="form-label" for="contactPhone">联系电话 <span style="color: #dc2626;">*</span></label>
                                <input type="text" class="form-control" id="contactPhone" required placeholder="如：13800138000">
                            </div>
                        </div>
                    </div>

                    <div class="form-row">
                        <div class="form-col">
                            <div class="form-group">
                                <label class="form-label" for="contactEmail">联系邮箱</label>
                                <input type="email" class="form-control" id="contactEmail" placeholder="如：contact@example.com">
                            </div>
                        </div>
                        <div class="form-col">
                            <div class="form-group">
                                <label class="form-label" for="maxUsers">最大用户数</label>
                                <input type="number" class="form-control" id="maxUsers" placeholder="0表示无限制" min="0">
                            </div>
                        </div>
                    </div>

                    <div class="form-row">
                        <div class="form-col">
                            <div class="form-group">
                                <label class="form-label" for="dataIsolationMode">数据隔离模式 <span style="color: #dc2626;">*</span></label>
                                <select class="select-control" id="dataIsolationMode" required>
                                    <option value="">请选择数据隔离模式</option>
                                    <option value="independent">独立Schema</option>
                                    <option value="shared">共享表</option>
                                </select>
                            </div>
                        </div>
                        <div class="form-col">
                            <div class="form-group">
                                <label class="form-label" for="schemaName">Schema名称</label>
                                <input type="text" class="form-control" id="schemaName" placeholder="独立Schema模式下必填">
                            </div>
                        </div>
                    </div>

                    <div class="form-row">
                        <div class="form-col">
                            <div class="form-group">
                                <label class="form-label" for="expireTime">到期时间</label>
                                <input type="date" class="form-control" id="expireTime">
                            </div>
                        </div>
                        <div class="form-col">
                            <div class="form-group">
                                <label class="form-label" for="status">租户状态</label>
                                <select class="select-control" id="status">
                                    <option value="active">启用</option>
                                    <option value="inactive">禁用</option>
                                </select>
                            </div>
                        </div>
                    </div>

                    <div class="form-group">
                        <label class="form-label" for="logoUrl">租户Logo URL</label>
                        <input type="text" class="form-control" id="logoUrl" placeholder="可选，输入Logo图片URL地址">
                        <div style="margin-top: 10px;" id="logoPreviewContainer">
                            <div class="tenant-logo-preview" id="logoPreview">
                                <i class="fas fa-building" style="color: #1a3a8f; font-size: 24px;"></i>
                            </div>
                        </div>
                    </div>

                    <div class="form-group">
                        <label class="form-label" for="customConfig">自定义配置 (JSON格式)</label>
                        <textarea class="textarea-control" id="customConfig" placeholder='{"theme": "blue", "language": "zh-CN"}' rows="3"></textarea>
                    </div>
                </form>
            </div>
            <div class="modal-footer">
                <button class="btn btn-secondary" id="cancelTenantBtn">取消</button>
                <button class="btn btn-primary" id="saveTenantBtn">保存租户</button>
            </div>
        </div>
    </div>

    <script>
        // 目录结构数据
        const directoryData = [
            {
                id: "user-management",
                title: "用户与权限管理",
                icon: "fas fa-user-shield",
                expanded: true,
                subItems: [
                    { id: "role-access-control", title: "角色-权限-访问控制", icon: "fas fa-key" },
                    { id: "tenant-management", title: "租户管理", icon: "fas fa-building" },
                    { 
                        id: "login-security", 
                        title: "登录与安全", 
                        icon: "fas fa-lock",
                        subItems: [
