            document.getElementById('cancelLogoutBtn').addEventListener('click', closeLogoutConfirmModal);
            document.getElementById('confirmLogoutBtn').addEventListener('click', confirmLogout);
        }

        // 保存配置
        function saveConfig() {
            const sessionTimeout = document.getElementById('sessionTimeout').value;
            const warningTime = document.getElementById('warningTime').value;
            const maxConcurrent = document.getElementById('maxConcurrent').value;
            const failedAttempts = document.getElementById('failedAttempts').value;
            const lockoutDuration = document.getElementById('lockoutDuration').value;

            // 简单验证
            if (sessionTimeout < 1 || sessionTimeout > 480) {
                showNotification('会话超时时间应在1-480分钟之间', 'error');
                return;
            }

            if (warningTime < 1 || warningTime > 60) {
                showNotification('警告时间应在1-60分钟之间', 'error');
                return;
            }

            // 模拟保存到服务器
            showNotification('配置已保存成功', 'success');

            // 更新统计信息
            updateStats();
        }

        // 恢复默认配置
        function resetConfig() {
            document.getElementById('sessionTimeout').value = 30;
            document.getElementById('warningTime').value = 5;
            document.getElementById('maxConcurrent').value = 3;
            document.getElementById('failedAttempts').value = 5;
            document.getElementById('lockoutDuration').value = 15;

            showNotification('已恢复默认配置', 'success');
        }

