        // 更新统计信息
        function updateStats() {
            // 活跃会话数
            const activeSessionCount = activeSessionsData.length;
            document.getElementById('activeSessionCount').textContent = activeSessionCount;

            // 即将超时会话数
            const expiringSessionCount = activeSessionsData.filter(s => s.status === 'expiring').length;
            document.getElementById('expiringSessionCount').textContent = expiringSessionCount;

            // 今日新登录数（模拟）
            document.getElementById('todayLoginCount').textContent = 24;

            // 平均会话时长（模拟）
            document.getElementById('avgSessionTime').textContent = '45m';
        }

        // 应用活跃会话筛选
        function applySessionFilters() {
            const roleFilter = document.getElementById('sessionRoleFilter').value;
            const statusFilter = document.getElementById('sessionStatusFilter').value;

            filteredActiveSessions = activeSessionsData.filter(session => {
                return (!roleFilter || session.role === roleMap(roleFilter)) &&
                       (!statusFilter || session.status === statusFilter);
            });

            currentActivePage = 1;
            renderActiveSessionsTable();
            renderActiveSessionsPagination();
        }

        // 角色映射函数
        function roleMap(roleValue) {
            switch(roleValue) {
                case 'admin': return '管理员';
                case 'pm': return '项目经理';
                case 'engineer': return '测试工程师';
                case 'viewer': return '观察员';
                default: return roleValue;
            }
        }

        // 重置活跃会话筛选
        function resetSessionFilters() {
            document.getElementById('sessionRoleFilter').value = '';
            document.getElementById('sessionStatusFilter').value = '';

            filteredActiveSessions = [...activeSessionsData];
            currentActivePage = 1;
            renderActiveSessionsTable();
            renderActiveSessionsPagination();
        }

        // 应用历史会话筛选
