            const userFilter = document.getElementById('historyUserFilter').value.toLowerCase();
            const dateFrom = document.getElementById('historyDateFrom').value;
            const dateTo = document.getElementById('historyDateTo').value;
            const statusFilter = document.getElementById('historyStatusFilter').value;

            filteredSessionHistory = sessionHistoryData.filter(history => {
                const matchesUser = !userFilter || 
                    history.username.toLowerCase().includes(userFilter) || 
                    history.name.toLowerCase().includes(userFilter);

                const matchesStatus = !statusFilter || history.status === statusFilter;

                // 简化日期筛选（实际应用中需要更复杂的日期处理）
                const loginDate = history.loginTime.split(' ')[0];
                const matchesDate = (!dateFrom || loginDate >= dateFrom) && 
                                   (!dateTo || loginDate <= dateTo);

                return matchesUser && matchesStatus && matchesDate;
            });

            currentHistoryPage = 1;
            renderSessionHistoryTable();
            renderSessionHistoryPagination();
        }

        // 重置历史会话筛选
        function resetHistoryFilters() {
            document.getElementById('historyUserFilter').value = '';
            document.getElementById('historyDateFrom').value = '2025-11-01';
