        // 渲染活跃会话表格
        function renderActiveSessionsTable() {
            const tableBody = document.getElementById('activeSessionsTableBody');
            const emptyState = document.getElementById('activeSessionsEmptyState');

            if (filteredActiveSessions.length === 0) {
                tableBody.innerHTML = '';
                emptyState.style.display = 'block';
                return;
            }

            emptyState.style.display = 'none';

            // 计算当前页的数据
            const startIndex = (currentActivePage - 1) * itemsPerPage;
            const endIndex = Math.min(startIndex + itemsPerPage, filteredActiveSessions.length);
            const currentSessions = filteredActiveSessions.slice(startIndex, endIndex);

            tableBody.innerHTML = '';

            currentSessions.forEach(session => {
                // 确定状态徽章
                let statusBadgeClass = '';
                let statusText = '';
                switch(session.status) {
                    case 'active':
                        statusBadgeClass = 'status-active';
                        statusText = '活跃';
                        break;
                    case 'expiring':
                        statusBadgeClass = 'status-expiring';
                        statusText = '即将超时';
                        break;
                    case 'idle':
                        statusBadgeClass = 'status-inactive';
                        statusText = '空闲';
                        break;
                }

                const row = document.createElement('tr');
                row.innerHTML = `
                    <td><input type="checkbox" class="session-checkbox" data-id="${session.id}" ${session.isSelected ? 'checked' : ''}></td>
                    <td>${session.username}</td>
