                `;

                tableBody.appendChild(row);
            });

            // 绑定复选框事件
            document.querySelectorAll('.session-checkbox').forEach(checkbox => {
                checkbox.addEventListener('change', (e) => {
                    const sessionId = parseInt(e.target.dataset.id);
                    const session = activeSessionsData.find(s => s.id === sessionId);
                    if (session) {
                        session.isSelected = e.target.checked;
                    }
                });
            });

            // 绑定强制注销按钮事件
            document.querySelectorAll('.logout-icon').forEach(icon => {
                icon.addEventListener('click', (e) => {
                    const sessionId = parseInt(e.currentTarget.dataset.id);
                    showLogoutConfirm('single', sessionId);
                });
            });
        }

        // 渲染活跃会话分页
        function renderActiveSessionsPagination() {
            const totalPages = Math.ceil(filteredActiveSessions.length / itemsPerPage);
            const pagination = document.getElementById('activeSessionsPagination');
            const paginationInfo = document.getElementById('activeSessionsPaginationInfo');

            // 更新分页信息
            const startItem = (currentActivePage - 1) * itemsPerPage + 1;
            const endItem = Math.min(currentActivePage * itemsPerPage, filteredActiveSessions.length);
            paginationInfo.textContent = `显示 ${startItem}-${endItem} 条，共 ${filteredActiveSessions.length} 条`;

            // 生成分页按钮
            pagination.innerHTML = '';

            // 上一页按钮
            const prevLi = document.createElement('li');
            prevLi.className = 'page-item';
            prevLi.innerHTML = `<a class="page-link ${currentActivePage === 1 ? 'disabled' : ''}" href="#" data-page="${currentActivePage - 1}"><i class="fas fa-chevron-left"></i></a>`;
            pagination.appendChild(prevLi);

            // 页码按钮
            const maxVisiblePages = 5;
            let startPage = Math.max(1, currentActivePage - Math.floor(maxVisiblePages / 2));
            let endPage = Math.min(totalPages, startPage + maxVisiblePages - 1);

            // 调整起始页，确保显示maxVisiblePages个页码
            if (endPage - startPage + 1 < maxVisiblePages) {
                startPage = Math.max(1, endPage - maxVisiblePages + 1);
            }

            for (let i = startPage; i <= endPage; i++) {
                const pageLi = document.createElement('li');
                pageLi.className = 'page-item';
                pageLi.innerHTML = `<a class="page-link ${i === currentActivePage ? 'active' : ''}" href="#" data-page="${i}">${i}</a>`;
                pagination.appendChild(pageLi);
            }

            // 下一页按钮
            const nextLi = document.createElement('li');
            nextLi.className = 'page-item';
            nextLi.innerHTML = `<a class="page-link ${currentActivePage === totalPages ? 'disabled' : ''}" href="#" data-page="${currentActivePage + 1}"><i class="fas fa-chevron-right"></i></a>`;
            pagination.appendChild(nextLi);

            // 绑定分页点击事件
            document.querySelectorAll('#activeSessionsPagination .page-link').forEach(link => {
                link.addEventListener('click', (e) => {
                    e.preventDefault();

                    if (link.classList.contains('disabled')) return;

                    const page = parseInt(link.dataset.page);
                    if (!isNaN(page)) {
                        currentActivePage = page;
                        renderActiveSessionsTable();
                        renderActiveSessionsPagination();
                    }
                });
            });
        }

        // 渲染会话历史表格
        function renderSessionHistoryTable() {
            const tableBody = document.getElementById('sessionHistoryTableBody');
            const emptyState = document.getElementById('sessionHistoryEmptyState');

            if (filteredSessionHistory.length === 0) {
                tableBody.innerHTML = '';
                emptyState.style.display = 'block';
                return;
            }

            emptyState.style.display = 'none';

            // 计算当前页的数据
            const startIndex = (currentHistoryPage - 1) * itemsPerPage;
            const endIndex = Math.min(startIndex + itemsPerPage, filteredSessionHistory.length);
            const currentHistory = filteredSessionHistory.slice(startIndex, endIndex);

            tableBody.innerHTML = '';

            currentHistory.forEach(history => {
                // 确定状态徽章
                let statusBadgeClass = '';
                let statusText = '';
                switch(history.status) {
                    case 'success':
                        statusBadgeClass = 'status-active';
                        statusText = '成功';
                        break;
                    case 'failed':
                        statusBadgeClass = 'status-expired';
                        statusText = '失败';
                        break;
                }

                const row = document.createElement('tr');
                row.innerHTML = `
                    <td>${history.username}</td>
