        // 初始化目录树
        function initDirectoryTree() {
            directoryTree.innerHTML = '';

            directoryData.forEach(section => {
                const li = document.createElement('li');
                li.className = 'tree-item';

                const header = document.createElement('div');
                header.className = 'tree-header';
                if (section.expanded) header.classList.add('active');
                header.dataset.id = section.id;

                header.innerHTML = `
                    <div class="tree-title">
                        <i class="${section.icon}"></i>
                        <span>${section.title}</span>
                    </div>
                    <div class="tree-toggle ${section.expanded ? '' : 'collapsed'}">
                        <i class="fas fa-chevron-down"></i>
                    </div>
                `;

                const content = document.createElement('ul');
                content.className = `tree-content ${section.expanded ? 'expanded' : ''}`;

                section.subItems.forEach(subItem => {
                    const subLi = document.createElement('li');
                    subLi.className = 'tree-subitem';
                    subLi.dataset.id = subItem.id;
                    subLi.dataset.parentId = section.id;

                    let iconHtml = '';
                    if (subItem.icon) {
                        iconHtml = `<i class="${subItem.icon}"></i>`;
                    }

                    subLi.innerHTML = `${iconHtml}<span>${subItem.title}</span>`;

                    // 默认选中项目看板
                    if (subItem.active) {
                        subLi.classList.add('active');
                        header.classList.add('active');
                    }

                    // 添加点击事件
                    subLi.addEventListener('click', (e) => {
                        e.stopPropagation();
                        selectMenuItem(subItem.id, subItem.title);

                        // 更新活动状态
                        document.querySelectorAll('.tree-subitem').forEach(item => {
                            item.classList.remove('active');
                        });
                        document.querySelectorAll('.tree-header').forEach(item => {
                            item.classList.remove('active');
                        });

                        subLi.classList.add('active');
                        header.classList.add('active');
                    });

                    content.appendChild(subLi);
                });

                // 添加点击事件展开/折叠
                header.addEventListener('click', () => {
                    const isExpanded = content.classList.contains('expanded');
                    const toggleIcon = header.querySelector('.tree-toggle i');

                    if (isExpanded) {
                        content.classList.remove('expanded');
                        header.querySelector('.tree-toggle').classList.add('collapsed');
                    } else {
                        content.classList.add('expanded');
                        header.querySelector('.tree-toggle').classList.remove('collapsed');
                    }
                });

                li.appendChild(header);
                li.appendChild(content);
                directoryTree.appendChild(li);
            });
