        // 刷新图表数据
        function refreshChartsData() {
            if (burnDownChartInstance) {
                // 模拟更新燃尽图数据
                const newData = burnDownChartInstance.data.datasets[1].data.map(value => {
                    // 随机调整实际工作量数据
                    const adjustment = Math.floor(Math.random() * 5) - 2;
                    return Math.max(0, value + adjustment);
                });
                burnDownChartInstance.data.datasets[1].data = newData;
                burnDownChartInstance.update();
            }

            if (defectDistributionChartInstance) {
                // 模拟更新缺陷分布数据
                const newData = defectDistributionChartInstance.data.datasets[0].data.map(value => {
                    // 随机调整缺陷数量
                    const adjustment = Math.floor(Math.random() * 3);
                    return Math.max(0, value + adjustment);
                });
                defectDistributionChartInstance.data.datasets[0].data = newData;
                defectDistributionChartInstance.update();
            }

            // 更新统计卡片数据
            updateStatsCards();

            // 显示刷新提示
            showRefreshIndicator();
        }

