        // 渲染仪表盘列表
        function renderDashboardList() {
            const dashboardList = document.getElementById('dashboardList');
            dashboardList.innerHTML = '';

            if (dashboards.length === 0) {
                dashboardList.innerHTML = `
                    <div class="empty-state" style="padding: 30px 20px;">
                        <i class="fas fa-tachometer-alt" style="font-size: 30px;"></i>
                        <h3 style="font-size: 16px; margin: 10px 0;">暂无仪表盘</h3>
                        <p style="font-size: 14px;">点击"新建仪表盘"按钮创建</p>
                    </div>
                `;
                return;
            }

            dashboards.forEach(dashboard => {
                const dashboardCard = document.createElement('div');
                dashboardCard.className = `dashboard-card ${dashboard.active ? 'active' : ''}`;
                dashboardCard.dataset.id = dashboard.id;

                dashboardCard.innerHTML = `
                    <div class="dashboard-card-header">
                        <div class="dashboard-name">${dashboard.name}</div>
                        <div class="dashboard-visibility ${dashboard.visibility}">${dashboard.visibility === 'public' ? '公开' : '私有'}</div>
