        // 渲染图表库
        function renderChartLibrary() {
            const chartLibrary = document.getElementById('chartLibrary');
            chartLibrary.innerHTML = '';

            chartTypes.forEach(chartType => {
                const chartCard = document.createElement('div');
                chartCard.className = 'chart-type-card';
                chartCard.dataset.type = chartType.id;
                chartCard.draggable = true;

                chartCard.innerHTML = `
                    <div class="chart-type-icon" style="color: ${chartType.color}">
                        <i class="${chartType.icon}"></i>
                    </div>
                    <div class="chart-type-name">${chartType.name}</div>
                    <div style="font-size: 12px; color: #888; margin-top: 5px;">${chartType.description}</div>
                `;

                // 添加拖拽事件
                chartCard.addEventListener('dragstart', handleDragStart);

                chartLibrary.appendChild(chartCard);
            });
        }

        // 渲染仪表盘网格
        function renderDashboardGrid() {
            const dashboardGrid = document.getElementById('dashboardGrid');
            const emptyDashboardState = document.getElementById('emptyDashboardState');

            if (currentDashboardCharts.length === 0) {
                dashboardGrid.style.display = 'none';
                emptyDashboardState.style.display = 'block';
                return;
            }

            dashboardGrid.style.display = 'grid';
            emptyDashboardState.style.display = 'none';
            dashboardGrid.innerHTML = '';

            currentDashboardCharts.forEach(chart => {
                const chartWidget = document.createElement('div');
                chartWidget.className = 'chart-widget';
                chartWidget.dataset.id = chart.id;
                chartWidget.style.gridColumn = chart.gridColumn;
                chartWidget.style.gridRow = chart.gridRow;
                chartWidget.draggable = true;

                // 获取图表类型信息
                const chartType = chartTypes.find(type => type.id === chart.type);

                chartWidget.innerHTML = `
                    <div class="chart-widget-header">
                        <div class="chart-widget-title">${chart.name}</div>
                        <div class="chart-widget-actions">
                            <div class="widget-action-btn edit-chart-btn" title="编辑">
                                <i class="fas fa-edit"></i>
                            </div>
                            <div class="widget-action-btn delete-chart-btn" title="删除">
                                <i class="fas fa-trash"></i>
                            </div>
                        </div>
                    </div>
                    <div class="chart-widget-content">
                        <div class="chart-placeholder" style="border-left: 4px solid ${chart.color}">
                            <i class="${chartType ? chartType.icon : 'fas fa-chart-bar'}" style="color: ${chart.color}"></i>
                            <div>${chartType ? chartType.name : '图表'}</div>
                            <div style="font-size: 12px; margin-top: 5px;">${chart.name}</div>
                        </div>
                    </div>
                `;

                // 添加拖拽事件
                chartWidget.addEventListener('dragstart', handleDragStart);
                chartWidget.addEventListener('dragover', handleDragOver);
                chartWidget.addEventListener('drop', handleDrop);
                chartWidget.addEventListener('dragend', handleDragEnd);

                // 添加编辑和删除按钮事件
                const editBtn = chartWidget.querySelector('.edit-chart-btn');
                const deleteBtn = chartWidget.querySelector('.delete-chart-btn');

                editBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    editChart(chart.id);
                });

                deleteBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    deleteChart(chart.id);
                });

                dashboardGrid.appendChild(chartWidget);
            });

            // 为网格区域添加拖放事件
            dashboardGrid.addEventListener('dragover', handleDragOver);
            dashboardGrid.addEventListener('drop', handleDrop);
        }

        // 选择仪表盘
        function selectDashboard(dashboardId) {
            // 更新仪表盘激活状态
            dashboards.forEach(dashboard => {
                dashboard.active = dashboard.id === dashboardId;
            });

            // 更新当前仪表盘名称
            const selectedDashboard = dashboards.find(d => d.id === dashboardId);
            if (selectedDashboard) {
                currentDashboardName.textContent = selectedDashboard.name;

                // 更新数据源配置和共享设置
                document.getElementById('dashboardVisibility').value = selectedDashboard.visibility;

                // 这里可以加载对应仪表盘的图表数据
                // 暂时使用默认数据
            }

            // 重新渲染列表和网格
            renderDashboardList();
            renderDashboardGrid();
        }

        // 拖拽处理函数
        let draggedElement = null;

        function handleDragStart(e) {
            draggedElement = e.target;
            e.target.classList.add('dragging');

            // 设置拖拽数据
            if (e.target.classList.contains('chart-type-card')) {
                e.dataTransfer.setData('text/plain', e.target.dataset.type);
                e.dataTransfer.effectAllowed = 'copy';
            } else if (e.target.classList.contains('chart-widget')) {
                e.dataTransfer.setData('text/plain', e.target.dataset.id);
                e.dataTransfer.effectAllowed = 'move';
            }
        }

        function handleDragOver(e) {
            e.preventDefault();
            e.dataTransfer.dropEffect = 'move';

            // 添加拖拽悬停效果
            if (e.target.classList.contains('chart-widget') || 
                e.target.classList.contains('dashboard-grid')) {
                e.target.classList.add('drag-over');
            }
        }

        function handleDrop(e) {
            e.preventDefault();

            // 移除拖拽悬停效果
            document.querySelectorAll('.drag-over').forEach(element => {
                element.classList.remove('drag-over');
            });

            if (e.target.classList.contains('dashboard-grid') || 
                e.target.classList.contains('chart-widget')) {

                const chartType = e.dataTransfer.getData('text/plain');

                // 如果是从图表库拖拽过来的
                if (chartTypes.find(type => type.id === chartType)) {
                    addChartToDashboard(chartType, e.target);
                } 
                // 如果是移动现有图表
                else if (draggedElement && draggedElement.classList.contains('chart-widget')) {
                    moveChartInDashboard(draggedElement.dataset.id, e.target);
                }
            }
        }

        function handleDragEnd(e) {
            // 移除拖拽样式
            document.querySelectorAll('.dragging').forEach(element => {
                element.classList.remove('dragging');
            });

            document.querySelectorAll('.drag-over').forEach(element => {
                element.classList.remove('drag-over');
            });

            draggedElement = null;
        }

        // 添加图表到仪表盘
        function addChartToDashboard(chartTypeId, targetElement) {
            const chartType = chartTypes.find(type => type.id === chartTypeId);
            if (!chartType) return;

            // 生成新图表ID
            const newChartId = currentDashboardCharts.length > 0 ? 
                Math.max(...currentDashboardCharts.map(c => c.id)) + 1 : 1;

            // 创建新图表
            const newChart = {
                id: newChartId,
                type: chartTypeId,
                name: `${chartType.name} ${newChartId}`,
                gridColumn: 'span 4',
                gridRow: 'span 2',
                color: chartType.color
            };

            currentDashboardCharts.push(newChart);
            renderDashboardGrid();

            // 显示通知
            showNotification(`已添加 ${chartType.name} 到仪表盘`, 'success');
        }

        // 移动仪表盘中的图表
        function moveChartInDashboard(chartId, targetElement) {
            // 这里可以实现图表位置的重新排列
            // 暂时只是显示通知
            showNotification('图表位置已更新', 'success');
        }

        // 编辑图表
        function editChart(chartId) {
            const chart = currentDashboardCharts.find(c => c.id === chartId);
            if (!chart) return;

            showNotification(`编辑图表: ${chart.name}`, 'success');
        }

        // 删除图表
        function deleteChart(chartId) {
            if (confirm('确定要删除这个图表吗？')) {
                currentDashboardCharts = currentDashboardCharts.filter(c => c.id !== chartId);
                renderDashboardGrid();
                showNotification('图表已删除', 'success');
            }
        }

        // 打开创建仪表盘模态框
        function openCreateDashboardModal() {
            createDashboardModal.classList.add('active');
        }

        // 关闭创建仪表盘模态框
        function closeCreateDashboardModal() {
            createDashboardModal.classList.remove('active');
            document.getElementById('dashboardName').value = '';
            document.getElementById('dashboardDescription').value = '';
        }

        // 创建新仪表盘
        function createDashboard() {
            const name = document.getElementById('dashboardName').value;
            const description = document.getElementById('dashboardDescription').value;
            const template = document.getElementById('dashboardTemplate').value;

            if (!name.trim()) {
                showNotification('请输入仪表盘名称', 'error');
                return;
            }

            // 生成新仪表盘ID
            const newDashboardId = dashboards.length > 0 ? 
                Math.max(...dashboards.map(d => d.id)) + 1 : 1;

            // 创建新仪表盘
            const newDashboard = {
                id: newDashboardId,
                name: name,
                description: description || '无描述',
                visibility: 'private',
                charts: template === 'none' ? 0 : 3,
                lastUpdated: new Date().toISOString().split('T')[0],
                active: false
            };

            dashboards.push(newDashboard);

            // 如果选择了模板，初始化图表数据
            if (template !== 'none') {
                // 这里可以根据模板初始化图表数据
                // 暂时只是设置图表数量
            }

            // 选中新创建的仪表盘
            selectDashboard(newDashboardId);

            // 关闭模态框
            closeCreateDashboardModal();

            // 显示通知
            showNotification(`仪表盘 "${name}" 创建成功`, 'success');
        }

