                        <div class="module-subtitle">拖拽式配置，支持多种图表类型，实现多维测试数据可视化</div>
                    </div>
                    <div class="action-buttons">
                        <button class="btn btn-success" id="createDashboardBtn">
                            <i class="fas fa-plus"></i> 新建仪表盘
                        </button>
                        <button class="btn btn-primary" id="importTemplateBtn">
                            <i class="fas fa-file-import"></i> 导入模板
                        </button>
                        <button class="btn btn-secondary" id="saveDashboardBtn">
                            <i class="fas fa-save"></i> 保存
                        </button>
                    </div>
                </div>

