                    <div class="dashboard-content">
                        <div class="module-card">
                            <div style="font-weight: 600; color: #1a3a8f; margin-bottom: 15px;">当前仪表盘：<span id="currentDashboardName">项目监控概览</span></div>

                            <!-- 图表组件库 -->
                            <div style="margin-bottom: 25px;">
                                <div style="font-weight: 500; color: #555; margin-bottom: 15px;">图表组件库（拖动到右侧区域）</div>
                                <div class="chart-library" id="chartLibrary">
                                    <!-- 图表类型将通过JavaScript动态生成 -->
                                </div>
                            </div>

