        // 渲染分页
        function renderPagination(paginationElement, paginationInfoElement, totalItems, currentPage, itemsPerPage, type) {
            const totalPages = Math.ceil(totalItems / itemsPerPage);

            // 更新分页信息
            const startItem = (currentPage - 1) * itemsPerPage + 1;
            const endItem = Math.min(currentPage * itemsPerPage, totalItems);
            paginationInfoElement.textContent = `显示 ${startItem}-${endItem} 条，共 ${totalItems} 条`;

            // 生成分页按钮
            paginationElement.innerHTML = '';

            // 上一页按钮
            const prevLi = document.createElement('li');
            prevLi.className = 'page-item';
            prevLi.innerHTML = `<a class="page-link ${currentPage === 1 ? 'disabled' : ''}" href="#" data-page="${currentPage - 1}" data-type="${type}"><i class="fas fa-chevron-left"></i></a>`;
            paginationElement.appendChild(prevLi);

            // 页码按钮
            const maxVisiblePages = 5;
            let startPage = Math.max(1, currentPage - Math.floor(maxVisiblePages / 2));
            let endPage = Math.min(totalPages, startPage + maxVisiblePages - 1);

            // 调整起始页，确保显示maxVisiblePages个页码
            if (endPage - startPage + 1 < maxVisiblePages) {
                startPage = Math.max(1, endPage - maxVisiblePages + 1);
            }

            for (let i = startPage; i <= endPage; i++) {
                const pageLi = document.createElement('li');
                pageLi.className = 'page-item';
                pageLi.innerHTML = `<a class="page-link ${i === currentPage ? 'active' : ''}" href="#" data-page="${i}" data-type="${type}">${i}</a>`;
                paginationElement.appendChild(pageLi);
            }

            // 下一页按钮
            const nextLi = document.createElement('li');
            nextLi.className = 'page-item';
            nextLi.innerHTML = `<a class="page-link ${currentPage === totalPages ? 'disabled' : ''}" href="#" data-page="${currentPage + 1}" data-type="${type}"><i class="fas fa-chevron-right"></i></a>`;
            paginationElement.appendChild(nextLi);

            // 绑定分页点击事件
            paginationElement.querySelectorAll('.page-link').forEach(link => {
                link.addEventListener('click', (e) => {
                    e.preventDefault();

                    if (link.classList.contains('disabled')) return;

                    const page = parseInt(link.dataset.page);
                    const type = link.dataset.type;

                    if (!isNaN(page)) {
                        switch(type) {
                            case 'project':
                                currentProjectPage = page;
                                renderProjectTable();
                                break;
                            case 'testCase':
                                currentTestCasePage = page;
                                renderTestCaseTable();
                                break;
                            case 'defect':
                                currentDefectPage = page;
                                renderDefectTable();
                                break;
                            case 'task':
                                currentTaskPage = page;
                                renderTaskTable();
                                break;
                        }
                    }
                });
            });
        }

