            dashboardCharts.forEach(chart => {
                const chartWidget = document.createElement('div');
                chartWidget.className = 'chart-widget draggable';
                chartWidget.dataset.id = chart.id;
                chartWidget.draggable = true;

                // 根据图表类型设置图标
                let chartIcon = 'fas fa-chart-line';
                let chartDescription = '趋势分析';

                switch(chart.type) {
                    case 'line':
                        chartIcon = 'fas fa-chart-line';
                        chartDescription = '趋势分析';
                        break;
                    case 'bar':
                        chartIcon = 'fas fa-chart-bar';
                        chartDescription = '数据对比';
                        break;
                    case 'pie':
                        chartIcon = 'fas fa-chart-pie';
                        chartDescription = '比例分布';
                        break;
                    case 'radar':
                        chartIcon = 'fas fa-chart-area';
                        chartDescription = '多维度分析';
                        break;
                    case 'gauge':
                        chartIcon = 'fas fa-tachometer-alt';
                        chartDescription = '进度监控';
                        break;
                    case 'burn-down':
                        chartIcon = 'fas fa-fire';
                        chartDescription = '项目进度';
                        break;
                }

                chartWidget.innerHTML = `
                    <div class="chart-header">
                        <div class="chart-name">${chart.name}</div>
                        <div class="chart-actions">
                            <div class="chart-action-btn edit-chart" title="编辑图表">
