                            </div>
                            <div class="chart-action-btn delete-chart" title="删除图表">
                                <i class="fas fa-trash"></i>
                            </div>
                        </div>
                    </div>
                    <div class="chart-content">
                        <div class="chart-placeholder">
                            <i class="${chartIcon}"></i>
                            <span>${chartDescription}</span>
                        </div>
                    </div>
                    <div class="chart-stats">
                        <div class="stat-item">
                            <div class="stat-value">${chart.stats.value1}</div>
                            <div class="stat-label">${chart.stats.label1}</div>
                        </div>
                        <div class="stat-item">
                            <div class="stat-value">${chart.stats.value2}</div>
                            <div class="stat-label">${chart.stats.label2}</div>
                        </div>
                        <div class="stat-item">
                            <div class="stat-value">${chart.stats.value3}</div>
                            <div class="stat-label">${chart.stats.label3}</div>
                        </div>
                    </div>
                `;

                // 设置图表颜色
                chartWidget.style.borderTop = `3px solid ${chart.color}`;

                dashboardContainer.appendChild(chartWidget);

                // 绑定图表操作事件
                const editBtn = chartWidget.querySelector('.edit-chart');
                const deleteBtn = chartWidget.querySelector('.delete-chart');

                editBtn.addEventListener('click', () => editChart(chart.id));
                deleteBtn.addEventListener('click', () => deleteChart(chart.id));

                // 绑定拖拽事件
                chartWidget.addEventListener('dragstart', handleDragStart);
                chartWidget.addEventListener('dragover', handleDragOver);
                chartWidget.addEventListener('drop', handleDrop);
                chartWidget.addEventListener('dragend', handleDragEnd);
            });
        }

