                // 模拟更新统计数据
                if (chart.type === 'line') {
                    chart.stats.value1 = Math.floor(Math.random() * 50 + 100).toString();
                } else if (chart.type === 'pie') {
                    chart.stats.value3 = Math.floor(Math.random() * 10 + 70) + '%';
                } else if (chart.type === 'gauge') {
                    chart.stats.value1 = Math.floor(Math.random() * 15 + 80) + '%';
                }
            });

            renderDashboardCharts();
        }

        // 编辑图表
        function editChart(chartId) {
            const chart = dashboardCharts.find(c => c.id === chartId);
            if (chart) {
                // 填充表单
                document.getElementById('chartName').value = chart.name;
                document.getElementById('chartType').value = chart.type;
                document.getElementById('dataSourceType').value = chart.dataSource;
                document.getElementById('refreshInterval').value = chart.refreshInterval;
                document.getElementById('selectedColor').value = chart.color;

                // 设置选中颜色
                document.querySelectorAll('.color-indicator').forEach(indicator => {
                    indicator.style.border = 'none';
                    if (indicator.dataset.color === chart.color) {
                        indicator.style.border = '2px solid #333';
                    }
                });

                addChartModal.classList.add('active');

                // 临时存储当前编辑的图表ID
                addChartModal.dataset.editingChartId = chartId;
                document.getElementById('confirmAddChartBtn').textContent = '更新图表';
            }
        }

        // 删除图表
        function deleteChart(chartId) {
            if (confirm('确定要删除此图表吗？')) {
                dashboardCharts = dashboardCharts.filter(chart => chart.id !== chartId);
                renderDashboardCharts();
                showNotification('图表已删除', 'success');
            }
        }

        // 打开添加图表模态框
        function openAddChartModal() {
            addChartModal.classList.add('active');
            addChartForm.reset();
            document.getElementById('selectedColor').value = '#1a3a8f';

            // 重置颜色选择器
            document.querySelectorAll('.color-indicator').forEach(indicator => {
                indicator.style.border = 'none';
            });

            // 设置默认选中第一个颜色
            document.querySelector('.color-indicator').style.border = '2px solid #333';

            // 移除编辑状态
            delete addChartModal.dataset.editingChartId;
            document.getElementById('confirmAddChartBtn').textContent = '添加图表';
        }

        // 关闭添加图表模态框
        function closeAddChartModal() {
            addChartModal.classList.remove('active');
            addChartForm.reset();

            // 移除编辑状态
            delete addChartModal.dataset.editingChartId;
            document.getElementById('confirmAddChartBtn').textContent = '添加图表';
        }

        // 确认添加/更新图表
        function confirmAddChart() {
            const chartName = document.getElementById('chartName').value;
            const chartType = document.getElementById('chartType').value;
            const dataSourceType = document.getElementById('dataSourceType').value;
            const refreshInterval = parseInt(document.getElementById('refreshInterval').value) || 0;
            const selectedColor = document.getElementById('selectedColor').value;

            if (!chartName || !chartType || !dataSourceType) {
                showNotification('请填写完整的图表信息', 'error');
                return;
            }

            // 检查是否正在编辑现有图表
            const editingChartId = addChartModal.dataset.editingChartId;

            if (editingChartId) {
                // 更新现有图表
                const chartIndex = dashboardCharts.findIndex(c => c.id === parseInt(editingChartId));
                if (chartIndex !== -1) {
                    dashboardCharts[chartIndex].name = chartName;
                    dashboardCharts[chartIndex].type = chartType;
                    dashboardCharts[chartIndex].dataSource = dataSourceType;
                    dashboardCharts[chartIndex].refreshInterval = refreshInterval;
                    dashboardCharts[chartIndex].color = selectedColor;

                    showNotification('图表已更新', 'success');
                }
            } else {
                // 添加新图表
                const newChartId = dashboardCharts.length > 0 ? Math.max(...dashboardCharts.map(c => c.id)) + 1 : 1;

                // 根据图表类型生成示例统计数据
                let stats = { value1: "0", label1: "数据1", value2: "0", label2: "数据2", value3: "0", label3: "数据3" };

                switch(chartType) {
                    case 'line':
                        stats = { value1: "0", label1: "数据点", value2: "0", label2: "趋势", value3: "0", label3: "变化率" };
                        break;
                    case 'bar':
                        stats = { value1: "0", label1: "最大值", value2: "0", label2: "平均值", value3: "0", label3: "最小值" };
                        break;
                    case 'pie':
                        stats = { value1: "0", label1: "类别1", value2: "0", label2: "类别2", value3: "0", label3: "类别3" };
                        break;
                    case 'radar':
                        stats = { value1: "0", label1: "维度1", value2: "0", label2: "维度2", value3: "0", label3: "维度3" };
                        break;
                    case 'gauge':
                        stats = { value1: "0%", label1: "完成度", value2: "0", label2: "目标值", value3: "0", label3: "当前值" };
                        break;
                    case 'burn-down':
                        stats = { value1: "0%", label1: "完成率", value2: "0", label2: "剩余任务", value3: "0", label3: "剩余天数" };
                        break;
                }

                const newChart = {
                    id: newChartId,
                    name: chartName,
                    type: chartType,
                    color: selectedColor,
                    dataSource: dataSourceType,
                    refreshInterval: refreshInterval,
                    stats: stats
                };

                dashboardCharts.push(newChart);
                showNotification('图表已添加', 'success');
            }

            closeAddChartModal();
            renderDashboardCharts();
        }

        // 拖拽功能实现
        let draggedElement = null;

        function handleDragStart(e) {
            draggedElement = this;
            this.classList.add('dragging');
            e.dataTransfer.effectAllowed = 'move';
            e.dataTransfer.setData('text/html', this.innerHTML);
        }

        function handleDragOver(e) {
            e.preventDefault();
            this.classList.add('drop-zone');
        }

        function handleDrop(e) {
            e.preventDefault();
            this.classList.remove('drop-zone');

            if (draggedElement !== this) {
                // 交换位置
                const dashboardContainer = document.getElementById('dashboardContainer');
                const children = Array.from(dashboardContainer.children);
                const draggedIndex = children.indexOf(draggedElement);
                const targetIndex = children.indexOf(this);

                if (draggedIndex < targetIndex) {
                    dashboardContainer.insertBefore(draggedElement, this.nextSibling);
                } else {
                    dashboardContainer.insertBefore(draggedElement, this);
                }

                // 更新数据顺序
                const draggedChartId = parseInt(draggedElement.dataset.id);
                const targetChartId = parseInt(this.dataset.id);

                const draggedChartIndex = dashboardCharts.findIndex(c => c.id === draggedChartId);
                const targetChartIndex = dashboardCharts.findIndex(c => c.id === targetChartId);

                if (draggedChartIndex !== -1 && targetChartIndex !== -1) {
                    const [draggedChart] = dashboardCharts.splice(draggedChartIndex, 1);
                    dashboardCharts.splice(targetChartIndex, 0, draggedChart);
                }

                showNotification('图表位置已调整', 'success');
            }
        }

        function handleDragEnd() {
            this.classList.remove('dragging');
            document.querySelectorAll('.chart-widget').forEach(widget => {
                widget.classList.remove('drop-zone');
            });
            draggedElement = null;
        }

        // 显示通知
        function showNotification(message, type) {
            // 移除现有通知
            const existingNotification = document.querySelector('.notification');
            if (existingNotification) {
                existingNotification.remove();
            }

            // 创建通知元素
            const notification = document.createElement('div');
            notification.className = `notification ${type === 'error' ? 'error' : ''}`;

            notification.innerHTML = `
                <i class="fas fa-${type === 'success' ? 'check-circle' : 'exclamation-circle'}"></i>
                <span>${message}</span>
            `;

            document.body.appendChild(notification);

            // 3秒后移除通知
            setTimeout(() => {
                notification.style.animation = 'slideOut 0.3s ease';
                setTimeout(() => {
                    if (notification.parentNode) {
                        notification.parentNode.removeChild(notification);
                    }
                }, 300);
            }, 3000);
        }

        // 初始化
        document.addEventListener('DOMContentLoaded', () => {
            initDirectoryTree();
            loadCustomDashboard();

            // 绑定全局事件
            closeAddChartModalBtn.addEventListener('click', closeAddChartModal);
            cancelAddChartBtn.addEventListener('click', closeAddChartModal);
            confirmAddChartBtn.addEventListener('click', confirmAddChart);

            // 移动端菜单切换
            mobileMenuToggle.addEventListener('click', () => {
                sidebar.classList.toggle('active');
            });

            // 窗口大小变化时调整侧边栏
            window.addEventListener('resize', () => {
                if (window.innerWidth > 992) {
                    sidebar.classList.remove('active');
                }
            });

            // 初始化颜色选择器
            document.querySelectorAll('.color-indicator').forEach(indicator => {
                indicator.addEventListener('click', () => {
                    document.querySelectorAll('.color-indicator').forEach(ind => {
                        ind.style.border = 'none';
                    });
                    indicator.style.border = '2px solid #333';
                    document.getElementById('selectedColor').value = indicator.dataset.color;
                });
            });

            // 设置默认选中第一个颜色
            if (document.querySelector('.color-indicator')) {
                document.querySelector('.color-indicator').style.border = '2px solid #333';
            }
        });
    </script>
</body>
</html>
```

## 功能说明

这个自定义仪表盘页面具有以下特点：

1. **与2.html一致的脚手架架构**：保持了相同的侧边栏、顶部栏和内容区域布局
2. **一致的图标和主题**：使用相同的配色方案（蓝白主题）和Font Awesome图标
3. **固定头部和侧边栏**：当页面上下滑动时，顶部头和左侧目录结构保持不动
4. **软件名称更新**：已按要求将软件名称改为"适配中心测试管理软件 V1.0"
5. **一致的目录结构**：与2.html完全相同的目录树结构，默认选中"自定义仪表盘"
6. **自定义仪表盘功能**：
   - 支持多种图表类型（燃尽图、柱状图、饼图、趋势图、雷达图、仪表盘）
   - 拖拽式布局调整
   - 可添加、编辑、删除图表组件
   - 图表颜色自定义
   - 数据源配置（SQL查询、API接口、静态数据）
   - 实时数据刷新功能
   - 图表预览区域

页面加载后默认显示自定义仪表盘功能，用户可以通过拖拽调整图表位置，点击"添加图表"按钮可以添加新的图表组件，支持多种图表类型和数据源配置。

