                    }
                });
            });

            // 如果所有插件都匹配可疑模式，可能是自动化环境
            return matchCount === pluginNames.length;
        } catch (e) {
            return true;
        }
    }

    // 方法7: AudioContext检测
    detectAudioContext() {
        try {
            if (!window.AudioContext && !window.webkitAudioContext) {
                return false;
            }

            const AudioContext = window.AudioContext || window.webkitAudioContext;
            const context = new AudioContext();

            // 自动化浏览器可能没有正确的AudioContext实现
            const oscillator = context.createOscillator();

            // 检查属性和方法
            const hasFrequency = typeof oscillator.frequency !== 'undefined';
            const hasStart = typeof oscillator.start === 'function';
            const hasStop = typeof oscillator.stop === 'function';

            oscillator.stop();
            context.close();

            // 如果缺少基本功能，可能是自动化环境
            return !(hasFrequency && hasStart && hasStop);
        } catch (e) {
            // 创建AudioContext失败可能是自动化环境
            return true;
        }
    }

    // 方法8: WebGL供应商检测
    detectWebGLVendor() {
        try {
            const canvas = document.createElement('canvas');
            const gl = canvas.getContext('webgl') || canvas.getContext('experimental-webgl');

            if (!gl) {
                return false;
            }

            const debugInfo = gl.getExtension('WEBGL_debug_renderer_info');
            if (debugInfo) {
                const vendor = gl.getParameter(debugInfo.UNMASKED_VENDOR_WEBGL);
                const renderer = gl.getParameter(debugInfo.UNMASKED_RENDERER_WEBGL);

                // 检查虚拟GPU或自动化环境特有的渲染器
                const virtualGPUs = [
                    'llvmpipe',
                    'swiftshader',
                    'software',
                    'virtualbox',
                    'vmware',
                    'parallels'
                ];

                const vendorStr = (vendor + renderer).toLowerCase();
                return virtualGPUs.some(gpu => vendorStr.includes(gpu));
            }

            return false;
        } catch (e) {
            return false;
        }
    }

    // 方法9: Chrome运行时检测
    detectChromeRuntime() {
        try {
            if (!window.chrome || !window.chrome.runtime) {
                return false;
            }

            // 尝试获取运行时ID
            const runtimeId = chrome.runtime.id;

            // 自动化浏览器可能有特定的运行时ID模式
            if (runtimeId) {
                // 检查ID是否包含自动化关键词
                const automationKeywords = [
                    'webdriver',
                    'automation',
                    'selenium',
                    'chromedriver',
                    'headless'
                ];

                const idStr = runtimeId.toLowerCase();
                return automationKeywords.some(keyword => idStr.includes(keyword));
            }

            // 检查是否存在自动化扩展
            if (chrome.runtime.getManifest) {
                try {
                    const manifest = chrome.runtime.getManifest();
                    if (manifest && manifest.name) {
                        const name = manifest.name.toLowerCase();
                        return name.includes('webdriver') || 
                               name.includes('automation') || 
                               name.includes('selenium');
                    }
                } catch (e) {}
            }

            return false;
        } catch (e) {
            return false;
        }
    }

    // 方法10: 性能指标检测
    detectPerformanceMetrics() {
        try {
            if (!window.performance || !window.performance.timing) {
                return false;
            }

            const timing = performance.timing;

            // 检查时间戳是否合理
            const navigationStart = timing.navigationStart;
            const loadEventEnd = timing.loadEventEnd;

            // 如果时间戳为0或异常，可能是自动化环境
            if (navigationStart === 0 || loadEventEnd === 0) {
                return true;
            }

            // 检查页面加载时间是否异常短（自动化工具可能模拟快速加载）
            const loadTime = loadEventEnd - navigationStart;
            if (loadTime > 0 && loadTime < 100) {
                // 页面加载时间小于100ms，可能是自动化环境
                return true;
            }

            // 检查性能条目
            if (performance.getEntriesByType) {
                const entries = performance.getEntriesByType('resource');
                // 自动化工具可能没有资源加载记录或记录异常
                if (entries.length === 0 && document.readyState === 'complete') {
                    return true;
                }
            }

            return false;
        } catch (e) {
            return false;
        }
    }

    // 方法11: 鼠标移动检测
    detectMouseMovement() {
        return new Promise((resolve) => {
            try {
                let mouseEvents = [];
                let startTime = Date.now();

                const recordEvent = (e) => {
                    mouseEvents.push({
                        type: e.type,
                        x: e.clientX,
                        y: e.clientY,
                        time: Date.now() - startTime
                    });
                };

                // 监听鼠标事件
                document.addEventListener('mousemove', recordEvent);
                document.addEventListener('mousedown', recordEvent);
                document.addEventListener('mouseup', recordEvent);

                // 等待一段时间收集数据
                setTimeout(() => {
                    document.removeEventListener('mousemove', recordEvent);
                    document.removeEventListener('mousedown', recordEvent);
                    document.removeEventListener('mouseup', recordEvent);

                    // 分析鼠标事件
                    if (mouseEvents.length === 0) {
                        // 没有鼠标事件，可能是自动化环境
                        resolve(true);
                        return;
                    }

                    // 检查事件模式
                    let suspiciousPatterns = 0;

                    // 1. 检查移动轨迹是否过于直线
                    const moveEvents = mouseEvents.filter(e => e.type === 'mousemove');
                    if (moveEvents.length >= 3) {
                        let totalAngleChange = 0;
                        for (let i = 1; i < moveEvents.length - 1; i++) {
                            const prev = moveEvents[i-1];
                            const curr = moveEvents[i];
                            const next = moveEvents[i+1];

                            const dx1 = curr.x - prev.x;
                            const dy1 = curr.y - prev.y;
                            const dx2 = next.x - curr.x;
                            const dy2 = next.y - curr.y;

                            const angle1 = Math.atan2(dy1, dx1);
                            const angle2 = Math.atan2(dy2, dx2);
                            const angleChange = Math.abs(angle2 - angle1);

                            totalAngleChange += angleChange;
                        }

                        const avgAngleChange = totalAngleChange / (moveEvents.length - 2);
                        // 人类鼠标移动通常有角度变化，自动化工具可能移动过于直线
                        if (avgAngleChange < 0.1) {
                            suspiciousPatterns++;
                        }
                    }

                    // 2. 检查点击位置是否过于精确
                    const clickEvents = mouseEvents.filter(e => 
                        e.type === 'mousedown' || e.type === 'mouseup'
                    );

                    if (clickEvents.length >= 2) {
                        // 检查点击位置是否在相同位置（像素级精确）
                        const positions = clickEvents.map(e => ({x: e.x, y: e.y}));
                        let samePositionCount = 0;

                        for (let i = 1; i < positions.length; i++) {
                            const prev = positions[i-1];
                            const curr = positions[i];

                            if (Math.abs(prev.x - curr.x) <= 1 && 
                                Math.abs(prev.y - curr.y) <= 1) {
                                samePositionCount++;
                            }
                        }

                        // 如果多次点击在完全相同的位置，可能是自动化
                        if (samePositionCount >= positions.length / 2) {
                            suspiciousPatterns++;
                        }
                    }

                    resolve(suspiciousPatterns >= 1);
                }, 2000); // 收集2秒的数据
            } catch (e) {
                resolve(false);
            }
        });
    }

    // 运行所有检测
    async runAllDetections() {
        this.results.chromeAutomation = this.detectChromeAutomation();
        this.results.cdpDetected = this.detectCDP();
        this.results.automationPatch = this.detectPatchedDOM();
        this.results.iframeDetection = await this.detectIframeSandbox();
        this.results.requestAnimationFrame = this.detectRAFAnomalies();
        this.results.pluginPatterns = this.detectPluginPatterns();
        this.results.audioContext = this.detectAudioContext();
        this.results.webglVendor = this.detectWebGLVendor();
        this.results.chromeRuntime = this.detectChromeRuntime();
        this.results.performanceMetrics = this.detectPerformanceMetrics();
        this.results.mouseMovement = await this.detectMouseMovement();

        return this.results;
    }

    // 获取检测摘要
    getDetectionSummary() {
        const detectedCount = Object.values(this.results).filter(v => v === true).length;
        const totalCount = Object.keys(this.results).length;

        return {
            results: this.results,
            detectedCount,
            totalCount,
            percentage: Math.round((detectedCount / totalCount) * 100),
            isLikelyAutomated: detectedCount > 1 // 如果检测到2个以上特征，认为是自动化
        };
    }
}

// 使用示例
async function runAdvancedDetection() {
    const detector = new AdvancedSeleniumDetector();
    await detector.runAllDetections();
    const summary = detector.getDetectionSummary();

    console.log('高级自动化检测结果:', summary);

    if (summary.isLikelyAutomated) {
        console.warn('警告：检测到高级自动化特征！');
        // 在页面上显示警告或采取其他措施
        showDetectionWarning(summary);
    }

    return summary;
}

// 在页面上显示检测结果
function showDetectionWarning(summary) {
    const warningDiv = document.createElement('div');
    warningDiv.style.cssText = `
        position: fixed;
        top: 20px;
        right: 20px;
        background: #ff4444;
        color: white;
        padding: 20px;
        border-radius: 10px;
        z-index: 99999;
        box-shadow: 0 5px 15px rgba(0,0,0,0.3);
        max-width: 400px;
        font-family: Arial, sans-serif;
    `;

    let details = '<h3>检测到自动化浏览器特征</h3>';
    details += `<p>检测到 ${summary.detectedCount}/${summary.totalCount} 个自动化特征</p>`;
    details += '<ul>';

    Object.entries(summary.results).forEach(([key, value]) => {
        if (value) {
            const readableName = key.replace(/([A-Z])/g, ' $1').replace(/^./, str => str.toUpperCase());
            details += `<li>${readableName}</li>`;
        }
    });

    details += '</ul>';
    details += '<p>这可能影响您的使用体验。</p>';

    warningDiv.innerHTML = details;
    document.body.appendChild(warningDiv);

    // 10秒后自动移除
    setTimeout(() => {
        if (document.body.contains(warningDiv)) {
            document.body.removeChild(warningDiv);
        }
    }, 10000);
}

// 页面加载时运行检测
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', runAdvancedDetection);
} else {
    runAdvancedDetection();
}
