        overallResult.textContent = '检测到高级自动化特征';
        overallResult.className = 'result-text detected';
        resultExplanation.innerHTML = `
            在 ${totalCount} 项检测中，有 <span class="highlight">${detectedCount}</span> 项显示自动化特征。
