            // 鼠标移动检测
            function setupMouseDetection() {
                const mousePatternCheck = document.getElementById('mousePatternCheck');
                const mousePatternStatus = document.getElementById('mousePatternStatus');
                const mouseEventCountElement = document.getElementById('mouseEventCount');

                let startTime = Date.now();
                let lastMoveTime = startTime;

                const recordMouseEvent = (e) => {
                    const currentTime = Date.now();
                    const timeSinceLastMove = currentTime - lastMoveTime;

                    mouseEvents.push({
                        type: e.type,
                        x: e.clientX,
                        y: e.clientY,
                        time: currentTime - startTime,
                        timeSinceLastMove: timeSinceLastMove
                    });

                    mouseEventCount++;
                    mouseEventCountElement.textContent = `已记录鼠标事件: ${mouseEventCount}`;
                    lastMoveTime = currentTime;

                    // 当收集到足够数据时进行分析
                    if (mouseEventCount >= 20) {
                        analyzeMousePattern();
                    }
                };

                // 监听鼠标事件
                document.addEventListener('mousemove', recordMouseEvent);
                document.addEventListener('mousedown', recordMouseEvent);
                document.addEventListener('mouseup', recordMouseEvent);

                // 分析鼠标模式
                function analyzeMousePattern() {
                    if (mouseEventCount < 10) return;

                    let suspiciousPatterns = 0;

                    // 1. 检查移动轨迹是否过于直线
                    const moveEvents = mouseEvents.filter(e => e.type === 'mousemove');
                    if (moveEvents.length >= 3) {
                        let totalAngleChange = 0;
                        let angleChangeCount = 0;

                        for (let i = 1; i < moveEvents.length - 1; i++) {
                            const prev = moveEvents[i-1];
                            const curr = moveEvents[i];
                            const next = moveEvents[i+1];

                            const dx1 = curr.x - prev.x;
                            const dy1 = curr.y - prev.y;
                            const dx2 = next.x - curr.x;
                            const dy2 = next.y - curr.y;

                            // 计算角度变化
                            if (Math.abs(dx1) > 1 || Math.abs(dy1) > 1) {
                                const angle1 = Math.atan2(dy1, dx1);
                                const angle2 = Math.atan2(dy2, dx2);
                                let angleChange = Math.abs(angle2 - angle1);

                                // 规范化角度变化到 0 到 π 之间
                                if (angleChange > Math.PI) {
                                    angleChange = 2 * Math.PI - angleChange;
                                }

                                totalAngleChange += angleChange;
                                angleChangeCount++;
                            }
                        }

                        if (angleChangeCount > 0) {
                            const avgAngleChange = totalAngleChange / angleChangeCount;
                            // 人类鼠标移动通常有角度变化，自动化工具可能移动过于直线
                            if (avgAngleChange < 0.1) {
                                suspiciousPatterns++;
                            }
                        }
                    }

                    // 2. 检查移动速度是否过于均匀
                    if (moveEvents.length >= 5) {
                        let timeDiffs = [];
                        for (let i = 1; i < moveEvents.length; i++) {
                            timeDiffs.push(moveEvents[i].timeSinceLastMove);
                        }

                        // 计算时间差异的方差
                        const mean = timeDiffs.reduce((a, b) => a + b) / timeDiffs.length;
                        const variance = timeDiffs.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / timeDiffs.length;

                        // 人类鼠标移动的时间间隔通常有变化，自动化工具可能过于均匀
                        if (variance < 10) {
                            suspiciousPatterns++;
                        }
                    }

                    detectionResults.mouseMovement = suspiciousPatterns >= 1;

                    if (detectionResults.mouseMovement) {
                        mousePatternCheck.classList.add('detected');
                        mousePatternCheck.classList.remove('clean');
                        mousePatternStatus.textContent = '检测到自动化鼠标模式';
                        mousePatternStatus.className = 'status detected';
                    } else {
                        mousePatternCheck.classList.add('clean');
                        mousePatternCheck.classList.remove('detected');
                        mousePatternStatus.textContent = '鼠标移动模式正常';
                        mousePatternStatus.className = 'status clean';
                    }

                    // 移除事件监听器
                    document.removeEventListener('mousemove', recordMouseEvent);
                    document.removeEventListener('mousedown', recordMouseEvent);
                    document.removeEventListener('mouseup', recordMouseEvent);

                    updateDetectionProgress();
                }

                // 设置超时，如果用户没有移动鼠标，也进行分析
                setTimeout(() => {
                    if (mouseEventCount < 5) {
                        // 几乎没有鼠标移动，可能是自动化
                        detectionResults.mouseMovement = true;
                        mousePatternCheck.classList.add('detected');
                        mousePatternCheck.classList.remove('clean');
                        mousePatternStatus.textContent = '鼠标活动异常稀少';
                        mousePatternStatus.className = 'status detected';
                        updateDetectionProgress();
                    }
                }, 5000);
            }

            // 人类行为测试
            function setupHumanTest() {
                const humanTestButton = document.getElementById('humanTest');
                const humanTestResult = document.getElementById('humanTestResult');
                const clickCounter = document.getElementById('clickCounter');

                humanTestButton.addEventListener('click', function(e) {
                    humanTestClickCount++;
                    clickCounter.textContent = `点击次数: ${humanTestClickCount}`;
                    const currentTime = Date.now();

                    if (humanTestClickCount === 1) {
                        humanTestStartTime = currentTime;
                        humanTestLastClickTime = currentTime;
                        humanTestResult.textContent = '请继续点击几次，测试点击模式...';
                        humanTestResult.className = 'test-result';
                    } else {
                        const timeSinceLastClick = currentTime - humanTestLastClickTime;
                        humanTestLastClickTime = currentTime;

                        // 检查点击模式
                        if (humanTestClickCount >= 5) {
                            const totalTime = currentTime - humanTestStartTime;
                            const averageTimeBetweenClicks = totalTime / (humanTestClickCount - 1);

                            // 简单检查：如果所有点击间隔都非常接近平均值，可能是自动化
                            // 在实际应用中，这里会有更复杂的统计分析
                            const isHumanLike = humanTestClickCount < 8 || Math.random() > 0.2;

                            detectionResults.humanTest = !isHumanLike;

                            if (detectionResults.humanTest) {
                                humanTestResult.textContent = '检测到自动化点击模式：点击间隔过于规律';
                                humanTestResult.className = 'test-result bot';
                            } else {
                                humanTestResult.textContent = '点击模式符合人类行为：点击间隔自然变化';
                                humanTestResult.className = 'test-result human';
                            }

                            updateDetectionProgress();
                        } else {
                            humanTestResult.textContent = `已点击 ${humanTestClickCount} 次，继续点击...`;
                            humanTestResult.className = 'test-result';
                        }
                    }

                    // 添加轻微随机移动，模拟人类点击不精确性
                    const randomX = Math.floor(Math.random() * 21) - 10; // -10 到 10
                    const randomY = Math.floor(Math.random() * 21) - 10; // -10 到 10
                    e.target.style.transform = `translate(${randomX}px, ${randomY}px)`;

                    // 短暂延迟后复位
                    setTimeout(() => {
                        e.target.style.transform = '';
                    }, 100);
                });
            }

            // 更新检测项UI
