            // 标签页切换功能
            function setupTabSwitching() {
                const tabs = document.querySelectorAll('.tab');
                const tabContents = document.querySelectorAll('.tab-content');

                tabs.forEach(tab => {
                    tab.addEventListener('click', () => {
                        // 移除所有标签的active类
                        tabs.forEach(t => t.classList.remove('active'));
                        tabContents.forEach(content => content.classList.remove('active'));

                        // 添加当前标签的active类
                        tab.classList.add('active');

                        // 显示对应的内容
                        const tabId = tab.getAttribute('data-tab');
                        document.getElementById(`${tabId}-tab`).classList.add('active');
                    });
                });
            }

            // 运行检测
            runAllDetections();
            setupTabSwitching();

            // 添加一个重置按钮用于演示
            const resetButton = document.createElement('button');
            resetButton.textContent = '重新检测';
            resetButton.style.cssText = `
                position: fixed;
                bottom: 20px;
                right: 20px;
                padding: 10px 20px;
                background: linear-gradient(to right, #0f3460, #1a1a2e);
                color: white;
                border: none;
                border-radius: 5px;
                cursor: pointer;
                font-weight: bold;
                z-index: 1000;
                box-shadow: 0 4px 10px rgba(0,0,0,0.3);
                transition: all 0.3s;
            `;

            resetButton.addEventListener('mouseenter', function() {
                this.style.transform = 'translateY(-2px)';
                this.style.boxShadow = '0 6px 15px rgba(0,0,0,0.4)';
            });

            resetButton.addEventListener('mouseleave', function() {
                this.style.transform = 'translateY(0)';
                this.style.boxShadow = '0 4px 10px rgba(0,0,0,0.3)';
            });

            resetButton.addEventListener('click', function() {
                // 重置所有检测状态
                detectionResults = {
                    webdriver: false,
                    plugins: false,
                    languages: false,
                    windowProps: false,
                    permissions: false,
                    chromeAutomation: false,
                    cdpDetected: false,
                    automationPatch: false,
                    iframeDetection: false,
                    webglVendor: false,
                    performanceMetrics: false,
                    audioContext: false,
                    chromeRuntime: false,
                    humanTest: false,
                    mouseMovement: false
                };

                humanTestClickCount = 0;
                humanTestStartTime = null;
                humanTestLastClickTime = null;
                mouseEvents = [];
                mouseEventCount = 0;
                completedDetections = 0;

                // 清除结果文本
                document.getElementById('humanTestResult').textContent = '';
                document.getElementById('clickCounter').textContent = '点击次数: 0';
                document.getElementById('mouseEventCount').textContent = '已记录鼠标事件: 0';
                document.getElementById('detectionCounter').textContent = '检测进度: 0/17';
                document.getElementById('confidenceFill').style.width = '0%';
                document.getElementById('overallResult').textContent = '分析中...';
                document.getElementById('overallResult').className = 'result-text';
                document.getElementById('resultExplanation').textContent = '正在分析浏览器特征，请稍候...';

                // 重置所有检测项的显示状态
                const detectionItems = document.querySelectorAll('.detection-item');
                detectionItems.forEach(item => {
                    item.classList.remove('detected', 'clean');
                    const statusElement = item.querySelector('.status');
                    if (statusElement) {
                        statusElement.textContent = '检测中...';
                        statusElement.className = 'status';
                    }
                });

                // 显示重置消息
                const message = document.createElement('div');
                message.textContent = '检测已重置，重新分析中...';
                message.style.cssText = `
                    position: fixed;
                    top: 20px;
                    right: 20px;
                    background: #4cc9f0;
                    color: #1a1a2e;
                    padding: 10px 20px;
                    border-radius: 5px;
                    font-weight: bold;
                    z-index: 1000;
                    box-shadow: 0 4px 10px rgba(0,0,0,0.3);
                `;
                document.body.appendChild(message);

                // 重新运行检测
                setTimeout(() => {
                    runAllDetections();
                }, 500);

                setTimeout(() => {
                    if (document.body.contains(message)) {
                        document.body.removeChild(message);
                    }
                }, 2000);
            });

            document.body.appendChild(resetButton);
        });
    </script>
</body>
</html>
```

## 主要改进和新增功能

1. **增加了17种检测方法**，包括：
   - 基础检测方法（5种）
   - 高级检测方法（8种）
   - 人类行为检测方法（4种）

2. **标签页界面**：将检测方法分类为"基础检测"、"高级检测"和"行为检测"三个标签页

3. **风险等级标识**：为每个检测方法标注了风险等级（高风险、中风险、低风险）

4. **进度指示器**：显示检测进度和完成百分比

5. **更详细的鼠标移动分析**：收集和分析鼠标移动轨迹来识别自动化

6. **WebGL供应商检测**：检测虚拟GPU（如LLVMPipe、SwiftShader等）

7. **Chrome DevTools Protocol痕迹检测**：检测CDP连接痕迹

8. **DOM API补丁检测**：检测被自动化工具重写的DOM API

9. **性能指标异常检测**：分析页面加载时间和性能数据

10. **iframe沙箱检测**：检测iframe隔离异常

11. **AudioContext检测**：检查浏览器音频API实现是否正常

12. **Chrome运行时检测**：检测自动化浏览器特有的Chrome运行时特征

13. **增强的用户交互**：重置按钮悬停效果、更流畅的动画

这个HTML文件现在包含了完整的Selenium检测工具，可以检测大多数自动化浏览器，包括那些试图隐藏自身的工具。您可以直接将此代码保存为HTML文件并在浏览器中打开使用。

