    <!-- 检测方法说明模态框 -->
    <div class="modal-overlay" id="methodsModal">
        <div class="modal-content">
            <button class="modal-close" id="closeModalBtn">&times;</button>
            <h2>检测方法说明</h2>
            <p>Selenium、Puppeteer等自动化工具会在浏览器中留下可检测的痕迹，以下是本工具使用的检测方法：</p>

            <div class="method-list">
                <h3>基础检测方法 <span class="highlight">(检测明显的自动化特征)</span></h3>

                <div class="method-item basic">
                    <strong>1. WebDriver 属性检测</strong>
                    <p>自动化浏览器通常会在 <span class="highlight">navigator.webdriver</span> 属性中返回 <span class="highlight">true</span>，而普通浏览器返回 <span class="highlight">undefined</span> 或 <span class="highlight">false</span>。</p>
                </div>

                <div class="method-item basic">
                    <strong>2. 插件列表检测</strong>
                    <p>自动化浏览器可能：返回空的插件列表、缺少常见的浏览器插件、插件列表包含自动化工具特有的项目。</p>
                </div>

                <div class="method-item basic">
                    <strong>3. 窗口属性检测</strong>
                    <p>Selenium会在window对象上添加属性如：<span class="highlight">_Selenium_IDE_Recorder</span>、<span class="highlight">callPhantom</span>、<span class="highlight">__webdriver_script_fn</span>等。</p>
                </div>

                <div class="method-item basic">
                    <strong>4. 权限检测</strong>
                    <p>检查浏览器是否支持某些功能，或权限状态是否异常：检查Notification权限、检测Chrome自动化扩展、检查浏览器驱动特征。</p>
                </div>

                <h3>高级检测方法 <span class="advanced-highlight">(检测隐藏的自动化特征)</span></h3>

                <div class="method-item advanced">
                    <strong>1. Chrome自动化扩展检测</strong>
                    <p>检测Chrome自动化扩展和修改的API，自动化浏览器经常修改Chrome API来隐藏自身。</p>
                </div>

                <div class="method-item advanced">
                    <strong>2. Chrome DevTools Protocol检测</strong>
                    <p>检测CDP连接痕迹，这是大多数自动化工具使用的底层协议。</p>
                </div>

                <div class="method-item advanced">
                    <strong>3. DOM API补丁检测</strong>
                    <p>自动化工具经常重写DOM API来隐藏自己，检测这些修改可以识别自动化。</p>
                </div>

                <div class="method-item advanced">
                    <strong>4. WebGL供应商检测</strong>
                    <p>自动化环境通常使用虚拟GPU如 <span class="highlight">LLVMPipe</span>、<span class="highlight">SwiftShader</span>，而真实浏览器使用硬件GPU。</p>
                </div>

                <div class="method-item advanced">
                    <strong>5. 性能指标异常检测</strong>
                    <p>自动化工具模拟的页面加载时间往往异常，或缺少真实的性能时间戳。</p>
                </div>

                <div class="method-item advanced">
                    <strong>6. iframe沙箱检测</strong>
                    <p>自动化工具可能不会正确实现iframe的隔离，通过检测iframe异常行为识别自动化。</p>
                </div>

                <h3>行为检测方法 <span class="highlight">(分析用户交互模式)</span></h3>

                <div class="method-item behavior">
                    <strong>1. 鼠标移动模式分析</strong>
                    <p>人类鼠标移动有自然的曲线和随机变化，而自动化工具通常产生直线或过于规律的移动。</p>
                </div>

                <div class="method-item behavior">
                    <strong>2. AudioContext检测</strong>
                    <p>自动化浏览器可能没有正确的AudioContext实现或实现不完整。</p>
                </div>

                <div class="method-item behavior">
                    <strong>3. Chrome运行时检测</strong>
                    <p>检测自动化浏览器特有的Chrome运行时特征，如特定的扩展ID或配置。</p>
                </div>

                <div class="method-item behavior">
                    <strong>4. 交互模式检测</strong>
                    <p>通过分析点击间隔、点击位置等交互模式识别自动化脚本。</p>
                </div>
            </div>

            <h3>如何避免被检测？</h3>
            <p>自动化工具可以通过以下方式尝试规避检测：</p>
            <ul>
                <li>使用无头浏览器检测规避插件</li>
                <li>修改WebDriver标志（ChromeOptions）</li>
                <li>模拟人类鼠标移动和点击模式</li>
                <li>随机化请求间隔和浏览行为</li>
                <li>使用真实浏览器的用户代理和插件配置</li>
                <li>禁用自动化扩展特征</li>
            </ul>
            <p><strong>注意：</strong>随着检测技术发展，完全规避检测变得越来越困难。</p>
        </div>
    </div>

    <script>
        // ============================================================================
        // 全局变量和配置
        // ============================================================================

        // 检测结果存储
        const detectionResults = {
            // 基础检测
            webdriver: false,
            plugins: false,
            languages: false,
            windowProps: false,
            permissions: false,

            // 高级检测
            chromeAutomation: false,
            cdpDetected: false,
            automationPatch: false,
            iframeDetection: false,
            webglVendor: false,
            performanceMetrics: false,
            audioContext: false,
            chromeRuntime: false,

            // 行为检测
            humanTest: false,
            mouseMovement: false
        };

        // 检测状态变量
        let humanTestClickCount = 0;
        let humanTestStartTime = null;
        let humanTestLastClickTime = null;
        let mouseEvents = [];
        let mouseEventCount = 0;
        let completedDetections = 0;
        const totalDetections = Object.keys(detectionResults).length;
        let detectionInProgress = false;
        let logEntries = [];

        // ============================================================================
        // 日志系统
        // ============================================================================

        /**
         * 添加日志条目
         * @param {string} message - 日志消息
         * @param {string} type - 日志类型: info, warn, error, success
         */
        function addLog(message, type = 'info') {
            const timestamp = new Date().toLocaleTimeString();
            const logEntry = {
                time: timestamp,
                message: message,
                type: type
            };

            logEntries.push(logEntry);

            // 更新日志显示
            const logContent = document.getElementById('logContent');
            const logEntryElement = document.createElement('div');
            logEntryElement.className = `log-entry log-${type}`;
            logEntryElement.innerHTML = `<span class="log-time">[${timestamp}]</span> ${message}`;

            logContent.appendChild(logEntryElement);

            // 自动滚动到底部
            logContent.scrollTop = logContent.scrollHeight;

            // 更新日志计数
            document.getElementById('logCount').textContent = `日志: ${logEntries.length}`;

            // 同时在控制台输出
            const consoleMethod = type === 'error' ? 'error' : 
                                 type === 'warn' ? 'warn' : 
                                 type === 'success' ? 'log' : 'info';
            console[consoleMethod](`[${timestamp}] ${message}`);
        }

        // ============================================================================
        // 高级检测器类
        // ============================================================================

        class AdvancedSeleniumDetector {

            /**
             * 检测Chrome自动化扩展
             * @returns {boolean} 是否检测到自动化特征
             */
            detectChromeAutomation() {
                try {
                    addLog('开始检测Chrome自动化扩展...', 'info');

                    // 检测Chrome自动化扩展
                    const isAutomationControlled = 
                        // 检查是否存在自动化相关属性
                        window.chrome && 
                        window.chrome.webstore && 
                        typeof window.chrome.webstore.install === 'function' &&
                        // 自动化浏览器中这个函数可能被修改
                        window.chrome.webstore.install.toString().includes('[native code]') === false;

                    // 检查Chrome的自动化标志
                    const automationFlag = 
                        window.navigator.webdriver === true ||
                        window.navigator.__proto__.webdriver === true ||
                        Object.getOwnPropertyDescriptor(navigator.__proto__, 'webdriver') !== undefined;

                    const result = isAutomationControlled || automationFlag;

                    if (result) {
                        addLog('检测到Chrome自动化扩展特征', 'warn');
                    } else {
                        addLog('未检测到Chrome自动化扩展特征', 'success');
                    }

                    return result;
                } catch (e) {
                    addLog(`Chrome自动化扩展检测出错: ${e.message}`, 'error');
                    return false;
                }
            }

            /**
             * 检测Chrome DevTools Protocol (CDP) 痕迹
             * @returns {boolean} 是否检测到CDP痕迹
             */
            detectCDP() {
                try {
                    addLog('开始检测Chrome DevTools Protocol痕迹...', 'info');

                    // 检查是否存在CDP相关函数
                    const cdpIndicators = [
                        'chrome.debugger',
                        'chrome.devtools',
                        '__chromeDevToolsProtocol'
                    ];

                    let detected = false;

                    // 检查全局对象
                    cdpIndicators.forEach(indicator => {
                        try {
                            if (eval(`typeof ${indicator}`) !== 'undefined') {
                                detected = true;
                                addLog(`检测到CDP指示器: ${indicator}`, 'warn');
                            }
                        } catch (e) {
                            // 忽略错误
                        }
                    });

                    if (detected) {
                        addLog('检测到CDP连接痕迹', 'warn');
                    } else {
                        addLog('未检测到CDP连接痕迹', 'success');
                    }

                    return detected;
                } catch (e) {
                    addLog(`CDP检测出错: ${e.message}`, 'error');
                    return false;
                }
            }

            /**
             * 检测被修改的DOM属性
             * @returns {boolean} 是否检测到DOM补丁
             */
            detectPatchedDOM() {
                try {
                    addLog('开始检测DOM API补丁...', 'info');

                    // 检查常见的被自动化工具修改的属性
                    const properties = [
                        'document.createElement',
                        'document.querySelector',
                        'window.navigator.userAgent',
                        'window.navigator.platform',
                        'window.navigator.languages'
                    ];

                    for (const prop of properties) {
                        try {
                            const value = eval(prop);

                            // 检查函数是否被重写
                            if (typeof value === 'function') {
                                const funcStr = value.toString();
                                // 如果函数被包装或修改
                                if (!funcStr.includes('[native code]') && 
                                    funcStr.length > 1000) { // 重写的函数通常很长
                                    addLog(`检测到DOM API补丁: ${prop}`, 'warn');
                                    return true;
                                }
                            }
                        } catch (e) {
                            // 忽略错误
                        }
                    }

                    addLog('未检测到DOM API补丁', 'success');
                    return false;
                } catch (e) {
                    addLog(`DOM补丁检测出错: ${e.message}`, 'error');
                    return false;
                }
            }

            /**
             * iframe沙箱检测
             * @returns {Promise<boolean>} 是否检测到iframe异常
             */
            detectIframeSandbox() {
                return new Promise((resolve) => {
                    try {
                        addLog('开始检测iframe沙箱异常...', 'info');

                        const iframe = document.createElement('iframe');
                        iframe.style.display = 'none';
                        document.body.appendChild(iframe);

                        // 尝试访问iframe内容
                        setTimeout(() => {
                            try {
                                // 在自动化环境中，iframe可能有不同的行为
                                const iframeDoc = iframe.contentDocument || iframe.contentWindow.document;

                                // 检查iframe是否被正确隔离
                                if (iframeDoc && iframeDoc.createElement) {
                                    const testElement = iframeDoc.createElement('div');
                                    // 自动化工具可能不会正确实现iframe的隔离
                                    if (testElement.constructor.name !== 'HTMLDivElement') {
                                        addLog('检测到iframe沙箱异常', 'warn');
                                        resolve(true);
                                        return;
                                    }
                                }

                                addLog('iframe沙箱正常', 'success');
                                resolve(false);
                            } catch (e) {
                                // 如果访问iframe抛出异常，可能是自动化环境
                                addLog('检测到iframe沙箱异常: 访问被阻止', 'warn');
                                resolve(true);
                            } finally {
                                document.body.removeChild(iframe);
                            }
                        }, 100);
                    } catch (e) {
                        addLog(`iframe检测出错: ${e.message}`, 'error');
                        resolve(false);
                    }
                });
            }

            /**
             * WebGL供应商检测
             * @returns {boolean} 是否检测到虚拟GPU
             */
            detectWebGLVendor() {
                try {
                    addLog('开始检测WebGL供应商...', 'info');

                    const canvas = document.createElement('canvas');
                    const gl = canvas.getContext('webgl') || canvas.getContext('experimental-webgl');

                    if (!gl) {
                        addLog('浏览器不支持WebGL，跳过检测', 'info');
                        return false;
                    }

                    const debugInfo = gl.getExtension('WEBGL_debug_renderer_info');
                    if (debugInfo) {
                        const vendor = gl.getParameter(debugInfo.UNMASKED_VENDOR_WEBGL);
                        const renderer = gl.getParameter(debugInfo.UNMASKED_RENDERER_WEBGL);

                        // 检查虚拟GPU或自动化环境特有的渲染器
                        const virtualGPUs = [
                            'llvmpipe',
                            'swiftshader',
                            'software',
                            'virtualbox',
                            'vmware',
                            'parallels'
                        ];

                        const vendorStr = (vendor + ' ' + renderer).toLowerCase();
                        const isVirtual = virtualGPUs.some(gpu => vendorStr.includes(gpu));

                        if (isVirtual) {
                            addLog(`检测到虚拟GPU: ${vendor} - ${renderer}`, 'warn');
                        } else {
                            addLog(`WebGL供应商正常: ${vendor} - ${renderer}`, 'success');
                        }

                        return isVirtual;
                    }

                    addLog('无法获取WebGL调试信息', 'info');
                    return false;
                } catch (e) {
                    addLog(`WebGL检测出错: ${e.message}`, 'error');
                    return false;
                }
            }

            /**
             * 性能指标检测
             * @returns {boolean} 是否检测到性能异常
             */
            detectPerformanceMetrics() {
                try {
                    addLog('开始检测性能指标异常...', 'info');

                    if (!window.performance || !window.performance.timing) {
                        addLog('浏览器不支持Performance API，跳过检测', 'info');
                        return false;
                    }

                    const timing = performance.timing;

                    // 检查时间戳是否合理
                    const navigationStart = timing.navigationStart;
                    const loadEventEnd = timing.loadEventEnd;

                    // 如果时间戳为0或异常，可能是自动化环境
                    if (navigationStart === 0 || loadEventEnd === 0) {
                        addLog('检测到异常性能时间戳', 'warn');
                        return true;
                    }

                    // 检查页面加载时间是否异常短（自动化工具可能模拟快速加载）
                    const loadTime = loadEventEnd - navigationStart;
                    if (loadTime > 0 && loadTime < 100) {
                        // 页面加载时间小于100ms，可能是自动化环境
                        addLog(`检测到异常页面加载时间: ${loadTime}ms`, 'warn');
                        return true;
                    }

                    addLog(`页面加载时间正常: ${loadTime}ms`, 'success');
                    return false;
                } catch (e) {
                    addLog(`性能指标检测出错: ${e.message}`, 'error');
                    return false;
                }
            }

            /**
             * AudioContext检测
             * @returns {boolean} 是否检测到AudioContext异常
             */
            detectAudioContext() {
                try {
                    addLog('开始检测AudioContext...', 'info');

                    if (!window.AudioContext && !window.webkitAudioContext) {
                        addLog('浏览器不支持AudioContext，跳过检测', 'info');
                        return false;
                    }

                    const AudioContext = window.AudioContext || window.webkitAudioContext;
                    const context = new AudioContext();

                    // 自动化浏览器可能没有正确的AudioContext实现
                    const oscillator = context.createOscillator();

                    // 检查属性和方法
                    const hasFrequency = typeof oscillator.frequency !== 'undefined';
                    const hasStart = typeof oscillator.start === 'function';
                    const hasStop = typeof oscillator.stop === 'function';

                    oscillator.stop();
                    context.close();

                    // 如果缺少基本功能，可能是自动化环境
                    const result = !(hasFrequency && hasStart && hasStop);

                    if (result) {
                        addLog('检测到AudioContext异常', 'warn');
                    } else {
                        addLog('AudioContext正常', 'success');
                    }

                    return result;
                } catch (e) {
                    // 创建AudioContext失败可能是自动化环境
                    addLog(`AudioContext检测出错: ${e.message}`, 'error');
                    return true;
                }
            }

            /**
             * Chrome运行时检测
             * @returns {boolean} 是否检测到Chrome运行时异常
             */
            detectChromeRuntime() {
                try {
                    addLog('开始检测Chrome运行时...', 'info');

                    if (!window.chrome || !window.chrome.runtime) {
                        addLog('非Chrome浏览器或Chrome运行时不可用', 'info');
                        return false;
                    }

                    // 尝试获取运行时ID
                    const runtimeId = chrome.runtime.id;

                    // 自动化浏览器可能有特定的运行时ID模式
                    if (runtimeId) {
                        // 检查ID是否包含自动化关键词
                        const automationKeywords = [
                            'webdriver',
                            'automation',
                            'selenium',
                            'chromedriver',
                            'headless'
                        ];

                        const idStr = runtimeId.toLowerCase();
                        const isAutomation = automationKeywords.some(keyword => idStr.includes(keyword));

                        if (isAutomation) {
                            addLog(`检测到自动化运行时ID: ${runtimeId}`, 'warn');
                        } else {
                            addLog(`Chrome运行时ID正常: ${runtimeId}`, 'success');
                        }

                        return isAutomation;
                    }

                    addLog('Chrome运行时正常', 'success');
                    return false;
                } catch (e) {
                    addLog(`Chrome运行时检测出错: ${e.message}`, 'error');
                    return false;
                }
            }
        }

