        /**
         * 1. WebDriver 检测
         */
        function checkWebDriver() {
            const webdriverCheck = document.getElementById('webdriverCheck');
            const webdriverStatus = document.getElementById('webdriverStatus');

            addLog('开始WebDriver属性检测...', 'info');

            // 标准WebDriver检测
            const hasWebDriver = navigator.webdriver === true;

            // 额外检查：某些自动化浏览器会隐藏webdriver属性，但仍有其他痕迹
            let extraChecks = false;

            // 检查是否可以通过其他方式检测到自动化
            try {
                // 尝试检测通过CDP（Chrome DevTools Protocol）控制的浏览器
                if (window.domAutomation || window.domAutomationController) {
                    extraChecks = true;
                    addLog('检测到domAutomation或domAutomationController', 'warn');
                }

                // 检查是否有被覆盖的属性
                const originalGetter = Object.getOwnPropertyDescriptor(navigator, 'webdriver')?.get;
                if (originalGetter && originalGetter.toString().includes('webdriver')) {
                    extraChecks = true;
                    addLog('检测到被覆盖的webdriver属性', 'warn');
                }
            } catch(e) {
                // 忽略错误
            }

            detectionResults.webdriver = hasWebDriver || extraChecks;

            if (detectionResults.webdriver) {
                webdriverCheck.classList.add('detected');
                webdriverCheck.classList.remove('clean');
                webdriverStatus.textContent = '检测到自动化特征';
                webdriverStatus.className = 'status detected';
                addLog('WebDriver检测: 检测到自动化特征', 'warn');
            } else {
                webdriverCheck.classList.add('clean');
                webdriverCheck.classList.remove('detected');
                webdriverStatus.textContent = '未检测到WebDriver';
                webdriverStatus.className = 'status clean';
                addLog('WebDriver检测: 未检测到自动化特征', 'success');
            }

            updateDetectionProgress();
        }

        /**
         * 2. 插件检测
         */
        function checkPlugins() {
            const pluginsCheck = document.getElementById('pluginsCheck');
            const pluginsStatus = document.getElementById('pluginsStatus');

            addLog('开始插件列表检测...', 'info');

            const plugins = navigator.plugins;
            let isSuspicious = false;

            // 检查插件列表是否异常
            if (!plugins || plugins.length === 0) {
                // 无插件可能是自动化浏览器
                isSuspicious = true;
                addLog('插件列表为空，可能是自动化浏览器', 'warn');
            } else {
                // 检查是否有常见的自动化相关插件
                const pluginNames = Array.from(plugins).map(p => p.name.toLowerCase());

                // 自动化浏览器可能包含特定插件或缺少常见插件
                const commonPlugins = ['chrome pdf viewer', 'native client', 'widevine content decryption module'];
                const hasCommonPlugins = commonPlugins.some(plugin => 
                    pluginNames.some(name => name.includes(plugin))
                );

                // 如果缺少常见插件，可能是自动化浏览器
                if (!hasCommonPlugins && plugins.length < 3) {
                    isSuspicious = true;
                    addLog(`缺少常见插件，插件数量: ${plugins.length}`, 'warn');
                }

                // 检查是否有自动化相关插件名称
                const automationKeywords = ['webdriver', 'selenium', 'puppeteer', 'automation'];
                const hasAutomationPlugins = automationKeywords.some(keyword => 
                    pluginNames.some(name => name.includes(keyword))
                );

                if (hasAutomationPlugins) {
                    isSuspicious = true;
                    addLog(`检测到自动化相关插件: ${pluginNames.join(', ')}`, 'warn');
                } else {
                    addLog(`插件列表正常: ${pluginNames.join(', ')}`, 'success');
                }
            }

            detectionResults.plugins = isSuspicious;

            if (detectionResults.plugins) {
                pluginsCheck.classList.add('detected');
                pluginsCheck.classList.remove('clean');
                pluginsStatus.textContent = '插件列表异常';
                pluginsStatus.className = 'status detected';
                addLog('插件检测: 检测到异常', 'warn');
            } else {
                pluginsCheck.classList.add('clean');
                pluginsCheck.classList.remove('detected');
                pluginsStatus.textContent = '插件列表正常';
                pluginsStatus.className = 'status clean';
                addLog('插件检测: 正常', 'success');
            }

            updateDetectionProgress();
        }

