                }
            } else {
                addLog('浏览器不支持Permissions API', 'info');
            }

            // 检查是否存在自动化扩展特征
            if (window.chrome && chrome.runtime && chrome.runtime.id) {
                try {
                    // 某些自动化工具会加载特定扩展
                    const manifest = chrome.runtime.getManifest();
                    if (manifest && manifest.name) {
                        const name = manifest.name.toLowerCase();
                        if (name.includes('webdriver') || name.includes('automation') || name.includes('selenium')) {
                            isSuspicious = true;
                            addLog(`检测到自动化扩展: ${manifest.name}`, 'warn');
                        } else {
                            addLog(`Chrome扩展名称: ${manifest.name}`, 'info');
                        }
                    }
                } catch(e) {
                    // 忽略错误
                }
            }

            detectionResults.permissions = isSuspicious;

            if (detectionResults.permissions) {
                permissionsCheck.classList.add('detected');
                permissionsCheck.classList.remove('clean');
                permissionsStatus.textContent = '权限配置异常';
                permissionsStatus.className = 'status detected';
                addLog('权限检测: 检测到异常', 'warn');
            } else {
