            margin: 10px 0;
            overflow: hidden;
        }

        .confidence-fill {
            height: 100%;
            background: linear-gradient(to right, #4cc9f0, #f72585);
            border-radius: 5px;
            transition: width 1s ease;
        }

        .detection-progress {
            display: inline-block;
            width: 20px;
            height: 20px;
            border: 2px solid #3a3a5d;
            border-top-color: #4cc9f0;
            border-radius: 50%;
            animation: spin 1s linear infinite;
            margin-right: 10px;
        }

        @keyframes spin {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
        }

        @media (max-width: 768px) {
            .content {
                flex-direction: column;
            }

            .control-section {
                border-left: none;
                border-top: 1px solid #3a3a5d;
            }

            h1 {
                font-size: 2rem;
            }

            .tab-container {
                flex-wrap: wrap;
            }

            .tab {
                flex: 1;
                text-align: center;
                min-width: 120px;
            }
        }

        .risk-level {
            display: inline-block;
            padding: 3px 10px;
            border-radius: 12px;
            font-size: 0.8rem;
            font-weight: bold;
            margin-left: 10px;
        }

        .risk-low {
            background-color: rgba(76, 201, 240, 0.2);
            color: #4cc9f0;
        }

        .risk-medium {
            background-color: rgba(255, 158, 0, 0.2);
            color: #ff9e00;
        }

        .risk-high {
            background-color: rgba(247, 37, 133, 0.2);
            color: #f72585;
        }

        .counter {
            font-size: 0.9rem;
            color: #a9a9b8;
            margin-top: 5px;
        }

        /* 模态框样式 */
        .modal-overlay {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background-color: rgba(0, 0, 0, 0.7);
            display: none;
            justify-content: center;
            align-items: center;
            z-index: 10000;
        }

        .modal-content {
            background-color: #1a1a2e;
            border-radius: 15px;
            padding: 30px;
            max-width: 800px;
            max-height: 80vh;
            overflow-y: auto;
            border: 2px solid #3a3a5d;
            position: relative;
        }

        .modal-close {
            position: absolute;
            top: 15px;
            right: 15px;
            background: none;
            border: none;
            color: #a9a9b8;
            font-size: 1.5rem;
            cursor: pointer;
            transition: color 0.3s;
        }

        .modal-close:hover {
            color: #f72585;
        }

        .method-list {
            margin-top: 20px;
        }

        .method-item {
            background-color: rgba(26, 26, 46, 0.7);
            border-radius: 8px;
            padding: 15px;
            margin-bottom: 15px;
            border-left: 4px solid #3a3a5d;
        }

        .method-item.basic {
            border-left-color: #4cc9f0;
        }

        .method-item.advanced {
            border-left-color: #ff9e00;
        }

        .method-item.behavior {
            border-left-color: #72efdd;
        }
    </style>
</head>
<body>
    <div class="container">
        <header>
            <h1><i class="fas fa-robot detection-icon"></i>Selenium 检测工具 - 高级版</h1>
            <p class="subtitle">使用17种检测技术识别Selenium、Puppeteer等自动化工具，包含基础、高级和行为检测方法</p>
        </header>

        <div class="content">
            <div class="detection-section">
                <div class="tab-container">
                    <div class="tab active" data-tab="basic">基础检测</div>
                    <div class="tab" data-tab="advanced">高级检测</div>
                    <div class="tab" data-tab="behavior">行为检测</div>
                </div>

                <div class="tab-content active" id="basic-tab">
                    <h2>基础自动化检测 <span class="counter">(检测明显的自动化特征)</span></h2>

                    <div class="result-box">
                        <div class="detection-item" id="webdriverCheck">
                            <div class="detection-header">
                                <i class="fas fa-desktop detection-icon"></i>
                                <strong>WebDriver属性检测</strong>
                                <span class="risk-level risk-high">高风险</span>
                            </div>
                            <p>检查 navigator.webdriver 属性，这是自动化浏览器最常见的标志。</p>
                            <div class="status" id="webdriverStatus">等待检测...</div>
                        </div>

                        <div class="detection-item" id="pluginsCheck">
                            <div class="detection-header">
                                <i class="fas fa-plug detection-icon"></i>
                                <strong>插件列表检测</strong>
                                <span class="risk-level risk-medium">中风险</span>
                            </div>
                            <p>自动化浏览器通常有异常的插件列表或缺少常见插件。</p>
                            <div class="status" id="pluginsStatus">等待检测...</div>
                        </div>

                        <div class="detection-item" id="languagesCheck">
                            <div class="detection-header">
                                <i class="fas fa-language detection-icon"></i>
                                <strong>语言设置检测</strong>
                                <span class="risk-level risk-low">低风险</span>
                            </div>
                            <p>自动化浏览器可能具有非标准的语言设置。</p>
                            <div class="status" id="languagesStatus">等待检测...</div>
                        </div>

                        <div class="detection-item" id="windowCheck">
                            <div class="detection-header">
                                <i class="fas fa-window-maximize detection-icon"></i>
                                <strong>窗口属性检测</strong>
                                <span class="risk-level risk-high">高风险</span>
                            </div>
                            <p>自动化工具会在window对象上留下特定属性。</p>
                            <div class="status" id="windowStatus">等待检测...</div>
                        </div>

                        <div class="detection-item" id="permissionsCheck">
                            <div class="detection-header">
                                <i class="fas fa-user-shield detection-icon"></i>
                                <strong>权限检测</strong>
                                <span class="risk-level risk-medium">中风险</span>
                            </div>
                            <p>检查浏览器权限状态，自动化浏览器可能有不同的权限配置。</p>
                            <div class="status" id="permissionsStatus">等待检测...</div>
                        </div>
                    </div>
                </div>

                <div class="tab-content" id="advanced-tab">
                    <h2>高级自动化检测 <span class="counter">(检测隐藏的自动化特征)</span></h2>

                    <div class="result-box">
                        <div class="detection-item advanced" id="chromeAutomationCheck">
                            <div class="detection-header">
                                <i class="fas fa-code detection-icon"></i>
                                <strong>Chrome自动化扩展检测</strong>
                                <span class="risk-level risk-high">高风险</span>
                            </div>
                            <p>检测Chrome自动化扩展和修改的API。</p>
                            <div class="status" id="chromeAutomationStatus">等待检测...</div>
                        </div>

                        <div class="detection-item advanced" id="cdpCheck">
                            <div class="detection-header">
                                <i class="fas fa-tools detection-icon"></i>
                                <strong>Chrome DevTools Protocol检测</strong>
                                <span class="risk-level risk-high">高风险</span>
                            </div>
                            <p>检测CDP连接和调试痕迹。</p>
                            <div class="status" id="cdpStatus">等待检测...</div>
                        </div>

                        <div class="detection-item advanced" id="domPatchCheck">
                            <div class="detection-header">
                                <i class="fas fa-puzzle-piece detection-icon"></i>
                                <strong>DOM API补丁检测</strong>
                                <span class="risk-level risk-high">高风险</span>
                            </div>
                            <p>检测被修改的DOM属性和方法。</p>
                            <div class="status" id="domPatchStatus">等待检测...</div>
                        </div>

                        <div class="detection-item advanced" id="webglCheck">
                            <div class="detection-header">
                                <i class="fas fa-gamepad detection-icon"></i>
                                <strong>WebGL供应商检测</strong>
                                <span class="risk-level risk-high">高风险</span>
                            </div>
                            <p>检测虚拟GPU和自动化环境特有的渲染器。</p>
                            <div class="status" id="webglStatus">等待检测...</div>
                        </div>

                        <div class="detection-item advanced" id="performanceCheck">
                            <div class="detection-header">
                                <i class="fas fa-tachometer-alt detection-icon"></i>
                                <strong>性能指标异常检测</strong>
                                <span class="risk-level risk-medium">中风险</span>
                            </div>
                            <p>检测异常的页面加载时间和性能数据。</p>
                            <div class="status" id="performanceStatus">等待检测...</div>
                        </div>

                        <div class="detection-item advanced" id="iframeCheck">
                            <div class="detection-header">
                                <i class="fas fa-square detection-icon"></i>
                                <strong>iframe沙箱检测</strong>
                                <span class="risk-level risk-medium">中风险</span>
                            </div>
                            <p>检测iframe隔离异常，自动化工具可能不会正确实现iframe隔离。</p>
                            <div class="status" id="iframeStatus">等待检测...</div>
                        </div>
                    </div>
                </div>

                <div class="tab-content" id="behavior-tab">
                    <h2>人类行为检测 <span class="counter">(分析用户交互模式)</span></h2>

                    <div class="result-box">
                        <div class="detection-item" id="mousePatternCheck">
                            <div class="detection-header">
                                <i class="fas fa-mouse-pointer detection-icon"></i>
                                <strong>鼠标移动模式检测</strong>
                                <span class="risk-level risk-high">高风险</span>
                            </div>
                            <p>分析鼠标移动轨迹识别自动化工具。人类鼠标移动有自然的曲线和变化。</p>
                            <div class="status" id="mousePatternStatus">等待检测...</div>
                            <div class="counter" id="mouseEventCount">已记录鼠标事件: 0</div>
                        </div>

                        <div class="detection-item" id="audioContextCheck">
                            <div class="detection-header">
                                <i class="fas fa-volume-up detection-icon"></i>
                                <strong>AudioContext检测</strong>
                                <span class="risk-level risk-medium">中风险</span>
                            </div>
                            <p>自动化浏览器可能没有正确的AudioContext实现。</p>
                            <div class="status" id="audioContextStatus">等待检测...</div>
                        </div>

                        <div class="detection-item" id="chromeRuntimeCheck">
                            <div class="detection-header">
                                <i class="fas fa-cogs detection-icon"></i>
                                <strong>Chrome运行时检测</strong>
                                <span class="risk-level risk-medium">中风险</span>
                            </div>
                            <p>检测自动化浏览器特有的Chrome运行时特征。</p>
                            <div class="status" id="chromeRuntimeStatus">等待检测...</div>
                        </div>
                    </div>

                    <div class="human-test-area">
                        <h3>交互测试</h3>
                        <p>点击下面的按钮测试人类交互模式。自动化脚本通常有可预测的点击模式。</p>
                        <button class="test-button" id="humanTest">点击我测试</button>
                        <div class="test-result" id="humanTestResult"></div>
                        <div class="counter" id="clickCounter">点击次数: 0</div>
                    </div>
                </div>
            </div>

            <div class="control-section">
                <h2>控制面板</h2>

                <button class="info-button" id="showMethodsBtn">
                    <i class="fas fa-info-circle"></i> 查看检测方法说明
                </button>

                <div class="control-buttons">
                    <button class="control-button" id="startDetectionBtn">
                        <i class="fas fa-play"></i> 开始检测
                    </button>
                    <button class="control-button" id="resetDetectionBtn">
                        <i class="fas fa-redo"></i> 重新检测
                    </button>
                    <button class="control-button" id="exportLogBtn">
                        <i class="fas fa-download"></i> 导出日志
                    </button>
                    <button class="control-button" id="clearLogBtn">
                        <i class="fas fa-trash"></i> 清除日志
                    </button>
                </div>

                <div class="log-panel">
                    <div class="log-header">
                        <h3>检测日志</h3>
                        <span class="counter" id="logCount">日志: 0</span>
                    </div>
                    <div class="log-content" id="logContent">
                        <!-- 日志内容将动态添加 -->
                    </div>
                </div>
            </div>
        </div>

        <div class="overall-result">
            <h2>总体检测结果</h2>
            <p>基于17种检测方法，您的浏览器被判定为：</p>
            <div class="result-text" id="overallResult">等待检测...</div>
            <div class="confidence-meter">
                <div class="confidence-fill" id="confidenceFill" style="width: 0%"></div>
            </div>
            <p id="resultExplanation">点击"开始检测"按钮开始分析浏览器特征</p>
            <div class="counter" id="detectionCounter">检测进度: 0/17</div>
        </div>

        <footer>
            <p>© 2023 Selenium检测工具 | 仅供教育目的 | 注意：没有任何检测方法是100%准确的</p>
            <p>检测结果可能因浏览器版本和自动化工具的配置而有所不同</p>
        </footer>
    </div>

    <!-- 检测方法说明模态框 -->
    <div class="modal-overlay" id="methodsModal">
        <div class="modal-content">
            <button class="modal-close" id="closeModalBtn">&times;</button>
            <h2>检测方法说明</h2>
            <p>Selenium、Puppeteer等自动化工具会在浏览器中留下可检测的痕迹，以下是本工具使用的检测方法：</p>

            <div class="method-list">
                <h3>基础检测方法 <span class="highlight">(检测明显的自动化特征)</span></h3>

                <div class="method-item basic">
                    <strong>1. WebDriver 属性检测</strong>
                    <p>自动化浏览器通常会在 <span class="highlight">navigator.webdriver</span> 属性中返回 <span class="highlight">true</span>，而普通浏览器返回 <span class="highlight">undefined</span> 或 <span class="highlight">false</span>。</p>
                </div>

                <div class="method-item basic">
                    <strong>2. 插件列表检测</strong>
                    <p>自动化浏览器可能：返回空的插件列表、缺少常见的浏览器插件、插件列表包含自动化工具特有的项目。</p>
                </div>

                <div class="method-item basic">
                    <strong>3. 窗口属性检测</strong>
                    <p>Selenium会在window对象上添加属性如：<span class="highlight">_Selenium_IDE_Recorder</span>、<span class="highlight">callPhantom</span>、<span class="highlight">__webdriver_script_fn</span>等。</p>
                </div>

                <div class="method-item basic">
                    <strong>4. 权限检测</strong>
                    <p>检查浏览器是否支持某些功能，或权限状态是否异常：检查Notification权限、检测Chrome自动化扩展、检查浏览器驱动特征。</p>
                </div>

                <h3>高级检测方法 <span class="advanced-highlight">(检测隐藏的自动化特征)</span></h3>

                <div class="method-item advanced">
                    <strong>1. Chrome自动化扩展检测</strong>
                    <p>检测Chrome自动化扩展和修改的API，自动化浏览器经常修改Chrome API来隐藏自身。</p>
                </div>

                <div class="method-item advanced">
                    <strong>2. Chrome DevTools Protocol检测</strong>
                    <p>检测CDP连接痕迹，这是大多数自动化工具使用的底层协议。</p>
                </div>

                <div class="method-item advanced">
                    <strong>3. DOM API补丁检测</strong>
                    <p>自动化工具经常重写DOM API来隐藏自己，检测这些修改可以识别自动化。</p>
                </div>

                <div class="method-item advanced">
                    <strong>4. WebGL供应商检测</strong>
                    <p>自动化环境通常使用虚拟GPU如 <span class="highlight">LLVMPipe</span>、<span class="highlight">SwiftShader</span>，而真实浏览器使用硬件GPU。</p>
                </div>

                <div class="method-item advanced">
                    <strong>5. 性能指标异常检测</strong>
                    <p>自动化工具模拟的页面加载时间往往异常，或缺少真实的性能时间戳。</p>
                </div>

                <div class="method-item advanced">
                    <strong>6. iframe沙箱检测</strong>
                    <p>自动化工具可能不会正确实现iframe的隔离，通过检测iframe异常行为识别自动化。</p>
                </div>

                <h3>行为检测方法 <span class="highlight">(分析用户交互模式)</span></h3>

                <div class="method-item behavior">
                    <strong>1. 鼠标移动模式分析</strong>
                    <p>人类鼠标移动有自然的曲线和随机变化，而自动化工具通常产生直线或过于规律的移动。</p>
                </div>

                <div class="method-item behavior">
                    <strong>2. AudioContext检测</strong>
                    <p>自动化浏览器可能没有正确的AudioContext实现或实现不完整。</p>
                </div>

                <div class="method-item behavior">
                    <strong>3. Chrome运行时检测</strong>
                    <p>检测自动化浏览器特有的Chrome运行时特征，如特定的扩展ID或配置。</p>
                </div>

                <div class="method-item behavior">
                    <strong>4. 交互模式检测</strong>
                    <p>通过分析点击间隔、点击位置等交互模式识别自动化脚本。</p>
                </div>
            </div>

            <h3>如何避免被检测？</h3>
            <p>自动化工具可以通过以下方式尝试规避检测：</p>
            <ul>
                <li>使用无头浏览器检测规避插件</li>
                <li>修改WebDriver标志（ChromeOptions）</li>
                <li>模拟人类鼠标移动和点击模式</li>
                <li>随机化请求间隔和浏览行为</li>
                <li>使用真实浏览器的用户代理和插件配置</li>
                <li>禁用自动化扩展特征</li>
            </ul>
            <p><strong>注意：</strong>随着检测技术发展，完全规避检测变得越来越困难。</p>
        </div>
    </div>

    <script>
        // ============================================================================
        // 全局变量和配置
        // ============================================================================

        // 检测结果存储
        const detectionResults = {
            // 基础检测
            webdriver: false,
            plugins: false,
            languages: false,
            windowProps: false,
            permissions: false,

            // 高级检测
            chromeAutomation: false,
            cdpDetected: false,
            automationPatch: false,
            iframeDetection: false,
            webglVendor: false,
            performanceMetrics: false,
            audioContext: false,
            chromeRuntime: false,

            // 行为检测
            humanTest: false,
            mouseMovement: false
        };

        // 检测状态变量
        let humanTestClickCount = 0;
        let humanTestStartTime = null;
        let humanTestLastClickTime = null;
        let mouseEvents = [];
        let mouseEventCount = 0;
        let completedDetections = 0;
        const totalDetections = Object.keys(detectionResults).length;
        let detectionInProgress = false;
        let logEntries = [];

        // ============================================================================
        // 日志系统
        // ============================================================================

        /**
         * 添加日志条目
         * @param {string} message - 日志消息
         * @param {string} type - 日志类型: info, warn, error, success
         */
        function addLog(message, type = 'info') {
            const timestamp = new Date().toLocaleTimeString();
            const logEntry = {
                time: timestamp,
                message: message,
                type: type
            };

            logEntries.push(logEntry);

            // 更新日志显示
            const logContent = document.getElementById('logContent');
            const logEntryElement = document.createElement('div');
            logEntryElement.className = `log-entry log-${type}`;
            logEntryElement.innerHTML = `<span class="log-time">[${timestamp}]</span> ${message}`;

            logContent.appendChild(logEntryElement);

            // 自动滚动到底部
            logContent.scrollTop = logContent.scrollHeight;

            // 更新日志计数
            document.getElementById('logCount').textContent = `日志: ${logEntries.length}`;

            // 同时在控制台输出
            const consoleMethod = type === 'error' ? 'error' : 
                                 type === 'warn' ? 'warn' : 
                                 type === 'success' ? 'log' : 'info';
            console[consoleMethod](`[${timestamp}] ${message}`);
        }

        // ============================================================================
        // 高级检测器类
        // ============================================================================

        class AdvancedSeleniumDetector {

            /**
             * 检测Chrome自动化扩展 - 修复版
             * @returns {boolean} 是否检测到自动化特征
             */
            detectChromeAutomation() {
                try {
                    addLog('开始检测Chrome自动化扩展...', 'info');

                    let isAutomationControlled = false;

                    // 检查1: 检查是否存在chrome对象
                    if (!window.chrome) {
                        addLog('未检测到Chrome对象', 'info');
                        return false;
                    }

                    // 检查2: 检查webdriver标志（已包含在基础检测中，但这里再次确认）
                    if (navigator.webdriver === true) {
                        addLog('检测到navigator.webdriver = true', 'warn');
                        isAutomationControlled = true;
                    }

                    // 检查3: 检查chrome对象是否被修改（安全方式）
                    try {
                        // 检查chrome对象是否有异常属性
                        const chromeKeys = Object.keys(window.chrome);
                        const commonChromeKeys = ['runtime', 'tabs', 'windows', 'storage', 'cookies', 'webRequest'];

                        // 统计chrome对象的标准属性数量
                        const standardKeyCount = chromeKeys.filter(key => 
                            commonChromeKeys.includes(key)
                        ).length;

                        // 如果chrome对象存在但标准属性很少，可能是自动化环境
                        if (chromeKeys.length > 0 && standardKeyCount < 3) {
                            addLog(`Chrome对象异常: 标准属性少 (${standardKeyCount}/${chromeKeys.length})`, 'warn');
                            isAutomationControlled = true;
                        }
                    } catch (e) {
                        // 忽略错误
                    }

                    // 检查4: 检查是否存在自动化相关属性（使用安全的方式）
                    const automationProperties = [
                        '_Selenium_IDE_Recorder',
                        'callPhantom',
                        '__webdriver_script_fn',
                        'domAutomation',
                        'domAutomationController'
                    ];

                    for (const prop of automationProperties) {
                        if (prop in window) {
                            addLog(`检测到自动化属性: ${prop}`, 'warn');
                            isAutomationControlled = true;
                            break;
                        }
                    }

                    // 检查5: 检查chrome.runtime是否存在异常
                    if (window.chrome && window.chrome.runtime) {
                        try {
                            // 尝试安全地检查runtime.id
                            if (chrome.runtime.id) {
                                const id = chrome.runtime.id.toLowerCase();
                                if (id.includes('webdriver') || id.includes('automation') || id.includes('selenium')) {
                                    addLog(`检测到自动化运行时ID: ${chrome.runtime.id}`, 'warn');
                                    isAutomationControlled = true;
                                }
                            }
                        } catch (e) {
                            // 忽略错误
                        }
                    }

                    if (isAutomationControlled) {
                        addLog('检测到Chrome自动化扩展特征', 'warn');
                    } else {
                        addLog('未检测到Chrome自动化扩展特征', 'success');
                    }

                    return isAutomationControlled;
                } catch (e) {
                    addLog(`Chrome自动化扩展检测出错: ${e.message}`, 'error');
                    return false;
                }
            }

            /**
             * 检测Chrome DevTools Protocol (CDP) 痕迹 - 修复版
             * @returns {boolean} 是否检测到CDP痕迹
             */
            detectCDP() {
                try {
                    addLog('开始检测Chrome DevTools Protocol痕迹...', 'info');

                    // 检查是否存在CDP相关函数 - 使用安全的方式
                    const cdpIndicators = [
                        'chrome.debugger',
                        'chrome.devtools',
                        '__chromeDevToolsProtocol'
                    ];

                    let detected = false;

                    // 检查全局对象 - 使用try-catch包装
                    cdpIndicators.forEach(indicator => {
                        try {
                            // 使用更安全的方式检查属性是否存在
                            const indicatorPath = indicator.split('.');
                            let current = window;

                            for (const part of indicatorPath) {
                                if (current && typeof current === 'object' && part in current) {
                                    current = current[part];
                                } else {
                                    current = undefined;
                                    break;
                                }
                            }

                            if (current !== undefined) {
                                detected = true;
                                addLog(`检测到CDP指示器: ${indicator}`, 'warn');
                            }
                        } catch (e) {
                            // 忽略错误
                        }
                    });

                    // 额外检查：检查window对象上是否有调试相关属性
                    try {
                        const debugProps = ['_debug', '__debug', '_chrome_debug'];
                        for (const prop of debugProps) {
                            if (prop in window) {
                                detected = true;
                                addLog(`检测到调试属性: ${prop}`, 'warn');
                                break;
                            }
                        }
                    } catch (e) {
                        // 忽略错误
                    }

                    if (detected) {
                        addLog('检测到CDP连接痕迹', 'warn');
                    } else {
                        addLog('未检测到CDP连接痕迹', 'success');
                    }

                    return detected;
                } catch (e) {
                    addLog(`CDP检测出错: ${e.message}`, 'error');
                    return false;
                }
            }

            /**
             * 检测被修改的DOM属性 - 修复版
             * @returns {boolean} 是否检测到DOM补丁
             */
            detectPatchedDOM() {
                try {
                    addLog('开始检测DOM API补丁...', 'info');

                    // 检查常见的被自动化工具修改的属性 - 使用安全的方式
                    const properties = [
                        'document.createElement',
                        'document.querySelector',
                        'window.navigator.userAgent',
                        'window.navigator.platform'
                    ];

                    for (const prop of properties) {
                        try {
                            // 安全地获取属性值
                            const value = eval(`(() => { try { return ${prop}; } catch(e) { return null; } })()`);

                            if (value === null) continue;

                            // 检查函数是否被重写
                            if (typeof value === 'function') {
                                // 使用Function.prototype.toString.call安全地获取函数字符串
                                let funcStr;
                                try {
                                    funcStr = Function.prototype.toString.call(value);
                                } catch (e) {
                                    // 如果无法获取字符串表示，尝试直接调用toString
                                    try {
                                        funcStr = value.toString();
                                    } catch (e2) {
                                        continue;
                                    }
                                }

                                // 如果函数被包装或修改
                                if (!funcStr.includes('[native code]')) {
                                    // 检查函数长度（重写的函数通常很长）
                                    if (funcStr.length > 1000) {
                                        addLog(`检测到DOM API补丁: ${prop} (长度: ${funcStr.length})`, 'warn');
                                        return true;
                                    }

                                    // 检查函数是否包含自动化关键词
                                    const automationKeywords = ['webdriver', 'selenium', 'automation', 'puppeteer'];
                                    const hasKeyword = automationKeywords.some(keyword => 
                                        funcStr.toLowerCase().includes(keyword)
                                    );

                                    if (hasKeyword) {
                                        addLog(`检测到DOM API补丁包含自动化关键词: ${prop}`, 'warn');
                                        return true;
                                    }
                                }
                            }
                        } catch (e) {
                            // 忽略单个属性的检测错误
                            continue;
                        }
                    }

                    addLog('未检测到DOM API补丁', 'success');
                    return false;
                } catch (e) {
                    addLog(`DOM补丁检测出错: ${e.message}`, 'error');
                    return false;
                }
            }

            /**
             * iframe沙箱检测 - 修复版
             * @returns {Promise<boolean>} 是否检测到iframe异常
             */
            detectIframeSandbox() {
                return new Promise((resolve) => {
                    try {
                        addLog('开始检测iframe沙箱异常...', 'info');

                        const iframe = document.createElement('iframe');
                        iframe.style.display = 'none';
                        iframe.sandbox = 'allow-scripts'; // 设置沙箱属性
                        document.body.appendChild(iframe);

                        // 尝试访问iframe内容
                        setTimeout(() => {
                            try {
                                // 在自动化环境中，iframe可能有不同的行为
                                let iframeDoc;
                                try {
                                    iframeDoc = iframe.contentDocument || iframe.contentWindow.document;
                                } catch (e) {
                                    // 如果访问被拒绝，可能是沙箱限制，这是正常的
                                    addLog('iframe访问被拒绝（正常沙箱行为）', 'info');
                                    resolve(false);
                                    return;
                                }

                                // 检查iframe是否被正确隔离
                                if (iframeDoc && iframeDoc.createElement) {
                                    const testElement = iframeDoc.createElement('div');
                                    // 自动化工具可能不会正确实现iframe的隔离
                                    if (testElement.constructor.name !== 'HTMLDivElement') {
                                        addLog('检测到iframe沙箱异常: 元素构造函数异常', 'warn');
                                        resolve(true);
                                        return;
                                    }

                                    // 检查iframe的window对象是否被隔离
                                    try {
                                        const iframeWindow = iframe.contentWindow;
                                        if (iframeWindow && iframeWindow === window) {
                                            addLog('检测到iframe沙箱异常: iframe窗口与主窗口相同', 'warn');
                                            resolve(true);
                                            return;
                                        }
                                    } catch (e) {
                                        // 忽略错误
                                    }
                                }

                                addLog('iframe沙箱正常', 'success');
                                resolve(false);
                            } catch (e) {
                                // 如果访问iframe抛出异常，可能是自动化环境
                                addLog('检测到iframe沙箱异常: ' + e.message, 'warn');
                                resolve(true);
                            } finally {
                                try {
                                    document.body.removeChild(iframe);
                                } catch (e) {
                                    // 忽略移除错误
                                }
                            }
                        }, 100);
                    } catch (e) {
                        addLog(`iframe检测出错: ${e.message}`, 'error');
                        resolve(false);
                    }
                });
            }

            /**
             * WebGL供应商检测 - 修复版
             * @returns {boolean} 是否检测到虚拟GPU
             */
            detectWebGLVendor() {
                try {
                    addLog('开始检测WebGL供应商...', 'info');

                    const canvas = document.createElement('canvas');
                    let gl = null;

                    try {
                        gl = canvas.getContext('webgl') || canvas.getContext('experimental-webgl');
                    } catch (e) {
                        addLog('WebGL上下文创建失败: ' + e.message, 'info');
                        return false;
                    }

                    if (!gl) {
                        addLog('浏览器不支持WebGL，跳过检测', 'info');
                        return false;
                    }

                    let debugInfo = null;
                    try {
                        debugInfo = gl.getExtension('WEBGL_debug_renderer_info');
                    } catch (e) {
                        addLog('无法获取WebGL调试扩展: ' + e.message, 'info');
                        return false;
                    }

                    if (debugInfo) {
                        let vendor, renderer;
                        try {
                            vendor = gl.getParameter(debugInfo.UNMASKED_VENDOR_WEBGL);
                            renderer = gl.getParameter(debugInfo.UNMASKED_RENDERER_WEBGL);
                        } catch (e) {
                            addLog('无法获取WebGL供应商信息: ' + e.message, 'info');
                            return false;
                        }

                        // 检查虚拟GPU或自动化环境特有的渲染器
                        const virtualGPUs = [
                            'llvmpipe',
                            'swiftshader',
                            'software',
                            'virtualbox',
                            'vmware',
                            'parallels',
                            'chromium'
                        ];

                        const vendorStr = (vendor + ' ' + renderer).toLowerCase();
                        let isVirtual = false;

                        for (const gpu of virtualGPUs) {
                            if (vendorStr.includes(gpu)) {
                                isVirtual = true;
                                break;
                            }
                        }

                        if (isVirtual) {
                            addLog(`检测到虚拟GPU: ${vendor} - ${renderer}`, 'warn');
                        } else {
                            addLog(`WebGL供应商正常: ${vendor} - ${renderer}`, 'success');
                        }

                        return isVirtual;
                    }

                    addLog('无法获取WebGL调试信息', 'info');
                    return false;
                } catch (e) {
                    addLog(`WebGL检测出错: ${e.message}`, 'error');
                    return false;
                }
            }

            /**
             * 性能指标检测 - 修复版
             * @returns {boolean} 是否检测到性能异常
             */
            detectPerformanceMetrics() {
                try {
                    addLog('开始检测性能指标异常...', 'info');

                    if (!window.performance || !window.performance.timing) {
                        addLog('浏览器不支持Performance API，跳过检测', 'info');
                        return false;
                    }

                    const timing = performance.timing;

                    // 检查时间戳是否合理
                    const navigationStart = timing.navigationStart;
                    const loadEventEnd = timing.loadEventEnd;

                    // 如果时间戳为0或异常，可能是自动化环境
                    if (navigationStart === 0) {
                        addLog('检测到异常导航开始时间', 'warn');
                        return true;
                    }

                    // 检查页面加载时间是否异常短（自动化工具可能模拟快速加载）
                    if (loadEventEnd > 0) {
                        const loadTime = loadEventEnd - navigationStart;
                        if (loadTime > 0 && loadTime < 100) {
                            // 页面加载时间小于100ms，可能是自动化环境
                            addLog(`检测到异常页面加载时间: ${loadTime}ms`, 'warn');
                            return true;
                        }

                        addLog(`页面加载时间: ${loadTime}ms`, 'info');
                    }

                    // 检查performance.now()的异常
                    try {
                        const perfNow1 = performance.now();
                        setTimeout(() => {
                            const perfNow2 = performance.now();
                            const diff = perfNow2 - perfNow1;

                            // 如果时间差异常小或大，可能是自动化环境
                            if (diff < 5 || diff > 150) { // 10ms setTimeout实际可能有15ms左右
                                addLog(`检测到异常performance.now()差异: ${diff}ms`, 'warn');
                            }
                        }, 10);
                    } catch (e) {
                        // 忽略错误
                    }

                    addLog('性能指标正常', 'success');
                    return false;
                } catch (e) {
                    addLog(`性能指标检测出错: ${e.message}`, 'error');
                    return false;
                }
            }

            /**
             * AudioContext检测 - 修复版
             * @returns {boolean} 是否检测到AudioContext异常
             */
            detectAudioContext() {
                try {
                    addLog('开始检测AudioContext...', 'info');

                    if (!window.AudioContext && !window.webkitAudioContext) {
                        addLog('浏览器不支持AudioContext，跳过检测', 'info');
                        return false;
                    }

                    const AudioContext = window.AudioContext || window.webkitAudioContext;
                    let context;

                    try {
                        context = new AudioContext();
                    } catch (e) {
                        addLog('AudioContext创建失败: ' + e.message, 'warn');
                        return true; // 创建失败可能是自动化环境
                    }

                    // 检查context是否正常工作
                    if (!context || context.state === 'suspended') {
                        addLog('AudioContext状态异常: ' + (context ? context.state : 'null'), 'warn');
                        try {
                            if (context) context.close();
                        } catch (e) {}
                        return true;
                    }

                    // 自动化浏览器可能没有正确的AudioContext实现
                    let oscillator;
                    try {
                        oscillator = context.createOscillator();
                    } catch (e) {
                        addLog('无法创建Oscillator: ' + e.message, 'warn');
                        try {
                            context.close();
                        } catch (e) {}
                        return true;
                    }

                    // 检查属性和方法
                    const hasFrequency = typeof oscillator.frequency !== 'undefined';
                    const hasStart = typeof oscillator.start === 'function';
                    const hasStop = typeof oscillator.stop === 'function';

                    // 尝试停止振荡器
                    try {
                        if (hasStop) {
                            oscillator.stop();
                        }
                    } catch (e) {
                        // 忽略停止错误
                    }

                    // 关闭上下文
                    try {
                        context.close();
                    } catch (e) {
                        // 忽略关闭错误
                    }

                    // 如果缺少基本功能，可能是自动化环境
                    const result = !(hasFrequency && hasStart && hasStop);

                    if (result) {
                        addLog('检测到AudioContext异常', 'warn');
                    } else {
                        addLog('AudioContext正常', 'success');
                    }

                    return result;
                } catch (e) {
                    // 创建AudioContext失败可能是自动化环境
                    addLog(`AudioContext检测出错: ${e.message}`, 'error');
                    return true;
                }
            }

            /**
             * Chrome运行时检测 - 修复版
             * @returns {boolean} 是否检测到Chrome运行时异常
             */
            detectChromeRuntime() {
                try {
                    addLog('开始检测Chrome运行时...', 'info');

                    if (!window.chrome || !window.chrome.runtime) {
                        addLog('非Chrome浏览器或Chrome运行时不可用', 'info');
                        return false;
                    }

                    let runtimeId = null;
                    try {
                        runtimeId = chrome.runtime.id;
                    } catch (e) {
                        addLog('无法获取Chrome运行时ID: ' + e.message, 'info');
                        return false;
                    }

                    // 自动化浏览器可能有特定的运行时ID模式
                    if (runtimeId) {
                        // 检查ID是否包含自动化关键词
                        const automationKeywords = [
                            'webdriver',
                            'automation',
                            'selenium',
                            'chromedriver',
                            'headless'
                        ];

                        const idStr = runtimeId.toLowerCase();
                        const isAutomation = automationKeywords.some(keyword => idStr.includes(keyword));

                        if (isAutomation) {
                            addLog(`检测到自动化运行时ID: ${runtimeId}`, 'warn');
                        } else {
                            addLog(`Chrome运行时ID: ${runtimeId}`, 'info');
                        }

                        return isAutomation;
                    }

                    // 检查chrome.runtime的其他属性
                    try {
                        const runtimeProps = Object.keys(chrome.runtime);
                        if (runtimeProps.length === 0) {
                            addLog('Chrome运行时属性为空，可能异常', 'warn');
                            return true;
                        }
                    } catch (e) {
                        // 忽略错误
                    }

                    addLog('Chrome运行时正常', 'success');
                    return false;
                } catch (e) {
                    addLog(`Chrome运行时检测出错: ${e.message}`, 'error');
                    return false;
                }
            }
        }

        // ============================================================================
        // 基础检测方法
        // ============================================================================

        /**
         * 1. WebDriver 检测
         */
        function checkWebDriver() {
            const webdriverCheck = document.getElementById('webdriverCheck');
            const webdriverStatus = document.getElementById('webdriverStatus');

            addLog('开始WebDriver属性检测...', 'info');

            // 标准WebDriver检测
            const hasWebDriver = navigator.webdriver === true;

            // 额外检查：某些自动化浏览器会隐藏webdriver属性，但仍有其他痕迹
            let extraChecks = false;

            // 检查是否可以通过其他方式检测到自动化
            try {
                // 尝试检测通过CDP（Chrome DevTools Protocol）控制的浏览器
                if (window.domAutomation || window.domAutomationController) {
                    extraChecks = true;
                    addLog('检测到domAutomation或domAutomationController', 'warn');
                }

                // 检查是否有被覆盖的属性
                try {
                    const originalGetter = Object.getOwnPropertyDescriptor(navigator, 'webdriver')?.get;
                    if (originalGetter) {
                        const getterStr = Function.prototype.toString.call(originalGetter);
                        if (getterStr.includes('webdriver')) {
                            extraChecks = true;
                            addLog('检测到被覆盖的webdriver属性', 'warn');
                        }
                    }
                } catch (e) {
                    // 忽略错误
                }
            } catch(e) {
                // 忽略错误
            }

            detectionResults.webdriver = hasWebDriver || extraChecks;

            if (detectionResults.webdriver) {
                webdriverCheck.classList.add('detected');
                webdriverCheck.classList.remove('clean');
                webdriverStatus.textContent = '检测到自动化特征';
                webdriverStatus.className = 'status detected';
                addLog('WebDriver检测: 检测到自动化特征', 'warn');
            } else {
                webdriverCheck.classList.add('clean');
                webdriverCheck.classList.remove('detected');
                webdriverStatus.textContent = '未检测到WebDriver';
                webdriverStatus.className = 'status clean';
                addLog('WebDriver检测: 未检测到自动化特征', 'success');
            }

            updateDetectionProgress();
        }

        /**
         * 2. 插件检测
         */
        function checkPlugins() {
            const pluginsCheck = document.getElementById('pluginsCheck');
            const pluginsStatus = document.getElementById('pluginsStatus');

            addLog('开始插件列表检测...', 'info');

            const plugins = navigator.plugins;
            let isSuspicious = false;

            // 检查插件列表是否异常
            if (!plugins || plugins.length === 0) {
                // 无插件可能是自动化浏览器
                isSuspicious = true;
                addLog('插件列表为空，可能是自动化浏览器', 'warn');
            } else {
                // 检查是否有常见的自动化相关插件
                const pluginNames = Array.from(plugins).map(p => p.name.toLowerCase());

                // 自动化浏览器可能包含特定插件或缺少常见插件
                const commonPlugins = ['chrome pdf viewer', 'native client', 'widevine content decryption module'];
                const hasCommonPlugins = commonPlugins.some(plugin => 
                    pluginNames.some(name => name.includes(plugin))
                );

                // 如果缺少常见插件，可能是自动化浏览器
                if (!hasCommonPlugins && plugins.length < 3) {
                    isSuspicious = true;
                    addLog(`缺少常见插件，插件数量: ${plugins.length}`, 'warn');
                }

                // 检查是否有自动化相关插件名称
                const automationKeywords = ['webdriver', 'selenium', 'puppeteer', 'automation'];
                const hasAutomationPlugins = automationKeywords.some(keyword => 
                    pluginNames.some(name => name.includes(keyword))
                );

                if (hasAutomationPlugins) {
                    isSuspicious = true;
                    addLog(`检测到自动化相关插件: ${pluginNames.join(', ')}`, 'warn');
                } else {
                    addLog(`插件列表: ${pluginNames.join(', ')}`, 'info');
                }
            }

            detectionResults.plugins = isSuspicious;

            if (detectionResults.plugins) {
                pluginsCheck.classList.add('detected');
                pluginsCheck.classList.remove('clean');
                pluginsStatus.textContent = '插件列表异常';
                pluginsStatus.className = 'status detected';
                addLog('插件检测: 检测到异常', 'warn');
            } else {
                pluginsCheck.classList.add('clean');
                pluginsCheck.classList.remove('detected');
                pluginsStatus.textContent = '插件列表正常';
                pluginsStatus.className = 'status clean';
                addLog('插件检测: 正常', 'success');
            }

            updateDetectionProgress();
        }

        /**
         * 3. 语言检测
         */
        function checkLanguages() {
            const languagesCheck = document.getElementById('languagesCheck');
            const languagesStatus = document.getElementById('languagesStatus');

            addLog('开始语言设置检测...', 'info');

            let languages;
            try {
                languages = navigator.languages || [navigator.language || navigator.userLanguage || navigator.browserLanguage];
            } catch (e) {
                addLog('无法获取语言设置: ' + e.message, 'error');
                languages = [];
            }

            let isSuspicious = false;

            // 检查语言设置是否异常
            if (!languages || languages.length === 0) {
                isSuspicious = true;
                addLog('语言设置为空', 'warn');
            } else {
                // 自动化浏览器有时有非标准的语言设置
                // 例如，只有单一语言或语言顺序异常
                if (languages.length === 1) {
                    addLog(`只有单一语言设置: ${languages[0]}`, 'info');
                    if (languages[0] === 'en-US') {
                        // 只有美式英语可能是默认的自动化设置
                        isSuspicious = true;
                        addLog('语言设置只有en-US，可能是自动化默认设置', 'warn');
                    }
                }

                // 检查是否有空字符串或无效语言代码
                if (languages.some(lang => !lang || lang.trim() === '')) {
                    isSuspicious = true;
                    addLog('检测到空或无效语言代码', 'warn');
                }

                addLog(`语言设置: ${languages.join(', ')}`, 'info');
            }

            detectionResults.languages = isSuspicious;

            if (detectionResults.languages) {
                languagesCheck.classList.add('detected');
                languagesCheck.classList.remove('clean');
                languagesStatus.textContent = '语言设置异常';
                languagesStatus.className = 'status detected';
                addLog('语言检测: 检测到异常', 'warn');
            } else {
