        /**
         * 4. 窗口属性检测
         */
        function checkWindowProperties() {
            const windowCheck = document.getElementById('windowCheck');
            const windowStatus = document.getElementById('windowStatus');

            addLog('开始窗口属性检测...', 'info');

            let isSuspicious = false;
            const automationProperties = [
                '_Selenium_IDE_Recorder',
                'callPhantom',
                '__webdriver_script_fn',
                '__driver_evaluate',
                '__webdriver_evaluate',
                '__selenium_evaluate',
                '__fxdriver_evaluate',
                '__driver_unwrapped',
                '__webdriver_unwrapped',
                '__selenium_unwrapped',
                '__fxdriver_unwrapped',
                '_phantom',
                'callSelenium',
                '_selenium',
                'calledSelenium',
                'webdriver',
                'domAutomation',
                'domAutomationController'
            ];

            // 检查是否存在任何自动化属性
            for (const prop of automationProperties) {
                try {
                    if (prop in window) {
                        isSuspicious = true;
                        addLog(`检测到自动化属性: ${prop}`, 'warn');
                        break;
                    }
                } catch (e) {
                    // 忽略检查单个属性时的错误
                }
            }

            detectionResults.windowProps = isSuspicious;

            if (detectionResults.windowProps) {
                windowCheck.classList.add('detected');
                windowCheck.classList.remove('clean');
                windowStatus.textContent = '发现自动化属性';
                windowStatus.className = 'status detected';
                addLog('窗口属性检测: 检测到自动化属性', 'warn');
            } else {
                windowCheck.classList.add('clean');
                windowCheck.classList.remove('detected');
                windowStatus.textContent = '未发现自动化属性';
                windowStatus.className = 'status clean';
                addLog('窗口属性检测: 未发现自动化属性', 'success');
            }

            updateDetectionProgress();
        }

        /**
         * 5. 权限检测
         */
        async function checkPermissions() {
            const permissionsCheck = document.getElementById('permissionsCheck');
            const permissionsStatus = document.getElementById('permissionsStatus');

            addLog('开始权限检测...', 'info');

            let isSuspicious = false;

            // 检查Notification权限状态
            if ('permissions' in navigator && 'query' in navigator.permissions) {
                try {
                    const permissionStatus = await navigator.permissions.query({name: 'notifications'});
                    addLog(`Notification权限状态: ${permissionStatus.state}`, 'info');
                } catch(e) {
                    // 如果查询失败，可能是自动化浏览器
                    isSuspicious = true;
                    addLog('权限查询失败，可能是自动化浏览器', 'warn');
                }
            } else {
                addLog('浏览器不支持Permissions API', 'info');
            }

            // 检查是否存在自动化扩展特征
            if (window.chrome && chrome.runtime) {
                try {
                    // 某些自动化工具会加载特定扩展
                    const manifest = chrome.runtime.getManifest && chrome.runtime.getManifest();
                    if (manifest && manifest.name) {
                        const name = manifest.name.toLowerCase();
                        if (name.includes('webdriver') || name.includes('automation') || name.includes('selenium')) {
                            isSuspicious = true;
                            addLog(`检测到自动化扩展: ${manifest.name}`, 'warn');
                        } else {
                            addLog(`Chrome扩展名称: ${manifest.name}`, 'info');
                        }
                    }
                } catch(e) {
                    // 忽略错误
                }
            }

            detectionResults.permissions = isSuspicious;

            if (detectionResults.permissions) {
                permissionsCheck.classList.add('detected');
                permissionsCheck.classList.remove('clean');
                permissionsStatus.textContent = '权限配置异常';
                permissionsStatus.className = 'status detected';
                addLog('权限检测: 检测到异常', 'warn');
            } else {
                permissionsCheck.classList.add('clean');
                permissionsCheck.classList.remove('detected');
                permissionsStatus.textContent = '权限配置正常';
                permissionsStatus.className = 'status clean';
                addLog('权限检测: 正常', 'success');
            }

            updateDetectionProgress();
        }

