                '检测到CDP连接痕迹', '未检测到CDP痕迹');
            updateDetectionProgress();

            // DOM补丁检测
            detectionResults.automationPatch = detector.detectPatchedDOM();
            updateDetectionUI('domPatchCheck', 'domPatchStatus', detectionResults.automationPatch,
                '检测到被修改的DOM API', 'DOM API正常');
            updateDetectionProgress();

            // iframe检测
            detectionResults.iframeDetection = await detector.detectIframeSandbox();
            updateDetectionUI('iframeCheck', 'iframeStatus', detectionResults.iframeDetection,
                '检测到iframe沙箱异常', 'iframe沙箱正常');
            updateDetectionProgress();

            // WebGL检测
            detectionResults.webglVendor = detector.detectWebGLVendor();
            updateDetectionUI('webglCheck', 'webglStatus', detectionResults.webglVendor,
                '检测到虚拟GPU', 'WebGL供应商正常');
            updateDetectionProgress();

            // 性能指标检测
            detectionResults.performanceMetrics = detector.detectPerformanceMetrics();
            updateDetectionUI('performanceCheck', 'performanceStatus', detectionResults.performanceMetrics,
                '检测到异常性能指标', '性能指标正常');
            updateDetectionProgress();

            // AudioContext检测
            detectionResults.audioContext = detector.detectAudioContext();
            updateDetectionUI('audioContextCheck', 'audioContextStatus', detectionResults.audioContext,
                '检测到AudioContext异常', 'AudioContext正常');
            updateDetectionProgress();

            // Chrome运行时检测
            detectionResults.chromeRuntime = detector.detectChromeRuntime();
            updateDetectionUI('chromeRuntimeCheck', 'chromeRuntimeStatus', detectionResults.chromeRuntime,
                '检测到Chrome运行时异常', 'Chrome运行时正常');
            updateDetectionProgress();
        }

        /**
         * 更新总体结果
         */
        function updateOverallResult() {
            const overallResult = document.getElementById('overallResult');
            const resultExplanation = document.getElementById('resultExplanation');

            // 计算检测到的可疑项目数
            const detectedCount = Object.values(detectionResults).filter(result => result === true).length;
            const totalTests = Object.keys(detectionResults).length;

            // 根据检测数量确定置信度和结果
            let confidence = '低';
            let riskLevel = '低风险';
            let isLikelyAutomated = false;

            if (detectedCount >= 5) {
                confidence = '非常高';
                riskLevel = '极高风险';
                isLikelyAutomated = true;
            } else if (detectedCount >= 3) {
                confidence = '高';
                riskLevel = '高风险';
                isLikelyAutomated = true;
            } else if (detectedCount >= 1) {
                confidence = '中';
                riskLevel = '中风险';
                isLikelyAutomated = true;
            } else {
                confidence = '低';
                riskLevel = '低风险';
                isLikelyAutomated = false;
            }

            if (isLikelyAutomated) {
                overallResult.textContent = `检测到自动化浏览器 (${riskLevel})`;
                overallResult.className = 'result-text detected';
                resultExplanation.innerHTML = `
                    在 <span class="highlight">${totalTests}</span> 项检测中，有 <span class="highlight">${detectedCount}</span> 项显示自动化特征。
                    <br>检测置信度：<span class="highlight">${confidence}</span>
                    <br>您的浏览器可能被Selenium、Puppeteer等自动化工具控制。
                `;
                addLog(`最终结果: 检测到自动化浏览器 (${detectedCount}/${totalTests} 项异常)`, 'error');
            } else {
                overallResult.textContent = '正常人类浏览器';
                overallResult.className = 'result-text clean';
                resultExplanation.innerHTML = `
                    在 <span class="highlight">${totalTests}</span> 项检测中，未发现自动化特征。
                    <br>检测置信度：<span class="highlight">${confidence}</span>
                    <br>您的浏览器看起来像正常的人类操作浏览器。
                `;
                addLog(`最终结果: 正常人类浏览器 (${detectedCount}/${totalTests} 项异常)`, 'success');
            }
        }

        /**
         * 初始化所有检测
         */
        async function runAllDetections() {
            if (detectionInProgress) {
                addLog('检测正在进行中，请等待完成', 'warn');
                return;
            }

            detectionInProgress = true;
            addLog('开始执行所有检测...', 'info');

            // 重置状态
            for (let key in detectionResults) {
                detectionResults[key] = false;
            }
            completedDetections = 0;

            // 运行基础检测
            checkWebDriver();
            checkPlugins();
            checkLanguages();
            checkWindowProperties();
            await checkPermissions();

            // 运行高级检测
            await runAdvancedDetections();

            // 设置行为检测
            setupMouseDetection();
            setupHumanTest();
        }

        /**
         * 重置所有检测
         */
        function resetAllDetections() {
            // 重置检测状态
            for (let key in detectionResults) {
                detectionResults[key] = false;
            }

            humanTestClickCount = 0;
            humanTestStartTime = null;
            humanTestLastClickTime = null;
            mouseEvents = [];
            mouseEventCount = 0;
            completedDetections = 0;
            detectionInProgress = false;

            // 清除结果文本
            document.getElementById('humanTestResult').textContent = '';
            document.getElementById('clickCounter').textContent = '点击次数: 0';
            document.getElementById('mouseEventCount').textContent = '已记录鼠标事件: 0';
            document.getElementById('detectionCounter').textContent = '检测进度: 0/17';
            document.getElementById('confidenceFill').style.width = '0%';
            document.getElementById('overallResult').textContent = '等待检测...';
            document.getElementById('overallResult').className = 'result-text';
            document.getElementById('resultExplanation').textContent = '点击"开始检测"按钮开始分析浏览器特征';

            // 重置所有检测项的显示状态
            const detectionItems = document.querySelectorAll('.detection-item');
            detectionItems.forEach(item => {
                item.classList.remove('detected', 'clean');
                const statusElement = item.querySelector('.status');
                if (statusElement) {
                    statusElement.textContent = '等待检测...';
                    statusElement.className = 'status';
                }
            });

            addLog('检测已重置', 'info');
        }

        /**
         * 导出日志
         */
        function exportLog() {
            let logText = "Selenium检测工具 - 检测日志\n";
            logText += "生成时间: " + new Date().toLocaleString() + "\n";
            logText += "用户代理: " + navigator.userAgent + "\n";
            logText += "=".repeat(50) + "\n\n";

            logEntries.forEach(entry => {
                logText += `[${entry.time}] ${entry.message}\n`;
            });

            // 添加检测结果摘要
            logText += "\n" + "=".repeat(50) + "\n";
            logText += "检测结果摘要:\n";

            const detectedCount = Object.values(detectionResults).filter(result => result === true).length;
            const totalTests = Object.keys(detectionResults).length;

            logText += `检测项目总数: ${totalTests}\n`;
            logText += `异常项目数: ${detectedCount}\n`;
            logText += `检测完成率: ${completedDetections}/${totalTests}\n`;

            // 详细结果
            logText += "\n详细结果:\n";
            for (const [key, value] of Object.entries(detectionResults)) {
                logText += `  ${key}: ${value ? '异常' : '正常'}\n`;
            }

            // 创建下载链接
            const blob = new Blob([logText], { type: 'text/plain' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `selenium-detection-log-${new Date().toISOString().slice(0, 10)}.txt`;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);

            addLog('日志已导出', 'success');
        }

        /**
         * 清除日志
         */
        function clearLog() {
            logEntries = [];
            document.getElementById('logContent').innerHTML = '';
            document.getElementById('logCount').textContent = '日志: 0';
            addLog('日志已清除', 'info');
        }

