console.log(navigator.webdriver);  // 可能输出: false 或 true
console.log(Object.getOwnPropertyDescriptor(navigator, 'webdriver'));
// 可能输出: {value: false, writable: false, enumerable: true, configurable: false}

// 注意：你是检查 __proto__，而不是 navigator 本身
console.log(Object.getOwnPropertyDescriptor(navigator.__proto__, 'webdriver'));
// 如果在原型链上定义了，就不是 undefined
```

## 3. **可能的原因**

### 原因A：原型链继承
```javascript
