## 2. 创建新的 RequestPatternDetector 类

在 JavaScript 中添加一个新类来专门处理请求检测：

```javascript
// ============================================================================
// HTTP请求模式检测器
// ============================================================================

class RequestPatternDetector {

    constructor() {
        this.requests = [];
        this.startTime = Date.now();
        this.requestCount = 0;
        this.xhrOriginalOpen = null;
        this.xhrOriginalSend = null;
        this.fetchOriginal = null;
        this.isMonitoring = false;

        // 常见爬虫/自动化工具的用户代理标识
        this.automationUserAgents = [
            'selenium', 'webdriver', 'puppeteer', 'playwright', 'chromedriver',
            'geckodriver', 'phantomjs', 'headlesschrome', 'headlessfirefox',
            'bot', 'crawler', 'spider', 'scraper', 'automation'
        ];

        // 常见爬虫/自动化工具的头部特征
        this.automationHeaders = [
            'webdriver', 'selenium', 'phantomjs', 'puppeteer', 'playwright',
            'automation', 'headless', '--disable-web-security'
        ];
    }

    /**
     * 开始监控网络请求
     */
    startMonitoring() {
        if (this.isMonitoring) return;

        addLog('开始监控HTTP请求模式...', 'info');
        this.isMonitoring = true;

        // 监控 XMLHttpRequest
        this.interceptXMLHttpRequest();

        // 监控 Fetch API
        this.interceptFetch();

        // 监控资源加载
        this.setupResourceObserver();

        addLog('HTTP请求监控已启动', 'success');
    }

    /**
     * 拦截 XMLHttpRequest
     */
    interceptXMLHttpRequest() {
        const self = this;

        // 保存原始方法
        this.xhrOriginalOpen = XMLHttpRequest.prototype.open;
        this.xhrOriginalSend = XMLHttpRequest.prototype.send;

        // 重写 open 方法
        XMLHttpRequest.prototype.open = function(method, url, async = true, user, password) {
            // 存储请求信息
            this._requestInfo = {
                method: method,
                url: url,
                startTime: Date.now(),
                headers: {}
            };

            // 继续原始调用
            return self.xhrOriginalOpen.apply(this, arguments);
        };

        // 重写 send 方法
        XMLHttpRequest.prototype.send = function(body) {
            const requestInfo = this._requestInfo;
            if (requestInfo) {
                requestInfo.body = body;
                requestInfo.contentType = this.getRequestHeader('Content-Type');
                requestInfo.userAgent = navigator.userAgent;

                // 监听请求完成
                this.addEventListener('load', function() {
                    const endTime = Date.now();
                    const duration = endTime - requestInfo.startTime;

                    const requestData = {
                        type: 'xhr',
                        method: requestInfo.method,
                        url: requestInfo.url,
                        startTime: requestInfo.startTime,
                        duration: duration,
                        status: this.status,
                        responseSize: this.responseText ? this.responseText.length : 0,
                        userAgent: requestInfo.userAgent,
                        contentType: requestInfo.contentType,
                        timestamp: endTime
                    };

                    self.recordRequest(requestData);
                });

                // 监听请求错误
                this.addEventListener('error', function() {
                    const endTime = Date.now();
                    const requestData = {
                        type: 'xhr',
                        method: requestInfo.method,
                        url: requestInfo.url,
                        startTime: requestInfo.startTime,
                        duration: endTime - requestInfo.startTime,
                        status: 0, // 网络错误
                        error: true,
                        timestamp: endTime
                    };

                    self.recordRequest(requestData);
                });
            }

            return self.xhrOriginalSend.apply(this, arguments);
        };

        // 拦截 setRequestHeader 以捕获请求头
        const originalSetRequestHeader = XMLHttpRequest.prototype.setRequestHeader;
        XMLHttpRequest.prototype.setRequestHeader = function(header, value) {
            if (this._requestInfo) {
                this._requestInfo.headers[header.toLowerCase()] = value;
            }
            return originalSetRequestHeader.apply(this, arguments);
        };

        // 辅助方法：获取请求头
        XMLHttpRequest.prototype.getRequestHeader = function(header) {
            return this._requestInfo ? this._requestInfo.headers[header.toLowerCase()] : null;
        };
    }

    /**
     * 拦截 Fetch API
     */
    interceptFetch() {
        const self = this;
        this.fetchOriginal = window.fetch;

        window.fetch = function(input, init) {
            const startTime = Date.now();
            const url = typeof input === 'string' ? input : input.url;
            const method = (init && init.method) || 'GET';
            const headers = (init && init.headers) || {};

            // 提取用户代理
            let userAgent = navigator.userAgent;
            if (headers instanceof Headers) {
                userAgent = headers.get('User-Agent') || navigator.userAgent;
            } else if (headers && headers['User-Agent']) {
                userAgent = headers['User-Agent'];
            }

            // 调用原始 fetch
            return self.fetchOriginal.apply(this, arguments).then(response => {
                const endTime = Date.now();
                const duration = endTime - startTime;

                // 克隆响应以便读取内容长度
                const clonedResponse = response.clone();

                clonedResponse.text().then(text => {
                    const requestData = {
                        type: 'fetch',
                        method: method,
                        url: url,
                        startTime: startTime,
                        duration: duration,
                        status: response.status,
                        responseSize: text.length,
                        userAgent: userAgent,
                        contentType: response.headers.get('Content-Type'),
                        timestamp: endTime
                    };

                    self.recordRequest(requestData);
                }).catch(() => {
                    // 如果无法读取响应文本，至少记录基本信息
                    const requestData = {
                        type: 'fetch',
                        method: method,
                        url: url,
                        startTime: startTime,
                        duration: duration,
                        status: response.status,
                        responseSize: 0,
                        userAgent: userAgent,
                        timestamp: endTime
                    };

                    self.recordRequest(requestData);
                });

                return response;
            }).catch(error => {
                const endTime = Date.now();
                const requestData = {
                    type: 'fetch',
                    method: method,
                    url: url,
                    startTime: startTime,
                    duration: endTime - startTime,
                    status: 0,
                    error: true,
                    errorMessage: error.message,
                    userAgent: userAgent,
                    timestamp: endTime
                };

                self.recordRequest(requestData);
                throw error;
            });
        };
    }

    /**
     * 设置资源加载观察器
     */
    setupResourceObserver() {
        // 使用 Performance API 获取已加载的资源
        if (window.performance && window.performance.getEntriesByType) {
            setTimeout(() => {
                const resources = performance.getEntriesByType('resource');
                resources.forEach(resource => {
                    const requestData = {
                        type: 'resource',
                        method: 'GET',
                        url: resource.name,
                        startTime: resource.startTime,
                        duration: resource.duration,
                        responseSize: resource.transferSize || 0,
                        contentType: resource.initiatorType,
                        timestamp: resource.startTime + resource.duration
                    };

                    this.recordRequest(requestData);
                });

                addLog(`通过Performance API捕获了 ${resources.length} 个资源请求`, 'info');
            }, 1000); // 延迟以确保资源已加载
        }

        // 监听后续的资源加载
        if (window.PerformanceObserver) {
            try {
                const observer = new PerformanceObserver((list) => {
                    list.getEntries().forEach(resource => {
                        const requestData = {
                            type: 'resource',
                            method: 'GET',
                            url: resource.name,
                            startTime: resource.startTime,
                            duration: resource.duration,
                            responseSize: resource.transferSize || 0,
                            contentType: resource.initiatorType,
                            timestamp: resource.startTime + resource.duration
                        };

                        this.recordRequest(requestData);
                    });
                });

                observer.observe({ entryTypes: ['resource'] });
            } catch (e) {
                addLog(`无法设置PerformanceObserver: ${e.message}`, 'warn');
            }
        }
    }

    /**
     * 记录请求
     */
    recordRequest(requestData) {
        this.requests.push(requestData);
        this.requestCount++;

        // 更新UI显示
        document.getElementById('requestCount').textContent = `已分析请求: ${this.requestCount}`;

        // 每收集10个请求进行一次分析
        if (this.requestCount % 10 === 0) {
            this.analyzeRequestPatterns();
        }
    }

    /**
     * 分析请求模式
     */
    analyzeRequestPatterns() {
        if (this.requests.length < 5) {
            addLog('请求数据不足，继续收集...', 'info');
            return;
        }

        addLog(`分析 ${this.requests.length} 个请求的模式...`, 'info');

        let detectionScore = 0;
        const warnings = [];

        // 1. 检查User-Agent是否包含自动化工具标识
        const userAgentCheck = this.checkUserAgents();
        if (userAgentCheck.detected) {
            detectionScore += 2;
            warnings.push(userAgentCheck.message);
        }

        // 2. 分析请求时间间隔的规律性
        const intervalCheck = this.checkRequestIntervals();
        if (intervalCheck.detected) {
            detectionScore += 1.5;
            warnings.push(intervalCheck.message);
        }

        // 3. 检查请求并发模式
        const concurrencyCheck = this.checkRequestConcurrency();
        if (concurrencyCheck.detected) {
            detectionScore += 1;
            warnings.push(concurrencyCheck.message);
        }

        // 4. 检查请求时间分布（自动化工具通常在特定时间点密集请求）
        const timingCheck = this.checkRequestTiming();
        if (timingCheck.detected) {
            detectionScore += 1;
            warnings.push(timingCheck.message);
        }

        // 5. 检查是否有异常请求模式（如大量相同请求）
        const patternCheck = this.checkAbnormalPatterns();
        if (patternCheck.detected) {
            detectionScore += 1.5;
            warnings.push(patternCheck.message);
        }

        // 6. 检查HTTP头中的自动化特征
        const headerCheck = this.checkRequestHeaders();
        if (headerCheck.detected) {
            detectionScore += 2;
            warnings.push(headerCheck.message);
        }

        // 根据得分判断是否为自动化
        const isAutomated = detectionScore >= 3;

        // 更新结果
        detectionResults.requestPatterns = isAutomated;

        const requestPatternCheck = document.getElementById('requestPatternCheck');
        const requestPatternStatus = document.getElementById('requestPatternStatus');

        if (isAutomated) {
            requestPatternCheck.classList.add('detected');
            requestPatternCheck.classList.remove('clean');
            requestPatternStatus.textContent = `检测到自动化请求模式 (得分: ${detectionScore.toFixed(1)})`;
            requestPatternStatus.className = 'status detected';

            // 汇总警告信息
            const warningSummary = warnings.join('; ');
            addLog(`HTTP请求检测: ${warningSummary}`, 'warn');
        } else {
            requestPatternCheck.classList.add('clean');
            requestPatternCheck.classList.remove('detected');
            requestPatternStatus.textContent = `请求模式正常 (得分: ${detectionScore.toFixed(1)})`;
            requestPatternStatus.className = 'status clean';
            addLog(`HTTP请求检测: 正常模式 (得分: ${detectionScore.toFixed(1)})`, 'success');
        }

        // 更新检测进度
        updateDetectionProgress();

        return isAutomated;
    }

    /**
     * 检查User-Agent
     */
    checkUserAgents() {
        const uniqueUserAgents = [...new Set(this.requests.map(r => r.userAgent))];

        for (const userAgent of uniqueUserAgents) {
            if (!userAgent) continue;

            const lowerUserAgent = userAgent.toLowerCase();

            for (const keyword of this.automationUserAgents) {
                if (lowerUserAgent.includes(keyword)) {
                    return {
                        detected: true,
                        message: `User-Agent包含自动化关键词: ${keyword}`
                    };
                }
            }

            // 检查User-Agent是否异常简短（自动化工具可能使用简化UA）
            if (userAgent.length < 30) {
                return {
                    detected: true,
                    message: `User-Agent异常简短: ${userAgent}`
                };
            }

            // 检查User-Agent格式（自动化工具可能缺少某些部分）
            const hasBrowserInfo = 
                lowerUserAgent.includes('mozilla/') &&
                (lowerUserAgent.includes('chrome/') || 
                 lowerUserAgent.includes('safari/') || 
                 lowerUserAgent.includes('firefox/'));

            if (!hasBrowserInfo) {
                return {
                    detected: true,
                    message: `User-Agent格式异常: ${userAgent}`
                };
            }
        }

        return {
            detected: false,
            message: 'User-Agent正常'
        };
    }

    /**
     * 检查请求时间间隔
     */
    checkRequestIntervals() {
        if (this.requests.length < 3) {
            return { detected: false, message: '数据不足' };
        }

        // 按时间排序
        const sortedRequests = [...this.requests].sort((a, b) => a.timestamp - b.timestamp);

        // 计算请求间隔
        const intervals = [];
        for (let i = 1; i < sortedRequests.length; i++) {
            const interval = sortedRequests[i].timestamp - sortedRequests[i-1].timestamp;
            intervals.push(interval);
        }

        // 计算间隔的方差
        const mean = intervals.reduce((a, b) => a + b) / intervals.length;
        const variance = intervals.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / intervals.length;
        const stdDev = Math.sqrt(variance);

        // 更新UI显示
        document.getElementById('networkStats').textContent = 
            `请求间隔方差: ${variance.toFixed(2)} (标准差: ${stdDev.toFixed(2)}ms)`;

        // 自动化工具通常有非常规律的请求间隔（方差小）
        if (variance < 1000 && intervals.length > 5) {
            return {
                detected: true,
                message: `请求间隔过于规律 (方差: ${variance.toFixed(2)})`
            };
        }

        // 检查是否有极短的间隔（可能表示并发请求）
        const veryShortIntervals = intervals.filter(i => i < 10).length;
        if (veryShortIntervals > intervals.length * 0.3) {
            return {
                detected: true,
                message: `检测到大量并发请求 (${veryShortIntervals}/${intervals.length} 间隔<10ms)`
            };
        }

        return {
            detected: false,
            message: `请求间隔正常 (方差: ${variance.toFixed(2)})`
        };
    }

    /**
     * 检查请求并发模式
     */
    checkRequestConcurrency() {
        if (this.requests.length < 10) {
            return { detected: false, message: '数据不足' };
        }

        // 按时间窗口统计并发请求
        const timeWindows = [];
        const windowSize = 100; // 100ms窗口

        for (let i = 0; i < this.requests.length; i++) {
            const request = this.requests[i];
            const windowStart = Math.floor(request.timestamp / windowSize);

            if (!timeWindows[windowStart]) {
                timeWindows[windowStart] = 0;
            }
            timeWindows[windowStart]++;
        }

        // 查找最大并发数
        const maxConcurrent = Math.max(...timeWindows.filter(Boolean));

        // 自动化工具可能同时发起大量请求
        if (maxConcurrent > 5) {
            return {
                detected: true,
                message: `检测到高并发请求 (最大并发: ${maxConcurrent})`
            };
        }

        return {
            detected: false,
            message: `并发请求正常 (最大并发: ${maxConcurrent})`
        };
    }

    /**
     * 检查请求时间分布
     */
    checkRequestTiming() {
        if (this.requests.length < 20) {
            return { detected: false, message: '数据不足' };
        }

        // 分析请求的时间分布模式
        // 人类用户通常有随机的时间间隔，而自动化工具可能有固定的模式

        // 将时间转换为毫秒时间戳
        const timestamps = this.requests.map(r => r.timestamp);

        // 计算请求密度（每秒钟的请求数）
        const startTime = Math.min(...timestamps);
        const endTime = Math.max(...timestamps);
        const duration = endTime - startTime;

        if (duration < 1000) return { detected: false, message: '时间窗口太短' };

        const requestsPerSecond = this.requests.length / (duration / 1000);

        // 自动化工具通常有稳定的请求速率
        if (requestsPerSecond > 2 && requestsPerSecond < 10) {
            // 进一步分析速率稳定性
            const secondWindows = Math.floor(duration / 1000);
            const requestsPerWindow = new Array(secondWindows).fill(0);

            timestamps.forEach(timestamp => {
                const windowIndex = Math.floor((timestamp - startTime) / 1000);
                if (windowIndex >= 0 && windowIndex < secondWindows) {
                    requestsPerWindow[windowIndex]++;
                }
            });

            // 计算请求数的方差
            const mean = requestsPerSecond;
            const variance = requestsPerWindow.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / secondWindows;

            if (variance < 0.5) {
                return {
                    detected: true,
                    message: `请求速率过于稳定 (方差: ${variance.toFixed(2)})`
                };
            }
        }

        return {
            detected: false,
            message: `请求时间分布正常 (${requestsPerSecond.toFixed(2)} 请求/秒)`
        };
    }

    /**
     * 检查异常请求模式
     */
    checkAbnormalPatterns() {
        if (this.requests.length < 10) {
            return { detected: false, message: '数据不足' };
        }

        // 1. 检查重复请求
        const urlCounts = {};
        this.requests.forEach(request => {
            const url = request.url.split('?')[0]; // 忽略查询参数
            urlCounts[url] = (urlCounts[url] || 0) + 1;
        });

        // 查找重复率高的URL
        for (const [url, count] of Object.entries(urlCounts)) {
            if (count > 5 && count > this.requests.length * 0.3) {
                return {
                    detected: true,
                    message: `检测到重复请求模式: ${url} (${count}次)`
                };
            }
        }

        // 2. 检查请求顺序（自动化工具可能按固定顺序请求）
        const recentRequests = this.requests.slice(-20);
        if (recentRequests.length >= 10) {
            // 简单检查：如果最近10个请求中有5个完全相同，可能是自动化
            const urlSequence = recentRequests.map(r => r.url).join('|');
            const patternMatches = [];

            for (let i = 5; i <= 8; i++) {
                const testPattern = urlSequence.slice(0, i * 20); // 近似匹配
                const occurrences = urlSequence.split(testPattern).length - 1;
                if (occurrences > 1) {
                    patternMatches.push(`检测到重复模式 (长度: ${i})`);
                }
            }

            if (patternMatches.length > 0) {
                return {
                    detected: true,
                    message: patternMatches[0]
                };
            }
        }

        return {
            detected: false,
            message: '请求模式正常'
        };
    }

    /**
     * 检查请求头中的自动化特征
     */
    checkRequestHeaders() {
        // 注意：由于浏览器安全限制，我们无法直接读取所有请求头
        // 只能读取我们通过拦截器捕获的头信息

        // 这里可以添加对已知自动化工具特定头的检查
        // 例如：某些自动化工具会在请求头中添加特定标识

        return {
            detected: false,
            message: '未发现异常请求头'
        };
    }

    /**
     * 停止监控
     */
    stopMonitoring() {
        if (!this.isMonitoring) return;

        // 恢复原始 XMLHttpRequest 方法
        if (this.xhrOriginalOpen) {
            XMLHttpRequest.prototype.open = this.xhrOriginalOpen;
        }
        if (this.xhrOriginalSend) {
            XMLHttpRequest.prototype.send = this.xhrOriginalSend;
        }

        // 恢复原始 Fetch API
        if (this.fetchOriginal) {
            window.fetch = this.fetchOriginal;
        }

        this.isMonitoring = false;
        addLog('HTTP请求监控已停止', 'info');
    }

    /**
     * 获取检测报告
     */
    getReport() {
        return {
            totalRequests: this.requests.length,
            requestTypes: this.countByType(),
            timeSpan: this.getTimeSpan(),
            averageInterval: this.getAverageInterval(),
            maxConcurrent: this.getMaxConcurrent()
        };
    }

    countByType() {
        const counts = {};
        this.requests.forEach(request => {
            counts[request.type] = (counts[request.type] || 0) + 1;
        });
        return counts;
    }

    getTimeSpan() {
        if (this.requests.length === 0) return 0;
        const timestamps = this.requests.map(r => r.timestamp);
        return Math.max(...timestamps) - Math.min(...timestamps);
    }

    getAverageInterval() {
        if (this.requests.length < 2) return 0;

        const sortedRequests = [...this.requests].sort((a, b) => a.timestamp - b.timestamp);
        let totalInterval = 0;
        let intervalCount = 0;

        for (let i = 1; i < sortedRequests.length; i++) {
            totalInterval += sortedRequests[i].timestamp - sortedRequests[i-1].timestamp;
            intervalCount++;
        }

        return totalInterval / intervalCount;
    }

    getMaxConcurrent() {
        if (this.requests.length === 0) return 0;

        const events = [];
        this.requests.forEach(request => {
            events.push({ time: request.timestamp, type: 'start' });
            events.push({ time: request.timestamp + (request.duration || 0), type: 'end' });
        });

        events.sort((a, b) => a.time - b.time);

        let concurrent = 0;
        let maxConcurrent = 0;

        events.forEach(event => {
            if (event.type === 'start') {
                concurrent++;
                maxConcurrent = Math.max(maxConcurrent, concurrent);
            } else {
                concurrent--;
            }
        });

        return maxConcurrent;
    }
}
```

