## 4. 在行为检测中初始化请求检测器

```javascript
// 在全局变量部分添加
let requestDetector = null;

// 修改 setupHumanTest 函数，添加请求检测初始化
function setupHumanTest() {
    // ... 原有的代码 ...

    // 初始化请求检测器
    requestDetector = new RequestPatternDetector();
    requestDetector.startMonitoring();

    // 延迟一段时间后开始分析
    setTimeout(() => {
        const requestResult = requestDetector.analyzeRequestPatterns();
        detectionResults.requestPatterns = requestResult;

        // 网络行为检测
        const networkResult = analyzeNetworkBehavior();
        detectionResults.networkBehavior = networkResult;

        updateDetectionUI('networkBehaviorCheck', 'networkBehaviorStatus', 
                         networkResult, '检测到异常网络行为', '网络行为正常');
        updateDetectionProgress();
    }, 5000); // 5秒后开始分析
}

// 添加网络行为分析函数
function analyzeNetworkBehavior() {
    if (!requestDetector || requestDetector.requests.length < 10) {
        return false;
    }

    const report = requestDetector.getReport();

    // 判断是否为自动化网络行为
    let suspicionScore = 0;

    // 1. 检查请求类型分布
    const typeCounts = report.requestTypes;
    const totalRequests = report.totalRequests;

    // 自动化工具可能大量使用XHR/Fetch
    const apiRequestRatio = ((typeCounts.xhr || 0) + (typeCounts.fetch || 0)) / totalRequests;
    if (apiRequestRatio > 0.8) {
        suspicionScore += 1;
        addLog(`API请求比例过高: ${(apiRequestRatio * 100).toFixed(1)}%`, 'warn');
    }

    // 2. 检查平均请求间隔
    const avgInterval = report.averageInterval;
    if (avgInterval > 0 && avgInterval < 100) {
        suspicionScore += 1;
        addLog(`请求间隔过短: ${avgInterval.toFixed(1)}ms`, 'warn');
    }

    // 3. 检查最大并发数
    if (report.maxConcurrent > 3) {
        suspicionScore += 1;
        addLog(`并发请求数较高: ${report.maxConcurrent}`, 'warn');
    }

    // 4. 检查时间跨度与请求数的关系
    const requestsPerSecond = totalRequests / (report.timeSpan / 1000);
    if (requestsPerSecond > 5) {
        suspicionScore += 1;
        addLog(`请求频率过高: ${requestsPerSecond.toFixed(1)} 请求/秒`, 'warn');
    }

    return suspicionScore >= 2;
}
