    /**
     * 添加日志条目
     * @param {string} message - 日志消息
     * @param {string} type - 日志类型: info, warn, error, success
     */
    function addLog(message, type = 'info') {
        const timestamp = new Date().toLocaleTimeString();
        const logEntry = {
            time: timestamp,
            message: message,
            type: type
        };

        logEntries.push(logEntry);

        // 更新日志显示
        const logContent = document.getElementById('logContent');
        const logEntryElement = document.createElement('div');
        logEntryElement.className = `log-entry log-${type}`;
        logEntryElement.innerHTML = `<span class="log-time">[${timestamp}]</span> ${message}`;

        logContent.appendChild(logEntryElement);

        // 自动滚动到底部
        logContent.scrollTop = logContent.scrollHeight;

        // 更新日志计数
        document.getElementById('logCount').textContent = `日志: ${logEntries.length}`;

        // 同时在控制台输出
        const consoleMethod = type === 'error' ? 'error' :
                             type === 'warn' ? 'warn' :
                             type === 'success' ? 'log' : 'info';
        console[consoleMethod](`[${timestamp}] ${message}`);
    }

