    class AdvancedSeleniumDetector {

        /**
         * 检测Chrome自动化扩展（修复版）
         * @returns {boolean} 是否检测到自动化特征
         */
        detectChromeAutomation() {
            try {
                addLog('开始检测Chrome自动化扩展...', 'info');

                let detectionResult = false;
                const warnings = [];

                // 方法1：标准的 navigator.webdriver 检测
                if (navigator.webdriver === true) {
                    detectionResult = true;
                    warnings.push('navigator.webdriver === true');
                    addLog('检测到 navigator.webdriver === true', 'warn');
                }

                // 方法2：检查 webdriver 属性的存在性
                try {
                    const webdriverDesc = Object.getOwnPropertyDescriptor(navigator, 'webdriver');
                    if (webdriverDesc && webdriverDesc.value === true) {
                        detectionResult = true;
                        warnings.push('Object.getOwnPropertyDescriptor(navigator, "webdriver").value === true');
                        addLog('通过属性描述符检测到 webdriver = true', 'warn');
                    }
                } catch (e) {
                    // 忽略错误
                }

                // 方法3：检查 Chrome 自动化相关标志
                if (window.chrome && chrome.runtime) {
                    const chromeFlags = [
                        '_automation',
                        '_debugger',
                        'domAutomation',
                        'domAutomationController'
                    ];

                    chromeFlags.forEach(flag => {
                        if (window[flag] || chrome[flag]) {
                            detectionResult = true;
                            warnings.push(`存在 ${flag} 标志`);
                            addLog(`检测到自动化标志: ${flag}`, 'warn');
                        }
                    });
                }

                // 方法4：检查常见的自动化浏览器痕迹
                const automationMarkers = {
                    'window.callPhantom': 'callPhantom' in window,
                    'window._phantom': '_phantom' in window,
                    'window.__phantastic': '__phantastic' in window,
                    'window.phantom': 'phantom' in window,
                    'window.Buffer': 'Buffer' in window && window.Buffer.name === 'Buffer',
                    'window.emit': 'emit' in window,
                    'window.spawn': 'spawn' in window,
                    'window.__nightmare': '__nightmare' in window,
                    'window.domAutomation': 'domAutomation' in window,
                    'window.domAutomationController': 'domAutomationController' in window,
                };

                Object.entries(automationMarkers).forEach(([marker, exists]) => {
                    if (exists) {
                        detectionResult = true;
                        warnings.push(`${marker} 存在`);
                        addLog(`检测到自动化标记: ${marker}`, 'warn');
                    }
                });

                // 方法5：检查 Chrome 自动化扩展特征
                if (window.chrome && chrome.runtime) {
                    try {
                        const manifest = chrome.runtime.getManifest && chrome.runtime.getManifest();
                        if (manifest) {
                            const manifestStr = JSON.stringify(manifest).toLowerCase();
                            const automationKeywords = [
                                'webdriver',
                                'automation',
                                'selenium',
                                'chromedriver',
                                'headless',
                                'puppeteer'
                            ];

                            if (automationKeywords.some(keyword => manifestStr.includes(keyword))) {
                                detectionResult = true;
                                warnings.push('manifest 包含自动化关键词');
                                addLog('Chrome manifest 包含自动化关键词', 'warn');
                            }
                        }
                    } catch (e) {
                        // 忽略错误，可能是权限问题
                    }
                }

                // 方法6：检查 WebDriver 命令执行器
                if (typeof window.__webdriver_execute !== 'undefined' ||
                    typeof window.__webdriver_script_fn !== 'undefined' ||
                    typeof window.__webdriver_unwrapped !== 'undefined') {
                    detectionResult = true;
                    warnings.push('存在 WebDriver 执行器');
                    addLog('检测到 WebDriver 执行器函数', 'warn');
                }

                // 方法7：检查 navigator 对象是否被修改
                try {
                    const navigatorProto = Object.getPrototypeOf(navigator);

                    if ('webdriver' in navigatorProto) {
                        detectionResult = true;
                        warnings.push('webdriver 存在于 navigator 原型');
                        addLog('webdriver 属性存在于 navigator 原型上', 'warn');
                    }

                    if (Proxy && navigator instanceof Proxy) {
                        detectionResult = true;
                        warnings.push('navigator 对象被代理');
                        addLog('navigator 对象被 Proxy 包装', 'warn');
                    }
                } catch (e) {
                    // 忽略错误
                }

                // 方法8：检查 Chrome 命令行开关
                if (window.chrome && chrome.runtime && chrome.runtime.getPlatformInfo) {
                    try {
                        chrome.runtime.getPlatformInfo((info) => {
                            if (info && (info.os === 'cros' || info.arch === 'unknown')) {
                                detectionResult = true;
                                warnings.push('异常的平台信息');
                                addLog(`检测到异常平台信息: ${JSON.stringify(info)}`, 'warn');
                            }
                        });
                    } catch (e) {
                        // 忽略错误
                    }
                }

                // 如果没有检测到任何异常
                if (!detectionResult) {
                    addLog('未检测到 Chrome 自动化扩展特征', 'success');

                    const debugInfo = {
                        'navigator.webdriver': navigator.webdriver,
                        'userAgent': navigator.userAgent,
                        'chrome存在': !!window.chrome,
                        'plugins数量': navigator.plugins ? navigator.plugins.length : 0
                    };

                    addLog(`调试信息: ${JSON.stringify(debugInfo)}`, 'info');
                } else if (warnings.length > 0) {
                    const warningSummary = warnings.join('; ');
                    addLog(`Chrome自动化检测汇总: ${warningSummary}`, 'warn');
                }

                return detectionResult;
            } catch (e) {
                addLog(`Chrome自动化扩展检测出错: ${e.message}`, 'error');
                return false;
            }
        }

