    /**
     * 2. 插件检测
     */
    function checkPlugins() {
        const pluginsCheck = document.getElementById('pluginsCheck');
        const pluginsStatus = document.getElementById('pluginsStatus');

        addLog('开始插件列表检测...', 'info');

        const plugins = navigator.plugins;
        let isSuspicious = false;

        if (!plugins || plugins.length === 0) {
            isSuspicious = true;
            addLog('插件列表为空，可能是自动化浏览器', 'warn');
        } else {
            const pluginNames = Array.from(plugins).map(p => p.name.toLowerCase());

            const commonPlugins = ['chrome pdf viewer', 'native client', 'widevine content decryption module'];
            const hasCommonPlugins = commonPlugins.some(plugin =>
                pluginNames.some(name => name.includes(plugin))
            );

            if (!hasCommonPlugins && plugins.length < 3) {
                isSuspicious = true;
                addLog(`缺少常见插件，插件数量: ${plugins.length}`, 'warn');
            }

            const automationKeywords = ['webdriver', 'selenium', 'puppeteer', 'automation'];
            const hasAutomationPlugins = automationKeywords.some(keyword =>
                pluginNames.some(name => name.includes(keyword))
            );

            if (hasAutomationPlugins) {
                isSuspicious = true;
                addLog(`检测到自动化相关插件: ${pluginNames.join(', ')}`, 'warn');
            } else {
                addLog(`插件列表正常: ${pluginNames.join(', ')}`, 'success');
            }
        }

        detectionResults.plugins = isSuspicious;

        if (detectionResults.plugins) {
            pluginsCheck.classList.add('detected');
            pluginsCheck.classList.remove('clean');
            pluginsStatus.textContent = '插件列表异常';
            pluginsStatus.className = 'status detected';
            addLog('插件检测: 检测到异常', 'warn');
        } else {
            pluginsCheck.classList.add('clean');
            pluginsCheck.classList.remove('detected');
            pluginsStatus.textContent = '插件列表正常';
            pluginsStatus.className = 'status clean';
            addLog('插件检测: 正常', 'success');
        }

        updateDetectionProgress();
    }

