                addLog(`点击间隔: ${timeSinceLastClick}ms`, 'info');

                if (humanTestClickCount >= 5) {
                    const totalTime = currentTime - humanTestStartTime;
                    const averageTimeBetweenClicks = totalTime / (humanTestClickCount - 1);

                    addLog(`平均点击间隔: ${averageTimeBetweenClicks.toFixed(2)}ms`, 'info');

