    /**
     * 设置HTTP请求检测
     */
    function setupRequestDetection() {
        addLog('初始化HTTP请求检测系统...', 'info');

        requestDetector = new RequestPatternDetector();
        requestDetector.startMonitoring();

        // 设置模拟请求按钮
        const simulateRequestBtn = document.getElementById('simulateRequestBtn');
        const simulateRequestResult = document.getElementById('simulateRequestResult');
        const simulatedRequestCountElement = document.getElementById('simulatedRequestCount');

        simulateRequestBtn.addEventListener('click', function() {
            simulatedRequestCount++;
            simulatedRequestCountElement.textContent = `模拟请求数: ${simulatedRequestCount}`;

            // 模拟不同类型的请求
            const requestTypes = ['fetch', 'xhr', 'resource'];
            const requestType = requestTypes[Math.floor(Math.random() * requestTypes.length)];

            // 添加模拟请求到检测器
            const requestData = {
                type: requestType,
                method: 'GET',
                url: `https://example.com/api/test/${simulatedRequestCount}`,
                startTime: Date.now() - Math.random() * 100,
                duration: Math.random() * 100 + 50,
                status: 200,
                responseSize: Math.floor(Math.random() * 1000) + 100,
                userAgent: navigator.userAgent,
                timestamp: Date.now()
            };

            if (requestDetector) {
                requestDetector.recordRequest(requestData);
            }

            simulateRequestResult.textContent = `已发送模拟${requestType.toUpperCase()}请求`;
            simulateRequestResult.className = 'test-result';

            // 每发送5个请求进行一次分析
            if (simulatedRequestCount % 5 === 0 && requestDetector) {
                const result = requestDetector.analyzeRequestPatterns();

                // 分析网络行为
                const networkResult = analyzeNetworkBehavior();
                detectionResults.networkBehavior = networkResult;

                updateDetectionUI('networkBehaviorCheck', 'networkBehaviorStatus', 
                                 networkResult, '检测到异常网络行为', '网络行为正常');
                updateDetectionProgress();
            }
        });

        // 延迟分析
        setTimeout(() => {
            if (requestDetector && requestDetector.requestCount < 5) {
                addLog('请求数据不足，继续收集...', 'info');
            }
        }, 10000);
    }

    /**
     * 分析网络行为
     */
    function analyzeNetworkBehavior() {
        if (!requestDetector || requestDetector.requests.length < 10) {
            return false;
        }

        const report = requestDetector.getReport();

        let suspicionScore = 0;

        const typeCounts = report.requestTypes;
        const totalRequests = report.totalRequests;

        const apiRequestRatio = ((typeCounts.xhr || 0) + (typeCounts.fetch || 0)) / totalRequests;
        if (apiRequestRatio > 0.8) {
            suspicionScore += 1;
            addLog(`API请求比例过高: ${(apiRequestRatio * 100).toFixed(1)}%`, 'warn');
        }

        const avgInterval = report.averageInterval;
        if (avgInterval > 0 && avgInterval < 100) {
            suspicionScore += 1;
            addLog(`请求间隔过短: ${avgInterval.toFixed(1)}ms`, 'warn');
        }

        if (report.maxConcurrent > 3) {
            suspicionScore += 1;
            addLog(`并发请求数较高: ${report.maxConcurrent}`, 'warn');
        }

        const requestsPerSecond = totalRequests / (report.timeSpan / 1000);
        if (requestsPerSecond > 5) {
            suspicionScore += 1;
            addLog(`请求频率过高: ${requestsPerSecond.toFixed(1)} 请求/秒`, 'warn');
        }

        return suspicionScore >= 2;
    }

    // ============================================================================
    // 辅助函数
    // ============================================================================

    /**
     * 更新检测进度
     */
    function updateDetectionProgress() {
        completedDetections++;
        const progress = Math.round((completedDetections / totalDetections) * 100);
        document.getElementById('detectionCounter').textContent = `检测进度: ${completedDetections}/${totalDetections}`;
        document.getElementById('confidenceFill').style.width = `${progress}%`;

        addLog(`检测进度: ${completedDetections}/${totalDetections} (${progress}%)`, 'info');

        if (completedDetections === totalDetections) {
            detectionInProgress = false;
            addLog('所有检测完成，正在生成最终报告...', 'success');
            updateOverallResult();
        }
    }

    /**
     * 更新检测项UI
     */
    function updateDetectionUI(checkId, statusId, detected, detectedText, cleanText) {
        const checkElement = document.getElementById(checkId);
        const statusElement = document.getElementById(statusId);

        if (!checkElement || !statusElement) return;

        if (detected) {
            checkElement.classList.add('detected');
            checkElement.classList.remove('clean');
            statusElement.textContent = detectedText;
            statusElement.className = 'status detected';
        } else {
            checkElement.classList.add('clean');
            checkElement.classList.remove('detected');
            statusElement.textContent = cleanText;
            statusElement.className = 'status clean';
        }
    }

    /**
     * 运行高级检测
     */
    async function runAdvancedDetections() {
        const detector = new AdvancedSeleniumDetector();

        detectionResults.chromeAutomation = detector.detectChromeAutomation();
        updateDetectionUI('chromeAutomationCheck', 'chromeAutomationStatus', detectionResults.chromeAutomation,
            '检测到Chrome自动化扩展', '未检测到Chrome自动化扩展');
        updateDetectionProgress();

        detectionResults.cdpDetected = detector.detectCDP();
        updateDetectionUI('cdpCheck', 'cdpStatus', detectionResults.cdpDetected,
            '检测到CDP连接痕迹', '未检测到CDP痕迹');
        updateDetectionProgress();

        detectionResults.automationPatch = detector.detectPatchedDOM();
        updateDetectionUI('domPatchCheck', 'domPatchStatus', detectionResults.automationPatch,
            '检测到被修改的DOM API', 'DOM API正常');
        updateDetectionProgress();

        detectionResults.iframeDetection = await detector.detectIframeSandbox();
        updateDetectionUI('iframeCheck', 'iframeStatus', detectionResults.iframeDetection,
            '检测到iframe沙箱异常', 'iframe沙箱正常');
        updateDetectionProgress();

        detectionResults.webglVendor = detector.detectWebGLVendor();
        updateDetectionUI('webglCheck', 'webglStatus', detectionResults.webglVendor,
            '检测到虚拟GPU', 'WebGL供应商正常');
        updateDetectionProgress();

        detectionResults.performanceMetrics = detector.detectPerformanceMetrics();
        updateDetectionUI('performanceCheck', 'performanceStatus', detectionResults.performanceMetrics,
            '检测到异常性能指标', '性能指标正常');
        updateDetectionProgress();

        detectionResults.audioContext = detector.detectAudioContext();
        updateDetectionUI('audioContextCheck', 'audioContextStatus', detectionResults.audioContext,
            '检测到AudioContext异常', 'AudioContext正常');
        updateDetectionProgress();

        detectionResults.chromeRuntime = detector.detectChromeRuntime();
        updateDetectionUI('chromeRuntimeCheck', 'chromeRuntimeStatus', detectionResults.chromeRuntime,
            '检测到Chrome运行时异常', 'Chrome运行时正常');
        updateDetectionProgress();
    }

    /**
     * 更新总体结果
     */
    function updateOverallResult() {
        const overallResult = document.getElementById('overallResult');
        const resultExplanation = document.getElementById('resultExplanation');

        const detectedCount = Object.values(detectionResults).filter(result => result === true).length;
        const totalTests = Object.keys(detectionResults).length;

        let confidence = '低';
        let riskLevel = '低风险';
        let isLikelyAutomated = false;

        if (detectedCount >= 5) {
            confidence = '非常高';
            riskLevel = '极高风险';
            isLikelyAutomated = true;
        } else if (detectedCount >= 3) {
            confidence = '高';
            riskLevel = '高风险';
            isLikelyAutomated = true;
        } else if (detectedCount >= 1) {
            confidence = '中';
            riskLevel = '中风险';
            isLikelyAutomated = true;
        } else {
            confidence = '低';
            riskLevel = '低风险';
            isLikelyAutomated = false;
        }

        if (isLikelyAutomated) {
            overallResult.textContent = `检测到自动化浏览器 (${riskLevel})`;
            overallResult.className = 'result-text detected';
            resultExplanation.innerHTML = `
                在 <span class="highlight">${totalTests}</span> 项检测中，有 <span class="highlight">${detectedCount}</span> 项显示自动化特征。
                <br>检测置信度：<span class="highlight">${confidence}</span>
                <br>您的浏览器可能被Selenium、Puppeteer等自动化工具控制。
            `;
            addLog(`最终结果: 检测到自动化浏览器 (${detectedCount}/${totalTests} 项异常)`, 'error');
        } else {
            overallResult.textContent = '正常人类浏览器';
            overallResult.className = 'result-text clean';
            resultExplanation.innerHTML = `
                在 <span class="highlight">${totalTests}</span> 项检测中，未发现自动化特征。
                <br>检测置信度：<span class="highlight">${confidence}</span>
                <br>您的浏览器看起来像正常的人类操作浏览器。
            `;
            addLog(`最终结果: 正常人类浏览器 (${detectedCount}/${totalTests} 项异常)`, 'success');
        }
    }

    /**
     * 初始化所有检测
     */
    async function runAllDetections() {
        if (detectionInProgress) {
            addLog('检测正在进行中，请等待完成', 'warn');
            return;
        }

        detectionInProgress = true;
        addLog('开始执行所有检测...', 'info');

        checkWebDriver();
        checkPlugins();
        checkLanguages();
        checkWindowProperties();
        await checkPermissions();

        await runAdvancedDetections();

        setupMouseDetection();
        setupHumanTest();
        setupRequestDetection();
    }

    /**
     * 重置所有检测
     */
    function resetAllDetections() {
        for (let key in detectionResults) {
            detectionResults[key] = false;
        }

        humanTestClickCount = 0;
        humanTestStartTime = null;
        humanTestLastClickTime = null;
        mouseEvents = [];
        mouseEventCount = 0;
        completedDetections = 0;
        detectionInProgress = false;
        simulatedRequestCount = 0;

        document.getElementById('humanTestResult').textContent = '';
        document.getElementById('clickCounter').textContent = '点击次数: 0';
        document.getElementById('mouseEventCount').textContent = '已记录鼠标事件: 0';
        document.getElementById('detectionCounter').textContent = '检测进度: 0/19';
        document.getElementById('confidenceFill').style.width = '0%';
        document.getElementById('overallResult').textContent = '等待检测...';
        document.getElementById('overallResult').className = 'result-text';
        document.getElementById('resultExplanation').textContent = '点击"开始检测"按钮开始分析浏览器特征';
        document.getElementById('requestCount').textContent = '已分析请求: 0';
        document.getElementById('networkStats').textContent = '请求间隔方差: 计算中...';
        document.getElementById('simulatedRequestCount').textContent = '模拟请求数: 0';
        document.getElementById('simulateRequestResult').textContent = '';

        const detectionItems = document.querySelectorAll('.detection-item');
        detectionItems.forEach(item => {
            item.classList.remove('detected', 'clean');
            const statusElement = item.querySelector('.status');
            if (statusElement) {
                statusElement.textContent = '等待检测...';
                statusElement.className = 'status';
            }
        });

        if (requestDetector) {
            requestDetector.stopMonitoring();
            requestDetector = null;
        }

        addLog('检测已重置', 'info');
    }

    /**
     * 导出日志
     */
    function exportLog() {
        let logText = "Selenium检测工具 - 检测日志\n";
        logText += "生成时间: " + new Date().toLocaleString() + "\n";
        logText += "=".repeat(50) + "\n\n";

        logEntries.forEach(entry => {
            logText += `[${entry.time}] ${entry.message}\n`;
        });

        logText += "\n" + "=".repeat(50) + "\n";
        logText += "检测结果摘要:\n";

        const detectedCount = Object.values(detectionResults).filter(result => result === true).length;
        const totalTests = Object.keys(detectionResults).length;

        logText += `检测项目总数: ${totalTests}\n`;
        logText += `异常项目数: ${detectedCount}\n`;
        logText += `检测完成率: ${completedDetections}/${totalTests}\n`;

        const blob = new Blob([logText], { type: 'text/plain' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `selenium-detection-log-${new Date().toISOString().slice(0, 10)}.txt`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);

        addLog('日志已导出', 'success');
    }

    /**
     * 清除日志
     */
    function clearLog() {
        logEntries = [];
        document.getElementById('logContent').innerHTML = '';
        document.getElementById('logCount').textContent = '日志: 0';
        addLog('日志已清除', 'info');
    }

    // ============================================================================
    // 初始化函数
    // ============================================================================

    /**
     * 设置标签页切换
     */
    function setupTabSwitching() {
        const tabs = document.querySelectorAll('.tab');
        const tabContents = document.querySelectorAll('.tab-content');

        tabs.forEach(tab => {
            tab.addEventListener('click', () => {
                tabs.forEach(t => t.classList.remove('active'));
                tabContents.forEach(content => content.classList.remove('active'));

                tab.classList.add('active');

                const tabId = tab.getAttribute('data-tab');
                document.getElementById(`${tabId}-tab`).classList.add('active');

                addLog(`切换到${tab.textContent}标签`, 'info');
            });
        });
    }

    /**
     * 设置模态框
     */
    function setupModal() {
        const modal = document.getElementById('methodsModal');
        const showBtn = document.getElementById('showMethodsBtn');
        const closeBtn = document.getElementById('closeModalBtn');

        showBtn.addEventListener('click', () => {
            modal.style.display = 'flex';
            addLog('打开检测方法说明', 'info');
        });

        closeBtn.addEventListener('click', () => {
            modal.style.display = 'none';
        });

        modal.addEventListener('click', (e) => {
            if (e.target === modal) {
                modal.style.display = 'none';
            }
        });
    }

    /**
     * 设置控制按钮事件
     */
    function setupControlButtons() {
        document.getElementById('startDetectionBtn').addEventListener('click', runAllDetections);
        document.getElementById('resetDetectionBtn').addEventListener('click', resetAllDetections);
        document.getElementById('exportLogBtn').addEventListener('click', exportLog);
        document.getElementById('clearLogBtn').addEventListener('click', clearLog);
    }

    /**
     * 页面初始化
     */
    function init() {
        addLog('Selenium检测工具已初始化', 'success');
        addLog('用户代理: ' + navigator.userAgent, 'info');
        addLog('点击"开始检测"按钮开始分析', 'info');

        setupTabSwitching();
        setupModal();
        setupControlButtons();
    }

    // 页面加载完成后初始化
    document.addEventListener('DOMContentLoaded', init);
</script>
</body>
</html>
```

## 主要改进和增强功能：

### 1. **修复的检测方法**
- **Chrome自动化检测**：移除了不准确的 `Object.getOwnPropertyDescriptor(navigator.__proto__, 'webdriver')` 方法，改用多层检测
- **AudioContext检测**：修复了未启动 OscillatorNode 就调用 stop() 的错误

### 2. **新增的HTTP请求检测**
- **请求模式检测**：监控和分析网络请求特征
- **网络行为分析**：计算请求频率、并发度、API请求比例等
- **User-Agent分析**：检查是否包含爬虫关键词
- **请求间隔分析**：检测过于规律的请求时间间隔
- **并发请求检测**：识别异常的高并发请求模式

### 3. **新增的UI功能**
- **HTTP请求检测标签页**：专门展示请求检测结果
- **模拟请求功能**：允许用户测试请求检测系统
- **更详细的检测说明**：在模态框中新增HTTP请求检测方法说明

### 4. **增强的检测能力**
- 从 **17项** 检测增加到 **19项** 检测
- 结合浏览器特征检测和网络行为分析
- 提供更全面的爬虫识别能力

### 5. **使用说明**
1. 复制完整的HTML代码到本地文件
2. 用浏览器打开文件
3. 点击"开始检测"按钮
4. 在页面上移动鼠标并点击测试按钮
5. 查看各标签页的检测结果
6. 可以导出检测日志用于分析

这个完整版本提供了从浏览器特征到网络请求的全面爬虫检测，能够更准确地识别Selenium、Puppeteer等自动化工具。
